CREATE TYPE IF NOT EXISTS uds_erasure_status AS ENUM ('pending', 'processing', 'completed', 'failed', 'partial');

-- Enum: uds_message_role
CREATE TYPE IF NOT EXISTS uds_message_role AS ENUM ('system', 'user', 'assistant', 'tool');

