CREATE TYPE IF NOT EXISTS uds_tier AS ENUM ('hot', 'warm', 'cold', 'glacier');

-- Enum: uds_upload_source
CREATE TYPE IF NOT EXISTS uds_upload_source AS ENUM ('direct', 'paste', 'api', 'integration', 'import');

-- Enum: uds_upload_status
CREATE TYPE IF NOT EXISTS uds_upload_status AS ENUM ('pending', 'scanning', 'clean', 'infected', 'processing', 'ready', 'failed', 'deleted');

-- Enum: uep_access_method
CREATE TYPE IF NOT EXISTS uep_access_method AS ENUM ('presigned_url',
