  'api_key',
  'public');

-- Enum: uep_data_classification
CREATE TYPE IF NOT EXISTS uep_data_classification AS ENUM ('PUBLIC',
  'INTERNAL',
  'CONFIDENTIAL',
  'RESTRICTED');

-- Enum: uep_delivery_type
