  'mls');

-- Enum: uep_envelope_type
CREATE TYPE IF NOT EXISTS uep_envelope_type AS ENUM (-- Pipeline envelopes (UEP v1.0 compatible)
  'method.output',
  'method.input',
  
  -- Streaming envelopes
  'stream.start',
  'stream.chunk',
  'stream.end',
  'stream.error',
  'stream.cancel',
  
  -- Artifact envelopes
  'artifact.created',
  'artifact.reference',
  
  -- Control envelopes
  'control.ack',
  'control.nack',
  'control.heartbeat',
  'control.capability',
  
  -- Event envelopes
  'event.checkpoint',
  'event.progress',
  'event.error');

