  'normal',
  'high',
  'critical');

-- Enum: uep_source_type
CREATE TYPE IF NOT EXISTS uep_source_type AS ENUM ('method',      -- Cato method
  'tool',        -- Cato tool (Lambda, MCP)
  'model',       -- AI model directly
  'agent',       -- Agent (Curator, Think Tank)
  'service',     -- Backend service
  'user',        -- Human user
  'external'     -- External system);

-- Enum: uep_storage_protocol
CREATE TYPE IF NOT EXISTS uep_storage_protocol AS ENUM ('https',
  's3',
  'radiant',
  'ipfs',
  'data');

-- Enum: uep_stream_status
CREATE TYPE IF NOT EXISTS uep_stream_status AS ENUM ('active',
  'completed',
  'failed',
  'cancelled',
  'paused');

-- Enum: vault_access_type
CREATE TYPE IF NOT EXISTS vault_access_type AS ENUM ('read',
  'write',
  'rotate',
  'delete');

-- Enum: vault_secret_category
CREATE TYPE IF NOT EXISTS vault_secret_category AS ENUM ('api_key',
  'database',
  'oauth',
  'encryption',
  'webhook',
  'custom');

-- Enum: war_room_status
CREATE TYPE IF NOT EXISTS war_room_status AS ENUM ('planning', 'active', 'deliberating', 'decided', 'archived');


-- ============================================================================
-- SECTION 2: TABLES
-- ============================================================================

-- Table: a2a_registered_agents
CREATE TABLE IF NOT EXISTS a2a_registered_agents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Agent identification
  agent_id VARCHAR(255) NOT NULL,
  agent_name VARCHAR(255) NOT NULL,
  agent_type VARCHAR(100) NOT NULL,
  agent_version VARCHAR(50),
  
  -- Authentication
  api_key_id UUID REFERENCES api_keys(id) ON DELETE SET NULL,
  mtls_cert_fingerprint VARCHAR(128),
  mtls_cert_expires_at TIMESTAMPTZ,
  
  -- Capabilities
  supported_operations TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  supported_protocols TEXT[] DEFAULT ARRAY['a2a-v1'],
  max_concurrent_requests INTEGER DEFAULT 10,
  
  -- Status
  status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'revoked', 'pending')),
  last_heartbeat_at TIMESTAMPTZ,
  last_request_at TIMESTAMPTZ,
  total_requests INTEGER NOT NULL DEFAULT 0,
  
  -- Contact
  owner_email VARCHAR(255),
  webhook_url VARCHAR(500),
  
  -- Metadata
  metadata JSONB DEFAULT '{}',
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(tenant_id, agent_id)
);

-- Table: account_trust_scores
CREATE TABLE IF NOT EXISTS account_trust_scores (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    -- Score components
    overall_score DOUBLE PRECISION DEFAULT 0.5,
    account_age_score DOUBLE PRECISION DEFAULT 0.0,
    payment_history_score DOUBLE PRECISION DEFAULT 0.5,
    usage_pattern_score DOUBLE PRECISION DEFAULT 0.5,
    violation_history_score DOUBLE PRECISION DEFAULT 1.0, -- 1.0 = no violations
    
    -- Tracking
    total_requests INTEGER DEFAULT 0,
    flagged_requests INTEGER DEFAULT 0,
    violations_count INTEGER DEFAULT 0,
    last_violation_at TIMESTAMPTZ,
    
    -- Metadata
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_user_trust UNIQUE (tenant_id, user_id)
);

-- Table: accounting_periods
CREATE TABLE IF NOT EXISTS accounting_periods (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'reconciled')),
    
    -- Totals
    total_revenue DECIMAL(15, 4) NOT NULL DEFAULT 0,
    total_cost DECIMAL(15, 4) NOT NULL DEFAULT 0,
    gross_profit DECIMAL(15, 4) NOT NULL DEFAULT 0,
    
    -- Reconciliation
    adjustments_total DECIMAL(15, 4) NOT NULL DEFAULT 0,
    
    -- Closure info
    closed_at TIMESTAMPTZ,
    closed_by VARCHAR(255),
    notes TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(period_start, period_end)
);

-- Table: action_policies
CREATE TABLE IF NOT EXISTS action_policies (
    policy_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Policy definition
    name VARCHAR(200) NOT NULL,
    context_pattern JSONB, -- When to use this policy
    
    -- Action sequences
    action_sequence JSONB NOT NULL, -- Sequence of actions
    expected_outcomes JSONB DEFAULT '[]',
    
    -- Expected free energy
    expected_free_energy DECIMAL(10,4), -- Lower is better
    epistemic_value DECIMAL(5,4), -- Information gain
    pragmatic_value DECIMAL(5,4), -- Goal achievement
    
    -- Performance
    times_selected INTEGER DEFAULT 0,
    times_successful INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: active_contexts
CREATE TABLE IF NOT EXISTS active_contexts (
    context_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    session_id UUID,
    user_id UUID,
    
    -- Current context
    context_stack JSONB DEFAULT '[]', -- Stack of active contexts
    
    -- Detected contexts
    user_context JSONB DEFAULT '{}', -- User-specific context
    task_context JSONB DEFAULT '{}', -- Current task context
    domain_context JSONB DEFAULT '{}', -- Domain-specific context
    temporal_context JSONB DEFAULT '{}', -- Time-based context
    emotional_context JSONB DEFAULT '{}', -- Emotional/tone context
    
    -- Adaptation state
    current_adaptations JSONB DEFAULT '{}', -- Active adaptations
    
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: active_episodes_cache
CREATE TABLE IF NOT EXISTS active_episodes_cache (
  episode_id UUID PRIMARY KEY REFERENCES learning_episodes(episode_id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  session_id UUID NOT NULL,
  episode_data JSONB NOT NULL,
  last_activity_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '1 hour',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: active_learning_requests
CREATE TABLE IF NOT EXISTS active_learning_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    message_id UUID NOT NULL,
    conversation_id UUID,
    
    -- Why we're asking
    request_reason TEXT NOT NULL CHECK (request_reason IN (
        'high_uncertainty',        -- Model was uncertain
        'new_domain',              -- First time seeing this domain
        'complex_query',           -- Complex multi-part query
        'edge_case',               -- Unusual request pattern
        'random_sample',           -- Random sampling for quality
        'domain_calibration',      -- Calibrating domain-specific adapter
        'after_correction'         -- User just corrected us
    )),
    
    -- The request
    request_type TEXT NOT NULL CHECK (request_type IN (
        'binary_helpful',          -- "Was this helpful? Yes/No"
        'rating_scale',            -- "Rate 1-5"
        'specific_feedback',       -- "What could be improved?"
        'correction_request',      -- "Is this correct?"
        'preference_choice'        -- "Which response is better? A/B"
    )),
    
    prompt_shown TEXT NOT NULL, -- The feedback prompt shown to user
    
    -- Response
    user_responded BOOLEAN DEFAULT false,
    user_response JSONB, -- The actual response
    response_timestamp TIMESTAMPTZ,
    
    -- Metadata
    model_confidence NUMERIC(3,2), -- Model's confidence when generating
    uncertainty_score NUMERIC(3,2),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '24 hours'
);

-- Table: active_predictions
CREATE TABLE IF NOT EXISTS active_predictions (
    prediction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    model_id UUID REFERENCES generative_models(model_id),
    
    -- Prediction
    predicted_state JSONB NOT NULL,
    predicted_observation JSONB,
    confidence DECIMAL(5,4),
    
    -- Context
    context_state JSONB,
    action_taken TEXT,
    
    -- Outcome
    actual_state JSONB,
    actual_observation JSONB,
    prediction_error DECIMAL(5,4), -- Free energy / surprise
    
    -- Learning
    belief_update JSONB, -- How beliefs changed
    model_update JSONB, -- How model changed
    
    predicted_at TIMESTAMPTZ DEFAULT NOW(),
    observed_at TIMESTAMPTZ
);

-- Table: active_verification_log
CREATE TABLE IF NOT EXISTS active_verification_log (
  verification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- What was verified
  skill_name VARCHAR(200) NOT NULL,
  initial_confidence DECIMAL(4,3),
  
  -- Verification attempt
  verification_code TEXT,
  execution_id UUID REFERENCES sandbox_execution_log(execution_id),
  
  -- Results
  success BOOLEAN,
  new_confidence DECIMAL(4,3),
  surprise_generated BOOLEAN DEFAULT false,
  
  -- Dream context
  dream_job_id UUID,
  trigger_reason VARCHAR(50), -- 'low_confidence', 'stale_skill', 'curiosity', 'failure_recovery'
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: admin_notifications
CREATE TABLE IF NOT EXISTS admin_notifications (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    admin_id UUID NOT NULL REFERENCES administrators(id) ON DELETE CASCADE,
    tenant_id VARCHAR(100) NOT NULL,
    type VARCHAR(50) NOT NULL,
    priority VARCHAR(20) NOT NULL DEFAULT 'medium',
    title VARCHAR(255) NOT NULL,
    message TEXT NOT NULL,
    action_url VARCHAR(500),
    action_label VARCHAR(100),
    read BOOLEAN NOT NULL DEFAULT false,
    read_at TIMESTAMPTZ,
    dismissed BOOLEAN NOT NULL DEFAULT false,
    dismissed_at TIMESTAMPTZ,
    email_sent BOOLEAN NOT NULL DEFAULT false,
    email_sent_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ,
    CONSTRAINT valid_notification_type CHECK (type IN ('security', 'billing', 'deployment', 'approval', 'system', 'alert')),
    CONSTRAINT valid_notification_priority CHECK (priority IN ('low', 'medium', 'high', 'critical'))
);

-- Table: admin_permissions
CREATE TABLE IF NOT EXISTS admin_permissions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    admin_id UUID NOT NULL REFERENCES administrators(id) ON DELETE CASCADE,
    permission VARCHAR(100) NOT NULL,
    granted_by UUID REFERENCES administrators(id),
    granted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ,
    UNIQUE (admin_id, permission)
);

-- Table: admin_profiles
CREATE TABLE IF NOT EXISTS admin_profiles (
    admin_id UUID PRIMARY KEY REFERENCES administrators(id) ON DELETE CASCADE,
    notifications JSONB NOT NULL DEFAULT '{}',
    timezone VARCHAR(50) NOT NULL DEFAULT 'America/New_York',
    language VARCHAR(10) NOT NULL DEFAULT 'en',
    date_format VARCHAR(20) NOT NULL DEFAULT 'MM/DD/YYYY',
    time_format VARCHAR(10) NOT NULL DEFAULT '12h',
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    theme VARCHAR(20) NOT NULL DEFAULT 'system',
    default_environment VARCHAR(20) NOT NULL DEFAULT 'dev',
    sidebar_collapsed BOOLEAN NOT NULL DEFAULT false,
    table_rows_per_page INTEGER NOT NULL DEFAULT 25,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: admin_reports
CREATE TABLE IF NOT EXISTS admin_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Report info
  name VARCHAR(200) NOT NULL,
  description TEXT,
  template_id UUID REFERENCES report_templates(id) ON DELETE SET NULL,
  
  -- Report type (denormalized for filtering)
  report_type VARCHAR(50) NOT NULL CHECK (report_type IN (
    'usage', 'cost', 'security', 'performance', 'compliance', 'custom'
  )),
  
  -- Schedule
  schedule VARCHAR(20) NOT NULL DEFAULT 'manual' CHECK (schedule IN (
    'manual', 'daily', 'weekly', 'monthly', 'quarterly'
  )),
  schedule_time TIME DEFAULT '09:00:00', -- Time of day to run (for scheduled)
  schedule_day_of_week INTEGER, -- 0=Sunday, 1=Monday, etc. (for weekly)
  schedule_day_of_month INTEGER, -- 1-28 (for monthly)
  schedule_timezone VARCHAR(50) DEFAULT 'UTC',
  
  -- Output format
  format VARCHAR(20) NOT NULL DEFAULT 'pdf' CHECK (format IN ('pdf', 'csv', 'json', 'excel')),
  
  -- Recipients (email addresses)
  recipients JSONB DEFAULT '[]', -- ['admin@company.com', 'team@company.com']
  
  -- Custom parameters for this report
  parameters JSONB DEFAULT '{}', -- Date ranges, filters, groupings, etc.
  
  -- Execution tracking
  last_run_at TIMESTAMPTZ,
  last_run_status VARCHAR(20) CHECK (last_run_status IN ('success', 'failed', 'running')),
  last_run_error TEXT,
  next_run_at TIMESTAMPTZ,
  run_count INTEGER DEFAULT 0,
  
  -- Status
  status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'draft', 'deleted')),
  is_favorite BOOLEAN DEFAULT false,
  
  -- Ownership
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_by_name VARCHAR(200),
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: admin_sessions
CREATE TABLE IF NOT EXISTS admin_sessions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    admin_id UUID NOT NULL REFERENCES administrators(id) ON DELETE CASCADE,
    session_token_hash VARCHAR(64) NOT NULL UNIQUE,
    ip_address INET,
    user_agent TEXT,
    last_activity_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: administrators
CREATE TABLE IF NOT EXISTS administrators (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    cognito_user_id VARCHAR(128) NOT NULL UNIQUE,
    email VARCHAR(255) NOT NULL UNIQUE,
    display_name VARCHAR(200) NOT NULL,
    role VARCHAR(50) NOT NULL DEFAULT 'admin' CHECK (role IN ('super_admin', 'admin', 'operator', 'auditor')),
    permissions TEXT[] NOT NULL DEFAULT '{}',
    mfa_enabled BOOLEAN NOT NULL DEFAULT false,
    last_login_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    invited_by UUID REFERENCES administrators(id)
);

-- Table: advanced_agi_settings
CREATE TABLE IF NOT EXISTS advanced_agi_settings (
    setting_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Meta-Learning
    meta_learning_enabled BOOLEAN DEFAULT true,
    strategy_evolution_enabled BOOLEAN DEFAULT true,
    experiment_auto_run BOOLEAN DEFAULT false,
    min_samples_for_evolution INTEGER DEFAULT 100,
    
    -- Active Inference
    active_inference_enabled BOOLEAN DEFAULT true,
    prediction_horizon INTEGER DEFAULT 5,
    free_energy_threshold DECIMAL(5,4) DEFAULT 0.3,
    exploration_exploitation_balance DECIMAL(3,2) DEFAULT 0.3,
    
    -- Neuro-Symbolic
    neuro_symbolic_enabled BOOLEAN DEFAULT true,
    rule_extraction_enabled BOOLEAN DEFAULT true,
    symbolic_verification_required BOOLEAN DEFAULT false,
    max_reasoning_depth INTEGER DEFAULT 10,
    
    -- Working Memory
    working_memory_slots INTEGER DEFAULT 7,
    decay_rate DECIMAL(5,4) DEFAULT 0.1,
    rehearsal_enabled BOOLEAN DEFAULT true,
    chunking_enabled BOOLEAN DEFAULT true,
    
    -- Self-Modification
    self_modification_enabled BOOLEAN DEFAULT false, -- Off by default for safety
    prompt_evolution_enabled BOOLEAN DEFAULT true,
    architecture_search_enabled BOOLEAN DEFAULT false,
    require_approval_for_changes BOOLEAN DEFAULT true,
    
    -- Common Sense
    common_sense_enabled BOOLEAN DEFAULT true,
    physical_reasoning_enabled BOOLEAN DEFAULT true,
    social_reasoning_enabled BOOLEAN DEFAULT true,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: advanced_cognition_settings
CREATE TABLE IF NOT EXISTS advanced_cognition_settings (
    setting_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Causal Reasoning
    causal_reasoning_enabled BOOLEAN DEFAULT true,
    causal_confidence_threshold DECIMAL(3,2) DEFAULT 0.6,
    max_causal_chain_depth INTEGER DEFAULT 5,
    counterfactual_enabled BOOLEAN DEFAULT true,
    
    -- Memory Consolidation
    consolidation_enabled BOOLEAN DEFAULT true,
    consolidation_schedule VARCHAR(50) DEFAULT 'daily', -- 'hourly', 'daily', 'weekly', 'manual'
    consolidation_time VARCHAR(10) DEFAULT '03:00', -- UTC time for scheduled consolidation
    default_compression_ratio DECIMAL(3,2) DEFAULT 0.7,
    importance_decay_rate DECIMAL(5,4) DEFAULT 0.05, -- Per day
    auto_prune_threshold DECIMAL(3,2) DEFAULT 0.1, -- Prune below this importance
    conflict_auto_resolve BOOLEAN DEFAULT true,
    
    -- Multimodal Binding
    multimodal_binding_enabled BOOLEAN DEFAULT true,
    auto_embed_uploads BOOLEAN DEFAULT true,
    cross_modal_search_enabled BOOLEAN DEFAULT true,
    binding_quality_threshold DECIMAL(3,2) DEFAULT 0.7,
    
    -- Skill Execution
    skill_execution_enabled BOOLEAN DEFAULT true,
    auto_skill_suggestion BOOLEAN DEFAULT true,
    skill_learning_enabled BOOLEAN DEFAULT true,
    max_skill_chain_depth INTEGER DEFAULT 3,
    
    -- Autonomous Agent
    autonomous_enabled BOOLEAN DEFAULT false, -- Off by default for safety
    autonomous_approval_required BOOLEAN DEFAULT true,
    max_autonomous_actions_per_day INTEGER DEFAULT 10,
    autonomous_resource_budget JSONB DEFAULT '{"max_tokens_per_day": 100000, "max_api_calls_per_day": 500}',
    allowed_autonomous_tasks TEXT[] DEFAULT ARRAY['suggestion', 'maintenance'],
    
    -- Global safety bounds
    max_tokens_per_operation INTEGER DEFAULT 50000,
    max_api_calls_per_operation INTEGER DEFAULT 100,
    operation_timeout_ms INTEGER DEFAULT 300000,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: affective_events
CREATE TABLE IF NOT EXISTS affective_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    valence_change NUMERIC(5,4) NOT NULL DEFAULT 0,
    arousal_change NUMERIC(5,4) NOT NULL DEFAULT 0,
    trigger_context TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: affective_state
CREATE TABLE IF NOT EXISTS affective_state (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    valence NUMERIC(5,4) NOT NULL DEFAULT 0, -- -1 to 1
    arousal NUMERIC(5,4) NOT NULL DEFAULT 0.5, -- 0 to 1
    curiosity NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    satisfaction NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    frustration NUMERIC(5,4) NOT NULL DEFAULT 0,
    confidence NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    engagement NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    surprise NUMERIC(5,4) NOT NULL DEFAULT 0,
    self_efficacy NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    exploration_drive NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: agent_beliefs
CREATE TABLE IF NOT EXISTS agent_beliefs (
    belief_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    agent_id UUID NOT NULL REFERENCES cognitive_agents(agent_id) ON DELETE CASCADE,
    session_id UUID REFERENCES collaboration_sessions(session_id) ON DELETE CASCADE,
    
    -- Belief content
    belief_type VARCHAR(50) NOT NULL, -- 'world_state', 'agent_model', 'goal_state', 'strategy'
    subject VARCHAR(500) NOT NULL,
    belief JSONB NOT NULL,
    confidence DECIMAL(5,4) DEFAULT 0.5,
    
    -- Provenance
    source_type VARCHAR(50), -- 'observation', 'inference', 'communication', 'prior'
    source_message_id UUID REFERENCES agent_messages(message_id),
    
    -- Validity
    is_current BOOLEAN DEFAULT true,
    superseded_by UUID REFERENCES agent_beliefs(belief_id),
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: agent_dependencies
CREATE TABLE IF NOT EXISTS agent_dependencies (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Dependency relationship
  dependent_agent_id UUID NOT NULL REFERENCES agent_registry(id) ON DELETE CASCADE,
  dependency_agent_id UUID NOT NULL REFERENCES agent_registry(id) ON DELETE CASCADE,
  
  -- Dependency type
  dependency_type VARCHAR(50) NOT NULL CHECK (dependency_type IN (
    'data', -- Agent A needs data from Agent B
    'approval', -- Agent A needs approval from Agent B
    'resource', -- Agent A needs a resource held by Agent B
    'sequence' -- Agent A must run after Agent B
  )),
  
  -- Status
  status VARCHAR(50) DEFAULT 'pending' CHECK (status IN ('pending', 'satisfied', 'failed', 'timeout')),
  satisfied_at TIMESTAMPTZ,
  
  -- What's being waited for
  wait_key VARCHAR(256), -- e.g., 'budget_approval', 'file:/path/to/file'
  wait_value JSONB, -- The value received when satisfied
  
  -- Timeout
  timeout_seconds INTEGER DEFAULT 3600,
  expires_at TIMESTAMPTZ,
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(dependent_agent_id, dependency_agent_id, wait_key)
);

-- Table: agent_executions
CREATE TABLE IF NOT EXISTS agent_executions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID REFERENCES users(id),
  session_id UUID,
  
  -- Goal
  goal TEXT NOT NULL,
  constraints JSONB DEFAULT '{}',
  config JSONB DEFAULT '{}',
  
  -- OODA State
  status agent_execution_status NOT NULL DEFAULT 'pending',
  current_phase ooda_phase DEFAULT 'observe',
  current_iteration INTEGER NOT NULL DEFAULT 0,
  
  -- Working Memory (primary in Redis, snapshot here)
  observations JSONB DEFAULT '[]',
  hypotheses JSONB DEFAULT '[]',
  plan JSONB DEFAULT '[]',
  completed_actions JSONB DEFAULT '[]',
  
  -- Results
  artifacts JSONB DEFAULT '[]',
  output_summary TEXT,
  
  -- Resources
  budget_allocated DECIMAL(10,4) NOT NULL,
  budget_consumed DECIMAL(10,4) NOT NULL DEFAULT 0,
  tokens_used BIGINT NOT NULL DEFAULT 0,
  
  -- Timing
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  timeout_at TIMESTAMPTZ,
  
  -- HITL
  hitl_required BOOLEAN NOT NULL DEFAULT false,
  hitl_decision agent_hitl_decision,
  hitl_decided_by UUID REFERENCES users(id),
  hitl_decided_at TIMESTAMPTZ,
  hitl_notes TEXT,
  
  -- Safety
  safety_flags TEXT[] DEFAULT '{}',
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: agent_iteration_logs
CREATE TABLE IF NOT EXISTS agent_iteration_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  execution_id UUID NOT NULL REFERENCES agent_executions(id) ON DELETE CASCADE,
  
  iteration_number INTEGER NOT NULL,
  phase ooda_phase NOT NULL,
  
  -- Phase details
  phase_input JSONB,
  phase_output JSONB,
  
  -- Model usage
  model_used VARCHAR(100),
  tokens_input INTEGER,
  tokens_output INTEGER,
  cost_usd DECIMAL(10,6),
  
  -- Timing
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  duration_ms INTEGER,
  
  -- Errors
  error_code VARCHAR(50),
  error_message TEXT
);

-- Table: agent_messages
CREATE TABLE IF NOT EXISTS agent_messages (
    message_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaboration_sessions(session_id) ON DELETE CASCADE,
    
    -- Message routing
    from_agent_id UUID REFERENCES cognitive_agents(agent_id),
    to_agent_id UUID REFERENCES cognitive_agents(agent_id), -- NULL = broadcast to all
    reply_to_message_id UUID REFERENCES agent_messages(message_id),
    
    -- Message content
    message_type VARCHAR(50) NOT NULL, -- 'proposal', 'critique', 'question', 'answer', 'agreement', 'disagreement', 'synthesis', 'delegation', 'report', 'decision'
    content TEXT NOT NULL,
    content_embedding vector(1536),
    
    -- Structured data
    artifacts JSONB DEFAULT '[]', -- [{type, content}]
    reasoning JSONB DEFAULT '{}', -- Chain of thought
    confidence DECIMAL(5,4),
    
    -- Voting/Agreement
    votes JSONB DEFAULT '{}', -- {agent_id: 'agree'|'disagree'|'abstain'}
    
    -- Performance
    tokens_used INTEGER,
    latency_ms INTEGER,
    
    -- Round tracking (for debate/consensus)
    round_number INTEGER DEFAULT 1,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: agent_registry
CREATE TABLE IF NOT EXISTS agent_registry (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    agent_key VARCHAR(50) NOT NULL UNIQUE,
    display_name VARCHAR(100) NOT NULL,
    description TEXT,
    icon_name VARCHAR(50),
    base_url VARCHAR(255),
    port INTEGER,
    is_active BOOLEAN DEFAULT true,
    is_internal BOOLEAN DEFAULT true,
    requires_license BOOLEAN DEFAULT false,
    license_tier VARCHAR(50),
    capabilities JSONB DEFAULT '[]'::jsonb,
    default_permissions JSONB DEFAULT '{}'::jsonb,
    metadata JSONB DEFAULT '{}'::jsonb,
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: agent_tools
CREATE TABLE IF NOT EXISTS agent_tools (
    tool_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Tool definition
    name VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    category VARCHAR(50), -- 'search', 'compute', 'data', 'communication', 'integration'
    
    -- Function spec (OpenAI-compatible)
    function_spec JSONB NOT NULL, -- {name, description, parameters: {type, properties, required}}
    
    -- Execution
    execution_type VARCHAR(50) NOT NULL, -- 'http', 'lambda', 'internal', 'code_interpreter'
    execution_config JSONB DEFAULT '{}', -- endpoint, auth, etc.
    
    -- Permissions
    requires_approval BOOLEAN DEFAULT false,
    allowed_roles TEXT[] DEFAULT '{}',
    rate_limit_per_minute INTEGER,
    
    -- Safety
    risk_level VARCHAR(20) DEFAULT 'low', -- 'low', 'medium', 'high', 'critical'
    safety_checks JSONB DEFAULT '[]', -- Pre-execution checks
    
    -- Stats
    times_called INTEGER DEFAULT 0,
    success_rate DECIMAL(5,4),
    avg_latency_ms INTEGER,
    
    enabled BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: agents
CREATE TABLE IF NOT EXISTS agents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- Identity
  name VARCHAR(100) NOT NULL,
  display_name VARCHAR(200) NOT NULL,
  description TEXT,
  version VARCHAR(20) NOT NULL DEFAULT '1.0.0',
  
  -- Classification
  category agent_category NOT NULL,
  capabilities TEXT[] NOT NULL DEFAULT '{}',
  
  -- Execution
  execution_mode agent_execution_mode NOT NULL DEFAULT 'async',
  max_iterations INTEGER NOT NULL DEFAULT 50,
  default_timeout_minutes INTEGER NOT NULL DEFAULT 30,
  
  -- Resources
  default_budget_usd DECIMAL(10,4) DEFAULT 1.00,
  max_budget_usd DECIMAL(10,4) DEFAULT 10.00,
  allowed_models TEXT[] NOT NULL DEFAULT '{}',
  allowed_tools TEXT[] NOT NULL DEFAULT '{}',
  
  -- Safety (Genesis Cato integration)
  safety_profile agent_safety_profile NOT NULL DEFAULT 'standard',
  requires_hitl BOOLEAN NOT NULL DEFAULT false,
  cbf_overrides JSONB DEFAULT '{}',
  
  -- Implementation
  implementation_type agent_impl_type NOT NULL,
  implementation_ref TEXT NOT NULL,
  config_schema JSONB,
  
  -- AI Helper Configuration (PARAMETRIC - each agent can have independent AI config)
  ai_helper_config JSONB NOT NULL DEFAULT '{
    "enabled": true,
    "disambiguation": {
      "enabled": true,
      "model": "claude-haiku-35",
      "confidenceThreshold": 0.7
    },
    "parameterInference": {
      "enabled": true,
      "model": "claude-haiku-35",
      "examples": []
    },
    "errorRecovery": {
      "enabled": true,
      "model": "claude-haiku-35",
      "maxAttempts": 3
    },
    "validation": {
      "enabled": false,
      "model": null,
      "checks": []
    },
    "explanation": {
      "enabled": true,
      "model": "claude-haiku-35"
    }
  }',
  
  -- Metadata
  is_active BOOLEAN NOT NULL DEFAULT true,
  scope agent_scope NOT NULL DEFAULT 'system',
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  created_by UUID REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_agent_name_scope UNIQUE (name, scope, tenant_id)
);

-- Table: aggregated_metrics
CREATE TABLE IF NOT EXISTS aggregated_metrics (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    period_type VARCHAR(20) NOT NULL CHECK (period_type IN ('hourly', 'daily', 'weekly', 'monthly')),
    metric_type VARCHAR(50) NOT NULL,
    total_requests BIGINT DEFAULT 0,
    total_tokens BIGINT DEFAULT 0,
    total_cost DECIMAL(20, 6) DEFAULT 0,
    avg_latency_ms DECIMAL(10, 2),
    p50_latency_ms DECIMAL(10, 2),
    p95_latency_ms DECIMAL(10, 2),
    p99_latency_ms DECIMAL(10, 2),
    error_count INTEGER DEFAULT 0,
    unique_users INTEGER DEFAULT 0,
    model_breakdown JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, period_start, period_type, metric_type)
);

-- Table: agi_bedrock_config
CREATE TABLE IF NOT EXISTS agi_bedrock_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN DEFAULT false,
    prefer_bedrock_models BOOLEAN DEFAULT false,
    bedrock_region VARCHAR(20) DEFAULT 'us-east-1',
    knowledge_base_id VARCHAR(100),
    guardrail_id VARCHAR(100),
    agent_id VARCHAR(100),
    prompt_flow_id VARCHAR(100),
    use_bedrock_agents BOOLEAN DEFAULT false,
    use_knowledge_bases BOOLEAN DEFAULT false,
    use_guardrails BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: agi_brain_plan_events
CREATE TABLE IF NOT EXISTS agi_brain_plan_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id VARCHAR(100) NOT NULL REFERENCES agi_brain_plans(plan_id) ON DELETE CASCADE,
    event_type VARCHAR(30) NOT NULL,
    step_id VARCHAR(100),
    step_number INTEGER,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    data JSONB DEFAULT '{}',
    
    CONSTRAINT chk_event_type CHECK (event_type IN (
        'plan_created', 'plan_started', 'step_started', 'step_completed', 
        'step_failed', 'step_skipped', 'plan_completed', 'plan_failed', 'plan_cancelled'
    ))
);

-- Table: agi_brain_plan_preferences
CREATE TABLE IF NOT EXISTS agi_brain_plan_preferences (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID NOT NULL,
    
    -- Display preferences
    show_plan_before_execution BOOLEAN DEFAULT true,
    show_step_details BOOLEAN DEFAULT true,
    show_model_selection BOOLEAN DEFAULT true,
    show_domain_detection BOOLEAN DEFAULT true,
    show_ethics_check BOOLEAN DEFAULT true,
    show_timing_estimates BOOLEAN DEFAULT true,
    show_cost_estimates BOOLEAN DEFAULT true,
    
    -- Execution preferences
    auto_approve_simple BOOLEAN DEFAULT false,
    auto_approve_threshold NUMERIC(4, 3) DEFAULT 0.8,
    preferred_mode VARCHAR(30),
    preferred_model VARCHAR(200),
    max_wait_seconds INTEGER DEFAULT 30,
    
    -- Notification preferences
    notify_on_completion BOOLEAN DEFAULT false,
    notify_on_failure BOOLEAN DEFAULT true,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, user_id)
);

-- Table: agi_brain_plan_templates
CREATE TABLE IF NOT EXISTS agi_brain_plan_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID,  -- NULL = global template
    template_name VARCHAR(100) NOT NULL,
    description TEXT,
    
    -- Template configuration
    task_type VARCHAR(50) NOT NULL,
    orchestration_mode VARCHAR(30) NOT NULL,
    steps JSONB NOT NULL DEFAULT '[]',
    quality_targets JSONB DEFAULT '{}',
    
    -- Usage tracking
    usage_count INTEGER DEFAULT 0,
    avg_success_rate NUMERIC(4, 3),
    avg_duration_ms INTEGER,
    
    is_default BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, template_name)
);

-- Table: agi_brain_plans
CREATE TABLE IF NOT EXISTS agi_brain_plans (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id VARCHAR(100) NOT NULL UNIQUE,
    tenant_id UUID NOT NULL,
    user_id UUID NOT NULL,
    session_id VARCHAR(100),
    conversation_id VARCHAR(100),
    
    -- Original request
    prompt TEXT NOT NULL,
    prompt_analysis JSONB NOT NULL DEFAULT '{}',
    
    -- Plan status
    status VARCHAR(20) NOT NULL DEFAULT 'planning',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    total_duration_ms INTEGER,
    
    -- Plan steps
    steps JSONB NOT NULL DEFAULT '[]',
    current_step_index INTEGER DEFAULT 0,
    
    -- Orchestration configuration
    orchestration_mode VARCHAR(30) NOT NULL,
    orchestration_reason TEXT,
    
    -- Model selection
    primary_model JSONB NOT NULL DEFAULT '{}',
    fallback_models JSONB DEFAULT '[]',
    
    -- Domain detection
    domain_detection JSONB,
    
    -- Consciousness state
    consciousness_active BOOLEAN DEFAULT true,
    consciousness_state JSONB,
    
    -- Ethics evaluation
    ethics_evaluation JSONB,
    
    -- Performance estimates
    estimated_duration_ms INTEGER,
    estimated_cost_cents NUMERIC(10, 4),
    estimated_tokens INTEGER,
    
    -- Quality targets
    quality_targets JSONB DEFAULT '{}',
    
    -- Self-improvement
    learning_enabled BOOLEAN DEFAULT true,
    feedback_requested BOOLEAN DEFAULT true,
    user_feedback JSONB,
    
    -- Result
    final_response TEXT,
    actual_tokens_used INTEGER,
    actual_cost_cents NUMERIC(10, 4),
    final_confidence NUMERIC(4, 3),
    
    CONSTRAINT chk_status CHECK (status IN ('planning', 'ready', 'executing', 'completed', 'failed', 'cancelled'))
);

-- Table: agi_component_state
CREATE TABLE IF NOT EXISTS agi_component_state (
    state_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    component_type TEXT NOT NULL,
    state_data JSONB NOT NULL DEFAULT '{}'::jsonb,
    data_hash TEXT,
    record_count INTEGER NOT NULL DEFAULT 0,
    is_loaded BOOLEAN NOT NULL DEFAULT false,
    last_restored_at TIMESTAMPTZ,
    last_modified TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, component_type)
);

-- Table: agi_consciousness_weights
CREATE TABLE IF NOT EXISTS agi_consciousness_weights (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    indicator_id VARCHAR(50) NOT NULL,
    weight NUMERIC(4, 3) NOT NULL DEFAULT 1.0 CHECK (weight >= 0 AND weight <= 1),
    enabled BOOLEAN NOT NULL DEFAULT true,
    cycle_depth INTEGER NOT NULL DEFAULT 3,
    integration_threshold NUMERIC(4, 3) DEFAULT 0.5,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, indicator_id)
);

-- Table: agi_decision_thresholds
CREATE TABLE IF NOT EXISTS agi_decision_thresholds (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    min_confidence_for_action NUMERIC(4, 3) DEFAULT 0.6,
    min_domain_match_score NUMERIC(5, 2) DEFAULT 50.0,
    max_uncertainty_for_direct_response NUMERIC(4, 3) DEFAULT 0.4,
    escalation_threshold NUMERIC(4, 3) DEFAULT 0.3,
    moral_concern_threshold NUMERIC(4, 3) DEFAULT 0.7,
    self_improvement_trigger_threshold NUMERIC(4, 3) DEFAULT 0.5,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: agi_decision_weights
CREATE TABLE IF NOT EXISTS agi_decision_weights (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Domain Detection Phase
    domain_detection_weight NUMERIC(4, 3) DEFAULT 0.8,
    proficiency_match_weight NUMERIC(4, 3) DEFAULT 0.7,
    subspecialty_weight NUMERIC(4, 3) DEFAULT 0.5,
    
    -- Model Selection Phase
    model_quality_weight NUMERIC(4, 3) DEFAULT 0.8,
    model_cost_weight NUMERIC(4, 3) DEFAULT 0.5,
    model_latency_weight NUMERIC(4, 3) DEFAULT 0.6,
    model_specialty_weight NUMERIC(4, 3) DEFAULT 0.7,
    model_reliability_weight NUMERIC(4, 3) DEFAULT 0.9,
    
    -- Consciousness Phase
    global_workspace_weight NUMERIC(4, 3) DEFAULT 0.7,
    recurrent_processing_weight NUMERIC(4, 3) DEFAULT 0.6,
    integrated_information_weight NUMERIC(4, 3) DEFAULT 0.5,
    self_modeling_weight NUMERIC(4, 3) DEFAULT 0.6,
    
    -- Ethics Phase
    moral_compass_weight NUMERIC(4, 3) DEFAULT 0.9,
    ethical_guardrail_weight NUMERIC(4, 3) DEFAULT 1.0,
    
    -- Meta Phase
    confidence_calibration_weight NUMERIC(4, 3) DEFAULT 0.7,
    error_detection_weight NUMERIC(4, 3) DEFAULT 0.8,
    self_improvement_weight NUMERIC(4, 3) DEFAULT 0.4,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by UUID,
    UNIQUE(tenant_id)
);

-- Table: agi_domain_detection_feedback
CREATE TABLE IF NOT EXISTS agi_domain_detection_feedback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
