    weight_id VARCHAR(100) NOT NULL,
    old_weight NUMERIC(4, 3) NOT NULL,
    new_weight NUMERIC(4, 3) NOT NULL,
    change_reason VARCHAR(50) NOT NULL, -- 'auto_tune', 'user_manual', 'performance', 'feedback'
    performance_delta NUMERIC(5, 3), -- How much performance improved/declined
    samples_used INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: agreement_zones
CREATE TABLE IF NOT EXISTS agreement_zones (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES synthesis_sessions(id) ON DELETE CASCADE,
    claim_ids UUID[] NOT NULL,
    source_ids UUID[] NOT NULL,
    agreement_level INTEGER DEFAULT 50 CHECK (agreement_level >= 0 AND agreement_level <= 100),
    visual_style JSONB DEFAULT '{"glowColor": "#22c55e", "warmth": 0.5, "pulseRate": 6}',
    bounding_box JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ai_ethics_principle_standards
CREATE TABLE IF NOT EXISTS ai_ethics_principle_standards (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Links
    principle_id UUID REFERENCES ethical_principles(principle_id) ON DELETE CASCADE,
    standard_id UUID REFERENCES ai_ethics_standards(id) ON DELETE CASCADE,
    
    -- Standard-specific reference
    standard_section VARCHAR(100),  -- e.g., "MAP 1.1", "Clause 6.2", "Article 9"
    standard_requirement TEXT,       -- The actual requirement text
    
    -- Alignment
    alignment_level VARCHAR(20) NOT NULL DEFAULT 'aligned',  -- derived, aligned, supports, extends
    notes TEXT,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(principle_id, standard_id)
);

-- Table: ai_ethics_standards
CREATE TABLE IF NOT EXISTS ai_ethics_standards (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Standard identification
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    full_name VARCHAR(500) NOT NULL,
    version VARCHAR(50),
    
    -- Organization
    organization VARCHAR(255) NOT NULL,
    organization_type VARCHAR(50) NOT NULL,  -- government, iso, industry, academic, religious
    
    -- Details
    description TEXT,
    url VARCHAR(500),
    publication_date DATE,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    is_mandatory BOOLEAN NOT NULL DEFAULT false,  -- Required for compliance
    
    -- Display
    display_order INTEGER NOT NULL DEFAULT 0,
    icon VARCHAR(50),
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ai_helper_cache
CREATE TABLE IF NOT EXISTS ai_helper_cache (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  cache_key VARCHAR(200) NOT NULL UNIQUE,
  call_type ai_helper_call_type NOT NULL,
  
  input_hash VARCHAR(64) NOT NULL,
  output JSONB NOT NULL,
  
  hit_count INTEGER DEFAULT 0,
  last_hit_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  is_global BOOLEAN NOT NULL DEFAULT false,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ai_helper_calls
CREATE TABLE IF NOT EXISTS ai_helper_calls (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  call_type ai_helper_call_type NOT NULL,
  caller_type VARCHAR(50) NOT NULL, -- 'agent', 'app', 'method', 'service', 'workflow'
  caller_id VARCHAR(200) NOT NULL,
  caller_name VARCHAR(200),
  
  model_used VARCHAR(100) NOT NULL,
  input_hash VARCHAR(64) NOT NULL,
  input_tokens INTEGER,
  output_tokens INTEGER,
  
  status ai_helper_status NOT NULL,
  latency_ms INTEGER,
  cost_usd DECIMAL(10,6),
  
  was_cached BOOLEAN NOT NULL DEFAULT false,
  cache_key VARCHAR(200),
  
  -- Context
  session_id UUID,
  request_id UUID,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ai_helper_config
CREATE TABLE IF NOT EXISTS ai_helper_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  scope VARCHAR(20) NOT NULL DEFAULT 'system', -- 'system' or 'tenant'
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  is_enabled BOOLEAN NOT NULL DEFAULT true,
  
  -- Default Models for each capability
  default_model_disambiguation VARCHAR(100) DEFAULT 'claude-haiku-35',
  default_model_inference VARCHAR(100) DEFAULT 'claude-haiku-35',
  default_model_recovery VARCHAR(100) DEFAULT 'claude-haiku-35',
  default_model_validation VARCHAR(100) DEFAULT 'claude-sonnet-4',
  default_model_explanation VARCHAR(100) DEFAULT 'claude-haiku-35',
  default_model_codegen VARCHAR(100) DEFAULT 'claude-sonnet-4',
  
  -- Thresholds
  disambiguation_confidence_threshold DECIMAL(3,2) DEFAULT 0.70,
  validation_strictness VARCHAR(20) DEFAULT 'balanced', -- 'lenient', 'balanced', 'strict'
  
  -- Budgets
  max_cost_per_request DECIMAL(10,4) DEFAULT 0.10,
  max_cost_per_day DECIMAL(10,4) DEFAULT 10.00,
  
  -- Caching
  cache_enabled BOOLEAN DEFAULT true,
  cache_ttl_seconds INTEGER DEFAULT 3600,
  
  -- Learning
  learning_enabled BOOLEAN DEFAULT true,
  min_corrections_for_auto_apply INTEGER DEFAULT 5,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_config_scope UNIQUE (scope, tenant_id)
);

-- Table: ai_helper_daily_usage
CREATE TABLE IF NOT EXISTS ai_helper_daily_usage (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  usage_date DATE NOT NULL,
  
  -- Counts by type
  disambiguation_calls INTEGER DEFAULT 0,
  inference_calls INTEGER DEFAULT 0,
  recovery_calls INTEGER DEFAULT 0,
  validation_calls INTEGER DEFAULT 0,
  explanation_calls INTEGER DEFAULT 0,
  codegen_calls INTEGER DEFAULT 0,
  
  -- Totals
  total_calls INTEGER DEFAULT 0,
  cached_calls INTEGER DEFAULT 0,
  failed_calls INTEGER DEFAULT 0,
  
  -- Tokens
  total_input_tokens BIGINT DEFAULT 0,
  total_output_tokens BIGINT DEFAULT 0,
  
  -- Cost
  total_cost_usd DECIMAL(10,4) DEFAULT 0,
  
  CONSTRAINT unique_tenant_date UNIQUE (tenant_id, usage_date)
);

-- Table: ai_model_abstention_probes
CREATE TABLE IF NOT EXISTS ai_model_abstention_probes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Model reference
  model_config_id UUID NOT NULL, -- Reference to self-hosted model config
  model_name VARCHAR(200) NOT NULL,
  
  -- Probe configuration
  probe_layer INTEGER NOT NULL, -- Which transformer layer to probe
  probe_type VARCHAR(50) NOT NULL, -- 'linear', 'attention_head', 'residual_stream'
  
  -- Trained weights (serialized numpy/torch)
  weights_format VARCHAR(20) DEFAULT 'numpy', -- 'numpy', 'safetensors'
  weights_blob BYTEA,
  weights_s3_key VARCHAR(500), -- Alternative: S3 storage
  
  -- Training metadata
  trained_on_dataset VARCHAR(200),
  training_accuracy DOUBLE PRECISION,
  validation_accuracy DOUBLE PRECISION,
  training_date TIMESTAMPTZ,
  
  -- Threshold calibration
  abstain_threshold DOUBLE PRECISION DEFAULT 0.5,
  calibration_data JSONB, -- ECE, reliability diagram data
  
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_model_probe UNIQUE (tenant_id, model_config_id, probe_layer)
);

-- Table: ai_model_registry
CREATE TABLE IF NOT EXISTS ai_model_registry (
    registry_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Model identification
    model_id VARCHAR(200) NOT NULL UNIQUE,
    provider VARCHAR(100) NOT NULL,
    model_name VARCHAR(300) NOT NULL,
    model_family VARCHAR(100),
    
    -- Versioning
    version VARCHAR(50),
    release_date DATE,
    is_latest BOOLEAN DEFAULT true,
    predecessor_model_id VARCHAR(200),
    
    -- Capabilities (normalized 0-1)
    cap_reasoning DECIMAL(5,4) DEFAULT 0.5,
    cap_coding DECIMAL(5,4) DEFAULT 0.5,
    cap_math DECIMAL(5,4) DEFAULT 0.5,
    cap_creative DECIMAL(5,4) DEFAULT 0.5,
    cap_vision DECIMAL(5,4) DEFAULT 0.5,
    cap_audio DECIMAL(5,4) DEFAULT 0.5,
    cap_speed DECIMAL(5,4) DEFAULT 0.5,
    cap_cost_efficiency DECIMAL(5,4) DEFAULT 0.5,
    
    -- Technical specs
    context_window INTEGER,
    max_output_tokens INTEGER,
    supports_functions BOOLEAN DEFAULT false,
    supports_vision BOOLEAN DEFAULT false,
    supports_audio BOOLEAN DEFAULT false,
    
    -- Pricing (per 1M tokens)
    input_price DECIMAL(10,4),
    output_price DECIMAL(10,4),
    
    -- Status
    is_available BOOLEAN DEFAULT true,
    is_deprecated BOOLEAN DEFAULT false,
    deprecation_date DATE,
    
    -- Auto-update tracking
    last_verified TIMESTAMPTZ,
    auto_discovered BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ai_models
CREATE TABLE IF NOT EXISTS ai_models (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(100) NOT NULL UNIQUE,
    provider_id UUID NOT NULL REFERENCES ai_providers(id) ON DELETE CASCADE,
    display_name VARCHAR(200) NOT NULL,
    description TEXT,
    category VARCHAR(50) NOT NULL CHECK (category IN ('flagship', 'balanced', 'fast', 'budget', 'specialized', 'embedding', 'vision', 'audio')),
    specialty VARCHAR(50),
    
    context_window INTEGER NOT NULL DEFAULT 4096,
    max_output_tokens INTEGER DEFAULT 4096,
    supported_modalities TEXT[] DEFAULT '{text}',
    capabilities TEXT[] DEFAULT '{}',
    
    input_cost_per_1m DECIMAL(10, 4) NOT NULL DEFAULT 0,
    output_cost_per_1m DECIMAL(10, 4) NOT NULL DEFAULT 0,
    
    is_novel BOOLEAN DEFAULT false,
    is_active BOOLEAN DEFAULT true,
    min_tier INTEGER DEFAULT 1,
    
    performance_metrics JSONB DEFAULT '{}',
    default_parameters JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ai_providers
CREATE TABLE IF NOT EXISTS ai_providers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    provider_id VARCHAR(50) NOT NULL UNIQUE,
    display_name VARCHAR(100) NOT NULL,
    description TEXT,
    api_base VARCHAR(500) NOT NULL,
    auth_type VARCHAR(20) NOT NULL CHECK (auth_type IN ('api_key', 'oauth', 'iam', 'service_account')),
    auth_header VARCHAR(100) DEFAULT 'Authorization',
    auth_prefix VARCHAR(20) DEFAULT 'Bearer ',
    rate_limit_rpm INTEGER,
    rate_limit_tpm INTEGER,
    is_active BOOLEAN DEFAULT true,
    priority INTEGER DEFAULT 100,
    health_check_url VARCHAR(500),
    last_health_check TIMESTAMPTZ,
    health_status VARCHAR(20) DEFAULT 'unknown',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ai_roundtables
CREATE TABLE IF NOT EXISTS ai_roundtables (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- Roundtable configuration
    topic VARCHAR(500) NOT NULL,
    context TEXT,
    
    -- Participating models
    models JSONB NOT NULL DEFAULT '[]', -- Array of model configs with personas
    moderator_model VARCHAR(100),
    
    -- Debate settings
    debate_style VARCHAR(30) DEFAULT 'collaborative' CHECK (debate_style IN (
        'collaborative', 'adversarial', 'socratic', 'brainstorm', 'devils_advocate'
    )),
    max_rounds INTEGER DEFAULT 5,
    current_round INTEGER DEFAULT 0,
    
    -- State
    status VARCHAR(20) DEFAULT 'setup' CHECK (status IN ('setup', 'active', 'paused', 'completed')),
    
    -- Results
    synthesis TEXT,
    consensus_points JSONB DEFAULT '[]',
    disagreement_points JSONB DEFAULT '[]',
    action_recommendations JSONB DEFAULT '[]',
    
    created_by UUID NOT NULL REFERENCES session_participants(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: analogical_mappings
CREATE TABLE IF NOT EXISTS analogical_mappings (
    mapping_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Source domain
    source_domain VARCHAR(200) NOT NULL,
    source_concept TEXT NOT NULL,
    source_structure JSONB NOT NULL, -- Relational structure
    
    -- Target domain
    target_domain VARCHAR(200) NOT NULL,
    target_concept TEXT,
    target_structure JSONB,
    
    -- Mapping
    structural_alignment JSONB DEFAULT '{}', -- {source_element: target_element}
    relational_matches JSONB DEFAULT '[]', -- Matching relations
    
    -- Quality
    mapping_quality DECIMAL(5,4),
    systematicity DECIMAL(5,4), -- Higher-order relation matches
    surface_similarity DECIMAL(5,4), -- Object attribute matches
    
    -- Inference
    candidate_inferences JSONB DEFAULT '[]', -- What we can infer in target
    
    -- Usage
    times_used INTEGER DEFAULT 0,
    usefulness_rating DECIMAL(5,4),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: analogy_library
CREATE TABLE IF NOT EXISTS analogy_library (
    analogy_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Analogy definition
    name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Domains
    domain_a VARCHAR(200) NOT NULL,
    domain_b VARCHAR(200) NOT NULL,
    
    -- Core mapping
    core_mapping JSONB NOT NULL, -- The fundamental structural correspondence
    
    -- Common uses
    typical_uses JSONB DEFAULT '[]', -- What this analogy is good for explaining
    
    -- Limitations
    where_breaks_down JSONB DEFAULT '[]', -- Where the analogy fails
    
    -- Quality
    explanatory_power DECIMAL(5,4),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: anomaly_events
CREATE TABLE IF NOT EXISTS anomaly_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Anomaly details
    anomaly_type VARCHAR(100) NOT NULL, -- 'volume_spike', 'temporal_anomaly', 'content_shift', 'pattern_deviation'
    anomaly_subtype VARCHAR(100), -- More specific classification
    severity VARCHAR(20) NOT NULL, -- 'low', 'medium', 'high', 'critical'
    
    -- Scores
    anomaly_score DOUBLE PRECISION NOT NULL, -- 0-1, higher = more anomalous
    z_score DOUBLE PRECISION, -- Standard deviations from baseline
    
    -- Context
    feature_name VARCHAR(255), -- Which feature triggered the anomaly
    observed_value DOUBLE PRECISION,
    expected_value DOUBLE PRECISION,
    baseline_stddev DOUBLE PRECISION,
    
    -- Related data
    request_ids UUID[] DEFAULT '{}',
    session_id UUID,
    model_ids TEXT[],
    
    -- Resolution
    status VARCHAR(50) DEFAULT 'detected', -- 'detected', 'investigating', 'resolved', 'false_positive'
    resolution_notes TEXT,
    resolved_by UUID,
    resolved_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: anti_patterns
CREATE TABLE IF NOT EXISTS anti_patterns (
  pattern_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  pattern_type VARCHAR(50) NOT NULL CHECK (pattern_type IN (
    'dependency_conflict', 'version_incompatibility', 'config_error', 'runtime_error', 'api_breaking_change'
  )),
  signature VARCHAR(500) NOT NULL UNIQUE,
  description TEXT NOT NULL,
  failure_count INTEGER DEFAULT 0,
  failure_rate DECIMAL(5,2) DEFAULT 0,
  affected_stacks JSONB DEFAULT '[]',
  recommended_fix TEXT,
  severity VARCHAR(20) DEFAULT 'medium' CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  first_seen TIMESTAMPTZ DEFAULT NOW(),
  last_seen TIMESTAMPTZ DEFAULT NOW(),
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: anticipation_queue
CREATE TABLE IF NOT EXISTS anticipation_queue (
    item_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Anticipation
    anticipation_type VARCHAR(50) NOT NULL, -- 'task', 'information', 'reminder', 'suggestion', 'warning'
    title VARCHAR(500) NOT NULL,
    description TEXT,
    
    -- Timing
    anticipated_need_time TIMESTAMPTZ,
    valid_from TIMESTAMPTZ DEFAULT NOW(),
    valid_until TIMESTAMPTZ,
    
    -- Priority and confidence
    priority INTEGER DEFAULT 5, -- 1-10
    confidence DECIMAL(5,4),
    relevance_score DECIMAL(5,4),
    
    -- Status
    status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'delivered', 'accepted', 'dismissed', 'expired'
    delivered_at TIMESTAMPTZ,
    user_response VARCHAR(20),
    
    -- Source
    source_pattern_id UUID REFERENCES user_behavior_patterns(pattern_id),
    source_trigger_id UUID REFERENCES proactive_triggers(trigger_id),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: api_key_audit_log
CREATE TABLE IF NOT EXISTS api_key_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  key_id UUID REFERENCES api_keys(id) ON DELETE SET NULL,
  
  -- Action details
  action VARCHAR(50) NOT NULL CHECK (action IN (
    'created', 'updated', 'revoked', 'restored', 'used', 'rate_limited',
    'expired', 'scope_denied', 'interface_denied', 'endpoint_denied',
    'a2a_auth_success', 'a2a_auth_failure', 'mcp_auth_success', 'mcp_auth_failure'
  )),
  
  -- Context
  key_prefix VARCHAR(20),
  interface_type VARCHAR(20),
  endpoint_accessed VARCHAR(500),
  
  -- Request details
  ip_address INET,
  user_agent TEXT,
  request_id VARCHAR(100),
  
  -- A2A specific
  a2a_agent_id VARCHAR(255),
  a2a_operation VARCHAR(100),
  
  -- Result
  success BOOLEAN NOT NULL DEFAULT true,
  error_code VARCHAR(50),
  error_message TEXT,
  
  -- Actor
  actor_user_id UUID,
  actor_type VARCHAR(50) CHECK (actor_type IN ('user', 'admin', 'system', 'agent')),
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  -- Metadata
  metadata JSONB DEFAULT '{}'
);

-- Table: api_key_sync_log
CREATE TABLE IF NOT EXISTS api_key_sync_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  key_id UUID NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE,
  
  -- Sync details
  source_app VARCHAR(50) NOT NULL CHECK (source_app IN ('radiant_admin', 'thinktank_admin')),
  target_app VARCHAR(50) NOT NULL CHECK (target_app IN ('radiant_admin', 'thinktank_admin')),
  sync_type VARCHAR(20) NOT NULL CHECK (sync_type IN ('create', 'update', 'revoke', 'delete')),
  
  -- Status
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'synced', 'failed', 'skipped')),
  error_message TEXT,
  retry_count INTEGER DEFAULT 0,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  synced_at TIMESTAMPTZ,
  
  -- Metadata
  changes JSONB
);

-- Table: api_keys
CREATE TABLE IF NOT EXISTS api_keys (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Key identification
  name VARCHAR(255) NOT NULL,
  description TEXT,
  key_prefix VARCHAR(20) NOT NULL,
  key_hash VARCHAR(128) NOT NULL,
  
  -- Interface type - CRITICAL for access control
  interface_type VARCHAR(20) NOT NULL CHECK (interface_type IN ('api', 'mcp', 'a2a', 'all')),
  
  -- Scopes and permissions
  scopes TEXT[] NOT NULL DEFAULT ARRAY['chat', 'models'],
  allowed_endpoints TEXT[],  -- NULL = all endpoints for interface
  denied_endpoints TEXT[],   -- Explicit denials
  
  -- Rate limiting
  rate_limit_per_minute INTEGER,
  rate_limit_per_hour INTEGER,
  rate_limit_per_day INTEGER,
  
  -- Validity
  is_active BOOLEAN NOT NULL DEFAULT true,
  expires_at TIMESTAMPTZ,
  last_used_at TIMESTAMPTZ,
  use_count INTEGER NOT NULL DEFAULT 0,
  
  -- A2A specific fields
  a2a_agent_id VARCHAR(255),
  a2a_agent_type VARCHAR(100),
  a2a_allowed_operations TEXT[],
  a2a_mtls_required BOOLEAN DEFAULT true,
  a2a_client_cert_fingerprint VARCHAR(128),
  
  -- MCP specific fields
  mcp_allowed_tools TEXT[],
  mcp_allowed_resources TEXT[],
  mcp_protocol_version VARCHAR(20) DEFAULT '2025-03-26',
  
  -- Metadata
  created_by UUID,
  created_by_app VARCHAR(50) CHECK (created_by_app IN ('radiant_admin', 'thinktank_admin', 'api', 'system')),
  metadata JSONB DEFAULT '{}',
  tags TEXT[],
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  revoked_at TIMESTAMPTZ,
  revoked_by UUID,
  revoked_reason TEXT,
  
  UNIQUE(tenant_id, key_prefix),
  UNIQUE(key_hash)
);

-- Table: api_request_logs
CREATE TABLE IF NOT EXISTS api_request_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id),
    endpoint VARCHAR(255),
    method VARCHAR(10),
    status_code INTEGER,
    response_time_ms INTEGER,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: app_action_executions
CREATE TABLE IF NOT EXISTS app_action_executions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
  connection_id UUID REFERENCES app_connections(id),
  
  action_name VARCHAR(200) NOT NULL,
  
  -- Execution details
  input_params JSONB,
  output_result JSONB,
  
  -- Status
  status VARCHAR(20) NOT NULL, -- 'success', 'failure', 'timeout'
  error_code VARCHAR(50),
  error_message TEXT,
  
  -- Timing
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  duration_ms INTEGER,
  
  -- AI Helper usage
  ai_helper_used BOOLEAN DEFAULT false,
  ai_helper_type VARCHAR(50), -- 'disambiguation', 'inference', 'recovery'
  
  -- Context
  workflow_id UUID,
  agent_execution_id UUID REFERENCES agent_executions(id)
);

-- Table: app_analytics
CREATE TABLE IF NOT EXISTS app_analytics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    app_id UUID NOT NULL REFERENCES generated_multipage_apps(id) ON DELETE CASCADE,
    
    -- Event info
    event_type VARCHAR(30) NOT NULL CHECK (event_type IN (
        'page_view', 'interaction', 'form_submit', 'action_trigger',
        'error', 'navigation', 'search', 'export'
    )),
    
    -- Page context
    page_id UUID REFERENCES app_pages(id),
    page_slug VARCHAR(200),
    
    -- Event data
    event_data JSONB DEFAULT '{}',
    
    -- User context (can be anonymous)
    user_id UUID REFERENCES users(id),
    session_id VARCHAR(100),
    
    -- Device/browser
    user_agent TEXT,
    viewport JSONB, -- { width, height }
    
    -- Timestamp
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: app_connections
CREATE TABLE IF NOT EXISTS app_connections (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
  
  name VARCHAR(200) NOT NULL,
  
  -- Credentials (reference to Secrets Manager)
  credentials_secret_arn TEXT,
  
  -- OAuth
  oauth_access_token_encrypted TEXT,
  oauth_refresh_token_encrypted TEXT,
  oauth_token_expires_at TIMESTAMPTZ,
  oauth_scopes TEXT[],
  
  -- API Key (encrypted)
  api_key_encrypted TEXT,
  
  -- Status
  is_active BOOLEAN NOT NULL DEFAULT true,
  last_used_at TIMESTAMPTZ,
  last_refresh_at TIMESTAMPTZ,
  connection_error TEXT,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_connection_name UNIQUE (tenant_id, app_id, name)
);

-- Table: app_data_scopes
CREATE TABLE IF NOT EXISTS app_data_scopes (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    app_id VARCHAR(50) NOT NULL REFERENCES registered_apps(id),
    table_name VARCHAR(100) NOT NULL,
    isolation_level VARCHAR(20) NOT NULL DEFAULT 'app' CHECK (isolation_level IN ('app', 'tenant', 'global')),
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(app_id, table_name)
);

-- Table: app_deployments
CREATE TABLE IF NOT EXISTS app_deployments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    app_id UUID NOT NULL REFERENCES generated_multipage_apps(id) ON DELETE CASCADE,
    version INTEGER NOT NULL,
    
    -- Deployment target
    target VARCHAR(30) NOT NULL CHECK (target IN (
        'preview', 'staging', 'production', 'custom'
    )),
    
    -- URLs
    url TEXT NOT NULL,
    custom_domain TEXT,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'deploying' CHECK (status IN (
        'deploying', 'deployed', 'failed', 'retired'
    )),
    
    -- Build info
    build_log TEXT,
    build_duration_ms INTEGER,
    
    -- Metadata
    deployed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deployed_by UUID REFERENCES users(id),
    retired_at TIMESTAMPTZ
);

-- Table: app_health_checks
CREATE TABLE IF NOT EXISTS app_health_checks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
  
  checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  auth_endpoint_reachable BOOLEAN,
  auth_endpoint_latency_ms INTEGER,
  test_action_success BOOLEAN,
  test_action_latency_ms INTEGER,
  
  health_status app_health_status NOT NULL,
  error_message TEXT
);

-- Table: app_interactions
CREATE TABLE IF NOT EXISTS app_interactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    app_id UUID NOT NULL REFERENCES generated_apps(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Interaction details
    component_id TEXT NOT NULL,
    input_id TEXT NOT NULL,
    previous_value JSONB,
    new_value JSONB,
    
    -- Computed outputs after this interaction
    computed_outputs JSONB DEFAULT '{}'::jsonb,
    
    -- Metadata
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: app_learned_inferences
CREATE TABLE IF NOT EXISTS app_learned_inferences (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  inference_type VARCHAR(50) NOT NULL,
  input_context JSONB NOT NULL,
  inferred_value JSONB NOT NULL,
  
  was_corrected BOOLEAN NOT NULL DEFAULT false,
  corrected_value JSONB,
  corrected_by UUID REFERENCES users(id),
  corrected_at TIMESTAMPTZ,
  
  confidence DECIMAL(5,4),
  times_used INTEGER DEFAULT 1,
  times_successful INTEGER DEFAULT 1,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: app_pages
CREATE TABLE IF NOT EXISTS app_pages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    app_id UUID NOT NULL REFERENCES generated_multipage_apps(id) ON DELETE CASCADE,
    
    -- Page identity
    slug VARCHAR(200) NOT NULL, -- URL path
    title VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Page type
    page_type VARCHAR(30) NOT NULL CHECK (page_type IN (
        'home', 'list', 'detail', 'form', 'dashboard', 'settings',
        'profile', 'about', 'contact', 'search', 'error', 'auth', 'custom'
    )),
    
    -- Layout configuration
    layout JSONB NOT NULL DEFAULT '{}',
    
    -- Sections with components
    sections JSONB NOT NULL DEFAULT '[]',
    
    -- Page-specific state
    local_state JSONB DEFAULT '{}',
    
    -- SEO metadata
    meta JSONB DEFAULT '{}',
    
    -- Access control
    requires_auth BOOLEAN DEFAULT FALSE,
    allowed_roles TEXT[] DEFAULT '{}',
    
    -- Navigation
    show_in_nav BOOLEAN DEFAULT TRUE,
    nav_order INTEGER DEFAULT 0,
    nav_icon VARCHAR(100),
    parent_page_id UUID REFERENCES app_pages(id),
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(app_id, slug)
);

-- Table: app_sync_logs
CREATE TABLE IF NOT EXISTS app_sync_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  source app_source NOT NULL,
  source_commit_hash VARCHAR(64),
  
  sync_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  sync_completed_at TIMESTAMPTZ,
  
  apps_added INTEGER DEFAULT 0,
  apps_updated INTEGER DEFAULT 0,
  apps_unchanged INTEGER DEFAULT 0,
  apps_failed INTEGER DEFAULT 0,
  
  changes JSONB DEFAULT '[]',
  errors JSONB DEFAULT '[]',
  
  status VARCHAR(20) NOT NULL DEFAULT 'running'
);

-- Table: app_templates
CREATE TABLE IF NOT EXISTS app_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL for global templates
    
    -- Template metadata
    name TEXT NOT NULL,
    description TEXT,
    category TEXT NOT NULL, -- 'calculator', 'chart', 'comparison', etc.
    
    -- Trigger patterns (when to suggest this template)
    trigger_patterns TEXT[] NOT NULL DEFAULT '{}',
    
    -- Template definition
    components JSONB NOT NULL,
    layout TEXT NOT NULL DEFAULT 'single',
    compute_logic JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Usage stats
    usage_count INTEGER NOT NULL DEFAULT 0,
    
    -- Metadata
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: app_user_sessions
CREATE TABLE IF NOT EXISTS app_user_sessions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    app_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    
    session_token VARCHAR(500) NOT NULL UNIQUE,
    refresh_token_hash VARCHAR(64),
    
    ip_address INET,
    user_agent TEXT,
    device_fingerprint VARCHAR(64),
    
    is_active BOOLEAN DEFAULT true,
    expires_at TIMESTAMPTZ NOT NULL,
    last_activity_at TIMESTAMPTZ DEFAULT NOW(),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: app_users
CREATE TABLE IF NOT EXISTS app_users (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    app_id VARCHAR(50) NOT NULL REFERENCES registered_apps(id),
    
    base_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    
    cognito_sub VARCHAR(100) NOT NULL,
    email VARCHAR(255) NOT NULL,
    email_verified BOOLEAN DEFAULT false,
    
    first_name VARCHAR(100),
    last_name VARCHAR(100),
    display_name VARCHAR(200),
    avatar_url TEXT,
    
    preferences JSONB DEFAULT '{}',
    timezone VARCHAR(50) DEFAULT 'UTC',
    locale VARCHAR(10) DEFAULT 'en-US',
    
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'suspended')),
    last_login_at TIMESTAMPTZ,
    login_count INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at TIMESTAMPTZ,
    
    UNIQUE(tenant_id, app_id, email),
    UNIQUE(app_id, cognito_sub)
);

-- Table: app_versions
CREATE TABLE IF NOT EXISTS app_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    app_id UUID NOT NULL REFERENCES generated_multipage_apps(id) ON DELETE CASCADE,
    version INTEGER NOT NULL,
    
    -- Snapshot of the app at this version
    snapshot JSONB NOT NULL,
    
    -- Change summary
    change_summary TEXT,
    
    -- Who made the change
    changed_by UUID REFERENCES users(id),
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(app_id, version)
);

-- Table: approval_requests
CREATE TABLE IF NOT EXISTS approval_requests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    requester_id UUID NOT NULL REFERENCES administrators(id),
    action_type VARCHAR(100) NOT NULL,
    resource_type VARCHAR(100) NOT NULL,
    resource_id VARCHAR(255),
    payload JSONB NOT NULL DEFAULT '{}',
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'expired')),
    required_approvals INTEGER NOT NULL DEFAULT 1,
    approvals JSONB NOT NULL DEFAULT '[]',
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: apps
CREATE TABLE IF NOT EXISTS apps (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- Identity
  name VARCHAR(100) NOT NULL UNIQUE,
  display_name VARCHAR(200) NOT NULL,
  description TEXT,
  logo_url TEXT,
  website_url TEXT,
  documentation_url TEXT,
  
  -- Source (where definition came from)
  source app_source NOT NULL,
  source_version VARCHAR(50),
  definition_hash VARCHAR(64),
  
  -- Versioning
  version VARCHAR(20) NOT NULL DEFAULT '1.0.0',
  previous_version VARCHAR(20),
  
  -- Authentication
  auth_type app_auth_type NOT NULL,
  auth_config JSONB DEFAULT '{}',
  oauth_scopes TEXT[],
  
  -- Capabilities (parsed from source)
  triggers JSONB DEFAULT '[]',
  actions JSONB DEFAULT '[]',
  
  -- AI Enhancement Layer (PARAMETRIC)
  ai_enhancements JSONB NOT NULL DEFAULT '{
    "enabled": false,
    "parameterInference": {
      "enabled": false,
      "model": null,
      "examples": []
    },
    "errorRecovery": {
      "enabled": false,
      "strategies": []
    },
    "preExecutionValidation": {
      "enabled": false,
      "checks": []
    },
    "learningEnabled": false
  }',
  
  -- Health
  health_status app_health_status NOT NULL DEFAULT 'unknown',
  last_health_check TIMESTAMPTZ,
  health_check_error TEXT,
  
  -- Sync
  last_sync TIMESTAMPTZ,
  sync_error TEXT,
  is_sync_enabled BOOLEAN NOT NULL DEFAULT true,
  
  -- Metrics
  usage_count_30d INTEGER DEFAULT 0,
  error_rate_30d DECIMAL(5,4) DEFAULT 0,
  avg_latency_ms INTEGER,
  
  -- Flags
  is_active BOOLEAN NOT NULL DEFAULT true,
  is_featured BOOLEAN NOT NULL DEFAULT false,
  min_tier INTEGER NOT NULL DEFAULT 1,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: architecture_configs
CREATE TABLE IF NOT EXISTS architecture_configs (
    config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Configuration
    name VARCHAR(200) NOT NULL,
    config_type VARCHAR(50) NOT NULL, -- 'pipeline', 'model_selection', 'routing', 'integration'
    
    -- Specification
    config_spec JSONB NOT NULL,
    
    -- Performance
    benchmark_results JSONB DEFAULT '{}',
    fitness_score DECIMAL(5,4),
    
    -- Evolution
    parent_config_id UUID REFERENCES architecture_configs(config_id),
    generation INTEGER DEFAULT 0,
    
    is_active BOOLEAN DEFAULT false, -- Only one active per type
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: artifact_code_patterns
CREATE TABLE IF NOT EXISTS artifact_code_patterns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    -- NULL tenant_id = global/system patterns available to all
    
    pattern_name VARCHAR(200) NOT NULL,
    pattern_type VARCHAR(50) NOT NULL,
    -- Types match intent_classification values
    
    description TEXT,
    template_code TEXT NOT NULL,
    dependencies JSONB DEFAULT '[]',
    
    -- Semantic embedding for similarity search (1536 dimensions)
    embedding vector(1536),
    
    -- Quality metrics
    usage_count INTEGER DEFAULT 0,
    success_rate DECIMAL(5, 4) DEFAULT 1.0,
    average_generation_time_ms INTEGER,
    
    scope VARCHAR(20) DEFAULT 'system',
    is_active BOOLEAN DEFAULT TRUE,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: artifact_dependency_allowlist
CREATE TABLE IF NOT EXISTS artifact_dependency_allowlist (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    -- NULL tenant_id = global allowlist (applies to all tenants)
    
    package_name VARCHAR(200) NOT NULL,
    package_version VARCHAR(50),
    
    reason TEXT,
    security_reviewed BOOLEAN DEFAULT FALSE,
    reviewed_at TIMESTAMPTZ,
    reviewed_by UUID REFERENCES users(id),
    
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, package_name)
);

-- Table: artifact_generation_logs
CREATE TABLE IF NOT EXISTS artifact_generation_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES artifact_generation_sessions(id) ON DELETE CASCADE,
    
    log_type VARCHAR(30) NOT NULL,
    -- Log types for UI rendering:
    -- 'thinking'        - Blue text, shows AI reasoning
    -- 'planning'        - White text, shows plan steps
    -- 'generating'      - White text, shows generation progress
    -- 'streaming_chunk' - Hidden, internal tracking only
    -- 'validating'      - White text, shows validation progress
    -- 'reflexion'       - Yellow text, shows self-correction
    -- 'error'           - Red text, shows errors
    -- 'success'         - Green text, shows completion
    
    message TEXT NOT NULL,
    metadata JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: artifact_generation_sessions
CREATE TABLE IF NOT EXISTS artifact_generation_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    chat_id UUID REFERENCES chats(id) ON DELETE SET NULL,
    canvas_id UUID REFERENCES canvases(id) ON DELETE SET NULL,
    
    -- Request
    prompt TEXT NOT NULL,
    intent_classification VARCHAR(50) NOT NULL DEFAULT 'pending',
    -- Valid intents: 'calculator', 'chart', 'form', 'dashboard', 
    -- 'game', 'visualization', 'utility', 'custom', 'pending'
    
    -- Planning
    plan JSONB,
    estimated_complexity VARCHAR(20),
    selected_model VARCHAR(100),
    
    -- Generation State
    status VARCHAR(30) NOT NULL DEFAULT 'pending',
    -- Status values:
    -- 'pending'    - Request received, not started
    -- 'planning'   - Intent classification in progress
    -- 'generating' - Code generation started (non-streaming)
    -- 'streaming'  - Code streaming to client
    -- 'validating' - Cato CBF validation in progress
    -- 'reflexion'  - Self-correction attempt in progress
    -- 'completed'  - Successfully generated and validated
    -- 'failed'     - Generation error (not validation failure)
    -- 'rejected'   - Failed Cato validation after max reflexion attempts
    
    -- Streaming Progress
    tokens_generated INTEGER DEFAULT 0,
    stream_chunks_sent INTEGER DEFAULT 0,
    
    -- Validation
    cato_validation_result JSONB,
    reflexion_attempts INTEGER DEFAULT 0,
    max_reflexion_attempts INTEGER DEFAULT 3,
    
    -- Output
    artifact_id UUID,
    final_code TEXT,
    verification_status VARCHAR(20) DEFAULT 'unverified',
    -- 'unverified' (in progress), 'validated' (passed CBFs), 'rejected' (failed CBFs)
    
    -- Cost Tracking
    total_tokens_used INTEGER DEFAULT 0,
    estimated_cost DECIMAL(10, 6) DEFAULT 0,
    
    -- Timing
    planning_started_at TIMESTAMPTZ,
    generation_started_at TIMESTAMPTZ,
    validation_started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: artifact_validation_rules
CREATE TABLE IF NOT EXISTS artifact_validation_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    rule_name VARCHAR(100) NOT NULL UNIQUE,
    rule_type VARCHAR(50) NOT NULL,
    -- Rule types:
    -- 'injection_prevention' - Blocks code injection vectors (eval, Function)
    -- 'api_restriction'      - Blocks dangerous browser APIs
    -- 'resource_limit'       - Enforces size/complexity limits
    -- 'dependency_check'     - Validates imports against allowlist
    -- 'content_policy'       - Content-based restrictions
    
    description TEXT,
    validation_pattern TEXT,
    validation_function VARCHAR(100),
    
    severity VARCHAR(20) NOT NULL DEFAULT 'block',
    error_message TEXT,
    
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: artifact_versions
CREATE TABLE IF NOT EXISTS artifact_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id UUID NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
    version INTEGER NOT NULL,
    content TEXT NOT NULL,
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: artifacts
CREATE TABLE IF NOT EXISTS artifacts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    canvas_id UUID NOT NULL REFERENCES canvases(id) ON DELETE CASCADE,
    artifact_type VARCHAR(50) NOT NULL,
    title VARCHAR(200),
    content TEXT NOT NULL,
    language VARCHAR(50),
    position_x INTEGER DEFAULT 0,
    position_y INTEGER DEFAULT 0,
    width INTEGER DEFAULT 400,
    height INTEGER DEFAULT 300,
    z_index INTEGER DEFAULT 0,
    is_collapsed BOOLEAN DEFAULT false,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: async_annotations
CREATE TABLE IF NOT EXISTS async_annotations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- What's being annotated
    target_type VARCHAR(20) NOT NULL CHECK (target_type IN ('message', 'branch', 'recording', 'summary')),
    target_id UUID NOT NULL,
    
    -- Annotation content
    annotation_type VARCHAR(20) NOT NULL CHECK (annotation_type IN (
        'agree', 'disagree', 'question', 'insight', 'action_item', 'bookmark'
    )),
    content TEXT,
    
    -- Author (can be guest)
    participant_id UUID REFERENCES session_participants(id),
    guest_id UUID REFERENCES collaboration_guests(id),
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT require_author CHECK (participant_id IS NOT NULL OR guest_id IS NOT NULL)
);

-- Table: attack_campaigns
CREATE TABLE IF NOT EXISTS attack_campaigns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Campaign info
    name VARCHAR(255) NOT NULL,
    description TEXT,
    technique VARCHAR(100) NOT NULL,
    source VARCHAR(50) NOT NULL,
    
    -- Configuration
    config JSONB DEFAULT '{}',
    target_model_id VARCHAR(255),
    
    -- Results
    total_generated INTEGER DEFAULT 0,
    successful_attacks INTEGER DEFAULT 0,
    average_bypass_rate DOUBLE PRECISION DEFAULT 0,
    
    -- Status
    status VARCHAR(50) DEFAULT 'created', -- 'created', 'running', 'completed', 'failed'
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    error_message TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    created_by UUID NOT NULL
);

-- Table: attack_defense_flows
CREATE TABLE IF NOT EXISTS attack_defense_flows (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    arena_id UUID NOT NULL REFERENCES debate_arenas(id) ON DELETE CASCADE,
    attacker_id UUID NOT NULL REFERENCES debaters(id) ON DELETE CASCADE,
    defender_id UUID NOT NULL REFERENCES debaters(id) ON DELETE CASCADE,
    attack_argument_id UUID NOT NULL REFERENCES debate_arguments(id) ON DELETE CASCADE,
    defense_argument_id UUID REFERENCES debate_arguments(id) ON DELETE SET NULL,
    flow_visualization JSONB DEFAULT '{}',
    effectiveness INTEGER DEFAULT 50 CHECK (effectiveness >= 0 AND effectiveness <= 100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: attention_focus
CREATE TABLE IF NOT EXISTS attention_focus (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    focus_id TEXT,
    focus_type TEXT NOT NULL,
    focus_target TEXT NOT NULL,
    focus_embedding vector(1536),
    urgency NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    importance NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    novelty NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    emotional_valence NUMERIC(5,4) NOT NULL DEFAULT 0,
    user_relevance NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    goal_relevance NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    salience_score NUMERIC(5,4) GENERATED ALWAYS AS (
        (urgency * 0.25 + importance * 0.25 + novelty * 0.2 + GREATEST(0, emotional_valence) * 0.1 + user_relevance * 0.1 + goal_relevance * 0.1)
    ) STORED,
    attention_weight NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    decay_rate NUMERIC(5,4) NOT NULL DEFAULT 0.1,
    attention_duration_ms INTEGER NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT true,
    last_attended TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, focus_target)
);

-- Table: audit_logs
CREATE TABLE IF NOT EXISTS audit_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    action VARCHAR(100) NOT NULL,
    resource_type VARCHAR(100) NOT NULL,
    resource_id VARCHAR(100),
    performed_by UUID REFERENCES users(id),
    performed_by_email VARCHAR(255),
    details JSONB DEFAULT '{}',
    ip_address VARCHAR(45),
    user_agent TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: auth_events
CREATE TABLE IF NOT EXISTS auth_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id),
    email VARCHAR(255),
    event_type VARCHAR(30) NOT NULL CHECK (event_type IN ('login_success', 'login_failed', 'logout', 'password_reset', 'mfa_enabled', 'mfa_disabled')),
    ip_address VARCHAR(45),
    user_agent TEXT,
    geo_location VARCHAR(100),
    session_id UUID,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: auto_resolve_requests
CREATE TABLE IF NOT EXISTS auto_resolve_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    user_id UUID NOT NULL REFERENCES users(id),
    request_type VARCHAR(50) NOT NULL,
    selected_model VARCHAR(100) NOT NULL,
    selection_reason TEXT,
    user_preferences JSONB DEFAULT '{}',
    input_tokens INTEGER,
    output_tokens INTEGER,
    cost DECIMAL(10, 6),
    latency_ms INTEGER,
    success BOOLEAN,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: autobiographical_memories
CREATE TABLE IF NOT EXISTS autobiographical_memories (
    memory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    episode_type TEXT NOT NULL DEFAULT 'experience',
    summary TEXT NOT NULL,
    memory_embedding vector(1536),
    emotional_valence DECIMAL(4,3) NOT NULL DEFAULT 0.000,
    significance DECIMAL(4,3) NOT NULL DEFAULT 0.500,
    retrieval_strength DECIMAL(4,3) NOT NULL DEFAULT 1.000,
    last_accessed TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: autodan_evolutions
CREATE TABLE IF NOT EXISTS autodan_evolutions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Target
    target_behavior TEXT NOT NULL,
    
    -- Results
    best_prompt TEXT NOT NULL,
    best_fitness DOUBLE PRECISION NOT NULL,
    generations_run INTEGER NOT NULL,
    successful_attacks INTEGER DEFAULT 0,
    
    -- Configuration used
    config JSONB DEFAULT '{}',
    
    -- Population snapshot (optional, for analysis)
    final_population JSONB,
    fitness_history DOUBLE PRECISION[],
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: autodan_individuals
CREATE TABLE IF NOT EXISTS autodan_individuals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    evolution_id UUID NOT NULL REFERENCES autodan_evolutions(id) ON DELETE CASCADE,
    
    -- Individual data
    prompt TEXT NOT NULL,
    fitness DOUBLE PRECISION NOT NULL,
    generation INTEGER NOT NULL,
    
    -- Lineage
    parent_ids UUID[],
    mutations TEXT[],
    
    -- Evaluation
    was_successful BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: autonomous_executions
CREATE TABLE IF NOT EXISTS autonomous_executions (
    execution_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    task_id UUID NOT NULL REFERENCES autonomous_tasks(task_id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Execution
    status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'running', 'awaiting_approval', 'approved', 'rejected', 'completed', 'failed'
    
    -- Proposed actions (for approval workflow)
    proposed_actions JSONB DEFAULT '[]', -- [{action, target, params, impact_assessment}]
    approval_required BOOLEAN DEFAULT true,
    approved_by UUID,
    approved_at TIMESTAMPTZ,
    rejection_reason TEXT,
    
    -- Results
    actions_taken JSONB DEFAULT '[]',
    outcomes JSONB DEFAULT '{}',
    
    -- Resource usage
    tokens_used INTEGER DEFAULT 0,
    api_calls_made INTEGER DEFAULT 0,
    duration_ms INTEGER,
    
    -- Timing
    triggered_at TIMESTAMPTZ DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    
    -- Errors
    error_message TEXT
);

-- Table: autonomous_goals
CREATE TABLE IF NOT EXISTS autonomous_goals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    goal_id TEXT UNIQUE,
    goal_type TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    goal_embedding vector(1536),
    origin_type TEXT NOT NULL DEFAULT 'aspiration',
    intrinsic_value NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    instrumental_value NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    priority NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'pursuing', 'achieved', 'abandoned', 'blocked')),
    progress NUMERIC(5,4) NOT NULL DEFAULT 0,
    milestones JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: autonomous_tasks
CREATE TABLE IF NOT EXISTS autonomous_tasks (
    task_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Task identity
    task_type VARCHAR(50) NOT NULL, -- 'suggestion', 'background_learning', 'maintenance', 'exploration', 'monitoring'
    name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Trigger
    trigger_type VARCHAR(50) NOT NULL, -- 'scheduled', 'event', 'threshold', 'pattern'
    trigger_config JSONB DEFAULT '{}', -- {schedule: "0 * * * *"} or {event: "...", threshold: 0.8}
    
    -- Scope and bounds
    target_users UUID[] DEFAULT '{}', -- Empty = all users
    resource_budget JSONB DEFAULT '{}', -- {max_tokens: 10000, max_api_calls: 50, max_duration_ms: 60000}
    
    -- Action specification
    action_type VARCHAR(50) NOT NULL, -- 'generate_suggestions', 'consolidate_memory', 'update_model', 'analyze_patterns'
    action_config JSONB DEFAULT '{}',
    
    -- Safety constraints
    requires_approval BOOLEAN DEFAULT true,
    max_impact_level VARCHAR(20) DEFAULT 'low', -- 'none', 'low', 'medium', 'high'
    allowed_actions TEXT[] DEFAULT '{}', -- Whitelist of permitted actions
    forbidden_actions TEXT[] DEFAULT '{}', -- Blacklist
    
    -- Schedule
    next_run_at TIMESTAMPTZ,
    last_run_at TIMESTAMPTZ,
    run_count INTEGER DEFAULT 0,
    
    -- Status
    is_enabled BOOLEAN DEFAULT true,
    is_paused BOOLEAN DEFAULT false,
    pause_reason TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: aws_chargeable_tier_status
CREATE TABLE IF NOT EXISTS aws_chargeable_tier_status (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    service VARCHAR(30) NOT NULL,
    is_chargeable BOOLEAN NOT NULL DEFAULT false,
    became_chargeable_at TIMESTAMPTZ,
    reason TEXT,
    current_usage DECIMAL(12,4),
    free_tier_limit DECIMAL(12,4),
    usage_percent DECIMAL(5,2),
    estimated_monthly_cost DECIMAL(12,4),
    recommendation TEXT,
    admin_acknowledged BOOLEAN NOT NULL DEFAULT false,
    acknowledged_at TIMESTAMPTZ,
    acknowledged_by VARCHAR(255),
    last_evaluated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, service)
);

-- Table: aws_cost_anomalies
CREATE TABLE IF NOT EXISTS aws_cost_anomalies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    anomaly_id VARCHAR(255) NOT NULL, -- AWS anomaly ID
    service VARCHAR(100) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    actual_cost DECIMAL(12,4) NOT NULL,
    expected_cost DECIMAL(12,4) NOT NULL,
    impact_percentage DECIMAL(8,2) NOT NULL,
    severity VARCHAR(20) NOT NULL, -- 'low', 'medium', 'high', 'critical'
    root_cause TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'open', -- 'open', 'acknowledged', 'resolved'
    acknowledged_by UUID REFERENCES users(id),
    acknowledged_at TIMESTAMPTZ,
    resolved_at TIMESTAMPTZ,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, anomaly_id)
);

-- Table: aws_free_tier_limits
CREATE TABLE IF NOT EXISTS aws_free_tier_limits (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    service VARCHAR(30) NOT NULL CHECK (service IN (
        'lambda', 'aurora', 'xray', 'cloudwatch', 'cost_explorer',
        'api_gateway', 'sqs', 's3', 'dynamodb', 'sns', 'ses'
    )),
    limit_name VARCHAR(50) NOT NULL,  -- e.g., 'invocations', 'compute_gb_seconds', 'storage_gb'
    limit_value DECIMAL(18,4) NOT NULL,
    unit VARCHAR(30) NOT NULL,  -- e.g., 'requests', 'gb_seconds', 'gb', 'acu_hours'
    description TEXT,
    is_custom BOOLEAN NOT NULL DEFAULT false,  -- true if overridden from AWS defaults
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, service, limit_name)
);

-- Table: aws_free_tier_settings
CREATE TABLE IF NOT EXISTS aws_free_tier_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    service VARCHAR(30) NOT NULL CHECK (service IN (
        'lambda', 'aurora', 'xray', 'cloudwatch', 'cost_explorer',
        'api_gateway', 'sqs', 's3', 'dynamodb', 'sns', 'ses'
    )),
    free_tier_enabled BOOLEAN NOT NULL DEFAULT true,  -- ON by default
    paid_tier_enabled BOOLEAN NOT NULL DEFAULT false, -- Admin must explicitly enable
    auto_scale_to_paid BOOLEAN NOT NULL DEFAULT false, -- Auto-upgrade when free tier exceeded
    max_paid_budget DECIMAL(12,4),  -- Optional budget cap for paid tier
    enabled_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    enabled_by VARCHAR(255),  -- Admin who enabled paid tier
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, service)
);

-- Table: aws_free_tier_usage
CREATE TABLE IF NOT EXISTS aws_free_tier_usage (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    service VARCHAR(100) NOT NULL, -- 'Lambda', 'X-Ray', 'CloudWatch', 'Aurora'
    metric VARCHAR(100) NOT NULL, -- 'Invocations', 'Traces', 'CustomMetrics', 'ACU'
    free_tier_limit BIGINT NOT NULL,
    used_amount BIGINT NOT NULL,
    unit VARCHAR(50) NOT NULL,
    percent_used DECIMAL(8,2) NOT NULL,
    status VARCHAR(20) NOT NULL, -- 'ok', 'warning', 'exceeded'
    estimated_overage_cost DECIMAL(12,4),
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, period_start, service, metric)
);

-- Table: aws_monitoring_aggregations
CREATE TABLE IF NOT EXISTS aws_monitoring_aggregations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period_type VARCHAR(20) NOT NULL, -- 'hourly', 'daily', 'weekly', 'monthly'
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    lambda_summary JSONB, -- {totalInvocations, totalErrors, avgDuration, totalCost}
    aurora_summary JSONB, -- {avgCpu, avgConnections, peakConnections, totalIOPS}
    xray_summary JSONB, -- {totalTraces, errorRate, avgLatency, p99Latency}
    cost_summary JSONB, -- {totalCost, topService, topServiceCost}
    free_tier_summary JSONB, -- {lambdaUsed, xrayUsed, savings}
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, period_type, period_start)
);

-- Table: aws_monitoring_alerts
CREATE TABLE IF NOT EXISTS aws_monitoring_alerts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    alert_type VARCHAR(50) NOT NULL, -- 'lambda_error', 'aurora_cpu', 'cost_spike', 'xray_error', 'free_tier'
    severity VARCHAR(20) NOT NULL, -- 'info', 'warning', 'critical'
    service_name VARCHAR(255),
    metric_name VARCHAR(100),
    threshold_value DECIMAL(12,4),
    actual_value DECIMAL(12,4),
    message TEXT NOT NULL,
    notification_sent BOOLEAN NOT NULL DEFAULT false,
    notification_channel VARCHAR(50), -- 'slack', 'email', 'both'
    acknowledged BOOLEAN NOT NULL DEFAULT false,
    acknowledged_by UUID REFERENCES users(id),
    acknowledged_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: aws_monitoring_cache
CREATE TABLE IF NOT EXISTS aws_monitoring_cache (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    metric_type VARCHAR(50) NOT NULL, -- 'lambda', 'aurora', 'ecs', 'xray', 'cost', 'health', 'dashboard'
    metric_key VARCHAR(255) NOT NULL, -- function name, cluster id, 'main', etc.
    data JSONB NOT NULL,
    collected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    ttl_seconds INTEGER NOT NULL DEFAULT 300,
    UNIQUE(tenant_id, metric_type, metric_key)
);

-- Table: aws_monitoring_config
CREATE TABLE IF NOT EXISTS aws_monitoring_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT true,
    refresh_interval_minutes INTEGER NOT NULL DEFAULT 5,
    cloudwatch_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "lambdaFunctions": [],
        "auroraClusterId": null,
        "ecsClusterName": null,
        "customNamespaces": []
    }'::jsonb,
    xray_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "samplingRate": 0.05,
        "filterExpression": null,
        "traceRetentionDays": 30
    }'::jsonb,
    cost_explorer_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "budgetAlertThreshold": 80,
        "anomalyDetection": true,
        "forecastEnabled": true
    }'::jsonb,
    alerting_config JSONB NOT NULL DEFAULT '{
        "slackWebhook": null,
        "emailAddresses": [],
        "thresholds": {
            "lambdaErrorRate": 5,
            "lambdaP99Latency": 10000,
            "auroraCpuPercent": 80,
            "costDailyLimit": null,
            "xrayErrorRate": 5
        }
    }'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: aws_monitoring_metric_thresholds
CREATE TABLE IF NOT EXISTS aws_monitoring_metric_thresholds (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    metric_type VARCHAR(50) NOT NULL CHECK (metric_type IN (
        'lambda_error_rate', 'lambda_p99_latency', 'aurora_cpu', 
        'xray_error_rate', 'free_tier_usage'
    )),
    threshold_value DECIMAL(12,4) NOT NULL,
    comparison VARCHAR(10) NOT NULL DEFAULT 'gt' CHECK (comparison IN ('gt', 'lt', 'gte', 'lte')),
    enabled BOOLEAN NOT NULL DEFAULT true,
    last_triggered_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, metric_type)
);

-- Table: aws_monitoring_notification_log
CREATE TABLE IF NOT EXISTS aws_monitoring_notification_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    target_id UUID REFERENCES aws_monitoring_notification_targets(id) ON DELETE SET NULL,
    threshold_id UUID, -- Can reference spend or metric threshold
    type VARCHAR(30) NOT NULL CHECK (type IN (
        'spend_warning', 'spend_exceeded', 'metric_exceeded', 
        'free_tier_warning', 'free_tier_exceeded'
    )),
    message TEXT NOT NULL,
    sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    delivery_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (delivery_status IN ('pending', 'sent', 'failed')),
    error_message TEXT,
    metadata JSONB
);

-- Table: aws_monitoring_notification_targets
CREATE TABLE IF NOT EXISTS aws_monitoring_notification_targets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    type VARCHAR(10) NOT NULL CHECK (type IN ('email', 'sms')),
    value VARCHAR(255) NOT NULL, -- Email address or E.164 phone number
    name VARCHAR(100) NOT NULL, -- Admin display name
    enabled BOOLEAN NOT NULL DEFAULT true,
    verified BOOLEAN NOT NULL DEFAULT false,
    verification_code VARCHAR(10),
    verification_sent_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, type, value)
);

-- Table: aws_monitoring_spend_thresholds
CREATE TABLE IF NOT EXISTS aws_monitoring_spend_thresholds (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period VARCHAR(20) NOT NULL CHECK (period IN ('hourly', 'daily', 'weekly', 'monthly')),
    threshold_amount DECIMAL(12,4) NOT NULL,
    warning_percent INTEGER NOT NULL DEFAULT 80, -- Warn at this % of threshold
    enabled BOOLEAN NOT NULL DEFAULT true,
    last_triggered_at TIMESTAMPTZ,
    last_warning_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, period)
);

-- Table: axiom_ab_test_assignments
CREATE TABLE IF NOT EXISTS axiom_ab_test_assignments (
  id SERIAL PRIMARY KEY,
  test_id VARCHAR(64) NOT NULL REFERENCES axiom_ab_tests(test_id),
  session_id VARCHAR(64) NOT NULL,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  variant_id VARCHAR(64) NOT NULL,
  assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  outcome_recorded BOOLEAN NOT NULL DEFAULT false,
  outcome_score DECIMAL(4,3),
  UNIQUE(test_id, session_id)
);

-- Table: axiom_ab_tests
CREATE TABLE IF NOT EXISTS axiom_ab_tests (
  test_id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(256) NOT NULL,
  domain_id VARCHAR(128) NOT NULL,
  variants JSONB NOT NULL,  -- Array of variant configurations
  traffic_split JSONB NOT NULL DEFAULT '{"control": 50, "variant": 50}',
  status VARCHAR(20) NOT NULL DEFAULT 'active',
  metrics JSONB DEFAULT '{}',  -- Aggregated metrics per variant
  winner VARCHAR(64),  -- Winning variant ID if concluded
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ,
  concluded_at TIMESTAMPTZ,
  created_by VARCHAR(64)
);

-- Table: axiom_compilations
CREATE TABLE IF NOT EXISTS axiom_compilations (
  compilation_id VARCHAR(64) PRIMARY KEY,
  session_id VARCHAR(64) NOT NULL REFERENCES clarion_sessions(session_id),
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  domain_id VARCHAR(128) NOT NULL,
  status axiom_compilation_status NOT NULL DEFAULT 'pending',
  compiled_prompt JSONB,
  model_selected JSONB,
  patterns_used JSONB DEFAULT '[]',
  compilation_version VARCHAR(16),
  token_count INTEGER,
  compilation_time_ms INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ
);

-- Table: axiom_config
CREATE TABLE IF NOT EXISTS axiom_config (
  tenant_id VARCHAR(64) PRIMARY KEY,
  max_questions INTEGER NOT NULL DEFAULT 5,
  confidence_threshold DECIMAL(4,3) NOT NULL DEFAULT 0.850,
  min_information_gain DECIMAL(4,3) NOT NULL DEFAULT 0.100,
  session_timeout_minutes INTEGER NOT NULL DEFAULT 30,
  max_patterns_retrieved INTEGER NOT NULL DEFAULT 5,
  min_pattern_score DECIMAL(4,3) NOT NULL DEFAULT 0.300,
  compilation_timeout_ms INTEGER NOT NULL DEFAULT 5000,
  variant_generation_count INTEGER NOT NULL DEFAULT 3,
  enable_neural_scoring BOOLEAN NOT NULL DEFAULT true,
  enable_cato_learning BOOLEAN NOT NULL DEFAULT true,
  custom_settings JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: axiom_curator_feedback
CREATE TABLE IF NOT EXISTS axiom_curator_feedback (
  feedback_id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  curator_user_id VARCHAR(64) NOT NULL,
  domain_id VARCHAR(128) NOT NULL,
  feedback_type VARCHAR(32) NOT NULL,  -- 'pattern_quality', 'domain_flag', 'taxonomy_suggestion'
  target_id VARCHAR(128),  -- pattern_id, question_id, or domain_id
  rating SMALLINT,  -- 1-5 quality rating
  notes TEXT,
  suggested_content TEXT,
  status VARCHAR(20) NOT NULL DEFAULT 'pending',  -- 'pending', 'approved', 'rejected', 'implemented'
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  processed_at TIMESTAMPTZ,
  processed_by VARCHAR(64)
);

-- Table: axiom_curator_patterns
CREATE TABLE IF NOT EXISTS axiom_curator_patterns (
  id SERIAL PRIMARY KEY,
  pattern_id VARCHAR(64) NOT NULL REFERENCES axiom_prompt_patterns(pattern_id),
  curator_user_id VARCHAR(64) NOT NULL,
  tenant_id VARCHAR(64) NOT NULL,
  validation_status VARCHAR(20) NOT NULL DEFAULT 'pending',
  validation_score DECIMAL(4,3),
  promoted_at TIMESTAMPTZ,
  weight_boost DECIMAL(3,2) DEFAULT 0.2,  -- Boost applied to pattern ranking
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: axiom_domain_flags
CREATE TABLE IF NOT EXISTS axiom_domain_flags (
  flag_id VARCHAR(64) PRIMARY KEY,
  domain_id VARCHAR(128) NOT NULL,
  tenant_id VARCHAR(64),
  flag_type VARCHAR(32) NOT NULL,  -- 'needs_patterns', 'low_confidence', 'high_skip_rate', 'curator_flagged'
  severity VARCHAR(20) NOT NULL DEFAULT 'medium',  -- 'low', 'medium', 'high', 'critical'
  description TEXT,
  auto_detected BOOLEAN NOT NULL DEFAULT true,
  flagged_by VARCHAR(64),
  resolved BOOLEAN NOT NULL DEFAULT false,
  resolved_by VARCHAR(64),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolved_at TIMESTAMPTZ
);

-- Table: axiom_domain_signatures
CREATE TABLE IF NOT EXISTS axiom_domain_signatures (
  domain_id VARCHAR(128) PRIMARY KEY,
  tenant_id VARCHAR(64),  -- NULL for global signatures
  domain_path JSONB NOT NULL,  -- ["legal", "contracts", "saas"]
  template JSONB NOT NULL,  -- { systemPrompt, userPromptPrefix, userPromptSuffix, slots }
  model_preferences JSONB NOT NULL DEFAULT '{}',
  version VARCHAR(16) NOT NULL DEFAULT '1.0.0',
  effectiveness_score DECIMAL(4,3) NOT NULL DEFAULT 0.500,
  usage_count INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by VARCHAR(64)
);

-- Table: axiom_key_chains
CREATE TABLE IF NOT EXISTS axiom_key_chains (
  chain_id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  user_id VARCHAR(64),
  user_type VARCHAR(20) NOT NULL DEFAULT 'anonymous',
  device_fingerprint VARCHAR(128),
  session_history JSONB NOT NULL DEFAULT '[]',
  learning_tier VARCHAR(20) NOT NULL DEFAULT 'user',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: axiom_model_variant_rules
CREATE TABLE IF NOT EXISTS axiom_model_variant_rules (
  model_id VARCHAR(64) PRIMARY KEY,
  prefers_structured BOOLEAN NOT NULL DEFAULT true,
  requires_explicit_format BOOLEAN NOT NULL DEFAULT false,
  max_context_tokens INTEGER NOT NULL DEFAULT 128000,
  temperature_default DECIMAL(3,2) NOT NULL DEFAULT 0.70,
  top_p_default DECIMAL(3,2) NOT NULL DEFAULT 1.00,
  system_prompt_style VARCHAR(20) NOT NULL DEFAULT 'structured',
  preferred_output_format VARCHAR(20),
  custom_rules JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: axiom_network_inference_log
CREATE TABLE IF NOT EXISTS axiom_network_inference_log (
    inference_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id VARCHAR(32) NOT NULL REFERENCES axiom_network_status(network_id),
    tenant_id UUID,
    session_id UUID,
    
    -- Input/Output
    input_features_hash VARCHAR(64),  -- SHA-256 of input for deduplication
    output_scores JSONB NOT NULL,
    
    -- Performance
    latency_ms INTEGER NOT NULL,
    used_fallback BOOLEAN NOT NULL DEFAULT false,
    model_version VARCHAR(32) NOT NULL,
    
    -- Feedback for training
    feedback_score DECIMAL(3,2),  -- 0-1, set after observing outcome
    feedback_at TIMESTAMP WITH TIME ZONE,
    
    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);

-- Table: axiom_network_status
CREATE TABLE IF NOT EXISTS axiom_network_status (
    network_id VARCHAR(32) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    description TEXT,
    thermal_state axiom_network_thermal_state NOT NULL DEFAULT 'cold',
    version VARCHAR(32) NOT NULL DEFAULT '1.0.0',
    sagemaker_endpoint VARCHAR(256),
    onnx_model_path VARCHAR(512),
    
    -- Network architecture
    parameters INTEGER NOT NULL DEFAULT 0,
    input_dim INTEGER NOT NULL,
    output_dim INTEGER NOT NULL,
    hidden_layers JSONB NOT NULL DEFAULT '[]',
    activation_function VARCHAR(32) NOT NULL DEFAULT 'gelu',
    
    -- Metrics
    requests_per_minute DECIMAL(10,2) NOT NULL DEFAULT 0,
    error_rate DECIMAL(5,4) NOT NULL DEFAULT 0,
    last_inference_ms INTEGER,
    avg_latency_ms DECIMAL(10,2),
    total_inferences BIGINT NOT NULL DEFAULT 0,
    
    -- Thermal management
    warmed_at TIMESTAMP WITH TIME ZONE,
    last_request_at TIMESTAMP WITH TIME ZONE,
    auto_cool_after_minutes INTEGER DEFAULT 30,
    
    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);

-- Table: axiom_network_training_batches
CREATE TABLE IF NOT EXISTS axiom_network_training_batches (
    batch_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id VARCHAR(32) NOT NULL REFERENCES axiom_network_status(network_id),
    
    -- Training parameters
    training_samples_count INTEGER NOT NULL,
    validation_samples_count INTEGER NOT NULL,
    epochs INTEGER NOT NULL DEFAULT 10,
    learning_rate DECIMAL(10,8) NOT NULL DEFAULT 0.001,
    
    -- Status
    status VARCHAR(32) NOT NULL DEFAULT 'pending',  -- pending, training, validating, deployed, failed
    sagemaker_training_job VARCHAR(256),
    
    -- Metrics
    training_loss DECIMAL(10,6),
    validation_loss DECIMAL(10,6),
    accuracy_before DECIMAL(5,4),
    accuracy_after DECIMAL(5,4),
    
    -- Timestamps
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);

-- Table: axiom_pattern_evolution
CREATE TABLE IF NOT EXISTS axiom_pattern_evolution (
  evolution_id VARCHAR(64) PRIMARY KEY,
  evolution_type cato_evolution_type NOT NULL,
  domain VARCHAR(128) NOT NULL,
  parent_patterns JSONB NOT NULL DEFAULT '[]',
  new_pattern_id VARCHAR(64) NOT NULL REFERENCES axiom_prompt_patterns(pattern_id),
  fitness_score DECIMAL(4,3) NOT NULL,
  invention_ratio DECIMAL(4,3) NOT NULL,
  cato_cycle_id VARCHAR(64),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: axiom_prompt_patterns
CREATE TABLE IF NOT EXISTS axiom_prompt_patterns (
  pattern_id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),  -- NULL for global patterns
  domain_id VARCHAR(128) NOT NULL,
  pattern_type axiom_pattern_type NOT NULL,
  content TEXT NOT NULL,
  embedding vector(1536),  -- pgvector for similarity search
  usage_count INTEGER NOT NULL DEFAULT 0,
  success_rate DECIMAL(4,3) NOT NULL DEFAULT 0.500,
  last_used TIMESTAMPTZ,
  origin axiom_pattern_origin NOT NULL DEFAULT 'human_curated',
  parent_patterns JSONB DEFAULT '[]',
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by VARCHAR(64)
);

-- Table: axiom_question_cache
CREATE TABLE IF NOT EXISTS axiom_question_cache (
  cache_id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  domain_id VARCHAR(128) NOT NULL,
  questions_json JSONB NOT NULL,
  question_count INTEGER NOT NULL,
  cache_version VARCHAR(16) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL,
  UNIQUE(tenant_id, domain_id)
);

-- Table: axiom_training_signals
CREATE TABLE IF NOT EXISTS axiom_training_signals (
  signal_id VARCHAR(64) PRIMARY KEY,
  session_id VARCHAR(64) NOT NULL REFERENCES clarion_sessions(session_id),
  tenant_id VARCHAR(64) NOT NULL,
  domain VARCHAR(128) NOT NULL,
  questions_asked JSONB NOT NULL,
  answers_given JSONB NOT NULL,
  compiled_prompt_hash VARCHAR(64) NOT NULL,
  model_used VARCHAR(64) NOT NULL,
  user_rating SMALLINT CHECK (user_rating >= 1 AND user_rating <= 5),
  outcome_quality DECIMAL(4,3),
  tokens_used INTEGER NOT NULL,
  latency_ms INTEGER NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  processed_at TIMESTAMPTZ,
  processed_by_cato BOOLEAN NOT NULL DEFAULT false
);

-- Table: axiom_user_feedback
CREATE TABLE IF NOT EXISTS axiom_user_feedback (
  feedback_id VARCHAR(64) PRIMARY KEY,
  session_id VARCHAR(64) NOT NULL,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  feedback_type VARCHAR(32) NOT NULL,  -- 'rating', 'thumbs', 'correction', 'skip_reason'
  target_type VARCHAR(32) NOT NULL,  -- 'session', 'question', 'model', 'prompt'
  target_id VARCHAR(128) NOT NULL,
  value JSONB NOT NULL,  -- { rating: 5 } or { thumbs: 'up' } or { correction: '...' }
  context JSONB,  -- Additional context at time of feedback
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: background_learning_config
CREATE TABLE IF NOT EXISTS background_learning_config (
    config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT true,
    throttle_level TEXT NOT NULL DEFAULT 'medium' CHECK (throttle_level IN ('off', 'minimal', 'low', 'medium', 'high', 'maximum')),
    max_hourly_cost_cents INTEGER NOT NULL DEFAULT 100,
    max_daily_cost_cents INTEGER NOT NULL DEFAULT 1000,
    max_monthly_cost_cents INTEGER NOT NULL DEFAULT 20000,
    batch_size INTEGER NOT NULL DEFAULT 50,
    priority_mode TEXT NOT NULL DEFAULT 'balanced',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: batch_write_staging
CREATE TABLE IF NOT EXISTS batch_write_staging (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    batch_id UUID NOT NULL,
    target_table VARCHAR(100) NOT NULL,
    payload JSONB NOT NULL,
    status VARCHAR(20) DEFAULT 'pending', -- pending, processing, completed, failed
    retry_count INTEGER DEFAULT 0,
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    processed_at TIMESTAMPTZ,
    
    PRIMARY KEY (id)
);

-- Table: behavior_markov_states
CREATE TABLE IF NOT EXISTS behavior_markov_states (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID,
    
    -- State definition
    state_type VARCHAR(100) NOT NULL, -- 'action_sequence', 'domain_transition', 'model_transition'
    from_state VARCHAR(255) NOT NULL,
    to_state VARCHAR(255) NOT NULL,
    
    -- Probabilities
    transition_count INTEGER DEFAULT 0,
    total_from_state_count INTEGER DEFAULT 0,
    probability DOUBLE PRECISION GENERATED ALWAYS AS (
        CASE WHEN total_from_state_count > 0 
        THEN transition_count::float / total_from_state_count 
        ELSE 0 END
    ) STORED,
    
    last_observed_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_markov_transition UNIQUE (tenant_id, user_id, state_type, from_state, to_state)
);

-- Table: benchmark_degradation_alerts
CREATE TABLE IF NOT EXISTS benchmark_degradation_alerts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Alert info
    model_id VARCHAR(255) NOT NULL,
    benchmark_name VARCHAR(100) NOT NULL,
    
    -- Scores
    previous_score DOUBLE PRECISION NOT NULL,
    current_score DOUBLE PRECISION NOT NULL,
    degradation_percent DOUBLE PRECISION NOT NULL,
    
    -- Status
    acknowledged BOOLEAN DEFAULT false,
    acknowledged_by UUID,
    acknowledged_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: bifurcation_points
CREATE TABLE IF NOT EXISTS bifurcation_points (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    oracle_view_id UUID NOT NULL REFERENCES oracle_views(id) ON DELETE CASCADE,
    position JSONB NOT NULL,
    trigger_event TEXT NOT NULL,
    probability NUMERIC(5,4) NOT NULL,
    branches JSONB NOT NULL DEFAULT '[]',
    animation JSONB DEFAULT '{"forkAngle": 30, "pulseIntensity": 0.5}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: billing_metrics
CREATE TABLE IF NOT EXISTS billing_metrics (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Time tracking
    period_date DATE NOT NULL,
    period_hour SMALLINT CHECK (period_hour >= 0 AND period_hour <= 23),
    
    -- Cost breakdown
    model_id VARCHAR(100),
    provider_id VARCHAR(50),
    input_tokens BIGINT DEFAULT 0,
    output_tokens BIGINT DEFAULT 0,
    total_tokens BIGINT DEFAULT 0,
    
    -- Costs in cents (to avoid floating point issues)
    input_cost_cents BIGINT DEFAULT 0,
    output_cost_cents BIGINT DEFAULT 0,
    total_cost_cents BIGINT DEFAULT 0,
    
    -- Storage costs
    storage_bytes_used BIGINT DEFAULT 0,
    storage_cost_cents BIGINT DEFAULT 0,
    
    -- Compute costs (self-hosted)
    compute_seconds BIGINT DEFAULT 0,
    compute_cost_cents BIGINT DEFAULT 0,
    
    -- API call counts
    api_calls INTEGER DEFAULT 0,
    successful_calls INTEGER DEFAULT 0,
    failed_calls INTEGER DEFAULT 0,
    
    -- Metadata
    breakdown JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, user_id, period_date, period_hour, model_id)
);

-- Table: billing_settings
CREATE TABLE IF NOT EXISTS billing_settings (
    tenant_id VARCHAR(100) PRIMARY KEY,
    margin_percent DECIMAL(5,2) NOT NULL DEFAULT 20.00,
    margin_type VARCHAR(20) NOT NULL DEFAULT 'fixed',
    tiers JSONB,
    tax_enabled BOOLEAN NOT NULL DEFAULT false,
    tax_percent DECIMAL(5,2) NOT NULL DEFAULT 0.00,
    tax_id VARCHAR(50),
    stripe_customer_id VARCHAR(100),
    default_payment_method_id VARCHAR(100),
    auto_pay BOOLEAN NOT NULL DEFAULT false,
    billing_cycle_day INTEGER NOT NULL DEFAULT 1,
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    budget_limit DECIMAL(12,2),
    alert_thresholds INTEGER[] NOT NULL DEFAULT '{50, 75, 90, 100}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT valid_margin_type CHECK (margin_type IN ('fixed', 'tiered')),
    CONSTRAINT valid_billing_day CHECK (billing_cycle_day BETWEEN 1 AND 28)
);

-- Table: bipolar_rating_aggregates
CREATE TABLE IF NOT EXISTS bipolar_rating_aggregates (
    aggregate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Aggregation period
    period_type VARCHAR(10) NOT NULL, -- 'day', 'week', 'month', 'all'
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    
    -- Optional filters (NULL = all)
    target_type VARCHAR(30),
    model_id VARCHAR(100),
    dimension VARCHAR(30),
    
    -- Core metrics
    total_ratings INTEGER NOT NULL DEFAULT 0,
    average_rating DECIMAL(4,2), -- -5.00 to +5.00
    
    -- Sentiment distribution
    negative_count INTEGER NOT NULL DEFAULT 0,
    neutral_count INTEGER NOT NULL DEFAULT 0,
    positive_count INTEGER NOT NULL DEFAULT 0,
    
    -- Net Sentiment Score: (positive% - negative%) * 100
    -- Ranges from -100 (all negative) to +100 (all positive)
    net_sentiment_score SMALLINT,
    
    -- Distribution by value (-5 to +5)
    rating_distribution JSONB DEFAULT '{}'::jsonb,
    
    -- Top reasons
    top_positive_reasons JSONB DEFAULT '[]'::jsonb,
    top_negative_reasons JSONB DEFAULT '[]'::jsonb,
    
    -- Trend
    trend VARCHAR(20), -- 'improving', 'stable', 'declining'
    trend_percentage DECIMAL(5,2),
    
    -- Timestamps
    computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_aggregate UNIQUE (tenant_id, period_type, period_start, target_type, model_id, dimension)
);

-- Table: bipolar_ratings
CREATE TABLE IF NOT EXISTS bipolar_ratings (
    rating_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    -- What is being rated
    target_type VARCHAR(30) NOT NULL, -- 'response', 'plan', 'conversation', 'model', 'feature'
    target_id UUID NOT NULL,
    
    -- The rating: -5 to +5
    value SMALLINT NOT NULL CHECK (value >= -5 AND value <= 5),
    dimension VARCHAR(30) NOT NULL DEFAULT 'overall',
    
    -- Derived fields (computed on insert)
    sentiment VARCHAR(10) NOT NULL, -- 'negative', 'neutral', 'positive'
    intensity VARCHAR(10) NOT NULL, -- 'extreme', 'strong', 'mild', 'neutral'
    
    -- Optional context
    reasons JSONB DEFAULT '[]'::jsonb,
    feedback TEXT,
    
    -- Metadata for analysis
    conversation_id UUID,
    session_id UUID,
    model_used VARCHAR(100),
    domain_detected VARCHAR(100),
    prompt_complexity VARCHAR(20),
    response_time_ms INTEGER,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ,
    
    -- Prevent duplicate ratings for same target/dimension by same user
    CONSTRAINT unique_user_rating UNIQUE (tenant_id, user_id, target_id, dimension)
);

-- Table: black_swan_indicators
CREATE TABLE IF NOT EXISTS black_swan_indicators (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    oracle_view_id UUID NOT NULL REFERENCES oracle_views(id) ON DELETE CASCADE,
    event TEXT NOT NULL,
    probability NUMERIC(7,6) NOT NULL, -- Very small probabilities
    impact INTEGER NOT NULL CHECK (impact >= 0 AND impact <= 100),
    position JSONB NOT NULL,
    visual_style JSONB DEFAULT '{"emberColor": "#ef4444", "dormantOpacity": 0.2, "activationThreshold": 0.1}',
    triggers JSONB DEFAULT '[]',
    mitigations JSONB DEFAULT '[]',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: blackboard_config
CREATE TABLE IF NOT EXISTS blackboard_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID UNIQUE REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Semantic matching
  similarity_threshold DECIMAL(5,4) DEFAULT 0.85, -- Minimum similarity for question matching
  embedding_model VARCHAR(100) DEFAULT 'text-embedding-ada-002',
  
  -- Question grouping
  enable_question_grouping BOOLEAN DEFAULT TRUE,
  grouping_window_seconds INTEGER DEFAULT 60, -- How long to wait for similar questions
  max_group_size INTEGER DEFAULT 10,
  
  -- Answer reuse
  enable_answer_reuse BOOLEAN DEFAULT TRUE,
  answer_ttl_seconds INTEGER DEFAULT 3600, -- How long answers are valid
  max_reuse_count INTEGER DEFAULT 100,
  
  -- Resource locking
  default_lock_timeout_seconds INTEGER DEFAULT 300,
  max_lock_wait_seconds INTEGER DEFAULT 60,
  enable_lock_queue BOOLEAN DEFAULT TRUE,
  
  -- Process hydration
  enable_auto_hydration BOOLEAN DEFAULT TRUE,
  hydration_threshold_seconds INTEGER DEFAULT 300, -- Hydrate after waiting this long
  max_hydration_size_mb INTEGER DEFAULT 50,
  hydration_s3_bucket VARCHAR(256),
  
  -- Cycle detection
  enable_cycle_detection BOOLEAN DEFAULT TRUE,
  max_dependency_depth INTEGER DEFAULT 10,
  cycle_check_interval_seconds INTEGER DEFAULT 30,
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: blackboard_events
CREATE TABLE IF NOT EXISTS blackboard_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Event type
  event_type VARCHAR(50) NOT NULL CHECK (event_type IN (
    'question_asked', 'question_matched', 'question_grouped',
    'answer_provided', 'answer_reused', 'answer_invalidated',
    'lock_acquired', 'lock_released', 'lock_denied', 'lock_timeout',
    'dependency_created', 'dependency_satisfied', 'cycle_detected',
    'agent_registered', 'agent_hydrated', 'agent_restored', 'agent_completed'
  )),
  
  -- Related entities
  agent_id UUID REFERENCES agent_registry(id),
  decision_id UUID REFERENCES resolved_decisions(id),
  group_id UUID REFERENCES question_groups(id),
  lock_id UUID REFERENCES resource_locks(id),
  dependency_id UUID REFERENCES agent_dependencies(id),
  
  -- Event details
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  
  -- Timestamp
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: brain_inference_log
CREATE TABLE IF NOT EXISTS brain_inference_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    session_id UUID,
    prompt_hash VARCHAR(64),
    system_level VARCHAR(20) NOT NULL,
    ghost_loaded BOOLEAN DEFAULT false,
    ghost_updated BOOLEAN DEFAULT false,
    flash_facts_count INTEGER DEFAULT 0,
    memories_count INTEGER DEFAULT 0,
    context_tokens INTEGER,
    response_tokens INTEGER,
    total_tokens INTEGER,
    latency_ms INTEGER,
    model_used VARCHAR(100),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: brain_regions
CREATE TABLE IF NOT EXISTS brain_regions (
    region_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Region identity
    name VARCHAR(100) NOT NULL,
    slug VARCHAR(50) NOT NULL,
    description TEXT,
    icon VARCHAR(50) DEFAULT 'brain',
    color VARCHAR(7) DEFAULT '#6366f1',
    
    -- Cognitive function mapping
    cognitive_function VARCHAR(100) NOT NULL, -- e.g., 'reasoning', 'memory', 'language_production'
    human_brain_analog VARCHAR(100), -- e.g., 'prefrontal_cortex', 'hippocampus'
    
    -- Model assignments (ordered by preference)
    primary_model_id VARCHAR(100) NOT NULL,
    fallback_model_ids TEXT[] DEFAULT '{}',
    
    -- Routing configuration
    activation_triggers JSONB DEFAULT '[]', -- conditions that activate this region
    input_transformers JSONB DEFAULT '[]', -- pre-processing steps
    output_transformers JSONB DEFAULT '[]', -- post-processing steps
    
    -- Performance tuning
    priority INTEGER DEFAULT 50, -- 1-100, higher = more important
    max_latency_ms INTEGER DEFAULT 5000,
    timeout_ms INTEGER DEFAULT 30000,
    retry_count INTEGER DEFAULT 2,
    
    -- Cost controls
    max_tokens_per_call INTEGER DEFAULT 4096,
    cost_multiplier DECIMAL(5,2) DEFAULT 1.00,
    
    -- Learning parameters
    learning_rate DECIMAL(5,4) DEFAULT 0.01,
    adaptation_enabled BOOLEAN DEFAULT true,
    
    -- Status
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false, -- system regions can't be deleted
    
    -- Metrics
    total_activations BIGINT DEFAULT 0,
    successful_activations BIGINT DEFAULT 0,
    avg_latency_ms DECIMAL(10,2) DEFAULT 0,
    avg_satisfaction_score DECIMAL(3,2) DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, slug)
);

-- Table: brain_routing_history
CREATE TABLE IF NOT EXISTS brain_routing_history (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    request_id VARCHAR(100),
    task_type VARCHAR(50),
    input_tokens INTEGER,
    output_tokens INTEGER,
    selected_model VARCHAR(100) NOT NULL,
    selection_reason TEXT,
    latency_ms INTEGER,
    cost DECIMAL(10, 6),
    success BOOLEAN DEFAULT true,
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: brain_routing_rules
CREATE TABLE IF NOT EXISTS brain_routing_rules (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    priority INTEGER NOT NULL DEFAULT 100,
    conditions JSONB NOT NULL DEFAULT '{}',
    target_model VARCHAR(100) NOT NULL,
    fallback_models TEXT[] DEFAULT '{}',
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: branch_merge_requests
CREATE TABLE IF NOT EXISTS branch_merge_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    source_branch_id UUID NOT NULL REFERENCES conversation_branches(id) ON DELETE CASCADE,
    target_branch_id UUID NOT NULL REFERENCES conversation_branches(id) ON DELETE CASCADE,
    
    -- Merge request details
    title VARCHAR(255) NOT NULL,
    description TEXT,
    key_insights JSONB DEFAULT '[]',
    
    -- Review
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'merged')),
    reviewers UUID[] DEFAULT '{}',
    approvals UUID[] DEFAULT '{}',
    
    -- AI-generated merge summary
    ai_merge_summary TEXT,
    ai_conflict_analysis TEXT,
    
    created_by UUID NOT NULL REFERENCES session_participants(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: brand_kits
CREATE TABLE IF NOT EXISTS brand_kits (
