-- Table: break_glass_access_log
CREATE TABLE IF NOT EXISTS break_glass_access_log (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  
  -- Who accessed
  admin_user_id UUID NOT NULL REFERENCES administrators(id),
  admin_email VARCHAR(255) NOT NULL,
  admin_ip_address INET,
  admin_user_agent TEXT,
  
  -- What was accessed
  tenant_id UUID NOT NULL REFERENCES tenants(id),
  accessed_resources TEXT[] NOT NULL,
  access_reason TEXT NOT NULL,
  access_justification TEXT,
  
  -- Incident tracking
  incident_ticket VARCHAR(100),
  approved_by VARCHAR(255),
  approval_timestamp TIMESTAMPTZ,
  
  -- Timing
  access_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  access_ended_at TIMESTAMPTZ,
  
  -- Actions taken
  actions_performed JSONB DEFAULT '[]',
  data_exported BOOLEAN DEFAULT false,
  data_modified BOOLEAN DEFAULT false,
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: butlin_consciousness_tests
CREATE TABLE IF NOT EXISTS butlin_consciousness_tests (
    suite_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    results JSONB NOT NULL,
    overall_score FLOAT NOT NULL,
    indicators_passed INT NOT NULL,
    indicators_total INT NOT NULL,
    consciousness_level TEXT NOT NULL,
    phi_score FLOAT,
    pci_score FLOAT,
    recommendations JSONB DEFAULT '[]',
    run_at TIMESTAMPTZ NOT NULL
);

-- Table: calibration_curves
CREATE TABLE IF NOT EXISTS calibration_curves (
    curve_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Scope
    domain VARCHAR(100) NOT NULL,
    task_type VARCHAR(100),
    model_id VARCHAR(200),
    
    -- Curve data
    buckets JSONB NOT NULL, -- [{confidence_range, accuracy, count}]
    
    -- Metrics
    expected_calibration_error DECIMAL(5,4),
    max_calibration_error DECIMAL(5,4),
    brier_score DECIMAL(5,4),
    
    -- Bias
    overconfidence_rate DECIMAL(5,4), -- How often too confident
    underconfidence_rate DECIMAL(5,4), -- How often too cautious
    
    -- Recommendations
    adjustment_function JSONB, -- How to adjust raw confidence
    
    sample_count INTEGER DEFAULT 0,
    last_updated TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, domain, task_type, model_id)
);

-- Table: calibration_history
CREATE TABLE IF NOT EXISTS calibration_history (
    calibration_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Time period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    
    -- Calibration metrics
    total_predictions INTEGER DEFAULT 0,
    predictions_with_feedback INTEGER DEFAULT 0,
    
    -- By confidence bucket
    bucket_0_20 JSONB DEFAULT '{"predicted": 0, "actual": 0}',
    bucket_20_40 JSONB DEFAULT '{"predicted": 0, "actual": 0}',
    bucket_40_60 JSONB DEFAULT '{"predicted": 0, "actual": 0}',
    bucket_60_80 JSONB DEFAULT '{"predicted": 0, "actual": 0}',
    bucket_80_100 JSONB DEFAULT '{"predicted": 0, "actual": 0}',
    
    -- Overall calibration score (lower = better calibrated)
    calibration_score DECIMAL(5,4), -- Brier score or similar
    overconfidence_tendency DECIMAL(5,4), -- Positive = overconfident
    underconfidence_tendency DECIMAL(5,4), -- Positive = underconfident
    
    -- By domain/task type
    calibration_by_domain JSONB DEFAULT '{}',
    calibration_by_task_type JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: canvases
CREATE TABLE IF NOT EXISTS canvases (
