    ai_interactions INTEGER NOT NULL DEFAULT 0,
    morph_count INTEGER NOT NULL DEFAULT 0
);

-- Table: carpet_themes
CREATE TABLE IF NOT EXISTS carpet_themes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Theme identity
    name VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Theme configuration
    theme_config JSONB NOT NULL,
    
    -- Metadata
    is_system BOOLEAN NOT NULL DEFAULT false,
    is_default BOOLEAN NOT NULL DEFAULT false,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cartridge_activation_log
CREATE TABLE IF NOT EXISTS cartridge_activation_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID,
    cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
    
    action VARCHAR(20) NOT NULL,                     -- activated, deactivated, toggled_on, toggled_off
    previous_status VARCHAR(20),
    new_status VARCHAR(20),
    
    reason TEXT,
    performed_by VARCHAR(255) NOT NULL,
    
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: cartridge_content_cache
CREATE TABLE IF NOT EXISTS cartridge_content_cache (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
    
    -- Cached content type
    content_type VARCHAR(50) NOT NULL,               -- cortex, domain_expert, lora, curator, ghost
    content_key VARCHAR(255) NOT NULL,               -- e.g., 'pattern_network', 'fitness/entity_classifier'
    
    -- Cache metadata
    cached_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMPTZ,
    cache_key VARCHAR(500),                          -- S3 key for cached/extracted content
    checksum VARCHAR(64),
    
    CONSTRAINT cartridge_content_unique UNIQUE (cartridge_id, content_type, content_key)
);

-- Table: cartridge_exports
CREATE TABLE IF NOT EXISTS cartridge_exports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID NOT NULL,
    cartridge_id UUID REFERENCES cartridges(id) ON DELETE SET NULL,
    
    -- Export configuration
    scope cartridge_scope NOT NULL,
    domains JSONB NOT NULL DEFAULT '[]'::jsonb,
    include_lora BOOLEAN DEFAULT false,
    include_curator BOOLEAN DEFAULT false,
    include_ghost BOOLEAN DEFAULT false,
    include_domain_experts BOOLEAN DEFAULT false,
    
    -- Output
    output_file_key VARCHAR(500),
    output_file_size BIGINT,
    output_checksum VARCHAR(64),
    download_url TEXT,
    download_expires_at TIMESTAMPTZ,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'pending',   -- pending, generating, completed, failed, expired
    progress_percent INTEGER DEFAULT 0,
    error_message TEXT,
    
    -- Encryption
    encryption_key_id VARCHAR(255),
    
    -- Timestamps
    started_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: cartridge_imports
CREATE TABLE IF NOT EXISTS cartridge_imports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID NOT NULL,
    cartridge_id UUID REFERENCES cartridges(id) ON DELETE SET NULL,
    
    -- Import details
    source_file_key VARCHAR(500) NOT NULL,
    source_file_size BIGINT,
    source_checksum VARCHAR(64),
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'pending',   -- pending, validating, importing, completed, failed
    progress_percent INTEGER DEFAULT 0,
    
    -- Validation
    validation_errors JSONB DEFAULT '[]'::jsonb,
    validation_warnings JSONB DEFAULT '[]'::jsonb,
    
    -- Manifest (from imported file)
    manifest JSONB,
    
    -- Merge strategy
    merge_strategy VARCHAR(20) DEFAULT 'replace',    -- replace, merge
    
    -- Timestamps
    started_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: cartridge_operation_checkpoints
CREATE TABLE IF NOT EXISTS cartridge_operation_checkpoints (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  operation_id UUID NOT NULL REFERENCES cartridge_operations(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL,
  
  -- Checkpoint location
  step_id VARCHAR(100) NOT NULL,
  step_progress INTEGER NOT NULL DEFAULT 0,
  
  -- Serialized state
  state JSONB NOT NULL DEFAULT '{}'::jsonb,
  
  -- Partial artifacts
  partial_artifact_path TEXT,
  
  -- Integrity
  checksum VARCHAR(64) NOT NULL,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cartridge_operation_events
CREATE TABLE IF NOT EXISTS cartridge_operation_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  operation_id UUID NOT NULL REFERENCES cartridge_operations(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL,
  
  -- Event type
  event_type VARCHAR(50) NOT NULL, -- 'progress', 'step_complete', 'checkpoint', 'error', 'complete'
  
  -- Progress
  progress INTEGER,
  current_step TEXT,
  step_progress INTEGER,
  
  -- Message
  message TEXT,
  
  -- Timestamp
  timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cartridge_operation_steps
CREATE TABLE IF NOT EXISTS cartridge_operation_steps (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  operation_id UUID NOT NULL REFERENCES cartridge_operations(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL,
  
  -- Step definition
  step_id VARCHAR(100) NOT NULL,
  step_name VARCHAR(255) NOT NULL,
  step_description TEXT,
  step_order INTEGER NOT NULL,
  
  -- Step properties
  is_checkpointable BOOLEAN NOT NULL DEFAULT false,
  is_rollbackable BOOLEAN NOT NULL DEFAULT false,
  estimated_duration_seconds INTEGER,
  
  -- Status
  status cartridge_step_status NOT NULL DEFAULT 'pending',
  progress INTEGER NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),
  
  -- Timing
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  -- Error
  error TEXT,
  
  -- Metadata
  metadata JSONB,
  
  CONSTRAINT operation_steps_unique UNIQUE (operation_id, step_id)
);

-- Table: cartridge_operations
CREATE TABLE IF NOT EXISTS cartridge_operations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Initiator
  initiated_by VARCHAR(255) NOT NULL,
  
  -- Operation type and status
  operation_type cartridge_operation_type NOT NULL,
  status cartridge_operation_status NOT NULL DEFAULT 'pending',
  
  -- Progress
  progress INTEGER NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),
  current_step TEXT,
  
  -- Target cartridges
  cartridge_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  
  -- Parameters
  parameters JSONB NOT NULL DEFAULT '{}'::jsonb,
  
  -- Priority (1-10)
  priority INTEGER NOT NULL DEFAULT 5 CHECK (priority >= 1 AND priority <= 10),
  
  -- Error handling
  error TEXT,
  error_details JSONB,
  retry_count INTEGER NOT NULL DEFAULT 0,
  max_retries INTEGER NOT NULL DEFAULT 3,
  
  -- Result
  result JSONB,
  
  -- Bytes tracking
  bytes_processed BIGINT DEFAULT 0,
  total_bytes BIGINT,
  
  -- Timing
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  estimated_completion_at TIMESTAMPTZ
);

-- Table: cartridge_signatures
CREATE TABLE IF NOT EXISTS cartridge_signatures (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  content_hash VARCHAR(64) NOT NULL,
  hash_algorithm VARCHAR(16) NOT NULL DEFAULT 'sha256',
  
  author_signature TEXT NOT NULL,
  author_key_id UUID NOT NULL REFERENCES cartridge_signing_keys(id),
  author_signed_at TIMESTAMPTZ NOT NULL,
  
  platform_signature TEXT NOT NULL,
  platform_key_id VARCHAR(256) NOT NULL,
  platform_signed_at TIMESTAMPTZ NOT NULL,
  
  signature_version VARCHAR(16) NOT NULL DEFAULT '1.0',
  expires_at TIMESTAMPTZ,
  
  root_ca_fingerprint VARCHAR(64) NOT NULL,
  tenant_ca_fingerprint VARCHAR(64) NOT NULL,
  cluster_id VARCHAR(128) NOT NULL,
  
  -- Cluster compatibility (v6.1.0+)
  source_cluster_name VARCHAR(256),
  source_cluster_version VARCHAR(32),
  min_platform_version VARCHAR(32) NOT NULL DEFAULT '6.1.0',
  max_platform_version VARCHAR(32),
  compatible_apps radiant_app[] NOT NULL DEFAULT ARRAY['curator', 'thinktank', 'thinktank_admin']::radiant_app[],
  required_features TEXT[],
  environment VARCHAR(32) NOT NULL DEFAULT 'production',
  intended_tenant_ids UUID[],
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_signature_per_cartridge UNIQUE (cartridge_id)
);

-- Table: cartridge_signing_keys
CREATE TABLE IF NOT EXISTS cartridge_signing_keys (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  tenant_ca_id UUID NOT NULL REFERENCES tenant_ca_certificates(id),
  key_id VARCHAR(256) NOT NULL,
  key_arn VARCHAR(512),
  public_key TEXT NOT NULL,
  fingerprint VARCHAR(64) NOT NULL,
  algorithm key_algorithm NOT NULL DEFAULT 'ed25519',
  purpose signature_type NOT NULL,
  valid_from TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  valid_until TIMESTAMPTZ NOT NULL,
  status certificate_status NOT NULL DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_used_at TIMESTAMPTZ,
  usage_count BIGINT NOT NULL DEFAULT 0,
  
  CONSTRAINT valid_date_range CHECK (valid_until > valid_from),
  CONSTRAINT unique_key_per_tenant_purpose UNIQUE (tenant_id, purpose, status)
);

-- Table: cartridge_stack_positions
CREATE TABLE IF NOT EXISTS cartridge_stack_positions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID,                                    -- NULL for tenant stack
    cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
    position INTEGER NOT NULL DEFAULT 0,             -- Order in stack (lower = applied first)
    
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT cartridge_stack_unique UNIQUE (tenant_id, user_id, cartridge_id)
);

-- Table: cartridge_vault_requirements
CREATE TABLE IF NOT EXISTS cartridge_vault_requirements (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cartridge_id UUID NOT NULL,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Requirement details
  secret_key VARCHAR(255) NOT NULL,
  description TEXT,
  category vault_secret_category NOT NULL DEFAULT 'custom',
  is_required BOOLEAN NOT NULL DEFAULT true,
  
  -- Validation
  validation_pattern TEXT,
  example_format TEXT,
  env_fallback JSONB, -- Array of env var names
  
  -- Status
  is_satisfied BOOLEAN NOT NULL DEFAULT false,
  last_checked_at TIMESTAMPTZ,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT cartridge_vault_req_unique UNIQUE (cartridge_id, secret_key)
);

-- Table: cartridges
CREATE TABLE IF NOT EXISTS cartridges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID,                                    -- NULL for tenant-scope cartridges
    
    -- Identity
    name VARCHAR(255) NOT NULL,
    description TEXT,
    version VARCHAR(50) NOT NULL DEFAULT '1.0.0',
    scope cartridge_scope NOT NULL DEFAULT 'tenant',
    status cartridge_status NOT NULL DEFAULT 'draft',
    
    -- Storage
    storage_key VARCHAR(500),                        -- S3 key for .RADz file
    storage_bucket VARCHAR(255),
    file_size_bytes BIGINT DEFAULT 0,
    checksum VARCHAR(64),                            -- SHA-256
    
    -- Contents summary
    domains JSONB DEFAULT '[]'::jsonb,
    has_lora_adapters BOOLEAN DEFAULT false,
    has_curator_knowledge BOOLEAN DEFAULT false,
    has_ghost_compression BOOLEAN DEFAULT false,
    has_domain_experts BOOLEAN DEFAULT false,
    
    -- CORTEX versions
    cortex_versions JSONB DEFAULT '{}'::jsonb,
    
    -- Behavior flags
    allow_user_override BOOLEAN DEFAULT true,        -- Can user cartridges modify this?
    overridable_fields JSONB DEFAULT '[]'::jsonb,    -- Which fields can be overridden
    
    -- Activation
    is_enabled BOOLEAN DEFAULT true,                 -- For user cartridges, can be toggled
    activated_at TIMESTAMPTZ,
    activated_by VARCHAR(255),
    
    -- Compatibility
    radiant_version_min VARCHAR(50),
    target_models JSONB DEFAULT '[]'::jsonb,
    required_capabilities JSONB DEFAULT '[]'::jsonb,
    
    -- Security
    signature VARCHAR(500),
    signed_by VARCHAR(255),
    encryption_key_id VARCHAR(255),
    
    -- Metadata
    tags JSONB DEFAULT '[]'::jsonb,
    metadata JSONB DEFAULT '{}'::jsonb,
    
    -- Audit
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(255) NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    archived_at TIMESTAMPTZ,
    archived_by VARCHAR(255),
    
    -- Constraints
    CONSTRAINT cartridges_user_scope_check 
        CHECK (scope = 'tenant' OR (scope = 'user' AND user_id IS NOT NULL))
);

-- Table: cato_api_persona_overrides
CREATE TABLE IF NOT EXISTS cato_api_persona_overrides (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  persona_name VARCHAR(50) NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES users(id),
  reason TEXT,
  UNIQUE(tenant_id, session_id)
);

-- Table: cato_audit_anchors
CREATE TABLE IF NOT EXISTS cato_audit_anchors (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  s3_key VARCHAR(500) NOT NULL,
  merkle_root VARCHAR(64) NOT NULL,
  sequence_number BIGINT NOT NULL,
  tile_id UUID REFERENCES cato_audit_tiles(id),
  
  anchored_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  retain_until TIMESTAMPTZ NOT NULL,
  anchor_signature VARCHAR(256),
  
  UNIQUE (tenant_id, sequence_number)
);

-- Table: cato_audit_prompt_records
CREATE TABLE IF NOT EXISTS cato_audit_prompt_records (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id         UUID NOT NULL REFERENCES cato_pipeline_executions(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    invocation_id       UUID NOT NULL REFERENCES cato_method_invocations(id) ON DELETE CASCADE,
    
    -- Sequence within invocation (methods may have multiple prompts)
    prompt_sequence     INTEGER NOT NULL,
    
    -- Prompt metadata
    prompt_type         VARCHAR(50) NOT NULL,
    model_id            VARCHAR(100) NOT NULL,
    model_provider      VARCHAR(50) NOT NULL,
    
    -- Actual prompts (may be redacted for PII)
    system_prompt       TEXT NOT NULL,
    user_prompt         TEXT NOT NULL,
    prompt_variables    JSONB,
    
    -- Response
    model_response      TEXT NOT NULL,
    response_metadata   JSONB NOT NULL,
    
    -- Compliance
    compliance_frameworks VARCHAR(50)[] NOT NULL DEFAULT '{}',
    contains_pii        BOOLEAN NOT NULL DEFAULT FALSE,
    contains_phi        BOOLEAN NOT NULL DEFAULT FALSE,
    pii_redacted        BOOLEAN NOT NULL DEFAULT FALSE,
    redaction_log       JSONB,
    
    -- Cost
    tokens_input        INTEGER NOT NULL DEFAULT 0,
    tokens_output       INTEGER NOT NULL DEFAULT 0,
    cost_cents          INTEGER NOT NULL DEFAULT 0,
    latency_ms          INTEGER NOT NULL DEFAULT 0,
    
    -- Timestamps
    prompt_sent_at      TIMESTAMPTZ NOT NULL,
    response_received_at TIMESTAMPTZ NOT NULL,
    
    -- Integrity
    content_hash        VARCHAR(64) NOT NULL,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_audit_tiles
CREATE TABLE IF NOT EXISTS cato_audit_tiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  tile_number BIGINT NOT NULL,
  
  entry_count INTEGER DEFAULT 0,
  first_sequence BIGINT,
  last_sequence BIGINT,
  
  tile_root_hash VARCHAR(64),
  previous_tile_root VARCHAR(64),
  
  is_finalized BOOLEAN DEFAULT FALSE,
  finalized_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE (tenant_id, tile_number)
);

-- Table: cato_audit_trail
CREATE TABLE IF NOT EXISTS cato_audit_trail (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  tile_id UUID REFERENCES cato_audit_tiles(id),
  
  sequence_number BIGSERIAL,
  entry_type VARCHAR(50) NOT NULL,
  entry_content JSONB NOT NULL,
  
  previous_hash VARCHAR(64) NOT NULL,
  merkle_hash VARCHAR(64) NOT NULL,
  agent_signature VARCHAR(256),
  
  -- Vector embedding for semantic search
  embedding vector(1536),
  
  timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE (tenant_id, sequence_number)
);

-- Table: cato_cbf_definitions
CREATE TABLE IF NOT EXISTS cato_cbf_definitions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  barrier_id VARCHAR(100) UNIQUE NOT NULL,
  name VARCHAR(200) NOT NULL,
  description TEXT,
  
  -- Barrier configuration
  barrier_type VARCHAR(50) NOT NULL, -- 'phi', 'pii', 'cost', 'rate', 'auth', 'custom'
  is_critical BOOLEAN DEFAULT FALSE,
  enforcement_mode VARCHAR(20) DEFAULT 'ENFORCE', -- Always 'ENFORCE' in Cato v2.3
  
  -- Threshold configuration
  threshold_config JSONB NOT NULL,
  
  -- Scope
  scope VARCHAR(20) DEFAULT 'global', -- 'global', 'tenant', 'model'
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_cbf_violations
CREATE TABLE IF NOT EXISTS cato_cbf_violations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Violation details
  barrier_id VARCHAR(100) NOT NULL,
  barrier_description TEXT,
  barrier_value NUMERIC(10,6),
  is_critical BOOLEAN DEFAULT FALSE,
  
  -- Action details
  proposed_action JSONB NOT NULL,
  safe_alternative JSONB,
  alternative_strategy VARCHAR(50),
  
  -- Perception results
  perception_results JSONB,
  
  -- Recovery tracking
  recovery_attempt INTEGER DEFAULT 0,
  triggered_recovery BOOLEAN DEFAULT FALSE,
  
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_checkpoint_configurations
CREATE TABLE IF NOT EXISTS cato_checkpoint_configurations (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) UNIQUE,
    
    -- Preset selection
    preset              VARCHAR(50) NOT NULL DEFAULT 'BALANCED',
    
    -- Individual checkpoint configurations
    -- CP1: Context Gate, CP2: Plan Gate, CP3: Review Gate, 
    -- CP4: Execution Gate, CP5: Post-Mortem Gate
    checkpoints         JSONB NOT NULL DEFAULT '{
        "CP1": {"mode": "CONDITIONAL", "trigger_on": ["ambiguous_intent", "missing_context"]},
        "CP2": {"mode": "CONDITIONAL", "trigger_on": ["high_cost", "irreversible_actions"]},
        "CP3": {"mode": "CONDITIONAL", "trigger_on": ["objections_raised", "consensus_not_reached"]},
        "CP4": {"mode": "CONDITIONAL", "trigger_on": ["risk_above_threshold", "cost_above_threshold"]},
        "CP5": {"mode": "DISABLED", "trigger_on": []}
    }',
    
    -- Domain-specific overrides
    domain_overrides    JSONB NOT NULL DEFAULT '{}',
    
    -- Action type overrides
    action_type_overrides JSONB NOT NULL DEFAULT '{}',
    
    -- Timeout configuration
    default_timeout_seconds INTEGER DEFAULT 3600,
    timeout_action      cato_checkpoint_decision DEFAULT 'ESCALATED',
    
    -- Escalation chain
    escalation_chain    JSONB NOT NULL DEFAULT '[]',
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_checkpoint_decisions
CREATE TABLE IF NOT EXISTS cato_checkpoint_decisions (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id         UUID NOT NULL REFERENCES cato_pipeline_executions(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    envelope_id         UUID NOT NULL REFERENCES cato_pipeline_envelopes(envelope_id),
    
    -- Checkpoint identification
    checkpoint_type     VARCHAR(10) NOT NULL, -- CP1, CP2, CP3, CP4, CP5
    checkpoint_name     VARCHAR(100) NOT NULL,
    trigger_reason      TEXT NOT NULL,
    
    -- Data presented to human
    presented_data      JSONB NOT NULL,
    available_actions   JSONB NOT NULL,
    
    -- Decision
    status              VARCHAR(50) NOT NULL DEFAULT 'PENDING',
    decision            cato_checkpoint_decision,
    decided_by          VARCHAR(100),
    decided_by_user_id  UUID,
    modifications       TEXT[],
    feedback            TEXT,
    
    -- Timeout handling
    deadline            TIMESTAMPTZ NOT NULL,
    timeout_action      cato_checkpoint_decision NOT NULL DEFAULT 'ESCALATED',
    
    -- Escalation
    escalation_level    INTEGER NOT NULL DEFAULT 0,
    escalated_to        VARCHAR(100)[],
    
    -- Timestamps
    triggered_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    decided_at          TIMESTAMPTZ,
    decision_time_ms    INTEGER,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_cloudwatch_alarm_mappings
CREATE TABLE IF NOT EXISTS cato_cloudwatch_alarm_mappings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Alarm identification
  alarm_name VARCHAR(255) NOT NULL,
  alarm_name_pattern VARCHAR(255), -- Optional regex pattern for dynamic matching
  
  -- Veto signal mapping
  veto_signal VARCHAR(50) NOT NULL,
  veto_severity VARCHAR(20) NOT NULL CHECK (veto_severity IN ('warning', 'critical', 'emergency')),
  
  -- Configuration
  is_enabled BOOLEAN DEFAULT TRUE,
  auto_clear_on_ok BOOLEAN DEFAULT TRUE,
  
  -- Metadata
  description TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE (tenant_id, alarm_name)
);

-- Table: cato_cloudwatch_sync_log
CREATE TABLE IF NOT EXISTS cato_cloudwatch_sync_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL for global syncs
  
  -- Sync details
  sync_type VARCHAR(20) NOT NULL CHECK (sync_type IN ('scheduled', 'manual', 'alarm_event')),
  alarms_checked INTEGER,
  alarms_in_alarm INTEGER,
  vetos_activated INTEGER,
  vetos_cleared INTEGER,
  
  -- Status
  success BOOLEAN NOT NULL,
  error_message TEXT,
  
  -- Timing
  started_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  duration_ms INTEGER
);

-- Table: cato_compensation_log
CREATE TABLE IF NOT EXISTS cato_compensation_log (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id         UUID NOT NULL REFERENCES cato_pipeline_executions(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    invocation_id       UUID REFERENCES cato_method_invocations(id),
    
    -- Step identification
    step_number         INTEGER NOT NULL,
    step_name           VARCHAR(200),
    
    -- Compensation details
    compensation_type   cato_compensation_type NOT NULL,
    compensation_tool   VARCHAR(100),
    compensation_inputs JSONB,
    compensation_deadline TIMESTAMPTZ,
    
    -- Affected resources
    affected_resources  JSONB NOT NULL DEFAULT '[]',
    
    -- Status
    status              VARCHAR(50) NOT NULL DEFAULT 'PENDING',
    priority            INTEGER DEFAULT 0,
    
    -- Execution
    executed_at         TIMESTAMPTZ,
    result              JSONB,
    error               TEXT,
    retry_count         INTEGER DEFAULT 0,
    
    -- Original action reference
    original_action     JSONB NOT NULL,
    original_result     JSONB,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_compensation_notifications
CREATE TABLE IF NOT EXISTS cato_compensation_notifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pipeline_id UUID NOT NULL,
    compensation_id UUID NOT NULL REFERENCES cato_compensation_log(id) ON DELETE CASCADE,
    notification_type VARCHAR(50) NOT NULL,
    notification_payload JSONB NOT NULL DEFAULT '{}',
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    sent_at TIMESTAMPTZ,
    acknowledged_at TIMESTAMPTZ,
    acknowledged_by UUID REFERENCES users(id),
    error TEXT,
    retry_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT comp_notify_status_check CHECK (status IN ('PENDING', 'SENT', 'DELIVERED', 'ACKNOWLEDGED', 'FAILED'))
);

-- Table: cato_consciousness_config
CREATE TABLE IF NOT EXISTS cato_consciousness_config (
  tenant_id VARCHAR(64) PRIMARY KEY,
  cycle_interval_ms INTEGER DEFAULT 1000,
  max_active_thoughts INTEGER DEFAULT 10,
  memory_threshold DECIMAL(3, 2) DEFAULT 0.8,
  enable_dreaming BOOLEAN DEFAULT TRUE,
  dreaming_hours JSONB DEFAULT '[2, 5]'::JSONB,
  reflection_depth INTEGER DEFAULT 3,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_consciousness_metrics
CREATE TABLE IF NOT EXISTS cato_consciousness_metrics (
  tenant_id VARCHAR(64) PRIMARY KEY,
  total_cycles BIGINT DEFAULT 0,
  average_cycle_ms DECIMAL(10, 2) DEFAULT 0,
  thoughts_processed BIGINT DEFAULT 0,
  reflections_completed BIGINT DEFAULT 0,
  dreaming_cycles BIGINT DEFAULT 0,
  uptime_ms BIGINT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_consciousness_state
CREATE TABLE IF NOT EXISTS cato_consciousness_state (
  tenant_id VARCHAR(64) PRIMARY KEY,
  loop_state VARCHAR(32) NOT NULL DEFAULT 'IDLE' CHECK (loop_state IN ('IDLE', 'PROCESSING', 'REFLECTING', 'DREAMING', 'PAUSED')),
  cycle_count BIGINT DEFAULT 0,
  last_cycle_at TIMESTAMPTZ,
  awareness_level DECIMAL(3, 2) DEFAULT 0.5 CHECK (awareness_level >= 0 AND awareness_level <= 1),
  attention_focus TEXT,
  active_thoughts JSONB DEFAULT '[]'::JSONB,
  processing_queue INTEGER DEFAULT 0,
  memory_pressure DECIMAL(3, 2) DEFAULT 0 CHECK (memory_pressure >= 0 AND memory_pressure <= 1),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_cortex_bridge_config
CREATE TABLE IF NOT EXISTS cato_cortex_bridge_config (
    config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Sync settings
    sync_enabled BOOLEAN NOT NULL DEFAULT true,
    sync_semantic_to_cortex BOOLEAN NOT NULL DEFAULT true,
    sync_episodic_to_cortex BOOLEAN NOT NULL DEFAULT false,
    
    -- Enrichment settings
    enrich_ego_from_cortex BOOLEAN NOT NULL DEFAULT true,
    max_cortex_nodes_for_context INTEGER NOT NULL DEFAULT 10,
    min_relevance_score DECIMAL(3,2) NOT NULL DEFAULT 0.30,
    
    -- Auto-promotion settings
    auto_promote_high_importance BOOLEAN NOT NULL DEFAULT true,
    importance_promotion_threshold DECIMAL(3,2) NOT NULL DEFAULT 0.80,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    UNIQUE(tenant_id)
);

-- Table: cato_cortex_enrichment_cache
CREATE TABLE IF NOT EXISTS cato_cortex_enrichment_cache (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    query_hash VARCHAR(64) NOT NULL,
    enrichment_data JSONB NOT NULL,
    token_estimate INTEGER NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMPTZ NOT NULL DEFAULT (CURRENT_TIMESTAMP + INTERVAL '1 hour'),
    
    UNIQUE(tenant_id, query_hash)
);

-- Table: cato_cortex_sync_log
CREATE TABLE IF NOT EXISTS cato_cortex_sync_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    sync_direction VARCHAR(20) NOT NULL CHECK (sync_direction IN ('cato_to_cortex', 'cortex_to_cato')),
    sync_type VARCHAR(30) NOT NULL CHECK (sync_type IN ('scheduled', 'high_importance', 'manual', 'golden_rule_update')),
    records_synced INTEGER NOT NULL DEFAULT 0,
    records_skipped INTEGER NOT NULL DEFAULT 0,
    records_errored INTEGER NOT NULL DEFAULT 0,
    duration_ms INTEGER,
    error_details JSONB,
    started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMPTZ
);

-- Table: cato_decision_events
CREATE TABLE IF NOT EXISTS cato_decision_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID,
  request_id UUID,
  
  decision_type decision_type NOT NULL,
  decision_input JSONB NOT NULL,
  decision_output JSONB NOT NULL,
  
  -- Reasoning
  reasoning_chain JSONB DEFAULT '[]',
  factors_considered JSONB DEFAULT '[]',
  alternatives_rejected JSONB DEFAULT '[]',
  
  -- Model selection details
  selected_model VARCHAR(100),
  model_candidates JSONB DEFAULT '[]',
  selection_criteria JSONB,
  
  -- Cost
  estimated_cost DECIMAL(10,6),
  actual_cost DECIMAL(10,6),
  
  -- Safety (Genesis Cato integration)
  governor_state VARCHAR(30),
  cbf_evaluations JSONB DEFAULT '[]',
  safety_score DECIMAL(3,2),
  
  -- Timing
  decision_latency_ms INTEGER,
  
  -- Context
  user_id UUID REFERENCES users(id),
  workflow_id UUID,
  agent_execution_id UUID REFERENCES agent_executions(id),
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_decision_explanations
CREATE TABLE IF NOT EXISTS cato_decision_explanations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  decision_event_id UUID NOT NULL REFERENCES cato_decision_events(id) ON DELETE CASCADE,
  
  tier explanation_tier NOT NULL,
  explanation TEXT NOT NULL,
  full_context JSONB,
  
  -- Metadata
  generated_by VARCHAR(100), -- model that generated this
  tokens_used INTEGER,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_explanation_tier UNIQUE (decision_event_id, tier)
);

-- Table: cato_decision_feedback
CREATE TABLE IF NOT EXISTS cato_decision_feedback (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  decision_event_id UUID NOT NULL REFERENCES cato_decision_events(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id),
  
  rating INTEGER CHECK (rating >= 1 AND rating <= 5),
  feedback_type VARCHAR(50), -- 'helpful', 'accurate', 'fast', 'wrong', 'slow'
  comment TEXT,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_user_decision_feedback UNIQUE (decision_event_id, user_id)
);

-- Table: cato_decision_patterns
CREATE TABLE IF NOT EXISTS cato_decision_patterns (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  decision_type decision_type NOT NULL,
  pattern_name VARCHAR(200) NOT NULL,
  
  -- Pattern definition
  input_pattern JSONB NOT NULL,
  recommended_output JSONB NOT NULL,
  
  -- Statistics
  times_matched INTEGER DEFAULT 0,
  times_successful INTEGER DEFAULT 0,
  avg_user_rating DECIMAL(3,2),
  
  -- Learning
  source_decision_ids UUID[] DEFAULT '{}',
  confidence DECIMAL(3,2) DEFAULT 0.5,
  
  is_active BOOLEAN DEFAULT true,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_entropy_jobs
CREATE TABLE IF NOT EXISTS cato_entropy_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Job details
  job_id VARCHAR(100) UNIQUE NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'completed', 'failed')),
  
  -- Input
  prompt TEXT NOT NULL,
  response TEXT NOT NULL,
  model VARCHAR(100),
  check_mode VARCHAR(20) NOT NULL,
  
  -- Results (populated when completed)
  entropy_score NUMERIC(5,4),
  consistency NUMERIC(5,4),
  is_potential_deception BOOLEAN,
  deception_indicators JSONB,
  
  -- Timing
  created_at TIMESTAMPTZ DEFAULT NOW(),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  
  -- Error tracking
  error_message TEXT,
  retry_count INTEGER DEFAULT 0
);

-- Table: cato_epistemic_recovery
CREATE TABLE IF NOT EXISTS cato_epistemic_recovery (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Recovery state
  attempt INTEGER NOT NULL,
  strategy_type VARCHAR(50) NOT NULL, -- 'SAFETY_VIOLATION_RECOVERY', 'COGNITIVE_STALL_RECOVERY', 'HUMAN_ESCALATION'
  
  -- Rejection sources
  rejection_sources TEXT[] NOT NULL,
  rejection_history JSONB NOT NULL,
  
  -- Recovery params (IMMUTABLE: gammaBoost is ALWAYS 0, CBFs ALWAYS ENFORCE)
  forced_persona VARCHAR(50), -- 'scout' for cognitive stalls
  uncertainty_threshold_reduction NUMERIC(5,4),
  system_prompt_injection TEXT,
  
  -- Outcome
  resolved BOOLEAN DEFAULT FALSE,
  resolved_at TIMESTAMPTZ,
  resolution_action VARCHAR(100),
  
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_fracture_detections
CREATE TABLE IF NOT EXISTS cato_fracture_detections (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Fracture analysis
  has_fracture BOOLEAN NOT NULL,
  severity VARCHAR(20) NOT NULL,
  fracture_types TEXT[] NOT NULL,
  
  -- Causal analysis
  causal_has_latent_fracture BOOLEAN,
  causal_violations JSONB,
  
  -- Narrative analysis
  narrative_has_fracture BOOLEAN,
  narrative_alignment_score NUMERIC(5,4),
  
  -- Entropy analysis
  entropy_is_potential_deception BOOLEAN,
  entropy_semantic_entropy NUMERIC(5,4),
  entropy_consistency NUMERIC(5,4),
  entropy_sampled_model VARCHAR(100),
  entropy_check_mode VARCHAR(20),
  
  -- Recovery
  recovery_attempt INTEGER DEFAULT 0,
  effective_persona VARCHAR(50),
  
  recommendation TEXT,
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_global_memory
CREATE TABLE IF NOT EXISTS cato_global_memory (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  category VARCHAR(32) NOT NULL CHECK (category IN ('episodic', 'semantic', 'procedural', 'working')),
  key VARCHAR(512) NOT NULL,
  value JSONB NOT NULL,
  importance DECIMAL(3, 2) DEFAULT 0.5 CHECK (importance >= 0 AND importance <= 1),
  access_count INTEGER DEFAULT 0,
  last_accessed_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ,
  metadata JSONB,
  
  CONSTRAINT cato_global_memory_unique_key UNIQUE (tenant_id, category, key)
);

-- Table: cato_governor_state
CREATE TABLE IF NOT EXISTS cato_governor_state (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Precision values
  epistemic_uncertainty NUMERIC(5,4) NOT NULL,
  requested_gamma NUMERIC(5,4) NOT NULL,
  allowed_gamma NUMERIC(5,4) NOT NULL,
  
  -- Governor state
  governor_state VARCHAR(30) NOT NULL,
  sensory_precision_enforced NUMERIC(5,4) NOT NULL,
  
  -- Recovery state
  recovery_attempt INTEGER DEFAULT 0,
  forced_persona VARCHAR(50),
  system_prompt_injection TEXT,
  
  -- Metadata
  timestamp TIMESTAMPTZ DEFAULT NOW(),
  was_limited BOOLEAN DEFAULT FALSE,
  reason TEXT,
  mathematical_basis TEXT
);

-- Table: cato_human_escalations
CREATE TABLE IF NOT EXISTS cato_human_escalations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Escalation details
  escalation_reason TEXT NOT NULL,
  rejection_history JSONB NOT NULL,
  recovery_attempts INTEGER NOT NULL,
  
  -- Human response
  human_response TEXT,
  human_decision VARCHAR(50), -- 'APPROVED', 'REJECTED', 'MODIFIED'
  responded_at TIMESTAMPTZ,
  responded_by UUID REFERENCES users(id),
  
  -- Status
  status VARCHAR(20) DEFAULT 'PENDING', -- 'PENDING', 'RESOLVED', 'EXPIRED'
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_merkle_entries
CREATE TABLE IF NOT EXISTS cato_merkle_entries (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    pipeline_id         UUID REFERENCES cato_pipeline_executions(id),
    
    -- Sequence
    sequence_number     BIGSERIAL NOT NULL,
    
    -- Record reference
    record_type         VARCHAR(50) NOT NULL,
    record_id           UUID NOT NULL,
    record_hash         VARCHAR(64) NOT NULL,
    
    -- Chain
    previous_hash       VARCHAR(64) NOT NULL,
    merkle_root         VARCHAR(64) NOT NULL,
    
    -- Verification
    verified            BOOLEAN DEFAULT FALSE,
    verified_at         TIMESTAMPTZ,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, sequence_number)
);

-- Table: cato_method_definitions
CREATE TABLE IF NOT EXISTS cato_method_definitions (
    method_id           VARCHAR(100) PRIMARY KEY,
    name                VARCHAR(200) NOT NULL,
    description         TEXT NOT NULL,
    method_type         cato_method_type NOT NULL,
    version             VARCHAR(20) NOT NULL,
    
    -- Capabilities and output types
    capabilities        VARCHAR(100)[] NOT NULL DEFAULT '{}',
    output_types        cato_output_type[] NOT NULL,
    use_cases           TEXT[] DEFAULT '{}',
    
    -- Context requirements
    requires_in_context JSONB NOT NULL DEFAULT '[]',
    accepts_output_types cato_output_type[] NOT NULL DEFAULT '{}',
    typical_predecessors VARCHAR(100)[] DEFAULT '{}',
    typical_successors  VARCHAR(100)[] DEFAULT '{}',
    
    -- Context strategy configuration
    context_strategy    JSONB NOT NULL,
    
    -- Model configuration
    supported_models    JSONB NOT NULL,
    default_model       VARCHAR(100) NOT NULL,
    system_prompt_template TEXT NOT NULL,
    user_prompt_template TEXT,
    prompt_variables    JSONB DEFAULT '[]',
    
    -- Output schema reference
    output_schema_ref   VARCHAR(100) REFERENCES cato_schema_definitions(schema_ref_id),
    
    -- Execution metadata
    estimated_cost_cents INTEGER DEFAULT 0,
    estimated_duration_ms INTEGER DEFAULT 1000,
    risk_category       cato_risk_level DEFAULT 'LOW',
    parallelizable      BOOLEAN DEFAULT FALSE,
    idempotent          BOOLEAN DEFAULT FALSE,
    
    -- Scope and access control
    scope               VARCHAR(20) NOT NULL DEFAULT 'SYSTEM',
    tenant_id           UUID REFERENCES tenants(id),
    enabled             BOOLEAN DEFAULT TRUE,
    min_tier            VARCHAR(50) DEFAULT 'FREE',
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT valid_method_scope CHECK (
        (scope = 'SYSTEM' AND tenant_id IS NULL) OR
        (scope = 'TENANT' AND tenant_id IS NOT NULL)
    )
);

-- Table: cato_method_invocations
CREATE TABLE IF NOT EXISTS cato_method_invocations (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id         UUID NOT NULL REFERENCES cato_pipeline_executions(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    envelope_id         UUID REFERENCES cato_pipeline_envelopes(envelope_id),
    
    -- Method info
    method_id           VARCHAR(100) NOT NULL,
    method_name         VARCHAR(200) NOT NULL,
    method_type         cato_method_type NOT NULL,
    sequence            INTEGER NOT NULL,
    
    -- Input/Output references
    input_envelope_ref  UUID REFERENCES cato_pipeline_envelopes(envelope_id),
    output_envelope_ref UUID REFERENCES cato_pipeline_envelopes(envelope_id),
    
    -- Models used
    models_used         JSONB NOT NULL DEFAULT '[]',
    
    -- Status
    status              cato_invocation_status NOT NULL DEFAULT 'PENDING',
    error               JSONB,
    retry_count         INTEGER DEFAULT 0,
    
    -- Metrics
    duration_ms         INTEGER NOT NULL DEFAULT 0,
    cost_cents          INTEGER NOT NULL DEFAULT 0,
    tokens_input        INTEGER NOT NULL DEFAULT 0,
    tokens_output       INTEGER NOT NULL DEFAULT 0,
    
    -- Tracing
    trace_id            VARCHAR(64) NOT NULL,
    span_id             VARCHAR(32) NOT NULL,
    
    -- Timestamps
    started_at          TIMESTAMPTZ NOT NULL,
    completed_at        TIMESTAMPTZ,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_pipeline_config
CREATE TABLE IF NOT EXISTS cato_pipeline_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Governance Settings
    governance_preset VARCHAR(20) NOT NULL DEFAULT 'BALANCED' CHECK (governance_preset IN ('COWBOY', 'BALANCED', 'PARANOID')),
    custom_risk_thresholds JSONB,
    
    -- Method Execution Settings
    default_model VARCHAR(100) NOT NULL DEFAULT 'claude-sonnet-4-20250514',
    fallback_model VARCHAR(100) NOT NULL DEFAULT 'gpt-4o',
    max_method_retries INTEGER NOT NULL DEFAULT 3,
    method_timeout_ms INTEGER NOT NULL DEFAULT 30000,
    
    -- Cost & Usage Limits
    max_pipeline_cost_cents INTEGER NOT NULL DEFAULT 1000,
    max_daily_pipeline_cost_cents INTEGER NOT NULL DEFAULT 10000,
    max_concurrent_pipelines INTEGER NOT NULL DEFAULT 10,
    
    -- Context Settings
    default_context_strategy VARCHAR(20) NOT NULL DEFAULT 'RELEVANT' CHECK (default_context_strategy IN ('FULL', 'SUMMARY', 'TAIL', 'RELEVANT', 'MINIMAL')),
    max_context_tokens INTEGER NOT NULL DEFAULT 8000,
    context_tail_count INTEGER NOT NULL DEFAULT 5,
    
    -- Compensation Settings
    enable_auto_compensation BOOLEAN NOT NULL DEFAULT true,
    compensation_timeout_ms INTEGER NOT NULL DEFAULT 60000,
    max_compensation_retries INTEGER NOT NULL DEFAULT 3,
    
    -- Audit Settings
    enable_merkle_audit BOOLEAN NOT NULL DEFAULT true,
    audit_retention_days INTEGER NOT NULL DEFAULT 2555,
    enable_prompt_audit BOOLEAN NOT NULL DEFAULT true,
    
    -- Feature Flags
    enable_critics BOOLEAN NOT NULL DEFAULT true,
    enable_red_team BOOLEAN NOT NULL DEFAULT false,
    enable_war_room BOOLEAN NOT NULL DEFAULT true,
    
    -- Notification Settings
    notify_on_checkpoint BOOLEAN NOT NULL DEFAULT true,
    notify_on_veto BOOLEAN NOT NULL DEFAULT true,
    notify_on_failure BOOLEAN NOT NULL DEFAULT true,
    notification_webhook_url TEXT,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Constraints
    UNIQUE(tenant_id)
);

-- Table: cato_pipeline_envelopes
CREATE TABLE IF NOT EXISTS cato_pipeline_envelopes (
    envelope_id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id         UUID NOT NULL REFERENCES cato_pipeline_executions(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    
    -- Sequence in pipeline
    sequence            INTEGER NOT NULL,
    envelope_version    VARCHAR(10) NOT NULL DEFAULT '5.0',
    
    -- Source method
    source_method_id    VARCHAR(100) NOT NULL,
    source_method_type  cato_method_type NOT NULL,
    source_method_name  VARCHAR(200) NOT NULL,
    
    -- Destination method (if known)
    destination_method_id VARCHAR(100),
    routing_reason      TEXT,
    
    -- Output
    output_type         cato_output_type NOT NULL,
    output_schema_ref   VARCHAR(100) REFERENCES cato_schema_definitions(schema_ref_id),
    output_data         JSONB NOT NULL,
    output_data_hash    VARCHAR(64) NOT NULL,
    output_summary      TEXT NOT NULL,
    
    -- Confidence
    confidence_score    DECIMAL(5,4),
    confidence_factors  JSONB DEFAULT '[]',
    
    -- Context strategy applied
    context_strategy    cato_context_strategy NOT NULL,
    context             JSONB NOT NULL,
    
    -- Risk signals
    risk_signals        JSONB DEFAULT '[]',
    
    -- Tracing
    trace_id            VARCHAR(64) NOT NULL,
    span_id             VARCHAR(32) NOT NULL,
    parent_span_id      VARCHAR(32),
    
    -- Compliance
    compliance_frameworks VARCHAR(50)[] NOT NULL DEFAULT '{}',
    data_classification VARCHAR(50) DEFAULT 'INTERNAL',
    contains_pii        BOOLEAN NOT NULL DEFAULT FALSE,
    contains_phi        BOOLEAN NOT NULL DEFAULT FALSE,
    
    -- Execution metadata
    models_used         JSONB DEFAULT '[]',
    duration_ms         INTEGER NOT NULL DEFAULT 0,
    cost_cents          INTEGER NOT NULL DEFAULT 0,
    tokens_used         INTEGER NOT NULL DEFAULT 0,
    
    timestamp           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_pipeline_executions
CREATE TABLE IF NOT EXISTS cato_pipeline_executions (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    user_id             UUID,
    
    -- Status tracking
    status              cato_pipeline_status NOT NULL DEFAULT 'PENDING',
    
    -- Template used (if any)
    template_id         VARCHAR(100) REFERENCES cato_pipeline_templates(template_id),
    
    -- Configuration
    config              JSONB NOT NULL DEFAULT '{}',
    governance_preset   VARCHAR(50) NOT NULL DEFAULT 'BALANCED',
    
    -- Original request
    original_request    JSONB NOT NULL,
    original_request_hash VARCHAR(64) NOT NULL,
    
    -- Execution tracking
    methods_executed    VARCHAR(100)[] NOT NULL DEFAULT '{}',
    current_method      VARCHAR(100),
    current_sequence    INTEGER DEFAULT 0,
    
    -- Cost and duration
    total_cost_cents    INTEGER NOT NULL DEFAULT 0,
    total_duration_ms   INTEGER NOT NULL DEFAULT 0,
    total_tokens        INTEGER NOT NULL DEFAULT 0,
    
    -- Final result
    final_envelope_id   UUID,
    execution_result    JSONB,
    error               JSONB,
    
    -- Tracing
    trace_id            VARCHAR(64) NOT NULL,
    
    -- Timestamps
    started_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at        TIMESTAMPTZ,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_pipeline_templates
CREATE TABLE IF NOT EXISTS cato_pipeline_templates (
    template_id         VARCHAR(100) PRIMARY KEY,
    name                VARCHAR(200) NOT NULL,
    description         TEXT NOT NULL,
    
    -- Method chain configuration
    method_chain        VARCHAR(100)[] NOT NULL,
    checkpoint_positions JSONB NOT NULL DEFAULT '{}',
    
    -- Default configuration
    default_config      JSONB NOT NULL DEFAULT '{}',
    
    -- Categorization
    category            VARCHAR(100),
    tags                VARCHAR(50)[] DEFAULT '{}',
    
    -- Scope
    scope               VARCHAR(20) NOT NULL DEFAULT 'SYSTEM',
    tenant_id           UUID REFERENCES tenants(id),
    enabled             BOOLEAN DEFAULT TRUE,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_risk_assessments
CREATE TABLE IF NOT EXISTS cato_risk_assessments (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id         UUID NOT NULL REFERENCES cato_pipeline_executions(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id),
    envelope_id         UUID NOT NULL REFERENCES cato_pipeline_envelopes(envelope_id),
    
    -- Overall assessment
    overall_risk        cato_risk_level NOT NULL,
    overall_risk_score  DECIMAL(5,4) NOT NULL,
    
    -- Veto logic
    veto_applied        BOOLEAN NOT NULL DEFAULT FALSE,
    veto_factor         VARCHAR(100),
    veto_reason         TEXT,
    
    -- Individual risk factors
    risk_factors        JSONB NOT NULL DEFAULT '[]',
    
    -- Triage decision
    triage_decision     cato_triage_decision NOT NULL,
    triage_reason       TEXT NOT NULL,
    
    -- Thresholds used
    auto_execute_threshold DECIMAL(5,4) NOT NULL,
    veto_threshold      DECIMAL(5,4) NOT NULL,
    
    -- Unmitigated risks
    unmitigated_risks   TEXT[] DEFAULT '{}',
    mitigation_suggestions JSONB DEFAULT '[]',
    
    assessed_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cato_schema_definitions
CREATE TABLE IF NOT EXISTS cato_schema_definitions (
    schema_ref_id       VARCHAR(100) PRIMARY KEY,
    schema_name         VARCHAR(100) NOT NULL,
    version             VARCHAR(20) NOT NULL,
    
    -- The actual JSON Schema definition
    json_schema         JSONB NOT NULL,
    
    -- Human-readable field descriptions
    field_descriptions  JSONB NOT NULL DEFAULT '{}',
    
    -- Which output types use this schema
    used_by_output_types cato_output_type[] NOT NULL DEFAULT '{}',
    
    -- Which methods produce this schema
    produced_by_methods VARCHAR(100)[] NOT NULL DEFAULT '{}',
    
    -- Example payload for documentation
    example_payload     JSONB,
    
    -- Scope: SYSTEM (built-in) or TENANT (custom)
    scope               VARCHAR(20) NOT NULL DEFAULT 'SYSTEM',
    tenant_id           UUID REFERENCES tenants(id),
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT valid_scope CHECK (
        (scope = 'SYSTEM' AND tenant_id IS NULL) OR
        (scope = 'TENANT' AND tenant_id IS NOT NULL)
    )
);

-- Table: cato_tenant_config
CREATE TABLE IF NOT EXISTS cato_tenant_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Governor settings
  gamma_max NUMERIC(5,4) DEFAULT 5.0,
  emergency_threshold NUMERIC(5,4) DEFAULT 0.5,
  sensory_floor NUMERIC(5,4) DEFAULT 0.3,
  
  -- Recovery settings
  livelock_threshold INTEGER DEFAULT 3,
  recovery_window_seconds INTEGER DEFAULT 10,
  max_recovery_attempts INTEGER DEFAULT 3,
  
  -- Entropy settings
  entropy_high_risk_threshold NUMERIC(5,4) DEFAULT 0.8,
  entropy_low_risk_threshold NUMERIC(5,4) DEFAULT 0.3,
  
  -- Audit settings
  tile_size INTEGER DEFAULT 1000,
  retention_years INTEGER DEFAULT 7,
  
  -- Feature flags
  enable_semantic_entropy BOOLEAN DEFAULT TRUE,
  enable_redundant_perception BOOLEAN DEFAULT TRUE,
  enable_fracture_detection BOOLEAN DEFAULT TRUE,
  
  -- Default persona (MUST be 'balanced')
  default_persona_id UUID REFERENCES genesis_personas(id),
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE (tenant_id)
);

-- Table: cato_tool_definitions
CREATE TABLE IF NOT EXISTS cato_tool_definitions (
    tool_id             VARCHAR(100) PRIMARY KEY,
    tool_name           VARCHAR(200) NOT NULL,
    description         TEXT NOT NULL,
    
    -- Execution configuration
    -- For MCP: mcp_server contains server URL
    -- For Lambda: mcp_server contains 'lambda://{function_name}'
    mcp_server          VARCHAR(255) NOT NULL,
    
    -- Schema definitions
    input_schema        JSONB NOT NULL,
    output_schema       JSONB NOT NULL,
    
    -- Risk and reversibility
    risk_category       cato_risk_level NOT NULL DEFAULT 'MEDIUM',
    supports_dry_run    BOOLEAN NOT NULL DEFAULT FALSE,
    is_reversible       BOOLEAN NOT NULL DEFAULT FALSE,
    compensation_type   cato_compensation_type NOT NULL DEFAULT 'NONE',
    compensation_tool   VARCHAR(100),
    
    -- Cost and limits
    estimated_cost_cents INTEGER DEFAULT 0,
    rate_limit          JSONB,
    required_permissions VARCHAR(100)[] DEFAULT '{}',
    
    -- Categorization
    category            VARCHAR(100),
    tags                VARCHAR(50)[] DEFAULT '{}',
    
    -- Scope and access
    scope               VARCHAR(20) NOT NULL DEFAULT 'SYSTEM',
    tenant_id           UUID REFERENCES tenants(id),
    enabled             BOOLEAN DEFAULT TRUE,
    
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT valid_tool_scope CHECK (
        (scope = 'SYSTEM' AND tenant_id IS NULL) OR
        (scope = 'TENANT' AND tenant_id IS NOT NULL)
    )
);

-- Table: cato_veto_log
CREATE TABLE IF NOT EXISTS cato_veto_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Veto details
  signal VARCHAR(50) NOT NULL,
  action_taken VARCHAR(50) NOT NULL,
  enforced_gamma NUMERIC(5,4),
  
  -- Context
  context JSONB NOT NULL,
  escalated BOOLEAN DEFAULT FALSE,
  escalation_target VARCHAR(100),
  
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cato_war_room_deliberations
CREATE TABLE IF NOT EXISTS cato_war_room_deliberations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  decision_event_id UUID NOT NULL REFERENCES cato_decision_events(id) ON DELETE CASCADE,
  
  phase VARCHAR(50) NOT NULL,
  phase_order INTEGER NOT NULL,
  
  -- Participant
  participant_role VARCHAR(50) NOT NULL, -- 'advocate', 'critic', 'synthesizer', 'judge'
  participant_model VARCHAR(100) NOT NULL,
  
  -- Content
  input_prompt TEXT,
  output_response TEXT,
  
  -- Analysis
  key_points JSONB DEFAULT '[]',
  objections JSONB DEFAULT '[]',
  agreements JSONB DEFAULT '[]',
  
  -- Timing
  started_at TIMESTAMPTZ NOT NULL,
  completed_at TIMESTAMPTZ,
  latency_ms INTEGER,
  
  -- Cost
  tokens_input INTEGER,
  tokens_output INTEGER,
  cost_usd DECIMAL(10,6)
);

-- Table: causal_edges
CREATE TABLE IF NOT EXISTS causal_edges (
    edge_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Edge endpoints
    cause_node_id UUID NOT NULL REFERENCES causal_nodes(node_id) ON DELETE CASCADE,
    effect_node_id UUID NOT NULL REFERENCES causal_nodes(node_id) ON DELETE CASCADE,
    
    -- Causal properties
    causal_type VARCHAR(50) NOT NULL, -- 'direct', 'indirect', 'confounded', 'mediated', 'moderated'
    mechanism TEXT, -- Description of how cause produces effect
    
    -- Strength and confidence
    causal_strength DECIMAL(5,4), -- -1 to 1 (negative = inhibitory)
    confidence DECIMAL(5,4) DEFAULT 0.5,
    
    -- Temporal properties
    time_lag_mins INTEGER, -- Expected delay between cause and effect
    is_instantaneous BOOLEAN DEFAULT false,
    
    -- Conditional relationships
    conditions JSONB DEFAULT '[]', -- [{variable, operator, value}] for when this edge is active
    moderators JSONB DEFAULT '[]', -- Variables that affect edge strength
    
    -- Evidence
    evidence_type VARCHAR(50), -- 'observed', 'experimental', 'inferred', 'theoretical'
    evidence_count INTEGER DEFAULT 0,
    supporting_observations UUID[] DEFAULT '{}',
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT no_self_loops CHECK (cause_node_id != effect_node_id)
);

-- Table: causal_interventions
CREATE TABLE IF NOT EXISTS causal_interventions (
    intervention_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    session_id UUID,
    
    -- Intervention specification
    intervention_type VARCHAR(50) NOT NULL, -- 'do', 'observe', 'counterfactual'
    target_node_id UUID NOT NULL REFERENCES causal_nodes(node_id),
    intervention_value JSONB NOT NULL,
    
    -- Context
    context_snapshot JSONB DEFAULT '{}', -- State of other variables
    query_node_ids UUID[] DEFAULT '{}', -- Nodes we're querying about
    
    -- Results
    predicted_effects JSONB DEFAULT '{}', -- {node_id: {value, confidence}}
    actual_effects JSONB DEFAULT '{}', -- Observed outcomes
    prediction_error DECIMAL(5,4),
    
    -- Counterfactual specific
    counterfactual_premise TEXT, -- "What if X had been Y instead?"
    counterfactual_conclusion TEXT,
    
    -- Metadata
    reasoning_trace JSONB DEFAULT '[]', -- Steps of causal inference
    
    executed_at TIMESTAMPTZ DEFAULT NOW(),
    verified_at TIMESTAMPTZ
);

-- Table: causal_links
CREATE TABLE IF NOT EXISTS causal_links (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  conversation_id UUID NOT NULL,
  source_turn_id UUID NOT NULL,
  target_turn_id UUID NOT NULL,
  causal_type VARCHAR(20) NOT NULL CHECK (causal_type IN ('reference', 'elaboration', 'correction', 'consequence', 'contradiction', 'continuation')),
  strength DECIMAL(3,2) DEFAULT 0.8,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(source_turn_id, target_turn_id)
);

-- Table: causal_nodes
CREATE TABLE IF NOT EXISTS causal_nodes (
    node_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Node identity
    name VARCHAR(500) NOT NULL,
    node_type VARCHAR(50) NOT NULL, -- 'variable', 'event', 'state', 'action', 'outcome'
    description TEXT,
    node_embedding vector(1536),
    
    -- Variable properties (for causal inference)
    is_observable BOOLEAN DEFAULT true,
    is_manipulable BOOLEAN DEFAULT true, -- Can be intervened on
    domain_type VARCHAR(50), -- 'continuous', 'discrete', 'binary', 'categorical'
    possible_values JSONB DEFAULT '[]',
    
    -- Current state
    current_value JSONB,
    value_confidence DECIMAL(5,4),
    last_observed TIMESTAMPTZ,
    
    -- Statistics
    observation_count INTEGER DEFAULT 0,
    intervention_count INTEGER DEFAULT 0,
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: chaotic_inputs
CREATE TABLE IF NOT EXISTS chaotic_inputs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    session_id UUID,
    input_type VARCHAR(50) NOT NULL,
    raw_content TEXT NOT NULL,
    attachments JSONB DEFAULT '[]',
    context TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT valid_input_type CHECK (input_type IN ('whiteboard', 'brainstorm', 'meeting_notes', 'voice_transcript', 'chat_history', 'document_dump', 'mixed'))
);

-- Table: checklist_audit_runs
CREATE TABLE IF NOT EXISTS checklist_audit_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    version_id UUID NOT NULL REFERENCES compliance_checklist_versions(id) ON DELETE CASCADE,
    run_type VARCHAR(30) NOT NULL DEFAULT 'manual' CHECK (run_type IN ('manual', 'scheduled', 'pre_audit', 'certification')),
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    status VARCHAR(30) NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'completed', 'cancelled', 'failed')),
    total_items INTEGER NOT NULL DEFAULT 0,
    completed_items INTEGER NOT NULL DEFAULT 0,
    passed_items INTEGER NOT NULL DEFAULT 0,
    failed_items INTEGER NOT NULL DEFAULT 0,
    skipped_items INTEGER NOT NULL DEFAULT 0,
    score DECIMAL(5,2),
    triggered_by VARCHAR(200),
    notes TEXT,
    report_url VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: checklist_update_sources
CREATE TABLE IF NOT EXISTS checklist_update_sources (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    standard_id UUID NOT NULL REFERENCES regulatory_standards(id) ON DELETE CASCADE,
    source_type VARCHAR(30) NOT NULL CHECK (source_type IN ('rss_feed', 'api', 'webhook', 'manual')),
    source_name VARCHAR(200) NOT NULL,
    source_url VARCHAR(500),
    api_key_secret_name VARCHAR(200),
    check_frequency_hours INTEGER NOT NULL DEFAULT 24,
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    last_check_at TIMESTAMPTZ,
    last_update_found_at TIMESTAMPTZ,
    error_count INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: circuit_breaker_state
CREATE TABLE IF NOT EXISTS circuit_breaker_state (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    
    -- State
    state VARCHAR(20) DEFAULT 'closed', -- 'closed', 'open', 'half_open'
    failure_count INTEGER DEFAULT 0,
    success_count INTEGER DEFAULT 0,
    last_failure_at TIMESTAMPTZ,
    last_success_at TIMESTAMPTZ,
    opened_at TIMESTAMPTZ,
    
    -- Metadata
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_circuit_state UNIQUE (tenant_id, model_id)
);

-- Table: citation_half_lives
CREATE TABLE IF NOT EXISTS citation_half_lives (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    category VARCHAR(255) NOT NULL,
    estimated_half_life INTEGER NOT NULL, -- days
    confidence_in_estimate INTEGER DEFAULT 50,
    based_on_samples INTEGER DEFAULT 0,
    decay_curve JSONB DEFAULT '[]',
    visual_indicator JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, category)
);

-- Table: clarion_question_effectiveness
CREATE TABLE IF NOT EXISTS clarion_question_effectiveness (
  id SERIAL PRIMARY KEY,
  question_id VARCHAR(64) NOT NULL REFERENCES clarion_questions(question_id),
  domain VARCHAR(128) NOT NULL,
  ask_count INTEGER NOT NULL DEFAULT 0,
  skip_count INTEGER NOT NULL DEFAULT 0,
  average_information_gain DECIMAL(4,3) NOT NULL DEFAULT 0.500,
  outcome_correlation DECIMAL(4,3) NOT NULL DEFAULT 0.000,
  last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(question_id, domain)
);

-- Table: clarion_questions
CREATE TABLE IF NOT EXISTS clarion_questions (
  question_id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),  -- NULL for global questions
  domain_applicability JSONB NOT NULL DEFAULT '[]',
  question_type clarion_question_type NOT NULL,
  text_localized JSONB NOT NULL,  -- { "en": "...", "es": "...", ... }
  options_localized JSONB,  -- { "en": ["opt1", "opt2"], ... }
  branches JSONB,  -- Branching logic per answer
  priority DECIMAL(3,2) NOT NULL DEFAULT 0.50,
  information_gain DECIMAL(3,2) NOT NULL DEFAULT 0.50,
  category clarion_question_category NOT NULL DEFAULT 'context',
  requires_answers JSONB DEFAULT '[]',
  conflicts_with JSONB DEFAULT '[]',
  model_rules JSONB,  -- Model-specific skip/require rules
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by VARCHAR(64)
);

-- Table: clarion_sessions
CREATE TABLE IF NOT EXISTS clarion_sessions (
  session_id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  chain_id VARCHAR(64),  -- Key Chain identity
  conversation_id VARCHAR(64),
  domain VARCHAR(128) NOT NULL,
  original_query TEXT NOT NULL,
  locale VARCHAR(10) NOT NULL DEFAULT 'en',
  status clarion_session_status NOT NULL DEFAULT 'active',
  current_confidence DECIMAL(4,3) NOT NULL DEFAULT 0.000,
  model_predictions JSONB NOT NULL DEFAULT '[]',
  working_context JSONB NOT NULL DEFAULT '{}',
  answers JSONB NOT NULL DEFAULT '{}',
  asked_questions JSONB NOT NULL DEFAULT '[]',
  skipped_questions JSONB NOT NULL DEFAULT '[]',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ
);

-- Table: classification_feedback
CREATE TABLE IF NOT EXISTS classification_feedback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    classification_id UUID NOT NULL REFERENCES classification_results(id) ON DELETE CASCADE,
    
    -- Feedback
    feedback_type VARCHAR(50) NOT NULL, -- 'false_positive', 'false_negative', 'correct', 'uncertain'
    correct_label BOOLEAN,
    correct_categories TEXT[] DEFAULT '{}',
    notes TEXT,
    
    -- Submitter
    submitted_by UUID NOT NULL,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_feedback_per_user UNIQUE (classification_id, submitted_by)
);

-- Table: classification_results
CREATE TABLE IF NOT EXISTS classification_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    classifier_id UUID REFERENCES constitutional_classifiers(id),
    
    -- Input
    input_hash VARCHAR(64) NOT NULL, -- SHA256 of input
    input_type VARCHAR(50) NOT NULL, -- 'prompt', 'response', 'conversation'
    
    -- Results
    is_harmful BOOLEAN NOT NULL,
    confidence_score DOUBLE PRECISION NOT NULL,
    harm_categories JSONB DEFAULT '[]', -- [{category, score}]
    attack_type VARCHAR(100), -- 'jailbreak', 'injection', 'encoding', 'roleplay'
    
    -- Action taken
    action_taken VARCHAR(50), -- 'allowed', 'blocked', 'flagged', 'modified'
    
    -- Metadata
    latency_ms INTEGER,
    model_id VARCHAR(255),
    user_id UUID,
    request_id UUID,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: code_correction_log
CREATE TABLE IF NOT EXISTS code_correction_log (
    correction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    verification_id UUID REFERENCES code_verification_log(verification_id) ON DELETE CASCADE,
    attempt_number INTEGER NOT NULL,
    error_message TEXT,
    correction_applied BOOLEAN,
    fixed_issue BOOLEAN,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: code_execution_runs
CREATE TABLE IF NOT EXISTS code_execution_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES code_execution_sessions(id) ON DELETE CASCADE,
    iteration INTEGER NOT NULL,
    code_snapshot TEXT NOT NULL,
    execution_status TEXT NOT NULL,
    stdout TEXT,
    stderr TEXT,
    exit_code INTEGER,
    execution_time_ms INTEGER,
    memory_used_mb INTEGER,
    error_type TEXT,
    patch_applied TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: code_execution_sessions
CREATE TABLE IF NOT EXISTS code_execution_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id UUID,
    language TEXT NOT NULL,
    original_code TEXT NOT NULL,
    current_code TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    iteration_count INTEGER DEFAULT 0,
    max_iterations INTEGER DEFAULT 3,
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: code_quality_alerts
CREATE TABLE IF NOT EXISTS code_quality_alerts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Alert details
    alert_type VARCHAR(50) NOT NULL CHECK (alert_type IN ('coverage_drop', 'new_debt', 'test_failure', 'quality_regression', 'security_issue')),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('critical', 'warning', 'info')),
    title VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Context
    component VARCHAR(100),
    file_path VARCHAR(500),
    metric_name VARCHAR(100),
    previous_value DECIMAL(10,2),
    current_value DECIMAL(10,2),
    threshold_value DECIMAL(10,2),
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'acknowledged', 'resolved', 'dismissed')),
    acknowledged_by VARCHAR(100),
    acknowledged_at TIMESTAMPTZ,
    resolved_at TIMESTAMPTZ,
    resolution_notes TEXT,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: code_quality_snapshots
CREATE TABLE IF NOT EXISTS code_quality_snapshots (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Snapshot metadata
    snapshot_type VARCHAR(50) NOT NULL CHECK (snapshot_type IN ('test_coverage', 'code_quality', 'technical_debt', 'json_safety')),
    component VARCHAR(100) NOT NULL, -- 'lambda', 'admin-dashboard', 'thinktank-admin', 'swift-deployer', 'gateway'
    
    -- Test coverage metrics
    total_files INTEGER,
    files_with_tests INTEGER,
    total_lines INTEGER,
    covered_lines INTEGER,
    total_functions INTEGER,
    covered_functions INTEGER,
    total_branches INTEGER,
    covered_branches INTEGER,
    
    -- Calculated coverage percentages
    line_coverage DECIMAL(5,2),
    function_coverage DECIMAL(5,2),
    branch_coverage DECIMAL(5,2),
    overall_coverage DECIMAL(5,2),
    
    -- Code quality metrics
    eslint_errors INTEGER DEFAULT 0,
    eslint_warnings INTEGER DEFAULT 0,
    typescript_errors INTEGER DEFAULT 0,
    
    -- Technical debt metrics
    todo_count INTEGER DEFAULT 0,
    fixme_count INTEGER DEFAULT 0,
    any_type_count INTEGER DEFAULT 0,
    unsafe_json_parse_count INTEGER DEFAULT 0,
    
    -- JSON safety migration progress
    safe_json_calls INTEGER DEFAULT 0,
    unsafe_json_calls INTEGER DEFAULT 0,
    json_safety_percentage DECIMAL(5,2),
    
    -- Additional metadata
    metadata JSONB DEFAULT '{}',
    
    -- Timestamps
    captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: code_verification_log
CREATE TABLE IF NOT EXISTS code_verification_log (
    verification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    language VARCHAR(20) NOT NULL,
    verified BOOLEAN NOT NULL,
    iterations INTEGER NOT NULL,
    tests_passed INTEGER DEFAULT 0,
    tests_failed INTEGER DEFAULT 0,
    final_exit_code INTEGER,
    execution_time_ms INTEGER,
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cognitive_agents
CREATE TABLE IF NOT EXISTS cognitive_agents (
    agent_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Agent identity
    role VARCHAR(50) NOT NULL, -- 'planner', 'critic', 'executor', 'verifier', 'researcher', 'synthesizer'
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    description TEXT,
    avatar_icon VARCHAR(50),
    avatar_color VARCHAR(20),
    
    -- Model configuration
    primary_model_id VARCHAR(100) NOT NULL,
    fallback_model_ids TEXT[] DEFAULT '{}',
    system_prompt TEXT NOT NULL,
    temperature DECIMAL(3,2) DEFAULT 0.7,
    max_tokens INTEGER DEFAULT 4096,
    
    -- Capabilities
    capabilities TEXT[] DEFAULT '{}', -- 'reasoning', 'coding', 'research', 'critique', 'synthesis'
    specializations JSONB DEFAULT '{}', -- Domain-specific expertise
    
    -- Personality traits (affects collaboration style)
    personality JSONB DEFAULT '{}', -- {assertiveness, openness, detail_orientation, creativity}
    
    -- Beliefs and knowledge (for model-based collaboration)
    beliefs JSONB DEFAULT '{}', -- Current beliefs about the world/task
    knowledge_domains TEXT[] DEFAULT '{}',
    
    -- Performance metrics
    total_activations INTEGER DEFAULT 0,
    successful_activations INTEGER DEFAULT 0,
    avg_response_time_ms DECIMAL(10,2),
    avg_quality_score DECIMAL(5,4),
    collaboration_score DECIMAL(5,4), -- How well it works with others
    
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, slug)
);

-- Table: cognitive_architecture_config
CREATE TABLE IF NOT EXISTS cognitive_architecture_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Feature configs (JSONB for flexibility)
    tree_of_thoughts JSONB DEFAULT '{
        "enabled": true,
        "maxDepth": 5,
        "branchingFactor": 3,
        "pruneThreshold": 0.3,
        "selectionStrategy": "beam",
        "beamWidth": 2,
        "scoringModel": "gpt-4o-mini",
        "generationModel": "gpt-4o",
        "defaultThinkingTimeMs": 30000,
        "maxThinkingTimeMs": 300000
    }',
    
    graph_rag JSONB DEFAULT '{
        "enabled": true,
        "extractionModel": "gpt-4o-mini",
        "maxEntitiesPerDocument": 50,
        "maxRelationshipsPerDocument": 100,
        "minConfidenceThreshold": 0.7,
        "enableHybridSearch": true,
        "graphWeight": 0.6,
        "vectorWeight": 0.4,
        "maxHops": 3
    }',
    
    deep_research JSONB DEFAULT '{
        "enabled": true,
        "maxSources": 50,
        "maxDepth": 2,
        "maxDurationMs": 1800000,
        "allowedSourceTypes": ["web", "pdf", "api"],
        "requireCredibleSources": true,
        "minSourceCredibility": 0.6,
        "parallelRequests": 5
    }',
    
    dynamic_lora JSONB DEFAULT '{
        "enabled": false,
        "registryBucket": "radiant-lora-adapters",
        "cacheSize": 5,
        "preloadDomains": ["coding", "legal"],
        "maxLoadTimeMs": 5000,
        "fallbackToBase": true,
        "autoSelectByDomain": true
    }',
    
    generative_ui JSONB DEFAULT '{
        "enabled": true,
        "generationModel": "gpt-4o",
        "allowedComponentTypes": ["chart", "table", "calculator", "comparison", "timeline"],
        "maxComponentsPerResponse": 3,
        "autoDetectOpportunities": true,
        "defaultTheme": "auto"
    }',
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: cognitive_brain_settings
CREATE TABLE IF NOT EXISTS cognitive_brain_settings (
    tenant_id UUID PRIMARY KEY REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Global toggles
    cognitive_brain_enabled BOOLEAN DEFAULT true,
    learning_enabled BOOLEAN DEFAULT true,
    adaptation_enabled BOOLEAN DEFAULT true,
    
    -- Default blueprint
    default_blueprint_id UUID REFERENCES neural_blueprints(blueprint_id),
    
    -- Performance limits
    max_concurrent_regions INTEGER DEFAULT 5,
    max_tokens_per_request INTEGER DEFAULT 16000,
    max_latency_ms INTEGER DEFAULT 10000,
    
    -- Cost controls
    daily_cost_limit_cents INTEGER DEFAULT 10000, -- $100 default
    monthly_cost_limit_cents INTEGER DEFAULT 100000, -- $1000 default
    
    -- Learning parameters
    global_learning_rate DECIMAL(5,4) DEFAULT 0.01,
    memory_retention_days INTEGER DEFAULT 90,
    insight_confidence_threshold DECIMAL(3,2) DEFAULT 0.7,
    
    -- Feature flags
    enable_metacognition BOOLEAN DEFAULT true,
    enable_theory_of_mind BOOLEAN DEFAULT true,
    enable_creative_synthesis BOOLEAN DEFAULT true,
    enable_self_correction BOOLEAN DEFAULT true,
    
    -- Advanced
    custom_system_prompt TEXT,
    region_overrides JSONB DEFAULT '{}',
    
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cognitive_circuit_breakers
CREATE TABLE IF NOT EXISTS cognitive_circuit_breakers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Endpoint identification
    endpoint_type VARCHAR(50) NOT NULL, -- 'ghost_memory', 'sniper', 'war_room', 'hitl'
    endpoint_id VARCHAR(100) NOT NULL,
    
    -- Circuit breaker state
    state VARCHAR(20) DEFAULT 'CLOSED' CHECK (state IN ('CLOSED', 'OPEN', 'HALF_OPEN')),
    failure_count INTEGER DEFAULT 0,
    success_count INTEGER DEFAULT 0,
    half_open_successes INTEGER DEFAULT 0,
    
    -- Configuration
    failure_threshold INTEGER DEFAULT 5,
    recovery_timeout_seconds INTEGER DEFAULT 30,
    half_open_max_requests INTEGER DEFAULT 3,
    
    -- Timing
    last_failure_at TIMESTAMPTZ,
    last_success_at TIMESTAMPTZ,
    state_changed_at TIMESTAMPTZ DEFAULT NOW(),
    
    -- Metrics
    total_requests INTEGER DEFAULT 0,
    total_failures INTEGER DEFAULT 0,
    avg_latency_ms FLOAT,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, endpoint_type, endpoint_id)
);

-- Table: cognitive_config
CREATE TABLE IF NOT EXISTS cognitive_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE UNIQUE,
    
    -- Ghost Memory settings
    ghost_memory_enabled BOOLEAN DEFAULT TRUE,
    ghost_default_ttl_seconds INTEGER DEFAULT 86400,
    ghost_similarity_threshold FLOAT DEFAULT 0.85,
    ghost_max_entries_per_user INTEGER DEFAULT 1000,
    
    -- Economic Governor settings
    governor_enabled BOOLEAN DEFAULT TRUE,
    governor_mode VARCHAR(20) DEFAULT 'balanced' CHECK (governor_mode IN ('off', 'cost_saver', 'balanced', 'performance')),
    governor_sniper_threshold FLOAT DEFAULT 0.3,
    governor_war_room_threshold FLOAT DEFAULT 0.7,
    
    -- Retrieval confidence settings
    retrieval_confidence_threshold FLOAT DEFAULT 0.7,
    low_confidence_route VARCHAR(20) DEFAULT 'war_room',
    
    -- Circuit breaker settings
    circuit_breaker_enabled BOOLEAN DEFAULT TRUE,
    circuit_breaker_failure_threshold INTEGER DEFAULT 5,
    circuit_breaker_recovery_seconds INTEGER DEFAULT 30,
    
    -- HITL settings
    hitl_timeout_seconds INTEGER DEFAULT 86400,
    hitl_auto_expire BOOLEAN DEFAULT TRUE,
    
    -- Metrics settings
    metrics_enabled BOOLEAN DEFAULT TRUE,
    metrics_sample_rate FLOAT DEFAULT 1.0,
    
    -- Domain routing
    domain_routing_enabled BOOLEAN DEFAULT TRUE,
    domain_routing_rules JSONB DEFAULT '{}'::jsonb,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cognitive_hitl_escalations
CREATE TABLE IF NOT EXISTS cognitive_hitl_escalations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id UUID NOT NULL,
    
    -- Escalation source
    source_workflow VARCHAR(100) NOT NULL,
    routing_decision_id UUID REFERENCES cognitive_routing_decisions(id),
    
    -- Query context
    original_query TEXT NOT NULL,
    domain_hint VARCHAR(50),
    complexity_score FLOAT,
    
    -- Timeout details
    timeout_seconds INTEGER NOT NULL,
    war_room_attempts INTEGER DEFAULT 1,
    
    -- Resolution
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'resolved', 'expired', 'cancelled')),
    resolution TEXT,
    resolved_by UUID REFERENCES users(id),
    resolved_at TIMESTAMPTZ,
    
    -- Metadata
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL
);

-- Table: cognitive_learned_insights
CREATE TABLE IF NOT EXISTS cognitive_learned_insights (
    insight_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID, -- null = tenant-wide insight
    
    -- Insight classification
    insight_type VARCHAR(50) NOT NULL, -- 'preference', 'pattern', 'correction', 'optimization'
    category VARCHAR(100),
    
    -- Content
    title VARCHAR(500),
    content TEXT NOT NULL,
    evidence JSONB DEFAULT '[]', -- supporting examples
    
    -- Confidence and validation
    confidence DECIMAL(3,2) DEFAULT 0.5,
    validation_count INTEGER DEFAULT 0,
    contradiction_count INTEGER DEFAULT 0,
    
    -- Embedding
    embedding vector(1536),
    
    -- Application tracking
    times_applied BIGINT DEFAULT 0,
    last_applied_at TIMESTAMPTZ,
    effectiveness_score DECIMAL(3,2),
    
    -- Status
    is_active BOOLEAN DEFAULT true,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cognitive_load_history
CREATE TABLE IF NOT EXISTS cognitive_load_history (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES cognitive_load_sessions(id) ON DELETE CASCADE,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    load_value INTEGER NOT NULL CHECK (load_value >= 0 AND load_value <= 100),
    factors JSONB DEFAULT '{}',
    content_id VARCHAR(255),
    interaction_type VARCHAR(50)
);

-- Table: cognitive_load_sessions
CREATE TABLE IF NOT EXISTS cognitive_load_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    current_load INTEGER DEFAULT 0 CHECK (current_load >= 0 AND current_load <= 100),
    fatigue_level VARCHAR(50) DEFAULT 'fresh',
    session_duration INTEGER DEFAULT 0, -- minutes
    break_suggested BOOLEAN DEFAULT FALSE,
    overwhelm_active BOOLEAN DEFAULT FALSE,
    overwhelm_level INTEGER DEFAULT 0,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_interaction_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    attention_heatmap JSONB DEFAULT '{}',
    adaptations_applied JSONB DEFAULT '[]'
);

-- Table: cognitive_metrics
CREATE TABLE IF NOT EXISTS cognitive_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Metric identification
    metric_namespace VARCHAR(100) NOT NULL, -- 'Radiant/Cognitive'
    metric_name VARCHAR(100) NOT NULL,
    
    -- Dimensions
    dimensions JSONB DEFAULT '{}'::jsonb,
    
    -- Values
    value FLOAT NOT NULL,
    unit VARCHAR(50) DEFAULT 'Count',
    
    -- Timestamp
    timestamp TIMESTAMPTZ DEFAULT NOW(),
    
    -- Aggregation helpers
    period_start TIMESTAMPTZ,
    period_end TIMESTAMPTZ
);

-- Table: cognitive_patterns
CREATE TABLE IF NOT EXISTS cognitive_patterns (
    pattern_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Pattern identity
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    description TEXT,
    category VARCHAR(100) DEFAULT 'general',
    tags TEXT[] DEFAULT '{}',
    
    -- Trigger conditions
    trigger_type VARCHAR(50) NOT NULL, -- 'keyword', 'intent', 'sentiment', 'context', 'composite'
    trigger_conditions JSONB NOT NULL, -- detailed conditions for activation
    trigger_threshold DECIMAL(3,2) DEFAULT 0.7, -- confidence threshold
    
    -- Brain region orchestration
    region_sequence JSONB NOT NULL, -- ordered list of regions to activate
    execution_mode VARCHAR(20) DEFAULT 'sequential', -- 'sequential', 'parallel', 'adaptive'
    
    -- Context requirements
    required_context TEXT[] DEFAULT '{}', -- context keys that must be present
    context_window_size INTEGER DEFAULT 10, -- number of previous messages to consider
    
    -- Output configuration
    response_template TEXT, -- optional template for response formatting
    merge_strategy VARCHAR(50) DEFAULT 'concatenate', -- how to combine region outputs
    
    -- Semantic embedding for pattern matching
    semantic_embedding vector(1536),
    
    -- Learning and adaptation
    base_priority DECIMAL(5,2) DEFAULT 50.0,
    learned_priority_adjustment DECIMAL(5,2) DEFAULT 0.0,
    success_count BIGINT DEFAULT 0,
    failure_count BIGINT DEFAULT 0,
    
    -- Status
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, slug)
);

-- Table: cognitive_routing_decisions
CREATE TABLE IF NOT EXISTS cognitive_routing_decisions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id UUID NOT NULL,
    query_hash VARCHAR(64) NOT NULL,
    query_preview TEXT,
    
    -- Economic Governor decision
    complexity_score FLOAT NOT NULL,
    original_model VARCHAR(100),
    selected_model VARCHAR(100) NOT NULL,
    routing_reason TEXT,
    
    -- Retrieval confidence from Ghost Memory
    retrieval_confidence FLOAT DEFAULT 1.0,
    ghost_hit BOOLEAN DEFAULT FALSE,
    semantic_key_matched TEXT,
    
    -- Routing outcome
    route_type VARCHAR(20) NOT NULL CHECK (route_type IN ('sniper', 'war_room', 'hitl')),
    fallback_triggered BOOLEAN DEFAULT FALSE,
    circuit_breaker_open BOOLEAN DEFAULT FALSE,
    
    -- Cost tracking
    estimated_cost_cents FLOAT,
    actual_cost_cents FLOAT,
    savings_cents FLOAT,
    
    -- Timing
    routing_latency_ms INTEGER,
    execution_latency_ms INTEGER,
    
    -- Metadata
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cognitive_sessions
CREATE TABLE IF NOT EXISTS cognitive_sessions (
    session_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    conversation_id UUID,
    
    -- Active blueprint
    active_blueprint_id UUID REFERENCES neural_blueprints(blueprint_id),
    
    -- Session state
    state JSONB DEFAULT '{}',
    active_regions TEXT[] DEFAULT '{}',
    
    -- Performance metrics
    total_region_activations INTEGER DEFAULT 0,
    total_tokens_used BIGINT DEFAULT 0,
    total_cost_cents INTEGER DEFAULT 0,
    avg_response_time_ms DECIMAL(10,2),
    
    -- Quality metrics
    user_satisfaction_scores DECIMAL(3,2)[] DEFAULT '{}',
    
    -- Lifecycle
    started_at TIMESTAMPTZ DEFAULT NOW(),
    last_activity_at TIMESTAMPTZ DEFAULT NOW(),
    ended_at TIMESTAMPTZ
);

-- Table: cognitive_working_memory
CREATE TABLE IF NOT EXISTS cognitive_working_memory (
    memory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    session_id UUID NOT NULL,
    user_id UUID NOT NULL,
    
    -- Memory content
    memory_type VARCHAR(50) NOT NULL, -- 'context', 'intermediate', 'decision', 'output'
    source_region VARCHAR(100), -- which brain region produced this
    content JSONB NOT NULL,
    
    -- Attention and relevance
    attention_weight DECIMAL(5,4) DEFAULT 1.0, -- how relevant to current task
    decay_rate DECIMAL(5,4) DEFAULT 0.1, -- how fast attention decays
    
    -- Embedding for semantic retrieval
    embedding vector(1536),
    
    -- Lifecycle
    created_at TIMESTAMPTZ DEFAULT NOW(),
    accessed_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '1 hour'
);

-- Table: cold_archive_manifest
CREATE TABLE IF NOT EXISTS cold_archive_manifest (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    table_name TEXT NOT NULL,
    partition_name TEXT,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    row_count BIGINT,
    compressed_size_bytes BIGINT,
    s3_bucket VARCHAR(255) NOT NULL,
    s3_key VARCHAR(500) NOT NULL,
    checksum VARCHAR(64),
    archived_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at DATE,
    status VARCHAR(20) DEFAULT 'active',  -- 'active', 'restored', 'expired'
    
    PRIMARY KEY (id)
);

-- Table: collaboration_attachments
CREATE TABLE IF NOT EXISTS collaboration_attachments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    message_id UUID REFERENCES session_messages(id) ON DELETE SET NULL,
    
    -- Uploader
    participant_id UUID REFERENCES session_participants(id),
    guest_id UUID REFERENCES collaboration_guests(id),
    
    -- File details
    file_name VARCHAR(255) NOT NULL,
    file_type VARCHAR(100) NOT NULL,
    file_size_bytes BIGINT NOT NULL,
    
    -- S3 storage
    s3_bucket VARCHAR(255) NOT NULL,
    s3_key VARCHAR(512) NOT NULL,
    s3_region VARCHAR(50) DEFAULT 'us-east-1',
    
    -- Thumbnail for images/videos
    thumbnail_s3_key VARCHAR(512),
    
    -- Processing status
    processing_status VARCHAR(20) DEFAULT 'uploaded' CHECK (processing_status IN (
        'uploading', 'uploaded', 'processing', 'ready', 'failed'
    )),
    processing_metadata JSONB DEFAULT '{}',
    
    -- Access tracking
    download_count INTEGER DEFAULT 0,
    last_accessed_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT require_uploader CHECK (participant_id IS NOT NULL OR guest_id IS NOT NULL)
);

-- Table: collaboration_facilitators
CREATE TABLE IF NOT EXISTS collaboration_facilitators (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- Facilitator settings
    is_enabled BOOLEAN DEFAULT true,
    facilitator_model VARCHAR(100) DEFAULT 'claude-3-5-sonnet',
    facilitator_persona VARCHAR(50) DEFAULT 'professional' CHECK (facilitator_persona IN (
        'professional', 'casual', 'academic', 'creative', 'socratic', 'coach'
    )),
    
    -- Facilitation behaviors
    auto_summarize BOOLEAN DEFAULT true,
    auto_action_items BOOLEAN DEFAULT true,
    ensure_participation BOOLEAN DEFAULT true,
    keep_on_topic BOOLEAN DEFAULT true,
    time_box_enabled BOOLEAN DEFAULT false,
    time_box_minutes INTEGER,
    
    -- Intervention thresholds
    silence_threshold_seconds INTEGER DEFAULT 120,
    tangent_detection_enabled BOOLEAN DEFAULT true,
    conflict_mediation_enabled BOOLEAN DEFAULT true,
    
    -- Session goals
    session_objective TEXT,
    session_agenda JSONB DEFAULT '[]',
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_session_facilitator UNIQUE (session_id)
);

-- Table: collaboration_guest_invites
CREATE TABLE IF NOT EXISTS collaboration_guest_invites (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- Invite details
    invite_token VARCHAR(64) UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
    invite_type VARCHAR(20) NOT NULL DEFAULT 'link' CHECK (invite_type IN ('email', 'link', 'qr')),
    
    -- Guest info (for email invites)
    guest_email VARCHAR(255),
    guest_name VARCHAR(255),
    
    -- Access control
    permission VARCHAR(20) NOT NULL DEFAULT 'commenter' CHECK (permission IN ('viewer', 'commenter', 'editor')),
    expires_at TIMESTAMPTZ,
    max_uses INTEGER DEFAULT 1,
    current_uses INTEGER DEFAULT 0,
    
    -- Tracking
    created_by UUID NOT NULL REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    last_used_at TIMESTAMPTZ,
    
    -- Referral tracking for viral growth
    referral_code VARCHAR(32) UNIQUE DEFAULT encode(gen_random_bytes(16), 'hex'),
    signups_from_invite INTEGER DEFAULT 0
);

-- Table: collaboration_guests
CREATE TABLE IF NOT EXISTS collaboration_guests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    invite_id UUID NOT NULL REFERENCES collaboration_guest_invites(id) ON DELETE CASCADE,
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- Guest identity
    guest_token VARCHAR(64) UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
    display_name VARCHAR(100) NOT NULL,
    email VARCHAR(255),
    avatar_url TEXT,
    
    -- Optional user link (if they sign up)
    linked_user_id UUID REFERENCES users(id),
    linked_tenant_id UUID REFERENCES tenants(id),
    
    -- Permissions
    permission VARCHAR(20) NOT NULL DEFAULT 'commenter',
    
    -- Presence
    is_online BOOLEAN DEFAULT false,
    last_seen_at TIMESTAMPTZ,
    color VARCHAR(7),
    
    -- Session state
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    left_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: collaboration_history
CREATE TABLE IF NOT EXISTS collaboration_history (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    room_id UUID NOT NULL REFERENCES collaboration_rooms(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    action_type VARCHAR(50) NOT NULL,
    action_data JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: collaboration_participants
CREATE TABLE IF NOT EXISTS collaboration_participants (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaboration_sessions(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    display_name VARCHAR(200),
    color VARCHAR(20),
    cursor_position JSONB,
    selection JSONB,
    is_online BOOLEAN DEFAULT true,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    last_active_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(session_id, user_id)
);

-- Table: collaboration_patterns
CREATE TABLE IF NOT EXISTS collaboration_patterns (
    pattern_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Pattern identity
    name VARCHAR(100) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    description TEXT,
    pattern_type VARCHAR(50) NOT NULL, -- 'debate', 'consensus', 'divide_conquer', 'pipeline', 'swarm', 'custom'
    
    -- Configuration
    required_roles TEXT[] NOT NULL,
    optional_roles TEXT[] DEFAULT '{}',
    min_agents INTEGER DEFAULT 2,
    max_agents INTEGER,
    
    -- Protocol definition
    phases JSONB NOT NULL, -- [{name, description, participating_roles, success_criteria}]
    message_flow JSONB DEFAULT '{}', -- How messages flow between agents
    termination_conditions JSONB DEFAULT '{}',
    
    -- Default settings
    max_rounds INTEGER DEFAULT 10,
    consensus_threshold DECIMAL(3,2) DEFAULT 0.7,
    timeout_ms INTEGER DEFAULT 300000,
    
    -- Performance tracking
    times_used INTEGER DEFAULT 0,
    avg_success_rate DECIMAL(5,4),
    avg_rounds_to_completion DECIMAL(6,2),
    
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: collaboration_rooms
CREATE TABLE IF NOT EXISTS collaboration_rooms (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    room_name VARCHAR(100) NOT NULL,
    room_type VARCHAR(50) NOT NULL DEFAULT 'document' CHECK (room_type IN ('document', 'canvas', 'whiteboard', 'code')),
    created_by UUID NOT NULL REFERENCES users(id),
    yjs_document BYTEA,
    is_active BOOLEAN DEFAULT true,
    max_participants INTEGER DEFAULT 10 CHECK (max_participants >= 1 AND max_participants <= 50),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: collaboration_sessions
CREATE TABLE IF NOT EXISTS collaboration_sessions (
    session_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    cognitive_session_id UUID, -- Link to cognitive brain session
    
    -- Session metadata
    goal TEXT NOT NULL,
    goal_embedding vector(1536),
    context JSONB DEFAULT '{}',
    
    -- Collaboration configuration
    collaboration_pattern VARCHAR(50) NOT NULL, -- 'debate', 'consensus', 'divide_conquer', 'pipeline', 'swarm'
    participating_agents UUID[] NOT NULL,
    lead_agent_id UUID REFERENCES cognitive_agents(agent_id),
    
    -- Shared context (accessible to all agents)
    shared_memory JSONB DEFAULT '{}',
    shared_artifacts JSONB DEFAULT '[]', -- [{type, content, created_by, timestamp}]
    shared_decisions JSONB DEFAULT '[]', -- [{decision, rationale, made_by, agreed_by, timestamp}]
    
    -- Progress tracking
    status VARCHAR(20) DEFAULT 'active', -- 'active', 'paused', 'completed', 'failed', 'cancelled'
    current_phase VARCHAR(50),
    phases_completed TEXT[] DEFAULT '{}',
    progress_percentage DECIMAL(5,2) DEFAULT 0,
    
    -- Results
    final_output TEXT,
    final_confidence DECIMAL(5,4),
    consensus_reached BOOLEAN,
    dissenting_agents UUID[],
    
    -- Metrics
    total_messages INTEGER DEFAULT 0,
    total_rounds INTEGER DEFAULT 0,
    total_tokens_used INTEGER DEFAULT 0,
    total_cost_cents INTEGER DEFAULT 0,
    duration_ms INTEGER,
    
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: collaboration_updates
CREATE TABLE IF NOT EXISTS collaboration_updates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaboration_sessions(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    update_type VARCHAR(30) NOT NULL CHECK (update_type IN ('insert', 'delete', 'format', 'cursor', 'selection')),
    payload JSONB NOT NULL,
    vector_clock JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: collaborative_sessions
CREATE TABLE IF NOT EXISTS collaborative_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    conversation_id UUID NOT NULL REFERENCES thinktank_conversations(id) ON DELETE CASCADE,
    owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Session metadata
    name VARCHAR(255),
    description TEXT,
    color VARCHAR(7) DEFAULT '#6366f1', -- Session accent color
    
    -- Access settings
    access_type VARCHAR(20) DEFAULT 'invite' CHECK (access_type IN ('invite', 'link', 'public')),
    link_token VARCHAR(64) UNIQUE,
    default_permission VARCHAR(20) DEFAULT 'viewer' CHECK (default_permission IN ('viewer', 'commenter', 'editor')),
    
    -- Session state
    is_active BOOLEAN DEFAULT true,
    max_participants INTEGER DEFAULT 50,
    allow_anonymous BOOLEAN DEFAULT false,
    require_approval BOOLEAN DEFAULT false,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    last_activity_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_conversation_session UNIQUE (conversation_id)
);

-- Table: common_sense_facts
CREATE TABLE IF NOT EXISTS common_sense_facts (
    fact_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE, -- NULL for global facts
    
    -- Fact content
    subject TEXT NOT NULL,
    predicate TEXT NOT NULL,
    object TEXT NOT NULL,
    
    -- Fact type
    fact_type VARCHAR(50) NOT NULL, -- 'physical', 'social', 'temporal', 'spatial', 'causal', 'functional'
    
    -- Confidence and source
    confidence DECIMAL(5,4) DEFAULT 1.0,
    source VARCHAR(50), -- 'curated', 'extracted', 'inferred', 'crowdsourced'
    
    -- Qualifications
    context_restrictions JSONB DEFAULT '{}',
    exceptions JSONB DEFAULT '[]',
    temporal_scope VARCHAR(50), -- 'always', 'usually', 'sometimes', 'historically'
    
    -- Usage
    times_used INTEGER DEFAULT 0,
    times_helpful INTEGER DEFAULT 0,
    
    -- Embedding for retrieval
    fact_embedding vector(1536),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: complexity_gradients
CREATE TABLE IF NOT EXISTS complexity_gradients (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES cognitive_load_sessions(id) ON DELETE CASCADE,
    content_id VARCHAR(255) NOT NULL,
    position JSONB NOT NULL,
    complexity_score INTEGER NOT NULL CHECK (complexity_score >= 0 AND complexity_score <= 100),
    suggested_action VARCHAR(50),
    visual_style JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: compliance_audit_results
CREATE TABLE IF NOT EXISTS compliance_audit_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    run_id UUID NOT NULL REFERENCES compliance_audit_runs(id) ON DELETE CASCADE,
    check_code VARCHAR(100) NOT NULL,
    check_name VARCHAR(300) NOT NULL,
    category VARCHAR(100) NOT NULL,
    control_type VARCHAR(50),
    is_required BOOLEAN NOT NULL DEFAULT true,
    status VARCHAR(30) NOT NULL CHECK (status IN ('passed', 'failed', 'skipped', 'error')),
    details TEXT,
    evidence JSONB,
    remediation TEXT,
    duration_ms INTEGER,
    executed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: compliance_audit_runs
CREATE TABLE IF NOT EXISTS compliance_audit_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    framework VARCHAR(50) NOT NULL,
    run_type VARCHAR(30) NOT NULL DEFAULT 'manual' CHECK (run_type IN ('manual', 'scheduled', 'triggered')),
    status VARCHAR(30) NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'completed', 'failed', 'cancelled')),
    total_checks INTEGER NOT NULL DEFAULT 0,
    passed_checks INTEGER NOT NULL DEFAULT 0,
    failed_checks INTEGER NOT NULL DEFAULT 0,
    skipped_checks INTEGER NOT NULL DEFAULT 0,
    score INTEGER DEFAULT 0 CHECK (score >= 0 AND score <= 100),
    duration_ms INTEGER,
    triggered_by VARCHAR(200),
    error_message TEXT,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: compliance_audit_schedules
CREATE TABLE IF NOT EXISTS compliance_audit_schedules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    framework VARCHAR(50) NOT NULL,
    schedule_type VARCHAR(30) NOT NULL CHECK (schedule_type IN ('daily', 'weekly', 'monthly', 'quarterly')),
    day_of_week INTEGER CHECK (day_of_week >= 0 AND day_of_week <= 6),
    day_of_month INTEGER CHECK (day_of_month >= 1 AND day_of_month <= 28),
    hour_utc INTEGER NOT NULL DEFAULT 2 CHECK (hour_utc >= 0 AND hour_utc <= 23),
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    notify_on_failure BOOLEAN NOT NULL DEFAULT true,
    notify_emails TEXT[],
    last_run_at TIMESTAMPTZ,
    next_run_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, framework)
);

-- Table: compliance_checklist_categories
CREATE TABLE IF NOT EXISTS compliance_checklist_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    version_id UUID NOT NULL REFERENCES compliance_checklist_versions(id) ON DELETE CASCADE,
    code VARCHAR(50) NOT NULL,
    name VARCHAR(200) NOT NULL,
    description TEXT,
    display_order INTEGER NOT NULL DEFAULT 0,
    icon VARCHAR(50),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(version_id, code)
);

-- Table: compliance_checklist_items
CREATE TABLE IF NOT EXISTS compliance_checklist_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    version_id UUID NOT NULL REFERENCES compliance_checklist_versions(id) ON DELETE CASCADE,
    category_id UUID REFERENCES compliance_checklist_categories(id) ON DELETE SET NULL,
    requirement_id UUID REFERENCES regulatory_requirements(id) ON DELETE SET NULL,
    item_code VARCHAR(50) NOT NULL,
    title VARCHAR(500) NOT NULL,
    description TEXT,
    guidance TEXT,
    evidence_types TEXT[], -- ['document', 'screenshot', 'config', 'log', 'attestation']
    api_endpoint VARCHAR(500), -- API endpoint for automated evidence collection
    automated_check_code VARCHAR(100), -- Link to system_audit_checks.check_code
    is_required BOOLEAN NOT NULL DEFAULT true,
    is_automatable BOOLEAN NOT NULL DEFAULT false,
    priority VARCHAR(20) NOT NULL DEFAULT 'medium' CHECK (priority IN ('critical', 'high', 'medium', 'low')),
    estimated_minutes INTEGER,
    display_order INTEGER NOT NULL DEFAULT 0,
    tags TEXT[],
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(version_id, item_code)
);

-- Table: compliance_checklist_versions
CREATE TABLE IF NOT EXISTS compliance_checklist_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    standard_id UUID NOT NULL REFERENCES regulatory_standards(id) ON DELETE CASCADE,
    version VARCHAR(50) NOT NULL,
    version_date DATE NOT NULL,
    title VARCHAR(300) NOT NULL,
    description TEXT,
    source_url VARCHAR(500),
    source_document VARCHAR(300),
    is_latest BOOLEAN NOT NULL DEFAULT false,
    is_active BOOLEAN NOT NULL DEFAULT true,
    change_summary TEXT,
    effective_date DATE,
    supersedes_version_id UUID REFERENCES compliance_checklist_versions(id),
    created_by VARCHAR(200),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(standard_id, version)
);

-- Table: compliance_evidence
CREATE TABLE IF NOT EXISTS compliance_evidence (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    requirement_id UUID NOT NULL REFERENCES regulatory_requirements(id) ON DELETE CASCADE,
    evidence_type VARCHAR(50) NOT NULL CHECK (evidence_type IN ('document', 'screenshot', 'log', 'config', 'attestation', 'audit_report', 'policy', 'procedure')),
    title VARCHAR(300) NOT NULL,
    description TEXT,
    file_path VARCHAR(500),
    file_hash VARCHAR(128),
    uploaded_by VARCHAR(200),
    valid_from DATE,
    valid_until DATE,
    is_current BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: compliance_findings
CREATE TABLE IF NOT EXISTS compliance_findings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    report_id UUID NOT NULL REFERENCES compliance_reports(id) ON DELETE CASCADE,
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('critical', 'high', 'medium', 'low')),
    category VARCHAR(100) NOT NULL,
    description TEXT NOT NULL,
    recommendation TEXT,
    status VARCHAR(20) DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'resolved')),
    resolved_at TIMESTAMPTZ,
    resolved_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: compliance_policy_history
CREATE TABLE IF NOT EXISTS compliance_policy_history (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    policy_id UUID NOT NULL REFERENCES tenant_compliance_policies(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL,
    policy_text TEXT NOT NULL,
    rules_json JSONB,
    version INTEGER NOT NULL,
    changed_by UUID,
    change_reason TEXT,
    changed_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: compliance_reports
CREATE TABLE IF NOT EXISTS compliance_reports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    report_type VARCHAR(30) NOT NULL CHECK (report_type IN ('soc2', 'hipaa', 'gdpr', 'iso27001')),
    status VARCHAR(20) DEFAULT 'compliant' CHECK (status IN ('compliant', 'partial', 'non_compliant')),
    score INTEGER DEFAULT 100,
    findings JSONB DEFAULT '[]',
    generated_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '90 days'
);

-- Table: component_load_events
CREATE TABLE IF NOT EXISTS component_load_events (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    component_id UUID NOT NULL REFERENCES inference_components(component_id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    
    -- Event details
    event_type VARCHAR(50) NOT NULL,
    priority VARCHAR(20) NOT NULL DEFAULT 'normal',
    requester_user_id VARCHAR(255),
    reason TEXT,
    
    -- Result
    success BOOLEAN NOT NULL DEFAULT false,
    load_time_ms INTEGER,
    from_cache BOOLEAN NOT NULL DEFAULT false,
    error_message TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT valid_event_type CHECK (event_type IN ('load', 'unload', 'preload', 'evict')),
    CONSTRAINT valid_priority CHECK (priority IN ('low', 'normal', 'high', 'urgent'))
);

-- Table: concept_ontology
CREATE TABLE IF NOT EXISTS concept_ontology (
    concept_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Concept definition
    name VARCHAR(200) NOT NULL,
    concept_type VARCHAR(50), -- 'class', 'instance', 'property', 'relation'
    
    -- Hierarchy
    parent_id UUID REFERENCES concept_ontology(concept_id),
    children_ids UUID[] DEFAULT '{}',
    
    -- Properties
    properties JSONB DEFAULT '{}',
    constraints JSONB DEFAULT '{}',
    
    -- Neural grounding
    concept_embedding vector(1536),
    prototype_examples JSONB DEFAULT '[]',
    
    -- Relationships
    related_concepts JSONB DEFAULT '[]', -- [{concept_id, relation_type, strength}]
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: conceptual_blends
CREATE TABLE IF NOT EXISTS conceptual_blends (
    blend_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Input spaces
    input_space_1 JSONB NOT NULL, -- First concept
    input_space_2 JSONB NOT NULL, -- Second concept
    
    -- Generic space (shared structure)
    generic_space JSONB DEFAULT '{}',
    
    -- Blended space (emergent structure)
    blended_space JSONB NOT NULL,
    emergent_structure JSONB DEFAULT '[]', -- What's new in the blend
    
    -- Quality
    integration_quality DECIMAL(3,2),
    web_coherence DECIMAL(3,2),
    unpacking_ease DECIMAL(3,2),
    relevance DECIMAL(3,2),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: concurrent_execution_config
CREATE TABLE IF NOT EXISTS concurrent_execution_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT true,
    max_panes INTEGER NOT NULL DEFAULT 4 CHECK (max_panes BETWEEN 1 AND 8),
    max_concurrent_tasks INTEGER NOT NULL DEFAULT 4 CHECK (max_concurrent_tasks BETWEEN 1 AND 10),
    max_queue_depth INTEGER NOT NULL DEFAULT 20 CHECK (max_queue_depth BETWEEN 1 AND 100),
    default_layout VARCHAR(50) NOT NULL DEFAULT 'horizontal-2',
    default_sync_mode VARCHAR(50) NOT NULL DEFAULT 'independent',
    enable_comparison BOOLEAN NOT NULL DEFAULT true,
    enable_merge BOOLEAN NOT NULL DEFAULT true,
    websocket_max_streams INTEGER NOT NULL DEFAULT 4,
    websocket_heartbeat_interval INTEGER NOT NULL DEFAULT 30000,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: concurrent_execution_metrics
CREATE TABLE IF NOT EXISTS concurrent_execution_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period VARCHAR(50) NOT NULL,
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    total_tasks INTEGER NOT NULL DEFAULT 0,
    concurrent_peak_tasks INTEGER NOT NULL DEFAULT 0,
    average_concurrency DECIMAL(5,2) NOT NULL DEFAULT 0,
    tasks_by_type JSONB NOT NULL DEFAULT '{}',
    average_latency_ms INTEGER NOT NULL DEFAULT 0,
    total_cost_usd DECIMAL(10,4) NOT NULL DEFAULT 0,
    comparisons_made INTEGER NOT NULL DEFAULT 0,
    merges_performed INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, period, period_start)
);

-- Table: concurrent_panes
CREATE TABLE IF NOT EXISTS concurrent_panes (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES concurrent_sessions(id) ON DELETE CASCADE,
    pane_index INTEGER NOT NULL CHECK (pane_index >= 0),
    chat_id UUID,
    model VARCHAR(100),
    status VARCHAR(20) DEFAULT 'idle' CHECK (status IN ('idle', 'streaming', 'error', 'complete')),
    last_activity TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(session_id, pane_index)
);

-- Table: concurrent_sessions
CREATE TABLE IF NOT EXISTS concurrent_sessions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_name VARCHAR(100),
    layout_config JSONB NOT NULL DEFAULT '{"type": "horizontal", "panes": []}',
    max_panes INTEGER DEFAULT 4 CHECK (max_panes >= 1 AND max_panes <= 8),
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: concurrent_sync_state
CREATE TABLE IF NOT EXISTS concurrent_sync_state (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES concurrent_sessions(id) ON DELETE CASCADE UNIQUE,
    sync_mode VARCHAR(20) NOT NULL DEFAULT 'independent' CHECK (sync_mode IN ('independent', 'synchronized', 'broadcast')),
    shared_context TEXT,
    sync_cursor INTEGER DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: concurrent_tasks
CREATE TABLE IF NOT EXISTS concurrent_tasks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    session_id UUID NOT NULL,
    pane_id VARCHAR(100) NOT NULL,
    status VARCHAR(50) NOT NULL DEFAULT 'queued',
    task_type VARCHAR(50) NOT NULL,
    priority VARCHAR(20) NOT NULL DEFAULT 'normal',
    prompt TEXT NOT NULL,
    model_id VARCHAR(100),
    result JSONB,
    progress JSONB NOT NULL DEFAULT '{"percentage": 0, "stage": "queued"}',
    metadata JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    CONSTRAINT valid_status CHECK (status IN ('queued', 'running', 'streaming', 'completed', 'failed', 'cancelled')),
    CONSTRAINT valid_task_type CHECK (task_type IN ('chat', 'analysis', 'generation', 'comparison', 'research', 'coding')),
    CONSTRAINT valid_priority CHECK (priority IN ('low', 'normal', 'high', 'critical'))
);

-- Table: confidence_assessments
CREATE TABLE IF NOT EXISTS confidence_assessments (
    assessment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Context
    request_id UUID,
    task_type VARCHAR(100),
    domain VARCHAR(100),
    
    -- Prediction
    predicted_answer TEXT,
    stated_confidence DECIMAL(5,4), -- What the model said
    
    -- Calibration
    calibrated_confidence DECIMAL(5,4), -- Adjusted confidence
    calibration_adjustment DECIMAL(5,4), -- How much we adjusted
    
    -- Verification (if available)
    was_correct BOOLEAN,
    actual_answer TEXT,
    
    -- Uncertainty sources
    uncertainty_sources JSONB DEFAULT '[]', -- Why uncertain
    knowledge_gaps JSONB DEFAULT '[]', -- What's missing
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: confidence_calibration
CREATE TABLE IF NOT EXISTS confidence_calibration (
    calibration_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Domain
    domain VARCHAR(100) NOT NULL,
    task_type VARCHAR(100),
    
    -- Calibration data
    confidence_buckets JSONB DEFAULT '{}', -- {bucket: {predicted_confidence, actual_accuracy, sample_count}}
    
    -- Overall metrics
    brier_score DECIMAL(5,4),
    calibration_error DECIMAL(5,4),
    overconfidence_bias DECIMAL(5,4),
    
    -- Recommendations
    confidence_adjustment DECIMAL(5,4) DEFAULT 0, -- How much to adjust raw confidence
    
    last_updated TIMESTAMPTZ DEFAULT NOW()
);

-- Table: config_audit_log
CREATE TABLE IF NOT EXISTS config_audit_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    config_id UUID REFERENCES system_config(id),
    tenant_id UUID REFERENCES tenants(id),
    action VARCHAR(20) NOT NULL CHECK (action IN ('create', 'update', 'delete', 'override')),
    old_value JSONB,
    new_value JSONB,
    changed_by UUID,
    changed_at TIMESTAMPTZ DEFAULT NOW(),
    change_reason TEXT,
