-- Table: consent_records
CREATE TABLE IF NOT EXISTS consent_records (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Jurisdiction and purpose
  jurisdiction VARCHAR(10) NOT NULL,
  purpose_code VARCHAR(50) NOT NULL,
  purpose_description TEXT NOT NULL,
  
  -- Legal basis (GDPR Article 6)
  lawful_basis VARCHAR(50) NOT NULL CHECK (
    lawful_basis IN ('consent', 'contract', 'legal_obligation', 'vital_interests', 'public_interest', 'legitimate_interests')
  ),
  
  -- Consent state
  consent_given BOOLEAN NOT NULL,
  consent_timestamp TIMESTAMPTZ NOT NULL,
  consent_version VARCHAR(20) NOT NULL,
  consent_method VARCHAR(50) NOT NULL CHECK (
    consent_method IN ('explicit_checkbox', 'click_accept', 'implicit', 'parent_consent', 'verified_parent', 'double_opt_in')
  ),
  consent_language VARCHAR(10) NOT NULL,
  consent_ip_address INET,
  consent_user_agent TEXT,
  
  -- Third-party disclosure (CCPA/CPRA)
  third_party_sharing_authorized BOOLEAN DEFAULT false,
  authorized_third_parties JSONB,
  sale_of_data_authorized BOOLEAN DEFAULT false,
  
  -- Withdrawal
  withdrawal_timestamp TIMESTAMPTZ,
  withdrawal_method VARCHAR(50),
  withdrawal_reason TEXT,
  
  -- COPPA fields
  parent_guardian_id UUID REFERENCES users(id),
  verification_method VARCHAR(50) CHECK (
    verification_method IS NULL OR verification_method IN (
      'credit_card', 'video_conference', 'signed_form', 'government_id', 'knowledge_based', 'toll_free_call'
    )
  ),
  verification_completed_at TIMESTAMPTZ,
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: constitutional_classifiers
CREATE TABLE IF NOT EXISTS constitutional_classifiers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    classifier_name VARCHAR(255) NOT NULL,
    classifier_version VARCHAR(50) NOT NULL,
    model_type VARCHAR(100) NOT NULL, -- 'harmbench_llama', 'custom_bert', 'ensemble'
    
    -- Model configuration
    model_config JSONB DEFAULT '{}',
    harm_categories TEXT[] DEFAULT '{}', -- Which categories this classifier handles
    
    -- Performance metrics
    precision_score DOUBLE PRECISION,
    recall_score DOUBLE PRECISION,
    f1_score DOUBLE PRECISION,
    false_positive_rate DOUBLE PRECISION,
    
    -- Training metadata
    training_dataset VARCHAR(255), -- 'harmbench', 'wildjailbreak', 'custom'
    training_samples INTEGER,
    last_trained_at TIMESTAMPTZ,
    
    -- Status
    status VARCHAR(50) DEFAULT 'active', -- 'active', 'training', 'deprecated'
    is_default BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_tenant_classifier UNIQUE (tenant_id, classifier_name, classifier_version)
);

-- Table: context_profiles
CREATE TABLE IF NOT EXISTS context_profiles (
    profile_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Profile definition
    name VARCHAR(200) NOT NULL,
    context_type VARCHAR(50) NOT NULL, -- 'user', 'domain', 'task', 'channel', 'time'
    
    -- Context characteristics
    characteristics JSONB NOT NULL,
    
    -- Adaptation rules
    style_adaptations JSONB DEFAULT '{}', -- How to adapt response style
    content_adaptations JSONB DEFAULT '{}', -- What content to include/exclude
    format_adaptations JSONB DEFAULT '{}', -- How to format responses
    
    -- When to apply
    activation_conditions JSONB DEFAULT '{}',
    priority INTEGER DEFAULT 5,
    
    -- Stats
    times_applied INTEGER DEFAULT 0,
    effectiveness_score DECIMAL(5,4),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: context_transitions
CREATE TABLE IF NOT EXISTS context_transitions (
