    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Transition
    from_context JSONB NOT NULL,
    to_context JSONB NOT NULL,
    trigger TEXT,
    
    -- Timing
    transition_time TIMESTAMPTZ DEFAULT NOW(),
    
    -- Quality
    smoothness DECIMAL(3,2), -- How smooth was the transition
    user_noticed BOOLEAN DEFAULT false
);

-- Table: contraindication_overrides
CREATE TABLE IF NOT EXISTS contraindication_overrides (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    contraindication_id UUID NOT NULL REFERENCES contraindications(id) ON DELETE CASCADE,
    
    -- Context
    user_id VARCHAR(255) NOT NULL,
    session_id UUID,
    request_id UUID,
    
    -- Override details
    reason TEXT NOT NULL,
    documentation TEXT,
    supervisor_id VARCHAR(255),
    specialist_id VARCHAR(255),
    
    -- Outcome
    outcome VARCHAR(20) DEFAULT 'approved' CHECK (outcome IN ('approved', 'denied', 'escalated')),
    outcome_notes TEXT,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMPTZ
);

-- Table: contraindications
CREATE TABLE IF NOT EXISTS contraindications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    domain_id VARCHAR(100) NOT NULL,
    
    -- The contraindication pair
    entity_id UUID NOT NULL REFERENCES safety_entities(id) ON DELETE CASCADE,
    action_id UUID NOT NULL REFERENCES safety_actions(id) ON DELETE CASCADE,
    
    -- Optional second entity (for entity+entity contraindications)
    second_entity_id UUID REFERENCES safety_entities(id) ON DELETE SET NULL,
    
    -- Severity
    severity contraindication_severity NOT NULL DEFAULT 'caution',
    
    -- Details
    reason TEXT NOT NULL,
    clinical_evidence TEXT,
    regulatory_reference TEXT,
    
    -- Conditions (when the contraindication applies)
    conditions JSONB DEFAULT '[]'::jsonb,
    
    -- Exceptions (when the contraindication does NOT apply)
    exceptions JSONB DEFAULT '[]'::jsonb,
    
    -- Alternative suggestions
    alternatives JSONB DEFAULT '[]'::jsonb,
    
    -- Override policy
    allow_override BOOLEAN DEFAULT false,
    override_requires VARCHAR(20) DEFAULT 'none' CHECK (override_requires IN ('documentation', 'supervisor', 'specialist', 'none')),
    
    -- ML model (if detected by Contraindication Net)
    ml_confidence DECIMAL(5, 4),
    ml_model_version VARCHAR(50),
    
    -- Status
    status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'pending_review', 'deprecated', 'rejected')),
    effective_date DATE,
    expiration_date DATE,
    
    -- Review
    reviewed_at TIMESTAMPTZ,
    reviewed_by VARCHAR(255),
    review_notes TEXT,
    
    -- Audit
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(255) NOT NULL,
    
    CONSTRAINT uq_contraindication UNIQUE (tenant_id, entity_id, action_id, second_entity_id)
);

-- Table: conversation_branches
CREATE TABLE IF NOT EXISTS conversation_branches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- Branch metadata
    branch_name VARCHAR(100) NOT NULL,
    branch_description TEXT,
    branch_color VARCHAR(7) DEFAULT '#6366f1',
    
    -- Parent branch (null for main)
    parent_branch_id UUID REFERENCES conversation_branches(id) ON DELETE SET NULL,
    fork_point_message_id UUID REFERENCES session_messages(id) ON DELETE SET NULL,
    
    -- Branch owner
    created_by UUID NOT NULL REFERENCES session_participants(id),
    
    -- Status
    status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'merged', 'abandoned', 'archived')),
    merged_into_id UUID REFERENCES conversation_branches(id),
    merged_at TIMESTAMPTZ,
    merged_by UUID REFERENCES session_participants(id),
    
    -- Exploration tracking
    exploration_hypothesis TEXT,
    exploration_conclusion TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: conversation_learning
CREATE TABLE IF NOT EXISTS conversation_learning (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    conversation_id UUID NOT NULL,
    
    -- Conversation summary
    message_count INTEGER NOT NULL,
    total_tokens INTEGER,
    domains_discussed TEXT[] DEFAULT '{}',
    
    -- Outcome signals
    conversation_rating INTEGER CHECK (conversation_rating BETWEEN -5 AND 5),
    goal_achieved BOOLEAN,
    user_satisfaction_inferred NUMERIC(3,2), -- -1 to 1
    
    -- Signals aggregated from messages
    positive_signals_count INTEGER NOT NULL DEFAULT 0,
    negative_signals_count INTEGER NOT NULL DEFAULT 0,
    corrections_count INTEGER NOT NULL DEFAULT 0,
    regenerations_count INTEGER NOT NULL DEFAULT 0,
    
    -- Learning value
    learning_value_score NUMERIC(3,2), -- How valuable for training
    selected_for_training BOOLEAN DEFAULT false,
    
    -- Key interactions to learn from
    best_interaction_ids UUID[] DEFAULT '{}',
    worst_interaction_ids UUID[] DEFAULT '{}',
    
    -- Timing
    conversation_start TIMESTAMPTZ NOT NULL,
    conversation_end TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: conversation_turns
CREATE TABLE IF NOT EXISTS conversation_turns (
