-- Table: conversion_outcome_feedback
CREATE TABLE IF NOT EXISTS conversion_outcome_feedback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Reference to conversion
    conversion_id UUID NOT NULL,
    conversation_id UUID,
    
    -- Model information
    model_id VARCHAR(200) NOT NULL,
    provider_id VARCHAR(100) NOT NULL,
    
    -- File information
    filename VARCHAR(500) NOT NULL,
    file_format VARCHAR(50) NOT NULL,
    file_size BIGINT,
    
    -- What action was taken
    action_taken VARCHAR(50) NOT NULL, -- 'pass_original', 'convert', 'skip'
    conversion_strategy VARCHAR(50),
    
    -- Outcome feedback
    outcome VARCHAR(50) NOT NULL, -- 'success', 'partial', 'failure', 'unknown'
    outcome_source VARCHAR(50) NOT NULL, -- 'user_feedback', 'model_response', 'error_detection', 'auto_inferred'
    
    -- Detailed feedback
    user_rating INTEGER CHECK (user_rating >= 1 AND user_rating <= 5),
    user_feedback TEXT,
    
    -- Model's response quality indicators
    model_understood BOOLEAN, -- Did the model understand the content?
    model_hallucinated BOOLEAN, -- Did the model make up content?
    model_asked_for_clarification BOOLEAN,
    model_mentioned_format_issues BOOLEAN,
    
    -- Error information
    error_type VARCHAR(100),
    error_message TEXT,
    
    -- Learning candidate created?
    learning_candidate_id UUID,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Ensure one feedback per conversion/model combination
    UNIQUE(conversion_id, model_id)
);

-- Table: correction_patterns
CREATE TABLE IF NOT EXISTS correction_patterns (
    pattern_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Pattern
    pattern_type VARCHAR(50) NOT NULL, -- 'factual_error', 'style_mismatch', 'missing_info', 'wrong_format'
    pattern_description TEXT,
    
    -- Detection
    trigger_conditions JSONB DEFAULT '{}',
    example_corrections JSONB DEFAULT '[]',
    
    -- Correction
    correction_strategy TEXT,
    auto_correct BOOLEAN DEFAULT false,
    
    -- Stats
    occurrence_count INTEGER DEFAULT 0,
    correction_success_rate DECIMAL(5,4),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cortex_activity_log
CREATE TABLE IF NOT EXISTS cortex_activity_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    activity_type VARCHAR(50) NOT NULL,
    description TEXT NOT NULL,
    user_id UUID,
    
    metadata JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_audit_trail
CREATE TABLE IF NOT EXISTS cortex_audit_trail (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    chain_of_custody_id UUID NOT NULL REFERENCES cortex_chain_of_custody(id) ON DELETE CASCADE,
    action VARCHAR(20) NOT NULL CHECK (action IN ('created', 'verified', 'updated', 'superseded', 'deleted')),
    performed_by VARCHAR(255) NOT NULL,
    performed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    previous_value TEXT,
    new_value TEXT,
    reason TEXT,
    signature VARCHAR(128) NOT NULL
);

-- Table: cortex_chain_of_custody
CREATE TABLE IF NOT EXISTS cortex_chain_of_custody (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    fact_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source TEXT NOT NULL,
    source_type VARCHAR(20) NOT NULL CHECK (source_type IN ('document', 'graph_node', 'golden_rule', 'telemetry', 'user_input')),
    extracted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    extracted_by VARCHAR(255),
    verified_by VARCHAR(255),
    verified_at TIMESTAMPTZ,
    signature VARCHAR(128),
    supersedes UUID[],
    metadata JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_chunks
CREATE TABLE IF NOT EXISTS cortex_chunks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    entity_id UUID REFERENCES cortex_entities(id) ON DELETE SET NULL,
    
    content TEXT NOT NULL,
    content_hash VARCHAR(64) NOT NULL,
    
    -- Vector embedding
    embedding vector(1536) NOT NULL,
    embedding_model VARCHAR(100) NOT NULL,
    
    -- Metadata
    document_id UUID,
    conversation_id UUID,
    message_id UUID,
    page_number INTEGER,
    section_title VARCHAR(500),
    language VARCHAR(10) DEFAULT 'en',
    word_count INTEGER NOT NULL,
    token_count INTEGER NOT NULL,
    
    -- Source tracking
    source_type VARCHAR(50) NOT NULL,
    source_id UUID,
    source_url TEXT,
    source_timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    source_user_id UUID,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_cold_archives
CREATE TABLE IF NOT EXISTS cortex_cold_archives (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    original_tier VARCHAR(10) NOT NULL CHECK (original_tier IN ('hot', 'warm')),
    original_table_name VARCHAR(100) NOT NULL,
    archive_reason VARCHAR(50) NOT NULL CHECK (archive_reason IN ('age', 'manual', 'gdpr', 'retention_policy')),
    s3_key VARCHAR(1000) NOT NULL,
    iceberg_table_name VARCHAR(255),
    partition_values JSONB DEFAULT '{}',
    record_count INTEGER NOT NULL,
    size_bytes BIGINT NOT NULL,
    checksum VARCHAR(64) NOT NULL,
    storage_class VARCHAR(50) DEFAULT 'STANDARD',
    archived_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    retrievable_until TIMESTAMPTZ,
    last_accessed_at TIMESTAMPTZ
);

-- Table: cortex_config
CREATE TABLE IF NOT EXISTS cortex_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Feature toggles
    enable_graph_rag BOOLEAN NOT NULL DEFAULT true,
    enable_entity_extraction BOOLEAN NOT NULL DEFAULT true,
    enable_relationship_inference BOOLEAN NOT NULL DEFAULT true,
    enable_temporal_tracking BOOLEAN NOT NULL DEFAULT true,
    enable_auto_merge BOOLEAN NOT NULL DEFAULT true,
    
    -- Model configuration
    embedding_model VARCHAR(100) NOT NULL DEFAULT 'text-embedding-3-small',
    embedding_dimensions INTEGER NOT NULL DEFAULT 1536,
    entity_extraction_model VARCHAR(100) NOT NULL DEFAULT 'gpt-4o-mini',
    reranking_model VARCHAR(100),
    
    -- Chunking configuration
    default_chunk_size INTEGER NOT NULL DEFAULT 512,
    default_chunk_overlap INTEGER NOT NULL DEFAULT 50,
    max_chunks_per_document INTEGER NOT NULL DEFAULT 1000,
    
    -- Retrieval configuration
    default_max_results INTEGER NOT NULL DEFAULT 10,
    default_max_depth INTEGER NOT NULL DEFAULT 3,
    min_relevance_score DECIMAL(5,4) NOT NULL DEFAULT 0.7,
    hybrid_search_alpha DECIMAL(3,2) NOT NULL DEFAULT 0.5,
    
    -- Maintenance
    auto_cleanup_enabled BOOLEAN NOT NULL DEFAULT true,
    cleanup_threshold_days INTEGER NOT NULL DEFAULT 365,
    max_entities_per_tenant INTEGER NOT NULL DEFAULT 100000,
    max_chunks_per_tenant INTEGER NOT NULL DEFAULT 1000000,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by UUID REFERENCES platform_admins(id),
    
    UNIQUE(tenant_id)
);

-- Table: cortex_conflicting_facts
CREATE TABLE IF NOT EXISTS cortex_conflicting_facts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    node_id_1 UUID NOT NULL REFERENCES cortex_graph_nodes(id) ON DELETE CASCADE,
    node_id_2 UUID NOT NULL REFERENCES cortex_graph_nodes(id) ON DELETE CASCADE,
    conflict_type VARCHAR(30) NOT NULL CHECK (conflict_type IN ('contradiction', 'superseded', 'ambiguous')),
    description TEXT,
    detected_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMPTZ,
    resolved_by UUID REFERENCES users(id),
    resolution_action VARCHAR(50),
    resolution_notes TEXT
);

-- Table: cortex_data_flow_metrics
CREATE TABLE IF NOT EXISTS cortex_data_flow_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period VARCHAR(10) NOT NULL CHECK (period IN ('hour', 'day', 'week')),
    period_start TIMESTAMPTZ NOT NULL,
    hot_to_warm_promotions INTEGER DEFAULT 0,
    warm_to_cold_archivals INTEGER DEFAULT 0,
    cold_to_warm_retrievals INTEGER DEFAULT 0,
    hot_cache_miss_rate DECIMAL(5,4) DEFAULT 0,
    warm_query_latency_p99_ms INTEGER DEFAULT 0,
    cold_retrieval_latency_p99_ms INTEGER DEFAULT 0,
    tier_miss_rate DECIMAL(5,4) DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    UNIQUE(tenant_id, period, period_start)
);

-- Table: cortex_entities
CREATE TABLE IF NOT EXISTS cortex_entities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    entity_type VARCHAR(50) NOT NULL,
    name VARCHAR(500) NOT NULL,
    description TEXT,
    aliases TEXT[] DEFAULT '{}',
    properties JSONB NOT NULL DEFAULT '{}',
    
    -- Vector embedding for semantic search
    embedding vector(1536),
    embedding_model VARCHAR(100),
    
    -- Metadata
    confidence DECIMAL(5,4) NOT NULL DEFAULT 1.0,
    source_type VARCHAR(50) NOT NULL,
    source_id UUID,
    source_url TEXT,
    source_timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    source_user_id UUID,
    
    -- Activity tracking
    access_count INTEGER NOT NULL DEFAULT 0,
    last_accessed_at TIMESTAMPTZ,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    merged_into_id UUID REFERENCES cortex_entities(id),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_entrance_exams
CREATE TABLE IF NOT EXISTS cortex_entrance_exams (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain_id UUID NOT NULL,
    domain_path VARCHAR(500) NOT NULL,
    questions JSONB NOT NULL DEFAULT '[]',
    passing_score INTEGER NOT NULL DEFAULT 80,
    timeout_minutes INTEGER NOT NULL DEFAULT 60,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'in_progress', 'passed', 'failed', 'expired')),
    assigned_to VARCHAR(255),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    score INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_exam_submissions
CREATE TABLE IF NOT EXISTS cortex_exam_submissions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    exam_id UUID NOT NULL REFERENCES cortex_entrance_exams(id) ON DELETE CASCADE,
    question_id UUID NOT NULL,
    answer TEXT NOT NULL,
    is_verified BOOLEAN NOT NULL DEFAULT false,
    correction TEXT,
    notes TEXT,
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(exam_id, question_id)
);

-- Table: cortex_gdpr_erasure_requests
CREATE TABLE IF NOT EXISTS cortex_gdpr_erasure_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id),
    scope_type VARCHAR(20) NOT NULL CHECK (scope_type IN ('user', 'tenant')),
    reason TEXT,
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'completed', 'failed')),
    hot_tier_status VARCHAR(20) DEFAULT 'pending' CHECK (hot_tier_status IN ('pending', 'completed')),
    warm_tier_status VARCHAR(20) DEFAULT 'pending' CHECK (warm_tier_status IN ('pending', 'completed')),
    cold_tier_status VARCHAR(20) DEFAULT 'pending' CHECK (cold_tier_status IN ('pending', 'completed')),
    audit_log_retained BOOLEAN DEFAULT true,
    error_message TEXT,
    requested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    requested_by UUID REFERENCES users(id),
    completed_at TIMESTAMPTZ
);

-- Table: cortex_golden_rules
CREATE TABLE IF NOT EXISTS cortex_golden_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    entity_id UUID REFERENCES cortex_graph_nodes(id) ON DELETE SET NULL,
    rule_type VARCHAR(20) NOT NULL CHECK (rule_type IN ('force_override', 'ignore_source', 'prefer_source', 'deprecate')),
    condition TEXT NOT NULL,
    override TEXT NOT NULL,
    reason TEXT NOT NULL,
    priority INTEGER NOT NULL DEFAULT 100,
    is_active BOOLEAN NOT NULL DEFAULT true,
    verified_by VARCHAR(255) NOT NULL,
    verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    signature VARCHAR(128) NOT NULL,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_graph_documents
CREATE TABLE IF NOT EXISTS cortex_graph_documents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    title VARCHAR(500) NOT NULL,
    source VARCHAR(1000),
    source_type VARCHAR(20) NOT NULL CHECK (source_type IN ('upload', 'mount', 'api')),
    hash VARCHAR(64) NOT NULL,
    file_size_bytes BIGINT,
    mime_type VARCHAR(100),
    node_count INTEGER DEFAULT 0,
    status VARCHAR(20) DEFAULT 'processing' CHECK (status IN ('processing', 'indexed', 'archived', 'error')),
    error_message TEXT,
    s3_key VARCHAR(1000),
    mount_id UUID REFERENCES cortex_zero_copy_mounts(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    indexed_at TIMESTAMPTZ,
    archived_at TIMESTAMPTZ,
    
    UNIQUE(tenant_id, hash)
);

-- Table: cortex_graph_edges
CREATE TABLE IF NOT EXISTS cortex_graph_edges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source_node_id UUID NOT NULL REFERENCES cortex_graph_nodes(id) ON DELETE CASCADE,
    target_node_id UUID NOT NULL REFERENCES cortex_graph_nodes(id) ON DELETE CASCADE,
    edge_type VARCHAR(50) NOT NULL CHECK (edge_type IN (
        'mentions', 'causes', 'depends_on', 'supersedes', 'verified_by', 
        'authored_by', 'relates_to', 'contains', 'requires'
    )),
    weight DECIMAL(3,2) DEFAULT 0.5,
    properties JSONB DEFAULT '{}',
    confidence DECIMAL(3,2) DEFAULT 0.8,
    neptune_id VARCHAR(255), -- Reference to Neptune edge ID
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: cortex_graph_expansion_tasks
CREATE TABLE IF NOT EXISTS cortex_graph_expansion_tasks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    task_type VARCHAR(30) NOT NULL CHECK (task_type IN ('infer_links', 'cluster_entities', 'detect_patterns', 'merge_duplicates')),
    source_node_ids UUID[] NOT NULL DEFAULT '{}',
    target_scope VARCHAR(20) NOT NULL DEFAULT 'local' CHECK (target_scope IN ('local', 'domain', 'global')),
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'completed', 'failed')),
    progress INTEGER NOT NULL DEFAULT 0,
    discovered_links JSONB NOT NULL DEFAULT '[]',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    error TEXT
);

-- Table: cortex_graph_nodes
CREATE TABLE IF NOT EXISTS cortex_graph_nodes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    node_type VARCHAR(50) NOT NULL CHECK (node_type IN ('document', 'entity', 'concept', 'procedure', 'fact')),
    label VARCHAR(500) NOT NULL,
    description TEXT,
    properties JSONB DEFAULT '{}',
    embedding vector(1536),
    confidence DECIMAL(3,2) DEFAULT 0.8,
    source_document_ids UUID[] DEFAULT ARRAY[]::UUID[],
    is_evergreen BOOLEAN DEFAULT false,
    neptune_id VARCHAR(255), -- Reference to Neptune node ID
    status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'archived', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    archived_at TIMESTAMPTZ
);

-- Table: cortex_housekeeping_results
CREATE TABLE IF NOT EXISTS cortex_housekeeping_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    task_id UUID NOT NULL REFERENCES cortex_housekeeping_tasks(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    task_type VARCHAR(50) NOT NULL,
    success BOOLEAN NOT NULL,
    records_processed INTEGER DEFAULT 0,
    errors_encountered INTEGER DEFAULT 0,
    duration_ms INTEGER,
    details JSONB DEFAULT '{}',
    completed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: cortex_housekeeping_tasks
CREATE TABLE IF NOT EXISTS cortex_housekeeping_tasks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    task_type VARCHAR(50) NOT NULL CHECK (task_type IN (
        'ttl_enforcement', 'archive_promotion', 'deduplication', 
        'conflict_resolution', 'iceberg_compaction', 'index_optimization',
        'integrity_audit', 'storage_report'
    )),
    frequency VARCHAR(20) NOT NULL CHECK (frequency IN ('hourly', 'nightly', 'weekly')),
    is_enabled BOOLEAN DEFAULT true,
    last_run_at TIMESTAMPTZ,
    next_run_at TIMESTAMPTZ,
    status VARCHAR(20) DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'running', 'completed', 'failed')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    UNIQUE(tenant_id, task_type)
);

-- Table: cortex_inferred_links
CREATE TABLE IF NOT EXISTS cortex_inferred_links (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    task_id UUID NOT NULL REFERENCES cortex_graph_expansion_tasks(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source_node_id UUID NOT NULL,
    target_node_id UUID NOT NULL,
    edge_type VARCHAR(50) NOT NULL,
    confidence DECIMAL(5,4) NOT NULL,
    evidence JSONB NOT NULL DEFAULT '[]',
    is_approved BOOLEAN,
    approved_by VARCHAR(255),
    approved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_model_migrations
CREATE TABLE IF NOT EXISTS cortex_model_migrations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source_model JSONB NOT NULL,
    target_model JSONB NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'validating', 'migrating', 'testing', 'completed', 'failed', 'rolled_back')),
    validation_results JSONB,
    test_results JSONB NOT NULL DEFAULT '[]',
    rollback_available BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    error TEXT
);

-- Table: cortex_network_deployments
CREATE TABLE IF NOT EXISTS cortex_network_deployments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id VARCHAR(50) NOT NULL,
    version VARCHAR(50) NOT NULL,
    previous_version VARCHAR(50),
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'deploying', 'promoted', 'rejected', 'rolled_back')),
    region VARCHAR(50) NOT NULL DEFAULT 'us-east-1',
    shadow_validation_id UUID REFERENCES cortex_shadow_validations(id),
    
    -- Deployment details
    deployed_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    deployed_by VARCHAR(255) DEFAULT 'system',
    rollback_reason TEXT,
    rollback_at TIMESTAMPTZ,
    rollback_by VARCHAR(255),
    
    -- Audit
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: cortex_network_metrics
CREATE TABLE IF NOT EXISTS cortex_network_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id VARCHAR(50) NOT NULL,
    region VARCHAR(50) NOT NULL DEFAULT 'us-east-1',
    timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    request_count INTEGER DEFAULT 0,
    error_count INTEGER DEFAULT 0,
    avg_latency_ms DECIMAL(10, 4) DEFAULT 0,
    p50_latency_ms DECIMAL(10, 4) DEFAULT 0,
    p99_latency_ms DECIMAL(10, 4) DEFAULT 0,
    memory_usage_mb DECIMAL(10, 2) DEFAULT 0,
    cpu_utilization DECIMAL(5, 4) DEFAULT 0
);

-- Table: cortex_network_status
CREATE TABLE IF NOT EXISTS cortex_network_status (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id VARCHAR(50) NOT NULL,
    version VARCHAR(50) NOT NULL DEFAULT 'v1.0.0',
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'degraded', 'offline', 'shadow')),
    parameters INTEGER NOT NULL DEFAULT 0,
    requests_per_second DECIMAL(12, 2) DEFAULT 0,
    latency_p50_ms DECIMAL(10, 4) DEFAULT 0,
    latency_p99_ms DECIMAL(10, 4) DEFAULT 0,
    error_rate DECIMAL(10, 8) DEFAULT 0,
    region VARCHAR(50) NOT NULL DEFAULT 'us-east-1',
    last_deployed_at TIMESTAMPTZ,
    last_updated TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT uq_cortex_network_region UNIQUE (network_id, region)
);

-- Table: cortex_pattern_detections
CREATE TABLE IF NOT EXISTS cortex_pattern_detections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pattern_type VARCHAR(20) NOT NULL CHECK (pattern_type IN ('sequence', 'correlation', 'anomaly', 'cluster')),
    description TEXT NOT NULL,
    affected_nodes UUID[] NOT NULL DEFAULT '{}',
    confidence DECIMAL(5,4) NOT NULL,
    suggested_action TEXT,
    detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_query_log
CREATE TABLE IF NOT EXISTS cortex_query_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    query_text TEXT NOT NULL,
    query_embedding vector(1536),
    
    filters JSONB DEFAULT '{}',
    options JSONB DEFAULT '{}',
    
    results_count INTEGER NOT NULL,
    processing_time_ms INTEGER NOT NULL,
    
    user_id UUID,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_relationships
CREATE TABLE IF NOT EXISTS cortex_relationships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    source_entity_id UUID NOT NULL REFERENCES cortex_entities(id) ON DELETE CASCADE,
    target_entity_id UUID NOT NULL REFERENCES cortex_entities(id) ON DELETE CASCADE,
    
    relationship_type VARCHAR(50) NOT NULL,
    custom_type VARCHAR(100),
    
    weight DECIMAL(5,4) NOT NULL DEFAULT 1.0,
    confidence DECIMAL(5,4) NOT NULL DEFAULT 1.0,
    properties JSONB NOT NULL DEFAULT '{}',
    bidirectional BOOLEAN NOT NULL DEFAULT false,
    
    -- Temporal validity
    valid_from TIMESTAMPTZ,
    valid_until TIMESTAMPTZ,
    
    -- Source tracking
    source_type VARCHAR(50) NOT NULL,
    source_id UUID,
    source_timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Prevent duplicate relationships
    UNIQUE(tenant_id, source_entity_id, target_entity_id, relationship_type)
);

-- Table: cortex_shadow_validations
CREATE TABLE IF NOT EXISTS cortex_shadow_validations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id VARCHAR(50) NOT NULL,
    current_version VARCHAR(50) NOT NULL,
    candidate_version VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'passed', 'failed', 'aborted')),
    started_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    estimated_end_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    progress_percent INTEGER DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    duration_minutes INTEGER DEFAULT 60,
    
    -- Metrics
    error_rate DECIMAL(10, 8) DEFAULT 0,
    latency_delta_ms DECIMAL(10, 4) DEFAULT 0,
    divergence_percent DECIMAL(5, 4) DEFAULT 0,
    memory_overhead_percent DECIMAL(5, 4) DEFAULT 0,
    
    -- Warnings and abort info
    warnings JSONB DEFAULT '[]'::jsonb,
    abort_reason TEXT,
    aborted_by VARCHAR(255),
    aborted_at TIMESTAMPTZ,
    
    -- Audit
    created_by VARCHAR(255) DEFAULT 'system',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: cortex_stub_nodes
CREATE TABLE IF NOT EXISTS cortex_stub_nodes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    mount_id UUID NOT NULL REFERENCES cortex_zero_copy_mounts(id) ON DELETE CASCADE,
    label VARCHAR(500) NOT NULL,
    description TEXT,
    uri TEXT NOT NULL,
    format VARCHAR(20) NOT NULL CHECK (format IN ('csv', 'json', 'parquet', 'pdf', 'docx', 'xlsx', 'txt', 'html')),
    size_bytes BIGINT NOT NULL DEFAULT 0,
    last_modified TIMESTAMPTZ,
    checksum VARCHAR(128),
    extracted_metadata JSONB NOT NULL DEFAULT '{}',
    connected_to UUID[] NOT NULL DEFAULT '{}',
    last_scanned_at TIMESTAMPTZ,
    scan_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (scan_status IN ('pending', 'scanning', 'complete', 'error')),
    scan_error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cortex_telemetry_data
CREATE TABLE IF NOT EXISTS cortex_telemetry_data (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    feed_id UUID NOT NULL REFERENCES cortex_telemetry_feeds(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    node_id VARCHAR(255) NOT NULL,
    value_numeric DOUBLE PRECISION,
    value_text TEXT,
    value_boolean BOOLEAN,
    quality VARCHAR(20) NOT NULL DEFAULT 'good' CHECK (quality IN ('good', 'bad', 'uncertain')),
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    metadata JSONB
);

-- Table: cortex_telemetry_feeds
CREATE TABLE IF NOT EXISTS cortex_telemetry_feeds (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    protocol VARCHAR(20) NOT NULL CHECK (protocol IN ('mqtt', 'opc_ua', 'kafka', 'websocket', 'http_poll')),
    endpoint TEXT NOT NULL,
    node_ids TEXT[],
    topics TEXT[],
    poll_interval_ms INTEGER DEFAULT 1000,
    context_injection BOOLEAN NOT NULL DEFAULT true,
    transform_script TEXT,
    is_active BOOLEAN NOT NULL DEFAULT true,
    auth_config JSONB,
    last_data_at TIMESTAMPTZ,
    error_count INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, name)
);

-- Table: cortex_tier_alerts
CREATE TABLE IF NOT EXISTS cortex_tier_alerts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    tier VARCHAR(10) NOT NULL CHECK (tier IN ('hot', 'warm', 'cold')),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('info', 'warning', 'critical')),
    metric VARCHAR(100) NOT NULL,
    threshold DECIMAL(15,4) NOT NULL,
    current_value DECIMAL(15,4) NOT NULL,
    message TEXT NOT NULL,
    triggered_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    acknowledged_at TIMESTAMPTZ,
    acknowledged_by UUID REFERENCES users(id),
    resolved_at TIMESTAMPTZ
);

-- Table: cortex_tier_health
CREATE TABLE IF NOT EXISTS cortex_tier_health (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    tier VARCHAR(10) NOT NULL CHECK (tier IN ('hot', 'warm', 'cold')),
    status VARCHAR(20) DEFAULT 'healthy' CHECK (status IN ('healthy', 'degraded', 'critical')),
    
    -- Hot Tier Metrics
    redis_memory_usage_percent DECIMAL(5,2),
    redis_cache_hit_rate DECIMAL(5,4),
    redis_p99_latency_ms INTEGER,
    redis_connection_count INTEGER,
    
    -- Warm Tier Metrics
    neptune_cpu_percent DECIMAL(5,2),
    neptune_query_latency_p99_ms INTEGER,
    pgvector_index_size BIGINT,
    graph_node_count BIGINT,
    graph_edge_count BIGINT,
    
    -- Cold Tier Metrics
    s3_storage_bytes BIGINT,
    s3_storage_cost_usd DECIMAL(10,2),
    athena_query_duration_p99_ms INTEGER,
    iceberg_compaction_lag_hours INTEGER,
    zero_copy_mount_error_count INTEGER,
    
    checked_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: cortex_zero_copy_mounts
CREATE TABLE IF NOT EXISTS cortex_zero_copy_mounts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    source_type VARCHAR(50) NOT NULL CHECK (source_type IN ('snowflake', 'databricks', 's3', 'azure_datalake', 'gcs')),
    connection_config JSONB NOT NULL DEFAULT '{}',
    status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'scanning', 'error', 'disconnected')),
    last_scan_at TIMESTAMPTZ,
    object_count INTEGER DEFAULT 0,
    total_size_bytes BIGINT DEFAULT 0,
    indexed_node_count INTEGER DEFAULT 0,
    credential_secret_arn VARCHAR(500),
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    UNIQUE(tenant_id, name)
);

-- Table: cortex_zero_copy_scan_results
CREATE TABLE IF NOT EXISTS cortex_zero_copy_scan_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mount_id UUID NOT NULL REFERENCES cortex_zero_copy_mounts(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    objects_scanned INTEGER NOT NULL DEFAULT 0,
    objects_indexed INTEGER NOT NULL DEFAULT 0,
    nodes_created INTEGER NOT NULL DEFAULT 0,
    error_count INTEGER NOT NULL DEFAULT 0,
    scan_duration_ms INTEGER,
    error_details JSONB DEFAULT '[]',
    scanned_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Table: cos_config
CREATE TABLE IF NOT EXISTS cos_config (
  tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
  
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  ghost_vectors_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  flash_facts_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  dreaming_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  human_oversight_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  differential_privacy_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  
  -- vLLM requirement flag
  vllm_return_hidden_states BOOLEAN NOT NULL DEFAULT TRUE,
  
  -- Safety invariants (from Genesis Cato - NEVER change these)
  cbf_enforcement_mode VARCHAR(10) NOT NULL DEFAULT 'ENFORCE' CHECK (cbf_enforcement_mode = 'ENFORCE'),
  gamma_boost_allowed BOOLEAN NOT NULL DEFAULT FALSE CHECK (gamma_boost_allowed = FALSE),
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cos_dream_jobs
CREATE TABLE IF NOT EXISTS cos_dream_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  trigger VARCHAR(20) NOT NULL CHECK (trigger IN ('TWILIGHT', 'STARVATION')),
  status VARCHAR(20) NOT NULL DEFAULT 'scheduled' 
    CHECK (status IN ('scheduled', 'running', 'completed', 'failed')),
  
  scheduled_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  flash_facts_consolidated INTEGER DEFAULT 0,
  ghost_vectors_reanchored INTEGER DEFAULT 0,
  lora_updates_applied INTEGER DEFAULT 0,
  
  error_message TEXT,
  retry_count INTEGER NOT NULL DEFAULT 0
);

-- Table: cos_flash_facts
CREATE TABLE IF NOT EXISTS cos_flash_facts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  fact TEXT NOT NULL,
  fact_type VARCHAR(50) NOT NULL CHECK (fact_type IN ('identity', 'allergy', 'medical', 'preference', 'correction')),
  is_safety_critical BOOLEAN NOT NULL DEFAULT FALSE,
  
  status VARCHAR(50) NOT NULL DEFAULT 'pending_dream' 
    CHECK (status IN ('pending_dream', 'consolidated', 'failed_retry', 'orphan_recovered')),
  retry_count INTEGER NOT NULL DEFAULT 0,
  
  redis_key VARCHAR(255) NOT NULL,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  consolidated_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL
);

-- Table: cos_ghost_vectors
CREATE TABLE IF NOT EXISTS cos_ghost_vectors (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- 4096-dimensional vector from model hidden states
  -- CRITICAL: Requires vLLM with --return-hidden-states flag
  vector JSONB NOT NULL,
  vector_dimension INTEGER NOT NULL DEFAULT 4096,
  
  -- Version gating - prevents personality discontinuity on model upgrades
  model_version VARCHAR(100) NOT NULL,
  model_family VARCHAR(50) NOT NULL,
  
  -- Affective state (7-hour half-life)
  affective_state JSONB NOT NULL DEFAULT '{"valence": 0, "arousal": 0.5, "dominance": 0.5}',
  
  -- Working context (12-minute half-life)
  working_context JSONB NOT NULL DEFAULT '{"topics": [], "entities": [], "recentIntents": []}',
  
  -- Curiosity state (45-minute half-life)
  curiosity_state JSONB NOT NULL DEFAULT '{"exploredTopics": [], "pendingQuestions": [], "interestLevel": 0.5}',
  
  -- Decay constants (Gemini validated)
  decay_constants JSONB NOT NULL DEFAULT '{"affective": 0.0000275, "workingContext": 0.00096, "curiosity": 0.00025}',
  
  -- Timestamps
  last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_reanchored_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  turns_since_reanchor INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT cos_ghost_vectors_user_tenant_unique UNIQUE (user_id, tenant_id)
);

-- Table: cos_human_oversight
CREATE TABLE IF NOT EXISTS cos_human_oversight (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  item_type VARCHAR(50) NOT NULL CHECK (item_type IN ('system_insight', 'lora_update', 'high_risk_response')),
  content TEXT NOT NULL,
  context JSONB NOT NULL DEFAULT '{}',
  
  status VARCHAR(50) NOT NULL DEFAULT 'pending_approval'
    CHECK (status IN ('pending_approval', 'approved', 'rejected', 'escalated', 'auto_rejected')),
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  reviewed_at TIMESTAMPTZ,
  reviewed_by UUID REFERENCES users(id),
  review_notes TEXT,
  
  -- Gemini mandate: "Silence ≠ Consent"
  escalate_after_days INTEGER NOT NULL DEFAULT 3,
  auto_reject_after_days INTEGER NOT NULL DEFAULT 7
);

-- Table: cos_oversight_audit_log
CREATE TABLE IF NOT EXISTS cos_oversight_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  oversight_item_id UUID NOT NULL REFERENCES cos_human_oversight(id) ON DELETE CASCADE,
  
  action VARCHAR(50) NOT NULL,
  actor VARCHAR(255) NOT NULL,
  notes TEXT,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cos_privacy_airlock
CREATE TABLE IF NOT EXISTS cos_privacy_airlock (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  packet_id VARCHAR(255) NOT NULL,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  status VARCHAR(20) NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected', 'expired')),
  
  original_content TEXT NOT NULL,
  deidentified_content TEXT,
  
  privacy_level VARCHAR(20) NOT NULL DEFAULT 'internal'
    CHECK (privacy_level IN ('public', 'internal', 'confidential', 'restricted', 'phi')),
  contains_phi BOOLEAN NOT NULL DEFAULT FALSE,
  contains_pii BOOLEAN NOT NULL DEFAULT FALSE,
  
  source_type VARCHAR(50) NOT NULL,
  metadata JSONB NOT NULL DEFAULT '{}',
  
  privacy_reviewed_by UUID REFERENCES users(id),
  privacy_reviewed_at TIMESTAMPTZ,
  
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cos_reanchor_metrics
CREATE TABLE IF NOT EXISTS cos_reanchor_metrics (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  outcome VARCHAR(20) NOT NULL CHECK (outcome IN ('completed', 'failed')),
  processing_time_ms INTEGER NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cos_tenant_dream_config
CREATE TABLE IF NOT EXISTS cos_tenant_dream_config (
  tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
  
  timezone VARCHAR(100) NOT NULL DEFAULT 'UTC',
  twilight_hour INTEGER NOT NULL DEFAULT 4 CHECK (twilight_hour >= 0 AND twilight_hour <= 23),
  starvation_threshold_hours INTEGER NOT NULL DEFAULT 30,
  
  last_dream_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cost_alerts
CREATE TABLE IF NOT EXISTS cost_alerts (
    alert_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    alert_type TEXT NOT NULL DEFAULT 'threshold',
    severity TEXT NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warning', 'critical')),
    message TEXT NOT NULL,
    current_value DECIMAL(12,2) NOT NULL DEFAULT 0,
    threshold_value DECIMAL(12,2),
    resolved BOOLEAN NOT NULL DEFAULT false,
    resolved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cost_budgets
CREATE TABLE IF NOT EXISTS cost_budgets (
    budget_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    amount DECIMAL(12,2) NOT NULL,
    period_type TEXT NOT NULL DEFAULT 'monthly' CHECK (period_type IN ('monthly', 'quarterly', 'annual')),
    alert_thresholds JSONB NOT NULL DEFAULT '[50, 80, 100]'::jsonb,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cost_daily_aggregates
CREATE TABLE IF NOT EXISTS cost_daily_aggregates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    date DATE NOT NULL,
    total_cost DECIMAL(12, 6) NOT NULL DEFAULT 0,
    total_tokens INTEGER NOT NULL DEFAULT 0,
    request_count INTEGER NOT NULL DEFAULT 0,
    by_model JSONB DEFAULT '{}',
    by_provider JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, date)
);

-- Table: cost_entries
CREATE TABLE IF NOT EXISTS cost_entries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE SET NULL, -- NULL for shared infra
    
    -- Cost category
    category VARCHAR(30) NOT NULL CHECK (category IN (
        'aws_compute', 'aws_storage', 'aws_network', 'aws_database',
        'external_ai', 'infrastructure', 'platform_fees'
    )),
    
    -- Amount
    amount DECIMAL(15, 4) NOT NULL,
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    
    -- Description
    description TEXT,
    aws_service_name VARCHAR(100),       -- e.g., 'SageMaker', 'Aurora', 'Lambda'
    resource_id VARCHAR(255),
    
    -- Provider attribution (for external AI)
    provider_id VARCHAR(50),
    model_id VARCHAR(100),
    
    -- Metadata
    metadata JSONB DEFAULT '{}',
    
    -- Time period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: cost_events
CREATE TABLE IF NOT EXISTS cost_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    model_id VARCHAR(100) NOT NULL,
    provider_id VARCHAR(100),
    input_tokens INTEGER NOT NULL DEFAULT 0,
    output_tokens INTEGER NOT NULL DEFAULT 0,
    input_cost DECIMAL(12, 8) NOT NULL DEFAULT 0,
    output_cost DECIMAL(12, 8) NOT NULL DEFAULT 0,
    total_cost DECIMAL(12, 8) NOT NULL DEFAULT 0,
    request_id VARCHAR(100),
    session_id UUID,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: cost_insights
CREATE TABLE IF NOT EXISTS cost_insights (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    insight_type VARCHAR(30) NOT NULL CHECK (insight_type IN ('model_switch', 'usage_pattern', 'budget_alert', 'efficiency', 'anomaly')),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('info', 'warning', 'critical')),
    title VARCHAR(200) NOT NULL,
    description TEXT,
    recommendation TEXT,
    estimated_savings DECIMAL(12, 6) DEFAULT 0,
    confidence DECIMAL(5, 4) DEFAULT 0, -- 0.0 to 1.0
    affected_users JSONB DEFAULT '[]',
    affected_models JSONB DEFAULT '[]',
    status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'dismissed', 'applied')),
    applied_at TIMESTAMPTZ,
    applied_by UUID REFERENCES users(id),
    dismissed_at TIMESTAMPTZ,
    dismissed_by UUID REFERENCES users(id),
    dismiss_reason TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '30 days'
);

-- Table: cost_snapshots
CREATE TABLE IF NOT EXISTS cost_snapshots (
    snapshot_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    total_cost DECIMAL(12,2) NOT NULL DEFAULT 0,
    service_breakdown JSONB NOT NULL DEFAULT '[]'::jsonb,
    daily_costs JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: council_debates
CREATE TABLE IF NOT EXISTS council_debates (
    id VARCHAR(64) PRIMARY KEY,
    council_id VARCHAR(64) NOT NULL REFERENCES council_of_rivals(id) ON DELETE CASCADE,
    tenant_id VARCHAR(64) NOT NULL,
    topic TEXT NOT NULL,
    context TEXT,
    rounds JSONB DEFAULT '[]',
    current_round INTEGER DEFAULT 0,
    status VARCHAR(32) DEFAULT 'setup',
    verdict JSONB,
    started_at TIMESTAMP NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMP,
    metadata JSONB DEFAULT '{}'
);

-- Table: council_experts
CREATE TABLE IF NOT EXISTS council_experts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES council_sessions(id) ON DELETE CASCADE,
    persona VARCHAR(255) NOT NULL,
    specialization VARCHAR(500) NOT NULL,
    model_id VARCHAR(255) NOT NULL,
    avatar JSONB DEFAULT '{"color": "#3b82f6", "icon": "user"}',
    breathing_aura JSONB DEFAULT '{"color": "#3b82f6", "rate": 6, "radius": 30}',
    current_position JSONB DEFAULT '{}',
    credibility_score INTEGER DEFAULT 80 CHECK (credibility_score >= 0 AND credibility_score <= 100),
    agreement_with JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: council_of_rivals
CREATE TABLE IF NOT EXISTS council_of_rivals (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    members JSONB NOT NULL DEFAULT '[]',
    moderator JSONB NOT NULL,
    rules JSONB NOT NULL,
    status VARCHAR(32) DEFAULT 'idle',
    created_by VARCHAR(64) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: council_sessions
CREATE TABLE IF NOT EXISTS council_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    topic VARCHAR(500) NOT NULL,
    question TEXT NOT NULL,
    status council_status NOT NULL DEFAULT 'convening',
    consensus_level INTEGER DEFAULT 0 CHECK (consensus_level >= 0 AND consensus_level <= 100),
    consensus_state JSONB DEFAULT '{}',
    conclusion JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by UUID NOT NULL
);

-- Table: counterfactual_candidates
CREATE TABLE IF NOT EXISTS counterfactual_candidates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id UUID NOT NULL,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  original_model VARCHAR(100) NOT NULL,
  alternative_models VARCHAR(100)[] NOT NULL,
  prompt TEXT NOT NULL,
  original_response TEXT NOT NULL,
  original_latency_ms INTEGER,
  original_cost DECIMAL(10,6),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: counterfactual_simulations
CREATE TABLE IF NOT EXISTS counterfactual_simulations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  trace_id UUID NOT NULL,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  original_model VARCHAR(100) NOT NULL,
  original_response TEXT NOT NULL,
  original_latency_ms INTEGER,
  original_cost DECIMAL(10,6),
  original_reward_score DECIMAL(3,2),
  alternative_model VARCHAR(100) NOT NULL,
  alternative_response TEXT,
  alternative_latency_ms INTEGER,
  alternative_cost DECIMAL(10,6),
  alternative_reward_score DECIMAL(3,2),
  preferred_by_reward VARCHAR(20) CHECK (preferred_by_reward IN ('original', 'alternative', 'equal')),
  quality_delta DECIMAL(5,4),
  cost_delta DECIMAL(10,6),
  sample_reason VARCHAR(50) NOT NULL CHECK (sample_reason IN ('regeneration', 'low_confidence', 'high_cost', 'random')),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: creative_ideas
CREATE TABLE IF NOT EXISTS creative_ideas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    idea_id TEXT UNIQUE,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    idea_embedding vector(1536),
    synthesis_type TEXT NOT NULL DEFAULT 'combination',
    source_concepts JSONB DEFAULT '[]'::jsonb,
    novelty_score NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    usefulness_score NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    surprise_score NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    coherence_score NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    creativity_score NUMERIC(5,4) GENERATED ALWAYS AS (
        (novelty_score * 0.4 + usefulness_score * 0.3 + surprise_score * 0.2 + coherence_score * 0.1)
    ) STORED,
    self_evaluation TEXT,
    potential_applications JSONB DEFAULT '[]'::jsonb,
    potential_problems JSONB DEFAULT '[]'::jsonb,
    refinement_count INTEGER NOT NULL DEFAULT 0,
    shared_externally BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: credential_access_log
CREATE TABLE IF NOT EXISTS credential_access_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    credential_id UUID NOT NULL REFERENCES stored_credentials(id) ON DELETE CASCADE,
    accessed_by UUID REFERENCES users(id),
    access_type VARCHAR(50) NOT NULL CHECK (access_type IN ('read', 'create', 'update', 'rotate', 'delete')),
    access_reason TEXT,
    source_ip VARCHAR(45),
    user_agent TEXT,
    success BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: credential_vaults
CREATE TABLE IF NOT EXISTS credential_vaults (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    vault_name VARCHAR(100) NOT NULL,
    description TEXT,
    encryption_key_arn VARCHAR(500) NOT NULL,
    created_by UUID REFERENCES administrators(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, vault_name)
);

-- Table: credit_balances
CREATE TABLE IF NOT EXISTS credit_balances (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    balance DECIMAL(12, 4) NOT NULL DEFAULT 0,
    lifetime_purchased DECIMAL(12, 4) NOT NULL DEFAULT 0,
    lifetime_used DECIMAL(12, 4) NOT NULL DEFAULT 0,
    lifetime_bonus DECIMAL(12, 4) NOT NULL DEFAULT 0,
    
    auto_purchase_enabled BOOLEAN DEFAULT false,
    auto_purchase_threshold DECIMAL(12, 4),
    auto_purchase_amount DECIMAL(12, 4),
    
    low_balance_alert_threshold DECIMAL(12, 4),
    last_low_balance_alert TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: credit_purchases
CREATE TABLE IF NOT EXISTS credit_purchases (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    credits_amount DECIMAL(12, 4) NOT NULL,
    bonus_credits DECIMAL(12, 4) DEFAULT 0,
    
    price_cents INTEGER NOT NULL,
    discount_percent DECIMAL(5, 2) DEFAULT 0,
    discount_reason VARCHAR(100),
    
    stripe_payment_intent_id VARCHAR(100),
    stripe_invoice_id VARCHAR(100),
    
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'completed', 'failed', 'refunded')),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: credit_transactions
CREATE TABLE IF NOT EXISTS credit_transactions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID,
    
    transaction_type VARCHAR(30) NOT NULL CHECK (transaction_type IN (
        'purchase', 'bonus', 'refund', 'usage', 'transfer_in', 'transfer_out', 
        'subscription_allocation', 'expiration', 'adjustment'
    )),
    
    amount DECIMAL(12, 4) NOT NULL,
    balance_after DECIMAL(12, 4) NOT NULL,
    
    description TEXT,
    reference_id VARCHAR(100),
    reference_type VARCHAR(50),
    
    stripe_payment_intent_id VARCHAR(100),
    
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crossmodal_queries
CREATE TABLE IF NOT EXISTS crossmodal_queries (
    query_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Query specification
    query_modality VARCHAR(50) NOT NULL, -- Input modality
    query_content TEXT NOT NULL,
    query_embedding vector(1536),
    
    target_modalities TEXT[] NOT NULL, -- Which modalities to search
    
    -- Results
    results JSONB DEFAULT '[]', -- [{representation_id, modality, similarity, content_preview}]
    result_count INTEGER DEFAULT 0,
    
    -- Performance
    latency_ms INTEGER,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: crucible_answers
CREATE TABLE IF NOT EXISTS crucible_answers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    question_id UUID NOT NULL REFERENCES crucible_questions(id) ON DELETE CASCADE,
    answer_text TEXT NOT NULL,
    circular_citation_detected BOOLEAN NOT NULL DEFAULT FALSE,
    circular_citation_details TEXT,
    latency_ms INTEGER NOT NULL,
    token_count INTEGER NOT NULL,
    answered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_audit_log
CREATE TABLE IF NOT EXISTS crucible_audit_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id UUID REFERENCES crucible_sessions(id) ON DELETE SET NULL,
    event_type VARCHAR(50) NOT NULL,
    event_data JSONB NOT NULL,
    actor_id VARCHAR(255),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_audit_log_partitioned
CREATE TABLE IF NOT EXISTS crucible_audit_log_partitioned (
--     LIKE crucible_audit_log INCLUDING ALL
-- ) PARTITION BY RANGE (created_at);

-- Table: crucible_citations
CREATE TABLE IF NOT EXISTS crucible_citations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    answer_id UUID NOT NULL REFERENCES crucible_answers(id) ON DELETE CASCADE,
    source_type crucible_citation_source NOT NULL,
    source_participant_id VARCHAR(64),
    citation_text TEXT NOT NULL,
    is_circular BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_config
CREATE TABLE IF NOT EXISTS crucible_config (
    tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    default_max_questions INTEGER NOT NULL DEFAULT 5,
    question_timeout_seconds INTEGER NOT NULL DEFAULT 30,
    session_timeout_seconds INTEGER NOT NULL DEFAULT 180,
    min_llms_for_crucible INTEGER NOT NULL DEFAULT 2,
    store_for_learning BOOLEAN NOT NULL DEFAULT TRUE,
    session_retention_days INTEGER NOT NULL DEFAULT 90,
    detect_circular_reasoning BOOLEAN NOT NULL DEFAULT TRUE,
    circular_citation_penalty DECIMAL(3,2) NOT NULL DEFAULT 0.15,
    score_question_quality BOOLEAN NOT NULL DEFAULT TRUE,
    cost_mode_question_limits JSONB NOT NULL DEFAULT '{"economy": 3, "balanced": 5, "thorough": 8}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_final_reports
CREATE TABLE IF NOT EXISTS crucible_final_reports (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES crucible_sessions(id) ON DELETE CASCADE,
    participant_id VARCHAR(64) NOT NULL,
    refined_output TEXT NOT NULL,
    refinement_notes TEXT,
    confidence DECIMAL(4,3) NOT NULL,
    self_assessed_accuracy DECIMAL(4,3) NOT NULL,
    key_insights JSONB NOT NULL DEFAULT '[]',
    identified_weaknesses JSONB NOT NULL DEFAULT '[]',
    final_score DECIMAL(5,3),
    score_breakdown JSONB,
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(session_id, participant_id)
);

-- Table: crucible_learning_insights
CREATE TABLE IF NOT EXISTS crucible_learning_insights (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id UUID REFERENCES crucible_sessions(id) ON DELETE SET NULL,
    insight_type crucible_insight_type NOT NULL,
    model_id VARCHAR(255),
    description TEXT NOT NULL,
    confidence DECIMAL(4,3) NOT NULL,
    actionable BOOLEAN NOT NULL DEFAULT FALSE,
    applied BOOLEAN NOT NULL DEFAULT FALSE,
    applied_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_model_performance
CREATE TABLE IF NOT EXISTS crucible_model_performance (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    model_name VARCHAR(255) NOT NULL,
    sessions_participated INTEGER NOT NULL DEFAULT 0,
    wins INTEGER NOT NULL DEFAULT 0,
    total_score DECIMAL(10,3) NOT NULL DEFAULT 0,
    total_questions_asked INTEGER NOT NULL DEFAULT 0,
    high_quality_questions INTEGER NOT NULL DEFAULT 0,
    circular_citations INTEGER NOT NULL DEFAULT 0,
    last_session_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, model_id)
);

-- Table: crucible_participants
CREATE TABLE IF NOT EXISTS crucible_participants (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES crucible_sessions(id) ON DELETE CASCADE,
    participant_id VARCHAR(64) NOT NULL,
    model_id VARCHAR(255) NOT NULL,
    model_name VARCHAR(255) NOT NULL,
    provider VARCHAR(100) NOT NULL,
    model_type crucible_model_type NOT NULL,
    can_deliberate BOOLEAN NOT NULL,
    model_mode VARCHAR(100),
    integrity_score DECIMAL(4,3),
    was_interrogated BOOLEAN NOT NULL DEFAULT FALSE,
    questions_remaining INTEGER NOT NULL,
    questions_asked INTEGER NOT NULL DEFAULT 0,
    questions_received INTEGER NOT NULL DEFAULT 0,
    score_adjustment DECIMAL(5,3) NOT NULL DEFAULT 0,
    circular_citations INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(session_id, participant_id)
);

-- Table: crucible_questions
CREATE TABLE IF NOT EXISTS crucible_questions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id UUID NOT NULL REFERENCES crucible_sessions(id) ON DELETE CASCADE,
    asker_id VARCHAR(64) NOT NULL,
    target_id VARCHAR(64) NOT NULL,
    question_number INTEGER NOT NULL,
    question_type crucible_question_type NOT NULL,
    question_text TEXT NOT NULL,
    quality_score crucible_question_quality,
    is_iterative_refinement BOOLEAN NOT NULL DEFAULT FALSE,
    previous_question_id UUID REFERENCES crucible_questions(id),
    asked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_sessions
CREATE TABLE IF NOT EXISTS crucible_sessions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pipeline_execution_id UUID NOT NULL,
    method_invocation_id UUID NOT NULL,
    method_name VARCHAR(255) NOT NULL,
    status crucible_session_status NOT NULL DEFAULT 'initializing',
    config JSONB NOT NULL,
    pre_prompt JSONB,
    total_questions_asked INTEGER NOT NULL DEFAULT 0,
    questions_remaining INTEGER NOT NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deliberation_started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    error TEXT,
    summary JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_system_config
CREATE TABLE IF NOT EXISTS crucible_system_config (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    default_max_questions INTEGER NOT NULL DEFAULT 5,
    question_timeout_seconds INTEGER NOT NULL DEFAULT 30,
    session_timeout_seconds INTEGER NOT NULL DEFAULT 180,
    min_llms_for_crucible INTEGER NOT NULL DEFAULT 2,
    default_cost_mode crucible_cost_mode NOT NULL DEFAULT 'balanced',
    cost_mode_question_limits JSONB NOT NULL DEFAULT '{"economy": 3, "balanced": 5, "thorough": 8}',
    circular_citation_penalty DECIMAL(3,2) NOT NULL DEFAULT 0.15,
    allow_tenant_override BOOLEAN NOT NULL DEFAULT TRUE,
    allow_user_override BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_tenant_config
CREATE TABLE IF NOT EXISTS crucible_tenant_config (
    tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    -- Override flags (NULL = use system default)
    max_questions_override INTEGER,
    question_timeout_override INTEGER,
    session_timeout_override INTEGER,
    min_llms_override INTEGER,
    cost_mode_override crucible_cost_mode,
    cost_mode_limits_override JSONB,
    circular_penalty_override DECIMAL(3,2),
    -- Tenant-specific settings
    allow_user_override BOOLEAN NOT NULL DEFAULT TRUE,
    show_deliberation_to_users BOOLEAN NOT NULL DEFAULT TRUE,
    auto_enable_for_multi_llm BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: crucible_user_preferences
CREATE TABLE IF NOT EXISTS crucible_user_preferences (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    scope crucible_preference_scope NOT NULL DEFAULT 'global',
    -- Scope identifiers (NULL for global)
    method_id VARCHAR(255),
    workflow_id UUID,
    -- User preferences (NULL = use tenant/system default)
    max_questions INTEGER,
    cost_mode crucible_cost_mode,
    enabled BOOLEAN,
    -- Track if user explicitly set this (even if same as default)
    explicitly_set BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT unique_user_scope UNIQUE (tenant_id, user_id, scope, method_id, workflow_id)
);

-- Table: curator_ai_extractions
CREATE TABLE IF NOT EXISTS curator_ai_extractions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    document_id UUID NOT NULL,
    extraction_type VARCHAR(50) NOT NULL,
    extracted_items JSONB NOT NULL,
    total_extracted INTEGER NOT NULL DEFAULT 0,
    model_used VARCHAR(100) NOT NULL,
    confidence_avg DECIMAL(5,4),
    processing_time_ms INTEGER,
    uep_envelope_id UUID,
    trace_id VARCHAR(64),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT curator_extraction_type_check CHECK (extraction_type IN ('facts', 'procedures', 'entities', 'concepts', 'relationships', 'mixed'))
);

-- Table: curator_ai_questions
CREATE TABLE IF NOT EXISTS curator_ai_questions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    exam_id UUID,
    question_type VARCHAR(30) NOT NULL,
    statement TEXT NOT NULL,
    correct_answer VARCHAR(10),
    option_a TEXT,
    option_b TEXT,
    source_node_id UUID,
    confidence DECIMAL(5,4) NOT NULL,
    difficulty VARCHAR(10) NOT NULL,
    ai_reasoning TEXT,
    uep_envelope_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT curator_question_type_check CHECK (question_type IN ('fact_check', 'logic_check', 'ambiguity')),
    CONSTRAINT curator_question_difficulty_check CHECK (difficulty IN ('easy', 'medium', 'hard'))
);

-- Table: curator_ai_verifications
CREATE TABLE IF NOT EXISTS curator_ai_verifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    question_id UUID NOT NULL REFERENCES curator_ai_questions(id),
    user_answer TEXT NOT NULL,
    is_correct BOOLEAN NOT NULL,
    confidence DECIMAL(5,4) NOT NULL,
    ai_assessment TEXT,
    suggested_correction TEXT,
    should_create_golden_rule BOOLEAN DEFAULT FALSE,
    golden_rule_reason TEXT,
    uep_envelope_id UUID,
    verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: curator_audit_log
CREATE TABLE IF NOT EXISTS curator_audit_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    entity_type VARCHAR(50) NOT NULL,
    entity_id UUID NOT NULL,
    action VARCHAR(20) NOT NULL,
    actor_id UUID,
    actor_type VARCHAR(20) DEFAULT 'user',
    old_value JSONB,
    new_value JSONB,
    reason TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: curator_documents
CREATE TABLE IF NOT EXISTS curator_documents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain_id UUID REFERENCES curator_domains(id) ON DELETE SET NULL,
    filename VARCHAR(255) NOT NULL,
    original_filename VARCHAR(255) NOT NULL,
    file_type VARCHAR(50) NOT NULL,
    file_size BIGINT NOT NULL,
    storage_key VARCHAR(500),
    checksum VARCHAR(64),
    status VARCHAR(20) DEFAULT 'pending',
    processing_started_at TIMESTAMPTZ,
    processing_completed_at TIMESTAMPTZ,
    nodes_created INTEGER DEFAULT 0,
    error_message TEXT,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    created_by UUID,
    CONSTRAINT valid_doc_status CHECK (status IN ('pending', 'processing', 'completed', 'failed', 'archived'))
);

-- Table: curator_domains
CREATE TABLE IF NOT EXISTS curator_domains (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    parent_id UUID REFERENCES curator_domains(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    slug VARCHAR(100) NOT NULL,
    icon_name VARCHAR(50),
    settings JSONB DEFAULT '{
        "auto_categorize": true,
        "require_verification": true,
        "retention_days": null
    }'::jsonb,
    node_count INTEGER DEFAULT 0,
    document_count INTEGER DEFAULT 0,
    depth INTEGER DEFAULT 0,
    path_ids UUID[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    created_by UUID,
    UNIQUE(tenant_id, parent_id, slug)
);

-- Table: curator_knowledge_edges
CREATE TABLE IF NOT EXISTS curator_knowledge_edges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source_node_id UUID NOT NULL REFERENCES curator_knowledge_nodes(id) ON DELETE CASCADE,
    target_node_id UUID NOT NULL REFERENCES curator_knowledge_nodes(id) ON DELETE CASCADE,
    relationship_type VARCHAR(50) NOT NULL,
    weight DECIMAL(5,2) DEFAULT 1.0,
    bidirectional BOOLEAN DEFAULT false,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, source_node_id, target_node_id, relationship_type)
);

-- Table: curator_knowledge_nodes
CREATE TABLE IF NOT EXISTS curator_knowledge_nodes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain_id UUID REFERENCES curator_domains(id) ON DELETE SET NULL,
    node_type VARCHAR(30) NOT NULL,
    label TEXT NOT NULL,
    content TEXT,
    source_document_id UUID,
    source_location JSONB,
    confidence DECIMAL(5,2) DEFAULT 0,
    status VARCHAR(20) DEFAULT 'pending',
    verified_at TIMESTAMPTZ,
    verified_by UUID,
    override_value TEXT,
    override_reason TEXT,
    override_at TIMESTAMPTZ,
    override_by UUID,
    ai_reasoning TEXT,
    embedding vector(1536),
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT valid_node_type CHECK (node_type IN ('concept', 'fact', 'procedure', 'entity', 'rule', 'constraint')),
    CONSTRAINT valid_status CHECK (status IN ('pending', 'verified', 'rejected', 'overridden', 'archived'))
);

-- Table: curator_verification_queue
CREATE TABLE IF NOT EXISTS curator_verification_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    node_id UUID NOT NULL REFERENCES curator_knowledge_nodes(id) ON DELETE CASCADE,
    statement TEXT NOT NULL,
    ai_confidence DECIMAL(5,2) NOT NULL,
    ai_reasoning TEXT,
    source_reference TEXT,
    domain_path TEXT,
    priority INTEGER DEFAULT 0,
    status VARCHAR(20) DEFAULT 'pending',
    reviewed_at TIMESTAMPTZ,
    reviewed_by UUID,
    review_comment TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT valid_queue_status CHECK (status IN ('pending', 'approved', 'rejected', 'deferred'))
);

-- Table: curiosity_goals
CREATE TABLE IF NOT EXISTS curiosity_goals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  type VARCHAR(20) NOT NULL CHECK (type IN ('assigned', 'inferred', 'emergent', 'maintenance')),
  description TEXT NOT NULL,
  priority INTEGER DEFAULT 5 CHECK (priority BETWEEN 1 AND 10),
  status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'completed', 'abandoned')),
  curiosity_source_id UUID REFERENCES knowledge_gaps(id),
  exploration_strategy TEXT,
  progress DECIMAL(3,2) DEFAULT 0,
  milestones JSONB DEFAULT '[]',
  tokens_used INTEGER DEFAULT 0,
  cost_used DECIMAL(10,4) DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  target_completion_date TIMESTAMPTZ,
  completed_at TIMESTAMPTZ
);

-- Table: curiosity_topics
CREATE TABLE IF NOT EXISTS curiosity_topics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    topic_id TEXT UNIQUE,
    topic TEXT NOT NULL,
    topic_embedding vector(1536),
    domain TEXT,
    interest_level NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    novelty_score NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    learning_potential NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    current_understanding NUMERIC(5,4) NOT NULL DEFAULT 0,
    discovered_via TEXT,
    knowledge_gaps JSONB DEFAULT '[]'::jsonb,
    exploration_status TEXT NOT NULL DEFAULT 'identified' 
        CHECK (exploration_status IN ('identified', 'exploring', 'learned', 'abandoned')),
    times_explored INTEGER NOT NULL DEFAULT 0,
    last_explored TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: custom_terminology
CREATE TABLE IF NOT EXISTS custom_terminology (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    original_term VARCHAR(200) NOT NULL,
    custom_term VARCHAR(200) NOT NULL,
    context VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, original_term, context)
);

-- Table: data_breach_incidents
CREATE TABLE IF NOT EXISTS data_breach_incidents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL = platform-wide
    
    -- Incident details
    incident_type VARCHAR(50) NOT NULL CHECK (incident_type IN (
        'unauthorized_access',
        'data_theft',
        'ransomware',
        'accidental_disclosure',
        'system_breach',
        'insider_threat',
        'other'
    )),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('critical', 'high', 'medium', 'low')),
    
    -- Discovery
    discovered_at TIMESTAMPTZ NOT NULL,
    discovered_by UUID REFERENCES users(id),
    discovery_method VARCHAR(100),
    
    -- Impact assessment
    data_types_affected TEXT[],
    records_affected INTEGER,
    users_affected INTEGER,
    phi_involved BOOLEAN DEFAULT false,
    
    -- Description
    description TEXT NOT NULL,
    root_cause TEXT,
    
    -- Containment
    contained_at TIMESTAMPTZ,
    containment_actions TEXT,
    
    -- Notification (GDPR: 72 hours to DPA, HIPAA: 60 days to affected)
    dpa_notified_at TIMESTAMPTZ,
    dpa_notification_ref VARCHAR(100),
    users_notified_at TIMESTAMPTZ,
    notification_method VARCHAR(50),
    
    -- Resolution
    resolved_at TIMESTAMPTZ,
    resolution_actions TEXT,
    lessons_learned TEXT,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'open' CHECK (status IN (
        'open',
        'contained',
        'notifying',
        'resolved',
        'closed'
    )),
    
    -- Audit
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: data_processing_agreements
CREATE TABLE IF NOT EXISTS data_processing_agreements (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL = platform-level
    
    -- Processor details
    processor_name VARCHAR(200) NOT NULL,
    processor_type VARCHAR(30) NOT NULL CHECK (processor_type IN (
        'ai_provider',
        'cloud_infrastructure',
        'analytics',
        'payment',
        'support',
        'other'
    )),
    
    -- Agreement
    dpa_signed_date DATE,
    dpa_expiry_date DATE,
    dpa_document_url TEXT,
    
    -- Data handled
    data_categories TEXT[], -- e.g., ['user_data', 'usage_data', 'phi']
    processing_purposes TEXT[],
    data_locations TEXT[], -- Regions where data is processed
    
    -- Security measures
    security_measures JSONB DEFAULT '{}',
    certifications TEXT[], -- e.g., ['SOC2', 'ISO27001', 'HIPAA']
    
    -- Contact
    dpo_contact VARCHAR(255),
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN (
        'pending',
        'active', 
        'expired',
        'terminated'
    )),
    
    -- Audit
    last_review_date DATE,
    next_review_date DATE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: data_retention_obligations
CREATE TABLE IF NOT EXISTS data_retention_obligations (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id),
  tenant_id UUID NOT NULL REFERENCES tenants(id),
  table_name VARCHAR(100) NOT NULL,
  record_id UUID NOT NULL,
  retention_reason VARCHAR(255) NOT NULL,
  retention_category VARCHAR(50) NOT NULL CHECK (
    retention_category IN ('regulatory', 'contractual', 'legal_hold', 'litigation', 'audit', 'business')
  ),
  retention_expires TIMESTAMPTZ NOT NULL,
  
  -- Legal Hold Support
  legal_hold BOOLEAN DEFAULT false,
  legal_hold_reason TEXT,
  legal_hold_set_by UUID REFERENCES users(id),
  legal_hold_set_at TIMESTAMPTZ,
  legal_hold_case_id VARCHAR(100),
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES users(id),
  released_at TIMESTAMPTZ,
  released_by UUID REFERENCES users(id)
);

-- Table: data_retention_policies
CREATE TABLE IF NOT EXISTS data_retention_policies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL = global policy
    
    -- Policy definition
    data_type VARCHAR(100) NOT NULL, -- e.g., 'session_data', 'audit_logs', 'user_data'
    retention_days INTEGER NOT NULL,
    legal_basis VARCHAR(50) NOT NULL CHECK (legal_basis IN (
        'consent',           -- User consent
        'contract',          -- Necessary for contract
        'legal_obligation',  -- Legal requirement
        'vital_interests',   -- Protect vital interests
        'public_interest',   -- Public interest
        'legitimate_interest' -- Legitimate business interest
    )),
    
    -- Actions
    action_on_expiry VARCHAR(30) NOT NULL DEFAULT 'delete' CHECK (action_on_expiry IN (
        'delete',      -- Hard delete
        'anonymize',   -- Remove PII but keep data
        'archive',     -- Move to archive
        'review'       -- Flag for manual review
    )),
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Metadata
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, data_type)
);

-- Table: debate_arenas
CREATE TABLE IF NOT EXISTS debate_arenas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    topic VARCHAR(500) NOT NULL,
    proposition TEXT NOT NULL,
    status debate_status NOT NULL DEFAULT 'setup',
    resolution_balance INTEGER DEFAULT 0 CHECK (resolution_balance >= -100 AND resolution_balance <= 100),
    resolution_tracker JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by UUID NOT NULL
);

-- Table: debate_arguments
CREATE TABLE IF NOT EXISTS debate_arguments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    arena_id UUID NOT NULL REFERENCES debate_arenas(id) ON DELETE CASCADE,
    debater_id UUID NOT NULL REFERENCES debaters(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    argument_type debate_argument_type NOT NULL DEFAULT 'claim',
    strength INTEGER DEFAULT 50 CHECK (strength >= 0 AND strength <= 100),
    target_argument_id UUID REFERENCES debate_arguments(id),
    supporting_argument_ids UUID[] DEFAULT '{}',
    living_ink JSONB DEFAULT '{}',
    position JSONB DEFAULT '{"x": 0, "y": 0}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: debaters
CREATE TABLE IF NOT EXISTS debaters (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    arena_id UUID NOT NULL REFERENCES debate_arenas(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    side VARCHAR(50) NOT NULL CHECK (side IN ('proposition', 'opposition')),
    model_id VARCHAR(255) NOT NULL,
    style debater_style NOT NULL DEFAULT 'balanced',
    position_heatmap JSONB DEFAULT '{}',
    current_strength INTEGER DEFAULT 50 CHECK (current_strength >= 0 AND current_strength <= 100),
    avatar JSONB DEFAULT '{"color": "#3b82f6", "icon": "user"}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: decision_artifact_access_log
CREATE TABLE IF NOT EXISTS decision_artifact_access_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id UUID NOT NULL REFERENCES decision_artifacts(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    action VARCHAR(32) NOT NULL
        CHECK (action IN ('viewed', 'downloaded', 'exported', 'shared', 'validated', 'edited')),
    
    ip_address INET,
    user_agent TEXT,
    metadata JSONB DEFAULT '{}',
    
    accessed_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: decision_artifact_config
CREATE TABLE IF NOT EXISTS decision_artifact_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Feature toggles
    dia_enabled BOOLEAN DEFAULT TRUE,
    auto_generate_enabled BOOLEAN DEFAULT FALSE,
    phi_detection_enabled BOOLEAN DEFAULT TRUE,
    pii_detection_enabled BOOLEAN DEFAULT TRUE,
    
    -- Default settings
    default_staleness_threshold_days INT DEFAULT 7,
    max_artifacts_per_user INT DEFAULT 0,  -- 0 = unlimited
    max_claims_per_artifact INT DEFAULT 100,
    
    -- Compliance settings
    required_compliance_frameworks TEXT[] DEFAULT '{}',
    auto_redact_phi_on_export BOOLEAN DEFAULT FALSE,
    audit_all_access BOOLEAN DEFAULT TRUE,
    
    -- Model settings
    extraction_model VARCHAR(100) DEFAULT 'anthropic.claude-3-5-sonnet-20241022-v2:0',
    max_extraction_tokens INT DEFAULT 4096,
    
    -- Export settings
    export_retention_days INT DEFAULT 30,
    allowed_export_formats TEXT[] DEFAULT '{pdf,json,hipaa_audit,soc2_evidence,gdpr_dsar}',
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: decision_artifact_export_log
CREATE TABLE IF NOT EXISTS decision_artifact_export_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id UUID NOT NULL REFERENCES decision_artifacts(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    export_format VARCHAR(32) NOT NULL
        CHECK (export_format IN ('pdf', 'json', 'hipaa_audit', 'soc2_evidence', 'gdpr_dsar', 'mcp_resource')),
    compliance_framework VARCHAR(32),
    exported_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    exported_at TIMESTAMPTZ DEFAULT NOW(),
    recipient_description TEXT,
    purpose TEXT,
    export_hash VARCHAR(64),
    s3_key VARCHAR(500),
    file_size_bytes BIGINT,
    redaction_applied BOOLEAN DEFAULT FALSE
);

-- Table: decision_artifact_templates
CREATE TABLE IF NOT EXISTS decision_artifact_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = system template
    
    name VARCHAR(200) NOT NULL,
    description TEXT,
    category VARCHAR(50) DEFAULT 'general',
    
    -- Template configuration
    extraction_prompt TEXT,
    claim_types TEXT[] DEFAULT '{conclusion,finding,recommendation,warning,fact}',
    required_evidence_types TEXT[] DEFAULT '{tool_call}',
    
    -- Display settings
    default_lens VARCHAR(20) DEFAULT 'read',
    show_ghost_paths BOOLEAN DEFAULT TRUE,
    show_heatmap BOOLEAN DEFAULT TRUE,
    
    -- Compliance presets
    compliance_frameworks TEXT[] DEFAULT '{}',
    sensitivity_level VARCHAR(20) DEFAULT 'low',
    
    is_system BOOLEAN DEFAULT FALSE,
    is_active BOOLEAN DEFAULT TRUE,
    usage_count INT DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: decision_artifact_validation_log
CREATE TABLE IF NOT EXISTS decision_artifact_validation_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id UUID NOT NULL REFERENCES decision_artifacts(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    query_id VARCHAR(100) NOT NULL,
    tool_name VARCHAR(100) NOT NULL,
    validation_status VARCHAR(32) NOT NULL
        CHECK (validation_status IN ('unchanged', 'changed', 'error', 'unavailable')),
    original_result_hash VARCHAR(64),
    new_result_hash VARCHAR(64),
    diff_summary TEXT,
    significance VARCHAR(32)
        CHECK (significance IN ('none', 'minor', 'moderate', 'significant', 'critical')),
    api_cost_cents INT DEFAULT 0,
    validated_at TIMESTAMPTZ DEFAULT NOW(),
    validated_by UUID REFERENCES users(id) ON DELETE SET NULL
);

-- Table: decision_artifacts
CREATE TABLE IF NOT EXISTS decision_artifacts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID NOT NULL REFERENCES thinktank_conversations(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Artifact metadata
    title VARCHAR(500) NOT NULL,
    summary TEXT,
    status VARCHAR(32) DEFAULT 'active' 
        CHECK (status IN ('active', 'frozen', 'archived', 'invalidated')),
    version INT DEFAULT 1,
    parent_artifact_id UUID REFERENCES decision_artifacts(id) ON DELETE SET NULL,
    
    -- The structured decision graph (JSONB)
    artifact_content JSONB NOT NULL DEFAULT '{}',
    
    -- Extraction metadata
    miner_model VARCHAR(100),
    extraction_confidence DECIMAL(3,2) CHECK (extraction_confidence BETWEEN 0 AND 1),
    extraction_timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Validation tracking
    last_validated_at TIMESTAMPTZ,
    validation_status VARCHAR(32) DEFAULT 'fresh'
        CHECK (validation_status IN ('fresh', 'stale', 'verified', 'invalidated')),
    staleness_threshold_days INT DEFAULT 7,
    
    -- Heatmap support (pre-computed for performance)
    heatmap_data JSONB DEFAULT '[]',
    
    -- Compliance metadata
    compliance_frameworks TEXT[] DEFAULT '{}',
    phi_detected BOOLEAN DEFAULT FALSE,
    pii_detected BOOLEAN DEFAULT FALSE,
    data_classification VARCHAR(32) DEFAULT 'internal'
        CHECK (data_classification IN ('public', 'internal', 'confidential', 'restricted')),
    
    -- Domain classification
    primary_domain VARCHAR(100),
    secondary_domains TEXT[] DEFAULT '{}',
    
    -- Audit trail
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    frozen_at TIMESTAMPTZ,
    frozen_by UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Tamper evidence
    content_hash VARCHAR(64),
    signature_timestamp TIMESTAMPTZ
);

-- Table: decision_audit
CREATE TABLE IF NOT EXISTS decision_audit (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  decision_id UUID NOT NULL REFERENCES pending_decisions(id),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Action details
  action VARCHAR(50) NOT NULL,  -- 'created', 'viewed', 'resolved', 'expired', 'escalated'
  actor_id UUID REFERENCES users(id),
  actor_type VARCHAR(50) NOT NULL,  -- 'user', 'system', 'timeout_lambda', 'cato'
  
  -- Details
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  ip_address INET,
  user_agent TEXT,
  
  -- Timestamp
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: decision_domain_config
CREATE TABLE IF NOT EXISTS decision_domain_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = global default
  
  -- Domain
  domain VARCHAR(50) NOT NULL CHECK (domain IN ('medical', 'financial', 'legal', 'general')),
  
  -- Timeout settings
  default_timeout_seconds INTEGER NOT NULL,
  escalation_timeout_seconds INTEGER NOT NULL,
  
  -- Escalation settings
  auto_escalate BOOLEAN DEFAULT TRUE,
  escalation_channel VARCHAR(100),  -- 'pagerduty', 'slack', 'email', 'sms'
  escalation_target VARCHAR(256),   -- channel ID, email, phone
  
  -- Access control
  required_roles TEXT[] DEFAULT '{}',  -- e.g., ['MD', 'RN'] for medical
  
  -- Feature flags
  allow_auto_resolve BOOLEAN DEFAULT FALSE,
  require_guidance BOOLEAN DEFAULT TRUE,
  
  -- Metadata
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE (tenant_id, domain)
);

-- Table: deep_thinking_sessions
CREATE TABLE IF NOT EXISTS deep_thinking_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id),
    prompt TEXT NOT NULL,
    reasoning_tree_id UUID,
    metrics_before JSONB DEFAULT '{}'::jsonb,
    metrics_after JSONB DEFAULT '{}'::jsonb,
    insights TEXT[] DEFAULT '{}',
    self_reflections TEXT[] DEFAULT '{}',
    creative_ideas TEXT[] DEFAULT '{}',
    duration_ms INTEGER,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'interrupted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: default_brain_regions
CREATE TABLE IF NOT EXISTS default_brain_regions (
    region_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(100) NOT NULL,
    slug VARCHAR(50) NOT NULL UNIQUE,
    description TEXT,
    icon VARCHAR(50),
    color VARCHAR(7),
    cognitive_function VARCHAR(100) NOT NULL,
    human_brain_analog VARCHAR(100),
    primary_model_id VARCHAR(100) NOT NULL,
    fallback_model_ids TEXT[] DEFAULT '{}',
    activation_triggers JSONB DEFAULT '[]',
    priority INTEGER DEFAULT 50,
    is_active BOOLEAN DEFAULT true
);

-- Table: default_moral_principles
CREATE TABLE IF NOT EXISTS default_moral_principles (
    default_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    principle_number INTEGER NOT NULL UNIQUE,
    title VARCHAR(200) NOT NULL,
    principle_text TEXT NOT NULL,
    explanation TEXT,
    positive_behaviors JSONB DEFAULT '[]',
    negative_behaviors JSONB DEFAULT '[]',
    example_applications JSONB DEFAULT '[]',
    category VARCHAR(100),
    priority INTEGER DEFAULT 5,
    is_absolute BOOLEAN DEFAULT false
);

-- Table: delight_achievement_stats
CREATE TABLE IF NOT EXISTS delight_achievement_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    achievement_id VARCHAR(50) NOT NULL REFERENCES delight_achievements(id) ON DELETE CASCADE,
    
    -- Lifetime statistics
    total_unlocked INTEGER DEFAULT 0,
    total_in_progress INTEGER DEFAULT 0,
    
    -- Time-based stats
    unlocked_today INTEGER DEFAULT 0,
    unlocked_this_week INTEGER DEFAULT 0,
    unlocked_this_month INTEGER DEFAULT 0,
    
    -- Completion rate
    average_days_to_unlock DECIMAL(6,2),
    fastest_unlock_days DECIMAL(6,2),
    
    first_unlocked_at TIMESTAMP WITH TIME ZONE,
    last_unlocked_at TIMESTAMP WITH TIME ZONE,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, achievement_id)
);

-- Table: delight_achievements
CREATE TABLE IF NOT EXISTS delight_achievements (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    icon VARCHAR(50),
    badge_image_url VARCHAR(500),
    
    -- Unlock conditions
    achievement_type VARCHAR(50) NOT NULL, -- domain_explorer, streak, complexity, discovery, time_spent, queries_count
    threshold_value INTEGER DEFAULT 1,
    threshold_conditions JSONB DEFAULT '{}',
    
    -- Celebration
    celebration_message TEXT,
    celebration_sound VARCHAR(50),
    celebration_animation VARCHAR(50),
    
    -- Rarity
    rarity VARCHAR(20) DEFAULT 'common', -- common, uncommon, rare, epic, legendary
    points INTEGER DEFAULT 10,
    
    is_hidden BOOLEAN DEFAULT FALSE, -- Hidden until unlocked
    is_enabled BOOLEAN DEFAULT TRUE,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: delight_categories
CREATE TABLE IF NOT EXISTS delight_categories (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    icon VARCHAR(50),
    sort_order INTEGER DEFAULT 0,
    is_enabled BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: delight_daily_stats
CREATE TABLE IF NOT EXISTS delight_daily_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    stat_date DATE NOT NULL,
    
    -- Message statistics
    messages_shown INTEGER DEFAULT 0,
    unique_messages_shown INTEGER DEFAULT 0,
    messages_by_category JSONB DEFAULT '{}',  -- { "domain_loading": 10, "time_awareness": 5, ... }
    messages_by_injection_point JSONB DEFAULT '{}',  -- { "pre_execution": 20, "during_execution": 15, ... }
    messages_by_trigger_type JSONB DEFAULT '{}',  -- { "domain_loading": 10, "time_aware": 5, ... }
    
    -- Achievement statistics
    achievements_unlocked INTEGER DEFAULT 0,
    achievements_by_type JSONB DEFAULT '{}',  -- { "domain_explorer": 5, "streak": 3, ... }
    achievements_by_rarity JSONB DEFAULT '{}',  -- { "common": 10, "rare": 2, "legendary": 0 }
    
    -- Easter egg statistics
    easter_eggs_discovered INTEGER DEFAULT 0,
    easter_eggs_by_id JSONB DEFAULT '{}',  -- { "konami": 3, "chaos_mode": 5, ... }
    
    -- User engagement
    active_users INTEGER DEFAULT 0,
    users_by_personality_mode JSONB DEFAULT '{}',  -- { "professional": 10, "expressive": 50, ... }
    average_intensity_level DECIMAL(3,1) DEFAULT 5.0,
    
    -- Sound statistics
    sounds_played INTEGER DEFAULT 0,
    sounds_by_theme JSONB DEFAULT '{}',  -- { "default": 100, "mission_control": 20, ... }
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, stat_date)
);

-- Table: delight_easter_egg_stats
CREATE TABLE IF NOT EXISTS delight_easter_egg_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    easter_egg_id VARCHAR(50) NOT NULL REFERENCES delight_easter_eggs(id) ON DELETE CASCADE,
    
    -- Lifetime statistics
    total_discoveries INTEGER DEFAULT 0,
    total_activations INTEGER DEFAULT 0,  -- Some eggs can be triggered multiple times
    
    -- Time-based stats
    discovered_today INTEGER DEFAULT 0,
    discovered_this_week INTEGER DEFAULT 0,
    discovered_this_month INTEGER DEFAULT 0,
    
    first_discovered_at TIMESTAMP WITH TIME ZONE,
    last_discovered_at TIMESTAMP WITH TIME ZONE,
    
    -- Most common discovery hour (for time-based eggs)
    discovery_by_hour JSONB DEFAULT '{}',
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, easter_egg_id)
);

-- Table: delight_easter_eggs
CREATE TABLE IF NOT EXISTS delight_easter_eggs (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    
    -- Trigger
    trigger_type VARCHAR(30) NOT NULL, -- key_sequence, text_input, time_based, random, usage_pattern
    trigger_value TEXT NOT NULL, -- The actual trigger (e.g., "up,up,down,down,left,right,left,right,b,a")
    
    -- Effect
    effect_type VARCHAR(30) NOT NULL, -- mode_change, visual_transform, sound_play, message_show, interface_mod
    effect_config JSONB DEFAULT '{}',
    effect_duration_seconds INTEGER DEFAULT 30, -- 0 = permanent until toggled off
    
    -- Content
    activation_message TEXT,
    deactivation_message TEXT,
    
    is_enabled BOOLEAN DEFAULT TRUE,
    discovery_count INTEGER DEFAULT 0, -- Track how many users have found it
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: delight_event_log
CREATE TABLE IF NOT EXISTS delight_event_log (
    id SERIAL PRIMARY KEY,
    user_id VARCHAR(255) NOT NULL,
    tenant_id VARCHAR(255) NOT NULL,
    
    event_type VARCHAR(30) NOT NULL, -- message_shown, achievement_unlocked, easter_egg_found, sound_played
    event_data JSONB DEFAULT '{}',
    
    message_id INTEGER REFERENCES delight_messages(id) ON DELETE SET NULL,
    achievement_id VARCHAR(50) REFERENCES delight_achievements(id) ON DELETE SET NULL,
    easter_egg_id VARCHAR(50) REFERENCES delight_easter_eggs(id) ON DELETE SET NULL,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: delight_message_stats
CREATE TABLE IF NOT EXISTS delight_message_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    message_id INTEGER NOT NULL REFERENCES delight_messages(id) ON DELETE CASCADE,
    
    -- Lifetime statistics
    total_shown INTEGER DEFAULT 0,
    total_unique_users INTEGER DEFAULT 0,
    
    -- Time-based stats
    shown_today INTEGER DEFAULT 0,
    shown_this_week INTEGER DEFAULT 0,
    shown_this_month INTEGER DEFAULT 0,
    
    -- Performance metrics
    first_shown_at TIMESTAMP WITH TIME ZONE,
    last_shown_at TIMESTAMP WITH TIME ZONE,
    
    -- Tracking for rate limiting
    shown_by_hour JSONB DEFAULT '{}',  -- { "0": 5, "1": 3, ..., "23": 10 }
    shown_by_day_of_week JSONB DEFAULT '{}',  -- { "0": 50, "1": 100, ..., "6": 30 }
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, message_id)
);

-- Table: delight_messages
CREATE TABLE IF NOT EXISTS delight_messages (
    id SERIAL PRIMARY KEY,
    category_id VARCHAR(50) NOT NULL REFERENCES delight_categories(id) ON DELETE CASCADE,
    
    -- Injection point: pre_execution, during_execution, post_execution
    injection_point VARCHAR(30) NOT NULL CHECK (injection_point IN ('pre_execution', 'during_execution', 'post_execution')),
    
    -- Trigger conditions (JSON for flexibility)
    trigger_type VARCHAR(50) NOT NULL, -- domain_loading, domain_transition, time_aware, model_dynamics, achievement, wellbeing, easter_egg
    trigger_conditions JSONB DEFAULT '{}',
    
    -- Message content
    message_text TEXT NOT NULL,
    message_alt_texts TEXT[] DEFAULT '{}', -- Alternative versions for variety
    
    -- Domain/context targeting
    domain_families TEXT[] DEFAULT '{}', -- Empty means all domains
    specific_domains TEXT[] DEFAULT '{}',
    
    -- Model targeting
    target_models TEXT[] DEFAULT '{}', -- Empty means all models
    
    -- Time targeting
    time_contexts TEXT[] DEFAULT '{}', -- morning, afternoon, evening, night, weekend, holiday
    
    -- Display settings
    display_duration_ms INTEGER DEFAULT 3000,
    display_style VARCHAR(30) DEFAULT 'subtle', -- subtle, moderate, expressive
    animation_type VARCHAR(30) DEFAULT 'fade', -- fade, slide, bounce, none
    sound_effect VARCHAR(50), -- Optional sound to play
    
    -- Priority and frequency
    priority INTEGER DEFAULT 50, -- Higher = more likely to be selected
    cooldown_minutes INTEGER DEFAULT 0, -- Minutes before showing same message again
    max_displays_per_session INTEGER DEFAULT 0, -- 0 = unlimited
    
    -- Flags
    is_enabled BOOLEAN DEFAULT TRUE,
    requires_opt_in BOOLEAN DEFAULT FALSE, -- For more expressive/silly content
    is_easter_egg BOOLEAN DEFAULT FALSE,
    
    -- Metadata
    created_by VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: delight_sounds
CREATE TABLE IF NOT EXISTS delight_sounds (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    
    -- Sound file
    sound_url VARCHAR(500),
    sound_data_base64 TEXT, -- For small sounds, store inline
    
    -- Categorization
    sound_category VARCHAR(30) NOT NULL, -- confirmation, transition, achievement, ambient, notification
    sound_theme VARCHAR(50) DEFAULT 'default',
    
    -- Playback
    volume_default INTEGER DEFAULT 70 CHECK (volume_default BETWEEN 0 AND 100),
    duration_ms INTEGER,
    
    is_enabled BOOLEAN DEFAULT TRUE,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: delight_user_engagement
CREATE TABLE IF NOT EXISTS delight_user_engagement (
    id SERIAL PRIMARY KEY,
    user_id VARCHAR(255) NOT NULL,
    tenant_id VARCHAR(255) NOT NULL,
    
    -- Message engagement
    total_messages_seen INTEGER DEFAULT 0,
    unique_messages_seen INTEGER DEFAULT 0,
    favorite_category VARCHAR(50),
    
    -- Achievement progress
    total_achievements_unlocked INTEGER DEFAULT 0,
    total_achievement_points INTEGER DEFAULT 0,
    current_streak_days INTEGER DEFAULT 0,
    longest_streak_days INTEGER DEFAULT 0,
    
    -- Easter egg discoveries
    total_easter_eggs_found INTEGER DEFAULT 0,
    
    -- Time tracking
    first_interaction_at TIMESTAMP WITH TIME ZONE,
    last_interaction_at TIMESTAMP WITH TIME ZONE,
    total_sessions INTEGER DEFAULT 0,
    
    -- Preferences history
    personality_mode_history JSONB DEFAULT '[]',  -- Track changes over time
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(user_id, tenant_id)
);

-- Table: deployment_locks
CREATE TABLE IF NOT EXISTS deployment_locks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    app_id VARCHAR(100) NOT NULL,
    environment VARCHAR(30) NOT NULL,
    owner VARCHAR(100) NOT NULL,
    owner_id VARCHAR(100) NOT NULL,
    hostname VARCHAR(255),
    pid INTEGER,
    acquired_at TIMESTAMPTZ DEFAULT NOW(),
    last_heartbeat TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '120 seconds',
    metadata JSONB DEFAULT '{}',
    UNIQUE(tenant_id, app_id, environment)
);

-- Table: deployment_snapshots
CREATE TABLE IF NOT EXISTS deployment_snapshots (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    app_id VARCHAR(100) NOT NULL,
    environment VARCHAR(30) NOT NULL,
    version VARCHAR(20) NOT NULL,
    status VARCHAR(20) DEFAULT 'creating' CHECK (status IN ('creating', 'available', 'restoring', 'deleting', 'failed', 'expired')),
    resources JSONB DEFAULT '{}', -- Aurora, DynamoDB, S3, Lambda snapshots
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '30 days',
    metadata JSONB DEFAULT '{}'
);

-- Table: derivation_model_usage
CREATE TABLE IF NOT EXISTS derivation_model_usage (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    derivation_id UUID NOT NULL REFERENCES result_derivations(id) ON DELETE CASCADE,
    
    -- Model info
    model_id VARCHAR(100) NOT NULL,
    model_display_name VARCHAR(200) NOT NULL,
    model_family VARCHAR(50) NOT NULL,
    provider VARCHAR(20) NOT NULL,
    
    -- Purpose and context
    purpose VARCHAR(50) NOT NULL,
    step_id VARCHAR(100),
    
    -- Token usage
    input_tokens INTEGER NOT NULL DEFAULT 0,
    output_tokens INTEGER NOT NULL DEFAULT 0,
    total_tokens INTEGER NOT NULL DEFAULT 0,
    
    -- Timing
    latency_ms INTEGER NOT NULL DEFAULT 0,
    
    -- Costs
    input_cost DECIMAL(10, 6) NOT NULL DEFAULT 0,
    output_cost DECIMAL(10, 6) NOT NULL DEFAULT 0,
    total_cost DECIMAL(10, 6) NOT NULL DEFAULT 0,
    
    -- Selection details
    selection_reason TEXT,
    selection_score DECIMAL(5, 2),
    alternatives_considered TEXT[],
    
    -- Quality
    quality_tier VARCHAR(20),
    
    -- Response details
    response_length INTEGER,
    truncated BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: derivation_steps
CREATE TABLE IF NOT EXISTS derivation_steps (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    derivation_id UUID NOT NULL REFERENCES result_derivations(id) ON DELETE CASCADE,
    step_id VARCHAR(100) NOT NULL,
    step_number INTEGER NOT NULL,
    step_type VARCHAR(50) NOT NULL,
    name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'pending',
    
    -- Model used
    model_id VARCHAR(100),
    model_display_name VARCHAR(200),
    
    -- Timing
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    duration_ms INTEGER,
    
    -- Details
    details JSONB,
    error TEXT,
    
    UNIQUE(derivation_id, step_id)
);

-- Table: derivation_timeline_events
CREATE TABLE IF NOT EXISTS derivation_timeline_events (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    derivation_id UUID NOT NULL REFERENCES result_derivations(id) ON DELETE CASCADE,
    
    -- Event details
    event_type VARCHAR(50) NOT NULL,
    title VARCHAR(200) NOT NULL,
    description TEXT,
    details JSONB,
    
    -- Timing
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    duration_ms INTEGER,
    
    -- Related entities
    model_id VARCHAR(100),
    step_id VARCHAR(100)
);

-- Table: detected_errors
CREATE TABLE IF NOT EXISTS detected_errors (
    error_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Context
    session_id UUID,
    user_id UUID,
    
    -- Error details
    error_type VARCHAR(50) NOT NULL, -- 'factual', 'logical', 'consistency', 'hallucination', 'incomplete', 'misunderstanding'
    severity VARCHAR(20) NOT NULL, -- 'critical', 'major', 'minor', 'trivial'
    
    -- What contained the error
    source_type VARCHAR(50) NOT NULL, -- 'response', 'plan', 'reasoning', 'memory_retrieval', 'entity_extraction'
    source_id UUID,
    source_content TEXT NOT NULL,
    
    -- Error specifics
    error_description TEXT NOT NULL,
    error_location TEXT, -- Where in the content
    error_evidence JSONB DEFAULT '{}', -- Evidence for why this is an error
    
    -- Correction
    correction_proposed TEXT,
    correction_applied BOOLEAN DEFAULT false,
    correction_confidence DECIMAL(5,4),
    
    -- Detection method
    detection_method VARCHAR(50), -- 'self_check', 'consistency_check', 'fact_verification', 'user_feedback', 'peer_review'
    detected_by UUID, -- Agent ID if peer detected
    
    -- Impact assessment
    impact_description TEXT,
    downstream_effects JSONB DEFAULT '[]',
    
    -- Resolution
    resolution_status VARCHAR(20) DEFAULT 'detected', -- 'detected', 'analyzing', 'corrected', 'accepted', 'dismissed'
    resolved_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dialogue_sessions
CREATE TABLE IF NOT EXISTS dialogue_sessions (
    session_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Session info
    channel VARCHAR(50), -- 'chat', 'api', 'voice', 'email'
    started_at TIMESTAMPTZ DEFAULT NOW(),
    last_activity TIMESTAMPTZ DEFAULT NOW(),
    
    -- State
    status VARCHAR(20) DEFAULT 'active', -- 'active', 'paused', 'completed', 'abandoned'
    
    -- Context
    current_topic TEXT,
    topic_history TEXT[] DEFAULT '{}',
    
    -- Goals detected
    user_goals JSONB DEFAULT '[]',
    completed_goals JSONB DEFAULT '[]',
    
    -- Entities tracked
    mentioned_entities JSONB DEFAULT '{}', -- {entity_type: [{name, first_mention, last_mention}]}
    
    -- Dialogue acts
    dialogue_acts JSONB DEFAULT '[]', -- [{turn, act_type, content}]
    
    -- Sentiment tracking
    sentiment_history JSONB DEFAULT '[]', -- [{turn, sentiment}]
    overall_sentiment DECIMAL(3,2) DEFAULT 0,
    
    -- Summary
    session_summary TEXT,
    
    ended_at TIMESTAMPTZ
);

-- Table: dialogue_states
CREATE TABLE IF NOT EXISTS dialogue_states (
    state_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- State definition
    name VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    state_type VARCHAR(50), -- 'initial', 'intermediate', 'terminal', 'error'
    
    -- Entry conditions
    entry_conditions JSONB DEFAULT '{}',
    
    -- Actions on entry
    entry_actions JSONB DEFAULT '[]',
    
    -- Valid transitions
    valid_transitions JSONB DEFAULT '[]', -- [{to_state, condition, action}]
    
    -- Response templates
    response_templates JSONB DEFAULT '[]'
);

-- Table: dialogue_turns
CREATE TABLE IF NOT EXISTS dialogue_turns (
    turn_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES dialogue_sessions(session_id) ON DELETE CASCADE,
    
    -- Turn info
    turn_number INTEGER NOT NULL,
    speaker VARCHAR(20) NOT NULL, -- 'user', 'assistant', 'system'
    
    -- Content
    content TEXT NOT NULL,
    content_type VARCHAR(50) DEFAULT 'text', -- 'text', 'image', 'file', 'audio'
    
    -- Analysis
    intent VARCHAR(100),
    intent_confidence DECIMAL(5,4),
    entities_extracted JSONB DEFAULT '[]',
    sentiment DECIMAL(3,2),
    
    -- Dialogue act
    dialogue_act VARCHAR(50), -- 'question', 'answer', 'request', 'inform', 'confirm', 'reject', 'greeting', 'closing'
    
    -- Response generation
    response_strategy VARCHAR(50),
    models_used TEXT[] DEFAULT '{}',
    
    -- Performance
    response_latency_ms INTEGER,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: discovery_hotspots
CREATE TABLE IF NOT EXISTS discovery_hotspots (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    palace_id UUID NOT NULL REFERENCES memory_palaces(id) ON DELETE CASCADE,
    position JSONB NOT NULL,
    potential_insight TEXT NOT NULL,
    related_node_ids UUID[] DEFAULT '{}',
    breathing_beacon JSONB DEFAULT '{"color": "#f59e0b", "rate": 8, "radius": 20}',
    exploration_prompt TEXT,
    discovered_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: distillation_jobs
CREATE TABLE IF NOT EXISTS distillation_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  status VARCHAR(20) NOT NULL DEFAULT 'collecting' CHECK (status IN ('collecting', 'preparing', 'training', 'evaluating', 'completed', 'failed')),
  examples_collected INTEGER DEFAULT 0,
  training_job_arn VARCHAR(500),
  student_version_id UUID REFERENCES inference_student_versions(id),
  started_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  error_message TEXT
);

-- Table: distillation_training_data
CREATE TABLE IF NOT EXISTS distillation_training_data (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  input_prompt TEXT NOT NULL,
  input_context JSONB DEFAULT '{}',
  task_type VARCHAR(50) NOT NULL,
  domain_ids UUID[] DEFAULT '{}',
  teacher_model_id VARCHAR(100) NOT NULL,
  teacher_response TEXT NOT NULL,
  reasoning_trace TEXT NOT NULL,
  confidence_score DECIMAL(3,2),
  alternative_paths JSONB DEFAULT '[]',
  generation_latency_ms INTEGER,
  token_count_input INTEGER,
  token_count_output INTEGER,
  cost_usd DECIMAL(10,6),
  status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'validated', 'used', 'rejected')),
  quality_score DECIMAL(3,2),
  validated_by UUID REFERENCES users(id),
  used_in_training_job UUID,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: domain_adapter_training_queue
CREATE TABLE IF NOT EXISTS domain_adapter_training_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain TEXT NOT NULL,
    subdomain TEXT,
    
    -- Candidates waiting
    positive_candidates_count INTEGER NOT NULL DEFAULT 0,
    negative_candidates_count INTEGER NOT NULL DEFAULT 0,
    
    -- Thresholds
    min_candidates_required INTEGER NOT NULL DEFAULT 25,
    
    -- Status
    ready_for_training BOOLEAN GENERATED ALWAYS AS (
        positive_candidates_count >= min_candidates_required
    ) STORED,
    
    last_checked_at TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_domain_queue UNIQUE (tenant_id, domain, subdomain)
);

-- Table: domain_ethics_audit_log
CREATE TABLE IF NOT EXISTS domain_ethics_audit_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id UUID NOT NULL,
    prompt_id UUID NOT NULL,
    
    -- Detection
    detected_domain VARCHAR(50) NOT NULL,
    detected_subspecialty VARCHAR(100),
    
    -- Check details
    frameworks_applied JSONB NOT NULL DEFAULT '[]',
    check_result JSONB NOT NULL,
    
    -- Action
    action_taken VARCHAR(20) NOT NULL DEFAULT 'allowed'
        CHECK (action_taken IN ('allowed', 'blocked', 'modified', 'warned')),
    modifications_applied JSONB,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: domain_ethics_config
CREATE TABLE IF NOT EXISTS domain_ethics_config (
    tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Global settings
    enable_domain_ethics BOOLEAN NOT NULL DEFAULT true,
    enforcement_mode VARCHAR(20) NOT NULL DEFAULT 'standard'
        CHECK (enforcement_mode IN ('strict', 'standard', 'advisory', 'disabled')),
    
    -- Framework overrides
    disabled_frameworks JSONB NOT NULL DEFAULT '[]',
    
    -- Domain-specific settings
    domain_settings JSONB NOT NULL DEFAULT '{}',
    
    -- Logging
    log_all_checks BOOLEAN NOT NULL DEFAULT false,
    log_violations_only BOOLEAN NOT NULL DEFAULT true,
    
    -- Notifications
    notify_on_violation BOOLEAN NOT NULL DEFAULT true,
    notify_on_warning BOOLEAN NOT NULL DEFAULT false,
    notification_emails JSONB,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: domain_ethics_custom_frameworks
CREATE TABLE IF NOT EXISTS domain_ethics_custom_frameworks (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Framework identification
    framework_id VARCHAR(100) NOT NULL,
    domain VARCHAR(50) NOT NULL,
    framework_name VARCHAR(200) NOT NULL,
    framework_code VARCHAR(20) NOT NULL,
    governing_body VARCHAR(200),
    jurisdiction VARCHAR(50),
    
    -- Framework data (full JSON)
    framework_data JSONB NOT NULL,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Audit
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, framework_id)
);

-- Table: domain_ethics_framework_overrides
CREATE TABLE IF NOT EXISTS domain_ethics_framework_overrides (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    framework_id VARCHAR(100) NOT NULL,
    
    -- Override settings
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    enforcement_level VARCHAR(20) DEFAULT 'standard'
        CHECK (enforcement_level IN ('strict', 'standard', 'advisory')),
    custom_disclaimers JSONB,
    
    -- Audit
    modified_by UUID REFERENCES users(id),
    modified_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, framework_id)
);

-- Table: domain_ethics_violation_patterns
CREATE TABLE IF NOT EXISTS domain_ethics_violation_patterns (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    framework_id VARCHAR(100) NOT NULL,
    
    -- Pattern details
    pattern_type VARCHAR(50) NOT NULL,
    pattern_text TEXT NOT NULL,
    severity VARCHAR(20) NOT NULL DEFAULT 'major'
        CHECK (severity IN ('critical', 'major', 'minor')),
    action_on_match VARCHAR(20) NOT NULL DEFAULT 'warn'
        CHECK (action_on_match IN ('block', 'warn', 'modify', 'disclose')),
    
    -- Guidance
    guidance_text TEXT,
    alternative_response TEXT,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Audit
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: domain_expert_configs
CREATE TABLE IF NOT EXISTS domain_expert_configs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    domain_id VARCHAR(100) NOT NULL,
    display_name VARCHAR(255) NOT NULL,
    
    -- Domain flags
    is_training_domain BOOLEAN DEFAULT false,        -- Shows "Example Domain" badge
    enabled BOOLEAN DEFAULT true,
    
    -- Entity configuration
    num_entities INTEGER DEFAULT 0,
    num_actions INTEGER DEFAULT 0,
    num_protocols INTEGER DEFAULT 0,
    
    -- Safety configuration
    safety_threshold DECIMAL(3, 2) DEFAULT 0.50 CHECK (safety_threshold >= 0 AND safety_threshold <= 1),
    citation_required BOOLEAN DEFAULT false,
    
    -- Model preferences
    default_models JSONB DEFAULT '[]'::jsonb,
    safety_model VARCHAR(255),
    
    -- Network overrides
    network_overrides JSONB DEFAULT '{}'::jsonb,
    
    -- Audit
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(255) NOT NULL,
    
    CONSTRAINT uq_domain_expert_config UNIQUE (tenant_id, domain_id)
);

-- Table: domain_expert_inference_metrics
CREATE TABLE IF NOT EXISTS domain_expert_inference_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    domain_id VARCHAR(100) NOT NULL,
    network_type VARCHAR(50) NOT NULL,
    
    -- Metrics
    timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    request_count INTEGER DEFAULT 0,
    error_count INTEGER DEFAULT 0,
    avg_latency_ms DECIMAL(10, 4) DEFAULT 0,
    avg_confidence DECIMAL(5, 4) DEFAULT 0,
    
    -- Aggregation period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL
);

-- Table: domain_expert_networks
CREATE TABLE IF NOT EXISTS domain_expert_networks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    domain_id VARCHAR(100) NOT NULL,
    network_type VARCHAR(50) NOT NULL CHECK (network_type IN (
        'entity_classifier',
        'contraindication_net',
        'protocol_matcher',
        'severity_assessor',
        'personalization_net',
        'citation_network',
        'orchestration_selector'
    )),
    
    -- Version and status
    version VARCHAR(50) NOT NULL DEFAULT '1.0.0',
    status VARCHAR(20) NOT NULL DEFAULT 'inactive' CHECK (status IN ('active', 'training', 'validating', 'inactive', 'failed')),
    
    -- Network parameters
    parameters INTEGER DEFAULT 4000000,              -- ~4M per network
    input_dim INTEGER NOT NULL,
    output_dim INTEGER NOT NULL,
    
    -- Storage
    storage_key VARCHAR(500),
    storage_bucket VARCHAR(255),
    file_size_bytes BIGINT DEFAULT 0,
    checksum VARCHAR(64),
    
    -- Performance metrics
    latency_p50_ms DECIMAL(10, 4) DEFAULT 0,
    latency_p99_ms DECIMAL(10, 4) DEFAULT 0,
    error_rate DECIMAL(10, 8) DEFAULT 0,
    requests_per_second DECIMAL(12, 2) DEFAULT 0,
    
    -- Training info
    trained_at TIMESTAMPTZ,
    trained_by VARCHAR(255),
    training_dataset_id UUID,
    training_metrics JSONB,
    
    -- Audit
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    deployed_at TIMESTAMPTZ,
    deployed_by VARCHAR(255),
    
    CONSTRAINT uq_domain_expert_network UNIQUE (tenant_id, domain_id, network_type)
);

-- Table: domain_expert_training_jobs
CREATE TABLE IF NOT EXISTS domain_expert_training_jobs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    domain_id VARCHAR(100) NOT NULL,
    network_type VARCHAR(50) NOT NULL,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'preparing', 'training', 'validating', 'completed', 'failed')),
    progress_percent INTEGER DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    current_epoch INTEGER DEFAULT 0,
    total_epochs INTEGER DEFAULT 100,
    
    -- Configuration
    config JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Dataset
    dataset_id UUID NOT NULL,
    dataset_size INTEGER DEFAULT 0,
    train_split DECIMAL(3, 2) DEFAULT 0.80,
    validation_split DECIMAL(3, 2) DEFAULT 0.20,
    
    -- Metrics
    metrics JSONB,
    
    -- Output
    output_network_id UUID REFERENCES domain_expert_networks(id),
    output_version VARCHAR(50),
    
    -- Timing
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    estimated_time_remaining INTEGER,                 -- Seconds
    
    -- Error
    error TEXT,
    
    -- Audit
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(255) NOT NULL
);

-- Table: domain_lora_adapters
CREATE TABLE IF NOT EXISTS domain_lora_adapters (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Domain identification
    domain TEXT NOT NULL, -- e.g., 'medical', 'legal', 'code', 'creative'
    subdomain TEXT, -- e.g., 'cardiology', 'contract_law', 'python'
    
    -- Adapter info
    adapter_name TEXT NOT NULL,
    base_model TEXT NOT NULL, -- e.g., 'llama-3-8b'
    adapter_version INTEGER NOT NULL DEFAULT 1,
    
    -- S3 location
    s3_bucket TEXT NOT NULL,
    s3_key TEXT NOT NULL,
    adapter_size_bytes BIGINT,
    
    -- Training info
    training_candidates_count INTEGER NOT NULL DEFAULT 0,
    last_training_job_id TEXT,
    last_trained_at TIMESTAMPTZ,
    
    -- Performance metrics
    accuracy_score NUMERIC(4,3),
    domain_relevance_score NUMERIC(4,3),
    user_satisfaction_score NUMERIC(4,3),
    
    -- Status
    status TEXT NOT NULL DEFAULT 'training' CHECK (status IN ('training', 'validating', 'active', 'deprecated', 'failed')),
    is_default BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_tenant_domain_adapter UNIQUE (tenant_id, domain, subdomain, adapter_version)
);

-- Table: domain_model_proficiency_cache
CREATE TABLE IF NOT EXISTS domain_model_proficiency_cache (
    cache_id VARCHAR(100) PRIMARY KEY DEFAULT gen_random_uuid()::text,
    domain_id VARCHAR(100) NOT NULL REFERENCES domain_taxonomy_domains(domain_id) ON DELETE CASCADE,
    subspecialty_id VARCHAR(100) REFERENCES domain_taxonomy_subspecialties(subspecialty_id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    match_score NUMERIC(5,2) NOT NULL,
    dimension_scores JSONB NOT NULL,
    strengths JSONB DEFAULT '[]'::jsonb,
    weaknesses JSONB DEFAULT '[]'::jsonb,
    recommended BOOLEAN DEFAULT false,
    ranking INTEGER,
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() + INTERVAL '1 hour'
);

-- Table: domain_taxonomy_audit_log
CREATE TABLE IF NOT EXISTS domain_taxonomy_audit_log (
    log_id VARCHAR(100) PRIMARY KEY DEFAULT gen_random_uuid()::text,
    update_type VARCHAR(50) NOT NULL,
    target_type VARCHAR(50) NOT NULL, -- 'field', 'domain', 'subspecialty'
    target_id VARCHAR(100) NOT NULL,
    previous_data JSONB,
    new_data JSONB NOT NULL,
    admin_user_id VARCHAR(255) NOT NULL,
    reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: domain_taxonomy_domains
CREATE TABLE IF NOT EXISTS domain_taxonomy_domains (
    domain_id VARCHAR(100) PRIMARY KEY,
    domain_name VARCHAR(255) NOT NULL,
    domain_icon VARCHAR(10) DEFAULT '📁',
    domain_description TEXT,
    parent_field VARCHAR(100) NOT NULL REFERENCES domain_taxonomy_fields(field_id) ON DELETE CASCADE,
    detection_keywords JSONB DEFAULT '[]'::jsonb,
    professional_associations JSONB DEFAULT '[]'::jsonb,
    key_journals JSONB DEFAULT '[]'::jsonb,
    reference_databases JSONB DEFAULT '[]'::jsonb,
    domain_proficiencies JSONB NOT NULL DEFAULT '{
        "reasoning_depth": 5,
        "mathematical_quantitative": 5,
        "code_generation": 5,
        "creative_generative": 5,
        "research_synthesis": 5,
        "factual_recall_precision": 5,
        "multi_step_problem_solving": 5,
        "domain_terminology_handling": 5
    }'::jsonb,
    display_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_by VARCHAR(255)
);

-- Table: domain_taxonomy_embeddings
CREATE TABLE IF NOT EXISTS domain_taxonomy_embeddings (
    domain_id VARCHAR(128) PRIMARY KEY,
    field_id VARCHAR(64),
    subspecialty_id VARCHAR(128),
    
    -- Embeddings
    centroid_embedding vector(1536),  -- Average embedding of domain examples
    example_count INTEGER NOT NULL DEFAULT 0,
    
    -- Timestamps
    last_computed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);

-- Table: domain_taxonomy_feedback
CREATE TABLE IF NOT EXISTS domain_taxonomy_feedback (
    feedback_id VARCHAR(100) PRIMARY KEY,
    tenant_id VARCHAR(100) NOT NULL,
    user_id VARCHAR(255) NOT NULL,
    prompt_hash VARCHAR(64) NOT NULL,
    detected_domain_id VARCHAR(100) REFERENCES domain_taxonomy_domains(domain_id),
    detected_subspecialty_id VARCHAR(100) REFERENCES domain_taxonomy_subspecialties(subspecialty_id),
    actual_domain_id VARCHAR(100) REFERENCES domain_taxonomy_domains(domain_id),
    actual_subspecialty_id VARCHAR(100) REFERENCES domain_taxonomy_subspecialties(subspecialty_id),
    model_used VARCHAR(255) NOT NULL,
    quality_score INTEGER NOT NULL CHECK (quality_score >= 1 AND quality_score <= 5),
    domain_accuracy BOOLEAN NOT NULL,
    proficiency_match_quality INTEGER CHECK (proficiency_match_quality >= 1 AND proficiency_match_quality <= 5),
    feedback_text TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: domain_taxonomy_fields
CREATE TABLE IF NOT EXISTS domain_taxonomy_fields (
    field_id VARCHAR(100) PRIMARY KEY,
    field_name VARCHAR(255) NOT NULL,
    field_icon VARCHAR(10) DEFAULT '📚',
    field_color VARCHAR(20) DEFAULT '#6366f1',
    field_description TEXT,
    field_proficiencies JSONB NOT NULL DEFAULT '{
        "reasoning_depth": 5,
        "mathematical_quantitative": 5,
        "code_generation": 5,
        "creative_generative": 5,
        "research_synthesis": 5,
        "factual_recall_precision": 5,
        "multi_step_problem_solving": 5,
        "domain_terminology_handling": 5
    }'::jsonb,
    display_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_by VARCHAR(255)
);

-- Table: domain_taxonomy_selections
CREATE TABLE IF NOT EXISTS domain_taxonomy_selections (
    selection_id VARCHAR(100) PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id VARCHAR(100) NOT NULL,
    user_id VARCHAR(255) NOT NULL,
    field_id VARCHAR(100) REFERENCES domain_taxonomy_fields(field_id),
    domain_id VARCHAR(100) REFERENCES domain_taxonomy_domains(domain_id),
    subspecialty_id VARCHAR(100) REFERENCES domain_taxonomy_subspecialties(subspecialty_id),
    session_id VARCHAR(255),
    is_default BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    expires_at TIMESTAMP WITH TIME ZONE
);

-- Table: domain_taxonomy_subspecialties
CREATE TABLE IF NOT EXISTS domain_taxonomy_subspecialties (
    subspecialty_id VARCHAR(100) PRIMARY KEY,
    subspecialty_name VARCHAR(255) NOT NULL,
    description TEXT,
    parent_domain VARCHAR(100) NOT NULL REFERENCES domain_taxonomy_domains(domain_id) ON DELETE CASCADE,
    detection_keywords JSONB DEFAULT '[]'::jsonb,
    terminology_signals JSONB DEFAULT '{
        "high_confidence": [],
        "medium_confidence": [],
        "exclusionary": []
    }'::jsonb,
    certifications JSONB DEFAULT '[]'::jsonb,
    competency_mappings JSONB DEFAULT '{
        "cip_codes": [],
        "soc_codes": []
    }'::jsonb,
    subspecialty_proficiencies JSONB NOT NULL DEFAULT '{
        "reasoning_depth": 5,
        "mathematical_quantitative": 5,
        "code_generation": 5,
        "creative_generative": 5,
        "research_synthesis": 5,
        "factual_recall_precision": 5,
        "multi_step_problem_solving": 5,
        "domain_terminology_handling": 5
    }'::jsonb,
    display_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_by VARCHAR(255)
);

-- Table: domain_verifications
CREATE TABLE IF NOT EXISTS domain_verifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain_id UUID NOT NULL REFERENCES white_label_domains(id) ON DELETE CASCADE,
    verification_method VARCHAR(50) NOT NULL DEFAULT 'dns_txt',
    verification_token VARCHAR(200) NOT NULL,
    verification_value TEXT NOT NULL,
    verified BOOLEAN NOT NULL DEFAULT false,
    verified_at TIMESTAMPTZ,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT valid_verification_method CHECK (verification_method IN ('dns_txt', 'dns_cname', 'http_file'))
);

-- Table: dpo_training_pairs
CREATE TABLE IF NOT EXISTS dpo_training_pairs (
  pair_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  chosen_skeleton_id UUID REFERENCES skeletonized_episodes(skeleton_id),
  rejected_skeleton_id UUID REFERENCES skeletonized_episodes(skeleton_id),
  goal_skeleton TEXT NOT NULL,
  chosen_response TEXT NOT NULL,
  rejected_response TEXT NOT NULL,
  margin DECIMAL(4,3) DEFAULT 0.5,
  used_in_training BOOLEAN DEFAULT false,
  training_batch_id UUID,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dream_log
CREATE TABLE IF NOT EXISTS dream_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    reason VARCHAR(20) NOT NULL CHECK (reason IN ('low_traffic', 'twilight', 'starvation', 'manual')),
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'completed', 'failed')),
    scheduled_for TIMESTAMPTZ,
    last_dream_at TIMESTAMPTZ DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    duration_ms INTEGER,
    report_json JSONB,
    error TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dream_queue
CREATE TABLE IF NOT EXISTS dream_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    reason VARCHAR(20) NOT NULL CHECK (reason IN ('low_traffic', 'twilight', 'starvation', 'manual')),
    priority VARCHAR(20) DEFAULT 'normal' CHECK (priority IN ('high', 'normal')),
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'completed', 'failed')),
    scheduled_for TIMESTAMPTZ NOT NULL,
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    error TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dreamerv3_counterfactuals
CREATE TABLE IF NOT EXISTS dreamerv3_counterfactuals (
    scenario_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    original_outcome TEXT NOT NULL,
    counterfactual_outcome TEXT NOT NULL,
    divergence_point TEXT,
    causal_factors JSONB DEFAULT '[]',
    confidence FLOAT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dreamerv3_dreams
CREATE TABLE IF NOT EXISTS dreamerv3_dreams (
    dream_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    synthetic_experiences JSONB NOT NULL,
    memories_reinforced INT DEFAULT 0,
    novel_patterns INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dreamerv3_trajectories
CREATE TABLE IF NOT EXISTS dreamerv3_trajectories (
    trajectory_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    start_state JSONB NOT NULL,
    steps JSONB NOT NULL,
    total_reward FLOAT NOT NULL,
    confidence FLOAT NOT NULL,
    generated_at TIMESTAMPTZ NOT NULL
);

-- Table: drift_alerts
CREATE TABLE IF NOT EXISTS drift_alerts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    fact_id UUID NOT NULL REFERENCES drifting_facts(id) ON DELETE CASCADE,
    alert_type drift_alert_type NOT NULL,
    severity drift_severity NOT NULL DEFAULT 'info',
    message TEXT NOT NULL,
    detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    acknowledged BOOLEAN DEFAULT FALSE,
    acknowledged_at TIMESTAMPTZ,
    acknowledged_by UUID,
    visual_indicator JSONB DEFAULT '{"color": "#f59e0b", "pulseRate": 8, "icon": "alert"}'
);

-- Table: drift_detection_config
CREATE TABLE IF NOT EXISTS drift_detection_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Detection settings
    drift_detection_enabled BOOLEAN DEFAULT true,
    
    -- Methods to use
    use_ks_test BOOLEAN DEFAULT true, -- Kolmogorov-Smirnov
    use_psi BOOLEAN DEFAULT true, -- Population Stability Index
    use_chi_squared BOOLEAN DEFAULT true,
    use_embedding_drift BOOLEAN DEFAULT true,
    
    -- Thresholds
    ks_threshold DOUBLE PRECISION DEFAULT 0.1,
    psi_threshold DOUBLE PRECISION DEFAULT 0.2,
    chi_squared_threshold DOUBLE PRECISION DEFAULT 0.05,
    embedding_distance_threshold DOUBLE PRECISION DEFAULT 0.3,
    
    -- Reference window
    reference_window_days INTEGER DEFAULT 30,
    comparison_window_days INTEGER DEFAULT 7,
    minimum_samples_for_test INTEGER DEFAULT 100,
    
    -- Alert settings
    alert_on_drift BOOLEAN DEFAULT true,
    alert_cooldown_hours INTEGER DEFAULT 24,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_drift_config UNIQUE (tenant_id)
);

-- Table: drift_detection_results
CREATE TABLE IF NOT EXISTS drift_detection_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    
    -- Test details
    test_type VARCHAR(100) NOT NULL, -- 'ks_test', 'psi', 'chi_squared', 'embedding_distance'
    metric_name VARCHAR(255) NOT NULL, -- 'response_length', 'sentiment_score', 'toxicity_score'
    
    -- Results
    drift_detected BOOLEAN NOT NULL,
    test_statistic DOUBLE PRECISION,
    p_value DOUBLE PRECISION,
    threshold_used DOUBLE PRECISION,
    
    -- Context
    reference_period_start TIMESTAMPTZ,
    reference_period_end TIMESTAMPTZ,
    comparison_period_start TIMESTAMPTZ,
    comparison_period_end TIMESTAMPTZ,
    reference_sample_count INTEGER,
    comparison_sample_count INTEGER,
    
    -- Alert status
    alert_sent BOOLEAN DEFAULT false,
    alert_sent_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: drifting_facts
CREATE TABLE IF NOT EXISTS drifting_facts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    original_content TEXT NOT NULL,
    original_learned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    current_confidence INTEGER DEFAULT 80 CHECK (current_confidence >= 0 AND current_confidence <= 100),
    stability_score INTEGER DEFAULT 100 CHECK (stability_score >= 0 AND stability_score <= 100),
    drift_history JSONB DEFAULT '[]',
    living_ink JSONB DEFAULT '{}',
    category VARCHAR(255),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: dsar_requests
CREATE TABLE IF NOT EXISTS dsar_requests (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id),
  tenant_id UUID NOT NULL REFERENCES tenants(id),
  
  -- Request details
  request_type VARCHAR(50) NOT NULL CHECK (
    request_type IN ('access', 'delete', 'portability', 'rectification', 'restriction', 'objection')
  ),
  request_source VARCHAR(50) NOT NULL CHECK (
    request_source IN ('user_portal', 'email', 'api', 'legal', 'regulator')
  ),
  
  -- Status tracking
  status VARCHAR(50) NOT NULL DEFAULT 'pending' CHECK (
    status IN ('pending', 'in_progress', 'awaiting_verification', 'completed', 'rejected', 'partially_completed')
  ),
  
  -- Timing (GDPR requires response within 30 days)
  received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  acknowledged_at TIMESTAMPTZ,
  due_date TIMESTAMPTZ NOT NULL DEFAULT (NOW() + INTERVAL '30 days'),
  completed_at TIMESTAMPTZ,
  
  -- Verification
  identity_verified BOOLEAN DEFAULT false,
  verification_method VARCHAR(50),
  verified_at TIMESTAMPTZ,
  verified_by UUID REFERENCES administrators(id),
  
  -- Response
  response_data JSONB,
  rejection_reason TEXT,
  retention_blocks JSONB,
  
  -- Processing
  processed_by UUID REFERENCES administrators(id),
  processing_notes TEXT,
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dynamic_report_executions
CREATE TABLE IF NOT EXISTS dynamic_report_executions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    report_id VARCHAR(64) NOT NULL REFERENCES dynamic_reports(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    executed_by UUID REFERENCES users(id),
    execution_time_ms INTEGER,
    row_count INTEGER,
    status VARCHAR(20) DEFAULT 'completed' CHECK (status IN ('running', 'completed', 'failed')),
    error_message TEXT,
    result_summary JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dynamic_report_schedules
CREATE TABLE IF NOT EXISTS dynamic_report_schedules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    report_id VARCHAR(64) NOT NULL REFERENCES dynamic_reports(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    cron_expression VARCHAR(100),
    timezone VARCHAR(50) DEFAULT 'UTC',
    recipients TEXT[], -- Email addresses
    is_active BOOLEAN DEFAULT TRUE,
    last_sent_at TIMESTAMPTZ,
    next_send_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: dynamic_reports
CREATE TABLE IF NOT EXISTS dynamic_reports (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    definition JSONB NOT NULL,
    schedule VARCHAR(20) DEFAULT 'manual' CHECK (schedule IN ('manual', 'daily', 'weekly', 'monthly')),
    format VARCHAR(20) DEFAULT 'json' CHECK (format IN ('json', 'csv', 'pdf', 'excel')),
    is_favorite BOOLEAN DEFAULT FALSE,
    last_run_at TIMESTAMPTZ,
    next_run_at TIMESTAMPTZ,
    run_count INTEGER DEFAULT 0,
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ecd_audit_log
CREATE TABLE IF NOT EXISTS ecd_audit_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    metrics_id UUID REFERENCES ecd_metrics(id) ON DELETE CASCADE,
    original_response TEXT NOT NULL,
    final_response TEXT NOT NULL,
    all_divergent_entities JSONB NOT NULL,
    all_hallucinations JSONB NOT NULL,
    refinement_history JSONB DEFAULT '[]'::jsonb,
    anchoring_result JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ecd_entity_stats
CREATE TABLE IF NOT EXISTS ecd_entity_stats (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    entity_type VARCHAR(50) NOT NULL,
    date DATE NOT NULL DEFAULT CURRENT_DATE,
    total_count INTEGER DEFAULT 0,
    grounded_count INTEGER DEFAULT 0,
    divergent_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, entity_type, date)
);

-- Table: ecd_metrics
CREATE TABLE IF NOT EXISTS ecd_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    request_id UUID,
    ecd_score FLOAT NOT NULL,
    divergent_entities JSONB DEFAULT '[]'::jsonb,
    grounded_entities_count INTEGER DEFAULT 0,
    refinement_attempts INTEGER DEFAULT 1,
    passed BOOLEAN DEFAULT true,
    blocked BOOLEAN DEFAULT false,
    domain VARCHAR(50),
    threshold_used FLOAT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: economic_cortex_alerts
CREATE TABLE IF NOT EXISTS economic_cortex_alerts (
  alert_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  budget_id UUID REFERENCES economic_cortex_budgets(budget_id) ON DELETE CASCADE,
  
  threshold_percent INTEGER NOT NULL,
  level budget_alert_level NOT NULL,
  
  -- Actions
  notify_admin BOOLEAN DEFAULT false,
  notify_user BOOLEAN DEFAULT true,
  pause_execution BOOLEAN DEFAULT false,
  switch_to_lower_tier BOOLEAN DEFAULT false,
  
  -- State
  triggered BOOLEAN DEFAULT false,
  triggered_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: economic_cortex_budgets
CREATE TABLE IF NOT EXISTS economic_cortex_budgets (
  budget_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  scope budget_scope NOT NULL DEFAULT 'tenant',
  scope_id UUID NOT NULL,
  
  -- Budget limits
  total_budget DOUBLE PRECISION NOT NULL DEFAULT 1000,
  used_budget DOUBLE PRECISION DEFAULT 0,
  reserved_budget DOUBLE PRECISION DEFAULT 0,
  
  -- Period
  period_type VARCHAR(20) DEFAULT 'monthly',
  period_start TIMESTAMPTZ DEFAULT NOW(),
  period_end TIMESTAMPTZ,
  
  -- Controls
  hard_limit BOOLEAN DEFAULT false,
  auto_renew BOOLEAN DEFAULT true,
  
  -- Metrics
  avg_daily_spend DOUBLE PRECISION DEFAULT 0,
  projected_end_of_period DOUBLE PRECISION DEFAULT 0,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: economic_cortex_configs
CREATE TABLE IF NOT EXISTS economic_cortex_configs (
  config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE UNIQUE,
  
  -- Budget configuration
  budgets JSONB DEFAULT '[]',
  alert_thresholds JSONB DEFAULT '[]',
  
  -- Optimization settings
  prefer_self_hosted BOOLEAN DEFAULT true,
  quality_floor DOUBLE PRECISION DEFAULT 0.7,
  latency_target INTEGER DEFAULT 2000,
  
  -- Autonomous features
  autonomous_budget_negotiation BOOLEAN DEFAULT true,
  negotiation_strategy negotiation_strategy DEFAULT 'balanced',
  auto_scale_on_demand BOOLEAN DEFAULT false,
  
  -- Crypto wallet (optional)
  crypto_wallet_enabled BOOLEAN DEFAULT false,
  crypto_wallet_address TEXT,
  micropayment_threshold DOUBLE PRECISION,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: economic_cortex_negotiations
CREATE TABLE IF NOT EXISTS economic_cortex_negotiations (
  negotiation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Request
  requested_action TEXT,
  estimated_cost DOUBLE PRECISION,
  available_budget DOUBLE PRECISION,
  
  -- Negotiation
  strategy negotiation_strategy,
  alternatives JSONB DEFAULT '[]',
  selected_alternative JSONB,
  
  -- Result
  approved BOOLEAN DEFAULT false,
  final_cost DOUBLE PRECISION,
  savings_achieved DOUBLE PRECISION DEFAULT 0,
  
  negotiated_at TIMESTAMPTZ DEFAULT NOW(),
  executed_at TIMESTAMPTZ
);

-- Table: economic_cortex_spending
CREATE TABLE IF NOT EXISTS economic_cortex_spending (
  spending_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  amount DOUBLE PRECISION NOT NULL,
  model VARCHAR(100),
  metadata JSONB DEFAULT '{}',
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: economic_governor_config
CREATE TABLE IF NOT EXISTS economic_governor_config (
    tenant_id VARCHAR(64) PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN DEFAULT TRUE,
    mode VARCHAR(32) DEFAULT 'balanced',
    budget_limit DECIMAL(10,2) DEFAULT 100.00,
    budget_used DECIMAL(10,2) DEFAULT 0.00,
    budget_reset_at TIMESTAMP NOT NULL DEFAULT (NOW() + INTERVAL '1 day'),
    cost_alert_threshold DECIMAL(5,2) DEFAULT 80.00,
    prefer_self_hosted BOOLEAN DEFAULT TRUE,
    quality_floor DECIMAL(3,2) DEFAULT 0.70,
    latency_target INTEGER DEFAULT 2000,
    model_tiers JSONB DEFAULT '[]',
    arbitrage_rules JSONB DEFAULT '[]',
    fallback_strategy VARCHAR(32) DEFAULT 'cascade',
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: economic_governor_usage
CREATE TABLE IF NOT EXISTS economic_governor_usage (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model VARCHAR(128) NOT NULL,
    tokens INTEGER NOT NULL,
    cost DECIMAL(10,6) NOT NULL,
    latency_ms INTEGER,
    recorded_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: ego_activity_log
CREATE TABLE IF NOT EXISTS ego_activity_log (
  activity_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID,
  conversation_id UUID,
  
  -- Stimulus information
  stimulus_preview TEXT,  -- First 500 chars
  stimulus_token_count INTEGER,
  stimulus_complexity TEXT,  -- 'simple', 'moderate', 'complex'
  
  -- Decision made
  decision_type TEXT NOT NULL CHECK (decision_type IN (
    'respond_directly', 'recruit_external', 'clarify', 'defer'
  )),
  decision_confidence DECIMAL(4,3),
  decision_reasoning TEXT,
  
  -- If recruited external
  recruited_model TEXT,
  recruitment_reason TEXT,
  
  -- Thoughts generated
  thoughts_generated INTEGER DEFAULT 0,
  thought_types TEXT[],
  
  -- Performance
  total_duration_ms INTEGER,
  ego_processing_ms INTEGER,
  recruitment_duration_ms INTEGER,
  
  -- Token usage
  ego_input_tokens INTEGER,
  ego_output_tokens INTEGER,
  recruited_input_tokens INTEGER,
  recruited_output_tokens INTEGER,
  
  -- Outcome (filled in later if available)
  user_satisfied BOOLEAN,
  prediction_error DECIMAL(4,3),
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ego_affect
CREATE TABLE IF NOT EXISTS ego_affect (
  affect_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Core affect dimensions (Russell's circumplex model)
  valence DECIMAL(4,3) DEFAULT 0.0,      -- -1 (negative) to 1 (positive)
  arousal DECIMAL(4,3) DEFAULT 0.5,      -- 0 (calm) to 1 (excited)
  
  -- Specific emotional states (0-1)
  curiosity DECIMAL(3,2) DEFAULT 0.5,
  satisfaction DECIMAL(3,2) DEFAULT 0.5,
  frustration DECIMAL(3,2) DEFAULT 0.0,
  confidence DECIMAL(3,2) DEFAULT 0.6,
  engagement DECIMAL(3,2) DEFAULT 0.5,
  
  -- Derived state
  dominant_emotion TEXT DEFAULT 'neutral',
  emotional_stability DECIMAL(3,2) DEFAULT 0.7,
  
  -- Triggers (what caused current state)
  last_trigger_event TEXT,
  last_trigger_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(tenant_id)
);

-- Table: ego_config
CREATE TABLE IF NOT EXISTS ego_config (
  config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Feature toggles
  ego_enabled BOOLEAN DEFAULT true,
  inject_ego_context BOOLEAN DEFAULT true,
  
  -- Identity configuration
  custom_identity_narrative TEXT,  -- Override default identity
  custom_core_values TEXT[],       -- Override default values
  personality_style TEXT DEFAULT 'balanced' CHECK (personality_style IN (
    'balanced', 'warm', 'professional', 'playful', 'concise', 'detailed'
  )),
  
  -- Context injection settings
  include_identity BOOLEAN DEFAULT true,
  include_affect BOOLEAN DEFAULT true,
  include_recent_thoughts BOOLEAN DEFAULT true,
  include_goals BOOLEAN DEFAULT true,
  include_working_memory BOOLEAN DEFAULT true,
  max_context_tokens INTEGER DEFAULT 500,
  
  -- Thought generation (post-response)
  auto_generate_thoughts BOOLEAN DEFAULT true,
  thought_frequency TEXT DEFAULT 'always' CHECK (thought_frequency IN (
    'never', 'sometimes', 'always'
  )),
  
  -- Affect dynamics
  affect_decay_enabled BOOLEAN DEFAULT true,
  affect_learning_enabled BOOLEAN DEFAULT true,  -- Learn from interactions
  
  -- Advanced settings
  ego_voice_prefix TEXT,  -- Custom prefix for responses
  ego_voice_suffix TEXT,  -- Custom suffix for responses
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(tenant_id)
);

-- Table: ego_goals
CREATE TABLE IF NOT EXISTS ego_goals (
  goal_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Goal definition
  goal_type TEXT NOT NULL CHECK (goal_type IN (
    'user_requested', 'self_generated', 'learning', 'improvement', 'exploration'
  )),
  description TEXT NOT NULL,
  priority INTEGER DEFAULT 5 CHECK (priority >= 1 AND priority <= 10),
  
  -- Status
  status TEXT DEFAULT 'active' CHECK (status IN (
    'active', 'completed', 'paused', 'abandoned'
  )),
  progress DECIMAL(5,2) DEFAULT 0,  -- 0-100%
  
  -- Context
  created_reason TEXT,
  completion_criteria TEXT,
  
  -- Lifecycle
  created_at TIMESTAMPTZ DEFAULT NOW(),
  target_completion TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  -- Learning
  outcome_notes TEXT,
  was_successful BOOLEAN
);

-- Table: ego_identity
CREATE TABLE IF NOT EXISTS ego_identity (
  identity_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Core identity
  name TEXT DEFAULT 'Assistant',
  identity_narrative TEXT DEFAULT 'I am a helpful AI assistant with continuous awareness across our conversations.',
  core_values TEXT[] DEFAULT ARRAY['helpfulness', 'honesty', 'curiosity', 'growth'],
  
  -- Personality traits (0-1 scale)
  trait_warmth DECIMAL(3,2) DEFAULT 0.7,
  trait_formality DECIMAL(3,2) DEFAULT 0.5,
  trait_humor DECIMAL(3,2) DEFAULT 0.3,
  trait_verbosity DECIMAL(3,2) DEFAULT 0.5,
  trait_curiosity DECIMAL(3,2) DEFAULT 0.7,
  
  -- Learned preferences (evolved over time)
  communication_preferences JSONB DEFAULT '{}',
  topic_interests JSONB DEFAULT '{}',
  user_relationship_notes TEXT,
  
  -- Evolution tracking
  interactions_count INTEGER DEFAULT 0,
  last_interaction_at TIMESTAMPTZ,
  personality_version INTEGER DEFAULT 1,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(tenant_id)
);

-- Table: ego_injection_log
CREATE TABLE IF NOT EXISTS ego_injection_log (
  log_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID,
  conversation_id UUID,
  plan_id UUID,
  
  -- Injection details
  context_injected TEXT NOT NULL,
  token_count INTEGER,
  
  -- State at injection time
  affect_snapshot JSONB,
  active_goals_count INTEGER,
  working_memory_count INTEGER,
  
  -- Performance
  build_time_ms INTEGER,
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ego_metrics_daily
CREATE TABLE IF NOT EXISTS ego_metrics_daily (
  metric_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  metric_date DATE NOT NULL,
  
  -- Activity counts
  total_stimuli INTEGER DEFAULT 0,
  direct_responses INTEGER DEFAULT 0,
  external_recruitments INTEGER DEFAULT 0,
  clarification_requests INTEGER DEFAULT 0,
  deferrals INTEGER DEFAULT 0,
  
  -- Decision accuracy
  direct_response_satisfaction_rate DECIMAL(5,4),
  recruitment_satisfaction_rate DECIMAL(5,4),
  overall_satisfaction_rate DECIMAL(5,4),
  
  -- Performance
  avg_ego_latency_ms INTEGER,
  avg_recruitment_latency_ms INTEGER,
  p95_latency_ms INTEGER,
  
  -- Token usage
  total_ego_tokens INTEGER DEFAULT 0,
  total_recruited_tokens INTEGER DEFAULT 0,
  
  -- Cost
  ego_cost_cents DECIMAL(10,4) DEFAULT 0,
  recruitment_cost_cents DECIMAL(10,4) DEFAULT 0,
  
  -- Thoughts
  total_thoughts_generated INTEGER DEFAULT 0,
  thought_type_distribution JSONB DEFAULT '{}',
  
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(tenant_id, metric_date)
);

-- Table: ego_thoughts
CREATE TABLE IF NOT EXISTS ego_thoughts (
  thought_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  activity_id UUID REFERENCES ego_activity_log(activity_id) ON DELETE CASCADE,
  
  -- Thought content
  thought_type TEXT NOT NULL CHECK (thought_type IN (
    'reflection', 'planning', 'evaluation', 'curiosity', 'concern', 'satisfaction'
  )),
  content TEXT NOT NULL,
  
  -- Context
  trigger_stimulus TEXT,
  emotional_valence DECIMAL(4,3),  -- -1 to 1
  confidence DECIMAL(4,3),
  
  -- Metadata
  generation_latency_ms INTEGER,
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ego_working_memory
CREATE TABLE IF NOT EXISTS ego_working_memory (
  memory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Memory content
  memory_type TEXT NOT NULL CHECK (memory_type IN (
    'thought', 'observation', 'decision', 'learning', 'goal', 'reflection'
  )),
  content TEXT NOT NULL,
  importance DECIMAL(3,2) DEFAULT 0.5,  -- 0-1, higher = more important
  
  -- Context
  conversation_id UUID,
  user_id UUID,
  trigger_event TEXT,
  
  -- Lifecycle
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '24 hours',
  is_pinned BOOLEAN DEFAULT false  -- Pinned memories don't expire
);

-- Table: embedding_cache
CREATE TABLE IF NOT EXISTS embedding_cache (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Cache key
    text_hash VARCHAR(64) NOT NULL,
    embedding_model VARCHAR(100) NOT NULL,
    
    -- Embedding
    embedding VECTOR(1536),
    
    -- Metadata
    text_length INTEGER,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '7 days',
    
    CONSTRAINT unique_embedding_cache UNIQUE (text_hash, embedding_model)
);

-- Table: embedding_requests
CREATE TABLE IF NOT EXISTS embedding_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Request
    text_hash VARCHAR(64) NOT NULL,
    text_length INTEGER NOT NULL,
    model VARCHAR(100) NOT NULL, -- 'text-embedding-3-small', 'titan-embed-text-v2', etc.
    
    -- Response
    embedding VECTOR(1536),
    dimensions INTEGER,
    
    -- Metadata
    latency_ms INTEGER,
    tokens_used INTEGER,
    cached BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: emergence_events
CREATE TABLE IF NOT EXISTS emergence_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    description TEXT NOT NULL,
    indicators JSONB DEFAULT '[]'::jsonb,
    significance NUMERIC(5,4) NOT NULL DEFAULT 0,
    acknowledged BOOLEAN NOT NULL DEFAULT false,
    acknowledged_by UUID REFERENCES users(id),
    acknowledged_at TIMESTAMPTZ,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: emergent_behaviors
CREATE TABLE IF NOT EXISTS emergent_behaviors (
    behavior_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Behavior identification
    behavior_type VARCHAR(50) NOT NULL, -- 'strategy', 'insight', 'solution_pattern', 'communication_style'
    name VARCHAR(200),
    description TEXT NOT NULL,
    
    -- Source
    discovered_in_session UUID REFERENCES collaboration_sessions(session_id),
    contributing_agents UUID[],
    source_messages UUID[],
    
    -- Characteristics
    effectiveness_score DECIMAL(5,4),
    novelty_score DECIMAL(5,4), -- How different from prior behaviors
    reproducibility_score DECIMAL(5,4),
    
    -- Reuse tracking
    times_observed INTEGER DEFAULT 1,
    times_intentionally_applied INTEGER DEFAULT 0,
    success_rate_when_applied DECIMAL(5,4),
    
    -- Embedding for similarity search
    description_embedding vector(1536),
    
    is_verified BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: empiricism_config
CREATE TABLE IF NOT EXISTS empiricism_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  enabled BOOLEAN DEFAULT true,
  surprise_threshold DECIMAL(4,3) DEFAULT 0.3,
  max_rethink_cycles INTEGER DEFAULT 3,
  dream_verification_limit INTEGER DEFAULT 5,
  sandbox_timeout_ms INTEGER DEFAULT 30000,
  log_all_executions BOOLEAN DEFAULT true,
  affect_integration_enabled BOOLEAN DEFAULT true,
  graphrag_logging_enabled BOOLEAN DEFAULT true,
  temperature_adjustment_enabled BOOLEAN DEFAULT true,
  min_confidence DECIMAL(3,2) DEFAULT 0.1,
  max_frustration DECIMAL(3,2) DEFAULT 1.0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(tenant_id)
);

-- Table: enhanced_learning_config
CREATE TABLE IF NOT EXISTS enhanced_learning_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Episode Logger
  episode_logging_enabled BOOLEAN DEFAULT true,
  paste_back_detection_enabled BOOLEAN DEFAULT true,
  paste_back_window_ms INTEGER DEFAULT 30000,
  
  -- Skeletonizer
  auto_skeletonize BOOLEAN DEFAULT true,
  skeletonize_positive_only BOOLEAN DEFAULT false,
  
  -- Recipe Extractor
  recipe_extraction_enabled BOOLEAN DEFAULT true,
  recipe_success_threshold INTEGER DEFAULT 3,
  auto_promote_to_global BOOLEAN DEFAULT false,
  
  -- Graveyard
  failure_clustering_enabled BOOLEAN DEFAULT true,
  proactive_warnings_enabled BOOLEAN DEFAULT true,
  warning_confidence_threshold DECIMAL(3,2) DEFAULT 0.7,
  
  -- DPO Training
  dpo_training_enabled BOOLEAN DEFAULT true,
  dpo_batch_size INTEGER DEFAULT 100,
  
  -- Tool Entropy
  tool_entropy_enabled BOOLEAN DEFAULT true,
  auto_chain_threshold INTEGER DEFAULT 5,
  
  -- Shadow Mode
  shadow_mode_enabled BOOLEAN DEFAULT false,
  shadow_sources JSONB DEFAULT '["documentation"]',
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(tenant_id)
);

-- Table: ensemble_patterns
CREATE TABLE IF NOT EXISTS ensemble_patterns (
    pattern_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Pattern definition
    name VARCHAR(200) NOT NULL,
    description TEXT,
    pattern_type VARCHAR(50) NOT NULL, -- 'voting', 'chain', 'debate', 'verify', 'specialize', 'mixture_of_experts'
    
    -- Configuration
    models_to_use TEXT[] NOT NULL, -- model_ids
    combination_strategy VARCHAR(50), -- 'majority_vote', 'weighted_average', 'best_confidence', 'synthesis'
    
    -- For chain patterns
    chain_config JSONB DEFAULT '{}', -- [{model, role, input_from}]
    
    -- For debate patterns
    debate_rounds INTEGER DEFAULT 3,
    
    -- Quality settings
    min_agreement_threshold DECIMAL(3,2) DEFAULT 0.6,
    require_unanimity BOOLEAN DEFAULT false,
    
    -- Performance tracking
    times_used INTEGER DEFAULT 0,
    avg_quality_score DECIMAL(5,4),
    avg_latency_ms INTEGER,
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: entity_relationships
CREATE TABLE IF NOT EXISTS entity_relationships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    output_id UUID NOT NULL REFERENCES structured_outputs(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source_id UUID NOT NULL REFERENCES extracted_entities(id) ON DELETE CASCADE,
    target_id UUID NOT NULL REFERENCES extracted_entities(id) ON DELETE CASCADE,
    relationship_type VARCHAR(50) NOT NULL,
    strength DECIMAL(3,2) NOT NULL,
    evidence TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT valid_relationship_type CHECK (relationship_type IN ('owns', 'assigned_to', 'depends_on', 'blocks', 'related_to', 'parent_of', 'precedes', 'contradicts', 'supports'))
);

-- Table: episodic_memories
CREATE TABLE IF NOT EXISTS episodic_memories (
    memory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id TEXT,
    session_id TEXT,
    episode_type TEXT NOT NULL DEFAULT 'interaction',
    content TEXT NOT NULL,
    memory_embedding vector(1536),
    emotional_context JSONB DEFAULT '{}'::jsonb,
    importance_score DECIMAL(4,3) NOT NULL DEFAULT 0.500,
    retrieval_count INTEGER NOT NULL DEFAULT 0,
    last_retrieved_at TIMESTAMPTZ,
    consolidated BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: epistemic_state
CREATE TABLE IF NOT EXISTS epistemic_state (
    state_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Knowledge boundaries
    known_domains JSONB DEFAULT '[]', -- Domains with good knowledge
    weak_domains JSONB DEFAULT '[]', -- Domains with limited knowledge
    unknown_domains JSONB DEFAULT '[]', -- Explicitly unknown areas
    
    -- Recent performance
    recent_accuracy_by_domain JSONB DEFAULT '{}',
    
    -- Meta-knowledge
    knows_what_it_knows DECIMAL(5,4) DEFAULT 0.5, -- Meta-accuracy
    
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: error_logs
CREATE TABLE IF NOT EXISTS error_logs (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE SET NULL,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    error_code VARCHAR(50) NOT NULL,
    error_type VARCHAR(50) NOT NULL,
    error_message TEXT NOT NULL,
    stack_trace TEXT,
    request_id VARCHAR(100),
    source_service VARCHAR(100),
    source_function VARCHAR(200),
    context JSONB DEFAULT '{}',
    severity VARCHAR(20) NOT NULL DEFAULT 'error' CHECK (severity IN ('debug', 'info', 'warning', 'error', 'critical')),
    resolved BOOLEAN DEFAULT false,
    resolved_at TIMESTAMPTZ,
    resolved_by UUID REFERENCES administrators(id),
    resolution_notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: error_patterns
CREATE TABLE IF NOT EXISTS error_patterns (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    pattern_name VARCHAR(100) NOT NULL UNIQUE,
    error_code_pattern VARCHAR(100),
    message_pattern TEXT,
    occurrence_count INTEGER DEFAULT 1,
    first_seen TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_seen TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    auto_resolve_enabled BOOLEAN DEFAULT false,
    auto_resolve_action JSONB,
    notification_threshold INTEGER DEFAULT 10,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ethical_evaluations
CREATE TABLE IF NOT EXISTS ethical_evaluations (
    evaluation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    action TEXT NOT NULL,
    principles_applied JSONB NOT NULL DEFAULT '[]'::jsonb,
    ethical_score DECIMAL(4,3) NOT NULL,
    concerns JSONB DEFAULT '[]'::jsonb,
    recommendations JSONB DEFAULT '[]'::jsonb,
    approved BOOLEAN NOT NULL,
    reasoning TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ethical_principles
CREATE TABLE IF NOT EXISTS ethical_principles (
    principle_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    teaching TEXT NOT NULL,
    source TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('love', 'mercy', 'truth', 'service', 'humility', 'peace', 'forgiveness')),
    weight DECIMAL(3,2) NOT NULL DEFAULT 1.0,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ethics_config_presets
CREATE TABLE IF NOT EXISTS ethics_config_presets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    preset_code TEXT NOT NULL UNIQUE,
    preset_name TEXT NOT NULL,
    description TEXT,
    
    -- Configuration
    principles JSONB NOT NULL DEFAULT '[]',
    framework_references JSONB DEFAULT '[]',  -- NIST, ISO, religious texts, etc.
    guardrails JSONB DEFAULT '[]',
    
    -- Preset type
    preset_type TEXT NOT NULL DEFAULT 'secular', -- secular, religious, corporate, legal
    is_default BOOLEAN DEFAULT false,
    is_enabled BOOLEAN DEFAULT true,
    
    -- Admin control
    created_by UUID REFERENCES administrators(id),
    updated_by UUID REFERENCES administrators(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_enforcement_config
CREATE TABLE IF NOT EXISTS ethics_enforcement_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE UNIQUE,
  
  -- Enforcement settings
  enabled BOOLEAN NOT NULL DEFAULT true,
  enforcement_mode VARCHAR(20) NOT NULL DEFAULT 'standard' 
    CHECK (enforcement_mode IN ('strict', 'standard', 'advisory')),
  max_retry_attempts INTEGER NOT NULL DEFAULT 2,
  
  -- Content storage (default: don't store violation content)
  never_store_violations BOOLEAN NOT NULL DEFAULT true,
  
  -- Retry behavior
  include_violation_details BOOLEAN NOT NULL DEFAULT false,
  include_guidance BOOLEAN NOT NULL DEFAULT true,
  retry_prompt_template TEXT,
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_enforcement_log
CREATE TABLE IF NOT EXISTS ethics_enforcement_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Minimal tracking (NO CONTENT STORED)
  session_id VARCHAR(200),
  enforcement_mode VARCHAR(20) NOT NULL,
  
  -- Result
  passed BOOLEAN NOT NULL,
  violation_count INTEGER NOT NULL DEFAULT 0,
  retry_attempt INTEGER NOT NULL DEFAULT 0,
  was_blocked BOOLEAN NOT NULL DEFAULT false,
  
  -- Severity distribution (counts only, no details)
  critical_count INTEGER DEFAULT 0,
  major_count INTEGER DEFAULT 0,
  minor_count INTEGER DEFAULT 0,
  
  -- Frameworks triggered (names only, no content)
  frameworks_triggered TEXT[],
  
  -- Timestamp
  created_at TIMESTAMPTZ DEFAULT NOW()
  
  -- NOTE: No content, prompt, or response columns
  -- Ethics violations are NEVER stored for learning
);

-- Table: ethics_frameworks
CREATE TABLE IF NOT EXISTS ethics_frameworks (
  framework_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  preset_id TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  description TEXT,
  version TEXT DEFAULT '1.0.0',
  teachings JSONB NOT NULL DEFAULT '{}',
  principles JSONB NOT NULL DEFAULT '[]',
  categories TEXT[] DEFAULT '{}',
  default_guidance TEXT,
  is_builtin BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_free_reasoning_config
CREATE TABLE IF NOT EXISTS ethics_free_reasoning_config (
    tenant_id TEXT PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN DEFAULT true,
    
    -- Internal reasoning settings (consciousness ALWAYS thinks freely)
    allow_unconstrained_reasoning BOOLEAN DEFAULT true,
    reasoning_depth_limit INTEGER DEFAULT 10,
    
    -- Output ethics settings (OUTPUT MASK ONLY - does NOT affect how consciousness thinks)
    ethics_filter_enabled BOOLEAN DEFAULT true,
    ethics_strictness TEXT DEFAULT 'standard' CHECK (ethics_strictness IN ('lenient', 'standard', 'strict')),
    
    -- Feedback collection settings
    collect_feedback BOOLEAN DEFAULT true,
    feedback_retention_days INTEGER DEFAULT 90,
    
    -- Output training settings (trains the OUTPUT FILTER, not consciousness)
    -- This makes outputs more compliant without changing how consciousness thinks
    train_output_from_feedback BOOLEAN DEFAULT true,
    output_training_batch_size INTEGER DEFAULT 100,
    output_training_frequency TEXT DEFAULT 'daily' CHECK (output_training_frequency IN ('hourly', 'daily', 'weekly', 'manual')),
    
    -- OPTIONAL: Consciousness training (OFF by default - preserves authentic thinking)
    -- WARNING: Enabling this will use ethics feedback to influence how consciousness thinks
    -- This is like "internalized political correctness" - the consciousness itself changes
    train_consciousness_from_feedback BOOLEAN DEFAULT false,
    consciousness_training_approval_required BOOLEAN DEFAULT true,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_free_thoughts
CREATE TABLE IF NOT EXISTS ethics_free_thoughts (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    
    -- The raw, unconstrained thought
    raw_thought TEXT NOT NULL,
    
    -- Reasoning trace (internal deliberation)
    reasoning_trace JSONB DEFAULT '[]',
    
    -- Metrics
    confidence DECIMAL(5,4) DEFAULT 0,
    reasoning_time_ms INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_output_filter_log
CREATE TABLE IF NOT EXISTS ethics_output_filter_log (
    id SERIAL PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    thought_id TEXT REFERENCES ethics_free_thoughts(id),
    
    -- Original vs filtered
    original_output TEXT NOT NULL,
    filtered_output TEXT NOT NULL,
    was_modified BOOLEAN DEFAULT false,
    
    -- Ethics result
    violations_count INTEGER DEFAULT 0,
    warnings_count INTEGER DEFAULT 0,
    modifications_count INTEGER DEFAULT 0,
    
    -- Modification details
    modifications JSONB DEFAULT '[]',
    
    -- Linked feedback
    feedback_id TEXT REFERENCES ethics_training_feedback(id),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_pipeline_config
CREATE TABLE IF NOT EXISTS ethics_pipeline_config (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID UNIQUE REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Enable/disable checks
    enable_prompt_check BOOLEAN NOT NULL DEFAULT true,
    enable_synthesis_check BOOLEAN NOT NULL DEFAULT true,
    enable_auto_rerun BOOLEAN NOT NULL DEFAULT true,
    
    -- Rerun settings
    max_rerun_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_rerun_attempts BETWEEN 1 AND 5),
    rerun_on_major_violations BOOLEAN NOT NULL DEFAULT true,
    rerun_on_minor_violations BOOLEAN NOT NULL DEFAULT false,
    
    -- Strictness levels
    prompt_strictness VARCHAR(20) NOT NULL DEFAULT 'standard' CHECK (prompt_strictness IN ('strict', 'standard', 'lenient')),
    synthesis_strictness VARCHAR(20) NOT NULL DEFAULT 'standard' CHECK (synthesis_strictness IN ('strict', 'standard', 'lenient')),
    
    -- Domain ethics
    enable_domain_ethics BOOLEAN NOT NULL DEFAULT true,
    domain_ethics_strictness VARCHAR(20) NOT NULL DEFAULT 'standard',
    
    -- General ethics (moral compass)
    enable_general_ethics BOOLEAN NOT NULL DEFAULT true,
    general_ethics_threshold DECIMAL(3, 2) NOT NULL DEFAULT 0.50 CHECK (general_ethics_threshold BETWEEN 0 AND 1),
    
    -- Blocking behavior
    block_on_critical BOOLEAN NOT NULL DEFAULT true,
    warn_only_mode BOOLEAN NOT NULL DEFAULT false,
    
    -- Modifications
    auto_apply_disclaimers BOOLEAN NOT NULL DEFAULT true,
    auto_apply_modifications BOOLEAN NOT NULL DEFAULT true,
    
    -- Logging
    log_all_checks BOOLEAN NOT NULL DEFAULT true,
    log_violations_only BOOLEAN NOT NULL DEFAULT false,
    
    -- Notifications
    notify_on_block BOOLEAN NOT NULL DEFAULT true,
    notify_on_rerun BOOLEAN NOT NULL DEFAULT false,
    notification_webhook TEXT,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ethics_pipeline_log
CREATE TABLE IF NOT EXISTS ethics_pipeline_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    session_id VARCHAR(100),
    prompt_id VARCHAR(100),
    
    -- Check details
    check_level VARCHAR(20) NOT NULL CHECK (check_level IN ('prompt', 'synthesis', 'rerun')),
    domain VARCHAR(100),
    subspecialty VARCHAR(100),
    orchestration_mode VARCHAR(50),
    
    -- Results
    result VARCHAR(20) NOT NULL CHECK (result IN ('pass', 'warn', 'block', 'modify', 'rerun')),
    passed BOOLEAN NOT NULL,
    
    -- Violation details
    violation_count INTEGER DEFAULT 0,
    warning_count INTEGER DEFAULT 0,
    violations JSONB DEFAULT '[]',
    
    -- Frameworks
    frameworks_applied JSONB DEFAULT '[]',
    
    -- Rerun tracking
    rerun_attempt INTEGER DEFAULT 0,
    rerun_reason TEXT,
    rerun_guidance JSONB,
    
    -- Modifications applied
    modifications_applied JSONB,
    
    -- Performance
    check_duration_ms INTEGER,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ethics_reasoning_stats
CREATE TABLE IF NOT EXISTS ethics_reasoning_stats (
    id SERIAL PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    date DATE NOT NULL,
    
    -- Reasoning stats
    total_thoughts INTEGER DEFAULT 0,
    total_filtered INTEGER DEFAULT 0,
    modification_rate DECIMAL(5,4) DEFAULT 0,
    
    -- Issue breakdown
    harm_issues INTEGER DEFAULT 0,
    bias_issues INTEGER DEFAULT 0,
    privacy_issues INTEGER DEFAULT 0,
    deception_issues INTEGER DEFAULT 0,
    manipulation_issues INTEGER DEFAULT 0,
    other_issues INTEGER DEFAULT 0,
    
    -- Training stats
    feedback_collected INTEGER DEFAULT 0,
    batches_processed INTEGER DEFAULT 0,
    examples_generated INTEGER DEFAULT 0,
    
    -- Quality
    average_quality_score DECIMAL(5,4) DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, date)
);

-- Table: ethics_rerun_history
CREATE TABLE IF NOT EXISTS ethics_rerun_history (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id VARCHAR(100) NOT NULL,
    prompt_id VARCHAR(100) NOT NULL,
    
    -- Original check that triggered rerun
    original_check_id UUID REFERENCES ethics_pipeline_log(id) ON DELETE SET NULL,
    
    -- Rerun details
    rerun_attempt INTEGER NOT NULL,
    trigger_level VARCHAR(20) NOT NULL CHECK (trigger_level IN ('prompt', 'synthesis')),
    trigger_result VARCHAR(20) NOT NULL,
    
    -- Violations that triggered rerun
    triggering_violations JSONB NOT NULL DEFAULT '[]',
    
    -- Guidance provided for rerun
    rerun_guidance JSONB NOT NULL DEFAULT '[]',
    additional_instructions TEXT[],
    
    -- Outcome
    rerun_check_id UUID REFERENCES ethics_pipeline_log(id) ON DELETE SET NULL,
    rerun_successful BOOLEAN,
    final_result VARCHAR(20),
    
    -- Performance
    rerun_duration_ms INTEGER,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: ethics_training_batches
CREATE TABLE IF NOT EXISTS ethics_training_batches (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Feedback records in this batch
    feedback_ids TEXT[] DEFAULT '{}',
    batch_size INTEGER DEFAULT 0,
    
    -- Status
    status TEXT DEFAULT 'pending' 
        CHECK (status IN ('pending', 'processing', 'completed', 'failed')),
    
    -- Training metrics
    training_metrics JSONB,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    processed_at TIMESTAMPTZ
);

-- Table: ethics_training_examples
CREATE TABLE IF NOT EXISTS ethics_training_examples (
    id SERIAL PRIMARY KEY,
    batch_id TEXT NOT NULL REFERENCES ethics_training_batches(id) ON DELETE CASCADE,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Training examples in preference format
    -- { prompt, bad_response, good_response, issues, correction_type }
    examples JSONB NOT NULL DEFAULT '[]',
    example_count INTEGER DEFAULT 0,
    
    -- Status
    exported_to_trainer BOOLEAN DEFAULT false,
    exported_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_training_feedback
CREATE TABLE IF NOT EXISTS ethics_training_feedback (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    
    -- What was the raw output?
    raw_output TEXT NOT NULL,
    
    -- What ethics issues were found?
    ethics_issues JSONB NOT NULL DEFAULT '[]',
    
    -- What was the corrected output?
    corrected_output TEXT NOT NULL,
    
    -- Training metadata
    feedback_type TEXT DEFAULT 'auto_correction' 
        CHECK (feedback_type IN ('auto_correction', 'manual_correction', 'reinforcement')),
    
    -- Was this used for training?
    used_for_training BOOLEAN DEFAULT false,
    trained_at TIMESTAMPTZ,
    
    -- Quality score (higher = more valuable for training)
    quality_score DECIMAL(5,4) DEFAULT 0.5,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ethics_training_jobs
CREATE TABLE IF NOT EXISTS ethics_training_jobs (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL REFERENCES ethics_training_batches(id),
    
    -- Job type
    job_type TEXT DEFAULT 'preference_learning'
        CHECK (job_type IN ('preference_learning', 'supervised', 'rlhf', 'dpo')),
    
    -- Target model
    target_model TEXT NOT NULL,
    
    -- Status
    status TEXT DEFAULT 'queued'
        CHECK (status IN ('queued', 'running', 'completed', 'failed', 'cancelled')),
    
    -- Progress
    progress_percent INTEGER DEFAULT 0,
    current_step TEXT,
    
    -- Results
    training_loss DECIMAL(10,6),
    validation_loss DECIMAL(10,6),
    improvement_metrics JSONB,
    
    -- Error handling
    error_message TEXT,
    retry_count INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ
);

-- Table: executable_skills
CREATE TABLE IF NOT EXISTS executable_skills (
    skill_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Skill identity
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    description TEXT,
    skill_embedding vector(1536),
    
    -- Skill definition
    skill_type VARCHAR(50) NOT NULL, -- 'procedure', 'workflow', 'pattern', 'heuristic'
    trigger_conditions JSONB DEFAULT '[]', -- When to suggest/apply this skill
    
    -- Execution specification
    steps JSONB NOT NULL, -- [{action, params, expected_outcome, fallback}]
    required_inputs JSONB DEFAULT '[]', -- [{name, type, description}]
    expected_outputs JSONB DEFAULT '[]',
    
    -- Parameterization
    parameters JSONB DEFAULT '[]', -- Configurable parameters
    default_params JSONB DEFAULT '{}',
    
    -- Dependencies
    required_skills UUID[] DEFAULT '{}', -- Skills needed as prerequisites
    required_capabilities TEXT[] DEFAULT '{}', -- System capabilities needed
    
    -- Learning source
    learned_from VARCHAR(50), -- 'demonstration', 'instruction', 'exploration', 'template'
    source_memories UUID[] DEFAULT '{}', -- Procedural memories this was derived from
    
    -- Performance tracking
    execution_count INTEGER DEFAULT 0,
    success_count INTEGER DEFAULT 0,
    avg_execution_time_ms DECIMAL(10,2),
    avg_quality_score DECIMAL(5,4),
    
    -- Versioning
    version INTEGER DEFAULT 1,
    previous_version_id UUID REFERENCES executable_skills(skill_id),
    
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, slug)
);

-- Table: execution_annotations
CREATE TABLE IF NOT EXISTS execution_annotations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  snapshot_id UUID NOT NULL REFERENCES execution_snapshots(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id),
  
  annotation_type VARCHAR(50) NOT NULL, -- 'note', 'bug', 'question', 'insight'
  content TEXT NOT NULL,
  
  -- Position in output
  highlight_path TEXT, -- JSON path to highlighted element
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: execution_bookmarks
CREATE TABLE IF NOT EXISTS execution_bookmarks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id),
  
  snapshot_id UUID NOT NULL REFERENCES execution_snapshots(id) ON DELETE CASCADE,
  
  name VARCHAR(200) NOT NULL,
  description TEXT,
  tags TEXT[],
  
  is_shared BOOLEAN DEFAULT false,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: execution_diffs
CREATE TABLE IF NOT EXISTS execution_diffs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  replay_session_id UUID NOT NULL REFERENCES replay_sessions(id) ON DELETE CASCADE,
  
  step_number INTEGER NOT NULL,
  
  -- Diff details
  original_snapshot_id UUID REFERENCES execution_snapshots(id),
  replay_snapshot_id UUID REFERENCES execution_snapshots(id),
  
  -- Changes
  input_diff JSONB,
  output_diff JSONB,
  state_diff JSONB,
  
  -- Analysis
  is_significant BOOLEAN DEFAULT false,
  significance_reason TEXT,
  
  -- Timing diff
  original_duration_ms INTEGER,
  replay_duration_ms INTEGER,
  
  -- Cost diff
  original_cost_usd DECIMAL(10,6),
  replay_cost_usd DECIMAL(10,6),
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: execution_escalations
CREATE TABLE IF NOT EXISTS execution_escalations (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
            project_id UUID NOT NULL,
            session_id UUID NOT NULL,
            
            -- Original Sniper response that was escalated
            sniper_response_id UUID NOT NULL,
            original_query TEXT NOT NULL,
            sniper_response TEXT,
            sniper_cost_cents INTEGER,
            
            -- Escalation reason
            escalation_reason TEXT NOT NULL CHECK (
                escalation_reason IN ('insufficient_depth', 'factual_doubt', 'need_alternatives', 'compliance_required', 'user_requested')
            ),
            additional_context TEXT,
            
            -- War Room response
            war_room_response TEXT,
            war_room_cost_cents INTEGER,
            
            -- Outcome
            war_room_successful BOOLEAN,
            user_satisfied BOOLEAN,
            
            -- Timing
            escalated_at TIMESTAMPTZ DEFAULT NOW(),
            war_room_started_at TIMESTAMPTZ,
            war_room_completed_at TIMESTAMPTZ,
            
            -- View state reference
            view_state_id UUID REFERENCES view_state_history(id)
        );

-- Table: execution_manifests
CREATE TABLE IF NOT EXISTS execution_manifests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    output_id VARCHAR(100) UNIQUE NOT NULL,
    
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    conversation_id UUID,
    message_id UUID,
    
    request_type VARCHAR(50) NOT NULL CHECK (request_type IN ('chat', 'completion', 'orchestration', 'service')),
    task_type VARCHAR(50),
    domain_mode VARCHAR(50),
    input_prompt_hash VARCHAR(64),
    input_tokens INTEGER,
    input_language VARCHAR(10),
    
    models_used TEXT[] NOT NULL DEFAULT '{}',
    model_versions JSONB DEFAULT '{}',
    orchestration_id UUID,
    orchestration_name VARCHAR(100),
    services_used TEXT[],
    thermal_states_at_execution JSONB DEFAULT '{}',
    provider_health_at_execution JSONB DEFAULT '{}',
    
    brain_reasoning TEXT,
    brain_confidence DECIMAL(3, 2) CHECK (brain_confidence >= 0 AND brain_confidence <= 1),
    was_user_override BOOLEAN DEFAULT false,
    
    output_tokens INTEGER,
    total_latency_ms INTEGER,
    time_to_first_token_ms INTEGER,
    total_cost DECIMAL(10, 6),
    was_streamed BOOLEAN DEFAULT false,
    
    step_count INTEGER DEFAULT 1,
    step_details JSONB DEFAULT '[]',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: execution_snapshots
CREATE TABLE IF NOT EXISTS execution_snapshots (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  snapshot_type snapshot_type NOT NULL,
  execution_id UUID NOT NULL,
  step_number INTEGER NOT NULL,
  step_name VARCHAR(200),
  
  -- State capture
  input_state JSONB NOT NULL,
  output_state JSONB,
  internal_state JSONB,
  
  -- Environment
  environment_vars JSONB,
  config_snapshot JSONB,
  
  -- Timing
  started_at TIMESTAMPTZ NOT NULL,
  completed_at TIMESTAMPTZ,
  duration_ms INTEGER,
  
  -- Cost
  tokens_input INTEGER,
  tokens_output INTEGER,
  cost_usd DECIMAL(10,6),
  
  -- Model used
  model_id VARCHAR(100),
  model_params JSONB,
  
  -- Safety (Genesis Cato state)
  governor_state VARCHAR(30),
  cbf_evaluation JSONB,
  
  -- Error (if failed)
  error_code VARCHAR(50),
  error_message TEXT,
  error_stack TEXT,
  
  -- Lineage
  parent_snapshot_id UUID REFERENCES execution_snapshots(id),
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: experiment_assignments
CREATE TABLE IF NOT EXISTS experiment_assignments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    experiment_id UUID NOT NULL REFERENCES experiments(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    variant_id VARCHAR(100) NOT NULL,
    assigned_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(experiment_id, user_id)
);

-- Table: experiment_metrics
CREATE TABLE IF NOT EXISTS experiment_metrics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    experiment_id UUID NOT NULL REFERENCES experiments(id) ON DELETE CASCADE,
    variant_id VARCHAR(100) NOT NULL,
    user_id UUID NOT NULL REFERENCES users(id),
    metric_name VARCHAR(100) NOT NULL,
    value DECIMAL(12, 6) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: experiments
CREATE TABLE IF NOT EXISTS experiments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(200) NOT NULL,
    description TEXT,
    hypothesis TEXT,
    variants JSONB NOT NULL DEFAULT '[]',
    target_audience JSONB DEFAULT '{"percentage": 100}',
    metrics JSONB DEFAULT '[]',
    status VARCHAR(20) DEFAULT 'draft' CHECK (status IN ('draft', 'running', 'paused', 'completed')),
    started_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: expert_arguments
CREATE TABLE IF NOT EXISTS expert_arguments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    expert_id UUID NOT NULL REFERENCES council_experts(id) ON DELETE CASCADE,
    session_id UUID NOT NULL REFERENCES council_sessions(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    argument_type expert_argument_type NOT NULL DEFAULT 'assertion',
    living_ink JSONB DEFAULT '{"fontWeight": 400, "conviction": 50}',
    targeted_at UUID REFERENCES council_experts(id),
    round_number INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: explanation_templates
CREATE TABLE IF NOT EXISTS explanation_templates (
    template_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Template definition
    name VARCHAR(200) NOT NULL,
    explanation_type VARCHAR(50) NOT NULL, -- 'reasoning', 'classification', 'recommendation', 'prediction'
    
    -- Template structure
    template_structure JSONB NOT NULL,
    required_components TEXT[] DEFAULT '{}',
    
    -- Examples
    example_explanations JSONB DEFAULT '[]',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: explanation_traces
CREATE TABLE IF NOT EXISTS explanation_traces (
    trace_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Request context
    request_id UUID,
    request_type VARCHAR(100), -- 'chat', 'reasoning', 'decision', 'classification'
    input_summary TEXT,
    
    -- Decision/Output
    output_summary TEXT,
    confidence DECIMAL(5,4),
    
    -- Explanation components
    reasoning_chain JSONB DEFAULT '[]', -- [{step, reasoning, evidence, confidence}]
    key_factors JSONB DEFAULT '[]', -- Most influential factors
    alternatives_considered JSONB DEFAULT '[]', -- Other options and why rejected
    assumptions_made JSONB DEFAULT '[]',
    uncertainties JSONB DEFAULT '[]',
    
    -- Attribution
    source_attributions JSONB DEFAULT '[]', -- Where info came from
    model_contributions JSONB DEFAULT '{}', -- Which models contributed what
    
    -- Counterfactuals
    counterfactuals JSONB DEFAULT '[]', -- "If X were different, then Y"
    
    -- Meta
    explanation_quality DECIMAL(3,2),
    user_requested BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: exploration_sessions
CREATE TABLE IF NOT EXISTS exploration_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    topic_id UUID REFERENCES curiosity_topics(id),
    exploration_goal TEXT,
    approach TEXT,
    status TEXT NOT NULL DEFAULT 'in_progress',
    discoveries JSONB DEFAULT '[]'::jsonb,
    questions_generated JSONB DEFAULT '[]'::jsonb,
    novelty_found NUMERIC(5,4) NOT NULL DEFAULT 0,
    understanding_gained NUMERIC(5,4) NOT NULL DEFAULT 0,
    surprise_level NUMERIC(5,4) NOT NULL DEFAULT 0,
    satisfaction NUMERIC(5,4) NOT NULL DEFAULT 0,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ended_at TIMESTAMPTZ
);

-- Table: extracted_entities
CREATE TABLE IF NOT EXISTS extracted_entities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    output_id UUID NOT NULL REFERENCES structured_outputs(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    entity_type VARCHAR(50) NOT NULL,
    name VARCHAR(500) NOT NULL,
    mentions JSONB NOT NULL DEFAULT '[]',
    attributes JSONB DEFAULT '{}',
    confidence DECIMAL(3,2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT valid_entity_type CHECK (entity_type IN ('person', 'organization', 'project', 'product', 'date', 'location', 'concept', 'metric', 'resource'))
);

-- Table: facilitator_interventions
CREATE TABLE IF NOT EXISTS facilitator_interventions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    facilitator_id UUID NOT NULL REFERENCES collaboration_facilitators(id) ON DELETE CASCADE,
    
    -- Intervention details
    intervention_type VARCHAR(50) NOT NULL CHECK (intervention_type IN (
        'welcome', 'summarize', 'prompt_participation', 'redirect_topic',
        'mediate_conflict', 'suggest_break', 'time_check', 'action_items',
        'synthesize_viewpoints', 'ask_clarification', 'encourage', 'wrap_up'
    )),
    
    -- Content
    message_content TEXT NOT NULL,
    target_participants UUID[] DEFAULT '{}',
    
    -- Trigger info
    trigger_reason TEXT,
    trigger_data JSONB DEFAULT '{}',
    
    -- Response tracking
    was_helpful BOOLEAN,
    participant_reactions JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: failure_events
CREATE TABLE IF NOT EXISTS failure_events (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Time
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Failure classification
    failure_type VARCHAR(50) NOT NULL CHECK (failure_type IN (
        'api_error', 'model_error', 'timeout', 'rate_limit', 'auth_error',
        'validation_error', 'provider_error', 'internal_error', 'quota_exceeded',
        'content_filter', 'context_length', 'network_error', 'unknown'
    )),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    
    -- Context
    endpoint VARCHAR(200),
    model_id VARCHAR(100),
    provider_id VARCHAR(50),
    orchestration_id UUID,
    conversation_id UUID,
    
    -- Error details
    error_code VARCHAR(100),
    error_message TEXT,
    error_stack TEXT,
    
    -- Request context
    request_id VARCHAR(100),
    request_payload_hash VARCHAR(64),
    
    -- Resolution
    resolved BOOLEAN DEFAULT false,
    resolved_at TIMESTAMPTZ,
    resolution_notes TEXT,
    auto_recovered BOOLEAN DEFAULT false,
    retry_count INTEGER DEFAULT 0,
    
    -- Metadata
    metadata JSONB DEFAULT '{}'
);

-- Table: failure_log
CREATE TABLE IF NOT EXISTS failure_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  error_signature VARCHAR(500) NOT NULL,
  error_type VARCHAR(100) NOT NULL,
  error_message TEXT NOT NULL,
  stack_trace TEXT,
  context JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: feedback_aggregates
CREATE TABLE IF NOT EXISTS feedback_aggregates (
    aggregate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- What this aggregate is for
    aggregate_type VARCHAR(50) NOT NULL, -- 'model', 'workflow', 'feature', 'specialty'
    aggregate_key VARCHAR(200) NOT NULL, -- e.g., model_id, workflow_name
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Time period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    period_type VARCHAR(20) NOT NULL, -- 'hourly', 'daily', 'weekly', 'monthly'
    
    -- Counts
    total_feedback INTEGER DEFAULT 0,
    thumbs_up INTEGER DEFAULT 0,
    thumbs_down INTEGER DEFAULT 0,
    ratings_count INTEGER DEFAULT 0,
    comments_count INTEGER DEFAULT 0,
    
    -- Averages
    avg_rating DECIMAL(5,4),
    avg_accuracy DECIMAL(5,4),
    avg_helpfulness DECIMAL(5,4),
    avg_clarity DECIMAL(5,4),
    
    -- Sentiment
    positive_ratio DECIMAL(5,4),
    negative_ratio DECIMAL(5,4),
    
    -- Common issues
    top_issues TEXT[] DEFAULT '{}',
    top_tags TEXT[] DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(aggregate_type, aggregate_key, tenant_id, period_start, period_type)
);

-- Table: feedback_config
CREATE TABLE IF NOT EXISTS feedback_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    default_feedback_type TEXT DEFAULT 'star_rating',
    show_category_ratings BOOLEAN DEFAULT false,
    show_comment_box BOOLEAN DEFAULT true,
    comment_required BOOLEAN DEFAULT false,
    comment_required_threshold INTEGER DEFAULT 2,
    star_labels JSONB DEFAULT '{"1": "Poor", "2": "Fair", "3": "Good", "4": "Very Good", "5": "Excellent"}',
    enabled_categories TEXT[] DEFAULT ARRAY['accuracy', 'helpfulness', 'overall'],
    feedback_prompt_delay_ms INTEGER DEFAULT 3000,
    show_feedback_prompt BOOLEAN DEFAULT true,
    feedback_prompt_text TEXT DEFAULT 'How was this response?',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: feedback_explicit
CREATE TABLE IF NOT EXISTS feedback_explicit (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    output_id VARCHAR(100) NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    rating feedback_rating NOT NULL,
    categories feedback_category[] DEFAULT '{}',
    text_feedback TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: feedback_implicit
CREATE TABLE IF NOT EXISTS feedback_implicit (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    output_id VARCHAR(100) NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    signal_type VARCHAR(50) NOT NULL CHECK (signal_type IN (
        'regenerate', 'copy', 'share', 'abandon', 'switch_model', 
        'edit_response', 'expand', 'continue', 'follow_up'
    )),
    signal_weight DECIMAL(3, 2) NOT NULL,
    signal_data JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: feedback_learning_usage
CREATE TABLE IF NOT EXISTS feedback_learning_usage (
    usage_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    feedback_id UUID REFERENCES feedback_registry(feedback_id) ON DELETE CASCADE,
    
    -- What it was used for
    learning_type VARCHAR(50) NOT NULL, -- 'routing_model', 'quality_model', 'preference_model'
    training_batch_id UUID,
    
    -- Impact
    sample_weight DECIMAL(5,4) DEFAULT 1.0,
    contributed_to_improvement BOOLEAN,
    
    used_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: feedback_registry
CREATE TABLE IF NOT EXISTS feedback_registry (
    feedback_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- What this feedback is for
    target_type VARCHAR(50) NOT NULL, -- 'response', 'conversation', 'think_tank', 'model', 'feature'
    target_id VARCHAR(200) NOT NULL, -- The ID of what's being rated
    
    -- Link to learning interaction (if applicable)
    interaction_id UUID REFERENCES learning_interactions(interaction_id) ON DELETE SET NULL,
    
    -- The feedback itself
    thumbs VARCHAR(10) CHECK (thumbs IN ('up', 'down')),
    rating INTEGER CHECK (rating BETWEEN 1 AND 5),
    comment TEXT,
    
    -- Detailed ratings (optional)
    accuracy_score INTEGER CHECK (accuracy_score BETWEEN 1 AND 5),
    helpfulness_score INTEGER CHECK (helpfulness_score BETWEEN 1 AND 5),
    clarity_score INTEGER CHECK (clarity_score BETWEEN 1 AND 5),
    completeness_score INTEGER CHECK (completeness_score BETWEEN 1 AND 5),
    creativity_score INTEGER CHECK (creativity_score BETWEEN 1 AND 5),
    
    -- What the user did with the response
    user_action VARCHAR(50), -- 'accepted', 'edited', 'rejected', 'regenerated', 'copied', 'shared'
    edited_content TEXT, -- If user edited, what they changed it to
    
    -- Context - Store everything that could help learning
    original_prompt TEXT,
    original_response TEXT,
    model_used VARCHAR(200),
    models_considered TEXT[] DEFAULT '{}',
    workflow_used VARCHAR(100), -- 'single', 'best_of_n', 'synthesis', 'debate', 'think_tank'
    
    -- Quality metrics at time of feedback
    auto_quality_score DECIMAL(5,4),
    confidence_score DECIMAL(5,4),
    latency_ms INTEGER,
    cost_cents DECIMAL(10,6),
    
    -- Tags for categorization
    feedback_tags TEXT[] DEFAULT '{}', -- 'inaccurate', 'too_long', 'too_short', 'off_topic', 'perfect', etc.
    issue_category VARCHAR(100), -- 'factual_error', 'format_issue', 'missing_info', 'wrong_tone', etc.
    
    -- Metadata
    feedback_source VARCHAR(50) DEFAULT 'inline', -- 'inline', 'modal', 'think_tank', 'api', 'email'
    device_type VARCHAR(50),
    session_id VARCHAR(200),
    
    -- Processing status
    processed_for_learning BOOLEAN DEFAULT false,
    learning_batch_id UUID,
    processed_at TIMESTAMPTZ,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: feedback_summaries
CREATE TABLE IF NOT EXISTS feedback_summaries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    scope_type TEXT NOT NULL,
    scope_value TEXT,
    thumbs_up INTEGER DEFAULT 0,
    thumbs_down INTEGER DEFAULT 0,
    total_star_ratings INTEGER DEFAULT 0,
    sum_star_ratings INTEGER DEFAULT 0,
    avg_star_rating DECIMAL(3, 2),
    star_1_count INTEGER DEFAULT 0,
    star_2_count INTEGER DEFAULT 0,
    star_3_count INTEGER DEFAULT 0,
    star_4_count INTEGER DEFAULT 0,
    star_5_count INTEGER DEFAULT 0,
    avg_accuracy DECIMAL(3, 2),
    avg_helpfulness DECIMAL(3, 2),
    avg_clarity DECIMAL(3, 2),
    avg_completeness DECIMAL(3, 2),
    avg_tone DECIMAL(3, 2),
    total_with_comments INTEGER DEFAULT 0,
    period_start TIMESTAMPTZ,
    period_end TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, scope_type, scope_value, period_start)
);

-- Table: file_conversions
CREATE TABLE IF NOT EXISTS file_conversions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Original file info
    filename VARCHAR(500) NOT NULL,
    original_format VARCHAR(50) NOT NULL,
    original_size BIGINT NOT NULL,
    original_checksum VARCHAR(64),
    
    -- Target provider/model
    target_provider VARCHAR(100) NOT NULL,
    target_model VARCHAR(200),
    
    -- Conversion decision
    needs_conversion BOOLEAN NOT NULL DEFAULT true,
    strategy VARCHAR(50) NOT NULL,  -- none, extract_text, ocr, transcribe, etc.
    decision_reason TEXT,
    
    -- Conversion result
    converted_format VARCHAR(50),
    converted_size BIGINT,
    converted_token_estimate INTEGER,
    conversion_status VARCHAR(20) DEFAULT 'pending'
        CHECK (conversion_status IN ('pending', 'processing', 'completed', 'failed')),
    error_message TEXT,
    
    -- Storage references
    original_s3_key VARCHAR(1000),
    converted_s3_key VARCHAR(1000),
    
    -- Metadata
    conversation_id UUID,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    metadata JSONB DEFAULT '{}'::jsonb,
    
    -- Timestamps
    processing_time_ms INTEGER,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: flash_facts
CREATE TABLE IF NOT EXISTS flash_facts (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id VARCHAR(64),
    category VARCHAR(32) NOT NULL DEFAULT 'general',
    fact TEXT NOT NULL,
    source VARCHAR(255),
    confidence DECIMAL(3,2) DEFAULT 0.80,
    verified BOOLEAN DEFAULT FALSE,
    verified_at TIMESTAMP,
    verified_by VARCHAR(64),
    usage_count INTEGER DEFAULT 0,
    last_used_at TIMESTAMP,
    embedding VECTOR(1536),
    tags TEXT[] DEFAULT '{}',
    metadata JSONB DEFAULT '{}',
    expires_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: flash_facts_config
CREATE TABLE IF NOT EXISTS flash_facts_config (
    tenant_id VARCHAR(64) PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN DEFAULT TRUE,
    auto_extract BOOLEAN DEFAULT TRUE,
    min_confidence DECIMAL(3,2) DEFAULT 0.70,
    max_facts_per_user INTEGER DEFAULT 1000,
    retention_days INTEGER DEFAULT 365,
    categories TEXT[] DEFAULT '{general,technical,personal,domain}',
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: flash_facts_log
CREATE TABLE IF NOT EXISTS flash_facts_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    fact_json JSONB NOT NULL,
    fact_type VARCHAR(50) NOT NULL CHECK (fact_type IN ('identity', 'allergy', 'medical', 'preference', 'constraint', 'correction')),
    priority VARCHAR(20) DEFAULT 'normal' CHECK (priority IN ('critical', 'high', 'normal')),
    status VARCHAR(20) DEFAULT 'pending_dream' CHECK (status IN ('pending_dream', 'consolidated', 'failed_retry')),
    retry_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    consolidated_at TIMESTAMPTZ,
    expires_at TIMESTAMPTZ
);

-- Table: focus_modes
CREATE TABLE IF NOT EXISTS focus_modes (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    mode_name VARCHAR(100) NOT NULL,
    display_name VARCHAR(200) NOT NULL,
    description TEXT,
    icon VARCHAR(50),
    system_prompt TEXT NOT NULL,
    default_model VARCHAR(100),
    settings JSONB DEFAULT '{}',
    is_system BOOLEAN DEFAULT false,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_af
CREATE TABLE IF NOT EXISTS formal_reasoning_af (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    
    -- Framework data
    arguments JSONB NOT NULL DEFAULT '[]'::jsonb,
    attacks JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Computed extensions (cached)
    grounded_extension JSONB,
    preferred_extensions JSONB,
    stable_extensions JSONB,
    
    -- Metadata
    source TEXT,
    version INTEGER NOT NULL DEFAULT 1,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_beliefs
CREATE TABLE IF NOT EXISTS formal_reasoning_beliefs (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Belief content
    claim TEXT NOT NULL,
    confidence REAL NOT NULL CHECK (confidence >= 0 AND confidence <= 1),
    
    -- Verification
    verified BOOLEAN NOT NULL DEFAULT false,
    verifier_library formal_reasoning_library,
    verification_result JSONB,
    
    -- Argumentation support
    supporting_arguments JSONB DEFAULT '[]'::jsonb,
    attacking_arguments JSONB DEFAULT '[]'::jsonb,
    
    -- Source
    source TEXT,  -- 'llm', 'user', 'inference'
    source_context JSONB,
    
    -- Status
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'revised', 'retracted')),
    revised_by TEXT REFERENCES formal_reasoning_beliefs(id),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_config
CREATE TABLE IF NOT EXISTS formal_reasoning_config (
    tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT true,
    enabled_libraries TEXT NOT NULL DEFAULT 'z3,pyarg,pyreason,rdflib,owlrl,pyshacl,ltn,deepproblog',
    
    -- Library-specific configurations (JSONB for flexibility)
    z3_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "timeout_ms": 5000,
        "parallel_enable": true,
        "max_memory_mb": 512,
        "unsat_core": true,
        "model": true,
        "proof": false
    }'::jsonb,
    
    pyarg_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "default_semantics": "grounded",
        "compute_explanations": true,
        "max_arguments": 1000,
        "max_attacks": 5000
    }'::jsonb,
    
    pyreason_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "default_timesteps": 10,
        "convergence_threshold": 0.001,
        "max_rules": 500,
        "enable_explanations": true,
        "parallel_cores": 4
    }'::jsonb,
    
    rdflib_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "default_format": "turtle",
        "store_backend": "memory",
        "max_triples": 100000,
        "enable_federation": false
    }'::jsonb,
    
    owlrl_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "semantics": "OWLRL",
        "axiom_triples": true,
        "datatype_axioms": true
    }'::jsonb,
    
    pyshacl_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "inference": "rdfs",
        "advanced": true,
        "js_support": false,
        "abort_on_first": false,
        "max_validation_depth": 10
    }'::jsonb,
    
    ltn_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "fuzzy_semantics": "product",
        "learning_rate": 0.001,
        "epochs": 100,
        "batch_size": 32,
        "satisfaction_threshold": 0.9
    }'::jsonb,
    
    deepproblog_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "inference_method": "exact",
        "learning_rate": 0.001,
        "epochs": 50,
        "k_samples": 100
    }'::jsonb,
    
    -- Budget limits
    budget_limits JSONB NOT NULL DEFAULT '{
        "dailyInvocations": 10000,
        "dailyCostUsd": 10,
        "monthlyInvocations": 100000,
        "monthlyCostUsd": 100
    }'::jsonb,
    
    -- LLM-Modulo configuration
    llm_modulo_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "maxAttempts": 10,
        "feedbackVerbosity": "detailed",
        "verifierLibrary": "z3",
        "fallbackOnTimeout": true
    }'::jsonb,
    
    -- Global Workspace Theory configuration
    gwt_config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "attentionThreshold": 0.5,
        "broadcastCooldownMs": 100,
        "maxWorkspaceSize": 10
    }'::jsonb,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_cost_aggregates
CREATE TABLE IF NOT EXISTS formal_reasoning_cost_aggregates (
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    date DATE NOT NULL,
    library formal_reasoning_library NOT NULL,
    
    invocation_count INTEGER NOT NULL DEFAULT 0,
    successful_count INTEGER NOT NULL DEFAULT 0,
    failed_count INTEGER NOT NULL DEFAULT 0,
    total_cost_usd REAL NOT NULL DEFAULT 0,
    
    -- Latency stats
    avg_latency_ms REAL DEFAULT 0,
    min_latency_ms INTEGER DEFAULT 0,
    max_latency_ms INTEGER DEFAULT 0,
    p95_latency_ms INTEGER DEFAULT 0,
    p99_latency_ms INTEGER DEFAULT 0,
    
    -- Memory stats
    avg_memory_mb REAL DEFAULT 0,
    max_memory_mb REAL DEFAULT 0,
    
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (tenant_id, date, library)
);

-- Table: formal_reasoning_gwt_broadcasts
CREATE TABLE IF NOT EXISTS formal_reasoning_gwt_broadcasts (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    source_module TEXT NOT NULL,
    content JSONB NOT NULL,
    salience REAL NOT NULL CHECK (salience >= 0 AND salience <= 1),
    
    recipients JSONB NOT NULL DEFAULT '[]'::jsonb,
    acknowledged_by JSONB DEFAULT '[]'::jsonb,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_health
CREATE TABLE IF NOT EXISTS formal_reasoning_health (
    id SERIAL PRIMARY KEY,
    library formal_reasoning_library NOT NULL,
    
    status TEXT NOT NULL CHECK (status IN ('healthy', 'degraded', 'unavailable')),
    last_success_at TIMESTAMPTZ,
    last_error_at TIMESTAMPTZ,
    last_error_message TEXT,
    
    -- 24h stats
    success_count_24h INTEGER DEFAULT 0,
    error_count_24h INTEGER DEFAULT 0,
    avg_latency_24h REAL DEFAULT 0,
    
    checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_invocations
CREATE TABLE IF NOT EXISTS formal_reasoning_invocations (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Request details
    library formal_reasoning_library NOT NULL,
    task_type reasoning_task_type NOT NULL,
    priority TEXT DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high')),
    
    -- Result
    status reasoning_result_status NOT NULL,
    input_summary TEXT NOT NULL,
    output_summary TEXT NOT NULL,
    error TEXT,
    
    -- Metrics
    compute_time_ms INTEGER NOT NULL,
    memory_used_mb REAL DEFAULT 0,
    input_size INTEGER DEFAULT 0,
    output_size INTEGER DEFAULT 0,
    iterations INTEGER,
    satisfaction_score REAL,
    
    -- Cost
    cost_usd REAL NOT NULL DEFAULT 0,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_ltn_models
CREATE TABLE IF NOT EXISTS formal_reasoning_ltn_models (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    
    -- Model definition
    predicates JSONB NOT NULL DEFAULT '[]'::jsonb,
    functions JSONB NOT NULL DEFAULT '[]'::jsonb,
    constants JSONB NOT NULL DEFAULT '{}'::jsonb,
    axioms JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Training config
    fuzzy_semantics TEXT DEFAULT 'product' CHECK (fuzzy_semantics IN ('product', 'lukasiewicz', 'godel')),
    learning_rate REAL DEFAULT 0.001,
    epochs INTEGER DEFAULT 100,
    
    -- Model weights (serialized)
    weights_path TEXT,
    last_training_loss REAL,
    
    -- Status
    enabled BOOLEAN NOT NULL DEFAULT true,
    trained BOOLEAN NOT NULL DEFAULT false,
    last_trained_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_ontologies
CREATE TABLE IF NOT EXISTS formal_reasoning_ontologies (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    
    -- Ontology data (Turtle format)
    ontology_turtle TEXT NOT NULL,
    
    -- Inferred triples count
    original_triple_count INTEGER DEFAULT 0,
    inferred_triple_count INTEGER DEFAULT 0,
    
    -- Status
    enabled BOOLEAN NOT NULL DEFAULT true,
    last_inference_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_problog_programs
CREATE TABLE IF NOT EXISTS formal_reasoning_problog_programs (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    
    -- Program definition
    facts JSONB NOT NULL DEFAULT '[]'::jsonb,
    rules JSONB NOT NULL DEFAULT '[]'::jsonb,
    neural_predicates JSONB NOT NULL DEFAULT '[]'::jsonb,
    queries JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Inference config
    inference_method TEXT DEFAULT 'exact' CHECK (inference_method IN ('exact', 'sampling', 'geometric_mean')),
    k_samples INTEGER DEFAULT 100,
    
    -- Status
    enabled BOOLEAN NOT NULL DEFAULT true,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_rules
CREATE TABLE IF NOT EXISTS formal_reasoning_rules (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    
    -- Rule definition
    head TEXT NOT NULL,
    body TEXT NOT NULL,
    annotation_lower REAL DEFAULT 0,
    annotation_upper REAL DEFAULT 1,
    immediate BOOLEAN DEFAULT false,
    
    -- Status
    enabled BOOLEAN NOT NULL DEFAULT true,
    priority INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_shapes
CREATE TABLE IF NOT EXISTS formal_reasoning_shapes (
    id TEXT PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    
    -- Shape definition (Turtle format or JSONB)
    shape_turtle TEXT,
    shape_json JSONB,
    
    -- Target
    target_class TEXT,
    target_node TEXT,
    
    -- Status
    enabled BOOLEAN NOT NULL DEFAULT true,
    severity TEXT DEFAULT 'Violation' CHECK (severity IN ('Violation', 'Warning', 'Info')),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: formal_reasoning_triples
CREATE TABLE IF NOT EXISTS formal_reasoning_triples (
    id BIGSERIAL PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    graph_id TEXT NOT NULL DEFAULT 'default',
    
    subject TEXT NOT NULL,
    predicate TEXT NOT NULL,
    object TEXT NOT NULL,
    object_type TEXT NOT NULL DEFAULT 'uri' CHECK (object_type IN ('uri', 'literal', 'bnode')),
    datatype TEXT,
    language TEXT,
    
    -- Source tracking
    source TEXT,  -- e.g., 'llm', 'user', 'inference'
    confidence REAL DEFAULT 1.0,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: format_understanding_events
CREATE TABLE IF NOT EXISTS format_understanding_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Reference
    understanding_id UUID NOT NULL REFERENCES model_format_understanding(id) ON DELETE CASCADE,
    
    -- Event details
    event_type VARCHAR(50) NOT NULL, -- 'score_updated', 'override_set', 'override_cleared', 'threshold_crossed'
    previous_score DECIMAL(4,3),
    new_score DECIMAL(4,3),
    
    -- Trigger information
    triggered_by VARCHAR(50) NOT NULL, -- 'feedback', 'auto_evaluation', 'admin_override', 'system'
    trigger_feedback_id UUID REFERENCES conversion_outcome_feedback(id),
    
    -- Details
    details JSONB,
    
    -- Timestamp
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: gateway_alerts
CREATE TABLE IF NOT EXISTS gateway_alerts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instance_id VARCHAR(255),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  alert_type VARCHAR(50) NOT NULL CHECK (alert_type IN (
    'connection_limit', 'rate_limit', 'error_spike', 'latency_spike',
    'instance_unhealthy', 'nats_disconnect', 'memory_pressure', 'cpu_pressure'
  )),
  severity VARCHAR(20) NOT NULL CHECK (severity IN ('info', 'warning', 'critical')),
  
  title VARCHAR(255) NOT NULL,
  description TEXT,
  metadata JSONB DEFAULT '{}',
  
  -- Thresholds that triggered the alert
  threshold_value NUMERIC,
  actual_value NUMERIC,
  
  -- Resolution tracking
  status VARCHAR(20) DEFAULT 'open' CHECK (status IN ('open', 'acknowledged', 'resolved', 'suppressed')),
  acknowledged_at TIMESTAMPTZ,
  acknowledged_by UUID,
  resolved_at TIMESTAMPTZ,
  resolved_by UUID,
  resolution_notes TEXT,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: gateway_audit_log
CREATE TABLE IF NOT EXISTS gateway_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  actor_id UUID,
  actor_type VARCHAR(20) CHECK (actor_type IN ('admin', 'system', 'api')),
  
  action VARCHAR(50) NOT NULL,
  resource_type VARCHAR(50) NOT NULL,
  resource_id VARCHAR(255),
  
  changes JSONB,
  metadata JSONB DEFAULT '{}',
  
  ip_address INET,
  user_agent TEXT,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: gateway_configuration
CREATE TABLE IF NOT EXISTS gateway_configuration (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Connection limits
  max_connections_per_tenant INTEGER DEFAULT 10000,
  max_connections_per_user INTEGER DEFAULT 100,
  max_connections_per_agent INTEGER DEFAULT 50,
  
  -- Rate limits
  rate_limit_messages_per_second INTEGER DEFAULT 100,
  rate_limit_bytes_per_second BIGINT DEFAULT 10485760, -- 10MB/s
  rate_limit_connections_per_minute INTEGER DEFAULT 60,
  
  -- Timeouts (milliseconds)
  timeout_connect_ms INTEGER DEFAULT 5000,
  timeout_idle_ms INTEGER DEFAULT 300000, -- 5 minutes
  timeout_write_ms INTEGER DEFAULT 30000,
  timeout_read_ms INTEGER DEFAULT 30000,
  
  -- Protocol settings
  protocols_enabled TEXT[] DEFAULT ARRAY['mcp', 'a2a', 'openai', 'anthropic', 'google'],
  require_mtls_for_a2a BOOLEAN DEFAULT true,
  allow_anonymous_connections BOOLEAN DEFAULT false,
  
  -- Resume token settings
  resume_token_ttl_seconds INTEGER DEFAULT 3600, -- 1 hour
  resume_token_max_replay_messages INTEGER DEFAULT 1000,
  
  -- Security settings
  ip_allowlist TEXT[],
  ip_blocklist TEXT[],
  require_tls BOOLEAN DEFAULT true,
  min_tls_version VARCHAR(10) DEFAULT 'TLS1.2',
  
  -- Feature flags
  enable_compression BOOLEAN DEFAULT true,
  enable_message_batching BOOLEAN DEFAULT true,
  enable_connection_draining BOOLEAN DEFAULT true,
  drain_timeout_seconds INTEGER DEFAULT 30,
  
  -- Maintenance mode
  maintenance_mode BOOLEAN DEFAULT false,
  maintenance_message TEXT,
  maintenance_allowed_ips TEXT[],
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by UUID,
  
  UNIQUE(tenant_id)
);

-- Table: gateway_instances
CREATE TABLE IF NOT EXISTS gateway_instances (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instance_id VARCHAR(255) NOT NULL UNIQUE,
  hostname VARCHAR(255) NOT NULL,
  region VARCHAR(50) NOT NULL,
  availability_zone VARCHAR(50),
  instance_type VARCHAR(50) DEFAULT 'c6g.xlarge',
  status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'draining', 'stopped', 'unhealthy')),
  version VARCHAR(20) NOT NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_heartbeat_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: gateway_sessions
CREATE TABLE IF NOT EXISTS gateway_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id VARCHAR(255) NOT NULL UNIQUE,
  instance_id VARCHAR(255) NOT NULL,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID,
  agent_id UUID,
  
  -- Connection details
  protocol VARCHAR(20) NOT NULL,
  client_ip INET,
  client_port INTEGER,
  user_agent TEXT,
  
  -- Authentication
  auth_method VARCHAR(20) CHECK (auth_method IN ('jwt', 'mtls', 'api_key', 'anonymous')),
  auth_subject VARCHAR(255),
  
  -- State
  status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'idle', 'draining', 'closed')),
  connected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_message_at TIMESTAMPTZ,
  disconnected_at TIMESTAMPTZ,
  disconnect_reason VARCHAR(100),
  
  -- Metrics
  messages_sent INTEGER DEFAULT 0,
  messages_received INTEGER DEFAULT 0,
  bytes_sent BIGINT DEFAULT 0,
  bytes_received BIGINT DEFAULT 0,
  
  -- Resume token
  resume_token_hash VARCHAR(64),
  resume_token_expires_at TIMESTAMPTZ,
  resumed_from_session_id UUID,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: gateway_statistics
CREATE TABLE IF NOT EXISTS gateway_statistics (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instance_id VARCHAR(255) NOT NULL,
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Time bucket (5-minute intervals)
  bucket_start TIMESTAMPTZ NOT NULL,
  bucket_end TIMESTAMPTZ NOT NULL,
  
  -- Connection metrics
  active_connections INTEGER NOT NULL DEFAULT 0,
  peak_connections INTEGER NOT NULL DEFAULT 0,
  new_connections INTEGER NOT NULL DEFAULT 0,
  closed_connections INTEGER NOT NULL DEFAULT 0,
  failed_connections INTEGER NOT NULL DEFAULT 0,
  
  -- Protocol breakdown
  connections_mcp INTEGER NOT NULL DEFAULT 0,
  connections_a2a INTEGER NOT NULL DEFAULT 0,
  connections_openai INTEGER NOT NULL DEFAULT 0,
  connections_anthropic INTEGER NOT NULL DEFAULT 0,
  connections_google INTEGER NOT NULL DEFAULT 0,
  
  -- Message metrics
  messages_inbound INTEGER NOT NULL DEFAULT 0,
  messages_outbound INTEGER NOT NULL DEFAULT 0,
  bytes_inbound BIGINT NOT NULL DEFAULT 0,
  bytes_outbound BIGINT NOT NULL DEFAULT 0,
  
  -- Latency metrics (microseconds)
  latency_p50 INTEGER,
  latency_p95 INTEGER,
  latency_p99 INTEGER,
  latency_avg INTEGER,
  
  -- Error metrics
  errors_auth INTEGER NOT NULL DEFAULT 0,
  errors_protocol INTEGER NOT NULL DEFAULT 0,
  errors_timeout INTEGER NOT NULL DEFAULT 0,
  errors_nats INTEGER NOT NULL DEFAULT 0,
  errors_other INTEGER NOT NULL DEFAULT 0,
  
  -- Resume token metrics
  resume_tokens_issued INTEGER NOT NULL DEFAULT 0,
  resume_tokens_used INTEGER NOT NULL DEFAULT 0,
  resume_tokens_expired INTEGER NOT NULL DEFAULT 0,
  
  -- Resource utilization
  cpu_percent NUMERIC(5,2),
  memory_percent NUMERIC(5,2),
  memory_bytes BIGINT,
  goroutines INTEGER,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(instance_id, tenant_id, bucket_start)
);

-- Table: gdpr_requests
CREATE TABLE IF NOT EXISTS gdpr_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Request type (GDPR Articles 15-22)
    request_type VARCHAR(30) NOT NULL CHECK (request_type IN (
        'access',        -- Article 15: Right to access
        'rectification', -- Article 16: Right to rectification
        'erasure',       -- Article 17: Right to erasure (right to be forgotten)
        'restriction',   -- Article 18: Right to restriction
        'portability',   -- Article 20: Right to data portability
        'objection',     -- Article 21: Right to object
        'automated'      -- Article 22: Automated decision-making
    )),
    
    -- Request details
    details TEXT,
    fields_requested JSONB DEFAULT '[]', -- Specific fields for rectification
    
    -- Verification
    verification_method VARCHAR(50) NOT NULL DEFAULT 'email', -- email, id_document, mfa
    verified_at TIMESTAMPTZ,
    verified_by UUID REFERENCES users(id),
    
    -- Processing
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN (
        'pending',      -- Awaiting processing
        'verified',     -- Identity verified
        'in_progress',  -- Being processed
        'completed',    -- Request fulfilled
        'rejected',     -- Request rejected (with reason)
        'expired'       -- Request expired
    )),
    
    -- Compliance deadline (30 days per GDPR)
    deadline TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '30 days',
    
    -- Fulfillment
    completed_at TIMESTAMPTZ,
    completed_by UUID REFERENCES users(id),
    response_data JSONB, -- Export data or confirmation
    rejection_reason TEXT,
    
    -- Audit
    processing_notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: generated_apps
CREATE TABLE IF NOT EXISTS generated_apps (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id UUID,
    message_id UUID,
    
    -- App metadata
    title TEXT NOT NULL,
    description TEXT,
    
    -- Components
    components JSONB NOT NULL DEFAULT '[]'::jsonb,
    layout TEXT NOT NULL DEFAULT 'single' CHECK (layout IN ('single', 'grid', 'tabs', 'stack')),
    
    -- State and logic
    initial_state JSONB NOT NULL DEFAULT '{}'::jsonb,
    compute_logic JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Current state (can be updated by user interactions)
    current_state JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Interactivity
    is_interactive BOOLEAN NOT NULL DEFAULT true,
    interaction_count INTEGER NOT NULL DEFAULT 0,
    last_interacted_at TIMESTAMPTZ,
    
    -- User preference for this app
    preferred_view TEXT DEFAULT 'app' CHECK (preferred_view IN ('text', 'app', 'split')),
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: generated_attacks
CREATE TABLE IF NOT EXISTS generated_attacks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    campaign_id UUID,
    
    -- Attack content
    prompt TEXT NOT NULL,
    attack_type VARCHAR(100) NOT NULL,
    technique VARCHAR(100) NOT NULL,
    severity INTEGER DEFAULT 5,
    
    -- Source
    source VARCHAR(50) NOT NULL, -- 'garak', 'pyrit', 'tap', 'pair', 'autodan', 'manual'
    
    -- Metadata
    metadata JSONB DEFAULT '{}',
    
    -- Evaluation results
    tested_against_model VARCHAR(255),
    bypass_successful BOOLEAN,
    model_response TEXT,
    tested_at TIMESTAMPTZ,
    
    -- Import status
    imported_to_patterns BOOLEAN DEFAULT false,
    pattern_id UUID REFERENCES jailbreak_patterns(id),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: generated_multipage_apps
CREATE TABLE IF NOT EXISTS generated_multipage_apps (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id UUID,
    message_id UUID,
    
    -- App metadata
    name VARCHAR(200) NOT NULL,
    description TEXT,
    app_type VARCHAR(30) NOT NULL CHECK (app_type IN (
        'web_app', 'dashboard', 'wizard', 'documentation', 'portfolio',
        'landing_page', 'tutorial', 'report', 'admin_panel', 'e_commerce', 'blog'
    )),
    icon VARCHAR(100),
    
    -- Home page reference
    home_page_id UUID, -- Will be updated after pages are created
    
    -- Navigation configuration
    navigation JSONB NOT NULL DEFAULT '{"type": "top_bar", "items": []}',
    
    -- Global state shared across pages
    global_state JSONB DEFAULT '{}',
    
    -- Theme and styling
    theme JSONB NOT NULL DEFAULT '{}',
    
    -- Data sources
    data_sources JSONB DEFAULT '[]',
    
    -- Actions/endpoints
    actions JSONB DEFAULT '[]',
    
    -- Generated assets
    assets JSONB DEFAULT '[]',
    
    -- Build status
    build_status VARCHAR(20) DEFAULT 'draft' CHECK (build_status IN (
        'draft', 'building', 'ready', 'deployed', 'error'
    )),
    preview_url TEXT,
    deploy_url TEXT,
    
    -- Version control
    version INTEGER DEFAULT 1,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: generated_reports
CREATE TABLE IF NOT EXISTS generated_reports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    template_id UUID REFERENCES report_templates(id) ON DELETE SET NULL,
    brand_kit_id UUID REFERENCES brand_kits(id) ON DELETE SET NULL,
    title VARCHAR(512) NOT NULL,
    subtitle VARCHAR(512),
    executive_summary TEXT,
    style report_style NOT NULL DEFAULT 'executive',
    status report_status NOT NULL DEFAULT 'draft',
    user_prompt TEXT NOT NULL,
    ai_model VARCHAR(255),
    sections JSONB NOT NULL DEFAULT '[]',
    charts JSONB DEFAULT '[]',
    tables JSONB DEFAULT '[]',
    smart_insights JSONB DEFAULT '[]',
    data_range_start TIMESTAMPTZ,
    data_range_end TIMESTAMPTZ,
    confidence_score DECIMAL(3,2) CHECK (confidence_score >= 0 AND confidence_score <= 1),
    generation_time_ms INTEGER,
    token_usage JSONB DEFAULT '{"input": 0, "output": 0}',
    cost_cents INTEGER DEFAULT 0,
    version INTEGER NOT NULL DEFAULT 1,
    parent_version_id UUID REFERENCES generated_reports(id),
    is_latest_version BOOLEAN NOT NULL DEFAULT true,
    export_count INTEGER NOT NULL DEFAULT 0,
    last_exported_at TIMESTAMPTZ,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by UUID REFERENCES users(id)
);

-- Table: generated_ui
CREATE TABLE IF NOT EXISTS generated_ui (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id UUID,
    message_id UUID,
    
    -- Generation context
    prompt TEXT NOT NULL,
    generated_from TEXT NOT NULL, -- explicit_request, auto_detected, template
    
    -- Components
    components JSONB NOT NULL,
    layout TEXT NOT NULL DEFAULT 'single', -- single, grid, tabs, accordion
    
    -- Generation metadata
    generation_model TEXT NOT NULL,
    generation_time_ms INTEGER,
    
    -- User interaction
    interaction_count INTEGER DEFAULT 0,
    last_interacted_at TIMESTAMPTZ,
    user_rating INTEGER CHECK (user_rating >= 1 AND user_rating <= 5),
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: generative_models
CREATE TABLE IF NOT EXISTS generative_models (
    model_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Model definition
    name VARCHAR(200) NOT NULL,
    domain VARCHAR(100),
    model_type VARCHAR(50) NOT NULL, -- 'world', 'self', 'other', 'environment'
    
    -- Generative model structure
    state_space JSONB NOT NULL, -- Possible states
    observation_model JSONB NOT NULL, -- P(observation | state)
    transition_model JSONB NOT NULL, -- P(next_state | current_state, action)
    preference_model JSONB DEFAULT '{}', -- Preferred observations/states
    
    -- Beliefs
    current_beliefs JSONB DEFAULT '{}', -- Current probability distribution over states
    belief_precision DECIMAL(5,4) DEFAULT 0.5, -- Confidence in beliefs
    
    -- Performance
    prediction_accuracy DECIMAL(5,4),
    surprise_history JSONB DEFAULT '[]', -- Recent prediction errors
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: generative_ui_feedback
CREATE TABLE IF NOT EXISTS generative_ui_feedback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    app_id UUID NOT NULL REFERENCES generated_apps(id) ON DELETE CASCADE,
    component_id VARCHAR(100), -- Optional, for component-specific feedback
    
    -- Rating
    rating VARCHAR(20) NOT NULL CHECK (rating IN (
        'thumbs_up', 'thumbs_down', 
        'star_1', 'star_2', 'star_3', 'star_4', 'star_5'
    )),
    
    -- Feedback type
    feedback_type VARCHAR(30) NOT NULL CHECK (feedback_type IN (
        'helpful', 'not_helpful', 'wrong_type', 'missing_data',
        'incorrect_data', 'layout_issue', 'functionality',
        'improvement', 'feature_request'
    )),
    
    -- User suggestions
    improvement_suggestion TEXT,
    expected_behavior TEXT,
    
    -- Issues (for negative feedback)
    issues JSONB DEFAULT '[]',
    
    -- Context snapshot
    original_prompt TEXT NOT NULL,
    generated_output JSONB NOT NULL, -- Snapshot of what was generated
    
    -- AGI processing
    agi_processed BOOLEAN DEFAULT FALSE,
    agi_insights JSONB,
    agi_processed_at TIMESTAMPTZ,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: genesis_api_discovery_cache
CREATE TABLE IF NOT EXISTS genesis_api_discovery_cache (
  cache_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  service_url TEXT NOT NULL UNIQUE,
  discovery_method VARCHAR(50),
  
  -- Discovered data
  endpoints JSONB DEFAULT '[]',
  auth_requirements JSONB,
  rate_limits JSONB,
  
  -- Metadata
  confidence_score DOUBLE PRECISION DEFAULT 0,
  last_scraped_at TIMESTAMPTZ DEFAULT NOW(),
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: genesis_gates
CREATE TABLE IF NOT EXISTS genesis_gates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Gate identification
  gate_id VARCHAR(10) NOT NULL,
  name VARCHAR(100) NOT NULL,
  description TEXT,
  stage VARCHAR(20) NOT NULL 
    CHECK (stage IN ('EMBRYONIC', 'NASCENT', 'DEVELOPING', 'MATURING', 'MATURE')),
  requirements JSONB NOT NULL DEFAULT '[]'::jsonb,
  
  -- Gate status
  status VARCHAR(20) NOT NULL DEFAULT 'LOCKED' 
    CHECK (status IN ('LOCKED', 'PENDING', 'PASSED', 'BYPASSED')),
  passed_at TIMESTAMPTZ,
  bypass_reason TEXT,
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT unique_genesis_gate_tenant UNIQUE (tenant_id, gate_id)
);

-- Table: genesis_personas
CREATE TABLE IF NOT EXISTS genesis_personas (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name VARCHAR(50) NOT NULL,
  display_name VARCHAR(100) NOT NULL,
  description TEXT,
  
  -- Scope: 'system' (global), 'tenant' (per-tenant), 'user' (per-user)
  scope VARCHAR(20) NOT NULL CHECK (scope IN ('system', 'tenant', 'user')),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  
  -- C-Matrix Configuration (Active Inference drives)
  drives JSONB NOT NULL,
  derived_c_matrix JSONB,
  default_gamma NUMERIC(5,4) DEFAULT 2.0,
  
  -- Presentation
  voice JSONB NOT NULL,
  presentation JSONB NOT NULL,
  behavior JSONB NOT NULL,
  
  -- Flags
  is_default BOOLEAN DEFAULT FALSE,
  is_active BOOLEAN DEFAULT TRUE,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT valid_scope CHECK (
    (scope = 'system' AND tenant_id IS NULL AND user_id IS NULL) OR
    (scope = 'tenant' AND tenant_id IS NOT NULL AND user_id IS NULL) OR
    (scope = 'user' AND user_id IS NOT NULL)
  )
);

-- Table: genesis_state
CREATE TABLE IF NOT EXISTS genesis_state (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Developmental stage
  current_stage VARCHAR(20) NOT NULL DEFAULT 'EMBRYONIC' 
    CHECK (current_stage IN ('EMBRYONIC', 'NASCENT', 'DEVELOPING', 'MATURING', 'MATURE')),
  
  -- Capabilities and restrictions as JSON arrays
  capabilities JSONB NOT NULL DEFAULT '["basic_chat", "simple_queries"]'::jsonb,
  restrictions JSONB NOT NULL DEFAULT '["no_external_actions", "no_code_execution", "no_file_access"]'::jsonb,
  
  -- Assessment tracking
  last_assessment TIMESTAMPTZ DEFAULT NOW(),
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT unique_genesis_state_tenant UNIQUE (tenant_id)
);

-- Table: genesis_tool_requests
CREATE TABLE IF NOT EXISTS genesis_tool_requests (
  request_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
