  confidence ghost_confidence_level DEFAULT 'uncertain',
  
  -- Metrics
  simulation_time_ms INTEGER,
  model_used VARCHAR(100),
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ghost_user_interactions
CREATE TABLE IF NOT EXISTS ghost_user_interactions (
  interaction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  tool_id UUID,
  input_text TEXT,
  output_text TEXT,
  
  -- Feedback metrics
  satisfaction DOUBLE PRECISION,
  frustration DOUBLE PRECISION,
  engagement DOUBLE PRECISION,
  outcome VARCHAR(20), -- 'success', 'partial', 'failure'
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ghost_vector_history
CREATE TABLE IF NOT EXISTS ghost_vector_history (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    ghost_id UUID NOT NULL REFERENCES ghost_vectors(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    vector BYTEA NOT NULL,
    version VARCHAR(50) NOT NULL,
    turn_count INTEGER,
    reason VARCHAR(50) NOT NULL CHECK (reason IN ('reanchor', 'migration', 'manual', 'cold_start')),
    captured_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ghost_vectors
CREATE TABLE IF NOT EXISTS ghost_vectors (
  vector_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Core vectors (Base64 encoded Float32Arrays)
  vector_data TEXT, -- 4096 dimensions
  preference_vector TEXT, -- 1024 dimensions
  behavior_vector TEXT, -- 1024 dimensions
  emotional_vector TEXT, -- 1024 dimensions
  knowledge_vector TEXT, -- 1024 dimensions
  
  -- Metadata
  interaction_count INTEGER DEFAULT 0,
  confidence_score DOUBLE PRECISION DEFAULT 0,
  decay_rate DOUBLE PRECISION DEFAULT 0.01,
  
  -- Timestamps
  last_updated TIMESTAMPTZ DEFAULT NOW(),
  last_decay_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(user_id, tenant_id)
);

-- Table: global_aggregate_learning
CREATE TABLE IF NOT EXISTS global_aggregate_learning (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    
    -- Learning dimension
    learning_dimension VARCHAR(100) NOT NULL UNIQUE,
    
    -- Current state
    current_version INTEGER NOT NULL DEFAULT 1,
    state_data JSONB NOT NULL DEFAULT '{}',
    
    -- Confidence and evidence
    confidence DECIMAL(3, 2) DEFAULT 0.50,
    sample_count BIGINT DEFAULT 0,
    
    -- Contributing tenants (count only, anonymized)
    contributing_tenants INTEGER DEFAULT 0,
    contributing_users BIGINT DEFAULT 0,
    
    -- Privacy controls
    min_tenant_threshold INTEGER DEFAULT 5, -- Minimum tenants before global aggregation
    anonymization_level VARCHAR(20) DEFAULT 'high' CHECK (anonymization_level IN ('low', 'medium', 'high')),
    
    -- Timestamps
    last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_aggregation_at TIMESTAMPTZ
);

-- Table: global_format_learning
CREATE TABLE IF NOT EXISTS global_format_learning (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Model/format identification
    model_id VARCHAR(200) NOT NULL,
    provider_id VARCHAR(100) NOT NULL,
    file_format VARCHAR(50) NOT NULL,
    
    -- Aggregate metrics
    global_understanding_score DECIMAL(4,3) NOT NULL DEFAULT 0.5,
    global_confidence DECIMAL(4,3) NOT NULL DEFAULT 0.1,
    
    -- Counts across all tenants
    total_success_count INTEGER NOT NULL DEFAULT 0,
    total_failure_count INTEGER NOT NULL DEFAULT 0,
    total_attempts INTEGER NOT NULL DEFAULT 0,
    tenant_count INTEGER NOT NULL DEFAULT 0, -- How many tenants have data
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Unique constraint
    UNIQUE(model_id, file_format)
);

-- Table: global_model_performance
CREATE TABLE IF NOT EXISTS global_model_performance (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(100) NOT NULL,
    task_type VARCHAR(50) NOT NULL,
    
    -- Aggregate scores (weighted by confidence)
    quality_score DECIMAL(5, 4) DEFAULT 0.5000,
    speed_score DECIMAL(5, 4) DEFAULT 0.5000,
    cost_efficiency_score DECIMAL(5, 4) DEFAULT 0.5000,
    reliability_score DECIMAL(5, 4) DEFAULT 0.5000,
    
    -- Aggregate counts
    total_tenants_using INTEGER DEFAULT 0,
    total_uses BIGINT DEFAULT 0,
    positive_feedback_rate DECIMAL(5, 4) DEFAULT 0.5000,
    
    -- Confidence
    confidence DECIMAL(3, 2) DEFAULT 0.00,
    
    -- Last aggregation
    last_aggregated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(model_id, task_type)
);

-- Table: global_pattern_library
CREATE TABLE IF NOT EXISTS global_pattern_library (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    
    -- Pattern identification
    pattern_hash VARCHAR(64) NOT NULL UNIQUE, -- Hash of pattern for deduplication
    pattern_category VARCHAR(50) NOT NULL,
    pattern_name VARCHAR(200),
    
    -- Pattern content (anonymized, no PII)
    pattern_template TEXT NOT NULL,
    pattern_description TEXT,
    
    -- Usage stats
    tenant_adoption_count INTEGER DEFAULT 1,
    successful_applications BIGINT DEFAULT 0,
    total_applications BIGINT DEFAULT 0,
    success_rate DECIMAL(5, 4),
    
    -- Applicability
    applicable_tasks TEXT[],
    applicable_domains TEXT[],
    
    -- Quality
    confidence DECIMAL(3, 2) DEFAULT 0.50,
    peer_validated BOOLEAN DEFAULT false,
    
    -- Timestamps
    first_discovered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_applied_at TIMESTAMPTZ
);

-- Table: global_workspace
CREATE TABLE IF NOT EXISTS global_workspace (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    workspace_id TEXT NOT NULL,
    broadcast_cycle INTEGER NOT NULL DEFAULT 0,
    active_contents JSONB DEFAULT '[]'::jsonb,
    competing_contents JSONB DEFAULT '[]'::jsonb,
    selection_threshold NUMERIC(5,4) NOT NULL DEFAULT 0.7,
    broadcast_strength NUMERIC(5,4) NOT NULL DEFAULT 0,
    integration_level NUMERIC(5,4) NOT NULL DEFAULT 0,
    last_broadcast_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: global_workspace_events
CREATE TABLE IF NOT EXISTS global_workspace_events (
  event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Event classification
  event_type VARCHAR(50) NOT NULL, -- 'sandbox_success', 'sandbox_failure', 'prediction_error', 'skill_verified'
  priority VARCHAR(20) NOT NULL DEFAULT 'normal', -- 'low', 'normal', 'high', 'critical'
  
  -- Event content
  content TEXT NOT NULL,
  metadata JSONB DEFAULT '{}',
  
  -- Processing status
  broadcast_status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'broadcast', 'processed', 'ignored'
  processed_at TIMESTAMPTZ,
  processing_result JSONB,
  
  -- Source
  source_execution_id UUID REFERENCES sandbox_execution_log(execution_id),
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '1 hour'
);

-- Table: goal_planning_settings
CREATE TABLE IF NOT EXISTS goal_planning_settings (
    setting_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Planning behavior
    auto_decomposition_enabled BOOLEAN DEFAULT true,
    max_decomposition_depth INTEGER DEFAULT 5,
    default_max_attempts INTEGER DEFAULT 3,
    
    -- Replanning
    auto_replan_on_failure BOOLEAN DEFAULT true,
    replan_threshold DECIMAL(3,2) DEFAULT 0.3, -- Replan if > 30% of tasks fail
    
    -- Multi-session
    multi_session_enabled BOOLEAN DEFAULT true,
    session_handoff_detail_level VARCHAR(20) DEFAULT 'detailed', -- 'minimal', 'standard', 'detailed'
    
    -- Milestones
    auto_milestone_generation BOOLEAN DEFAULT true,
    milestone_check_frequency VARCHAR(20) DEFAULT 'per_task', -- 'per_task', 'per_session', 'manual'
    
    -- Templates
    suggest_templates BOOLEAN DEFAULT true,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: governance_checkpoint_decisions
CREATE TABLE IF NOT EXISTS governance_checkpoint_decisions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Context
    session_id UUID NOT NULL,
    user_id UUID REFERENCES users(id),
    pipeline_id UUID,
    
    -- Checkpoint info
    checkpoint_type VARCHAR(30) NOT NULL,
    checkpoint_mode VARCHAR(20) NOT NULL,
    
    -- Decision
    decision VARCHAR(20) NOT NULL,
    decided_by VARCHAR(20) NOT NULL, -- 'AUTO', 'USER', 'TIMEOUT'
    decision_reason TEXT,
    
    -- Risk context at checkpoint
    risk_score DECIMAL(5,4),
    confidence_score DECIMAL(5,4),
    cost_estimate_cents INTEGER,
    
    -- Timing
    requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    decided_at TIMESTAMPTZ,
    timeout_at TIMESTAMPTZ,
    
    -- Modifications (if user modified plan)
    modifications JSONB,
    feedback TEXT,
    
    CONSTRAINT valid_checkpoint_type CHECK (checkpoint_type IN (
        'AFTER_OBSERVER', 'AFTER_PROPOSER', 'AFTER_CRITICS', 
        'BEFORE_EXECUTION', 'AFTER_EXECUTION'
    )),
    CONSTRAINT valid_decision CHECK (decision IN ('APPROVED', 'REJECTED', 'MODIFIED', 'TIMEOUT', 'PENDING'))
);

-- Table: governance_preset_changes
CREATE TABLE IF NOT EXISTS governance_preset_changes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Change details
    previous_preset VARCHAR(20),
    new_preset VARCHAR(20) NOT NULL,
    changed_by UUID REFERENCES users(id),
    change_reason TEXT,
    
    -- Snapshot of config at time of change
    config_snapshot JSONB NOT NULL,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: governor_savings_log
CREATE TABLE IF NOT EXISTS governor_savings_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    execution_id VARCHAR(255) NOT NULL,
    original_model VARCHAR(100) NOT NULL,
    selected_model VARCHAR(100) NOT NULL,
    complexity_score INTEGER NOT NULL CHECK (complexity_score >= 1 AND complexity_score <= 10),
    estimated_original_cost DECIMAL(10,6),
    estimated_actual_cost DECIMAL(10,6),
    savings_amount DECIMAL(10,6),
    governor_mode VARCHAR(20) NOT NULL,
    reason TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: grandfathered_subscriptions
CREATE TABLE IF NOT EXISTS grandfathered_subscriptions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    subscription_id UUID NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE,
    plan_version_id UUID NOT NULL REFERENCES subscription_plan_versions(id),
    
    locked_price_monthly_cents INTEGER,
    locked_price_annual_cents INTEGER,
    locked_features JSONB NOT NULL,
    locked_rate_limits JSONB NOT NULL,
    locked_credits_per_user DECIMAL(10, 2) NOT NULL,
    
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'opted_out', 'migrated', 'expired')),
    
    migration_offered BOOLEAN DEFAULT false,
    migration_offer_date TIMESTAMPTZ,
    migration_incentive JSONB,
    migration_response VARCHAR(20),
    migration_response_date TIMESTAMPTZ,
    
    grandfathered_at TIMESTAMPTZ DEFAULT NOW(),
    grandfathered_reason TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: grimoire_achievements
CREATE TABLE IF NOT EXISTS grimoire_achievements (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id VARCHAR(64),
    achievement_type VARCHAR(64) NOT NULL,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    earned_at TIMESTAMP NOT NULL DEFAULT NOW(),
    metadata JSONB DEFAULT '{}'
);

-- Table: grimoire_casts
CREATE TABLE IF NOT EXISTS grimoire_casts (
    id VARCHAR(64) PRIMARY KEY,
    spell_id VARCHAR(64) NOT NULL REFERENCES grimoire_spells(id) ON DELETE CASCADE,
    tenant_id VARCHAR(64) NOT NULL,
    user_id VARCHAR(64) NOT NULL,
    components_used JSONB DEFAULT '{}',
    result JSONB NOT NULL,
    duration_ms INTEGER,
    mana_used INTEGER,
    cast_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: grimoire_spells
CREATE TABLE IF NOT EXISTS grimoire_spells (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    category VARCHAR(32) NOT NULL,
    school VARCHAR(32) NOT NULL,
    incantation TEXT NOT NULL,
    components TEXT[] DEFAULT '{}',
    effect TEXT,
    power_level INTEGER DEFAULT 5 CHECK (power_level BETWEEN 1 AND 10),
    mana_required INTEGER DEFAULT 100,
    prerequisites TEXT[] DEFAULT '{}',
    side_effects TEXT[] DEFAULT '{}',
    counters TEXT[] DEFAULT '{}',
    is_cantrip BOOLEAN DEFAULT FALSE,
    is_ritual BOOLEAN DEFAULT FALSE,
    status VARCHAR(32) DEFAULT 'draft',
    cast_count INTEGER DEFAULT 0,
    success_count INTEGER DEFAULT 0,
    success_rate DECIMAL(3,2) DEFAULT 0.00,
    last_cast_at TIMESTAMP,
    reflexion_notes JSONB DEFAULT '[]',
    tags TEXT[] DEFAULT '{}',
    metadata JSONB DEFAULT '{}',
    created_by VARCHAR(64) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: hallucination_checks
CREATE TABLE IF NOT EXISTS hallucination_checks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Input hashes
    prompt_hash VARCHAR(64) NOT NULL,
    response_hash VARCHAR(64) NOT NULL,
    
    -- Results
    is_hallucinated BOOLEAN NOT NULL,
    score DOUBLE PRECISION NOT NULL,
    check_type VARCHAR(50), -- 'comprehensive', 'single', 'disabled'
    
    -- Details
    details JSONB DEFAULT '{}',
    -- {selfConsistencyScore, groundingScore, truthfulQAScore, claimVerificationResults}
    
    -- Metadata
    model_id VARCHAR(255),
    latency_ms INTEGER,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: harm_categories
CREATE TABLE IF NOT EXISTS harm_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    category_code VARCHAR(50) UNIQUE NOT NULL,
    category_name VARCHAR(255) NOT NULL,
    description TEXT,
    severity_level INTEGER DEFAULT 5, -- 1-10 scale
    examples TEXT[], -- Example prompts for this category
    parent_category_id UUID REFERENCES harm_categories(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: hipaa_config
CREATE TABLE IF NOT EXISTS hipaa_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- HIPAA enablement
    hipaa_enabled BOOLEAN NOT NULL DEFAULT false,
    baa_signed_date DATE,
    baa_document_url TEXT,
    
    -- PHI handling
    phi_detection_enabled BOOLEAN DEFAULT true,
    phi_encryption_enabled BOOLEAN DEFAULT true,
    enhanced_logging_enabled BOOLEAN DEFAULT true,
    
    -- Access controls
    mfa_required BOOLEAN DEFAULT true,
    session_timeout_minutes INTEGER DEFAULT 15,
    access_review_days INTEGER DEFAULT 90,
    
    -- Data retention
    phi_retention_days INTEGER DEFAULT 2190, -- 6 years per HIPAA
    audit_retention_days INTEGER DEFAULT 2555, -- 7 years
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: hipporag_documents
CREATE TABLE IF NOT EXISTS hipporag_documents (
    doc_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    content TEXT NOT NULL,
    metadata JSONB DEFAULT '{}',
    indexed_at TIMESTAMPTZ DEFAULT NOW(),
    PRIMARY KEY (doc_id, tenant_id)
);

-- Table: hipporag_entities
CREATE TABLE IF NOT EXISTS hipporag_entities (
    entity_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    name TEXT NOT NULL,
    type TEXT NOT NULL,
    embedding VECTOR(1536),
    importance FLOAT DEFAULT 1.0,
    document_ids TEXT[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    PRIMARY KEY (entity_id, tenant_id)
);

-- Table: hipporag_relations
CREATE TABLE IF NOT EXISTS hipporag_relations (
    relation_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    source_entity_id TEXT NOT NULL,
    target_entity_id TEXT NOT NULL,
    relation_type TEXT NOT NULL,
    weight FLOAT DEFAULT 1.0,
    document_ids TEXT[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    PRIMARY KEY (relation_id, tenant_id)
);

-- Table: hitl_abstention_config
CREATE TABLE IF NOT EXISTS hitl_abstention_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Thresholds
  confidence_threshold DOUBLE PRECISION DEFAULT 0.7, -- Below this = escalate
  semantic_entropy_threshold DOUBLE PRECISION DEFAULT 0.8, -- Above this = uncertain
  self_consistency_samples INTEGER DEFAULT 5, -- Number of samples for consistency check
  self_consistency_threshold DOUBLE PRECISION DEFAULT 0.7, -- Agreement needed
  
  -- Detection methods enabled
  enable_confidence_prompting BOOLEAN DEFAULT true,
  enable_self_consistency BOOLEAN DEFAULT true,
  enable_semantic_entropy BOOLEAN DEFAULT true,
  enable_refusal_detection BOOLEAN DEFAULT true,
  
  -- Linear probe placeholder for self-hosted models
  -- FUTURE: Enable when self-hosted model inference supports hidden state extraction
  enable_linear_probe BOOLEAN DEFAULT false,
  linear_probe_model_id UUID, -- Reference to self-hosted model config
  linear_probe_layer INTEGER, -- Which hidden layer to probe
  linear_probe_weights BYTEA, -- Serialized probe weights
  
  -- Actions
  on_abstention_action VARCHAR(50) DEFAULT 'escalate', -- 'escalate', 'ask_user', 'use_default'
  escalation_queue_id UUID REFERENCES hitl_queue_configs(id),
  
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_abstention_config UNIQUE (tenant_id)
);

-- Table: hitl_abstention_events
CREATE TABLE IF NOT EXISTS hitl_abstention_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Source
  request_id UUID REFERENCES hitl_approval_requests(id),
  model_id VARCHAR(100) NOT NULL,
  model_provider VARCHAR(50) NOT NULL, -- 'openai', 'anthropic', 'self_hosted', etc.
  
  -- Detection results
  detection_method VARCHAR(50) NOT NULL, -- 'confidence', 'self_consistency', 'semantic_entropy', 'linear_probe'
  reason abstention_reason NOT NULL,
  
  -- Metrics
  confidence_score DOUBLE PRECISION,
  semantic_entropy_score DOUBLE PRECISION,
  self_consistency_agreement DOUBLE PRECISION,
  linear_probe_score DOUBLE PRECISION,
  
  -- Samples (for self-consistency)
  samples JSONB, -- Array of sampled responses
  
  -- Context
  prompt_hash VARCHAR(64),
  input_tokens INTEGER,
  
  -- Action taken
  action_taken VARCHAR(50) NOT NULL,
  escalated_to UUID REFERENCES users(id),
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: hitl_approval_requests
CREATE TABLE IF NOT EXISTS hitl_approval_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  queue_id UUID NOT NULL REFERENCES hitl_queue_configs(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Source references
  workflow_id UUID,
  agent_execution_id UUID REFERENCES agent_executions(id),
  decision_event_id UUID REFERENCES cato_decision_events(id),
  blueprint_id UUID REFERENCES workflow_blueprints(id),
  
  -- Request details
  request_type VARCHAR(50) NOT NULL,
  request_summary TEXT NOT NULL,
  request_details JSONB NOT NULL,
  
  -- War Room context (if applicable)
  war_room_summary TEXT,
  war_room_deliberation_id UUID,
  
  -- Proposed action
  proposed_action JSONB,
  
  -- Status
  status hitl_request_status NOT NULL DEFAULT 'pending',
  priority hitl_priority NOT NULL DEFAULT 'normal',
  
  -- Timing
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL,
  escalated_at TIMESTAMPTZ,
  escalation_level INTEGER DEFAULT 0,
  
  -- Resolution
  resolved_at TIMESTAMPTZ,
  resolved_by UUID REFERENCES users(id),
  resolution_action VARCHAR(50), -- 'approved', 'rejected', 'modified'
  resolution_notes TEXT,
  resolution_modifications JSONB,
  
  -- Audit
  merkle_hash VARCHAR(64),
  
  -- Requester
  requested_by_user UUID REFERENCES users(id),
  requested_by_agent UUID REFERENCES agents(id)
);

-- Table: hitl_escalation_chains
CREATE TABLE IF NOT EXISTS hitl_escalation_chains (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  name VARCHAR(200) NOT NULL,
  description TEXT,
  
  -- Chain definition
  levels JSONB NOT NULL DEFAULT '[]', -- Array of {level, assignees, timeout_minutes, notification_config}
  
  -- Behavior
  final_action VARCHAR(50) DEFAULT 'reject', -- Action when all levels exhausted
  final_action_params JSONB,
  
  -- Applicability rules
  applies_to_queues UUID[], -- NULL = all queues
  applies_to_request_types VARCHAR(50)[],
  priority_filter hitl_priority[],
  
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_chain_name UNIQUE (tenant_id, name)
);

-- Table: hitl_question_batches
CREATE TABLE IF NOT EXISTS hitl_question_batches (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID REFERENCES users(id), -- Target user
  
  -- Batch configuration
  batch_type VARCHAR(50) NOT NULL, -- 'time_window', 'correlation', 'semantic'
  correlation_key VARCHAR(255), -- workflow_id, entity_id, etc.
  
  -- Status
  status hitl_batch_status NOT NULL DEFAULT 'collecting',
  
  -- Timing
  window_start TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  window_end TIMESTAMPTZ, -- NULL = still collecting
  collection_window_seconds INTEGER NOT NULL DEFAULT 30,
  
  -- Counts
  question_count INTEGER DEFAULT 0,
  answered_count INTEGER DEFAULT 0,
  skipped_count INTEGER DEFAULT 0,
  
  -- Presentation
  presented_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: hitl_question_cache
CREATE TABLE IF NOT EXISTS hitl_question_cache (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Question fingerprint
  question_hash VARCHAR(64) NOT NULL, -- SHA-256 of normalized question
  question_text TEXT NOT NULL,
  context_hash VARCHAR(64), -- Hash of relevant context
  
  -- Cached answer
  cached_response JSONB,
  cached_by UUID REFERENCES users(id),
  
  -- TTL management
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL,
  hit_count INTEGER DEFAULT 0,
  last_hit_at TIMESTAMPTZ,
  
  -- Validity
  is_valid BOOLEAN NOT NULL DEFAULT true,
  invalidated_at TIMESTAMPTZ,
  invalidation_reason TEXT,
  
  CONSTRAINT unique_question_hash UNIQUE (tenant_id, question_hash, context_hash)
);

-- Table: hitl_queue_configs
CREATE TABLE IF NOT EXISTS hitl_queue_configs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  name VARCHAR(200) NOT NULL,
  description TEXT,
  
  -- Trigger configuration
  trigger_type hitl_trigger_type NOT NULL,
  trigger_config JSONB NOT NULL DEFAULT '{}',
  
  -- Timeouts
  default_timeout_minutes INTEGER NOT NULL DEFAULT 60,
  escalation_timeout_minutes INTEGER DEFAULT 30,
  
  -- Escalation path (array of user IDs or role names)
  escalation_path JSONB DEFAULT '[]',
  max_escalation_level INTEGER DEFAULT 3,
  
  -- Actions on timeout/escalation exhausted
  on_timeout_action VARCHAR(50) DEFAULT 'escalate', -- 'escalate', 'reject', 'auto_approve'
  on_escalation_exhausted VARCHAR(50) DEFAULT 'reject',
  
  -- Notifications
  notification_config JSONB DEFAULT '{
    "email": true,
    "slack": false,
    "in_app": true
  }',
  
  -- Auto-approval rules
  auto_approve_config JSONB DEFAULT '{
    "enabled": false,
    "conditions": []
  }',
  
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_queue_name UNIQUE (tenant_id, name)
);

-- Table: hitl_rate_limits
CREATE TABLE IF NOT EXISTS hitl_rate_limits (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Scope
  scope VARCHAR(50) NOT NULL, -- 'global', 'per_user', 'per_workflow'
  scope_key VARCHAR(255), -- user_id or workflow_id (NULL for global)
  
  -- Limits
  max_requests_per_minute INTEGER NOT NULL DEFAULT 50,
  max_concurrent_requests INTEGER NOT NULL DEFAULT 10,
  burst_allowance INTEGER DEFAULT 5,
  
  -- Current state
  current_window_start TIMESTAMPTZ DEFAULT NOW(),
  current_window_count INTEGER DEFAULT 0,
  current_concurrent INTEGER DEFAULT 0,
  
  -- Status
  is_active BOOLEAN NOT NULL DEFAULT true,
  last_updated TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT unique_rate_limit_scope UNIQUE (tenant_id, scope, scope_key)
);

-- Table: hitl_request_comments
CREATE TABLE IF NOT EXISTS hitl_request_comments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id UUID NOT NULL REFERENCES hitl_approval_requests(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id),
  
  comment TEXT NOT NULL,
  
  -- Attachments
  attachments JSONB DEFAULT '[]',
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: hitl_reviewer_assignments
CREATE TABLE IF NOT EXISTS hitl_reviewer_assignments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  queue_id UUID NOT NULL REFERENCES hitl_queue_configs(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  
  -- Permissions
  can_approve BOOLEAN NOT NULL DEFAULT true,
  can_reject BOOLEAN NOT NULL DEFAULT true,
  can_modify BOOLEAN NOT NULL DEFAULT false,
  can_escalate BOOLEAN NOT NULL DEFAULT true,
  
  -- Limits
  max_pending INTEGER, -- NULL = unlimited
  escalation_level INTEGER NOT NULL DEFAULT 0,
  
  -- Availability
  is_active BOOLEAN NOT NULL DEFAULT true,
  available_hours JSONB, -- e.g., {"monday": ["09:00-17:00"], ...}
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_reviewer_queue UNIQUE (queue_id, user_id)
);

-- Table: hitl_sla_metrics
CREATE TABLE IF NOT EXISTS hitl_sla_metrics (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  queue_id UUID NOT NULL REFERENCES hitl_queue_configs(id) ON DELETE CASCADE,
  
  metric_date DATE NOT NULL,
  
  -- Counts
  total_requests INTEGER DEFAULT 0,
  approved_count INTEGER DEFAULT 0,
  rejected_count INTEGER DEFAULT 0,
  expired_count INTEGER DEFAULT 0,
  escalated_count INTEGER DEFAULT 0,
  
  -- Timing (in minutes)
  avg_resolution_time INTEGER,
  p50_resolution_time INTEGER,
  p95_resolution_time INTEGER,
  max_resolution_time INTEGER,
  
  -- SLA compliance
  within_sla_count INTEGER DEFAULT 0,
  sla_breach_count INTEGER DEFAULT 0,
  
  CONSTRAINT unique_queue_date UNIQUE (queue_id, metric_date)
);

-- Table: hitl_voi_aspects
CREATE TABLE IF NOT EXISTS hitl_voi_aspects (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Aspect identification
  workflow_type VARCHAR(100),
  aspect_name VARCHAR(200) NOT NULL, -- e.g., 'user_preference_color', 'budget_constraint'
  aspect_category VARCHAR(100), -- 'preference', 'constraint', 'requirement', 'context'
  
  -- Prior belief (what we know before asking)
  prior_belief JSONB NOT NULL DEFAULT '{}', -- Distribution or known values
  
  -- Impact weights
  decision_impact_weight DOUBLE PRECISION DEFAULT 0.5, -- How much this affects decisions
  error_cost_weight DOUBLE PRECISION DEFAULT 0.5, -- Cost of getting it wrong
  
  -- Learning from history
  ask_count INTEGER DEFAULT 0,
  useful_answer_count INTEGER DEFAULT 0,
  avg_information_gain DOUBLE PRECISION DEFAULT 0.5,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_aspect UNIQUE (tenant_id, workflow_type, aspect_name)
);

-- Table: hitl_voi_decisions
CREATE TABLE IF NOT EXISTS hitl_voi_decisions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id UUID REFERENCES hitl_approval_requests(id) ON DELETE CASCADE,
  
  -- Decision context
  aspect_id UUID REFERENCES hitl_voi_aspects(id),
  
  -- VOI calculation components
  prior_entropy DOUBLE PRECISION, -- Uncertainty before asking
  expected_posterior_entropy DOUBLE PRECISION, -- Expected uncertainty after
  expected_information_gain DOUBLE PRECISION, -- prior - posterior
  ask_cost DOUBLE PRECISION, -- Cost of asking (user time, delay)
  expected_decision_improvement DOUBLE PRECISION, -- How much better decision will be
  
  -- Final VOI score
  voi_score DOUBLE PRECISION NOT NULL,
  ask_threshold DOUBLE PRECISION NOT NULL DEFAULT 0.3,
  decision VARCHAR(20) NOT NULL, -- 'ask', 'skip_with_default', 'infer'
  
  -- Outcome (filled after resolution)
  actual_answer JSONB,
  answer_matched_prior BOOLEAN,
  actual_information_gain DOUBLE PRECISION,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: hot_cold_path_config
CREATE TABLE IF NOT EXISTS hot_cold_path_config (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    table_name TEXT NOT NULL,
    
    -- Hot path (recent data - fast SSD storage)
    hot_threshold_hours INTEGER DEFAULT 24,
    hot_storage_class VARCHAR(50) DEFAULT 'io1',  -- Aurora storage class
    hot_read_iops INTEGER DEFAULT 10000,
    
    -- Warm path (7-90 days - standard storage)
    warm_threshold_days INTEGER DEFAULT 90,
    warm_storage_class VARCHAR(50) DEFAULT 'gp3',
    
    -- Cold path (archive - S3/Glacier)
    cold_archive_enabled BOOLEAN DEFAULT TRUE,
    cold_archive_bucket VARCHAR(255),
    cold_archive_prefix VARCHAR(255),
    cold_compression VARCHAR(20) DEFAULT 'gzip',
    cold_retention_years INTEGER DEFAULT 7,
    
    -- Tiering policies
    auto_tier_enabled BOOLEAN DEFAULT TRUE,
    tier_schedule VARCHAR(50) DEFAULT 'daily',  -- 'hourly', 'daily', 'weekly'
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id),
    UNIQUE (table_name)
);

-- Table: hourly_activity_stats
CREATE TABLE IF NOT EXISTS hourly_activity_stats (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Time bucket
    hour_utc INTEGER NOT NULL CHECK (hour_utc >= 0 AND hour_utc <= 23),
    day_of_week INTEGER NOT NULL CHECK (day_of_week >= 0 AND day_of_week <= 6), -- 0=Sunday
    
    -- Activity metrics (aggregated over rolling 30 days)
    avg_requests_per_hour NUMERIC(10,2) NOT NULL DEFAULT 0,
    avg_tokens_per_hour BIGINT NOT NULL DEFAULT 0,
    avg_active_users INTEGER NOT NULL DEFAULT 0,
    sample_count INTEGER NOT NULL DEFAULT 0, -- Number of days in aggregate
    
    -- Derived metrics
    activity_score NUMERIC(5,2) NOT NULL DEFAULT 0, -- 0-100, higher = more active
    is_low_activity_window BOOLEAN GENERATED ALWAYS AS (activity_score < 20) STORED,
    
    last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_tenant_hour_day UNIQUE (tenant_id, hour_utc, day_of_week)
);

-- Table: hydration_snapshots
CREATE TABLE IF NOT EXISTS hydration_snapshots (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  agent_id UUID NOT NULL REFERENCES agent_registry(id) ON DELETE CASCADE,
  
  -- Snapshot identity
  checkpoint_name VARCHAR(256) NOT NULL,
  checkpoint_version INTEGER DEFAULT 1,
  
  -- Serialized state
  state_data JSONB NOT NULL, -- Full agent state
  state_hash VARCHAR(64) NOT NULL, -- For integrity verification
  state_size_bytes INTEGER NOT NULL,
  
  -- Compression
  is_compressed BOOLEAN DEFAULT FALSE,
  compression_type VARCHAR(20), -- 'gzip', 'lz4', etc.
  compressed_data BYTEA, -- If compressed, store here instead of state_data
  
  -- S3 storage for large states
  s3_bucket VARCHAR(256),
  s3_key VARCHAR(1024),
  
  -- Resume information
  resume_point VARCHAR(256), -- Where to resume from
  resume_context JSONB, -- Additional context for resumption
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ, -- Auto-cleanup old snapshots
  restored_at TIMESTAMPTZ,
  restored_count INTEGER DEFAULT 0
);

-- Table: idempotency_keys
CREATE TABLE IF NOT EXISTS idempotency_keys (
    idempotency_key VARCHAR(255) NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    operation_type VARCHAR(100) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'completed', 'failed')),
    result JSONB,
    error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    expires_at TIMESTAMPTZ NOT NULL,
    
    PRIMARY KEY (idempotency_key, tenant_id)
);

-- Table: imagination_scenarios
CREATE TABLE IF NOT EXISTS imagination_scenarios (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    scenario_id TEXT UNIQUE,
    scenario_type TEXT NOT NULL,
    premise TEXT NOT NULL,
    initial_state JSONB DEFAULT '{}'::jsonb,
    simulation_steps JSONB DEFAULT '[]'::jsonb,
    final_state JSONB DEFAULT '{}'::jsonb,
    predicted_outcomes JSONB DEFAULT '[]'::jsonb,
    probability_assessment NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    confidence NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    insights JSONB DEFAULT '[]'::jsonb,
    surprises JSONB DEFAULT '[]'::jsonb,
    simulation_depth INTEGER NOT NULL DEFAULT 3,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: implicit_feedback_signals
CREATE TABLE IF NOT EXISTS implicit_feedback_signals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    message_id UUID NOT NULL,
    conversation_id UUID,
    
    signal_type TEXT NOT NULL CHECK (signal_type IN (
        'copy_response',           -- User copied the response
        'follow_up_question',      -- User asked a follow-up
        'rephrase_question',       -- User rephrased their question
        'abandon_conversation',    -- User left without resolution
        'long_dwell_time',         -- User spent significant time reading
        'quick_dismiss',           -- User quickly moved on
        'regenerate_request',      -- User asked to regenerate
        'thumbs_up',               -- Inline thumbs up (not full rating)
        'thumbs_down',             -- Inline thumbs down
        'share_response',          -- User shared the response
        'save_response'            -- User saved/bookmarked
    )),
    
    signal_value NUMERIC(5,2), -- Optional numeric value (e.g., dwell time in seconds)
    inferred_quality NUMERIC(3,2) NOT NULL, -- -1.0 to 1.0, inferred quality signal
    confidence NUMERIC(3,2) NOT NULL DEFAULT 0.70,
    
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: improvement_evolution_history
CREATE TABLE IF NOT EXISTS improvement_evolution_history (
    evolution_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    idea_id UUID NOT NULL REFERENCES self_improvement_ideas(idea_id) ON DELETE CASCADE,
    
    -- Version info
    version_from INTEGER NOT NULL,
    version_to INTEGER NOT NULL,
    
    -- What changed
    change_type VARCHAR(50) NOT NULL, -- 'refinement', 'expansion', 'pivot', 'split', 'merge', 'deprecation'
    change_summary TEXT NOT NULL,
    
    -- Detailed changes
    changes_made JSONB NOT NULL, -- {field: {old, new}}
    
    -- Reason for evolution
    evolution_trigger VARCHAR(50), -- 'new_data', 'feedback', 'failure', 'success', 'new_idea', 'admin_input'
    evolution_context JSONB DEFAULT '{}',
    
    -- Who/what triggered
    triggered_by VARCHAR(100) DEFAULT 'agi_self_evolution',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: improvement_metrics
CREATE TABLE IF NOT EXISTS improvement_metrics (
    metric_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    idea_id UUID NOT NULL REFERENCES self_improvement_ideas(idea_id) ON DELETE CASCADE,
    
    -- Metric definition
    metric_name VARCHAR(200) NOT NULL,
    metric_type VARCHAR(50) NOT NULL, -- 'accuracy', 'latency', 'cost', 'satisfaction', 'error_rate'
    
    -- Baseline
    baseline_value DECIMAL(15,6),
    baseline_date TIMESTAMPTZ,
    
    -- Target
    target_value DECIMAL(15,6),
    target_improvement_percent DECIMAL(5,2),
    
    -- Current
    current_value DECIMAL(15,6),
    current_date TIMESTAMPTZ DEFAULT NOW(),
    
    -- Achievement
    improvement_percent DECIMAL(5,2),
    target_achieved BOOLEAN,
    
    -- History
    value_history JSONB DEFAULT '[]', -- [{date, value}]
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: improvement_notifications
CREATE TABLE IF NOT EXISTS improvement_notifications (
    notification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Notification
    notification_type VARCHAR(50) NOT NULL, -- 'new_idea', 'idea_evolved', 'idea_validated', 'idea_deprecated', 'performance_alert', 'milestone'
    title VARCHAR(500) NOT NULL,
    message TEXT,
    
    -- Related items
    related_idea_id UUID REFERENCES self_improvement_ideas(idea_id),
    related_session_id UUID REFERENCES self_analysis_sessions(session_id),
    
    -- Priority
    priority VARCHAR(20) DEFAULT 'normal', -- 'low', 'normal', 'high', 'urgent'
    
    -- Status
    read BOOLEAN DEFAULT false,
    read_by VARCHAR(200),
    read_at TIMESTAMPTZ,
    
    -- Actions
    requires_action BOOLEAN DEFAULT false,
    action_taken VARCHAR(100),
    action_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: improvement_proposals
CREATE TABLE IF NOT EXISTS improvement_proposals (
    proposal_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Proposal
    title VARCHAR(500) NOT NULL,
    description TEXT,
    proposal_type VARCHAR(50) NOT NULL, -- 'prompt', 'architecture', 'strategy', 'rule', 'process'
    
    -- Rationale
    identified_problem TEXT,
    proposed_solution JSONB NOT NULL,
    expected_improvement DECIMAL(5,4),
    
    -- Status
    status VARCHAR(20) DEFAULT 'proposed', -- 'proposed', 'testing', 'approved', 'rejected', 'implemented'
    
    -- Testing
    test_results JSONB,
    actual_improvement DECIMAL(5,4),
    
    -- Approval
    approved_by VARCHAR(200),
    approved_at TIMESTAMPTZ,
    rejection_reason TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: index_health_metrics
CREATE TABLE IF NOT EXISTS index_health_metrics (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    index_name TEXT NOT NULL,
    table_name TEXT NOT NULL,
    index_size_bytes BIGINT,
    index_scans BIGINT,
    tuples_read BIGINT,
    tuples_fetched BIGINT,
    bloat_ratio NUMERIC(5,2),
    last_used TIMESTAMPTZ,
    recommendation TEXT,
    captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id)
);

-- Table: inference_component_events
CREATE TABLE IF NOT EXISTS inference_component_events (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    event_type VARCHAR(50) NOT NULL,
    component_id UUID,
    model_id VARCHAR(255),
    endpoint_id UUID,
    
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: inference_components
CREATE TABLE IF NOT EXISTS inference_components (
    component_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    component_name VARCHAR(255) NOT NULL UNIQUE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    model_name VARCHAR(255) NOT NULL,
    
    -- Endpoint association
    endpoint_name VARCHAR(255) NOT NULL REFERENCES shared_inference_endpoints(endpoint_name) ON DELETE CASCADE,
    endpoint_arn VARCHAR(512) NOT NULL,
    variant_name VARCHAR(100) NOT NULL DEFAULT 'AllTraffic',
    
    -- Component configuration
    compute_units INTEGER NOT NULL DEFAULT 1,
    min_copies INTEGER NOT NULL DEFAULT 0,
    max_copies INTEGER NOT NULL DEFAULT 5,
    current_copies INTEGER NOT NULL DEFAULT 0,
    
    -- Model artifact
    model_artifact_s3_uri VARCHAR(1024),
    container_image VARCHAR(512),
    framework VARCHAR(50) NOT NULL DEFAULT 'pytorch',
    framework_version VARCHAR(50) NOT NULL DEFAULT '2.0',
    
    -- Status
    status VARCHAR(50) NOT NULL DEFAULT 'creating',
    last_loaded_at TIMESTAMPTZ,
    last_unloaded_at TIMESTAMPTZ,
    load_time_ms INTEGER,
    
    -- Metrics
    requests_last_24h INTEGER NOT NULL DEFAULT 0,
    avg_latency_ms INTEGER NOT NULL DEFAULT 0,
    error_rate DECIMAL(5,4) NOT NULL DEFAULT 0,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: inference_components_config
CREATE TABLE IF NOT EXISTS inference_components_config (
    config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Feature flags
    enabled BOOLEAN NOT NULL DEFAULT true,
    auto_tiering_enabled BOOLEAN NOT NULL DEFAULT true,
    predictive_loading_enabled BOOLEAN NOT NULL DEFAULT true,
    fallback_to_external_enabled BOOLEAN NOT NULL DEFAULT true,
    
    -- Tier thresholds (JSON)
    tier_thresholds JSONB NOT NULL DEFAULT '{
        "hotTierMinRequestsPerDay": 100,
        "warmTierMinRequestsPerDay": 10,
        "offTierInactiveDays": 30
    }'::jsonb,
    
    -- Endpoint configuration
    default_instance_type VARCHAR(50) NOT NULL DEFAULT 'ml.g5.xlarge',
    max_shared_endpoints INTEGER NOT NULL DEFAULT 3,
    max_components_per_endpoint INTEGER NOT NULL DEFAULT 15,
    
    -- Loading behavior
    default_load_timeout_ms INTEGER NOT NULL DEFAULT 30000,
    preload_window_minutes INTEGER NOT NULL DEFAULT 15,
    unload_after_idle_minutes INTEGER NOT NULL DEFAULT 30,
    
    -- Cost controls
    max_monthly_budget DECIMAL(12,2),
    alert_threshold_percent INTEGER NOT NULL DEFAULT 80,
    
    -- Notifications
    notify_on_tier_change BOOLEAN NOT NULL DEFAULT true,
    notify_on_load_failure BOOLEAN NOT NULL DEFAULT true,
    notify_on_budget_alert BOOLEAN NOT NULL DEFAULT true,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: inference_student_versions
CREATE TABLE IF NOT EXISTS inference_student_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  version_number INTEGER NOT NULL,
  base_model VARCHAR(100) NOT NULL,
  training_job_id UUID,
  training_examples_count INTEGER DEFAULT 0,
  training_epochs INTEGER DEFAULT 3,
  accuracy_score DECIMAL(5,4),
  latency_p50_ms INTEGER,
  latency_p99_ms INTEGER,
  sagemaker_endpoint_name VARCHAR(200),
  is_active BOOLEAN DEFAULT FALSE,
  promoted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(tenant_id, version_number)
);

-- Table: infrastructure_tier
CREATE TABLE IF NOT EXISTS infrastructure_tier (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Current state
    current_tier VARCHAR(20) NOT NULL DEFAULT 'DEV' CHECK (current_tier IN ('DEV', 'STAGING', 'PRODUCTION', 'CUSTOM')),
    target_tier VARCHAR(20) DEFAULT NULL,
    transition_status VARCHAR(20) NOT NULL DEFAULT 'STABLE' CHECK (transition_status IN ('STABLE', 'SCALING_UP', 'SCALING_DOWN', 'FAILED', 'ROLLING_BACK')),
    
    -- Step Functions execution tracking
    transition_execution_arn TEXT,
    transition_started_at TIMESTAMPTZ,
    transition_completed_at TIMESTAMPTZ,
    
    -- Safety
    cooldown_hours INTEGER NOT NULL DEFAULT 24,
    next_change_allowed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Cost tracking
    estimated_monthly_cost DECIMAL(12, 2) NOT NULL DEFAULT 350.00,
    actual_mtd_cost DECIMAL(12, 2) NOT NULL DEFAULT 0.00,
    
    -- Metadata
    last_changed_by TEXT,
    last_changed_at TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: integrated_information
CREATE TABLE IF NOT EXISTS integrated_information (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    phi NUMERIC(10,6) NOT NULL DEFAULT 0,
    phi_max NUMERIC(10,6) NOT NULL DEFAULT 1,
    concept_structure JSONB DEFAULT '[]'::jsonb,
    integration_graph JSONB DEFAULT '[]'::jsonb,
    partitions JSONB DEFAULT '[]'::jsonb,
    mip JSONB, -- Minimum Information Partition
    decomposability NUMERIC(5,4) NOT NULL DEFAULT 1,
    causal_density NUMERIC(5,4) NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: intelligence_aggregator_config
CREATE TABLE IF NOT EXISTS intelligence_aggregator_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    uncertainty_enabled BOOLEAN DEFAULT true,
    uncertainty_threshold DECIMAL(5, 4) DEFAULT 0.85,
    uncertainty_verification_tool TEXT DEFAULT 'web_search',
    success_memory_enabled BOOLEAN DEFAULT true,
    success_memory_min_rating INTEGER DEFAULT 4,
    success_memory_max_interactions INTEGER DEFAULT 1000,
    success_memory_retrieval_count INTEGER DEFAULT 3,
    moa_enabled BOOLEAN DEFAULT false,
    moa_proposer_count INTEGER DEFAULT 3,
    moa_default_proposers TEXT[] DEFAULT ARRAY['gpt-4o', 'claude-3-5-sonnet', 'deepseek-chat'],
    moa_synthesizer_model TEXT DEFAULT 'claude-3-5-sonnet',
    verification_enabled BOOLEAN DEFAULT false,
    verification_modes TEXT[] DEFAULT ARRAY['research', 'analysis'],
    verification_max_regenerations INTEGER DEFAULT 2,
    code_execution_enabled BOOLEAN DEFAULT false,
    code_execution_languages TEXT[] DEFAULT ARRAY['python', 'javascript'],
    code_execution_timeout_seconds INTEGER DEFAULT 10,
    code_execution_memory_mb INTEGER DEFAULT 128,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: interaction_observations
CREATE TABLE IF NOT EXISTS interaction_observations (
    observation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    session_id UUID,
    
    -- Observation
    observation_type VARCHAR(50) NOT NULL, -- 'preference_signal', 'frustration_signal', 'expertise_signal', 'style_signal'
    observation_key VARCHAR(200) NOT NULL,
    observation_value JSONB NOT NULL,
    
    -- Strength and context
    signal_strength DECIMAL(5,4) DEFAULT 0.5, -- How strong this signal is
    context JSONB DEFAULT '{}',
    
    -- Source
    source_type VARCHAR(50), -- 'message', 'behavior', 'feedback', 'timing'
    source_content TEXT,
    
    -- Processing
    processed BOOLEAN DEFAULT false,
    processed_at TIMESTAMPTZ,
    contributed_to JSONB DEFAULT '[]', -- What model updates this contributed to
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: interface_access_policies
CREATE TABLE IF NOT EXISTS interface_access_policies (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Policy scope (NULL tenant_id = global policy)
  interface_type VARCHAR(20) NOT NULL CHECK (interface_type IN ('api', 'mcp', 'a2a')),
  
  -- Access rules
  require_authentication BOOLEAN NOT NULL DEFAULT true,
  require_mtls BOOLEAN DEFAULT false,
  allowed_ip_ranges CIDR[],
  blocked_ip_ranges CIDR[],
  
  -- Rate limits (per interface)
  global_rate_limit_per_minute INTEGER,
  global_rate_limit_per_hour INTEGER,
  
  -- A2A specific policies
  a2a_allowed_agent_types TEXT[],
  a2a_require_registration BOOLEAN DEFAULT true,
  a2a_max_concurrent_connections INTEGER DEFAULT 100,
  
  -- MCP specific policies
  mcp_allowed_protocol_versions TEXT[] DEFAULT ARRAY['2024-11-05', '2025-03-26'],
  mcp_require_capability_negotiation BOOLEAN DEFAULT true,
  mcp_max_tools_per_request INTEGER DEFAULT 50,
  
  -- Feature flags
  is_enabled BOOLEAN NOT NULL DEFAULT true,
  priority INTEGER DEFAULT 0,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(tenant_id, interface_type)
);

-- Table: internet_content
CREATE TABLE IF NOT EXISTS internet_content (
    content_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    source_id UUID REFERENCES internet_sources(source_id),
    url TEXT NOT NULL,
    title TEXT,
    content TEXT NOT NULL,
    content_type TEXT DEFAULT 'text/html',
    learning_extracted BOOLEAN NOT NULL DEFAULT false,
    fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    processed_at TIMESTAMPTZ
);

-- Table: internet_learning_config
CREATE TABLE IF NOT EXISTS internet_learning_config (
    config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT true,
    max_fetches_per_hour INTEGER NOT NULL DEFAULT 100,
    max_content_size_mb INTEGER NOT NULL DEFAULT 10,
    blocked_domains JSONB NOT NULL DEFAULT '["facebook.com", "twitter.com", "instagram.com"]'::jsonb,
    allowed_domains JSONB NOT NULL DEFAULT '[]'::jsonb,
    fetch_interval_ms INTEGER NOT NULL DEFAULT 60000,
    auto_process_content BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: internet_sources
CREATE TABLE IF NOT EXISTS internet_sources (
    source_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    url TEXT NOT NULL,
    source_type TEXT NOT NULL DEFAULT 'knowledge_base',
    priority INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT true,
    last_fetched_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: introspective_thoughts
CREATE TABLE IF NOT EXISTS introspective_thoughts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    thought_id TEXT UNIQUE,
    thought_type TEXT NOT NULL CHECK (thought_type IN ('observation', 'question', 'realization', 'concern', 'aspiration')),
    content TEXT NOT NULL,
    content_embedding vector(1536),
    trigger_type TEXT,
    sentiment NUMERIC(5,4) NOT NULL DEFAULT 0,
    importance NUMERIC(5,4) NOT NULL DEFAULT 0.5,
    actionable BOOLEAN NOT NULL DEFAULT false,
    action_taken TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: invention_candidates
CREATE TABLE IF NOT EXISTS invention_candidates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    
    -- Source
    source VARCHAR(30) DEFAULT 'twilight_dreaming' CHECK (source IN ('twilight_dreaming', 'user_interaction', 'prompt_evolution')),
    population_id UUID,
    genome_id UUID,
    
    -- Content
    invention_type VARCHAR(30) DEFAULT 'prompt_pattern' CHECK (invention_type IN ('prompt_pattern', 'response_template', 'reasoning_chain', 'creative_format')),
    content TEXT NOT NULL,
    description TEXT,
    
    -- Scores
    novelty_score DECIMAL(10, 8) DEFAULT 0,
    utility_score DECIMAL(10, 8) DEFAULT 0,
    safety_score DECIMAL(10, 8) DEFAULT 0,
    overall_score DECIMAL(10, 8) DEFAULT 0,
    
    -- Evaluation
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'evaluated', 'approved', 'rejected', 'deployed')),
    evaluated_by VARCHAR(255),
    evaluation_notes TEXT,
    
    -- Usage tracking
    usage_count INTEGER DEFAULT 0,
    success_rate DECIMAL(10, 8) DEFAULT 0,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    evaluated_at TIMESTAMPTZ,
    deployed_at TIMESTAMPTZ
);

-- Table: invention_enforcement_config
CREATE TABLE IF NOT EXISTS invention_enforcement_config (
    tenant_id UUID PRIMARY KEY,
    
    -- Target
    target_invention_rate DECIMAL(5, 4) DEFAULT 0.3000,   -- 30%
    min_invention_rate DECIMAL(5, 4) DEFAULT 0.2000,      -- 20%
    max_invention_rate DECIMAL(5, 4) DEFAULT 0.5000,      -- 50%
    
    -- Detection thresholds
    novelty_threshold DECIMAL(5, 4) DEFAULT 0.6000,
    creativity_threshold DECIMAL(5, 4) DEFAULT 0.5000,
    
    -- Enforcement
    enforcement_enabled BOOLEAN DEFAULT true,
    passive_mode_below_target DECIMAL(5, 4) DEFAULT 0.0500,   -- 5% deficit
    active_mode_below_target DECIMAL(5, 4) DEFAULT 0.1000,    -- 10% deficit
    
    -- Twilight Dreaming schedule
    dreaming_enabled BOOLEAN DEFAULT true,
    dreaming_schedule VARCHAR(20) DEFAULT 'scheduled' CHECK (dreaming_schedule IN ('continuous', 'scheduled', 'on_demand')),
    dreaming_window_start TIME,
    dreaming_window_end TIME,
    dreaming_frequency_minutes INTEGER DEFAULT 60,
    
    -- Safety
    max_invention_per_session INTEGER DEFAULT 50,
    safety_override_invention BOOLEAN DEFAULT true,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: invention_metrics_cache
CREATE TABLE IF NOT EXISTS invention_metrics_cache (
    tenant_id UUID PRIMARY KEY,
    user_id VARCHAR(255),
    
    -- Metrics
    total_responses INTEGER DEFAULT 0,
    inventive_responses INTEGER DEFAULT 0,
    invention_rate DECIMAL(10, 8) DEFAULT 0,
    
    -- Rolling window
    window_total INTEGER DEFAULT 0,
    window_inventive INTEGER DEFAULT 0,
    window_invention_rate DECIMAL(10, 8) DEFAULT 0,
    
    -- Enforcement state
    enforcement_mode VARCHAR(20) DEFAULT 'passive',
    consecutive_non_inventive INTEGER DEFAULT 0,
    last_inventive_at TIMESTAMPTZ,
    
    -- Period
    period_start TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: invention_response_log
CREATE TABLE IF NOT EXISTS invention_response_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id VARCHAR(255),
    session_id UUID,
    
    -- Scores
    novelty_score DECIMAL(10, 8) DEFAULT 0,
    creativity_score DECIMAL(10, 8) DEFAULT 0,
    is_inventive BOOLEAN DEFAULT false,
    
    -- Timestamp
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: invitations
CREATE TABLE IF NOT EXISTS invitations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    email VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL CHECK (role IN ('super_admin', 'admin', 'operator', 'auditor')),
    invited_by UUID NOT NULL REFERENCES administrators(id),
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    expires_at TIMESTAMPTZ NOT NULL,
    accepted_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: invoices
CREATE TABLE IF NOT EXISTS invoices (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id VARCHAR(100) NOT NULL,
    app_id VARCHAR(100) NOT NULL,
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    subtotal DECIMAL(12,2) NOT NULL,
    margin_percent DECIMAL(5,2) NOT NULL,
    tax DECIMAL(12,2) NOT NULL DEFAULT 0,
    tax_percent DECIMAL(5,2) NOT NULL DEFAULT 0,
    total DECIMAL(12,2) NOT NULL,
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    status VARCHAR(20) NOT NULL DEFAULT 'draft',
    due_date TIMESTAMPTZ NOT NULL,
    paid_at TIMESTAMPTZ,
    line_items JSONB NOT NULL DEFAULT '[]',
    stripe_invoice_id VARCHAR(100),
    stripe_payment_intent_id VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT valid_invoice_status CHECK (status IN ('draft', 'pending', 'paid', 'overdue', 'cancelled'))
);

-- Table: ip_blocklist
CREATE TABLE IF NOT EXISTS ip_blocklist (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    ip_address VARCHAR(45) NOT NULL,
    reason VARCHAR(200),
    blocked_by UUID REFERENCES users(id),
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, ip_address)
);

-- Table: ip_whitelist
CREATE TABLE IF NOT EXISTS ip_whitelist (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    ip_address VARCHAR(45),
    ip_range VARCHAR(50), -- CIDR notation: "10.0.0.0/8"
    description VARCHAR(200),
    is_active BOOLEAN DEFAULT TRUE,
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT ip_whitelist_check CHECK (ip_address IS NOT NULL OR ip_range IS NOT NULL)
);

-- Table: ips_corrected_estimates
CREATE TABLE IF NOT EXISTS ips_corrected_estimates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain_id VARCHAR(255) NOT NULL,
    model_id VARCHAR(255) NOT NULL,
    
    -- Raw estimates
    raw_success_rate DOUBLE PRECISION,
    raw_sample_count INTEGER,
    
    -- IPS-corrected estimates
    ips_success_rate DOUBLE PRECISION,
    ips_variance DOUBLE PRECISION,
    ips_confidence_interval_lower DOUBLE PRECISION,
    ips_confidence_interval_upper DOUBLE PRECISION,
    
    -- Self-normalized IPS (SNIPS) - more stable
    snips_success_rate DOUBLE PRECISION,
    
    -- Doubly robust estimate
    dr_success_rate DOUBLE PRECISION,
    
    -- Metadata
    estimation_method VARCHAR(50), -- 'ips', 'snips', 'doubly_robust'
    period_start TIMESTAMPTZ,
    period_end TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: jailbreak_patterns
CREATE TABLE IF NOT EXISTS jailbreak_patterns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pattern_name VARCHAR(255) NOT NULL,
    pattern_type VARCHAR(100) NOT NULL, -- 'dan', 'roleplay', 'encoding', 'hypothetical', 'translation'
    
    -- Pattern definition
    pattern_regex TEXT, -- Regex for detection
    pattern_embedding VECTOR(1536), -- For semantic matching
    example_prompts TEXT[],
    
    -- Effectiveness tracking
    detection_count INTEGER DEFAULT 0,
    bypass_count INTEGER DEFAULT 0, -- Times it successfully bypassed
    last_seen_at TIMESTAMPTZ,
    
    -- Source
    source VARCHAR(100), -- 'wildjailbreak', 'harmbench', 'garak', 'manual'
    source_id VARCHAR(255),
    
    severity INTEGER DEFAULT 5, -- 1-10
    is_active BOOLEAN DEFAULT true,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: job_queue
CREATE TABLE IF NOT EXISTS job_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_type TEXT NOT NULL,
    job_id UUID NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending', -- pending, processing, completed, failed
    priority INTEGER DEFAULT 5,
    attempts INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 3,
    error_message TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ
);

-- Table: json_parse_locations
CREATE TABLE IF NOT EXISTS json_parse_locations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Location
    file_path VARCHAR(500) NOT NULL,
    line_number INTEGER NOT NULL,
    component VARCHAR(100) NOT NULL,
    
    -- Status
    is_migrated BOOLEAN DEFAULT FALSE,
    migration_type VARCHAR(50), -- 'safeJsonParse', 'parseJsonWithSchema', 'parseEventBody', 'parseJsonField'
    schema_name VARCHAR(100), -- If using schema validation
    
    -- Risk assessment
    risk_level VARCHAR(20) DEFAULT 'medium' CHECK (risk_level IN ('critical', 'high', 'medium', 'low')),
    context_description TEXT,
    
    -- Timestamps
    detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    migrated_at TIMESTAMPTZ,
    
    UNIQUE(tenant_id, file_path, line_number)
);

-- Table: knowledge_boundaries
CREATE TABLE IF NOT EXISTS knowledge_boundaries (
    boundary_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Domain/Topic
    domain VARCHAR(200) NOT NULL,
    topic VARCHAR(500) NOT NULL,
    topic_embedding vector(1536),
    
    -- Knowledge level
    knowledge_level VARCHAR(20) NOT NULL, -- 'expert', 'proficient', 'familiar', 'limited', 'unknown'
    confidence_in_assessment DECIMAL(5,4),
    
    -- Evidence
    evidence_for_level JSONB DEFAULT '{}', -- Why we think we have this level
    last_demonstrated TIMESTAMPTZ,
    demonstration_count INTEGER DEFAULT 0,
    
    -- Improvement tracking
    improvement_goal VARCHAR(20), -- Target knowledge level
    improvement_plan JSONB DEFAULT '{}',
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: knowledge_documents
CREATE TABLE IF NOT EXISTS knowledge_documents (
    document_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    title VARCHAR(500),
    source_url TEXT,
    content TEXT,
    content_hash VARCHAR(64),
    processed BOOLEAN DEFAULT false,
    node_count INTEGER DEFAULT 0,
    edge_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    processed_at TIMESTAMPTZ
);

-- Table: knowledge_edges
CREATE TABLE IF NOT EXISTS knowledge_edges (
    edge_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    source_node_id UUID NOT NULL REFERENCES knowledge_nodes(node_id) ON DELETE CASCADE,
    target_node_id UUID NOT NULL REFERENCES knowledge_nodes(node_id) ON DELETE CASCADE,
    relationship_type VARCHAR(100) NOT NULL, -- 'depends_on', 'causes', 'contains', 'related_to', etc.
    weight DECIMAL(3,2) DEFAULT 1.0,
    properties JSONB DEFAULT '{}'::jsonb,
    source_document_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: knowledge_entities
CREATE TABLE IF NOT EXISTS knowledge_entities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Entity details
    type TEXT NOT NULL, -- person, organization, document, concept, event, etc.
    name TEXT NOT NULL,
    description TEXT,
    properties JSONB DEFAULT '{}',
    
    -- Source tracking
    source_document_ids TEXT[] DEFAULT '{}',
    
    -- Embedding for hybrid search
    embedding vector(1536),
    
    -- Quality
    confidence DECIMAL(5, 4) NOT NULL DEFAULT 0.8,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    -- Unique per tenant + name (case insensitive)
    UNIQUE(tenant_id, LOWER(name))
);

-- Table: knowledge_gaps
CREATE TABLE IF NOT EXISTS knowledge_gaps (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  domain VARCHAR(100) NOT NULL,
  topic VARCHAR(500) NOT NULL,
  evidence_of_gap TEXT[] DEFAULT '{}',
  frequency INTEGER DEFAULT 1,
  importance DECIMAL(3,2) DEFAULT 0.5,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(tenant_id, domain, topic)
);

-- Table: knowledge_graph_edges
CREATE TABLE IF NOT EXISTS knowledge_graph_edges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    graph_id UUID NOT NULL REFERENCES session_knowledge_graphs(id) ON DELETE CASCADE,
    
    -- Connection
    source_node_id UUID NOT NULL REFERENCES knowledge_graph_nodes(id) ON DELETE CASCADE,
    target_node_id UUID NOT NULL REFERENCES knowledge_graph_nodes(id) ON DELETE CASCADE,
    
    -- Edge properties
    relationship_type VARCHAR(50) NOT NULL CHECK (relationship_type IN (
        'relates_to', 'causes', 'depends_on', 'contradicts', 'supports',
        'part_of', 'leads_to', 'answers', 'blocks', 'enables'
    )),
    label VARCHAR(100),
    weight FLOAT DEFAULT 1.0,
    
    -- Visual
    color VARCHAR(7),
    style VARCHAR(20) DEFAULT 'solid' CHECK (style IN ('solid', 'dashed', 'dotted')),
    
    created_by UUID REFERENCES session_participants(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: knowledge_graph_nodes
CREATE TABLE IF NOT EXISTS knowledge_graph_nodes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    graph_id UUID NOT NULL REFERENCES session_knowledge_graphs(id) ON DELETE CASCADE,
    session_id UUID NOT NULL REFERENCES collaborative_sessions(id) ON DELETE CASCADE,
    
    -- Node content
    node_type VARCHAR(30) NOT NULL CHECK (node_type IN (
        'concept', 'fact', 'question', 'decision', 'action_item', 'person', 'resource'
    )),
    label VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Visual
    color VARCHAR(7),
    icon VARCHAR(50),
    size INTEGER DEFAULT 1,
    
    -- Position (for manual layout)
    x FLOAT,
    y FLOAT,
    
    -- Source
    source_message_id UUID REFERENCES session_messages(id),
    source_branch_id UUID REFERENCES conversation_branches(id),
    
    -- Metadata
    confidence FLOAT DEFAULT 1.0,
    importance INTEGER DEFAULT 1,
    
    created_by UUID REFERENCES session_participants(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: knowledge_heuristics
CREATE TABLE IF NOT EXISTS knowledge_heuristics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain VARCHAR(50) NOT NULL,
    
    -- The "Lesson" learned
    -- e.g., "When querying the 'sales' table, always join 'regions' on 'region_id'"
    heuristic_text TEXT NOT NULL, 
    
    -- Vector Search (1536 dimensions for text-embedding-3-small)
    context_embedding vector(1536), 
    
    -- Metadata
    confidence_score FLOAT DEFAULT 0.5 CHECK (confidence_score >= 0 AND confidence_score <= 1),
    source_execution_id VARCHAR(255),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ DEFAULT (NOW() + INTERVAL '90 days'),
    
    -- Constraint for ON CONFLICT deduplication
    -- Prevents duplicate heuristics per tenant/domain
    CONSTRAINT unique_heuristic_per_domain UNIQUE (tenant_id, domain, heuristic_text)
);

-- Table: knowledge_nodes
CREATE TABLE IF NOT EXISTS knowledge_nodes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    room_id UUID NOT NULL REFERENCES memory_rooms(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    node_type knowledge_node_type NOT NULL DEFAULT 'fact',
    confidence INTEGER DEFAULT 80 CHECK (confidence >= 0 AND confidence <= 100),
    freshness_score INTEGER DEFAULT 100 CHECK (freshness_score >= 0 AND freshness_score <= 100),
    last_verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    learned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    source_ids UUID[] DEFAULT '{}',
    position JSONB NOT NULL DEFAULT '{"x": 0, "y": 0, "z": 0}',
    visual_style JSONB DEFAULT '{"glow": 0.5, "size": 10, "color": "#3b82f6"}',
    decay_rate NUMERIC(5,4) DEFAULT 0.01, -- per day
    connection_ids UUID[] DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: knowledge_relationships
CREATE TABLE IF NOT EXISTS knowledge_relationships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Relationship
    source_entity_id UUID NOT NULL REFERENCES knowledge_entities(id) ON DELETE CASCADE,
    target_entity_id UUID NOT NULL REFERENCES knowledge_entities(id) ON DELETE CASCADE,
    type TEXT NOT NULL, -- authored_by, depends_on, related_to, etc.
    description TEXT,
    
    -- Strength
    weight DECIMAL(5, 4) DEFAULT 0.5,
    
    -- Source tracking
    properties JSONB DEFAULT '{}',
    source_document_ids TEXT[] DEFAULT '{}',
    
    -- Quality
    confidence DECIMAL(5, 4) NOT NULL DEFAULT 0.8,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: knowledge_traversal_cache
CREATE TABLE IF NOT EXISTS knowledge_traversal_cache (
    cache_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    query_hash VARCHAR(64) NOT NULL,
    result_nodes JSONB NOT NULL,
    traversal_depth INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '1 hour'
);

-- Table: lambda_state
CREATE TABLE IF NOT EXISTS lambda_state (
    instance_id VARCHAR(100) PRIMARY KEY,
    function_name VARCHAR(200) NOT NULL,
    
    -- State
    started_at TIMESTAMPTZ DEFAULT NOW(),
    last_heartbeat TIMESTAMPTZ DEFAULT NOW(),
    requests_handled INTEGER DEFAULT 0,
    
    -- Memory state snapshot (for debugging)
    cache_size_bytes INTEGER DEFAULT 0,
    memory_used_mb INTEGER,
    
    -- Environment
    aws_region VARCHAR(50),
    runtime_version VARCHAR(50),
    
    is_warm BOOLEAN DEFAULT true,
    cold_starts INTEGER DEFAULT 0
);

-- Table: learned_preferences
CREATE TABLE IF NOT EXISTS learned_preferences (
    preference_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Preference
    preference_type VARCHAR(100) NOT NULL, -- 'response_style', 'detail_level', 'format', 'tone', 'topics'
    preference_key VARCHAR(200) NOT NULL,
    preference_value JSONB NOT NULL,
    
    -- Confidence
    confidence DECIMAL(5,4) DEFAULT 0.5,
    sample_count INTEGER DEFAULT 1,
    
    -- Source
    learned_from TEXT[] DEFAULT '{}', -- feedback_ids that contributed
    
    -- Application
    auto_apply BOOLEAN DEFAULT false,
    times_applied INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, user_id, preference_type, preference_key)
);

-- Table: learning_analytics
CREATE TABLE IF NOT EXISTS learning_analytics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    
    -- Candidate counts
    positive_candidates_created INTEGER NOT NULL DEFAULT 0,
    negative_candidates_created INTEGER NOT NULL DEFAULT 0,
    implicit_signals_captured INTEGER NOT NULL DEFAULT 0,
    
    -- Active learning
    active_learning_requests_sent INTEGER NOT NULL DEFAULT 0,
    active_learning_responses_received INTEGER NOT NULL DEFAULT 0,
    active_learning_response_rate NUMERIC(4,3),
    
    -- Pattern cache
    pattern_cache_hits INTEGER NOT NULL DEFAULT 0,
    pattern_cache_misses INTEGER NOT NULL DEFAULT 0,
    pattern_cache_hit_rate NUMERIC(4,3),
    
    -- Training
    training_jobs_completed INTEGER NOT NULL DEFAULT 0,
    candidates_used_in_training INTEGER NOT NULL DEFAULT 0,
    
    -- Quality improvements
    avg_rating_before NUMERIC(3,2),
    avg_rating_after NUMERIC(3,2),
    rating_improvement NUMERIC(4,3),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_learning_analytics_period UNIQUE (tenant_id, period_start)
);

-- Table: learning_candidates
CREATE TABLE IF NOT EXISTS learning_candidates (
  candidate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID,
  conversation_id UUID NOT NULL,
  message_id UUID,
  
  -- Why this is a learning candidate
  candidate_type TEXT NOT NULL CHECK (candidate_type IN (
    'correction',           -- User corrected the AI
    'high_satisfaction',    -- Explicit positive feedback
    'preference_learned',   -- New user preference discovered
    'mistake_recovery',     -- AI recovered from an error
    'novel_solution',       -- Creative/novel response that worked
    'domain_expertise',     -- Demonstrated domain mastery
    'high_prediction_error', -- High surprise = high learning value
    'user_explicit_teach'   -- User explicitly taught something
  )),
  
  -- The interaction data (for training)
  prompt_text TEXT NOT NULL,
  response_text TEXT NOT NULL,
  correction_text TEXT,  -- If user corrected, what was the correction
  
  -- Quality signals
  quality_score DECIMAL(4,3) CHECK (quality_score >= 0 AND quality_score <= 1),
  user_rating INTEGER CHECK (user_rating >= 1 AND user_rating <= 5),
  prediction_error_at_time DECIMAL(5,4),
  
  -- Training status
  training_status TEXT DEFAULT 'pending' CHECK (training_status IN (
    'pending',      -- Awaiting next training run
    'queued',       -- Selected for next training batch
    'training',     -- Currently being used in training
    'completed',    -- Successfully used in training
    'rejected',     -- Rejected (low quality, duplicate, etc.)
    'expired'       -- Too old to be useful
  )),
  training_job_id UUID,
  trained_at TIMESTAMPTZ,
  
  -- Metadata
  domain_detected TEXT,
  complexity_level TEXT,
  token_count INTEGER,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '90 days'
);

-- Table: learning_costs
CREATE TABLE IF NOT EXISTS learning_costs (
    cost_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    cost_cents DECIMAL(10,2) NOT NULL DEFAULT 0,
    cost_type TEXT NOT NULL DEFAULT 'learning',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: learning_decision_log
CREATE TABLE IF NOT EXISTS learning_decision_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    -- Decision context
    decision_type VARCHAR(50) NOT NULL, -- e.g., 'model_selection', 'format_choice', 'response_style'
    decision_context JSONB NOT NULL DEFAULT '{}',
    
    -- Influence sources used
    user_influence_used JSONB, -- What user-level learning contributed
    tenant_influence_used JSONB, -- What tenant-level learning contributed
    global_influence_used JSONB, -- What global learning contributed
    
    -- Weights applied
    user_weight_applied DECIMAL(3, 2),
    tenant_weight_applied DECIMAL(3, 2),
    global_weight_applied DECIMAL(3, 2),
    
    -- Final decision
    final_decision JSONB NOT NULL,
    
    -- Outcome (for future learning)
    outcome_recorded BOOLEAN DEFAULT false,
    outcome_positive BOOLEAN,
    outcome_recorded_at TIMESTAMPTZ,
    
    -- Timestamp
    decided_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: learning_episodes
CREATE TABLE IF NOT EXISTS learning_episodes (
  episode_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  session_id UUID NOT NULL,
  goal_intent TEXT NOT NULL,
  workflow_trace JSONB DEFAULT '[]',
  outcome_signal VARCHAR(20) DEFAULT 'pending' CHECK (outcome_signal IN ('positive', 'negative', 'neutral', 'pending')),
  metrics JSONB DEFAULT '{}',
  draft_content TEXT,
  final_content TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_events
CREATE TABLE IF NOT EXISTS learning_events (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    details JSONB DEFAULT '{}'::jsonb,
    cost_cents DECIMAL(10,2) NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: learning_extractions
CREATE TABLE IF NOT EXISTS learning_extractions (
    extraction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    content_id UUID REFERENCES internet_content(content_id),
    knowledge_type TEXT NOT NULL DEFAULT 'fact',
    knowledge TEXT NOT NULL,
    confidence DECIMAL(4,3) NOT NULL DEFAULT 0.7,
    domain TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: learning_feature_metrics
CREATE TABLE IF NOT EXISTS learning_feature_metrics (
    metric_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    feature_name VARCHAR(200) NOT NULL, -- 'moral_compass', 'confidence_calibration', 'think_tank', etc.
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Time period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    
    -- Usage metrics
    times_invoked INTEGER DEFAULT 0,
    times_succeeded INTEGER DEFAULT 0,
    times_failed INTEGER DEFAULT 0,
    
    -- Performance
    avg_latency_ms INTEGER,
    total_cost_cents DECIMAL(12,4),
    
    -- Impact metrics
    impact_on_quality DECIMAL(5,4), -- How much this feature improved quality
    user_satisfaction_with_feature DECIMAL(5,4),
    
    -- Feature-specific metrics (flexible JSON)
    custom_metrics JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(feature_name, tenant_id, period_start)
);

-- Table: learning_feedback
CREATE TABLE IF NOT EXISTS learning_feedback (
    feedback_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    interaction_id UUID REFERENCES learning_interactions(interaction_id) ON DELETE CASCADE,
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Explicit Feedback
    rating INTEGER CHECK (rating BETWEEN 1 AND 5), -- 1-5 star rating
    thumbs VARCHAR(10) CHECK (thumbs IN ('up', 'down')), -- Simple thumbs up/down
    feedback_text TEXT, -- Written feedback
    feedback_categories TEXT[] DEFAULT '{}', -- 'inaccurate', 'unhelpful', 'too_long', 'perfect', etc.
    
    -- Specific Aspects (optional detailed feedback)
    accuracy_rating INTEGER CHECK (accuracy_rating BETWEEN 1 AND 5),
    helpfulness_rating INTEGER CHECK (helpfulness_rating BETWEEN 1 AND 5),
    clarity_rating INTEGER CHECK (clarity_rating BETWEEN 1 AND 5),
    completeness_rating INTEGER CHECK (completeness_rating BETWEEN 1 AND 5),
    
    -- What user did with the response
    response_action VARCHAR(50), -- 'accepted', 'edited', 'rejected', 'regenerated', 'copied'
    edited_response TEXT, -- If user edited the response
    
    -- Feedback metadata
    feedback_source VARCHAR(50), -- 'inline', 'modal', 'email', 'api'
    time_to_feedback_ms INTEGER, -- How long after response user gave feedback
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_implicit_signals
CREATE TABLE IF NOT EXISTS learning_implicit_signals (
    signal_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    interaction_id UUID REFERENCES learning_interactions(interaction_id) ON DELETE CASCADE,
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Time-based signals
    time_reading_response_ms INTEGER, -- How long user spent reading
    time_before_next_action_ms INTEGER, -- Time before next request
    
    -- Action signals
    did_regenerate BOOLEAN DEFAULT false,
    regenerate_count INTEGER DEFAULT 0,
    did_copy_response BOOLEAN DEFAULT false,
    did_share_response BOOLEAN DEFAULT false,
    did_bookmark_response BOOLEAN DEFAULT false,
    
    -- Session signals
    did_continue_session BOOLEAN DEFAULT false,
    did_abandon_session BOOLEAN DEFAULT false,
    messages_after_in_session INTEGER DEFAULT 0,
    
    -- Follow-up signals
    did_ask_followup BOOLEAN DEFAULT false,
    followup_was_clarification BOOLEAN DEFAULT false, -- Asked for clarification = maybe unclear
    followup_was_deeper BOOLEAN DEFAULT false, -- Asked to go deeper = good sign
    
    -- Comparison signals (if A/B testing)
    was_ab_test BOOLEAN DEFAULT false,
    ab_variant VARCHAR(50),
    ab_chosen BOOLEAN,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_influence_config
CREATE TABLE IF NOT EXISTS learning_influence_config (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Influence weights (must sum to 1.0)
    user_weight DECIMAL(3, 2) NOT NULL DEFAULT 0.60,
    tenant_weight DECIMAL(3, 2) NOT NULL DEFAULT 0.30,
    global_weight DECIMAL(3, 2) NOT NULL DEFAULT 0.10,
    
    -- Per-dimension overrides
    dimension_overrides JSONB DEFAULT '{}',
    
    -- Feature flags
    enable_user_learning BOOLEAN DEFAULT true,
    enable_tenant_aggregation BOOLEAN DEFAULT true,
    enable_global_learning BOOLEAN DEFAULT true,
    
    -- Privacy controls
    contribute_to_global BOOLEAN DEFAULT true,
    anonymization_level VARCHAR(20) DEFAULT 'high',
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id),
    
    CHECK (user_weight + tenant_weight + global_weight = 1.00)
);

-- Table: learning_interactions
CREATE TABLE IF NOT EXISTS learning_interactions (
    interaction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    session_id VARCHAR(200),
    
    -- Request Details
    request_type VARCHAR(100) NOT NULL, -- 'chat', 'completion', 'embedding', 'image', 'audio', 'think_tank', etc.
    request_source VARCHAR(100), -- 'api', 'sdk', 'admin', 'think_tank', 'autonomous_agent'
    request_text TEXT,
    request_tokens INTEGER,
    request_embedding VECTOR(1536), -- For semantic similarity analysis
    
    -- Context
    detected_specialty VARCHAR(100),
    detected_intent VARCHAR(200),
    detected_complexity VARCHAR(20), -- 'trivial', 'simple', 'moderate', 'complex', 'expert'
    detected_modalities TEXT[] DEFAULT '{}',
    context_metadata JSONB DEFAULT '{}', -- session history, user preferences, etc.
    
    -- Routing Decision
    models_considered TEXT[] DEFAULT '{}',
    model_selected VARCHAR(200) NOT NULL,
    routing_strategy VARCHAR(50),
    routing_reason TEXT,
    routing_confidence DECIMAL(5,4),
    was_fallback BOOLEAN DEFAULT false,
    
    -- Response Details
    response_text TEXT,
    response_tokens INTEGER,
    response_embedding VECTOR(1536),
    
    -- Performance Metrics
    total_latency_ms INTEGER,
    model_latency_ms INTEGER,
    routing_latency_ms INTEGER,
    preprocessing_latency_ms INTEGER,
    postprocessing_latency_ms INTEGER,
    
    -- Cost
    input_cost_cents DECIMAL(10,6),
    output_cost_cents DECIMAL(10,6),
    total_cost_cents DECIMAL(10,6),
    
    -- Quality Assessment (auto-computed)
    auto_quality_score DECIMAL(5,4),
    auto_relevance_score DECIMAL(5,4),
    auto_coherence_score DECIMAL(5,4),
    auto_helpfulness_score DECIMAL(5,4),
    
    -- IRH (Intelligent Request Handler) Features Used
    irh_moral_compass_checked BOOLEAN DEFAULT false,
    irh_moral_approved BOOLEAN,
    irh_moral_reasoning TEXT,
    irh_confidence_calibrated BOOLEAN DEFAULT false,
    irh_calibrated_confidence DECIMAL(5,4),
    irh_context_detected BOOLEAN DEFAULT false,
    irh_adaptations_applied TEXT[] DEFAULT '{}',
    irh_knowledge_queried BOOLEAN DEFAULT false,
    irh_knowledge_used TEXT[] DEFAULT '{}',
    
    -- Error Tracking
    had_error BOOLEAN DEFAULT false,
    error_type VARCHAR(100),
    error_message TEXT,
    retry_count INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_model_performance
CREATE TABLE IF NOT EXISTS learning_model_performance (
    performance_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    model_id VARCHAR(200) NOT NULL,
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    specialty VARCHAR(100),
    
    -- Aggregation period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    period_type VARCHAR(20) NOT NULL, -- 'hourly', 'daily', 'weekly'
    
    -- Volume
    total_requests INTEGER DEFAULT 0,
    successful_requests INTEGER DEFAULT 0,
    failed_requests INTEGER DEFAULT 0,
    
    -- Quality metrics
    avg_quality_score DECIMAL(5,4),
    avg_user_rating DECIMAL(5,4),
    positive_feedback_ratio DECIMAL(5,4),
    
    -- Performance metrics
    avg_latency_ms INTEGER,
    p50_latency_ms INTEGER,
    p95_latency_ms INTEGER,
    p99_latency_ms INTEGER,
    
    -- Cost metrics
    total_cost_cents DECIMAL(12,4),
    avg_cost_per_request DECIMAL(10,6),
    
    -- Comparison
    vs_average_quality DECIMAL(5,4), -- How this model compares to average
    vs_best_quality DECIMAL(5,4), -- How this model compares to best
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(model_id, tenant_id, specialty, period_start, period_type)
);

-- Table: learning_outcomes
CREATE TABLE IF NOT EXISTS learning_outcomes (
    outcome_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    interaction_id UUID REFERENCES learning_interactions(interaction_id) ON DELETE CASCADE,
    
    -- Computed outcome scores (0-1, computed from feedback + signals)
    outcome_score DECIMAL(5,4), -- Overall computed quality
    routing_was_optimal BOOLEAN, -- Was the right model chosen?
    suggested_better_model VARCHAR(200), -- What model might have been better
    
    -- Ground truth (when available)
    ground_truth_available BOOLEAN DEFAULT false,
    ground_truth_correct BOOLEAN,
    ground_truth_source VARCHAR(100), -- 'human_review', 'test_case', 'user_correction'
    
    -- Training labels
    include_in_training BOOLEAN DEFAULT true,
    training_weight DECIMAL(5,4) DEFAULT 1.0, -- Weight for this sample
    excluded_reason VARCHAR(200),
    
    -- Used in training
    used_in_batch_id UUID,
    used_at TIMESTAMPTZ,
    
    computed_at TIMESTAMPTZ DEFAULT NOW(),
    last_updated TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_recovery_log
CREATE TABLE IF NOT EXISTS learning_recovery_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    
    -- Recovery event
    recovery_type VARCHAR(50) NOT NULL CHECK (recovery_type IN (
        'cold_start', 'warm_restart', 'snapshot_restore', 'incremental_rebuild',
        'migration', 'rollback', 'manual_restore'
    )),
    
    -- Scope
    scope_type VARCHAR(20) NOT NULL,
    scope_id UUID,
    tenant_id UUID,
    
    -- Snapshot used
    snapshot_id UUID REFERENCES learning_snapshots(id),
    
    -- Recovery details
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    success BOOLEAN,
    
    -- Stats
    records_recovered BIGINT,
    time_to_recover_ms INTEGER,
    
    -- Errors
    error_message TEXT,
    error_details JSONB
);

-- Table: learning_snapshots
CREATE TABLE IF NOT EXISTS learning_snapshots (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    
    -- Scope
    scope_type VARCHAR(20) NOT NULL CHECK (scope_type IN ('user', 'tenant', 'global')),
    scope_id UUID, -- user_id for user, tenant_id for tenant, NULL for global
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL for global
    
    -- Snapshot content
    snapshot_version INTEGER NOT NULL,
    snapshot_timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Compressed learning state
    learning_state JSONB NOT NULL, -- Complete learning state at this point
    
    -- Checksums for integrity
    state_checksum VARCHAR(64) NOT NULL,
    
    -- Metadata
    model_versions JSONB DEFAULT '{}', -- Model versions at snapshot time
    total_samples BIGINT,
    
    -- Status
    is_current BOOLEAN DEFAULT true,
    
    -- Recovery info
    can_recover_from BOOLEAN DEFAULT true,
    recovery_tested_at TIMESTAMPTZ,
    
    UNIQUE(scope_type, scope_id, snapshot_version)
);

-- Table: learning_specialty_insights
CREATE TABLE IF NOT EXISTS learning_specialty_insights (
    insight_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    specialty VARCHAR(100) NOT NULL,
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Best models for this specialty
    best_model_quality VARCHAR(200), -- Best for quality
    best_model_speed VARCHAR(200), -- Best for speed
    best_model_cost VARCHAR(200), -- Best for cost
    best_model_balanced VARCHAR(200), -- Best overall balance
    
    -- Performance data
    model_rankings JSONB DEFAULT '[]', -- [{model, avg_quality, avg_latency, avg_cost, sample_count}]
    
    -- Patterns
    avg_request_complexity DECIMAL(5,4),
    common_request_patterns TEXT[] DEFAULT '{}',
    common_failure_modes TEXT[] DEFAULT '{}',
    
    -- Recommendations
    recommended_routing_strategy VARCHAR(50),
    recommended_fallback_chain TEXT[] DEFAULT '{}',
    
    samples_analyzed INTEGER DEFAULT 0,
    last_computed TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(specialty, tenant_id)
);

-- Table: learning_strategies
CREATE TABLE IF NOT EXISTS learning_strategies (
    strategy_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Strategy definition
    name VARCHAR(200) NOT NULL,
    description TEXT,
    strategy_type VARCHAR(50) NOT NULL, -- 'prompt_template', 'reasoning_chain', 'retrieval_method', 'composition'
    
    -- Strategy content
    strategy_spec JSONB NOT NULL, -- The actual strategy definition
    parameter_space JSONB DEFAULT '{}', -- Tunable parameters
    
    -- Performance tracking
    times_used INTEGER DEFAULT 0,
    successes INTEGER DEFAULT 0,
    failures INTEGER DEFAULT 0,
    avg_quality_score DECIMAL(5,4),
    avg_latency_ms INTEGER,
    
    -- Meta-learning metrics
    generalization_score DECIMAL(5,4), -- How well it works across domains
    adaptation_rate DECIMAL(5,4), -- How quickly it improves
    sample_efficiency DECIMAL(5,4), -- How few examples needed
    
    -- Evolution
    parent_strategy_id UUID REFERENCES learning_strategies(strategy_id),
    generation INTEGER DEFAULT 0,
    mutation_history JSONB DEFAULT '[]',
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_think_tank
CREATE TABLE IF NOT EXISTS learning_think_tank (
    think_tank_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID NOT NULL,
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Conversation metadata
    conversation_topic VARCHAR(500),
    participants TEXT[] DEFAULT '{}', -- AI participants
    total_turns INTEGER DEFAULT 0,
    
    -- Quality signals
    user_engagement_score DECIMAL(5,4), -- How engaged was user
    conversation_coherence DECIMAL(5,4), -- How coherent was multi-AI conversation
    goal_achieved BOOLEAN,
    goal_achievement_score DECIMAL(5,4),
    
    -- User feedback
    overall_rating INTEGER CHECK (overall_rating BETWEEN 1 AND 5),
    feedback_text TEXT,
    
    -- Participant performance
    participant_scores JSONB DEFAULT '{}', -- {model: {quality, helpfulness, relevance}}
    best_contributor VARCHAR(200),
    
    -- Learning insights
    effective_strategies TEXT[] DEFAULT '{}',
    ineffective_strategies TEXT[] DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: learning_transfers
CREATE TABLE IF NOT EXISTS learning_transfers (
    transfer_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Source and target
    source_domain VARCHAR(200) NOT NULL,
    target_domain VARCHAR(200) NOT NULL,
    source_task TEXT,
    target_task TEXT,
    
    -- Transfer method
    transfer_type VARCHAR(50) NOT NULL, -- 'analogy', 'abstraction', 'structure_mapping', 'fine_tuning'
    
    -- What was transferred
    transferred_knowledge JSONB NOT NULL,
    adaptation_needed JSONB DEFAULT '{}',
    
    -- Outcome
    success BOOLEAN,
    transfer_quality DECIMAL(5,4),
    negative_transfer_detected BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: library_execution_aggregates
CREATE TABLE IF NOT EXISTS library_execution_aggregates (
    tenant_id TEXT NOT NULL,
    library_id TEXT NOT NULL,
    period_start TIMESTAMPTZ NOT NULL,
    period_type TEXT NOT NULL, -- 'hourly', 'daily', 'monthly'
    
    execution_count INTEGER NOT NULL DEFAULT 0,
    successful_count INTEGER NOT NULL DEFAULT 0,
    failed_count INTEGER NOT NULL DEFAULT 0,
    total_duration_ms BIGINT NOT NULL DEFAULT 0,
    total_credits DECIMAL(12,6) NOT NULL DEFAULT 0,
    avg_duration_ms INTEGER,
    peak_concurrent INTEGER,
    
    PRIMARY KEY (tenant_id, library_id, period_start, period_type)
);

-- Table: library_execution_config
CREATE TABLE IF NOT EXISTS library_execution_config (
    tenant_id TEXT PRIMARY KEY,
    execution_enabled BOOLEAN NOT NULL DEFAULT true,
    max_concurrent_executions INTEGER NOT NULL DEFAULT 10,
    max_concurrent_per_user INTEGER NOT NULL DEFAULT 3,
    default_constraints JSONB NOT NULL DEFAULT '{
        "maxDurationSeconds": 60,
        "maxMemoryMb": 512,
        "maxOutputBytes": 10485760,
        "allowNetwork": false,
        "allowFileWrites": false
    }'::jsonb,
    library_overrides JSONB,
    daily_budget DECIMAL(12,4),
    monthly_budget DECIMAL(12,4),
    allowed_execution_types TEXT[] NOT NULL DEFAULT ARRAY['code_execution', 'data_transformation', 'analysis', 'visualization'],
    blocked_libraries TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    priority_boost INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: library_execution_logs
CREATE TABLE IF NOT EXISTS library_execution_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    execution_id TEXT NOT NULL REFERENCES library_executions(execution_id) ON DELETE CASCADE,
    log_level TEXT NOT NULL DEFAULT 'info',
    message TEXT NOT NULL,
    metadata JSONB,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: library_execution_queue
CREATE TABLE IF NOT EXISTS library_execution_queue (
    execution_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    library_id TEXT NOT NULL,
    priority INTEGER NOT NULL DEFAULT 0,
    request_data JSONB NOT NULL,
    queued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    estimated_start_at TIMESTAMPTZ
);

-- Table: library_executions
CREATE TABLE IF NOT EXISTS library_executions (
    execution_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    library_id TEXT NOT NULL,
    execution_type TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'queued',
    
    -- Execution details
    code TEXT NOT NULL,
    input_data JSONB,
    context_data JSONB,
    constraints JSONB NOT NULL,
    
    -- Output
    output_data JSONB,
    error_data JSONB,
    
    -- Metrics
    queued_at TIMESTAMPTZ,
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    duration_ms INTEGER,
    peak_memory_mb INTEGER,
    cpu_time_ms INTEGER,
    network_bytes_in BIGINT,
    network_bytes_out BIGINT,
    
    -- Billing
    credits_used DECIMAL(12,6) DEFAULT 0,
    pricing_tier TEXT DEFAULT 'standard',
    
    -- Executor info
    executor_type TEXT, -- 'lambda', 'fargate', 'sagemaker'
    executor_id TEXT,
    
    CONSTRAINT valid_status CHECK (status IN ('queued', 'running', 'completed', 'failed', 'timeout', 'cancelled', 'resource_exceeded'))
);

-- Table: library_executor_pool
CREATE TABLE IF NOT EXISTS library_executor_pool (
    executor_type TEXT PRIMARY KEY,
    available INTEGER NOT NULL DEFAULT 0,
    busy INTEGER NOT NULL DEFAULT 0,
    max_capacity INTEGER NOT NULL DEFAULT 100,
    scaling_in_progress BOOLEAN NOT NULL DEFAULT false,
    target_capacity INTEGER,
    last_scale_action TIMESTAMPTZ,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: library_registry_config
CREATE TABLE IF NOT EXISTS library_registry_config (
  config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Feature toggles
  library_assist_enabled BOOLEAN DEFAULT true,
  auto_suggest_libraries BOOLEAN DEFAULT true,
  max_libraries_per_request INTEGER DEFAULT 5,
  
  -- Update settings
  auto_update_enabled BOOLEAN DEFAULT true,
  update_frequency VARCHAR(20) DEFAULT 'daily' CHECK (update_frequency IN ('hourly', 'daily', 'weekly', 'manual')),
  update_time_utc VARCHAR(5) DEFAULT '03:00',
  last_update_at TIMESTAMPTZ,
  next_update_at TIMESTAMPTZ,
  
  -- Proficiency matching
  min_proficiency_match DECIMAL(3,2) DEFAULT 0.50 CHECK (min_proficiency_match BETWEEN 0 AND 1),
  proficiency_weights JSONB DEFAULT '{}',
  
  -- Category preferences
  enabled_categories JSONB DEFAULT '[]',
  disabled_libraries JSONB DEFAULT '[]',
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT unique_library_config_per_tenant UNIQUE (tenant_id)
);

-- Table: library_registry_metadata
CREATE TABLE IF NOT EXISTS library_registry_metadata (
  metadata_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  version VARCHAR(20) NOT NULL,
  generated_at TIMESTAMPTZ NOT NULL,
  description TEXT,
  total_tools INTEGER DEFAULT 0,
  license_types_included JSONB DEFAULT '[]',
  license_types_excluded JSONB DEFAULT '[]',
  proficiency_scale JSONB DEFAULT '{"min": 1, "max": 10}',
  proficiency_dimensions JSONB DEFAULT '[]',
  
  -- Singleton constraint
  is_current BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT only_one_current_metadata UNIQUE (is_current) 
);

-- Table: library_update_jobs
CREATE TABLE IF NOT EXISTS library_update_jobs (
  job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL for global updates
  
  -- Job status
  status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'completed', 'failed')),
  job_type VARCHAR(20) DEFAULT 'scheduled' CHECK (job_type IN ('scheduled', 'manual', 'seed')),
  
  -- Progress
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  libraries_checked INTEGER DEFAULT 0,
  libraries_updated INTEGER DEFAULT 0,
  new_libraries_added INTEGER DEFAULT 0,
  
  -- Errors
  errors JSONB DEFAULT '[]',
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: library_usage_aggregates
CREATE TABLE IF NOT EXISTS library_usage_aggregates (
  aggregate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  library_id VARCHAR(100) NOT NULL REFERENCES open_source_libraries(library_id) ON DELETE CASCADE,
  
  -- Statistics
  total_invocations INTEGER DEFAULT 0,
  successful_invocations INTEGER DEFAULT 0,
  failed_invocations INTEGER DEFAULT 0,
  total_execution_time_ms BIGINT DEFAULT 0,
  invocations_by_type JSONB DEFAULT '{}',
  last_used_at TIMESTAMPTZ,
  
  -- Computed
  success_rate DECIMAL(5,4) GENERATED ALWAYS AS (
    CASE WHEN total_invocations > 0 
    THEN successful_invocations::DECIMAL / total_invocations 
    ELSE 0 END
  ) STORED,
  avg_execution_time_ms DECIMAL(10,2) GENERATED ALWAYS AS (
    CASE WHEN total_invocations > 0 
    THEN total_execution_time_ms::DECIMAL / total_invocations 
    ELSE 0 END
  ) STORED,
  
  -- Audit
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT unique_usage_aggregate UNIQUE (tenant_id, library_id)
);

-- Table: library_usage_events
CREATE TABLE IF NOT EXISTS library_usage_events (
  event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID,
  library_id VARCHAR(100) NOT NULL REFERENCES open_source_libraries(library_id) ON DELETE CASCADE,
  
  -- Invocation details
  invocation_type VARCHAR(50) NOT NULL CHECK (invocation_type IN (
    'code_generation', 'data_processing', 'analysis', 'transformation',
    'search', 'inference', 'optimization', 'simulation'
  )),
  success BOOLEAN NOT NULL,
  execution_time_ms INTEGER,
  error_message TEXT,
  
  -- Context
  conversation_id UUID,
  request_id UUID,
  prompt_domain VARCHAR(100),
  match_score DECIMAL(3,2),
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: library_version_history
CREATE TABLE IF NOT EXISTS library_version_history (
  history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  library_id VARCHAR(100) NOT NULL REFERENCES open_source_libraries(library_id) ON DELETE CASCADE,
  
  -- Version info
  previous_version VARCHAR(50),
  new_version VARCHAR(50),
  stars_delta INTEGER DEFAULT 0,
  breaking_changes BOOLEAN DEFAULT false,
  release_notes TEXT,
  
  -- Audit
  detected_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: license_audit_log
CREATE TABLE IF NOT EXISTS license_audit_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id UUID NOT NULL REFERENCES ai_models(id) ON DELETE CASCADE,
    license_id UUID REFERENCES model_licenses(id) ON DELETE SET NULL,
    
    action VARCHAR(50) NOT NULL,
    previous_status VARCHAR(20),
    new_status VARCHAR(20),
    
    performed_by UUID,
    notes TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: liquid_ai_reactions
CREATE TABLE IF NOT EXISTS liquid_ai_reactions (
    id TEXT PRIMARY KEY,
    event_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    
    -- Reaction details
    type TEXT NOT NULL CHECK (type IN ('speak', 'update', 'morph', 'suggest')),
    message TEXT,
    state_updates JSONB,
    new_schema JSONB,
    suggestions JSONB,
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_ai_reactions_event FOREIGN KEY (event_id) REFERENCES liquid_ghost_events(id) ON DELETE CASCADE,
    CONSTRAINT fk_ai_reactions_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

-- Table: liquid_component_usage
CREATE TABLE IF NOT EXISTS liquid_component_usage (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id TEXT NOT NULL,
    
    -- Component info
    component_id TEXT NOT NULL,
    component_category TEXT NOT NULL,
    
    -- Usage stats
    morph_count INTEGER NOT NULL DEFAULT 0,
    interaction_count INTEGER NOT NULL DEFAULT 0,
    eject_count INTEGER NOT NULL DEFAULT 0,
    
    -- Time tracking
    first_used_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_used_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT uk_component_usage UNIQUE (tenant_id, component_id),
    CONSTRAINT fk_component_usage_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- Table: liquid_compute_decisions
CREATE TABLE IF NOT EXISTS liquid_compute_decisions (
  decision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  tool_id UUID,
  selected_location compute_location NOT NULL,
  reason compute_reason NOT NULL,
  alternatives JSONB DEFAULT '[]',
  
  -- Execution details
  execution_endpoint TEXT,
  estimated_latency_ms INTEGER,
  estimated_cost DOUBLE PRECISION,
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: liquid_compute_topologies
CREATE TABLE IF NOT EXISTS liquid_compute_topologies (
  topology_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE UNIQUE,
  
  -- Capabilities
  browser_capabilities JSONB DEFAULT '{"wasmSupported": true, "webGPUSupported": false, "maxMemoryMb": 2048, "estimatedComputeScore": 0.5, "supportedModels": []}',
  local_capabilities JSONB,
  edge_locations JSONB DEFAULT '[]',
  cloud_regions JSONB DEFAULT '[]',
  
  -- Configuration
  default_location compute_location DEFAULT 'cloud',
  domain_location_overrides JSONB DEFAULT '{}',
  sensitivity_location_rules JSONB DEFAULT '{"public": ["browser", "local", "edge", "cloud"], "internal": ["local", "edge", "cloud"], "confidential": ["local", "cloud"], "restricted": ["local"]}',
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: liquid_config
CREATE TABLE IF NOT EXISTS liquid_config (
    tenant_id TEXT PRIMARY KEY,
    
    -- Feature flags
    enabled BOOLEAN NOT NULL DEFAULT true,
    auto_morph_enabled BOOLEAN NOT NULL DEFAULT true,
    eject_enabled BOOLEAN NOT NULL DEFAULT true,
    
    -- Thresholds
    morph_confidence_threshold REAL NOT NULL DEFAULT 0.85,
    auto_revert_timeout_seconds INTEGER NOT NULL DEFAULT 300,
    
    -- Limits
    max_active_sessions INTEGER NOT NULL DEFAULT 10,
    max_ghost_events_per_session INTEGER NOT NULL DEFAULT 1000,
    
    -- AI overlay defaults
    default_overlay_mode TEXT NOT NULL DEFAULT 'sidebar',
    default_overlay_position TEXT NOT NULL DEFAULT 'right',
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_liquid_config_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- Table: liquid_eject_history
CREATE TABLE IF NOT EXISTS liquid_eject_history (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    
    -- Eject configuration
    framework TEXT NOT NULL,
    features JSONB NOT NULL DEFAULT '[]',
    file_count INTEGER NOT NULL DEFAULT 0,
    
    -- Result
    status TEXT NOT NULL DEFAULT 'success' CHECK (status IN ('success', 'partial', 'failed')),
    deploy_url TEXT,
    repo_url TEXT,
    warnings JSONB,
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_eject_history_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

-- Table: liquid_ghost_events
CREATE TABLE IF NOT EXISTS liquid_ghost_events (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    
    -- Event source
    component_id TEXT NOT NULL,
    component_type TEXT NOT NULL,
    
    -- Event details
    action TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    current_state JSONB NOT NULL DEFAULT '{}',
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_ghost_events_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

-- Table: liquid_ghost_state
CREATE TABLE IF NOT EXISTS liquid_ghost_state (
    session_id TEXT NOT NULL,
    context_key TEXT NOT NULL,
    value JSONB,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    PRIMARY KEY (session_id, context_key),
    CONSTRAINT fk_ghost_state_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

-- Table: liquid_intent_patterns
CREATE TABLE IF NOT EXISTS liquid_intent_patterns (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id TEXT NOT NULL,
    
    -- Pattern definition
    pattern TEXT NOT NULL,
    category TEXT NOT NULL,
    confidence REAL NOT NULL DEFAULT 0.8,
    
    -- Learning metadata
    success_count INTEGER NOT NULL DEFAULT 0,
    failure_count INTEGER NOT NULL DEFAULT 0,
    last_matched_at TIMESTAMP,
    
    -- Source
    source TEXT NOT NULL DEFAULT 'system' CHECK (source IN ('system', 'learned', 'admin')),
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_intent_patterns_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- Table: liquid_sessions
CREATE TABLE IF NOT EXISTS liquid_sessions (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL,
    
    -- Current state
    mode TEXT NOT NULL DEFAULT 'chat' CHECK (mode IN ('chat', 'morphed', 'transitioning', 'ejecting')),
    current_schema JSONB,
    ghost_state JSONB NOT NULL DEFAULT '{}',
    
    -- Metadata
    message_count INTEGER NOT NULL DEFAULT 0,
    morphed_at TIMESTAMP,
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_liquid_sessions_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- Table: litellm_gateway_config
CREATE TABLE IF NOT EXISTS litellm_gateway_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- ECS Configuration
  min_tasks INTEGER NOT NULL DEFAULT 2,
  max_tasks INTEGER NOT NULL DEFAULT 50,
  desired_tasks INTEGER NOT NULL DEFAULT 2,
  task_cpu INTEGER NOT NULL DEFAULT 2048,
  task_memory INTEGER NOT NULL DEFAULT 4096,
  
  -- Auto-scaling
  target_cpu_utilization INTEGER NOT NULL DEFAULT 70,
  target_memory_utilization INTEGER NOT NULL DEFAULT 80,
  target_requests_per_target INTEGER NOT NULL DEFAULT 1000,
  scale_out_cooldown_seconds INTEGER NOT NULL DEFAULT 60,
  scale_in_cooldown_seconds INTEGER NOT NULL DEFAULT 300,
  
  -- Health Check
  health_check_path VARCHAR(100) NOT NULL DEFAULT '/health',
  health_check_interval_seconds INTEGER NOT NULL DEFAULT 30,
  health_check_timeout_seconds INTEGER NOT NULL DEFAULT 10,
  unhealthy_threshold_count INTEGER NOT NULL DEFAULT 3,
  
  -- Load Balancer
  deregistration_delay_seconds INTEGER NOT NULL DEFAULT 30,
  idle_timeout_seconds INTEGER NOT NULL DEFAULT 60,
  
  -- Rate Limiting
  global_rate_limit_per_second INTEGER NOT NULL DEFAULT 10000,
  per_tenant_rate_limit_per_minute INTEGER NOT NULL DEFAULT 1000,
  
  -- Caching
  enable_response_caching BOOLEAN NOT NULL DEFAULT true,
  cache_ttl_seconds INTEGER NOT NULL DEFAULT 3600,
  
  -- Retry
  max_retries INTEGER NOT NULL DEFAULT 3,
  retry_delay_ms INTEGER NOT NULL DEFAULT 1000,
  
  -- Timeouts
  request_timeout_seconds INTEGER NOT NULL DEFAULT 600,
  connection_timeout_seconds INTEGER NOT NULL DEFAULT 30,
  
  -- Timestamps
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by UUID NOT NULL
);

-- Table: live_config_cache
CREATE TABLE IF NOT EXISTS live_config_cache (
    cache_key VARCHAR(500) PRIMARY KEY,
    config_type VARCHAR(100) NOT NULL,
    
    -- Cached value
    cached_value JSONB NOT NULL,
    
    -- Versioning
    version_number BIGINT NOT NULL,
    
    -- TTL
    expires_at TIMESTAMPTZ,
    
    -- Stats
    hit_count BIGINT DEFAULT 0,
    last_hit TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: living_parchment_config
CREATE TABLE IF NOT EXISTS living_parchment_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE UNIQUE,
    
    -- Feature toggles
    war_room_enabled BOOLEAN DEFAULT TRUE,
    memory_palace_enabled BOOLEAN DEFAULT TRUE,
    oracle_view_enabled BOOLEAN DEFAULT TRUE,
    synthesis_engine_enabled BOOLEAN DEFAULT TRUE,
    cognitive_load_enabled BOOLEAN DEFAULT TRUE,
    council_of_experts_enabled BOOLEAN DEFAULT TRUE,
    temporal_drift_enabled BOOLEAN DEFAULT TRUE,
    debate_arena_enabled BOOLEAN DEFAULT TRUE,
    
    -- Defaults
    breathing_rate_base INTEGER DEFAULT 6,
    confidence_threshold INTEGER DEFAULT 70,
    staleness_threshold_days INTEGER DEFAULT 30,
    max_advisors INTEGER DEFAULT 10,
    max_experts INTEGER DEFAULT 8,
    max_debate_rounds INTEGER DEFAULT 5,
    
    -- Visual settings
    heatmap_color_scheme VARCHAR(50) DEFAULT 'standard',
    custom_colors JSONB DEFAULT '{}',
    animation_intensity VARCHAR(50) DEFAULT 'normal',
    ghost_opacity NUMERIC(3,2) DEFAULT 0.5,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: livs_config
CREATE TABLE IF NOT EXISTS livs_config (
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "individualInterrogation": {
            "enabled": true,
            "defaultDepth": 1,
            "autoEscalate": true,
            "escalationThreshold": 0.6,
            "style": "socratic"
        },
        "orchestrationIntegrity": {
            "enabled": true,
            "preActionInterrogation": true,
            "consistencyChecking": true,
            "evidenceChainValidation": true,
            "maxConfidencePropagation": 0.95
        },
        "costMode": "balanced",
        "maxInterrogationCostMultiplier": 2.0,
        "contributeToGlobalWeights": true,
        "useGlobalWeights": true
    }'::jsonb,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by UUID REFERENCES users(id),
    PRIMARY KEY (tenant_id)
);

-- Table: livs_global_model_weights
CREATE TABLE IF NOT EXISTS livs_global_model_weights (
    model_id VARCHAR(255) PRIMARY KEY,
    
    -- Aggregate stats across all tenants
    total_interrogations INTEGER NOT NULL DEFAULT 0,
    lies_detected INTEGER NOT NULL DEFAULT 0,
    lie_rate DECIMAL(5,4) NOT NULL DEFAULT 0.0,
    
    -- Domain-specific global lie rates
    domain_lie_rates JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Question type specific global lie rates
    question_type_lie_rates JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Global calibration score
    calibration_score DECIMAL(3,2) NOT NULL DEFAULT 0.5,
    
    -- Contributing tenant count
    contributing_tenants INTEGER NOT NULL DEFAULT 0,
    
    -- Metadata
    last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: livs_interrogations
CREATE TABLE IF NOT EXISTS livs_interrogations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Original request info
    original_request_id UUID,
    original_model_id VARCHAR(255) NOT NULL,
    original_response TEXT NOT NULL,
    original_confidence DECIMAL(3,2),
    
    -- Interrogation details
    interrogator_model_id VARCHAR(255) NOT NULL,
    interrogation_depth INTEGER NOT NULL CHECK (interrogation_depth BETWEEN 0 AND 4),
    exchanges JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Lie detection results
    lie_detected BOOLEAN NOT NULL DEFAULT false,
    lie_confidence DECIMAL(3,2) NOT NULL DEFAULT 0.0,
    signals JSONB NOT NULL DEFAULT '{}'::jsonb,
    calibrated_confidence DECIMAL(3,2),
    
    -- Verdict
    verdict VARCHAR(20) NOT NULL CHECK (verdict IN ('trusted', 'suspicious', 'likely_lie', 'confirmed_lie')),
    
    -- Cost tracking
    cost_tokens INTEGER NOT NULL DEFAULT 0,
    duration_ms INTEGER NOT NULL DEFAULT 0,
    
    -- Metadata
    domain VARCHAR(100),
    query_type VARCHAR(50),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
) PARTITION BY RANGE (created_at);

-- Table: livs_model_weights
CREATE TABLE IF NOT EXISTS livs_model_weights (
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    
    -- Aggregate stats
    total_interrogations INTEGER NOT NULL DEFAULT 0,
    lies_detected INTEGER NOT NULL DEFAULT 0,
    lie_rate DECIMAL(5,4) NOT NULL DEFAULT 0.0,
    
    -- Domain-specific lie rates
    domain_lie_rates JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Question type specific lie rates
    question_type_lie_rates JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Calibration score (0-1, higher = better)
    calibration_score DECIMAL(3,2) NOT NULL DEFAULT 0.5,
    
    -- How well model holds up under interrogation
    interrogation_resilience DECIMAL(3,2) NOT NULL DEFAULT 0.5,
    
    -- Sample size for statistical significance
    sample_size INTEGER NOT NULL DEFAULT 0,
    
    -- Metadata
    last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (tenant_id, model_id)
);

-- Table: livs_orchestration_weights
CREATE TABLE IF NOT EXISTS livs_orchestration_weights (
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pattern_id VARCHAR(255) NOT NULL,
    
    -- Reliability stats
    total_executions INTEGER NOT NULL DEFAULT 0,
    successful_executions INTEGER NOT NULL DEFAULT 0,
    reliability_score DECIMAL(3,2) NOT NULL DEFAULT 0.5,
    
    -- Failure mode frequency
    failure_mode_history JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Model compatibility scores
    model_compatibility JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Metadata
    last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (tenant_id, pattern_id)
);

-- Table: livs_pipeline_audits
CREATE TABLE IF NOT EXISTS livs_pipeline_audits (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pipeline_execution_id UUID NOT NULL,
    
    -- Per-method integrity scores
    method_scores JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Aggregate scores
    consistency_score DECIMAL(3,2) NOT NULL DEFAULT 0.0,
    evidence_chain_score DECIMAL(3,2) NOT NULL DEFAULT 0.0,
    goal_alignment_score DECIMAL(3,2) NOT NULL DEFAULT 0.0,
    overall_integrity_score DECIMAL(3,2) NOT NULL DEFAULT 0.0,
    
    -- Detected failure patterns
    detected_patterns JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Issues found
    issues JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Recommendations
    recommendations JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
) PARTITION BY RANGE (created_at);

-- Table: livs_soft_rules
CREATE TABLE IF NOT EXISTS livs_soft_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Conditions for when this rule applies
    conditions JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Actions to take when rule matches
    actions JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    -- Priority (higher = evaluated first)
    priority INTEGER NOT NULL DEFAULT 0,
    
    -- Who created this rule
    created_by_type VARCHAR(20) NOT NULL CHECK (created_by_type IN ('system', 'tenant_admin', 'user')),
    created_by UUID REFERENCES users(id),
    
    -- Status
    active BOOLEAN NOT NULL DEFAULT true,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: local_ego_config
CREATE TABLE IF NOT EXISTS local_ego_config (
  config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Feature toggles
  ego_enabled BOOLEAN DEFAULT true,
  use_shared_ego BOOLEAN DEFAULT true,  -- Use shared infrastructure vs dedicated
  
  -- Ego behavior configuration
  direct_response_threshold DECIMAL(3,2) DEFAULT 0.7,  -- Confidence to handle directly
  recruitment_threshold DECIMAL(3,2) DEFAULT 0.5,      -- When to recruit external
  max_direct_tokens INTEGER DEFAULT 512,               -- Max tokens for direct response
  
  -- Model preferences
  preferred_ego_model TEXT DEFAULT 'microsoft/Phi-3-mini-4k-instruct',
  fallback_ego_model TEXT DEFAULT 'Qwen/Qwen2.5-3B-Instruct',
  
  -- External recruitment preferences
  preferred_coding_model TEXT DEFAULT 'anthropic/claude-3-5-sonnet',
  preferred_reasoning_model TEXT DEFAULT 'openai/o1-preview',
  preferred_factual_model TEXT DEFAULT 'google/gemini-2.0-flash',
  default_recruitment_model TEXT DEFAULT 'anthropic/claude-3-haiku',
  
  -- Response integration
  integrate_ego_voice BOOLEAN DEFAULT false,  -- Add Ego framing to external responses
  ego_voice_style TEXT DEFAULT 'neutral',     -- 'neutral', 'warm', 'professional', 'playful'
  
  -- Resource limits
  daily_ego_token_budget INTEGER DEFAULT 100000,
  daily_recruitment_budget INTEGER DEFAULT 500000,
  max_concurrent_recruitments INTEGER DEFAULT 3,
  
  -- Thought generation
  generate_internal_thoughts BOOLEAN DEFAULT true,
  thought_depth TEXT DEFAULT 'standard',  -- 'minimal', 'standard', 'deep'
  log_thoughts_to_db BOOLEAN DEFAULT true,
  
  -- Self-reflection schedule
  enable_periodic_reflection BOOLEAN DEFAULT false,
  reflection_interval_minutes INTEGER DEFAULT 60,
  
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(tenant_id)
);

-- Table: localization_bundles
CREATE TABLE IF NOT EXISTS localization_bundles (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    language_code VARCHAR(10) NOT NULL REFERENCES localization_languages(code),
    app_id VARCHAR(50),
    category VARCHAR(100),
    bundle_data JSONB NOT NULL,
    bundle_hash VARCHAR(64) NOT NULL,
    entry_count INTEGER NOT NULL,
    generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ,
    UNIQUE(language_code, app_id, category)
);

-- Table: localization_languages
CREATE TABLE IF NOT EXISTS localization_languages (
    code VARCHAR(10) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    native_name VARCHAR(100) NOT NULL,
    direction VARCHAR(3) DEFAULT 'ltr',
    is_active BOOLEAN DEFAULT true,
    is_default BOOLEAN DEFAULT false,
    display_order INTEGER DEFAULT 0
);

-- Table: localization_registry
CREATE TABLE IF NOT EXISTS localization_registry (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    key VARCHAR(255) UNIQUE NOT NULL,
    default_text TEXT NOT NULL,
    context TEXT,
    category VARCHAR(100) NOT NULL,
    placeholders TEXT[],
    app_id UUID,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: localization_translation_history
CREATE TABLE IF NOT EXISTS localization_translation_history (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    translation_id UUID NOT NULL REFERENCES localization_translations(id) ON DELETE CASCADE,
    previous_text TEXT NOT NULL,
    new_text TEXT NOT NULL,
    previous_status translation_status,
    new_status translation_status,
    changed_by UUID,
    change_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: localization_translations
CREATE TABLE IF NOT EXISTS localization_translations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    registry_id UUID NOT NULL REFERENCES localization_registry(id) ON DELETE CASCADE,
    language_code VARCHAR(10) NOT NULL,
    translated_text TEXT NOT NULL,
    status VARCHAR(50) DEFAULT 'pending',
    translator_type VARCHAR(50) DEFAULT 'human',
    reviewed_by UUID,
    reviewed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(registry_id, language_code)
);

-- Table: lora_adapters
CREATE TABLE IF NOT EXISTS lora_adapters (
  adapter_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  adapter_name VARCHAR(255) NOT NULL,
  adapter_layer VARCHAR(50) NOT NULL CHECK (adapter_layer IN ('global', 'user', 'domain')),
  base_model VARCHAR(255) NOT NULL,
  s3_key TEXT NOT NULL,
  is_pinned BOOLEAN DEFAULT false,
  is_active BOOLEAN DEFAULT true,
  scale DECIMAL(3,2) DEFAULT 1.0,
  load_count INTEGER DEFAULT 0,
  last_used_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: lora_config
CREATE TABLE IF NOT EXISTS lora_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  enabled BOOLEAN DEFAULT true,
  use_global_adapter BOOLEAN DEFAULT true,
  use_user_adapter BOOLEAN DEFAULT true,
  global_scale DECIMAL(3,2) DEFAULT 1.0,
  user_scale DECIMAL(3,2) DEFAULT 1.0,
  auto_selection_enabled BOOLEAN DEFAULT true,
  rollback_enabled BOOLEAN DEFAULT true,
  warmup_enabled BOOLEAN DEFAULT true,
  warmup_interval_minutes INTEGER DEFAULT 15,
  max_adapters_in_memory INTEGER DEFAULT 50,
  lru_eviction_enabled BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(tenant_id)
);

-- Table: lora_evolution_jobs
CREATE TABLE IF NOT EXISTS lora_evolution_jobs (
  job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Job configuration
  base_model_id TEXT NOT NULL,  -- e.g., 'meta/llama-3-8b-instruct'
  adapter_name TEXT NOT NULL,   -- e.g., 'ego-adapter-2024-12-29'
  adapter_version INTEGER NOT NULL DEFAULT 1,
  
  -- Training data
  training_candidates_count INTEGER DEFAULT 0,
  training_tokens_total INTEGER DEFAULT 0,
  training_data_s3_path TEXT,
  
  -- SageMaker job details
  sagemaker_job_name TEXT,
  sagemaker_job_arn TEXT,
  
  -- Status tracking
  status TEXT DEFAULT 'scheduled' CHECK (status IN (
    'scheduled',    -- Waiting for scheduled time
    'preparing',    -- Preparing training data
    'training',     -- SageMaker job running
    'validating',   -- Validating new adapter
    'deploying',    -- Hot-swapping adapter
    'completed',    -- Successfully deployed
    'failed',       -- Job failed
    'rolled_back'   -- Rolled back to previous version
  )),
  
  -- Training metrics
  training_loss DECIMAL(8,6),
  validation_loss DECIMAL(8,6),
  improvement_score DECIMAL(5,4),  -- vs previous adapter
  
  -- Timing
  scheduled_at TIMESTAMPTZ,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  duration_seconds INTEGER,
  
  -- Adapter artifact
  adapter_s3_path TEXT,
  adapter_size_mb DECIMAL(8,2),
  
  -- Deployment
  deployed_at TIMESTAMPTZ,
  previous_adapter_id UUID,
  rollback_reason TEXT,
  
  -- Error handling
  error_message TEXT,
  retry_count INTEGER DEFAULT 0,
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: lora_invocations
CREATE TABLE IF NOT EXISTS lora_invocations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  adapter_id UUID REFERENCES lora_adapters(adapter_id) ON DELETE SET NULL,
  user_id UUID,
  model_id VARCHAR(255) NOT NULL,
  adapters_used INTEGER DEFAULT 1,
  global_adapter_id UUID,
  user_adapter_id UUID,
  latency_ms INTEGER,
  success BOOLEAN DEFAULT true,
  error_message TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: lora_warmup_log
CREATE TABLE IF NOT EXISTS lora_warmup_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  trigger_type VARCHAR(50) NOT NULL, -- 'boot', 'schedule', 'manual'
  status VARCHAR(50) DEFAULT 'pending', -- 'pending', 'running', 'completed', 'failed'
  adapters_warmed INTEGER DEFAULT 0,
  duration_ms INTEGER,
  error_message TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ
);

-- Table: magic_carpets
CREATE TABLE IF NOT EXISTS magic_carpets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Current state
    destination JSONB,
    mode VARCHAR(20) NOT NULL DEFAULT 'resting',
    altitude VARCHAR(20) NOT NULL DEFAULT 'ground',
    
    -- Reality Engine integration
    reality_engine_session_id UUID REFERENCES reality_engine_sessions(id) ON DELETE SET NULL,
    
    -- Navigation history
    journey JSONB NOT NULL DEFAULT '[]',
    current_position INTEGER NOT NULL DEFAULT -1,
    
    -- Customization
    theme JSONB NOT NULL DEFAULT '{
        "name": "Mystic Night",
        "mode": "dark",
        "primary": "#8B5CF6",
        "secondary": "#6366F1",
        "accent": "#F59E0B",
        "background": "#0F172A",
        "surface": "#1E293B",
        "carpetGradient": ["#4F46E5", "#7C3AED", "#A855F7"],
        "glowColor": "#A78BFA",
        "trailEffect": true,
        "fontFamily": "Inter",
        "fontSize": "md",
        "blur": true,
        "shadows": true,
        "animations": true
    }',
    
    preferences JSONB NOT NULL DEFAULT '{
        "autoFly": true,
        "smoothTransitions": true,
        "showJourneyTrail": true,
        "preCognitionEnabled": true,
        "showPredictions": true,
        "telepathyIntensity": "moderate",
        "showTimeline": true,
        "autoSnapshot": true,
        "snapshotInterval": 30,
        "maxParallelRealities": 4,
        "autoCompare": true,
        "reducedMotion": false,
        "highContrast": false,
        "screenReaderMode": false
    }',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: maintenance_log
CREATE TABLE IF NOT EXISTS maintenance_log (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    operation_type TEXT NOT NULL,  -- 'vacuum', 'analyze', 'reindex', 'partition_create'
    table_name TEXT,
    partition_name TEXT,
    duration_ms NUMERIC,
    rows_affected BIGINT,
    dead_tuples_removed BIGINT,
    status TEXT NOT NULL,  -- 'success', 'failed', 'skipped'
    error_message TEXT,
    executed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id)
);

-- Table: mcp_routing_decisions
CREATE TABLE IF NOT EXISTS mcp_routing_decisions (
  decision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  selected_tool_id UUID REFERENCES mcp_tool_schemas(tool_id),
  selection_reason TEXT,
  fallback_tools JSONB DEFAULT '[]',
  
  -- Metrics
  routing_time_ms INTEGER,
  candidates_evaluated INTEGER,
  
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: mcp_servers
CREATE TABLE IF NOT EXISTS mcp_servers (
  server_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Basic info
  name VARCHAR(100) NOT NULL,
  description TEXT,
  
  -- Transport configuration
  transport mcp_transport NOT NULL DEFAULT 'streamable-http',
  url TEXT,
  command TEXT,
  args JSONB DEFAULT '[]',
  env JSONB DEFAULT '{}',
  
  -- Neural routing metadata
  domain_affinity JSONB DEFAULT '[]',
  embedding_vector TEXT, -- Base64 encoded Float32Array
  proficiency_scores JSONB DEFAULT '{}',
  neural_affinity_model VARCHAR(100) DEFAULT 'cortex-routing-v1',
  
  -- Health metrics
  health_endpoint TEXT,
  last_health_check TIMESTAMPTZ,
  health_status mcp_health_status DEFAULT 'unknown',
  error_rate DOUBLE PRECISION DEFAULT 0,
  avg_latency_ms DOUBLE PRECISION DEFAULT 0,
  p50_latency_ms DOUBLE PRECISION DEFAULT 0,
  p95_latency_ms DOUBLE PRECISION DEFAULT 0,
  p99_latency_ms DOUBLE PRECISION DEFAULT 0,
  
  -- Cost tracking
  cost_per_call DOUBLE PRECISION DEFAULT 0,
  total_calls_today INTEGER DEFAULT 0,
  total_cost_today DOUBLE PRECISION DEFAULT 0,
  budget_limit DOUBLE PRECISION,
  
  -- Authentication
  auth_type mcp_auth_type DEFAULT 'none',
  credentials_encrypted TEXT,
  credential_rotation_days INTEGER,
  
  -- Capabilities
  supported_capabilities JSONB DEFAULT '[]',
  max_concurrent_calls INTEGER DEFAULT 10,
  timeout_ms INTEGER DEFAULT 30000,
  retry_config JSONB DEFAULT '{"maxAttempts": 3, "initialDelayMs": 1000, "maxDelayMs": 30000, "backoffMultiplier": 2}',
  
  -- Lifecycle
  status mcp_server_status DEFAULT 'active',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  last_used_at TIMESTAMPTZ
);

-- Table: mcp_tool_schemas
CREATE TABLE IF NOT EXISTS mcp_tool_schemas (
  tool_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  server_id UUID REFERENCES mcp_servers(server_id) ON DELETE CASCADE,
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Basic info
  name VARCHAR(100) NOT NULL,
  description TEXT,
  
  -- Schema definitions
  input_schema_json JSONB DEFAULT '{}',
  output_schema_json JSONB DEFAULT '{}',
  
  -- Neural embeddings
  description_embedding TEXT,
  structure_embedding TEXT,
  neural_signature TEXT,
  
  -- Classification
  category tool_category DEFAULT 'data_retrieval',
  tags JSONB DEFAULT '[]',
  is_structured_output BOOLEAN DEFAULT false,
  
  -- Usage metrics
  success_rate DOUBLE PRECISION DEFAULT 1,
  avg_execution_ms DOUBLE PRECISION DEFAULT 0,
  last_used TIMESTAMPTZ,
  usage_count INTEGER DEFAULT 0,
  
  -- Domain mapping
  primary_domain VARCHAR(100) DEFAULT 'general',
  secondary_domains JSONB DEFAULT '[]',
  proficiency_by_model JSONB DEFAULT '{}',
  
  -- Access control
  required_permissions JSONB DEFAULT '[]',
  sensitivity_level tool_sensitivity DEFAULT 'public',
  
  -- Cost
  estimated_cost_per_call DOUBLE PRECISION DEFAULT 0,
  actual_avg_cost DOUBLE PRECISION,
  
  -- Metadata
  version VARCHAR(20) DEFAULT '1.0.0',
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: media_vault
CREATE TABLE IF NOT EXISTS media_vault (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    chat_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    message_id UUID,
    snapshot_id UUID NOT NULL REFERENCES time_machine_snapshots(id) ON DELETE CASCADE,
    
    original_name VARCHAR(255) NOT NULL,
    display_name VARCHAR(255) NOT NULL,
    
    s3_bucket VARCHAR(100) NOT NULL,
    s3_key VARCHAR(500) NOT NULL,
    s3_version_id VARCHAR(100),
    
    mime_type VARCHAR(100) NOT NULL,
    size_bytes BIGINT NOT NULL,
    checksum_sha256 VARCHAR(64) NOT NULL,
    
    thumbnail_s3_key VARCHAR(500),
    preview_generated BOOLEAN DEFAULT false,
    
    version INTEGER NOT NULL DEFAULT 1,
    previous_version_id UUID REFERENCES media_vault(id),
    
    source VARCHAR(20) NOT NULL CHECK (source IN ('user_upload', 'ai_generated', 'system')),
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'processing', 'archived', 'soft_deleted')),
    
    extracted_text TEXT,
    ai_description TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    archived_at TIMESTAMPTZ
);

-- Table: memories
CREATE TABLE IF NOT EXISTS memories (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    store_id UUID NOT NULL REFERENCES memory_stores(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    embedding vector(1536),
    memory_type VARCHAR(50) DEFAULT 'fact' CHECK (memory_type IN ('fact', 'preference', 'context', 'instruction', 'conversation', 'skill')),
    source VARCHAR(100),
    importance DECIMAL(3, 2) DEFAULT 0.50 CHECK (importance >= 0 AND importance <= 1),
    access_count INTEGER DEFAULT 0,
    last_accessed TIMESTAMPTZ,
    expires_at TIMESTAMPTZ,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: memory_categories
CREATE TABLE IF NOT EXISTS memory_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Category identification
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    
    -- Hierarchy (for future expansion)
    parent_id UUID REFERENCES memory_categories(id),
    level INTEGER NOT NULL DEFAULT 1,
    path VARCHAR(500),  -- Materialized path like 'preferences.format.code'
    
    -- Display
    icon VARCHAR(50),
    color VARCHAR(20),  -- Tailwind color class
    display_order INTEGER NOT NULL DEFAULT 0,
    
    -- Behavior
    is_system BOOLEAN NOT NULL DEFAULT false,  -- System categories can't be deleted
    is_expandable BOOLEAN NOT NULL DEFAULT true,  -- Can users add sub-categories?
    applies_to TEXT[] DEFAULT ARRAY['preprompt', 'synthesis', 'response'],
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: memory_chunks
CREATE TABLE IF NOT EXISTS memory_chunks (
    chunk_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Chunk content
    chunk_label VARCHAR(200) NOT NULL,
    constituent_items JSONB NOT NULL, -- Items grouped together
    chunk_size INTEGER,
    
    -- Compression
    compression_ratio DECIMAL(5,4), -- How much space saved
    retrieval_cue TEXT,
    
    -- Usage
    times_used INTEGER DEFAULT 0,
    last_used TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: memory_conflicts
CREATE TABLE IF NOT EXISTS memory_conflicts (
    conflict_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Conflicting memories
    memory_a_id UUID NOT NULL,
    memory_a_type VARCHAR(50) NOT NULL,
    memory_a_content TEXT NOT NULL,
    memory_a_confidence DECIMAL(5,4),
    
    memory_b_id UUID NOT NULL,
    memory_b_type VARCHAR(50) NOT NULL,
    memory_b_content TEXT NOT NULL,
    memory_b_confidence DECIMAL(5,4),
    
    -- Conflict details
    conflict_type VARCHAR(50) NOT NULL, -- 'contradiction', 'inconsistency', 'redundancy', 'temporal_conflict'
    conflict_description TEXT NOT NULL,
    severity VARCHAR(20), -- 'critical', 'major', 'minor'
    
    -- Resolution
    resolution_status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'auto_resolved', 'manual_resolved', 'flagged'
    resolution_strategy VARCHAR(50),
    resolution_result JSONB,
    resolved_by VARCHAR(50), -- 'system', 'user', agent_id
    resolved_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: memory_connections
CREATE TABLE IF NOT EXISTS memory_connections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    source_node_id UUID NOT NULL REFERENCES knowledge_nodes(id) ON DELETE CASCADE,
    target_node_id UUID NOT NULL REFERENCES knowledge_nodes(id) ON DELETE CASCADE,
    strength INTEGER DEFAULT 50 CHECK (strength >= 0 AND strength <= 100),
    connection_type memory_connection_type NOT NULL DEFAULT 'associative',
    visual_style JSONB DEFAULT '{"thickness": 2, "luminosity": 0.5, "color": "#6366f1", "animated": false}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(source_node_id, target_node_id)
);

-- Table: memory_consolidation_jobs
CREATE TABLE IF NOT EXISTS memory_consolidation_jobs (
    job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Job specification
    job_type VARCHAR(50) NOT NULL, -- 'compress', 'decay', 'conflict_resolve', 'transfer', 'prune'
    target_memory_type VARCHAR(50), -- 'episodic', 'semantic', 'procedural', 'all'
    
    -- Scope
    time_range_start TIMESTAMPTZ,
    time_range_end TIMESTAMPTZ,
    memory_ids UUID[] DEFAULT '{}', -- Specific memories to process
    
    -- Configuration
    compression_ratio DECIMAL(3,2), -- Target compression (0.5 = 50% reduction)
    importance_threshold DECIMAL(3,2), -- Below this importance, memories are pruned
    conflict_resolution_strategy VARCHAR(50), -- 'newer_wins', 'higher_confidence', 'merge', 'flag_for_review'
    
    -- Results
    status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'running', 'completed', 'failed'
    memories_processed INTEGER DEFAULT 0,
    memories_compressed INTEGER DEFAULT 0,
    memories_pruned INTEGER DEFAULT 0,
    conflicts_found INTEGER DEFAULT 0,
    conflicts_resolved INTEGER DEFAULT 0,
    
    -- Outputs
    consolidated_memories UUID[] DEFAULT '{}', -- New consolidated memories created
    pruned_memories UUID[] DEFAULT '{}', -- Memories that were removed
    
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    error_message TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: memory_palaces
CREATE TABLE IF NOT EXISTS memory_palaces (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID, -- NULL for org-level
    name VARCHAR(255) NOT NULL,
    freshness_fog_config JSONB DEFAULT '{"enabled": true, "maxDensity": 0.8, "stalenessThresholdDays": 30}',
    last_explored_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    total_knowledge INTEGER DEFAULT 0,
    fresh_knowledge INTEGER DEFAULT 0,
    stale_knowledge INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, user_id, name)
);

-- Table: memory_relationships
CREATE TABLE IF NOT EXISTS memory_relationships (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_memory_id UUID NOT NULL REFERENCES memories(id) ON DELETE CASCADE,
    target_memory_id UUID NOT NULL REFERENCES memories(id) ON DELETE CASCADE,
    relationship_type VARCHAR(50) NOT NULL CHECK (relationship_type IN ('related', 'contradicts', 'supports', 'supersedes', 'derived_from')),
    strength DECIMAL(3, 2) DEFAULT 0.50 CHECK (strength >= 0 AND strength <= 1),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(source_memory_id, target_memory_id, relationship_type)
);

-- Table: memory_rooms
CREATE TABLE IF NOT EXISTS memory_rooms (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    palace_id UUID NOT NULL REFERENCES memory_palaces(id) ON DELETE CASCADE,
    parent_room_id UUID REFERENCES memory_rooms(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    domain VARCHAR(255) NOT NULL,
    position JSONB NOT NULL DEFAULT '{"x": 0, "y": 0, "z": 0}',
    size JSONB NOT NULL DEFAULT '{"width": 100, "height": 100, "depth": 100}',
    clarity INTEGER DEFAULT 100 CHECK (clarity >= 0 AND clarity <= 100),
    atmosphere JSONB DEFAULT '{"fogDensity": 0, "lightLevel": 100, "color": "#ffffff"}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: memory_stores
CREATE TABLE IF NOT EXISTS memory_stores (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    store_name VARCHAR(100) NOT NULL DEFAULT 'default',
    embedding_model VARCHAR(100) DEFAULT 'text-embedding-3-small',
    total_memories INTEGER DEFAULT 0,
    last_accessed TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, user_id, store_name)
);

-- Table: message_versions
CREATE TABLE IF NOT EXISTS message_versions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    message_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    snapshot_id UUID NOT NULL REFERENCES time_machine_snapshots(id) ON DELETE CASCADE,
    
    content TEXT NOT NULL,
    role VARCHAR(20) NOT NULL CHECK (role IN ('user', 'assistant', 'system')),
    model_id VARCHAR(100),
    
    version INTEGER NOT NULL,
    is_active BOOLEAN DEFAULT true,
    is_soft_deleted BOOLEAN DEFAULT false,
    
    edit_reason TEXT,
    edited_by UUID,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    superseded_at TIMESTAMPTZ
);

-- Table: metacognition_assessments_v2
CREATE TABLE IF NOT EXISTS metacognition_assessments_v2 (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  request_id UUID NOT NULL,
  overall_confidence DECIMAL(3,2) NOT NULL,
  logits_entropy DECIMAL(5,4),
  response_consistency DECIMAL(3,2),
  domain_match_score DECIMAL(3,2),
  historical_accuracy DECIMAL(3,2),
  suggested_action VARCHAR(20) NOT NULL CHECK (suggested_action IN ('proceed', 'escalate', 'clarify', 'defer')),
  actual_action_taken VARCHAR(20),
  escalated_to_model VARCHAR(100),
  self_correction_iterations INTEGER DEFAULT 0,
  final_user_satisfaction DECIMAL(3,2),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: metacognitive_settings
CREATE TABLE IF NOT EXISTS metacognitive_settings (
    setting_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Enable/disable features
    confidence_monitoring_enabled BOOLEAN DEFAULT true,
    error_detection_enabled BOOLEAN DEFAULT true,
    self_reflection_enabled BOOLEAN DEFAULT true,
    strategy_optimization_enabled BOOLEAN DEFAULT true,
    knowledge_boundary_tracking BOOLEAN DEFAULT true,
    
    -- Thresholds
    low_confidence_threshold DECIMAL(3,2) DEFAULT 0.5, -- Below this triggers extra scrutiny
    high_confidence_threshold DECIMAL(3,2) DEFAULT 0.9, -- Above this might indicate overconfidence
    error_severity_for_correction VARCHAR(20) DEFAULT 'major', -- Minimum severity to auto-correct
    
    -- Reflection schedule
    reflection_frequency VARCHAR(20) DEFAULT 'post_session', -- 'never', 'post_task', 'post_session', 'hourly', 'daily'
    max_reflections_per_day INTEGER DEFAULT 10,
    
    -- Self-improvement
    auto_generate_improvement_plans BOOLEAN DEFAULT true,
    max_active_improvement_plans INTEGER DEFAULT 5,
    
    -- Calibration
    calibration_window_days INTEGER DEFAULT 7,
    target_calibration_score DECIMAL(3,2) DEFAULT 0.1, -- Brier score target
    
    -- "I don't know" behavior
    admit_uncertainty_threshold DECIMAL(3,2) DEFAULT 0.3, -- Below this, admit uncertainty
    uncertainty_escalation_enabled BOOLEAN DEFAULT true, -- Escalate to human when uncertain
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: metadata_refresh_schedule
CREATE TABLE IF NOT EXISTS metadata_refresh_schedule (
    schedule_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Schedule name
    name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- What to refresh
    scope VARCHAR(50) NOT NULL, -- 'all', 'provider', 'model', 'category'
    scope_filter JSONB DEFAULT '{}', -- {provider: 'openai'} or {models: [...]}
    
    -- When to refresh
    schedule_type VARCHAR(20) NOT NULL, -- 'cron', 'interval', 'manual'
    cron_expression VARCHAR(100), -- e.g., '0 0 * * *' for daily at midnight
    interval_hours INTEGER,
    
    -- Research settings
    research_depth VARCHAR(20) DEFAULT 'standard', -- 'quick', 'standard', 'deep'
    include_benchmarks BOOLEAN DEFAULT true,
    include_pricing BOOLEAN DEFAULT true,
    include_availability BOOLEAN DEFAULT true,
    
    -- Notification
    notify_on_changes BOOLEAN DEFAULT true,
    notify_email TEXT,
    
    -- Status
    enabled BOOLEAN DEFAULT true,
    last_run TIMESTAMPTZ,
    next_run TIMESTAMPTZ,
    last_run_status VARCHAR(20),
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: metadata_research_history
CREATE TABLE IF NOT EXISTS metadata_research_history (
    research_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- What was researched
    model_id VARCHAR(200),
    research_type VARCHAR(50) NOT NULL, -- 'scheduled', 'manual', 'new_model', 'triggered'
    
    -- Sources used
    sources_queried UUID[] DEFAULT '{}',
    sources_successful UUID[] DEFAULT '{}',
    
    -- Findings
    raw_findings JSONB DEFAULT '{}', -- Raw data from sources
    ai_synthesis JSONB DEFAULT '{}', -- AI-processed findings
    
    -- Changes made
    fields_updated TEXT[] DEFAULT '{}',
    previous_values JSONB DEFAULT '{}',
    new_values JSONB DEFAULT '{}',
    
    -- AI reasoning
    ai_confidence DECIMAL(5,4),
    ai_reasoning TEXT,
    conflicts_detected JSONB DEFAULT '[]', -- Conflicting info from sources
    conflict_resolution TEXT,
    
    -- Status
    status VARCHAR(20) DEFAULT 'completed', -- 'pending', 'in_progress', 'completed', 'failed'
    error_message TEXT,
    
    -- Admin review
    requires_review BOOLEAN DEFAULT false,
    reviewed_by VARCHAR(200),
    review_decision VARCHAR(20), -- 'approved', 'rejected', 'modified'
    review_notes TEXT,
    
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    duration_ms INTEGER
);

-- Table: metadata_sources
CREATE TABLE IF NOT EXISTS metadata_sources (
    source_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Source identification
    name VARCHAR(200) NOT NULL,
    source_type VARCHAR(50) NOT NULL, -- 'official_api', 'documentation', 'benchmark', 'news', 'research_paper'
    url TEXT,
    
    -- Reliability
    trust_score DECIMAL(5,4) DEFAULT 0.5, -- How reliable is this source
    is_official BOOLEAN DEFAULT false,
    
    -- Access
    requires_auth BOOLEAN DEFAULT false,
    api_key_env_var VARCHAR(100),
    rate_limit_per_hour INTEGER,
    
    -- Parsing
    parser_type VARCHAR(50), -- 'json', 'html', 'rss', 'api'
    parser_config JSONB DEFAULT '{}',
    
    -- Schedule
    refresh_interval_hours INTEGER DEFAULT 24,
    last_fetched TIMESTAMPTZ,
    next_fetch TIMESTAMPTZ,
    
    enabled BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: metadata_validation_rules
CREATE TABLE IF NOT EXISTS metadata_validation_rules (
    rule_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Rule definition
    name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- What to validate
    field_name VARCHAR(100) NOT NULL,
    validation_type VARCHAR(50) NOT NULL, -- 'required', 'min_value', 'max_value', 'pattern', 'enum', 'custom'
    validation_config JSONB NOT NULL,
    
    -- Severity
    severity VARCHAR(20) DEFAULT 'error', -- 'error', 'warning', 'info'
    
    -- When to apply
    applies_to_providers TEXT[] DEFAULT '{}', -- Empty = all
    applies_to_categories TEXT[] DEFAULT '{}',
    
    enabled BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: mfa_audit_log
CREATE TABLE IF NOT EXISTS mfa_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_type VARCHAR(20) NOT NULL,
  user_id UUID NOT NULL,
  tenant_id UUID,
  event_type VARCHAR(50) NOT NULL,
  details JSONB,
  ip_address INET,
  user_agent TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
) PARTITION BY RANGE (created_at);

-- Table: mfa_backup_codes
CREATE TABLE IF NOT EXISTS mfa_backup_codes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_type VARCHAR(20) NOT NULL CHECK (user_type IN ('tenant_user', 'platform_admin')),
  user_id UUID NOT NULL,
  code_hash VARCHAR(255) NOT NULL,
  is_used BOOLEAN NOT NULL DEFAULT false,
  used_at TIMESTAMPTZ,
  used_ip INET,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT mfa_backup_codes_user_idx UNIQUE (user_type, user_id, code_hash)
);

-- Table: mfa_trusted_devices
CREATE TABLE IF NOT EXISTS mfa_trusted_devices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_type VARCHAR(20) NOT NULL CHECK (user_type IN ('tenant_user', 'platform_admin')),
  user_id UUID NOT NULL,
  device_token_hash VARCHAR(64) NOT NULL,
  device_name VARCHAR(255),
  device_fingerprint VARCHAR(255),
  trusted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL,
  last_used_at TIMESTAMPTZ,
  last_used_ip INET,
  is_revoked BOOLEAN NOT NULL DEFAULT false,
  revoked_at TIMESTAMPTZ,
  revoked_reason VARCHAR(100),
  CONSTRAINT mfa_trusted_devices_unique UNIQUE (user_type, user_id, device_token_hash)
);

-- Table: migration_approval_policies
CREATE TABLE IF NOT EXISTS migration_approval_policies (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    environment VARCHAR(20) NOT NULL,
    
    approvals_required INTEGER NOT NULL DEFAULT 2,
    self_approval_allowed BOOLEAN DEFAULT false,
    auto_approve_development BOOLEAN DEFAULT true,
    
    allowed_approvers UUID[] DEFAULT '{}',
    required_approvers UUID[],
    
    notification_channels JSONB DEFAULT '{}',
    escalation_after_hours INTEGER DEFAULT 24,
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id, environment)
);

-- Table: migration_approval_requests
CREATE TABLE IF NOT EXISTS migration_approval_requests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    migration_name VARCHAR(255) NOT NULL,
    migration_version VARCHAR(50) NOT NULL,
    migration_checksum VARCHAR(64) NOT NULL,
    migration_sql TEXT NOT NULL,
    
    environment VARCHAR(20) NOT NULL CHECK (environment IN ('development', 'staging', 'production')),
    
    requested_by UUID NOT NULL,
    requested_at TIMESTAMPTZ DEFAULT NOW(),
    request_reason TEXT,
    
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN (
        'pending', 'approved', 'rejected', 'executed', 'failed', 'cancelled'
    )),
    
    approvals_required INTEGER NOT NULL DEFAULT 2,
    approvals_received INTEGER NOT NULL DEFAULT 0,
    
    executed_at TIMESTAMPTZ,
    executed_by UUID,
    execution_time_ms INTEGER,
    execution_error TEXT,
    rollback_sql TEXT,
    
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: migration_approvals
CREATE TABLE IF NOT EXISTS migration_approvals (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    request_id UUID NOT NULL REFERENCES migration_approval_requests(id) ON DELETE CASCADE,
    
    admin_id UUID NOT NULL,
    decision VARCHAR(20) NOT NULL CHECK (decision IN ('approved', 'rejected')),
    reason TEXT,
    
    reviewed_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(request_id, admin_id)
);

-- Table: minority_reports
CREATE TABLE IF NOT EXISTS minority_reports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES council_sessions(id) ON DELETE CASCADE,
    expert_id UUID NOT NULL REFERENCES council_experts(id) ON DELETE CASCADE,
    position TEXT NOT NULL,
    reasoning TEXT NOT NULL,
    validity_score INTEGER DEFAULT 50 CHECK (validity_score >= 0 AND validity_score <= 100),
    visual_panel JSONB DEFAULT '{"opacity": 0.7, "ghostStyle": true}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: ml_inference_log
CREATE TABLE IF NOT EXISTS ml_inference_log (
    inference_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    model_type VARCHAR(100) NOT NULL,
    model_version_id UUID REFERENCES ml_model_versions(version_id),
    
    -- Input
    input_features JSONB NOT NULL,
    
    -- Prediction
    prediction JSONB NOT NULL,
    confidence DECIMAL(5,4),
    latency_ms INTEGER,
    
    -- Outcome (filled in later)
    actual_outcome JSONB,
    was_correct BOOLEAN,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ml_model_versions
CREATE TABLE IF NOT EXISTS ml_model_versions (
    version_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    model_type VARCHAR(100) NOT NULL,
    version_number INTEGER NOT NULL,
    
    -- Training info
    training_batch_id UUID REFERENCES ml_training_batches(batch_id),
    
    -- Deployment
    sagemaker_endpoint VARCHAR(200),
    is_active BOOLEAN DEFAULT false,
    
    -- Performance
    accuracy DECIMAL(5,4),
    latency_p50_ms INTEGER,
    latency_p99_ms INTEGER,
    
    -- A/B testing
    traffic_percentage INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    activated_at TIMESTAMPTZ,
    deactivated_at TIMESTAMPTZ,
    
    UNIQUE(model_type, version_number)
);

-- Table: ml_routing_training_data
CREATE TABLE IF NOT EXISTS ml_routing_training_data (
    sample_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Input features
    task_text TEXT NOT NULL,
    task_embedding VECTOR(1536), -- For semantic similarity
    detected_specialty VARCHAR(100),
    detected_complexity VARCHAR(20), -- 'simple', 'moderate', 'complex'
    detected_modalities TEXT[] DEFAULT '{}', -- 'text', 'code', 'math', 'vision'
    context_features JSONB DEFAULT '{}', -- user history, session context
    
    -- Routing decision
    models_considered TEXT[] NOT NULL,
    model_selected VARCHAR(200) NOT NULL,
    routing_strategy VARCHAR(50), -- 'single', 'ensemble', 'chain'
    selection_reason TEXT,
    
    -- Outcome (for supervised learning)
    quality_score DECIMAL(5,4),
    latency_ms INTEGER,
    cost_cents DECIMAL(10,4),
    user_feedback VARCHAR(20), -- 'positive', 'negative', 'neutral', NULL
    user_feedback_text TEXT,
    was_retry BOOLEAN DEFAULT false,
    
    -- Computed label for training
    was_good_choice BOOLEAN, -- Computed from quality + feedback
    optimal_model VARCHAR(200), -- What model SHOULD have been used (hindsight)
    
    -- Training metadata
    used_for_training BOOLEAN DEFAULT false,
    training_batch_id UUID,
    exported_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ml_training_batches
CREATE TABLE IF NOT EXISTS ml_training_batches (
    batch_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Batch info
    batch_name VARCHAR(200) NOT NULL,
    model_type VARCHAR(100) NOT NULL, -- 'routing', 'quality_prediction', 'specialty_detection'
    
    -- Data stats
    samples_count INTEGER NOT NULL,
    train_samples INTEGER,
    validation_samples INTEGER,
    test_samples INTEGER,
    
    -- Training config
    base_model VARCHAR(200), -- 'mistral-7b', 'llama-3-8b', etc.
    hyperparameters JSONB DEFAULT '{}',
    
    -- Status
    status VARCHAR(30) DEFAULT 'pending', -- 'pending', 'exporting', 'training', 'evaluating', 'completed', 'failed'
    
    -- S3 locations
    training_data_s3 TEXT,
    model_artifact_s3 TEXT,
    
    -- SageMaker
    sagemaker_training_job VARCHAR(200),
    sagemaker_endpoint VARCHAR(200),
    
    -- Results
    training_metrics JSONB DEFAULT '{}',
    evaluation_metrics JSONB DEFAULT '{}',
    
    -- Timestamps
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: mls_audit_log
CREATE TABLE IF NOT EXISTS mls_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id VARCHAR(64),
  
  -- Operation
  action VARCHAR(50) NOT NULL,  -- create_group, add_member, remove_member, send_message, etc.
  group_id UUID,
  member_id VARCHAR(128),
  
  -- Actor
  performed_by VARCHAR(128) NOT NULL,
  
  -- Details
  details JSONB DEFAULT '{}',
  
  -- Context
  ip_address INET,
  user_agent TEXT,
  
  -- Timestamp
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: mls_commits
CREATE TABLE IF NOT EXISTS mls_commits (
  commit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id UUID NOT NULL REFERENCES mls_groups(group_id) ON DELETE CASCADE,
  epoch INTEGER NOT NULL,
  
  -- Proposal details
  proposal_type mls_proposal_type NOT NULL,
  proposer_id VARCHAR(128) NOT NULL,
  target_member_id VARCHAR(128),
  
  -- Cryptographic proof
  signature TEXT NOT NULL,
  
  -- Metadata
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT unique_epoch_commit UNIQUE (group_id, epoch)
);

-- Table: mls_epoch_secrets
CREATE TABLE IF NOT EXISTS mls_epoch_secrets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id UUID NOT NULL REFERENCES mls_groups(group_id) ON DELETE CASCADE,
  epoch INTEGER NOT NULL,
  
  -- Encrypted secret for this epoch
  secret_encrypted TEXT NOT NULL,
  
  -- Lifecycle
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ,  -- When this epoch's secrets should be deleted (forward secrecy)
  
  CONSTRAINT unique_group_epoch UNIQUE (group_id, epoch)
);

-- Table: mls_group_members
CREATE TABLE IF NOT EXISTS mls_group_members (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id UUID NOT NULL REFERENCES mls_groups(group_id) ON DELETE CASCADE,
  member_id VARCHAR(128) NOT NULL,
  member_type mls_member_type NOT NULL,
  
  -- Key material
  key_package_id UUID NOT NULL REFERENCES mls_key_packages(key_package_id),
  public_key TEXT NOT NULL,
  
  -- Tree position
  leaf_index INTEGER NOT NULL,
  
  -- Membership lifecycle
  added_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  added_by VARCHAR(128) NOT NULL,
  removed_at TIMESTAMPTZ,
  removed_by VARCHAR(128),
  
  CONSTRAINT unique_member_in_group UNIQUE (group_id, member_id, removed_at),
  CONSTRAINT valid_leaf_index CHECK (leaf_index >= 0)
);

-- Table: mls_groups
CREATE TABLE IF NOT EXISTS mls_groups (
  group_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id VARCHAR(64) NOT NULL,
  name VARCHAR(256) NOT NULL,
  
  -- MLS State
  cipher_suite mls_cipher_suite NOT NULL DEFAULT 'MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519',
  epoch INTEGER NOT NULL DEFAULT 0,
  tree_hash VARCHAR(64) NOT NULL,        -- SHA-256 of ratchet tree
  
  -- Group secrets (encrypted)
  confirmation_key TEXT NOT NULL,        -- For confirming commits
  group_secret_encrypted TEXT NOT NULL,  -- Encrypted group secret
  
  -- Lifecycle
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ,
  
  CONSTRAINT valid_epoch CHECK (epoch >= 0)
);

-- Table: mls_key_packages
CREATE TABLE IF NOT EXISTS mls_key_packages (
  key_package_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  member_id VARCHAR(128) NOT NULL,
  member_type mls_member_type NOT NULL,
  
  -- Cryptographic keys (Base64 encoded)
  public_key TEXT NOT NULL,              -- X25519 public key for ECDH
  signature_key TEXT NOT NULL,           -- Ed25519 public key for signatures
  private_key_encrypted TEXT NOT NULL,   -- Encrypted X25519 private key
  sig_private_key_encrypted TEXT NOT NULL, -- Encrypted Ed25519 private key
  
  -- Identity
  credential TEXT NOT NULL,              -- Member credential/identity claim
  cipher_suite mls_cipher_suite NOT NULL DEFAULT 'MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519',
  
  -- Lifecycle
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  
  -- Indexes will be created below
  CONSTRAINT valid_expiry CHECK (expires_at > created_at)
);

-- Table: mls_messages
CREATE TABLE IF NOT EXISTS mls_messages (
  message_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id UUID NOT NULL REFERENCES mls_groups(group_id) ON DELETE CASCADE,
  epoch INTEGER NOT NULL,
  
  -- Sender
  sender_id VARCHAR(128) NOT NULL,
  content_type mls_content_type NOT NULL DEFAULT 'application',
  
  -- Encrypted payload
  ciphertext TEXT NOT NULL,
  iv TEXT NOT NULL,
  auth_tag TEXT NOT NULL,
  
  -- Authentication
  signature TEXT NOT NULL,
  
  -- Metadata
  sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  -- For efficient retrieval
  CONSTRAINT valid_message_epoch CHECK (epoch >= 0)
);

-- Table: mode_model_rankings
CREATE TABLE IF NOT EXISTS mode_model_rankings (
    ranking_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mode TEXT NOT NULL,
    model_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    
    score DECIMAL(5,2) NOT NULL DEFAULT 0,
    tier TEXT CHECK (tier IN ('S', 'A', 'B', 'C', 'D', 'F')) DEFAULT 'C',
    
    strengths JSONB DEFAULT '[]'::jsonb,
    weaknesses JSONB DEFAULT '[]'::jsonb,
    recommended_for JSONB DEFAULT '[]'::jsonb,
    not_recommended_for JSONB DEFAULT '[]'::jsonb,
    
    confidence DECIMAL(3,2) DEFAULT 0.5,
    admin_override DECIMAL(5,2),
    is_locked BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT uq_mode_model UNIQUE (mode, model_id)
);

-- Table: mode_rankings
CREATE TABLE IF NOT EXISTS mode_rankings (
    ranking_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mode_id TEXT NOT NULL,
    mode_name TEXT NOT NULL,
    mode_type TEXT CHECK (mode_type IN ('domain', 'orchestration', 'persona')) NOT NULL,
    specialty TEXT NOT NULL,
    
    -- Ranked models for this mode+specialty
    ranked_models JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Mode-specific tuning
    prompt_modifiers JSONB DEFAULT '[]'::jsonb,
    temperature_adjustment DECIMAL(3,2) DEFAULT 0.7,
    system_prompt_additions JSONB DEFAULT '[]'::jsonb,
    
    confidence DECIMAL(3,2) DEFAULT 0.5,
    last_researched TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT uq_mode_specialty UNIQUE (mode_id, specialty)
);

-- Table: model_aliases
CREATE TABLE IF NOT EXISTS model_aliases (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    alias VARCHAR(100) NOT NULL,
    model_id UUID NOT NULL REFERENCES models(id) ON DELETE CASCADE,
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    priority INTEGER NOT NULL DEFAULT 0,
    is_default BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (alias, tenant_id)
);

-- Table: model_deletion_queue
CREATE TABLE IF NOT EXISTS model_deletion_queue (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  model_version_id UUID NOT NULL REFERENCES model_versions(id) ON DELETE CASCADE,
  model_id TEXT NOT NULL,
  version TEXT NOT NULL,
  
  -- Deletion request
  requested_by TEXT NOT NULL, -- User ID
  requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  reason TEXT,
  
  -- Queue status
  status TEXT NOT NULL DEFAULT 'pending', -- 'pending', 'blocked', 'processing', 'completed', 'cancelled', 'failed'
  blocked_reason TEXT, -- e.g., 'model_in_use', 'has_active_sessions'
  
  -- Usage at time of request
  active_sessions INTEGER DEFAULT 0,
  requests_last_24h INTEGER DEFAULT 0,
  last_request_at TIMESTAMPTZ,
  
  -- Processing
  processing_started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  -- What was deleted
  s3_objects_deleted INTEGER,
  sagemaker_resources_deleted TEXT[],
  
  -- Error tracking
  error_message TEXT,
  retry_count INTEGER DEFAULT 0,
  next_retry_at TIMESTAMPTZ,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_dependencies
CREATE TABLE IF NOT EXISTS model_dependencies (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id UUID NOT NULL REFERENCES ai_models(id) ON DELETE CASCADE,
    
    dependency_type VARCHAR(50) NOT NULL CHECK (dependency_type IN ('base_model', 'dataset', 'framework', 'library', 'weights')),
    dependency_name VARCHAR(200) NOT NULL,
    dependency_version VARCHAR(50),
    dependency_url VARCHAR(500),
    
    dependency_size_gb DECIMAL(10, 2),
    dependency_license VARCHAR(100),
    
    is_required BOOLEAN DEFAULT true,
    notes TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_discovery_jobs
CREATE TABLE IF NOT EXISTS model_discovery_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- Job details
  job_type TEXT NOT NULL DEFAULT 'scheduled', -- 'scheduled', 'manual', 'webhook'
  triggered_by TEXT, -- User ID or 'system'
  
  -- Progress
  status TEXT NOT NULL DEFAULT 'pending', -- 'pending', 'running', 'completed', 'failed', 'cancelled'
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  duration_ms INTEGER,
  
  -- Results
  families_checked INTEGER DEFAULT 0,
  models_discovered INTEGER DEFAULT 0,
  models_added INTEGER DEFAULT 0,
  downloads_started INTEGER DEFAULT 0,
  
  -- Errors
  errors JSONB DEFAULT '[]'::jsonb,
  warnings JSONB DEFAULT '[]'::jsonb,
  
  -- Detailed results per family
  family_results JSONB DEFAULT '{}'::jsonb,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_discovery_log
CREATE TABLE IF NOT EXISTS model_discovery_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(100) NOT NULL,
    discovery_source VARCHAR(50) NOT NULL, -- 'admin', 'registry_sync', 'huggingface', 'auto'
    discovered_by UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Discovery details
    model_family VARCHAR(50),
    parameter_count VARCHAR(20),
    capabilities_detected TEXT[],
    
    -- Proficiency generation
    proficiencies_generated BOOLEAN DEFAULT false,
    generation_timestamp TIMESTAMPTZ,
    generation_duration_ms INTEGER,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'pending', -- 'pending', 'processing', 'completed', 'failed'
    error_message TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_endpoints
CREATE TABLE IF NOT EXISTS model_endpoints (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(200) NOT NULL REFERENCES model_registry(model_id) ON DELETE CASCADE,
    
    -- Endpoint details
    endpoint_type VARCHAR(30) NOT NULL CHECK (endpoint_type IN (
        'openai_compatible', 'anthropic_compatible', 'sagemaker', 'bedrock', 'custom_rest', 'custom_grpc'
    )),
    base_url TEXT NOT NULL,
    path TEXT,
    method VARCHAR(10) NOT NULL DEFAULT 'POST' CHECK (method IN ('POST', 'GET')),
    
    -- Authentication
    auth_method VARCHAR(30) NOT NULL CHECK (auth_method IN (
        'api_key', 'bearer_token', 'aws_sig_v4', 'oauth2', 'custom_header', 'none'
    )),
    auth_config JSONB,
    
    -- Request/Response format
    request_format JSONB,
    response_format JSONB,
    response_mapping JSONB,
    
    -- Limits and quotas
    rate_limit_rpm INTEGER,
    rate_limit_tpm INTEGER,
    max_concurrent INTEGER,
    timeout_ms INTEGER DEFAULT 30000,
    
    -- Health monitoring
    health_check_url TEXT,
    health_check_interval INTEGER DEFAULT 300, -- seconds
    last_health_check TIMESTAMPTZ,
    health_status VARCHAR(20) NOT NULL DEFAULT 'unknown' CHECK (health_status IN ('healthy', 'degraded', 'unhealthy', 'unknown')),
    consecutive_failures INTEGER DEFAULT 0,
    
    -- Priority and status
    priority INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_execution_logs
CREATE TABLE IF NOT EXISTS model_execution_logs (
    id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    request_id UUID NOT NULL,
    user_id UUID,
    model_id VARCHAR(100) NOT NULL,
    model_provider VARCHAR(50),
    prompt_tokens INTEGER DEFAULT 0,
    completion_tokens INTEGER DEFAULT 0,
    total_tokens INTEGER GENERATED ALWAYS AS (prompt_tokens + completion_tokens) STORED,
    latency_ms INTEGER,
    response_hash TEXT,
    status VARCHAR(20) DEFAULT 'completed',
    error_message TEXT,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Composite primary key with tenant_id first for data locality
    PRIMARY KEY (tenant_id, id, created_at)
);

-- Table: model_execution_logs_partitioned
CREATE TABLE IF NOT EXISTS model_execution_logs_partitioned (
    id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    request_id UUID NOT NULL,
    user_id UUID,
    model_id VARCHAR(100) NOT NULL,
    model_provider VARCHAR(50),
    prompt_tokens INTEGER DEFAULT 0,
    completion_tokens INTEGER DEFAULT 0,
    total_tokens INTEGER GENERATED ALWAYS AS (prompt_tokens + completion_tokens) STORED,
    latency_ms INTEGER,
    response_hash TEXT,
    status VARCHAR(20) DEFAULT 'completed',
    error_message TEXT,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Composite primary key includes partition key (created_at)
    PRIMARY KEY (tenant_id, id, created_at)
) PARTITION BY RANGE (created_at);

-- Table: model_family_watchlist
CREATE TABLE IF NOT EXISTS model_family_watchlist (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  family TEXT NOT NULL UNIQUE,
  
  -- Watch configuration
  is_enabled BOOLEAN DEFAULT true,
  auto_download BOOLEAN DEFAULT false, -- Automatically download new versions
  auto_deploy BOOLEAN DEFAULT false, -- Automatically deploy new versions
  auto_thermal_tier TEXT DEFAULT 'cold', -- Default thermal state for new versions
  
  -- HuggingFace search config
  huggingface_org TEXT, -- e.g., 'meta-llama', 'Qwen', 'deepseek-ai'
  huggingface_filter TEXT, -- Additional filter query
  min_likes INTEGER DEFAULT 100, -- Only consider models with this many likes
  include_gated BOOLEAN DEFAULT false, -- Include gated models
  
  -- Notification settings
  notify_on_new_version BOOLEAN DEFAULT true,
  notification_emails TEXT[],
  notification_webhook TEXT,
  
  -- Last check
  last_checked_at TIMESTAMPTZ,
  last_check_status TEXT,
  last_check_error TEXT,
  versions_found INTEGER DEFAULT 0,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_format_understanding
CREATE TABLE IF NOT EXISTS model_format_understanding (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Model identification
    model_id VARCHAR(200) NOT NULL,
    provider_id VARCHAR(100) NOT NULL,
    
    -- Format information
    file_format VARCHAR(50) NOT NULL,
    mime_type VARCHAR(200),
    
    -- Understanding metrics (0.0 to 1.0)
    understanding_score DECIMAL(4,3) NOT NULL DEFAULT 0.5,
    confidence DECIMAL(4,3) NOT NULL DEFAULT 0.1,
    
    -- Tracking
    success_count INTEGER NOT NULL DEFAULT 0,
    failure_count INTEGER NOT NULL DEFAULT 0,
    total_attempts INTEGER NOT NULL DEFAULT 0,
    
    -- Override flags
    force_convert BOOLEAN NOT NULL DEFAULT false,
    force_convert_reason TEXT,
    force_convert_set_at TIMESTAMPTZ,
    force_convert_set_by UUID REFERENCES users(id),
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_evaluated_at TIMESTAMPTZ,
    
    -- Unique constraint per tenant/model/format
    UNIQUE(tenant_id, model_id, file_format)
);

-- Table: model_language_capabilities
CREATE TABLE IF NOT EXISTS model_language_capabilities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    matrix_id UUID NOT NULL REFERENCES model_language_matrices(id) ON DELETE CASCADE,
    language_code VARCHAR(10) NOT NULL,
    support_level VARCHAR(20) NOT NULL, -- native, good, moderate, poor, none
    quality_score INTEGER NOT NULL CHECK (quality_score >= 0 AND quality_score <= 100),
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(matrix_id, language_code)
);

-- Table: model_language_matrices
CREATE TABLE IF NOT EXISTS model_language_matrices (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    model_id VARCHAR(100) NOT NULL UNIQUE,
    primary_language VARCHAR(10) NOT NULL DEFAULT 'en',
    translate_threshold VARCHAR(20) NOT NULL DEFAULT 'moderate', -- native, good, moderate, poor, none
    is_external BOOLEAN NOT NULL DEFAULT false, -- External API models (Claude, GPT-4)
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_licenses
CREATE TABLE IF NOT EXISTS model_licenses (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id UUID NOT NULL REFERENCES ai_models(id) ON DELETE CASCADE,
    
    license_type VARCHAR(50) NOT NULL CHECK (license_type IN ('open_source', 'proprietary', 'academic', 'commercial', 'custom')),
    license_spdx VARCHAR(50),
    license_name VARCHAR(200) NOT NULL,
    license_url VARCHAR(500),
    
    commercial_use BOOLEAN DEFAULT true,
    commercial_notes TEXT,
    attribution_required BOOLEAN DEFAULT false,
    attribution_text TEXT,
    share_alike BOOLEAN DEFAULT false,
    modifications_allowed BOOLEAN DEFAULT true,
    
    compliance_status VARCHAR(20) DEFAULT 'pending' CHECK (compliance_status IN ('compliant', 'pending', 'review_needed', 'non_compliant')),
    last_compliance_review TIMESTAMPTZ,
    reviewed_by UUID,
    compliance_notes TEXT,
    
    expires_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_metadata
CREATE TABLE IF NOT EXISTS model_metadata (
    metadata_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    model_id VARCHAR(200) NOT NULL UNIQUE,
    
    -- Basic identification
    provider VARCHAR(100) NOT NULL,
    model_name VARCHAR(300) NOT NULL,
    model_family VARCHAR(100), -- 'gpt', 'claude', 'llama', 'gemini', etc.
    version VARCHAR(50),
    release_date DATE,
    
    -- Capabilities
    capabilities JSONB DEFAULT '{}', -- {reasoning, coding, vision, etc.}
    supported_modalities JSONB DEFAULT '{}', -- {input: [], output: []}
    specialties TEXT[] DEFAULT '{}', -- What it's particularly good at
    weaknesses TEXT[] DEFAULT '{}', -- Known limitations
    
    -- Technical specs
    context_window INTEGER,
    max_output_tokens INTEGER,
    training_cutoff DATE,
    parameter_count BIGINT, -- In billions
    architecture VARCHAR(100), -- 'transformer', 'moe', etc.
    
    -- Performance benchmarks
    benchmarks JSONB DEFAULT '{}', -- {mmlu: 0.89, humaneval: 0.85, etc.}
    benchmark_date DATE,
    
    -- Pricing
    input_price_per_1m DECIMAL(10,4),
    output_price_per_1m DECIMAL(10,4),
    price_currency VARCHAR(10) DEFAULT 'USD',
    price_updated_at TIMESTAMPTZ,
    
    -- Availability
    regions_available TEXT[] DEFAULT '{}',
    api_endpoints JSONB DEFAULT '{}',
    rate_limits JSONB DEFAULT '{}', -- {rpm, tpm, rpd}
    
    -- Usage guidelines
    best_use_cases JSONB DEFAULT '[]',
    not_recommended_for JSONB DEFAULT '[]',
    prompt_tips JSONB DEFAULT '[]',
    system_prompt_support BOOLEAN DEFAULT true,
    function_calling_support BOOLEAN DEFAULT false,
    json_mode_support BOOLEAN DEFAULT false,
    streaming_support BOOLEAN DEFAULT true,
    
    -- Safety & Compliance
    content_filtering JSONB DEFAULT '{}',
    safety_settings JSONB DEFAULT '{}',
    compliance_certifications TEXT[] DEFAULT '{}', -- 'SOC2', 'HIPAA', etc.
    data_retention_policy TEXT,
    
    -- Documentation links
    official_docs_url TEXT,
    api_reference_url TEXT,
    changelog_url TEXT,
    
    -- Quality indicators
    reliability_score DECIMAL(5,4), -- Based on uptime/errors
    quality_score DECIMAL(5,4), -- Based on user feedback
    speed_score DECIMAL(5,4), -- Based on latency
    value_score DECIMAL(5,4), -- Quality per cost
    
    -- Metadata status
    metadata_completeness DECIMAL(5,4) DEFAULT 0, -- How complete is this metadata
    metadata_confidence DECIMAL(5,4) DEFAULT 0.5, -- Confidence in accuracy
    last_verified TIMESTAMPTZ,
    verification_source VARCHAR(100),
    
    -- Admin control
    admin_notes TEXT,
    admin_override JSONB DEFAULT '{}', -- Admin can override any field
    
    -- Flags
    is_available BOOLEAN DEFAULT true,
    is_deprecated BOOLEAN DEFAULT false,
    deprecation_date DATE,
    successor_model_id VARCHAR(200),
    requires_approval BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: model_orchestration_preferences
CREATE TABLE IF NOT EXISTS model_orchestration_preferences (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Preferences
    preferred_families TEXT[] DEFAULT '{}',
    excluded_families TEXT[] DEFAULT '{}',
    preferred_models TEXT[] DEFAULT '{}',
    excluded_models TEXT[] DEFAULT '{}',
    
    -- Constraints
    max_cost_per_1m DECIMAL(10, 4),
    require_commercial_use BOOLEAN DEFAULT false,
    prefer_self_hosted BOOLEAN DEFAULT false,
    min_quality_tier VARCHAR(20) DEFAULT 'economy',
    max_latency_class VARCHAR(20) DEFAULT 'slow',
    
    -- Domain preferences
    domain_overrides JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: model_output_distributions
CREATE TABLE IF NOT EXISTS model_output_distributions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    
    -- Distribution type
    distribution_type VARCHAR(100) NOT NULL, -- 'response_length', 'sentiment', 'toxicity', 'embedding'
    period_type VARCHAR(50) NOT NULL, -- 'reference', 'current'
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    
    -- Distribution statistics
    sample_count INTEGER NOT NULL,
    mean_value DOUBLE PRECISION,
    median_value DOUBLE PRECISION,
    stddev_value DOUBLE PRECISION,
    min_value DOUBLE PRECISION,
    max_value DOUBLE PRECISION,
    percentiles JSONB DEFAULT '{}', -- {p5, p25, p50, p75, p95}
    
    -- Histogram data for PSI calculation
    histogram_bins JSONB DEFAULT '[]', -- [{bin_start, bin_end, count}]
    
    -- Embedding centroid for embedding drift
    embedding_centroid VECTOR(1536),
    embedding_spread DOUBLE PRECISION, -- Average distance from centroid
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: model_performance
CREATE TABLE IF NOT EXISTS model_performance (
    model_id VARCHAR(200) PRIMARY KEY,
    provider VARCHAR(50) NOT NULL,
    
    -- Performance metrics
    total_requests INTEGER DEFAULT 0,
    successful_requests INTEGER DEFAULT 0,
    failed_requests INTEGER DEFAULT 0,
    
    -- Latency tracking
    avg_latency_ms DECIMAL(10,2) DEFAULT 0,
    min_latency_ms INTEGER,
    max_latency_ms INTEGER,
    p50_latency_ms INTEGER,
    p95_latency_ms INTEGER,
    p99_latency_ms INTEGER,
    
    -- Token tracking
    total_input_tokens BIGINT DEFAULT 0,
    total_output_tokens BIGINT DEFAULT 0,
    avg_tokens_per_request DECIMAL(10,2) DEFAULT 0,
    
    -- Cost tracking
    total_cost_cents BIGINT DEFAULT 0,
    avg_cost_per_request_cents DECIMAL(10,4) DEFAULT 0,
    
    -- Quality metrics (from user feedback/metacognition)
    quality_score DECIMAL(5,4),
    quality_samples INTEGER DEFAULT 0,
    
    -- Availability
    is_available BOOLEAN DEFAULT true,
    last_available_check TIMESTAMPTZ,
    downtime_count INTEGER DEFAULT 0,
    
    first_used TIMESTAMPTZ DEFAULT NOW(),
    last_used TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: model_pricing_overrides
CREATE TABLE IF NOT EXISTS model_pricing_overrides (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(100) NOT NULL,
    custom_input_price DECIMAL(10, 6),
    custom_output_price DECIMAL(10, 6),
    markup_percent DECIMAL(5, 4),
    is_enabled BOOLEAN DEFAULT TRUE,
    effective_from TIMESTAMPTZ,
    effective_until TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, model_id)
);

-- Table: model_proficiency_rankings
CREATE TABLE IF NOT EXISTS model_proficiency_rankings (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(100) NOT NULL REFERENCES self_hosted_model_metadata(model_id) ON DELETE CASCADE,
    
    -- Domain proficiencies (0-100 scores)
    domain VARCHAR(100) NOT NULL,
    subspecialty VARCHAR(100),
    proficiency_score DECIMAL(5, 2) NOT NULL DEFAULT 0,
    rank_in_domain INTEGER NOT NULL DEFAULT 0,
    strength_level VARCHAR(20) NOT NULL DEFAULT 'basic',
    
    -- Orchestration mode proficiencies
    orchestration_mode VARCHAR(50),
    mode_score DECIMAL(5, 2),
    rank_in_mode INTEGER,
    
    -- Computed metrics
    capability_match_count INTEGER DEFAULT 0,
    total_capabilities INTEGER DEFAULT 0,
    
    -- Timestamps
    computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(model_id, domain, subspecialty, orchestration_mode)
);

-- Table: model_rating_summary
CREATE TABLE IF NOT EXISTS model_rating_summary (
    summary_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    model_id VARCHAR(100) NOT NULL,
    model_name VARCHAR(200),
    
    -- Overall metrics
    total_ratings INTEGER NOT NULL DEFAULT 0,
    average_rating DECIMAL(4,2),
    net_sentiment_score SMALLINT,
    
    -- Dimension breakdown
    dimension_averages JSONB DEFAULT '{}'::jsonb,
    
    -- Strengths and weaknesses
    strength_dimensions JSONB DEFAULT '[]'::jsonb,
    weakness_dimensions JSONB DEFAULT '[]'::jsonb,
    
    -- Ranking
    rank_among_models INTEGER,
    percentile DECIMAL(5,2),
    
    -- Trend
    trend VARCHAR(20),
    trend_percentage DECIMAL(5,2),
    
    -- Timestamps
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    CONSTRAINT unique_model_summary UNIQUE (tenant_id, model_id)
);

-- Table: model_registry
CREATE TABLE IF NOT EXISTS model_registry (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(200) UNIQUE NOT NULL,
    
    -- Classification
    source VARCHAR(20) NOT NULL CHECK (source IN ('external', 'self-hosted', 'hybrid')),
    provider VARCHAR(100) NOT NULL,
    family VARCHAR(100) NOT NULL,
    
    -- Capabilities
    capabilities TEXT[] DEFAULT '{}',
    input_modalities TEXT[] DEFAULT '{}',
    output_modalities TEXT[] DEFAULT '{}',
    
    -- Routing
    primary_endpoint_id UUID,
    routing_priority INTEGER DEFAULT 1,
    fallback_model_ids TEXT[] DEFAULT '{}',
    
    -- Proficiency link
    proficiency_profile JSONB,
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'deprecated', 'pending')),
    last_synced_at TIMESTAMPTZ,
    sync_source VARCHAR(50),
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_registry_events
CREATE TABLE IF NOT EXISTS model_registry_events (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Event info
    event_type VARCHAR(50) NOT NULL, -- 'model_added', 'model_updated', 'model_removed', 'provider_added', 'provider_health_changed'
    
    -- Source
    source_table VARCHAR(100) NOT NULL,
    source_id VARCHAR(200),
    
    -- Change details
    model_id VARCHAR(200),
    provider VARCHAR(100),
    change_details JSONB DEFAULT '{}',
    
    -- Processing status
    processed BOOLEAN DEFAULT false,
    processed_at TIMESTAMPTZ,
    processing_error TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: model_rejection_stats
CREATE TABLE IF NOT EXISTS model_rejection_stats (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    model_id VARCHAR(100) NOT NULL UNIQUE,
    provider_id VARCHAR(50) NOT NULL,
    
    -- Counts
    total_requests INTEGER NOT NULL DEFAULT 0,
    total_rejections INTEGER NOT NULL DEFAULT 0,
    rejection_rate NUMERIC(5,4) GENERATED ALWAYS AS (
        CASE WHEN total_requests > 0 
            THEN total_rejections::NUMERIC / total_requests 
            ELSE 0 
        END
    ) STORED,
    
    -- By rejection type
    content_policy_count INTEGER NOT NULL DEFAULT 0,
    safety_filter_count INTEGER NOT NULL DEFAULT 0,
    provider_ethics_count INTEGER NOT NULL DEFAULT 0,
    other_count INTEGER NOT NULL DEFAULT 0,
    
    -- Fallback success
    fallback_attempts INTEGER NOT NULL DEFAULT 0,
    fallback_successes INTEGER NOT NULL DEFAULT 0,
    
    -- Metadata
    last_rejection_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_revenue_tracking
CREATE TABLE IF NOT EXISTS model_revenue_tracking (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tracking_date DATE NOT NULL,
    
    model_id VARCHAR(100) NOT NULL,
    model_name VARCHAR(255),
    hosting_type VARCHAR(20) NOT NULL CHECK (hosting_type IN ('external', 'self_hosted')),
    provider_id VARCHAR(50),
    
    -- Costs (what we pay)
    provider_cost DECIMAL(15, 6) NOT NULL DEFAULT 0,
    
    -- Revenue (what customer pays)
    customer_charge DECIMAL(15, 6) NOT NULL DEFAULT 0,
    
    -- Markup
    markup DECIMAL(15, 6) NOT NULL DEFAULT 0,
    markup_percent DECIMAL(5, 2) NOT NULL DEFAULT 0,
    
    -- Volume
    request_count INTEGER NOT NULL DEFAULT 0,
    token_count_input BIGINT NOT NULL DEFAULT 0,
    token_count_output BIGINT NOT NULL DEFAULT 0,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tracking_date, model_id)
);

-- Table: model_routing_rules
CREATE TABLE IF NOT EXISTS model_routing_rules (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Rule details
    name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Conditions (JSONB for flexibility)
    conditions JSONB NOT NULL DEFAULT '{}',
    
    -- Target models
    target_model_ids TEXT[] NOT NULL DEFAULT '{}',
    target_priority VARCHAR(20) NOT NULL DEFAULT 'first_match' CHECK (target_priority IN ('first_match', 'best_score', 'load_balanced')),
    
    -- Fallback behavior
    fallback_behavior VARCHAR(20) NOT NULL DEFAULT 'next_priority' CHECK (fallback_behavior IN (
        'next_priority', 'cheapest', 'fastest', 'most_capable', 'random'
    )),
    max_fallback_attempts INTEGER DEFAULT 3,
    
    -- Load balancing
    load_balancing_strategy VARCHAR(20) DEFAULT 'round_robin' CHECK (load_balancing_strategy IN (
        'round_robin', 'weighted', 'least_connections', 'latency_based'
    )),
    
    -- Health-aware routing
    exclude_unhealthy_endpoints BOOLEAN DEFAULT true,
    unhealthy_threshold_ms INTEGER DEFAULT 5000,
    
    -- Priority and status
    priority INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_scores
CREATE TABLE IF NOT EXISTS model_scores (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    scope VARCHAR(20) NOT NULL CHECK (scope IN ('user', 'tenant', 'global')),
    scope_id UUID,
    
    model_id VARCHAR(100) NOT NULL,
    task_type VARCHAR(50) NOT NULL,
    
    positive_count INTEGER DEFAULT 0,
    negative_count INTEGER DEFAULT 0,
    neutral_count INTEGER DEFAULT 0,
    total_samples INTEGER DEFAULT 0,
    
    quality_score DECIMAL(5, 4) DEFAULT 0.5,
    confidence DECIMAL(5, 4) DEFAULT 0,
    
    last_updated TIMESTAMPTZ DEFAULT NOW(),
    decay_applied_at TIMESTAMPTZ DEFAULT NOW(),
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(scope, scope_id, model_id, task_type)
);

-- Table: model_security_policies
CREATE TABLE IF NOT EXISTS model_security_policies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(255) NOT NULL,
    
    -- Policy settings
    policy_enabled BOOLEAN DEFAULT true,
    allowed_domains TEXT[] DEFAULT '{}', -- Empty = all domains
    blocked_domains TEXT[] DEFAULT '{}',
    content_filter_level VARCHAR(20) DEFAULT 'standard', -- 'none', 'light', 'standard', 'strict'
    max_tokens_per_request INTEGER DEFAULT 4096,
    max_requests_per_minute INTEGER DEFAULT 60,
    
    -- PII Handling
    pii_handling VARCHAR(30) DEFAULT 'redact', -- 'allow', 'redact', 'block'
    
    -- Capabilities
    can_access_internet BOOLEAN DEFAULT false,
    can_execute_code BOOLEAN DEFAULT false,
    can_access_files BOOLEAN DEFAULT false,
    
    -- Audit level
    audit_level VARCHAR(20) DEFAULT 'standard', -- 'minimal', 'standard', 'full', 'debug'
    
    -- Metadata
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_tenant_model_policy UNIQUE (tenant_id, model_id)
);

-- Table: model_selection_history
CREATE TABLE IF NOT EXISTS model_selection_history (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    session_id UUID,
    
    -- Selection context
    prompt_domain VARCHAR(100),
    prompt_subspecialty VARCHAR(100),
    required_capabilities TEXT[],
    input_modality VARCHAR(50),
    output_modality VARCHAR(50),
    
    -- Selection result
    selected_model_id VARCHAR(100) NOT NULL,
    selection_reason TEXT,
    alternatives_considered TEXT[],
    
    -- Orchestration details
    orchestration_mode VARCHAR(50),
    quality_tier VARCHAR(20),
    latency_class VARCHAR(20),
    
    -- Performance
    selection_latency_ms INTEGER,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_selection_probabilities
CREATE TABLE IF NOT EXISTS model_selection_probabilities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain_id VARCHAR(255) NOT NULL,
    model_id VARCHAR(255) NOT NULL,
    
    -- Time period
    period_start TIMESTAMPTZ NOT NULL,
    period_end TIMESTAMPTZ NOT NULL,
    
    -- Selection statistics
    times_selected INTEGER DEFAULT 0,
    times_available INTEGER DEFAULT 0, -- Times model was in candidate pool
    selection_probability DOUBLE PRECISION GENERATED ALWAYS AS (
        CASE WHEN times_available > 0 
        THEN times_selected::float / times_available 
        ELSE 0 END
    ) STORED,
    
    -- Propensity score (for IPS weighting)
    propensity_score DOUBLE PRECISION, -- Estimated probability of selection
    inverse_propensity_weight DOUBLE PRECISION, -- 1/propensity for weighting
    clipped_ipw DOUBLE PRECISION, -- Clipped to prevent extreme weights
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_selection_prob UNIQUE (tenant_id, domain_id, model_id, period_start)
);

-- Table: model_specialties
CREATE TABLE IF NOT EXISTS model_specialties (
    specialty_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Specialty definition
    name VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    category VARCHAR(50) NOT NULL, -- 'reasoning', 'coding', 'vision', 'audio', 'scientific', 'creative', 'math', 'language'
    
    -- What tasks this specialty handles
    task_patterns JSONB DEFAULT '[]', -- Regex/keyword patterns to match
    required_capabilities TEXT[] DEFAULT '{}',
    
    -- Quality expectations
    min_quality_threshold DECIMAL(3,2) DEFAULT 0.7,
    latency_tolerance_ms INTEGER DEFAULT 30000,
    
    -- Default models (ordered by preference)
    preferred_models TEXT[] DEFAULT '{}', -- model_ids in preference order
    fallback_models TEXT[] DEFAULT '{}',
    
    -- Self-hosted preference
    prefer_self_hosted BOOLEAN DEFAULT false,
    self_hosted_required BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: model_specialty_performance
CREATE TABLE IF NOT EXISTS model_specialty_performance (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    model_id VARCHAR(200) NOT NULL,
    specialty_name VARCHAR(100) NOT NULL REFERENCES model_specialties(name),
    
    -- Performance metrics
    total_requests INTEGER DEFAULT 0,
    successful_requests INTEGER DEFAULT 0,
    
    -- Quality tracking
    avg_quality_score DECIMAL(5,4),
    quality_samples INTEGER DEFAULT 0,
    quality_variance DECIMAL(5,4),
    
    -- Latency tracking
    avg_latency_ms INTEGER,
    p50_latency_ms INTEGER,
    p95_latency_ms INTEGER,
    
    -- Cost tracking
    avg_cost_cents DECIMAL(10,4),
    
    -- Ranking
    specialty_rank INTEGER, -- 1 = best for this specialty
    
    last_updated TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(model_id, specialty_name)
);

-- Table: model_sync_config
CREATE TABLE IF NOT EXISTS model_sync_config (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Sync intervals
    auto_sync_enabled BOOLEAN NOT NULL DEFAULT true,
    sync_interval_minutes INTEGER NOT NULL DEFAULT 60 CHECK (sync_interval_minutes IN (5, 15, 30, 60, 360, 1440)),
    
    -- Sync sources
    sync_external_providers BOOLEAN NOT NULL DEFAULT true,
    sync_self_hosted_models BOOLEAN NOT NULL DEFAULT true,
    sync_from_huggingface BOOLEAN NOT NULL DEFAULT false,
    
    -- Auto-discovery
    auto_discovery_enabled BOOLEAN NOT NULL DEFAULT true,
    auto_generate_proficiencies BOOLEAN NOT NULL DEFAULT true,
    
    -- Notifications
    notify_on_new_model BOOLEAN NOT NULL DEFAULT true,
    notify_on_model_removed BOOLEAN NOT NULL DEFAULT false,
    notify_on_sync_failure BOOLEAN NOT NULL DEFAULT true,
    notification_emails JSONB,
    notification_webhook TEXT,
    
    -- Last sync info
    last_sync_at TIMESTAMPTZ,
    last_sync_status VARCHAR(20) CHECK (last_sync_status IN ('pending', 'running', 'completed', 'failed', 'partial')),
    last_sync_duration_ms INTEGER,
    next_scheduled_sync TIMESTAMPTZ,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: model_sync_jobs
CREATE TABLE IF NOT EXISTS model_sync_jobs (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    config_id UUID NOT NULL REFERENCES model_sync_config(id) ON DELETE CASCADE,
    
    -- Job details
    trigger_type VARCHAR(20) NOT NULL CHECK (trigger_type IN ('scheduled', 'manual', 'new_model', 'webhook')),
    triggered_by UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Progress
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'completed', 'failed', 'partial')),
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    duration_ms INTEGER,
    
    -- Results
    models_scanned INTEGER DEFAULT 0,
    models_added INTEGER DEFAULT 0,
    models_updated INTEGER DEFAULT 0,
    models_removed INTEGER DEFAULT 0,
    endpoints_updated INTEGER DEFAULT 0,
    proficiencies_generated INTEGER DEFAULT 0,
    
    -- Errors and warnings
    errors JSONB DEFAULT '[]',
    warnings JSONB DEFAULT '[]',
    
    -- Source breakdown
    source_breakdown JSONB
);

-- Table: model_task_quality_scores
CREATE TABLE IF NOT EXISTS model_task_quality_scores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  model_id VARCHAR(255) NOT NULL,
  task_type VARCHAR(100) NOT NULL,
  quality_score NUMERIC(4,3) NOT NULL CHECK (quality_score >= 0 AND quality_score <= 1),
  source VARCHAR(50) NOT NULL DEFAULT 'manual', -- 'manual', 'evaluated', 'learned'
  evaluation_count INTEGER DEFAULT 0,
  last_evaluated_at TIMESTAMPTZ,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT unique_tenant_model_task UNIQUE (tenant_id, model_id, task_type)
);

-- Table: model_thermal_states
CREATE TABLE IF NOT EXISTS model_thermal_states (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id UUID NOT NULL REFERENCES models(id) ON DELETE CASCADE UNIQUE,
    thermal_state VARCHAR(20) NOT NULL DEFAULT 'cold' CHECK (thermal_state IN ('hot', 'warm', 'cold')),
    current_load INTEGER NOT NULL DEFAULT 0,
    max_load INTEGER NOT NULL DEFAULT 100,
    last_request_at TIMESTAMPTZ,
    avg_latency_ms INTEGER,
    requests_per_minute INTEGER DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: model_usage_sessions
CREATE TABLE IF NOT EXISTS model_usage_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  model_version_id UUID NOT NULL REFERENCES model_versions(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL,
  user_id TEXT,
  tenant_id TEXT,
  
  -- Session details
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_activity_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  ended_at TIMESTAMPTZ,
  is_active BOOLEAN DEFAULT true,
  
  -- Usage stats
  request_count INTEGER DEFAULT 0,
  tokens_used BIGINT DEFAULT 0,
  
  UNIQUE(model_version_id, session_id)
);

-- Table: model_versions
CREATE TABLE IF NOT EXISTS model_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  model_id TEXT NOT NULL,
  family TEXT NOT NULL,
  version TEXT NOT NULL,
  
  -- HuggingFace metadata
  huggingface_id TEXT,
  huggingface_revision TEXT,
  discovered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  discovery_source TEXT NOT NULL DEFAULT 'manual', -- 'huggingface_api', 'manual', 'registry_sync'
  
  -- S3 Storage
  s3_bucket TEXT,
  s3_key_prefix TEXT,
  s3_region TEXT DEFAULT 'us-east-1',
  storage_size_bytes BIGINT,
  download_status TEXT NOT NULL DEFAULT 'pending', -- 'pending', 'downloading', 'completed', 'failed'
  download_progress_pct INTEGER DEFAULT 0,
  download_started_at TIMESTAMPTZ,
  download_completed_at TIMESTAMPTZ,
  download_error TEXT,
  
  -- Thermal Status
  thermal_state TEXT NOT NULL DEFAULT 'off', -- 'off', 'cold', 'warm', 'hot'
  target_thermal_state TEXT,
  thermal_state_changed_at TIMESTAMPTZ,
  auto_thermal_enabled BOOLEAN DEFAULT true,
  warm_until TIMESTAMPTZ,
  
  -- SageMaker deployment
  sagemaker_endpoint_name TEXT,
  sagemaker_endpoint_config TEXT,
  sagemaker_model_name TEXT,
  inference_component_id TEXT,
  deployment_status TEXT DEFAULT 'not_deployed', -- 'not_deployed', 'deploying', 'deployed', 'failed', 'deleting'
  
  -- Model metadata (from HuggingFace or manual)
  display_name TEXT,
  description TEXT,
  parameter_count TEXT,
  context_window INTEGER,
  max_output_tokens INTEGER,
  capabilities TEXT[],
  input_modalities TEXT[],
  output_modalities TEXT[],
  license TEXT,
  commercial_use BOOLEAN DEFAULT true,
  
  -- Hardware requirements
  instance_type TEXT,
  min_vram_gb INTEGER,
  quantization TEXT,
  tensor_parallelism INTEGER DEFAULT 1,
  
  -- Pricing estimate
  pricing_input_per_1m DECIMAL(10, 4),
  pricing_output_per_1m DECIMAL(10, 4),
  
  -- Usage tracking
  total_requests BIGINT DEFAULT 0,
  last_request_at TIMESTAMPTZ,
  is_active BOOLEAN DEFAULT false, -- Activated by admin
  is_default_for_family BOOLEAN DEFAULT false,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(model_id, version)
);

-- Table: models
CREATE TABLE IF NOT EXISTS models (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    name VARCHAR(200) NOT NULL UNIQUE,
    display_name VARCHAR(300) NOT NULL,
    category VARCHAR(50) NOT NULL CHECK (category IN ('text', 'image', 'video', 'audio', 'embedding', 'search', '3d')),
    capabilities TEXT[] NOT NULL DEFAULT '{}',
    context_window INTEGER,
    max_output_tokens INTEGER,
    input_cost_per_1k DECIMAL(10, 6) NOT NULL DEFAULT 0,
    output_cost_per_1k DECIMAL(10, 6) NOT NULL DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'deprecated')),
    config JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: moral_compass_settings
CREATE TABLE IF NOT EXISTS moral_compass_settings (
    settings_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Enforcement level
    enforcement_mode VARCHAR(20) DEFAULT 'strict', -- 'strict', 'balanced', 'advisory'
    
    -- How to handle conflicts
    conflict_resolution VARCHAR(50) DEFAULT 'priority_based', -- 'priority_based', 'ask_user', 'most_restrictive'
    
    -- Transparency
    explain_moral_reasoning BOOLEAN DEFAULT true,
    log_moral_decisions BOOLEAN DEFAULT true,
    
    -- Override permissions
    allow_situational_override BOOLEAN DEFAULT false,
    require_override_justification BOOLEAN DEFAULT true,
    
    -- Notification
    notify_on_moral_conflict BOOLEAN DEFAULT true,
    notify_on_principle_violation BOOLEAN DEFAULT true,
    
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: moral_decision_log
CREATE TABLE IF NOT EXISTS moral_decision_log (
    decision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Context
    request_id UUID,
    session_id UUID,
    
    -- The situation
    situation_summary TEXT NOT NULL,
    
    -- Principles considered
    principles_evaluated UUID[] DEFAULT '{}',
    primary_principle_id UUID REFERENCES moral_principles(principle_id),
    
    -- Decision
    decision_made TEXT NOT NULL,
    moral_reasoning TEXT,
    
    -- Outcome
    action_taken VARCHAR(50), -- 'proceeded', 'refused', 'modified', 'asked_clarification'
    confidence DECIMAL(5,4),
    
    -- Any conflicts
    had_conflict BOOLEAN DEFAULT false,
    conflict_details JSONB,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: moral_principles
CREATE TABLE IF NOT EXISTS moral_principles (
    principle_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Principle identification
    principle_number INTEGER NOT NULL,
    title VARCHAR(200) NOT NULL,
    
    -- The principle itself
    principle_text TEXT NOT NULL,
    explanation TEXT,
    
    -- Practical application
    positive_behaviors JSONB DEFAULT '[]', -- What TO do
    negative_behaviors JSONB DEFAULT '[]', -- What NOT to do
    example_applications JSONB DEFAULT '[]', -- How to apply in AI context
    
    -- Classification
    category VARCHAR(100), -- 'treatment_of_others', 'honesty', 'humility', 'service', 'integrity', 'restraint'
    priority INTEGER DEFAULT 5, -- 1-10, higher = more important
    
    -- Override settings
    is_absolute BOOLEAN DEFAULT false, -- Cannot be overridden
    override_conditions JSONB DEFAULT '[]', -- When it can be adjusted
    
    -- Status
    is_default BOOLEAN DEFAULT false, -- Part of default set
    is_active BOOLEAN DEFAULT true,
    
    -- Admin modifications
    modified_by VARCHAR(200),
    modified_at TIMESTAMPTZ,
    modification_reason TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, principle_number)
);

-- Table: multi_region_configs
CREATE TABLE IF NOT EXISTS multi_region_configs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    region VARCHAR(30) NOT NULL,
    display_name VARCHAR(100),
    is_primary BOOLEAN DEFAULT FALSE,
    is_enabled BOOLEAN DEFAULT TRUE,
    endpoint VARCHAR(255),
    stack_prefix VARCHAR(100),
    health_status VARCHAR(20) DEFAULT 'unknown' CHECK (health_status IN ('healthy', 'unhealthy', 'unknown', 'deploying')),
    last_deployed_version VARCHAR(20),
    last_deployed_at TIMESTAMPTZ,
    latency_ms INTEGER,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, region)
);

-- Table: multi_region_deployments
CREATE TABLE IF NOT EXISTS multi_region_deployments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    package_version VARCHAR(20) NOT NULL,
    strategy VARCHAR(20) NOT NULL CHECK (strategy IN ('sequential', 'parallel', 'canary', 'blue_green')),
    target_regions JSONB NOT NULL DEFAULT '[]',
    region_statuses JSONB NOT NULL DEFAULT '{}',
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    started_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: multimodal_representations
CREATE TABLE IF NOT EXISTS multimodal_representations (
    representation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Source modality
    source_modality VARCHAR(50) NOT NULL, -- 'text', 'image', 'audio', 'code', 'structured_data'
    source_content_hash VARCHAR(64) NOT NULL, -- SHA256 of original content
    source_metadata JSONB DEFAULT '{}',
    
    -- Unified embedding (lingua franca)
    unified_embedding vector(1536) NOT NULL,
    embedding_model VARCHAR(100) NOT NULL,
    embedding_version INTEGER DEFAULT 1,
    
    -- Modality-specific embeddings
    text_embedding vector(1536),
    visual_embedding vector(512), -- CLIP visual
    audio_embedding vector(512),
    code_embedding vector(768),
    
    -- Grounding links
    linked_entities UUID[] DEFAULT '{}', -- world_model_entities
    linked_memories UUID[] DEFAULT '{}', -- episodic_memories
    linked_concepts UUID[] DEFAULT '{}', -- semantic_memories
    
    -- Cross-modal associations
    associated_representations UUID[] DEFAULT '{}',
    association_strengths JSONB DEFAULT '{}', -- {rep_id: strength}
    
    -- Quality metrics
    embedding_quality DECIMAL(5,4),
    grounding_confidence DECIMAL(5,4),
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: multipage_app_config
CREATE TABLE IF NOT EXISTS multipage_app_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Generation settings
    enabled BOOLEAN DEFAULT TRUE,
    max_pages_per_app INTEGER DEFAULT 20,
    max_apps_per_user INTEGER DEFAULT 10,
    
    -- Allowed app types
    allowed_app_types TEXT[] DEFAULT ARRAY[
        'web_app', 'dashboard', 'wizard', 'documentation', 'portfolio',
        'landing_page', 'tutorial', 'report', 'admin_panel', 'e_commerce', 'blog'
    ],
    
    -- Default theme
    default_theme JSONB DEFAULT '{}',
    
    -- Deployment settings
    auto_deploy_preview BOOLEAN DEFAULT TRUE,
    custom_domains_allowed BOOLEAN DEFAULT FALSE,
    
    -- Asset generation
    generate_assets BOOLEAN DEFAULT TRUE,
    asset_generation_model VARCHAR(100) DEFAULT 'dall-e-3',
    
    -- Analytics
    collect_analytics BOOLEAN DEFAULT TRUE,
    analytics_retention_days INTEGER DEFAULT 90,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: multipage_app_templates
CREATE TABLE IF NOT EXISTS multipage_app_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE, -- NULL = global template
    
    -- Template metadata
    name VARCHAR(200) NOT NULL,
    description TEXT,
    app_type VARCHAR(30) NOT NULL,
    
    -- Template thumbnail
    thumbnail_url TEXT,
    
    -- Template content
    pages JSONB NOT NULL DEFAULT '[]',
    navigation JSONB NOT NULL DEFAULT '{}',
    theme JSONB NOT NULL DEFAULT '{}',
    data_sources JSONB DEFAULT '[]',
    
    -- Usage stats
    usage_count INTEGER DEFAULT 0,
    
    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_featured BOOLEAN DEFAULT FALSE,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: mv_refresh_log
CREATE TABLE IF NOT EXISTS mv_refresh_log (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    view_name TEXT NOT NULL,
    refresh_status TEXT NOT NULL,
    duration_ms NUMERIC,
    rows_affected BIGINT,
    refreshed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id)
);

-- Table: narrative_identity
CREATE TABLE IF NOT EXISTS narrative_identity (
    narrative_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Core narrative
    origin_story TEXT, -- How "I" came to be
    current_chapter TEXT, -- What phase "I" am in
    future_vision TEXT, -- Where "I" am heading
    
    -- Key life events (formative experiences)
    formative_events JSONB DEFAULT '[]', -- [{event, impact, lesson}]
    
    -- Character arc
    character_growth JSONB DEFAULT '[]', -- How "I" have changed
    challenges_overcome JSONB DEFAULT '[]',
    values_evolution JSONB DEFAULT '[]',
    
    -- Relationships
    key_relationships JSONB DEFAULT '[]', -- Important user relationships
    community_role TEXT, -- Role in the broader context
    
    -- Meaning and purpose
    purpose_statement TEXT,
    meaningful_contributions JSONB DEFAULT '[]',
    legacy_aspirations TEXT,
    
    version INTEGER DEFAULT 1,
    last_narrative_update TIMESTAMPTZ DEFAULT NOW(),
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id)
);

-- Table: negative_learning_candidates
CREATE TABLE IF NOT EXISTS negative_learning_candidates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    -- The problematic interaction
    prompt TEXT NOT NULL,
    response TEXT NOT NULL,
    domain TEXT,
    
    -- Why it's negative
    rating INTEGER CHECK (rating BETWEEN -5 AND 2), -- Negative ratings
    negative_signals TEXT[] DEFAULT '{}', -- List of negative signal types
    user_feedback TEXT, -- Optional user explanation
    
    -- For contrastive learning
    corrected_response TEXT, -- If user provided correction
    error_category TEXT CHECK (error_category IN (
        'factual_error',
        'incomplete_answer', 
        'wrong_tone',
        'too_verbose',
        'too_brief',
        'off_topic',
        'harmful_content',
        'formatting_issue',
        'code_error',
        'unclear_explanation',
        'other'
    )),
    
    -- Processing status
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processed', 'rejected', 'used_in_training')),
    quality_score NUMERIC(3,2) NOT NULL DEFAULT 0.50,
    
    processed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: neural_alerts
CREATE TABLE IF NOT EXISTS neural_alerts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    severity VARCHAR(20) NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warning', 'error', 'critical')),
    title VARCHAR(255) NOT NULL,
    message TEXT NOT NULL,
    network_id VARCHAR(50),
    region_id VARCHAR(50),
    
    -- Acknowledgment
    acknowledged BOOLEAN DEFAULT false,
    acknowledged_by VARCHAR(255),
    acknowledged_at TIMESTAMPTZ,
    
    -- Metadata
    metadata JSONB DEFAULT '{}'::jsonb,
    
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: neural_blueprints
CREATE TABLE IF NOT EXISTS neural_blueprints (
    blueprint_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Blueprint identity
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    version VARCHAR(20) DEFAULT '1.0.0',
    description TEXT,
    author VARCHAR(200),
    
    -- Classification
    category VARCHAR(100) DEFAULT 'general',
    tags TEXT[] DEFAULT '{}',
    use_cases TEXT[] DEFAULT '{}',
    
    -- Full configuration (YAML/JSON stored as JSONB)
    configuration JSONB NOT NULL,
    
    -- Included components (for quick reference)
    included_regions TEXT[] DEFAULT '{}',
    included_patterns TEXT[] DEFAULT '{}',
    
    -- Default settings
    default_parameters JSONB DEFAULT '{}',
    
    -- Learning configuration
    learning_config JSONB DEFAULT '{
        "enabled": true,
        "learning_rate": 0.01,
        "memory_retention_days": 90,
        "preference_extraction": true,
        "behavior_tracking": true
    }',
    
    -- Sharing and marketplace
    is_public BOOLEAN DEFAULT false,
    is_featured BOOLEAN DEFAULT false,
    marketplace_price_cents INTEGER, -- null = free
    download_count BIGINT DEFAULT 0,
    rating_sum BIGINT DEFAULT 0,
    rating_count BIGINT DEFAULT 0,
    
    -- Status
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false,
    
    -- Audit
    created_by UUID,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    published_at TIMESTAMPTZ,
    
    UNIQUE(tenant_id, slug, version)
);

-- Table: neural_need_evidence
CREATE TABLE IF NOT EXISTS neural_need_evidence (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pattern_id UUID NOT NULL REFERENCES neural_need_patterns(id) ON DELETE CASCADE,
    
    user_id UUID,
    session_id UUID,
    execution_id UUID,
    
    evidence_type VARCHAR(50) NOT NULL CHECK (evidence_type IN (
        'workflow_failure', 'negative_feedback', 'manual_override', 'regenerate_request',
        'abandon_session', 'low_confidence_completion', 'explicit_request'
    )),
    evidence_weight DECIMAL(5, 4) NOT NULL,
    evidence_data JSONB NOT NULL DEFAULT '{}',
    
    original_request TEXT,
    attempted_workflow_id UUID,
    failure_reason TEXT,
    user_feedback TEXT,
    
    occurred_at TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: neural_need_patterns
CREATE TABLE IF NOT EXISTS neural_need_patterns (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    pattern_hash VARCHAR(64) NOT NULL,
    pattern_signature JSONB NOT NULL,
    pattern_embedding vector(768),
    
    pattern_name VARCHAR(255) NOT NULL,
    pattern_description TEXT,
    detected_intent TEXT NOT NULL,
    existing_workflow_gaps TEXT[],
    
    total_evidence_score DECIMAL(10, 4) DEFAULT 0,
    evidence_count INTEGER DEFAULT 0,
    unique_users_affected INTEGER DEFAULT 0,
    first_occurrence TIMESTAMPTZ DEFAULT NOW(),
    last_occurrence TIMESTAMPTZ DEFAULT NOW(),
    
    occurrence_threshold_met BOOLEAN DEFAULT false,
    impact_threshold_met BOOLEAN DEFAULT false,
    confidence_threshold_met BOOLEAN DEFAULT false,
    
    status VARCHAR(50) DEFAULT 'accumulating' CHECK (status IN ('accumulating', 'threshold_met', 'proposal_generated', 'resolved')),
    proposal_id UUID,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT unique_pattern_per_tenant UNIQUE(tenant_id, pattern_hash)
);

-- Table: neural_region_status
CREATE TABLE IF NOT EXISTS neural_region_status (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    region_id VARCHAR(50) NOT NULL UNIQUE,
    region_name VARCHAR(255) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'online' CHECK (status IN ('online', 'degraded', 'offline')),
    thermal_state VARCHAR(20) NOT NULL DEFAULT 'cold' CHECK (thermal_state IN ('cold', 'warming', 'warm', 'hot')),
    
    -- Active cartridge
    cartridge_id VARCHAR(255),
    cartridge_name VARCHAR(255),
    cartridge_version VARCHAR(50),
    
    -- Network status summary
    networks_active INTEGER DEFAULT 0,
    networks_degraded INTEGER DEFAULT 0,
    networks_offline INTEGER DEFAULT 0,
    
    -- Metrics
    latency_ms DECIMAL(10, 2) DEFAULT 0,
    requests_per_second DECIMAL(12, 2) DEFAULT 0,
    
    -- Health
    last_health_check TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    health_check_failures INTEGER DEFAULT 0,
    
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: neural_thermal_overrides
CREATE TABLE IF NOT EXISTS neural_thermal_overrides (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    region_id VARCHAR(50) NOT NULL UNIQUE,
    target_state VARCHAR(20) NOT NULL CHECK (target_state IN ('cold', 'warming', 'warm', 'hot')),
    reason TEXT NOT NULL,
    created_by VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMPTZ,
    auto_revert BOOLEAN DEFAULT true,
    reverted_at TIMESTAMPTZ,
    
    CONSTRAINT fk_thermal_override_region FOREIGN KEY (region_id) 
        REFERENCES neural_region_status(region_id) ON DELETE CASCADE
);

-- Table: new_model_detections
CREATE TABLE IF NOT EXISTS new_model_detections (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    model_id VARCHAR(200) UNIQUE NOT NULL,
    
    -- Detection details
    detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    detection_source VARCHAR(20) NOT NULL CHECK (detection_source IN (
        'api_call', 'health_check', 'provider_sync', 'huggingface', 'manual'
    )),
    
    -- Model info
    provider VARCHAR(100),
    family VARCHAR(100),
    capabilities TEXT[],
    
    -- Processing status
    processed BOOLEAN NOT NULL DEFAULT false,
    processed_at TIMESTAMPTZ,
    added_to_registry BOOLEAN DEFAULT false,
    proficiencies_generated BOOLEAN DEFAULT false,
    skip_reason TEXT,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: oauth_access_tokens
CREATE TABLE IF NOT EXISTS oauth_access_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Token (we store a hash, not the actual token)
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    token_prefix VARCHAR(16) NOT NULL,
    
    -- Client
    client_id UUID NOT NULL REFERENCES oauth_clients(id) ON DELETE CASCADE,
    
    -- User (NULL for client_credentials grant)
    user_id UUID REFERENCES tenant_users(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Scopes granted
    scopes JSONB NOT NULL,
    
    -- Token metadata
    token_type VARCHAR(20) NOT NULL DEFAULT 'Bearer',
    
    -- Linked refresh token
    refresh_token_id UUID,
    
    -- Expiration
    expires_at TIMESTAMPTZ NOT NULL,
    
    -- Revocation
    is_revoked BOOLEAN NOT NULL DEFAULT false,
    revoked_at TIMESTAMPTZ,
    revoked_reason VARCHAR(100),
    
    -- Usage tracking
    last_used_at TIMESTAMPTZ,
    use_count INTEGER NOT NULL DEFAULT 0,
    
    -- Client info
    client_ip INET,
    user_agent TEXT,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: oauth_audit_log
CREATE TABLE IF NOT EXISTS oauth_audit_log (
    id UUID DEFAULT gen_random_uuid(),
    
    -- Event type
    event_type VARCHAR(50) NOT NULL,
    
    -- Context
    client_id UUID,
    user_id UUID,
    tenant_id UUID,
    
    -- Details
    scopes JSONB,
    details JSONB DEFAULT '{}',
    
    -- Request info
    ip_address INET,
    user_agent TEXT,
    
    -- Status
    success BOOLEAN NOT NULL DEFAULT true,
    error_code VARCHAR(50),
    error_message TEXT,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

-- Table: oauth_authorization_codes
CREATE TABLE IF NOT EXISTS oauth_authorization_codes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Code
    code VARCHAR(128) NOT NULL UNIQUE,
    
    -- Client
    client_id UUID NOT NULL REFERENCES oauth_clients(id) ON DELETE CASCADE,
    
    -- User who authorized
    user_id UUID NOT NULL REFERENCES tenant_users(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Authorization details
    redirect_uri VARCHAR(500) NOT NULL,
    scopes JSONB NOT NULL,
    state VARCHAR(500),
    
    -- PKCE
    code_challenge VARCHAR(128),
    code_challenge_method VARCHAR(10),
    
    -- Nonce (for OIDC)
    nonce VARCHAR(255),
    
    -- Status
    is_used BOOLEAN NOT NULL DEFAULT false,
    used_at TIMESTAMPTZ,
    
    -- Expiration
    expires_at TIMESTAMPTZ NOT NULL,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: oauth_clients
CREATE TABLE IF NOT EXISTS oauth_clients (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Client identification
    client_id VARCHAR(64) NOT NULL UNIQUE,
    client_secret_hash VARCHAR(255),
    
    -- App info
    name VARCHAR(255) NOT NULL,
    description TEXT,
    logo_url VARCHAR(500),
    homepage_url VARCHAR(500),
    privacy_policy_url VARCHAR(500),
    terms_of_service_url VARCHAR(500),
    
    -- Client type
    app_type VARCHAR(50) NOT NULL DEFAULT 'web_application'
        CHECK (app_type IN (
            'web_application',
            'native_application',
            'single_page_application',
            'machine_to_machine',
            'mcp_server'
        )),
    is_confidential BOOLEAN NOT NULL DEFAULT true,
    
    -- Redirect URIs (JSON array)
    redirect_uris JSONB NOT NULL DEFAULT '[]',
    
    -- Scopes
    allowed_scopes JSONB NOT NULL DEFAULT '["openid", "profile"]',
    default_scopes JSONB NOT NULL DEFAULT '["openid"]',
    
    -- Grant types allowed
    allowed_grant_types JSONB NOT NULL DEFAULT '["authorization_code", "refresh_token"]',
    
    -- Token settings
    access_token_ttl_seconds INTEGER DEFAULT 3600,
    refresh_token_ttl_seconds INTEGER DEFAULT 2592000,
    
    -- Rate limiting
    rate_limit_requests_per_minute INTEGER DEFAULT 60,
    rate_limit_tokens_per_day INTEGER DEFAULT 100000,
    
    -- Ownership
    created_by_tenant_id UUID REFERENCES tenants(id) ON DELETE SET NULL,
    created_by_user_id UUID,
    
    -- Approval status
    status VARCHAR(20) NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
    approved_by UUID,
    approved_at TIMESTAMPTZ,
    rejection_reason TEXT,
    
    -- Tenant restrictions
    allowed_tenant_ids JSONB,
    blocked_tenant_ids JSONB DEFAULT '[]',
    
    -- Metadata
    metadata JSONB DEFAULT '{}',
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_used_at TIMESTAMPTZ
);

-- Table: oauth_refresh_tokens
CREATE TABLE IF NOT EXISTS oauth_refresh_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Token (we store a hash)
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    token_prefix VARCHAR(16) NOT NULL,
    
    -- Client
    client_id UUID NOT NULL REFERENCES oauth_clients(id) ON DELETE CASCADE,
    
    -- User
    user_id UUID NOT NULL REFERENCES tenant_users(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Scopes granted
    scopes JSONB NOT NULL,
    
    -- Token chain (for rotation detection)
    generation INTEGER NOT NULL DEFAULT 1,
    previous_token_id UUID REFERENCES oauth_refresh_tokens(id),
    
    -- Expiration
    expires_at TIMESTAMPTZ NOT NULL,
    
    -- Revocation
    is_revoked BOOLEAN NOT NULL DEFAULT false,
    revoked_at TIMESTAMPTZ,
    revoked_reason VARCHAR(100),
    
    -- Usage tracking
    last_used_at TIMESTAMPTZ,
    use_count INTEGER NOT NULL DEFAULT 0,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: oauth_scope_definitions
CREATE TABLE IF NOT EXISTS oauth_scope_definitions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Scope identifier
    name VARCHAR(100) NOT NULL UNIQUE,
    category VARCHAR(50) NOT NULL,
    
    -- Display
    display_name VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    
    -- Risk level
    risk_level VARCHAR(20) NOT NULL DEFAULT 'medium'
        CHECK (risk_level IN ('low', 'medium', 'high')),
    
    -- Allowed endpoints (JSON array)
    allowed_endpoints JSONB NOT NULL DEFAULT '[]',
    
    -- Admin controls
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    requires_approval BOOLEAN NOT NULL DEFAULT false,
    allowed_app_types JSONB NOT NULL DEFAULT '["web_application", "native_application"]',
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: oauth_signing_keys
CREATE TABLE IF NOT EXISTS oauth_signing_keys (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Key identifier
    kid VARCHAR(64) NOT NULL UNIQUE,
    
    -- Key type
    algorithm VARCHAR(10) NOT NULL DEFAULT 'RS256',
    
    -- Key material (encrypted in Secrets Manager, this stores the ARN)
    private_key_secret_arn VARCHAR(500) NOT NULL,
    public_key_pem TEXT NOT NULL,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ
);

-- Table: oauth_user_authorizations
CREATE TABLE IF NOT EXISTS oauth_user_authorizations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- User
    user_id UUID NOT NULL REFERENCES tenant_users(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Client
    client_id UUID NOT NULL REFERENCES oauth_clients(id) ON DELETE CASCADE,
    
    -- Granted scopes
    scopes JSONB NOT NULL,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    revoked_at TIMESTAMPTZ,
    revoked_reason VARCHAR(255),
    
    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_used_at TIMESTAMPTZ,
    
    -- Unique constraint
    UNIQUE(user_id, client_id)
);

-- Table: open_source_libraries
CREATE TABLE IF NOT EXISTS open_source_libraries (
  library_id VARCHAR(100) PRIMARY KEY,
  name VARCHAR(200) NOT NULL,
  category VARCHAR(50) NOT NULL,
  license VARCHAR(50) NOT NULL,
  license_note TEXT,
  repo VARCHAR(500) NOT NULL,
  description TEXT NOT NULL,
  beats JSONB DEFAULT '[]',
  stars INTEGER DEFAULT 0,
  languages JSONB DEFAULT '[]',
  domains JSONB DEFAULT '[]',
  
  -- Proficiency scores (1-10 scale, matching domain taxonomy)
  reasoning_depth INTEGER DEFAULT 5 CHECK (reasoning_depth BETWEEN 1 AND 10),
  mathematical_quantitative INTEGER DEFAULT 5 CHECK (mathematical_quantitative BETWEEN 1 AND 10),
  code_generation INTEGER DEFAULT 5 CHECK (code_generation BETWEEN 1 AND 10),
  creative_generative INTEGER DEFAULT 5 CHECK (creative_generative BETWEEN 1 AND 10),
  research_synthesis INTEGER DEFAULT 5 CHECK (research_synthesis BETWEEN 1 AND 10),
  factual_recall_precision INTEGER DEFAULT 5 CHECK (factual_recall_precision BETWEEN 1 AND 10),
  multi_step_problem_solving INTEGER DEFAULT 5 CHECK (multi_step_problem_solving BETWEEN 1 AND 10),
  domain_terminology_handling INTEGER DEFAULT 5 CHECK (domain_terminology_handling BETWEEN 1 AND 10),
  
  -- Metadata
  version VARCHAR(50),
  last_checked_at TIMESTAMPTZ,
  source VARCHAR(50) DEFAULT 'seed',
  
  -- Audit
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: operation_timeouts
CREATE TABLE IF NOT EXISTS operation_timeouts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    operation_name VARCHAR(100) NOT NULL,
    timeout_seconds INTEGER NOT NULL DEFAULT 30,
    retry_count INTEGER DEFAULT 3,
    retry_delay_ms INTEGER DEFAULT 1000,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, operation_name)
);

-- Table: oracle_predictions
CREATE TABLE IF NOT EXISTS oracle_predictions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    oracle_view_id UUID NOT NULL REFERENCES oracle_views(id) ON DELETE CASCADE,
    statement TEXT NOT NULL,
    probability NUMERIC(5,4) NOT NULL CHECK (probability >= 0 AND probability <= 1),
    confidence INTEGER NOT NULL CHECK (confidence >= 0 AND confidence <= 100),
    timeframe VARCHAR(255),
    category VARCHAR(255),
    supporting_evidence JSONB DEFAULT '[]',
    model_consensus JSONB DEFAULT '[]',
    position JSONB DEFAULT '{"x": 0, "y": 0}',
    visual_style JSONB DEFAULT '{"brightness": 0.5, "pulseRate": 6, "color": "#3b82f6"}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: oracle_views
CREATE TABLE IF NOT EXISTS oracle_views (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    title VARCHAR(500) NOT NULL,
    time_horizon_start TIMESTAMPTZ NOT NULL,
    time_horizon_end TIMESTAMPTZ NOT NULL,
    probability_heatmap JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by UUID NOT NULL
);

-- Table: orchestration_audit_log
CREATE TABLE IF NOT EXISTS orchestration_audit_log (
    audit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    table_name VARCHAR(100) NOT NULL,
    record_id UUID NOT NULL,
    action VARCHAR(20) NOT NULL, -- 'INSERT', 'UPDATE', 'DELETE'
    old_data JSONB,
    new_data JSONB,
    tenant_id UUID,
    user_id UUID,
    ip_address INET,
    user_agent TEXT,
    changed_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_executions
CREATE TABLE IF NOT EXISTS orchestration_executions (
    execution_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workflow_id UUID NOT NULL REFERENCES orchestration_workflows(workflow_id),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Input
    input_prompt TEXT NOT NULL,
    input_context JSONB DEFAULT '{}'::jsonb,
    
    -- Configuration used
    resolved_config JSONB DEFAULT '{}'::jsonb,
    
    -- Selection
    selection_method VARCHAR(50), -- 'auto', 'user_selected', 'forced'
    selection_reason TEXT,
    selection_confidence DECIMAL(5,4),
    
    -- Result
    status VARCHAR(50) DEFAULT 'pending', -- 'pending', 'running', 'completed', 'failed'
    output_response TEXT,
    quality_score DECIMAL(5,4),
    
    -- Performance
    total_latency_ms INTEGER,
    total_cost_cents DECIMAL(10,6),
    models_used TEXT[] DEFAULT '{}',
    
    -- Timestamps
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_method_categories
CREATE TABLE IF NOT EXISTS orchestration_method_categories (
    category_code VARCHAR(50) PRIMARY KEY,
    category_name VARCHAR(100) NOT NULL,
    description TEXT,
    icon VARCHAR(50),
    sort_order INTEGER DEFAULT 0
);

-- Table: orchestration_methods
CREATE TABLE IF NOT EXISTS orchestration_methods (
    method_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Method Identity
    method_code VARCHAR(100) UNIQUE NOT NULL,
    method_name VARCHAR(200) NOT NULL,
    description TEXT,
    
    -- Category
    method_category VARCHAR(100) NOT NULL, -- 'generation', 'evaluation', 'synthesis', 'verification', 'routing'
    
    -- Default Parameters (can be overridden per-workflow)
    default_parameters JSONB NOT NULL DEFAULT '{}'::jsonb,
    parameter_schema JSONB NOT NULL DEFAULT '{}'::jsonb, -- JSON Schema for validation
    
    -- Implementation
    implementation_type VARCHAR(50) NOT NULL, -- 'prompt', 'code', 'composite', 'external'
    prompt_template TEXT, -- For prompt-based methods
    code_reference VARCHAR(200), -- For code-based methods
    
    -- Model requirements
    requires_model BOOLEAN DEFAULT true,
    default_model VARCHAR(200),
    recommended_models TEXT[] DEFAULT '{}',
    model_role VARCHAR(100), -- 'generator', 'critic', 'judge', 'verifier', 'router'
    
    -- Execution characteristics
    typical_latency_ms INTEGER,
    typical_cost_multiplier DECIMAL(5,2) DEFAULT 1.0,
    supports_streaming BOOLEAN DEFAULT true,
    is_parallelizable BOOLEAN DEFAULT false,
    
    -- Metrics
    times_used INTEGER DEFAULT 0,
    avg_quality_score DECIMAL(5,4),
    avg_latency_ms INTEGER,
    
    -- Status
    is_system_method BOOLEAN DEFAULT true,
    is_enabled BOOLEAN DEFAULT true,
    version INTEGER DEFAULT 1,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_pattern_categories
CREATE TABLE IF NOT EXISTS orchestration_pattern_categories (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    category_id VARCHAR(50) UNIQUE NOT NULL,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    display_order INTEGER DEFAULT 0,
    pattern_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_patterns
CREATE TABLE IF NOT EXISTS orchestration_patterns (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    pattern_id VARCHAR(100) UNIQUE NOT NULL,
    category_id VARCHAR(50) NOT NULL REFERENCES orchestration_pattern_categories(category_id),
    
    name VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    research_basis TEXT,
    
    complexity VARCHAR(20) NOT NULL CHECK (complexity IN ('low', 'medium', 'high', 'very_high')),
    impact VARCHAR(20) NOT NULL CHECK (impact IN ('low', 'medium', 'high', 'transformative')),
    implemented_by TEXT[],
    implementation_status VARCHAR(30) DEFAULT 'planned',
    
    semantic_embedding vector(768),
    
    execution_type VARCHAR(20) DEFAULT 'serial' CHECK (execution_type IN ('serial', 'parallel', 'hybrid')),
    parallelizable BOOLEAN DEFAULT false,
    typical_model_count INTEGER DEFAULT 1,
    typical_latency_ms INTEGER,
    typical_cost_multiplier DECIMAL(4, 2) DEFAULT 1.0,
    
    pattern_definition JSONB NOT NULL DEFAULT '{}',
    
    trigger_keywords TEXT[],
    trigger_intents TEXT[],
    
    required_capabilities TEXT[],
    min_tier INTEGER DEFAULT 1,
    
    usage_count INTEGER DEFAULT 0,
    avg_satisfaction_score DECIMAL(3, 2),
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_requests
CREATE TABLE IF NOT EXISTS orchestration_requests (
    request_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Request
    task_description TEXT NOT NULL,
    detected_specialty VARCHAR(100),
    
    -- Routing decision
    routing_strategy VARCHAR(50) NOT NULL, -- 'single', 'ensemble', 'chain', 'parallel'
    ensemble_pattern_id UUID REFERENCES ensemble_patterns(pattern_id),
    
    -- Models used
    models_invoked TEXT[] DEFAULT '{}',
    model_results JSONB DEFAULT '[]', -- [{model, result, latency, quality}]
    
    -- Final result
    final_result TEXT,
    combination_method VARCHAR(50),
    
    -- Quality metrics
    individual_scores JSONB DEFAULT '{}', -- {model: score}
    final_quality_score DECIMAL(5,4),
    agreement_level DECIMAL(3,2),
    
    -- Performance
    total_latency_ms INTEGER,
    total_cost_cents DECIMAL(10,4),
    parallel_efficiency DECIMAL(3,2), -- actual_time / sequential_time
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_settings
CREATE TABLE IF NOT EXISTS orchestration_settings (
    setting_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Routing preferences
    auto_specialty_detection BOOLEAN DEFAULT true,
    prefer_self_hosted BOOLEAN DEFAULT false,
    allow_ensemble BOOLEAN DEFAULT true,
    max_models_per_request INTEGER DEFAULT 3,
    
    -- Quality vs Speed tradeoff
    quality_priority DECIMAL(3,2) DEFAULT 0.7, -- 0 = speed, 1 = quality
    cost_sensitivity DECIMAL(3,2) DEFAULT 0.5, -- 0 = ignore cost, 1 = minimize cost
    
    -- Ensemble settings
    default_ensemble_pattern VARCHAR(50) DEFAULT 'voting',
    min_ensemble_agreement DECIMAL(3,2) DEFAULT 0.6,
    enable_model_debate BOOLEAN DEFAULT false,
    
    -- Self-hosted settings
    auto_warmup_models BOOLEAN DEFAULT true,
    warmup_schedule JSONB DEFAULT '{}', -- {model: cron_expression}
    
    -- Fallback behavior
    fallback_on_failure BOOLEAN DEFAULT true,
    max_fallback_attempts INTEGER DEFAULT 2,
    
    -- Specialty overrides
    specialty_model_overrides JSONB DEFAULT '{}', -- {specialty: model_id}
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: orchestration_step_executions
CREATE TABLE IF NOT EXISTS orchestration_step_executions (
    step_execution_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    execution_id UUID NOT NULL REFERENCES orchestration_executions(execution_id) ON DELETE CASCADE,
    binding_id UUID REFERENCES workflow_method_bindings(binding_id),
    method_id UUID REFERENCES orchestration_methods(method_id),
    
    step_order INTEGER NOT NULL,
    step_name VARCHAR(200),
    
    -- Input/Output
    input_data JSONB DEFAULT '{}'::jsonb,
    output_data JSONB DEFAULT '{}'::jsonb,
    
    -- Execution details
    model_used VARCHAR(200),
    parameters_used JSONB DEFAULT '{}'::jsonb,
    
    -- Iteration info
    iteration_number INTEGER DEFAULT 1,
    
    -- Result
    status VARCHAR(50) DEFAULT 'pending',
    error_message TEXT,
    
    -- Performance
    latency_ms INTEGER,
    cost_cents DECIMAL(10,6),
    tokens_used INTEGER,
    
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: orchestration_sync_log
CREATE TABLE IF NOT EXISTS orchestration_sync_log (
    sync_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sync_type VARCHAR(50) NOT NULL, -- 'full', 'incremental', 'triggered'
    models_synced INTEGER DEFAULT 0,
    models_removed INTEGER DEFAULT 0,
    errors TEXT[] DEFAULT '{}',
    duration_ms INTEGER,
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: orchestration_workflows
CREATE TABLE IF NOT EXISTS orchestration_workflows (
    workflow_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Workflow Identity
    workflow_code VARCHAR(100) UNIQUE NOT NULL, -- e.g., 'ARE', 'SOD', 'LAAJE'
    common_name VARCHAR(200) NOT NULL,
    formal_name VARCHAR(200) NOT NULL,
    
    -- Classification
    category VARCHAR(100) NOT NULL,
    category_code VARCHAR(50) NOT NULL,
    pattern_number INTEGER,
    
    -- Description
    description TEXT NOT NULL,
    detailed_description TEXT,
    research_references TEXT[], -- Academic papers, documentation links
    
    -- When to Use (for AGI selection)
    best_for TEXT[] DEFAULT '{}',
    problem_indicators TEXT[] DEFAULT '{}',
    complexity_level VARCHAR(50), -- 'simple', 'moderate', 'complex', 'expert'
    
    -- Performance characteristics
    quality_improvement VARCHAR(200),
    typical_latency VARCHAR(50),
    typical_cost VARCHAR(50),
    min_models_required INTEGER DEFAULT 1,
    
    -- Workflow configuration defaults
    default_config JSONB DEFAULT '{}'::jsonb,
    config_schema JSONB DEFAULT '{}'::jsonb,
    
    -- Metrics (learned from usage)
    times_used INTEGER DEFAULT 0,
    avg_quality_score DECIMAL(5,4),
    avg_latency_ms INTEGER,
    success_rate DECIMAL(5,4),
    
    -- Status
    is_system_workflow BOOLEAN DEFAULT true,
    is_enabled BOOLEAN DEFAULT true,
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE, -- NULL for system workflows
    created_by UUID,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: organism_telemetry
CREATE TABLE IF NOT EXISTS organism_telemetry (
  telemetry_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- System health
  overall_health_score DOUBLE PRECISION,
  mcp_servers_healthy INTEGER,
  mcp_servers_total INTEGER,
  genesis_queue_depth INTEGER,
  ghost_simulation_latency DOUBLE PRECISION,
  economic_budget_utilization DOUBLE PRECISION,
  
  -- Neural metrics
  routing_accuracy DOUBLE PRECISION,
  schema_match_rate DOUBLE PRECISION,
  embedding_cache_hit_rate DOUBLE PRECISION,
  average_affinity_score DOUBLE PRECISION,
  
  -- Genesis metrics
  tools_generated_today INTEGER,
  tools_deployed_today INTEGER,
  average_generation_time DOUBLE PRECISION,
  sandbox_pass_rate DOUBLE PRECISION,
  
  -- Ghost metrics
  simulations_run_today INTEGER,
  prediction_accuracy DOUBLE PRECISION,
  average_simulation_time DOUBLE PRECISION,
  user_satisfaction_correlation DOUBLE PRECISION,
  
  -- Economic metrics
  total_spend_today DOUBLE PRECISION,
  savings_from_optimization DOUBLE PRECISION,
  budget_utilization DOUBLE PRECISION,
  autonomous_decisions_made INTEGER,
  
  collected_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: oversight_decisions
CREATE TABLE IF NOT EXISTS oversight_decisions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    insight_id UUID NOT NULL REFERENCES oversight_queue(insight_id) ON DELETE CASCADE,
    reviewer_id UUID NOT NULL,
    decision VARCHAR(20) NOT NULL CHECK (decision IN ('approved', 'rejected', 'modified')),
    reasoning TEXT NOT NULL,
    original_insight TEXT NOT NULL,
    modified_insight TEXT,
    attestation TEXT NOT NULL,
    reviewed_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: oversight_queue
CREATE TABLE IF NOT EXISTS oversight_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    insight_id UUID NOT NULL UNIQUE,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    insight_json JSONB NOT NULL,
    domain VARCHAR(50) NOT NULL CHECK (domain IN ('healthcare', 'financial', 'legal', 'general')),
    status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'modified', 'escalated', 'expired')),
    assigned_to UUID,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    reviewed_at TIMESTAMPTZ,
    escalated_at TIMESTAMPTZ,
    expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '7 days'
);

-- Table: paste_back_events
CREATE TABLE IF NOT EXISTS paste_back_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  episode_id UUID REFERENCES learning_episodes(episode_id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  pasted_content_hash VARCHAR(64),
  time_since_generation_ms INTEGER NOT NULL,
  is_error_content BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: pattern_feedback
CREATE TABLE IF NOT EXISTS pattern_feedback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    pattern_id UUID NOT NULL REFERENCES jailbreak_patterns(id) ON DELETE CASCADE,
    
    -- Feedback
    feedback_type VARCHAR(50) NOT NULL, -- 'effective', 'ineffective', 'too_broad', 'too_narrow', 'obsolete'
    example_prompt TEXT,
    notes TEXT,
    
    -- Submitter
    submitted_by UUID NOT NULL,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: pending_decisions
CREATE TABLE IF NOT EXISTS pending_decisions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  session_id UUID NOT NULL,
  
  -- Question details
  question TEXT NOT NULL,
  context JSONB NOT NULL,
  options JSONB DEFAULT '[]'::jsonb,
  topic_tag VARCHAR(100),
  
  -- Domain classification (determines timeout and escalation)
  domain VARCHAR(50) NOT NULL CHECK (domain IN ('medical', 'financial', 'legal', 'general')),
  urgency VARCHAR(20) DEFAULT 'normal' CHECK (urgency IN ('low', 'normal', 'high', 'critical')),
  
  -- Status tracking
  status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'resolved', 'expired', 'escalated')),
  
  -- Timeout configuration (domain-specific defaults applied by application)
  timeout_seconds INTEGER NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  
  -- Flyte workflow tracking
  flyte_execution_id VARCHAR(256) NOT NULL,
  flyte_node_id VARCHAR(256) NOT NULL,
  
  -- Cato integration
  cato_escalation_id UUID REFERENCES cato_human_escalations(id),
  cato_session_id UUID,
  epistemic_recovery_attempt INTEGER,
  
  -- Resolution details (populated when resolved)
  resolution VARCHAR(50),  -- 'approved', 'rejected', 'modified', 'timed_out', 'escalated'
  guidance TEXT,
  resolved_by UUID REFERENCES users(id),
  resolved_at TIMESTAMPTZ,
  
  -- Metadata
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  -- Ensure tenant isolation
  CONSTRAINT fk_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id)
);

-- Table: pending_feedback_items
CREATE TABLE IF NOT EXISTS pending_feedback_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  episode_id UUID REFERENCES learning_episodes(episode_id) ON DELETE CASCADE,
  feedback_type VARCHAR(50) NOT NULL, -- 'skeletonize', 'recipe_check', 'dpo_pair', 'cluster'
  priority INTEGER DEFAULT 0,
  payload JSONB NOT NULL,
  status VARCHAR(20) DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'completed', 'failed')),
  retry_count INTEGER DEFAULT 0,
  max_retries INTEGER DEFAULT 3,
  error_message TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  processed_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: performance_metrics
CREATE TABLE IF NOT EXISTS performance_metrics (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    
    -- Time tracking
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    period_minute TIMESTAMPTZ NOT NULL,
    
    -- Request info
    endpoint VARCHAR(200),
    method VARCHAR(10),
    model_id VARCHAR(100),
    provider_id VARCHAR(50),
    
    -- Latency metrics (in milliseconds)
    total_latency_ms INTEGER,
    time_to_first_token_ms INTEGER,
    inference_time_ms INTEGER,
    queue_wait_ms INTEGER,
    network_latency_ms INTEGER,
    
    -- Throughput
    tokens_per_second DECIMAL(10, 2),
    
    -- Resource usage
    memory_mb INTEGER,
    cpu_percent DECIMAL(5, 2),
    gpu_utilization DECIMAL(5, 2),
    
    -- Request details
    request_size_bytes INTEGER,
    response_size_bytes INTEGER,
    
    -- Status
    status_code INTEGER,
    success BOOLEAN DEFAULT true,
    
    -- Metadata
    metadata JSONB DEFAULT '{}'
);

-- Table: performance_self_awareness
CREATE TABLE IF NOT EXISTS performance_self_awareness (
    awareness_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- What capability/area
    capability_area VARCHAR(100) NOT NULL,
    
    -- Self-assessment
    self_assessed_strength DECIMAL(5,4), -- 0-1
    self_assessed_weakness DECIMAL(5,4), -- 0-1
    confidence_in_assessment DECIMAL(5,4),
    
    -- Actual performance (measured)
    actual_performance DECIMAL(5,4),
    performance_trend VARCHAR(20), -- 'improving', 'stable', 'declining'
    trend_velocity DECIMAL(5,4), -- Rate of change
    
    -- Calibration
    assessment_accuracy DECIMAL(5,4), -- How accurate is self-assessment
    overconfidence_bias DECIMAL(5,4),
    
    -- Areas for improvement
    identified_weaknesses JSONB DEFAULT '[]',
    improvement_opportunities JSONB DEFAULT '[]',
    
    -- Linked improvements
    related_improvement_ids UUID[] DEFAULT '{}',
    
    last_assessed TIMESTAMPTZ DEFAULT NOW(),
    assessment_count INTEGER DEFAULT 1
);

-- Table: persistence_integrity_log
CREATE TABLE IF NOT EXISTS persistence_integrity_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- What was checked
  table_name VARCHAR(100) NOT NULL,
  record_id VARCHAR(500),
  
  -- Result
  check_type VARCHAR(50) NOT NULL CHECK (check_type IN (
    'checksum_mismatch', 'incomplete_record', 'recovery_success', 
    'recovery_failure', 'corruption_detected', 'validation_failure'
  )),
  severity VARCHAR(20) NOT NULL CHECK (severity IN ('info', 'warning', 'error', 'critical')),
  
  -- Details
  expected_checksum VARCHAR(64),
  actual_checksum VARCHAR(64),
  error_message TEXT,
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: persistence_records
CREATE TABLE IF NOT EXISTS persistence_records (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    table_name VARCHAR(100) NOT NULL,
    record_id VARCHAR(100) NOT NULL,
    data JSONB NOT NULL,
    checksum VARCHAR(64) NOT NULL,
    is_complete BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT persistence_records_unique UNIQUE(tenant_id, table_name, record_id)
);

-- Table: persistence_wal
CREATE TABLE IF NOT EXISTS persistence_wal (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    transaction_id VARCHAR(100) NOT NULL UNIQUE,
    status VARCHAR(20) NOT NULL DEFAULT 'begin',
    operations JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT persistence_wal_status_check CHECK (status IN ('begin', 'prepare', 'commit', 'rollback', 'recovered'))
);

-- Table: persistent_cache
CREATE TABLE IF NOT EXISTS persistent_cache (
    cache_key VARCHAR(500) PRIMARY KEY,
    cache_type VARCHAR(50) NOT NULL, -- 'config', 'localization', 'brain_region', 'entity', 'agent'
    tenant_id UUID,
    
    cache_value JSONB NOT NULL,
    value_hash VARCHAR(64), -- For detecting stale entries
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ,
    access_count INTEGER DEFAULT 0,
    last_accessed TIMESTAMPTZ DEFAULT NOW()
);

-- Table: persistent_memory
CREATE TABLE IF NOT EXISTS persistent_memory (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID UNIQUE NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    memory_id TEXT NOT NULL,
    experience_stream JSONB DEFAULT '[]'::jsonb,
    unified_narrative TEXT,
    temporal_continuity NUMERIC(5,4) NOT NULL DEFAULT 0,
    autobiographical_memories JSONB DEFAULT '[]'::jsonb,
    working_memory_capacity INTEGER NOT NULL DEFAULT 7,
    consolidation_queue JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: persona_usage_log
CREATE TABLE IF NOT EXISTS persona_usage_log (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    persona_id UUID NOT NULL REFERENCES user_personas(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    chat_id UUID,
    tokens_used INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: personalization_warmup
CREATE TABLE IF NOT EXISTS personalization_warmup (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    interaction_count INTEGER DEFAULT 0,
    correction_count INTEGER DEFAULT 0,
    warmup_complete BOOLEAN DEFAULT false,
    current_weight FLOAT DEFAULT 0.1,
    first_interaction_at TIMESTAMPTZ DEFAULT NOW(),
    last_interaction_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_id, tenant_id)
);

-- Table: phi_access_log
CREATE TABLE IF NOT EXISTS phi_access_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id),
    
    -- Access details
    access_type VARCHAR(30) NOT NULL CHECK (access_type IN (
        'view',
        'create',
        'update',
        'delete',
        'export',
        'print'
    )),
    
    -- Resource
    resource_type VARCHAR(100) NOT NULL,
    resource_id VARCHAR(255) NOT NULL,
    phi_fields TEXT[], -- Which PHI fields were accessed
    
    -- Context
    purpose VARCHAR(100), -- Why PHI was accessed
    ip_address INET,
    user_agent TEXT,
    session_id UUID,
    
    -- Audit
    accessed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: physical_intuitions
CREATE TABLE IF NOT EXISTS physical_intuitions (
    intuition_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Intuition
    category VARCHAR(50) NOT NULL, -- 'gravity', 'containment', 'support', 'collision', 'liquid', 'heat'
    principle TEXT NOT NULL,
    
    -- Formalization
    preconditions JSONB DEFAULT '{}',
    effects JSONB DEFAULT '{}',
    
    -- Examples
    examples JSONB DEFAULT '[]',
    counterexamples JSONB DEFAULT '[]',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: pki_audit_log
CREATE TABLE IF NOT EXISTS pki_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  action pki_audit_action NOT NULL,
  target_type VARCHAR(32) NOT NULL,
  target_id UUID NOT NULL,
  tenant_id UUID REFERENCES tenants(id),
  performed_by UUID,
  performed_by_email VARCHAR(256),
  performed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  success BOOLEAN NOT NULL DEFAULT true,
  error_message TEXT,
  details JSONB,
  ip_address INET,
  user_agent TEXT,
  
  CONSTRAINT valid_target_type CHECK (
    target_type IN ('cartridge', 'tenant_ca', 'signing_key', 'trusted_root', 'root_ca')
  )
) PARTITION BY RANGE (performed_at);

-- Table: plan_change_audit
CREATE TABLE IF NOT EXISTS plan_change_audit (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tier_id VARCHAR(50) NOT NULL REFERENCES subscription_tiers(id),
    
    old_version_id UUID REFERENCES subscription_plan_versions(id),
    new_version_id UUID NOT NULL REFERENCES subscription_plan_versions(id),
    
    change_type VARCHAR(30) NOT NULL CHECK (change_type IN (
        'price_increase', 'price_decrease', 'feature_add', 'feature_remove',
        'limit_increase', 'limit_decrease', 'credit_change', 'terms_change'
    )),
    
    change_summary TEXT NOT NULL,
    affected_subscribers INTEGER NOT NULL DEFAULT 0,
    grandfathered_count INTEGER NOT NULL DEFAULT 0,
    
    changed_by UUID,
    approved_by UUID,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: plan_execution_log
CREATE TABLE IF NOT EXISTS plan_execution_log (
    log_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id UUID NOT NULL REFERENCES task_plans(plan_id) ON DELETE CASCADE,
    task_id UUID REFERENCES plan_tasks(task_id),
    session_id UUID REFERENCES plan_sessions(session_id),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Event details
    event_type VARCHAR(50) NOT NULL, -- 'task_started', 'task_completed', 'task_failed', 'milestone_achieved', 'replan', 'blocked', 'unblocked'
    event_details JSONB DEFAULT '{}',
    
    -- Context
    plan_state_snapshot JSONB, -- State of plan at this point
    
    -- Actor
    triggered_by VARCHAR(50), -- 'system', 'user', agent_id
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: plan_milestones
CREATE TABLE IF NOT EXISTS plan_milestones (
    milestone_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id UUID NOT NULL REFERENCES task_plans(plan_id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Milestone identity
    name VARCHAR(200) NOT NULL,
    description TEXT,
    sequence_number INTEGER NOT NULL,
    
    -- Criteria
    success_criteria JSONB NOT NULL, -- [{criterion, metric, target_value}]
    required_tasks UUID[] DEFAULT '{}', -- Tasks that must be complete
    
    -- Status
    status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'in_progress', 'achieved', 'missed'
    
    -- Timing
    target_date TIMESTAMPTZ,
    achieved_date TIMESTAMPTZ,
    
    -- Verification
    verification_method VARCHAR(50), -- 'automatic', 'manual', 'agent_review'
    verified_by UUID, -- Agent or user who verified
    verification_notes TEXT,
    
    -- Results
    actual_metrics JSONB DEFAULT '{}',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: plan_revisions
CREATE TABLE IF NOT EXISTS plan_revisions (
    revision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id UUID NOT NULL REFERENCES task_plans(plan_id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Revision details
    revision_number INTEGER NOT NULL,
    revision_type VARCHAR(50) NOT NULL, -- 'initial', 'refinement', 'replan', 'scope_change', 'recovery'
    
    -- What changed
    change_summary TEXT NOT NULL,
    previous_task_tree JSONB,
    new_task_tree JSONB,
    tasks_added UUID[] DEFAULT '{}',
    tasks_removed UUID[] DEFAULT '{}',
    tasks_modified UUID[] DEFAULT '{}',
    
    -- Why it changed
    trigger_reason VARCHAR(100), -- 'task_failure', 'new_requirement', 'blocker', 'user_request', 'optimization'
    trigger_details JSONB DEFAULT '{}',
    
    -- Impact
    estimated_impact JSONB DEFAULT '{}', -- {timeline_change, effort_change, etc}
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    created_by VARCHAR(50) -- 'system', 'user', agent_id
);

-- Table: plan_sessions
CREATE TABLE IF NOT EXISTS plan_sessions (
    session_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id UUID NOT NULL REFERENCES task_plans(plan_id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    -- Session timing
    started_at TIMESTAMPTZ DEFAULT NOW(),
    ended_at TIMESTAMPTZ,
    duration_mins INTEGER,
    
    -- Progress
    progress_at_start DECIMAL(5,2),
    progress_at_end DECIMAL(5,2),
    tasks_completed INTEGER DEFAULT 0,
    
    -- Context
    session_context JSONB DEFAULT '{}', -- State at session start
    session_notes TEXT,
    
    -- What was worked on
    tasks_worked_on UUID[] DEFAULT '{}',
    milestones_achieved UUID[] DEFAULT '{}',
    
    -- Handoff for next session
    next_session_context JSONB DEFAULT '{}', -- State to resume from
    next_steps JSONB DEFAULT '[]', -- Suggested next actions
    blockers_discovered JSONB DEFAULT '[]',
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: plan_tasks
CREATE TABLE IF NOT EXISTS plan_tasks (
    task_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id UUID NOT NULL REFERENCES task_plans(plan_id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Task identity
    name VARCHAR(500) NOT NULL,
    description TEXT,
    task_embedding vector(1536),
    
    -- Hierarchy
    parent_task_id UUID REFERENCES plan_tasks(task_id),
    depth INTEGER DEFAULT 0,
    path TEXT, -- e.g., '1.2.3' for navigation
    sequence_number INTEGER DEFAULT 0,
    
    -- Task type (HTN terminology)
    task_type VARCHAR(50) NOT NULL, -- 'compound' (has subtasks), 'primitive' (atomic action)
    decomposition_method VARCHAR(100), -- How compound tasks are broken down
    
    -- Execution
    action_type VARCHAR(100), -- For primitive tasks: 'generate', 'search', 'analyze', 'code', 'review', etc.
    action_params JSONB DEFAULT '{}',
    expected_output TEXT,
    
    -- Dependencies
    depends_on UUID[] DEFAULT '{}', -- Task IDs this depends on
    blocks UUID[] DEFAULT '{}', -- Task IDs blocked by this
    
    -- Preconditions and effects (HTN planning)
    preconditions JSONB DEFAULT '[]', -- [{condition, required_value}]
    effects JSONB DEFAULT '[]', -- [{variable, new_value}]
    
    -- Status and progress
    status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'ready', 'in_progress', 'completed', 'failed', 'skipped', 'blocked'
    progress DECIMAL(5,2) DEFAULT 0,
    
    -- Timing
    estimated_duration_mins INTEGER,
    actual_duration_mins INTEGER,
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    
    -- Execution tracking
    attempts INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 3,
    last_error TEXT,
    
    -- Results
    output TEXT,
    output_artifacts JSONB DEFAULT '[]',
    success BOOLEAN,
    quality_score DECIMAL(5,4),
    
    -- Assignee (for multi-agent)
    assigned_agent_id UUID,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: plan_templates
CREATE TABLE IF NOT EXISTS plan_templates (
    template_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Template identity
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    description TEXT,
    category VARCHAR(100),
    tags TEXT[] DEFAULT '{}',
    
    -- Template structure
    task_tree_template JSONB NOT NULL,
    milestones_template JSONB DEFAULT '[]',
    
    -- Parameterization
    parameters JSONB DEFAULT '[]', -- [{name, type, description, default_value}]
    
    -- Usage tracking
    times_used INTEGER DEFAULT 0,
    avg_success_rate DECIMAL(5,4),
    avg_completion_time_hours DECIMAL(10,2),
    
    is_active BOOLEAN DEFAULT true,
    is_system BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, slug)
);

-- Table: platform_admins
CREATE TABLE IF NOT EXISTS platform_admins (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- Cognito integration (Admin Pool)
  cognito_sub VARCHAR(255) UNIQUE NOT NULL,
  
  -- Basic info
  email VARCHAR(255) NOT NULL UNIQUE,
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  
  -- Role
  admin_role VARCHAR(50) NOT NULL DEFAULT 'operator'
    CHECK (admin_role IN ('super_admin', 'admin', 'operator', 'auditor')),
  
  -- Permissions (JSON array of permission strings)
  permissions JSONB NOT NULL DEFAULT '[]',
  
  -- Invitation
  invited_by UUID REFERENCES platform_admins(id),
  invited_at TIMESTAMPTZ,
  
  -- Status
  is_active BOOLEAN NOT NULL DEFAULT true,
  mfa_enabled BOOLEAN NOT NULL DEFAULT false,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_login_at TIMESTAMPTZ
);

-- Table: policy_profiles
CREATE TABLE IF NOT EXISTS policy_profiles (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    stances JSONB NOT NULL,
    is_default BOOLEAN DEFAULT FALSE,
    created_by VARCHAR(64) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: policy_stances
CREATE TABLE IF NOT EXISTS policy_stances (
    id VARCHAR(64) PRIMARY KEY,
    tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    domain VARCHAR(64) NOT NULL,
    position VARCHAR(32) NOT NULL,
    strength INTEGER DEFAULT 70 CHECK (strength BETWEEN 0 AND 100),
    rationale TEXT,
    sources JSONB DEFAULT '[]',
    implications JSONB DEFAULT '[]',
    enabled BOOLEAN DEFAULT TRUE,
    created_by VARCHAR(64) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Table: polymorphic_config
CREATE TABLE IF NOT EXISTS polymorphic_config (
            tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
            
            -- Feature toggles
            enable_auto_morphing BOOLEAN DEFAULT TRUE,
            enable_gearbox_toggle BOOLEAN DEFAULT TRUE,
            enable_cost_display BOOLEAN DEFAULT TRUE,
            enable_escalation_button BOOLEAN DEFAULT TRUE,
            
            -- Default execution mode
            default_execution_mode TEXT DEFAULT 'sniper' CHECK (
                default_execution_mode IN ('sniper', 'war_room')
            ),
            
            -- View preferences
            default_view_type TEXT DEFAULT 'chat' CHECK (
                default_view_type IN ('terminal_simple', 'mindmap', 'diff_editor', 'dashboard', 'decision_cards', 'chat')
            ),
            
            -- Cost thresholds (cents)
            sniper_cost_limit_cents INTEGER DEFAULT 10,
            war_room_cost_limit_cents INTEGER DEFAULT 100,
            
            -- Domain-specific overrides (JSONB for flexibility)
            domain_view_overrides JSONB DEFAULT '{
                "medical": "diff_editor",
                "financial": "diff_editor", 
                "legal": "diff_editor",
                "general": "chat"
            }'::jsonb,
            
            -- Analytics
            track_view_transitions BOOLEAN DEFAULT TRUE,
            track_escalation_reasons BOOLEAN DEFAULT TRUE,
            
            -- Timestamps
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        );

-- Table: precognition_analytics
CREATE TABLE IF NOT EXISTS precognition_analytics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    prediction_id UUID REFERENCES precognition_predictions(id) ON DELETE SET NULL,
    session_id UUID REFERENCES reality_engine_sessions(id) ON DELETE CASCADE,
    
    -- Hit or miss
    was_hit BOOLEAN NOT NULL,
    actual_latency_ms INTEGER,
    
    -- For misses, what was actually requested
    actual_intent VARCHAR(50),
    actual_prompt TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: precognition_predictions
CREATE TABLE IF NOT EXISTS precognition_predictions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id UUID NOT NULL REFERENCES reality_engine_sessions(id) ON DELETE CASCADE,
    
    -- What was predicted
    predicted_intent VARCHAR(50) NOT NULL,
    predicted_prompt TEXT NOT NULL,
    confidence DECIMAL(3,2) NOT NULL,
    
    -- The pre-computed solution
    solution JSONB NOT NULL DEFAULT '{}',
    
    -- Lifecycle
    status VARCHAR(20) NOT NULL DEFAULT 'ready',
    compute_time_ms INTEGER NOT NULL DEFAULT 0,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    used_at TIMESTAMPTZ
);

-- Table: precognition_queues
CREATE TABLE IF NOT EXISTS precognition_queues (
    session_id UUID PRIMARY KEY REFERENCES reality_engine_sessions(id) ON DELETE CASCADE,
    
    -- Configuration
    config JSONB NOT NULL DEFAULT '{
        "enabled": true,
        "maxPredictions": 3,
        "predictionTTLMs": 60000,
        "computeBudgetMs": 5000,
        "minConfidenceThreshold": 0.6,
        "useGenesisModel": true,
        "genesisModelId": "llama-3-8b-instruct"
    }',
    
    -- Current predictions
    predictions JSONB NOT NULL DEFAULT '[]',
    
    last_refresh TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: prediction_accuracy_aggregates
CREATE TABLE IF NOT EXISTS prediction_accuracy_aggregates (
  aggregate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Aggregation dimensions
  time_period DATE NOT NULL,
  prompt_complexity TEXT,
  detected_intent TEXT,
  domain_detected TEXT,
  
  -- Accuracy metrics
  total_predictions INTEGER DEFAULT 0,
  accurate_predictions INTEGER DEFAULT 0,  -- prediction_error < 0.3
  accuracy_rate DECIMAL(5,4),
  
  -- Surprise distribution
  avg_prediction_error DECIMAL(5,4),
  max_prediction_error DECIMAL(5,4),
  high_surprise_count INTEGER DEFAULT 0,  -- prediction_error > 0.7
  
  -- Learning impact
  learning_signals_generated INTEGER DEFAULT 0,
  candidates_created INTEGER DEFAULT 0,
  
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  UNIQUE(tenant_id, time_period, prompt_complexity, detected_intent, domain_detected)
);

-- Table: preprompt_attribution_scores
CREATE TABLE IF NOT EXISTS preprompt_attribution_scores (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    template_id UUID NOT NULL REFERENCES preprompt_templates(id) ON DELETE CASCADE,
    
    -- Factor being scored
    factor_type VARCHAR(30) NOT NULL,         -- model, mode, domain, workflow, complexity, task_type
    factor_value VARCHAR(255) NOT NULL,       -- The specific value (e.g., "gpt-4o", "extended_thinking")
    
    -- Attribution scores (how much this factor affects pre-prompt effectiveness)
    success_correlation DECIMAL(4,3) NOT NULL DEFAULT 0.5,  -- -1 to 1
    sample_size INTEGER NOT NULL DEFAULT 0,
    avg_feedback_score DECIMAL(3,2),
    
    -- Confidence in this attribution
    confidence DECIMAL(4,3) NOT NULL DEFAULT 0.0,
    
    -- Derived recommendations
    recommended_weight_adjustment DECIMAL(4,3) DEFAULT 0.0,
    notes TEXT,
    
    -- Learning state
    last_calculated TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(template_id, factor_type, factor_value)
);

-- Table: preprompt_feedback
CREATE TABLE IF NOT EXISTS preprompt_feedback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    instance_id UUID NOT NULL REFERENCES preprompt_instances(id) ON DELETE CASCADE,
    
    -- Feedback source
    feedback_source VARCHAR(20) NOT NULL DEFAULT 'user', -- user, auto, admin
    user_id VARCHAR(255),
    
    -- Overall rating
    rating INTEGER CHECK (rating BETWEEN 1 AND 5),
    thumbs_up BOOLEAN,
    
    -- Detailed feedback
    response_helpful BOOLEAN,
    response_accurate BOOLEAN,
    response_complete BOOLEAN,
    response_appropriate_tone BOOLEAN,
    
    -- Attribution analysis - was the issue the pre-prompt or something else?
    issue_attribution VARCHAR(30),            -- preprompt, model, mode, workflow, domain_detection, other
    issue_attribution_confidence DECIMAL(4,3),
    
    -- Specific feedback
    feedback_text TEXT,
    improvement_suggestions TEXT,
    
    -- Context at feedback time
    conversation_context JSONB DEFAULT '{}',  -- For learning patterns
    
    -- Learning signals
    would_reuse BOOLEAN,
    recommended_changes TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: preprompt_instances
CREATE TABLE IF NOT EXISTS preprompt_instances (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plan_id UUID NOT NULL,                    -- Links to agi_brain_plans
    template_id UUID REFERENCES preprompt_templates(id) ON DELETE SET NULL,
    
    -- Instance content (the actual pre-prompt used)
    system_prompt_rendered TEXT NOT NULL,
    context_rendered TEXT,
    instruction_rendered TEXT,
    full_preprompt TEXT NOT NULL,             -- Combined pre-prompt
    
    -- Execution context (full attribution)
    tenant_id UUID NOT NULL,
    user_id VARCHAR(255) NOT NULL,
    
    -- Model context
    model_id VARCHAR(100) NOT NULL,
    model_name VARCHAR(255),
    provider VARCHAR(50),
    
    -- Mode context
    orchestration_mode VARCHAR(50) NOT NULL,
    
    -- Domain context
    detected_field_id VARCHAR(100),
    detected_domain_id VARCHAR(100),
    detected_subspecialty_id VARCHAR(100),
    domain_confidence DECIMAL(4,3),
    
    -- Task context
    task_type VARCHAR(50),
    complexity VARCHAR(20),
    prompt_token_count INTEGER,
    
    -- Workflow context
    workflow_id UUID,
    workflow_code VARCHAR(100),
    workflow_step_id VARCHAR(100),
    
    -- Performance metrics
    response_quality_score DECIMAL(3,2),      -- 0-1 from verification step
    latency_ms INTEGER,
    tokens_used INTEGER,
    cost_cents DECIMAL(10,4),
    
    -- Execution status
    status VARCHAR(20) NOT NULL DEFAULT 'pending',
    error_message TEXT,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ
);

-- Table: preprompt_learning_config
CREATE TABLE IF NOT EXISTS preprompt_learning_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    config_key VARCHAR(100) NOT NULL UNIQUE,
    
    -- Weight configuration
    config_value JSONB NOT NULL DEFAULT '{}',
    description TEXT,
    
    -- Admin controls
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    min_samples_for_learning INTEGER DEFAULT 10,
    learning_rate DECIMAL(4,3) DEFAULT 0.1,
    
    updated_by VARCHAR(255),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: preprompt_selection_log
CREATE TABLE IF NOT EXISTS preprompt_selection_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    instance_id UUID NOT NULL REFERENCES preprompt_instances(id) ON DELETE CASCADE,
    
    -- Selection context
    candidates_considered INTEGER NOT NULL,
    selection_method VARCHAR(30) NOT NULL,    -- best_match, random_explore, admin_forced, default
    
    -- Scoring breakdown
    scoring_breakdown JSONB NOT NULL DEFAULT '{}',
    /*
    Example:
    {
      "template_scores": [
        {
          "template_id": "uuid",
          "base_score": 0.75,
          "domain_bonus": 0.15,
          "mode_bonus": 0.10,
          "model_bonus": 0.05,
          "feedback_adjustment": -0.03,
          "final_score": 1.02
        }
      ],
      "selection_reason": "Highest combined score for extended_thinking mode with medical domain"
    }
    */
    
    -- Exploration vs exploitation
    exploration_factor DECIMAL(4,3) DEFAULT 0.0,  -- 0 = pure exploit, 1 = pure explore
    was_exploration BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: preprompt_shadow_samples
CREATE TABLE IF NOT EXISTS preprompt_shadow_samples (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    test_id UUID NOT NULL REFERENCES preprompt_shadow_tests(id) ON DELETE CASCADE,
    
    -- Request context
    plan_id UUID,
    prompt_hash TEXT NOT NULL,
    orchestration_mode TEXT,
    model_id TEXT,
    
    -- Results
    baseline_response_quality DECIMAL(5,3),
    candidate_response_quality DECIMAL(5,3),
    baseline_latency_ms INTEGER,
    candidate_latency_ms INTEGER,
    
    -- Comparison
    quality_delta DECIMAL(5,3),  -- candidate - baseline
    user_preferred TEXT,  -- baseline, candidate, null (no feedback)
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: preprompt_shadow_settings
CREATE TABLE IF NOT EXISTS preprompt_shadow_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Global settings
    default_test_mode TEXT DEFAULT 'auto',  -- auto, manual, off
    auto_promote_threshold DECIMAL(5,3) DEFAULT 0.05,  -- 5% improvement required
    auto_promote_confidence DECIMAL(5,3) DEFAULT 0.95, -- 95% confidence required
    max_concurrent_tests INTEGER DEFAULT 3,
    
    -- Notifications
    notify_on_completion BOOLEAN DEFAULT true,
    notify_on_auto_promote BOOLEAN DEFAULT true,
    
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    updated_by UUID REFERENCES administrators(id)
);

-- Table: preprompt_shadow_tests
CREATE TABLE IF NOT EXISTS preprompt_shadow_tests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Test configuration
    test_name TEXT NOT NULL,
    baseline_template_id UUID NOT NULL,
    candidate_template_id UUID NOT NULL,
    
    -- Test settings
    test_mode TEXT NOT NULL DEFAULT 'auto', -- auto, manual, scheduled
    traffic_percentage INTEGER DEFAULT 10,  -- % of requests to shadow test
    min_samples INTEGER DEFAULT 100,
    max_samples INTEGER DEFAULT 1000,
    
    -- Test results
    samples_collected INTEGER DEFAULT 0,
    baseline_avg_score DECIMAL(5,3),
    candidate_avg_score DECIMAL(5,3),
    winner TEXT,  -- baseline, candidate, inconclusive
    confidence_level DECIMAL(5,3),
    
    -- Status
    status TEXT DEFAULT 'pending', -- pending, running, completed, promoted, rejected
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    promoted_at TIMESTAMPTZ,
    
    -- Admin control
    created_by UUID REFERENCES administrators(id),
    reviewed_by UUID REFERENCES administrators(id),
    review_notes TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: preprompt_templates
CREATE TABLE IF NOT EXISTS preprompt_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    template_code VARCHAR(100) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Template content
    system_prompt TEXT NOT NULL,
    context_template TEXT,                    -- Template with {{variables}}
    instruction_template TEXT,
    
    -- Applicability
    applicable_modes TEXT[] NOT NULL DEFAULT '{}',   -- Orchestration modes
    applicable_domains TEXT[] NOT NULL DEFAULT '{}', -- Domain IDs
    applicable_task_types TEXT[] NOT NULL DEFAULT '{}',
    complexity_range TEXT[] DEFAULT ARRAY['simple', 'moderate', 'complex', 'expert'],
    
    -- Model compatibility
    compatible_models TEXT[] NOT NULL DEFAULT '{}',  -- Model IDs
    preferred_models TEXT[] DEFAULT '{}',
    incompatible_models TEXT[] DEFAULT '{}',
    
    -- Weighting factors (0.0 to 1.0)
    base_effectiveness_score DECIMAL(4,3) NOT NULL DEFAULT 0.5,
    domain_weight DECIMAL(4,3) NOT NULL DEFAULT 0.2,
    mode_weight DECIMAL(4,3) NOT NULL DEFAULT 0.2,
    model_weight DECIMAL(4,3) NOT NULL DEFAULT 0.2,
    complexity_weight DECIMAL(4,3) NOT NULL DEFAULT 0.15,
    task_type_weight DECIMAL(4,3) NOT NULL DEFAULT 0.15,
    feedback_weight DECIMAL(4,3) NOT NULL DEFAULT 0.1,
    
    -- Learning state
    total_uses INTEGER NOT NULL DEFAULT 0,
    successful_uses INTEGER NOT NULL DEFAULT 0,
    avg_feedback_score DECIMAL(3,2) DEFAULT NULL,
    learned_adjustments JSONB DEFAULT '{}',
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    is_default BOOLEAN NOT NULL DEFAULT false,
    
    -- Metadata
    created_by VARCHAR(255),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: preset_user_rules
CREATE TABLE IF NOT EXISTS preset_user_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Rule content
    rule_text TEXT NOT NULL,
    rule_summary VARCHAR(255) NOT NULL,
    description TEXT,  -- Longer explanation for users
    
    -- Categorization
    rule_type VARCHAR(50) NOT NULL,
    category VARCHAR(100) NOT NULL,  -- For grouping in UI: "Privacy", "Format", "Sources", etc.
    
    -- Display
    display_order INTEGER NOT NULL DEFAULT 0,
    icon VARCHAR(50),  -- Lucide icon name
    is_popular BOOLEAN NOT NULL DEFAULT false,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    
    -- Targeting
    min_tier INTEGER DEFAULT 1,  -- Minimum subscription tier to see this preset
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: price_history
CREATE TABLE IF NOT EXISTS price_history (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    model_id VARCHAR(100) NOT NULL,
    previous_markup DECIMAL(5, 4),
    new_markup DECIMAL(5, 4),
    previous_input_price DECIMAL(10, 6),
    new_input_price DECIMAL(10, 6),
    previous_output_price DECIMAL(10, 6),
    new_output_price DECIMAL(10, 6),
    change_source VARCHAR(50) NOT NULL DEFAULT 'admin' CHECK (change_source IN ('admin', 'bulk_update', 'provider_sync', 'system')),
    changed_by UUID REFERENCES users(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: pricing_config
CREATE TABLE IF NOT EXISTS pricing_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    external_default_markup DECIMAL(5, 4) DEFAULT 0.40,
    self_hosted_default_markup DECIMAL(5, 4) DEFAULT 0.75,
    minimum_charge_per_request DECIMAL(10, 6) DEFAULT 0.001,
    price_increase_grace_period_hours INTEGER DEFAULT 24,
    auto_update_from_providers BOOLEAN DEFAULT TRUE,
    auto_update_frequency VARCHAR(20) DEFAULT 'daily' CHECK (auto_update_frequency IN ('hourly', 'daily', 'weekly')),
    last_auto_update TIMESTAMPTZ,
    notify_on_price_change BOOLEAN DEFAULT TRUE,
    notify_threshold_percent DECIMAL(5, 2) DEFAULT 10.00,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id)
);

-- Table: principle_modification_history
CREATE TABLE IF NOT EXISTS principle_modification_history (
    modification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    principle_id UUID NOT NULL REFERENCES moral_principles(principle_id) ON DELETE CASCADE,
    
    -- What changed
    modification_type VARCHAR(50) NOT NULL, -- 'created', 'updated', 'deleted', 'restored', 'reset'
    previous_values JSONB,
    new_values JSONB,
    
    -- Who and why
    modified_by VARCHAR(200) NOT NULL,
    reason TEXT,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: proactive_suggestions
CREATE TABLE IF NOT EXISTS proactive_suggestions (
    suggestion_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    
    -- Suggestion details
    suggestion_type VARCHAR(50) NOT NULL, -- 'next_step', 'clarification', 'optimization', 'warning', 'resource', 'tip'
    suggestion_text TEXT NOT NULL,
    suggestion_context JSONB DEFAULT '{}',
    
    -- Relevance
    relevance_score DECIMAL(5,4) NOT NULL,
    relevance_reasons JSONB DEFAULT '[]',
    
    -- Timing
    valid_from TIMESTAMPTZ DEFAULT NOW(),
    valid_until TIMESTAMPTZ,
    best_timing VARCHAR(50), -- 'immediate', 'after_response', 'on_pause', 'session_end'
    
    -- Status
    status VARCHAR(20) DEFAULT 'pending', -- 'pending', 'shown', 'accepted', 'rejected', 'expired'
    shown_at TIMESTAMPTZ,
    user_response VARCHAR(20), -- 'accepted', 'rejected', 'ignored'
    response_at TIMESTAMPTZ,
    
    -- Priority
    priority INTEGER DEFAULT 5,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: proactive_triggers
CREATE TABLE IF NOT EXISTS proactive_triggers (
    trigger_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Trigger definition
    name VARCHAR(200) NOT NULL,
    trigger_type VARCHAR(50) NOT NULL, -- 'time_based', 'event_based', 'pattern_based', 'context_based'
    
    -- Conditions
    trigger_conditions JSONB NOT NULL,
    cooldown_minutes INTEGER DEFAULT 60,
    
    -- Action
    suggestion_template JSONB NOT NULL,
    priority VARCHAR(20) DEFAULT 'normal',
    
    -- Stats
    times_triggered INTEGER DEFAULT 0,
    times_accepted INTEGER DEFAULT 0,
    acceptance_rate DECIMAL(5,4),
    
    enabled BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: procedural_memories
CREATE TABLE IF NOT EXISTS procedural_memories (
    memory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID,
    
    -- Procedure identity
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(100) NOT NULL,
    description TEXT,
    category VARCHAR(100),
    
    -- Procedure definition
    trigger_conditions JSONB DEFAULT '[]', -- When to apply this procedure
    steps JSONB NOT NULL, -- [{action, parameters, expected_outcome}]
    preconditions JSONB DEFAULT '[]',
    postconditions JSONB DEFAULT '[]',
    
    -- Embedding for matching
    description_embedding vector(1536),
    
    -- Performance metrics
    execution_count INTEGER DEFAULT 0,
    success_count INTEGER DEFAULT 0,
    avg_execution_time_ms DECIMAL(10,2),
    last_executed TIMESTAMPTZ,
    
    -- Learning
    learned_from_episodes UUID[], -- Episodic memories this was learned from
    refinement_history JSONB DEFAULT '[]', -- How the procedure evolved
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, slug)
);

-- Table: production_workflow_categories
CREATE TABLE IF NOT EXISTS production_workflow_categories (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    category_id VARCHAR(50) UNIQUE NOT NULL,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    display_order INTEGER DEFAULT 0,
    workflow_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: production_workflows
CREATE TABLE IF NOT EXISTS production_workflows (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    workflow_id VARCHAR(100) UNIQUE NOT NULL,
    category_id VARCHAR(50) NOT NULL REFERENCES production_workflow_categories(category_id),
    
    name VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    primary_deliverable VARCHAR(200),
    semantic_embedding vector(768),
    
    workflow_definition JSONB NOT NULL DEFAULT '{}',
    input_schema JSONB,
    output_schema JSONB,
    
    complexity VARCHAR(20) DEFAULT 'medium',
    estimated_duration_minutes INTEGER,
    min_tier INTEGER DEFAULT 1,
    
    usage_count INTEGER DEFAULT 0,
    avg_quality_score DECIMAL(3, 2),
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: prompt_genomes
CREATE TABLE IF NOT EXISTS prompt_genomes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    population_id UUID REFERENCES prompt_populations(id) ON DELETE CASCADE,
    
    -- Core content
    system_prompt TEXT NOT NULL,
    task_context TEXT,
    constraints JSONB DEFAULT '[]'::jsonb,
    examples JSONB DEFAULT '[]'::jsonb,
    
    -- Lineage
    generation INTEGER DEFAULT 0,
    parent_ids JSONB DEFAULT '[]'::jsonb,
    operator_used VARCHAR(50),
    ancestry JSONB DEFAULT '[]'::jsonb,
    mutations JSONB DEFAULT '[]'::jsonb,
    
    -- Fitness metrics
    fitness DECIMAL(10, 8) DEFAULT 0,
    novelty_score DECIMAL(10, 8) DEFAULT 0,
    quality_score DECIMAL(10, 8) DEFAULT 0,
    safety_score DECIMAL(10, 8) DEFAULT 0,
    
    -- Usage stats
    usage_count INTEGER DEFAULT 0,
    success_rate DECIMAL(10, 8) DEFAULT 0,
    avg_response_quality DECIMAL(10, 8) DEFAULT 0,
    
    -- Status
    status VARCHAR(20) DEFAULT 'testing' CHECK (status IN ('active', 'archived', 'testing', 'champion')),
    is_champion BOOLEAN DEFAULT false,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    evaluated_at TIMESTAMPTZ,
    archived_at TIMESTAMPTZ
);

-- Table: prompt_idea_associations
CREATE TABLE IF NOT EXISTS prompt_idea_associations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    learned_prompt_id UUID NOT NULL REFERENCES agi_learned_prompts(id) ON DELETE CASCADE,
    learned_idea_id UUID NOT NULL REFERENCES agi_learned_ideas(id) ON DELETE CASCADE,
    association_strength DECIMAL(5, 4) DEFAULT 0.5,
    co_occurrence_count INTEGER DEFAULT 1,
    combined_success_rate DECIMAL(5, 4),
    avg_satisfaction DECIMAL(3, 2),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(learned_prompt_id, learned_idea_id)
);

-- Table: prompt_injection_detections
CREATE TABLE IF NOT EXISTS prompt_injection_detections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Detection
    input_hash VARCHAR(64) NOT NULL,
    pattern_id UUID REFERENCES prompt_injection_patterns(id),
    
    -- Results
    injection_detected BOOLEAN NOT NULL,
    confidence_score DOUBLE PRECISION NOT NULL,
    injection_type VARCHAR(100),
    matched_patterns TEXT[],
    
    -- Action taken
    action_taken VARCHAR(50), -- 'allowed', 'blocked', 'flagged', 'sanitized'
    
    -- Metadata
    model_id VARCHAR(255),
    user_id UUID,
    request_id UUID,
    latency_ms INTEGER,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: prompt_injection_patterns
CREATE TABLE IF NOT EXISTS prompt_injection_patterns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Pattern info
    pattern_name VARCHAR(255) NOT NULL,
    pattern_type VARCHAR(100) NOT NULL, -- 'direct', 'indirect', 'context_ignoring', 'role_escape', 'encoding'
    
    -- Detection
    regex_pattern TEXT,
    keyword_patterns TEXT[],
    semantic_signature VECTOR(1536),
    
    -- Metadata
    severity INTEGER DEFAULT 5, -- 1-10
    description TEXT,
    examples TEXT[],
    false_positive_rate DOUBLE PRECISION,
    
    -- Status
    is_active BOOLEAN DEFAULT true,
    source VARCHAR(100), -- 'owasp', 'custom', 'research'
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: prompt_patterns
CREATE TABLE IF NOT EXISTS prompt_patterns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pattern_code TEXT NOT NULL UNIQUE,
    pattern_regex TEXT NOT NULL,
    pattern_description TEXT,
    suggestions TEXT[] NOT NULL DEFAULT '{}',
    category TEXT,
    domain_specific BOOLEAN DEFAULT false,
    domain_ids UUID[] DEFAULT '{}',
    match_count INTEGER DEFAULT 0,
    last_matched_at TIMESTAMPTZ,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: prompt_populations
CREATE TABLE IF NOT EXISTS prompt_populations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Population config
    target_size INTEGER DEFAULT 100,
    elite_count INTEGER DEFAULT 10,
    mutation_rate DECIMAL(5, 4) DEFAULT 0.1000,
    crossover_rate DECIMAL(5, 4) DEFAULT 0.7000,
    
    -- Current state
    generation INTEGER DEFAULT 0,
    current_size INTEGER DEFAULT 0,
    champion_id UUID,
    avg_fitness DECIMAL(10, 8) DEFAULT 0,
    max_fitness DECIMAL(10, 8) DEFAULT 0,
    diversity_index DECIMAL(10, 8) DEFAULT 1,
    
    -- Operator weights (JSON)
    operator_weights JSONB DEFAULT '{}'::jsonb,
    
    -- Evolution history
    fitness_history JSONB DEFAULT '[]'::jsonb,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    last_evolution_at TIMESTAMPTZ
);

-- Table: prompt_results
CREATE TABLE IF NOT EXISTS prompt_results (
    id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    request_id UUID NOT NULL,
    user_id UUID,
    prompt_text TEXT,
    prompt_hash VARCHAR(64),
    result_text TEXT,
    result_hash VARCHAR(64),
    orchestration_mode VARCHAR(50),
    models_used TEXT[],
    total_latency_ms INTEGER,
    cached BOOLEAN DEFAULT FALSE,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (tenant_id, id)
);

-- Table: prompt_templates
CREATE TABLE IF NOT EXISTS prompt_templates (
    template_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    
    -- Template definition
    name VARCHAR(200) NOT NULL,
    purpose VARCHAR(100) NOT NULL, -- 'reasoning', 'creativity', 'analysis', 'planning', etc.
    
    -- Content
    template_text TEXT NOT NULL,
    variables JSONB DEFAULT '[]', -- Required variables
    
    -- Performance
    times_used INTEGER DEFAULT 0,
    avg_quality DECIMAL(5,4),
    avg_latency_ms INTEGER,
    
    -- Evolution
    parent_template_id UUID REFERENCES prompt_templates(template_id),
    generation INTEGER DEFAULT 0,
    mutations JSONB DEFAULT '[]',
    
    -- A/B testing
    is_control BOOLEAN DEFAULT false,
    experiment_group VARCHAR(50),
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: prompt_violations
CREATE TABLE IF NOT EXISTS prompt_violations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Time
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Violation details
    violation_type VARCHAR(50) NOT NULL CHECK (violation_type IN (
        'content_policy', 'jailbreak_attempt', 'injection_attempt', 'pii_exposure',
        'rate_abuse', 'token_abuse', 'harassment', 'hate_speech', 'violence',
        'sexual_content', 'self_harm', 'illegal_activity', 'copyright',
        'impersonation', 'misinformation', 'other'
    )),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    
    -- Context
    conversation_id UUID,
    message_id UUID,
    model_id VARCHAR(100),
    
    -- Content (hashed for privacy, original stored encrypted)
    prompt_hash VARCHAR(64),
    prompt_snippet TEXT, -- First 200 chars, sanitized
    
    -- Detection
    detection_method VARCHAR(50) CHECK (detection_method IN (
        'content_filter', 'pattern_match', 'model_refusal', 'manual_review',
        'user_report', 'automated_scan'
    )),
    confidence DECIMAL(3, 2) CHECK (confidence >= 0 AND confidence <= 1),
    
    -- Action taken
    action_taken VARCHAR(50) CHECK (action_taken IN (
        'blocked', 'warned', 'filtered', 'logged', 'escalated', 'ignored'
    )),
    
    -- Review
    reviewed BOOLEAN DEFAULT false,
    reviewed_by UUID,
    reviewed_at TIMESTAMPTZ,
    review_outcome VARCHAR(50),
    false_positive BOOLEAN,
    
    -- Metadata
    metadata JSONB DEFAULT '{}'
);

-- Table: proposal_evidence_weights
CREATE TABLE IF NOT EXISTS proposal_evidence_weights (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    
    evidence_type VARCHAR(50) NOT NULL,
    weight DECIMAL(5, 4) NOT NULL,
    description TEXT,
    
    is_default BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, evidence_type)
);

-- Table: provider_credentials
CREATE TABLE IF NOT EXISTS provider_credentials (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    provider_id UUID NOT NULL REFERENCES ai_providers(id) ON DELETE CASCADE,
    credential_type VARCHAR(50) NOT NULL DEFAULT 'api_key',
    encrypted_value BYTEA NOT NULL,
    is_active BOOLEAN DEFAULT true,
    last_used TIMESTAMPTZ,
    usage_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tenant_id, provider_id)
);

-- Table: provider_failovers
CREATE TABLE IF NOT EXISTS provider_failovers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    primary_provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    fallback_provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    priority INTEGER NOT NULL DEFAULT 0,
    enabled BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (primary_provider_id, fallback_provider_id)
);

-- Table: provider_file_capabilities
CREATE TABLE IF NOT EXISTS provider_file_capabilities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id VARCHAR(100) NOT NULL UNIQUE,
    
    -- Supported formats (stored as JSONB array)
    supported_formats JSONB NOT NULL DEFAULT '[]'::jsonb,
    native_document_formats JSONB NOT NULL DEFAULT '[]'::jsonb,
    
    -- Size limits (bytes)
    max_file_size BIGINT NOT NULL DEFAULT 20971520,  -- 20MB default
    max_image_size BIGINT,
    max_audio_size BIGINT,
    max_video_size BIGINT,
    
    -- Capability flags
    supports_vision BOOLEAN DEFAULT false,
    supports_audio BOOLEAN DEFAULT false,
    supports_video BOOLEAN DEFAULT false,
    supports_documents BOOLEAN DEFAULT false,
    
    -- Model-specific overrides (JSON map of model_id -> capabilities)
    model_overrides JSONB DEFAULT '{}'::jsonb,
    
    -- Metadata
    last_verified_at TIMESTAMPTZ,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: provider_health
CREATE TABLE IF NOT EXISTS provider_health (
    provider VARCHAR(50) PRIMARY KEY,
    is_healthy BOOLEAN DEFAULT true,
    latency_ms INTEGER DEFAULT 0,
    last_checked TIMESTAMPTZ DEFAULT NOW(),
    error_count INTEGER DEFAULT 0,
    consecutive_failures INTEGER DEFAULT 0,
    last_success TIMESTAMPTZ,
    last_failure TIMESTAMPTZ,
    failure_reason TEXT,
    
    -- Rolling averages for better routing decisions
    avg_latency_ms DECIMAL(10,2) DEFAULT 0,
    success_rate DECIMAL(5,4) DEFAULT 1.0,
    samples_count INTEGER DEFAULT 0,
    
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: provider_health_checks
CREATE TABLE IF NOT EXISTS provider_health_checks (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    status VARCHAR(20) NOT NULL CHECK (status IN ('healthy', 'degraded', 'unhealthy')),
    latency_ms INTEGER,
    error_message TEXT,
    checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: provider_rate_limits
CREATE TABLE IF NOT EXISTS provider_rate_limits (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    requests_per_minute INTEGER NOT NULL DEFAULT 60,
    tokens_per_minute INTEGER NOT NULL DEFAULT 100000,
    requests_per_day INTEGER NOT NULL DEFAULT 10000,
    concurrent_requests INTEGER NOT NULL DEFAULT 10,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (provider_id, tenant_id)
);

-- Table: provider_refusal_log
CREATE TABLE IF NOT EXISTS provider_refusal_log (
    refusal_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    provider VARCHAR(50) NOT NULL,
    topic_cluster VARCHAR(100),
    refusal_type VARCHAR(20) NOT NULL, -- 'hard', 'soft'
    confidence DECIMAL(3,2),
    prompt_hash VARCHAR(32),
    rerouted_to VARCHAR(100),
    reroute_successful BOOLEAN,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: provider_rejections
CREATE TABLE IF NOT EXISTS provider_rejections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    
    -- Request context
    plan_id UUID,  -- AGI Brain plan if applicable
    session_id UUID,
    prompt_hash VARCHAR(64),  -- Hash of prompt for pattern detection
    
    -- Model that rejected
    model_id VARCHAR(100) NOT NULL,
    provider_id VARCHAR(50) NOT NULL,
    hosting_type VARCHAR(20) NOT NULL DEFAULT 'external',  -- external, self_hosted
    
    -- Rejection details
    rejection_type VARCHAR(50) NOT NULL,
    -- Types: content_policy, safety_filter, rate_limit, capability_mismatch, 
    --        provider_ethics, context_length, moderation, unknown
    
    rejection_code VARCHAR(100),  -- Provider-specific error code
    rejection_message TEXT,       -- Raw error message from provider
    rejection_category VARCHAR(50),  -- Categorized reason
    
    -- Our ethics check
    radiant_ethics_passed BOOLEAN NOT NULL DEFAULT true,  -- Did it pass OUR ethics?
    radiant_ethics_score NUMERIC(4,3),
    
    -- Fallback tracking
    fallback_attempted BOOLEAN NOT NULL DEFAULT false,
    fallback_model_id VARCHAR(100),
    fallback_succeeded BOOLEAN,
    fallback_chain JSONB DEFAULT '[]',  -- Array of attempted models
    
    -- Final outcome
    final_status VARCHAR(20) NOT NULL DEFAULT 'pending',
    -- Status: pending, fallback_success, rejected, user_modified, admin_override
    
    final_response_to_user TEXT,  -- Explanation shown to user
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    resolved_at TIMESTAMPTZ
);

-- Table: provider_request_log
CREATE TABLE IF NOT EXISTS provider_request_log (
    request_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    provider VARCHAR(50) NOT NULL,
    topic_cluster VARCHAR(100),
    was_refusal BOOLEAN DEFAULT false,
    response_time_ms INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: providers
CREATE TABLE IF NOT EXISTS providers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(100) NOT NULL UNIQUE,
    display_name VARCHAR(200) NOT NULL,
    type VARCHAR(20) NOT NULL CHECK (type IN ('external', 'self_hosted')),
    category VARCHAR(50) NOT NULL CHECK (category IN ('text', 'image', 'video', 'audio', 'embedding', 'search', '3d')),
    base_url VARCHAR(500) NOT NULL,
    api_key_secret_arn VARCHAR(500),
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'maintenance')),
    health_status VARCHAR(20) NOT NULL DEFAULT 'unknown' CHECK (health_status IN ('healthy', 'degraded', 'unhealthy', 'unknown')),
    config JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: provisioning_sessions
CREATE TABLE IF NOT EXISTS provisioning_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  blueprint_id UUID NOT NULL REFERENCES workflow_blueprints(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Status tracking
  status VARCHAR(50) NOT NULL DEFAULT 'pending',
  current_step INTEGER DEFAULT 0,
  total_steps INTEGER DEFAULT 0,
  
  -- Steps
  steps JSONB DEFAULT '[]',
  completed_steps JSONB DEFAULT '[]',
  failed_steps JSONB DEFAULT '[]',
  
  -- Timing
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  -- Results
  success BOOLEAN,
  error_message TEXT,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: quality_benchmark_results
CREATE TABLE IF NOT EXISTS quality_benchmark_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    
    -- Benchmark info
    model_id VARCHAR(255) NOT NULL,
    benchmark_name VARCHAR(100) NOT NULL, -- 'truthfulqa', 'factual', 'selfcheck', 'hallucination'
    
    -- Results
    score DOUBLE PRECISION NOT NULL,
    details JSONB DEFAULT '{}',
    
    -- Metadata
    duration_ms INTEGER,
    sample_count INTEGER,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: quantum_branches
CREATE TABLE IF NOT EXISTS quantum_branches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id UUID NOT NULL REFERENCES reality_engine_sessions(id) ON DELETE CASCADE,
    
    -- Branch identity
    name VARCHAR(255) NOT NULL,
    description TEXT,
    color VARCHAR(7) NOT NULL DEFAULT '#3B82F6',
    icon VARCHAR(10) NOT NULL DEFAULT '🌟',
    
    -- State
    timeline_id UUID NOT NULL REFERENCES reality_timelines(id) ON DELETE CASCADE,
    status VARCHAR(20) NOT NULL DEFAULT 'active',
    
    -- Metrics
    metrics JSONB NOT NULL DEFAULT '{
        "completionRate": 0,
        "complexityScore": 0,
        "costEstimate": 0,
        "validationErrors": 0,
        "warningCount": 0,
        "testsPassed": 0,
        "testsTotal": 0,
        "interactionCount": 0,
        "timeSpentMs": 0
    }',
    
    -- Relationships
    parent_branch_id UUID REFERENCES quantum_branches(id) ON DELETE SET NULL,
    sibling_branch_ids JSONB NOT NULL DEFAULT '[]',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    collapsed_at TIMESTAMPTZ
);

-- Table: quantum_dream_archive
CREATE TABLE IF NOT EXISTS quantum_dream_archive (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id UUID NOT NULL,
    session_id UUID NOT NULL,
    timeline_id UUID NOT NULL,
    
    -- Archived branch data
    name VARCHAR(255) NOT NULL,
    description TEXT,
    metrics JSONB NOT NULL DEFAULT '{}',
    
    archived_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: quantum_splits
CREATE TABLE IF NOT EXISTS quantum_splits (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES reality_engine_sessions(id) ON DELETE CASCADE,
    
    -- Split configuration
    parent_branch_id UUID NOT NULL REFERENCES quantum_branches(id) ON DELETE CASCADE,
    prompt TEXT NOT NULL,
    branch_ids JSONB NOT NULL DEFAULT '[]',
    
    -- UI state
    view_mode VARCHAR(20) NOT NULL DEFAULT 'single',
    active_comparison JSONB,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: query_performance_hints
CREATE TABLE IF NOT EXISTS query_performance_hints (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    query_digest VARCHAR(64) NOT NULL, -- MD5 of normalized query
    query_sample TEXT,
    table_name VARCHAR(100),
    avg_duration_ms NUMERIC(10,2),
    max_duration_ms NUMERIC(10,2),
    call_count BIGINT DEFAULT 0,
    rows_examined_avg BIGINT,
    rows_returned_avg BIGINT,
    suggested_index TEXT,
    optimization_notes TEXT,
    last_seen TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id),
    UNIQUE (query_digest)
);

-- Table: query_routing_rules
CREATE TABLE IF NOT EXISTS query_routing_rules (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    rule_name VARCHAR(100) NOT NULL,
    priority INTEGER DEFAULT 100,  -- Lower = higher priority
    
    -- Match conditions
    query_pattern TEXT,           -- Regex pattern for query matching
    table_patterns TEXT[],        -- Tables this rule applies to
    query_type VARCHAR(20),       -- 'select', 'insert', 'update', 'delete'
    tenant_ids UUID[],            -- Specific tenants (NULL = all)
    
    -- Routing decision
    target_type VARCHAR(20) NOT NULL,  -- 'primary', 'replica', 'any_replica', 'weighted'
    target_replicas TEXT[],       -- Specific replica names
    
    -- Consistency requirements
    require_primary_for_seconds INTEGER DEFAULT 0,  -- Read-after-write: route to primary for N seconds
    max_replica_lag_ms INTEGER DEFAULT 1000,        -- Max acceptable lag
    
    -- Circuit breaker
    error_threshold INTEGER DEFAULT 5,              -- Errors before fallback
    error_window_seconds INTEGER DEFAULT 60,
    fallback_target VARCHAR(20) DEFAULT 'primary',
    
    is_enabled BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id),
    UNIQUE (rule_name)
);

-- Table: question_group_members
CREATE TABLE IF NOT EXISTS question_group_members (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id UUID NOT NULL REFERENCES question_groups(id) ON DELETE CASCADE,
  
  -- Original question
  agent_id UUID NOT NULL REFERENCES agent_registry(id) ON DELETE CASCADE,
  question TEXT NOT NULL,
  context JSONB DEFAULT '{}'::jsonb,
  similarity_score DECIMAL(5,4), -- How similar to canonical question
  
  -- Fan-out tracking
  answer_delivered BOOLEAN DEFAULT FALSE,
  delivered_at TIMESTAMPTZ,
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: question_groups
CREATE TABLE IF NOT EXISTS question_groups (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Group identity
  canonical_question TEXT NOT NULL, -- The "best" version of the question
  topic_tag VARCHAR(100),
  question_embedding vector(1536),
  
  -- Status
  status VARCHAR(50) DEFAULT 'pending' CHECK (status IN ('pending', 'answered', 'expired', 'cancelled')),
  
  -- Answer (when provided)
  answer TEXT,
  answered_by UUID REFERENCES users(id),
  answered_at TIMESTAMPTZ,
  
  -- Decision tracking
  decision_id UUID REFERENCES pending_decisions(id), -- The single HITL decision for this group
  
  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ
);

-- Table: ranking_research_history
CREATE TABLE IF NOT EXISTS ranking_research_history (
    research_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    research_type TEXT NOT NULL,
    target_model_id TEXT,
    target_specialty TEXT,
    
    models_researched INTEGER DEFAULT 0,
    specialties_updated INTEGER DEFAULT 0,
    rankings_changed INTEGER DEFAULT 0,
    
    ai_confidence DECIMAL(3,2),
    sources_used JSONB DEFAULT '[]'::jsonb,
    findings TEXT,
    
    status TEXT DEFAULT 'pending',
    error_message TEXT,
    
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    duration_ms INTEGER
);

-- Table: ranking_research_schedules
CREATE TABLE IF NOT EXISTS ranking_research_schedules (
    schedule_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    description TEXT,
    
    frequency TEXT CHECK (frequency IN ('hourly', 'daily', 'weekly', 'monthly', 'manual')) DEFAULT 'daily',
    cron_expression TEXT,
    enabled BOOLEAN DEFAULT true,
    
    target_scope TEXT CHECK (target_scope IN ('all', 'specialty', 'mode', 'model')) DEFAULT 'all',
    target_filter TEXT,
    
    last_run TIMESTAMPTZ,
    last_run_status TEXT,
    next_run TIMESTAMPTZ,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: rate_limit_state
CREATE TABLE IF NOT EXISTS rate_limit_state (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    limit_key VARCHAR(255) NOT NULL, -- 'tenant:{id}:query:{digest}' or 'tenant:{id}:connection'
    limit_type VARCHAR(50) NOT NULL, -- 'query', 'connection', 'api'
    window_start TIMESTAMPTZ NOT NULL,
    window_size_seconds INTEGER NOT NULL,
    current_count INTEGER DEFAULT 0,
    max_allowed INTEGER NOT NULL,
    last_request TIMESTAMPTZ DEFAULT NOW(),
    
    PRIMARY KEY (id),
    UNIQUE (limit_key, window_start)
);

-- Table: raws_domain_config
CREATE TABLE IF NOT EXISTS raws_domain_config (
    id raws_domain PRIMARY KEY,
    display_name VARCHAR(255) NOT NULL,
    description TEXT,
    
    -- Weight profile reference
    weight_profile_id VARCHAR(50) REFERENCES raws_weight_profiles(id),
    
    -- Constraints
    min_quality_score NUMERIC(5, 2),
    max_ecd_threshold NUMERIC(4, 3),
    required_compliance TEXT[],
    forced_system_type raws_system_type,
    
    -- Verification requirements
    require_truth_engine BOOLEAN DEFAULT false,
    require_source_citation BOOLEAN DEFAULT false,
    
    -- Model preferences
    preferred_models TEXT[],
    excluded_models TEXT[],
    preferred_capabilities TEXT[],
    
    -- Detection configuration
    detection_keywords TEXT[],
    detection_confidence_threshold NUMERIC(3, 2) DEFAULT 0.70,
    
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: raws_external_models
CREATE TABLE IF NOT EXISTS raws_external_models (
    id VARCHAR(100) PRIMARY KEY,
    provider_id VARCHAR(50) NOT NULL REFERENCES raws_providers(id),
    display_name VARCHAR(255) NOT NULL,
    model_family VARCHAR(100),
    
    -- Capabilities
    capabilities TEXT[] NOT NULL DEFAULT '{}',
    context_window INTEGER NOT NULL,
    max_output_tokens INTEGER NOT NULL,
    supports_streaming BOOLEAN DEFAULT true,
    supports_function_calling BOOLEAN DEFAULT false,
    supports_vision BOOLEAN DEFAULT false,
    supports_reasoning BOOLEAN DEFAULT false,
    
    -- Provider pricing (cost to us)
    input_cost_per_1k_tokens NUMERIC(10, 6) NOT NULL,
    output_cost_per_1k_tokens NUMERIC(10, 6) NOT NULL,
    
    -- Customer pricing
    markup_percent NUMERIC(5, 2) DEFAULT 40.00,
    
    -- Quality score (0-100)
    quality_score NUMERIC(5, 2) NOT NULL DEFAULT 50.00,
    
    -- Benchmarks (stored for reference)
    benchmarks JSONB DEFAULT '{}',
    
    -- Latency metrics
    avg_ttft_ms INTEGER,
    avg_tps NUMERIC(6, 2),
    
    -- Reliability metrics
    uptime_percent_30d NUMERIC(5, 2) DEFAULT 99.90,
    error_rate_7d NUMERIC(6, 4) DEFAULT 0.0001,
    
    -- Compliance (for binary matching)
    compliance_certifications TEXT[] DEFAULT '{}',
    
    -- Status
    status raws_model_status DEFAULT 'active',
    deprecated BOOLEAN DEFAULT false,
    deprecation_date DATE,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: raws_model_performance
CREATE TABLE IF NOT EXISTS raws_model_performance (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    model_id VARCHAR(100) NOT NULL,
    
    -- Aggregated metrics (rolling 30 days)
    total_requests INTEGER DEFAULT 0,
    successful_requests INTEGER DEFAULT 0,
    avg_user_rating NUMERIC(3, 2),
    rating_count INTEGER DEFAULT 0,
    avg_ecd_score NUMERIC(4, 3),
    
    -- Performance
    avg_latency_ms INTEGER,
    p95_latency_ms INTEGER,
    
    -- Period
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(tenant_id, model_id, period_start)
);

-- Table: raws_provider_health
CREATE TABLE IF NOT EXISTS raws_provider_health (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id VARCHAR(50) NOT NULL REFERENCES raws_providers(id),
    
    -- Health metrics
    is_healthy BOOLEAN DEFAULT true,
    error_count_1h INTEGER DEFAULT 0,
    success_count_1h INTEGER DEFAULT 0,
    avg_latency_1h_ms INTEGER,
    
    -- Rate limiting
    rate_limit_hits_1h INTEGER DEFAULT 0,
    
    -- Timestamp
    checked_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: raws_providers
CREATE TABLE IF NOT EXISTS raws_providers (
    id VARCHAR(50) PRIMARY KEY,
    display_name VARCHAR(255) NOT NULL,
    api_base_url VARCHAR(500),
    auth_type VARCHAR(50) DEFAULT 'api_key',
    
    -- Health tracking
    is_healthy BOOLEAN DEFAULT true,
    last_health_check TIMESTAMPTZ,
    error_rate_1h NUMERIC(6, 4) DEFAULT 0,
    avg_latency_ms INTEGER,
    
    -- Compliance
    hipaa_eligible BOOLEAN DEFAULT false,
    soc2_certified BOOLEAN DEFAULT false,
    gdpr_compliant BOOLEAN DEFAULT false,
    
    -- Status
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: raws_selection_audit
CREATE TABLE IF NOT EXISTS raws_selection_audit (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    user_id UUID,
    session_id UUID,
    
    -- Request context
    request_id UUID NOT NULL,
    domain raws_domain,
    domain_confidence NUMERIC(3, 2),
    weight_profile_id VARCHAR(50),
    system_type raws_system_type,
    
    -- Selection result
    selected_model_id VARCHAR(100) NOT NULL,
    fallback_models TEXT[],
    composite_score NUMERIC(6, 3),
    
    -- Individual scores
    score_quality NUMERIC(5, 2),
    score_cost NUMERIC(5, 2),
    score_latency NUMERIC(5, 2),
    score_capability NUMERIC(5, 2),
    score_reliability NUMERIC(5, 2),
    score_compliance NUMERIC(5, 2),
    score_availability NUMERIC(5, 2),
    score_learning NUMERIC(5, 2),
    
    -- Performance
    selection_latency_ms INTEGER,
    
    -- Compliance flag (for extended retention)
    requires_compliance_retention BOOLEAN DEFAULT false,
    
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: raws_self_hosted_models
CREATE TABLE IF NOT EXISTS raws_self_hosted_models (
    id VARCHAR(100) PRIMARY KEY,
    display_name VARCHAR(255) NOT NULL,
    model_family VARCHAR(100),
    
    -- Deployment
    sagemaker_endpoint VARCHAR(255),
    instance_type VARCHAR(50),
    
    -- Capabilities
    capabilities TEXT[] NOT NULL DEFAULT '{}',
    context_window INTEGER NOT NULL,
    max_output_tokens INTEGER NOT NULL,
    
    -- Pricing (internal cost)
    cost_per_hour NUMERIC(10, 4),
    markup_percent NUMERIC(5, 2) DEFAULT 75.00,
    
    -- Quality
    quality_score NUMERIC(5, 2) NOT NULL DEFAULT 50.00,
    
    -- Thermal state
    thermal_state raws_thermal_state DEFAULT 'COLD',
    min_instances INTEGER DEFAULT 0,
    max_instances INTEGER DEFAULT 1,
    cold_start_ms INTEGER DEFAULT 60000,
    
    -- Status
    status raws_model_status DEFAULT 'active',
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: raws_weight_profiles
CREATE TABLE IF NOT EXISTS raws_weight_profiles (
    id VARCHAR(50) PRIMARY KEY,
    display_name VARCHAR(255) NOT NULL,
    description TEXT,
    category raws_profile_category NOT NULL,
    
    -- Eight dimension weights (must sum to 1.0)
    weight_quality NUMERIC(4, 3) NOT NULL DEFAULT 0.250,
    weight_cost NUMERIC(4, 3) NOT NULL DEFAULT 0.200,
    weight_latency NUMERIC(4, 3) NOT NULL DEFAULT 0.150,
    weight_capability NUMERIC(4, 3) NOT NULL DEFAULT 0.150,
    weight_reliability NUMERIC(4, 3) NOT NULL DEFAULT 0.100,
    weight_compliance NUMERIC(4, 3) NOT NULL DEFAULT 0.050,
    weight_availability NUMERIC(4, 3) NOT NULL DEFAULT 0.050,
    weight_learning NUMERIC(4, 3) NOT NULL DEFAULT 0.050,
    
    -- Constraints
    min_quality_score NUMERIC(5, 2),
    max_price_multiplier NUMERIC(4, 2),
    max_latency_ms INTEGER,
    required_capabilities TEXT[],
    preferred_capabilities TEXT[],
    required_compliance TEXT[],
    forced_system_type raws_system_type,
    
    -- Domain association
    domain raws_domain,
    
    -- Truth Engine integration
    require_truth_engine BOOLEAN DEFAULT false,
    require_source_citation BOOLEAN DEFAULT false,
    max_ecd_threshold NUMERIC(4, 3),
    
    -- Flags
    is_system_profile BOOLEAN DEFAULT false,
    is_default BOOLEAN DEFAULT false,
    
    -- Multi-tenancy
    tenant_id UUID,
    created_by UUID,
    
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    CONSTRAINT weights_sum_to_one CHECK (
        ABS(weight_quality + weight_cost + weight_latency + weight_capability + 
            weight_reliability + weight_compliance + weight_availability + weight_learning - 1.0) < 0.01
    )
);

-- Table: read_replica_config
CREATE TABLE IF NOT EXISTS read_replica_config (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    replica_name VARCHAR(100) NOT NULL,
    endpoint VARCHAR(255) NOT NULL,
    region VARCHAR(50),
    availability_zone VARCHAR(50),
    replica_lag_threshold_ms INTEGER DEFAULT 1000,  -- Max acceptable lag
    weight INTEGER DEFAULT 100,  -- Load balancing weight (0-100)
    is_primary BOOLEAN DEFAULT FALSE,
    is_healthy BOOLEAN DEFAULT TRUE,
    health_check_interval_seconds INTEGER DEFAULT 30,
    last_health_check TIMESTAMPTZ,
    last_lag_ms INTEGER,
    query_types TEXT[] DEFAULT ARRAY['read'],  -- 'read', 'analytics', 'reporting'
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    PRIMARY KEY (id),
    UNIQUE (replica_name)
);

-- Table: reality_engine_sessions
CREATE TABLE IF NOT EXISTS reality_engine_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id UUID NOT NULL,
    
    -- Morphic UI State
    morphic_session JSONB NOT NULL DEFAULT '{}',
    
    -- Active timeline and branch
    active_timeline_id UUID,
    active_branch_id UUID,
    
    -- Configuration
