CREATE INDEX IF NOT EXISTS idx_sagemaker_endpoints_provider_id ON sagemaker_endpoints(provider_id);
CREATE INDEX IF NOT EXISTS idx_sagemaker_endpoints_status ON sagemaker_endpoints(status);
CREATE INDEX IF NOT EXISTS idx_sagemaker_endpoints_endpoint_name ON sagemaker_endpoints(endpoint_name);
