-- ============================================================================
-- SECTION 4: FUNCTIONS
-- ============================================================================

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_tenant_context(p_tenant_id UUID, p_is_super_admin BOOLEAN DEFAULT false)
RETURNS void AS $$
BEGIN
    PERFORM set_config('app.current_tenant_id', p_tenant_id::text, true);
    PERFORM set_config('app.is_super_admin', p_is_super_admin::text, true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================================
-- HELPER FUNCTION TO CLEAR TENANT CONTEXT
-- ============================================================================

CREATE OR REPLACE FUNCTION clear_tenant_context()
RETURNS void AS $$
BEGIN
    PERFORM set_config('app.current_tenant_id', '', true);
    PERFORM set_config('app.is_super_admin', 'false', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================================
-- GRANT PERMISSIONS
-- ============================================================================

GRANT EXECUTE ON FUNCTION set_tenant_context(UUID, BOOLEAN) TO PUBLIC;
GRANT EXECUTE ON FUNCTION clear_tenant_context() TO PUBLIC;


-- Source: 003_ai_models.sql
-- RADIANT v4.17.0 - Migration 003: AI Models Registry
-- Providers and models configuration

-- ============================================================================
-- PROVIDERS TABLE
-- ============================================================================

CREATE TABLE providers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(100) NOT NULL UNIQUE,
    display_name VARCHAR(200) NOT NULL,
    type VARCHAR(20) NOT NULL CHECK (type IN ('external', 'self_hosted')),
    category VARCHAR(50) NOT NULL CHECK (category IN ('text', 'image', 'video', 'audio', 'embedding', 'search', '3d')),
    base_url VARCHAR(500) NOT NULL,
    api_key_secret_arn VARCHAR(500),
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'maintenance')),
    health_status VARCHAR(20) NOT NULL DEFAULT 'unknown' CHECK (health_status IN ('healthy', 'degraded', 'unhealthy', 'unknown')),
    config JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_providers_name ON providers(name);
CREATE INDEX idx_providers_type ON providers(type);
CREATE INDEX idx_providers_category ON providers(category);
CREATE INDEX idx_providers_status ON providers(status);

-- ============================================================================
-- MODELS TABLE
-- ============================================================================

CREATE TABLE models (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    name VARCHAR(200) NOT NULL UNIQUE,
    display_name VARCHAR(300) NOT NULL,
    category VARCHAR(50) NOT NULL CHECK (category IN ('text', 'image', 'video', 'audio', 'embedding', 'search', '3d')),
    capabilities TEXT[] NOT NULL DEFAULT '{}',
    context_window INTEGER,
    max_output_tokens INTEGER,
    input_cost_per_1k DECIMAL(10, 6) NOT NULL DEFAULT 0,
    output_cost_per_1k DECIMAL(10, 6) NOT NULL DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'deprecated')),
    config JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_models_provider_id ON models(provider_id);
CREATE INDEX idx_models_name ON models(name);
CREATE INDEX idx_models_category ON models(category);
CREATE INDEX idx_models_status ON models(status);

-- ============================================================================
-- TRIGGERS
-- ============================================================================

CREATE TRIGGER update_providers_updated_at BEFORE UPDATE ON providers
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_models_updated_at BEFORE UPDATE ON models
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

