-- Cleanup old health checks (keep last 7 days)
CREATE OR REPLACE FUNCTION cleanup_old_health_checks()
RETURNS void AS $$
BEGIN
    DELETE FROM provider_health_checks WHERE checked_at < NOW() - INTERVAL '7 days';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_hourly_metrics(p_tenant_id UUID, p_hour TIMESTAMPTZ)
RETURNS void AS $$
BEGIN
    INSERT INTO aggregated_metrics (
        tenant_id, period_start, period_end, period_type, metric_type,
        total_requests, total_tokens, total_cost, avg_latency_ms,
        error_count, unique_users
    )
    SELECT 
        tenant_id,
        date_trunc('hour', p_hour),
        date_trunc('hour', p_hour) + INTERVAL '1 hour',
        'hourly',
        metric_type,
        COUNT(*),
        SUM(CASE WHEN metric_name = 'tokens' THEN metric_value ELSE 0 END)::BIGINT,
        SUM(CASE WHEN metric_name = 'cost' THEN metric_value ELSE 0 END),
        AVG(CASE WHEN metric_name = 'latency_ms' THEN metric_value END),
        COUNT(*) FILTER (WHERE metric_name = 'error'),
        COUNT(DISTINCT user_id)
    FROM usage_metrics
    WHERE tenant_id = p_tenant_id
    AND recorded_at >= date_trunc('hour', p_hour)
    AND recorded_at < date_trunc('hour', p_hour) + INTERVAL '1 hour'
    GROUP BY tenant_id, metric_type
    ON CONFLICT (tenant_id, period_start, period_type, metric_type) 
    DO UPDATE SET
        total_requests = EXCLUDED.total_requests,
        total_tokens = EXCLUDED.total_tokens,
        total_cost = EXCLUDED.total_cost,
        avg_latency_ms = EXCLUDED.avg_latency_ms,
        error_count = EXCLUDED.error_count,
        unique_users = EXCLUDED.unique_users;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION search_user_memories(
    p_tenant_id UUID,
    p_user_id UUID,
    p_query_embedding vector(1536),
    p_limit INTEGER DEFAULT 5
)
RETURNS TABLE (
    id UUID,
    content TEXT,
    memory_type VARCHAR(50),
    importance DECIMAL(3, 2),
    similarity FLOAT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        um.id,
        um.content,
        um.memory_type,
        um.importance,
        1 - (um.embedding <=> p_query_embedding) as similarity
    FROM user_memory um
    WHERE um.tenant_id = p_tenant_id 
    AND um.user_id = p_user_id
    AND (um.expires_at IS NULL OR um.expires_at > NOW())
    ORDER BY um.embedding <=> p_query_embedding
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION search_memories_by_embedding(
    p_store_id UUID,
    p_query_embedding vector(1536),
    p_limit INTEGER DEFAULT 5,
    p_min_similarity FLOAT DEFAULT 0.7
)
RETURNS TABLE (
    id UUID,
    content TEXT,
    memory_type VARCHAR(50),
    importance DECIMAL(3, 2),
    similarity FLOAT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.id,
        m.content,
        m.memory_type,
        m.importance,
        (1 - (m.embedding <=> p_query_embedding))::FLOAT as similarity
    FROM memories m
    WHERE m.store_id = p_store_id
    AND (m.expires_at IS NULL OR m.expires_at > NOW())
    AND (1 - (m.embedding <=> p_query_embedding)) >= p_min_similarity
    ORDER BY m.embedding <=> p_query_embedding
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_team_tokens(p_team_id UUID, p_member_id UUID, p_tokens_needed INTEGER)
RETURNS BOOLEAN AS $$
DECLARE
    v_team team_plans%ROWTYPE;
    v_member team_members%ROWTYPE;
BEGIN
    SELECT * INTO v_team FROM team_plans WHERE id = p_team_id AND is_active = true;
    IF NOT FOUND THEN RETURN false; END IF;
    
    SELECT * INTO v_member FROM team_members WHERE id = p_member_id AND is_active = true;
    IF NOT FOUND THEN RETURN false; END IF;
    
    IF v_team.shared_pool THEN
        RETURN (v_team.tokens_used_this_period + p_tokens_needed) <= v_team.total_tokens_monthly;
    ELSE
        RETURN v_member.token_allocation IS NULL OR 
               (v_member.tokens_used_this_period + p_tokens_needed) <= v_member.token_allocation;
    END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_time_machine_snapshot(
    p_chat_id UUID,
    p_tenant_id UUID,
    p_trigger VARCHAR(50),
    p_trigger_details JSONB DEFAULT '{}'
) RETURNS UUID AS $$
DECLARE
    v_snapshot_id UUID;
    v_version INTEGER;
    v_previous_id UUID;
    v_message_count INTEGER;
    v_file_count INTEGER;
    v_checksum VARCHAR(64);
BEGIN
    -- Get next version number
    SELECT COALESCE(MAX(version), 0) + 1, id
    INTO v_version, v_previous_id
    FROM time_machine_snapshots
    WHERE chat_id = p_chat_id
    GROUP BY id
    ORDER BY version DESC
    LIMIT 1;
    
    v_version := COALESCE(v_version, 1);
    
    -- Count current messages and files
    SELECT COUNT(*) INTO v_message_count
    FROM message_versions
    WHERE snapshot_id IN (SELECT id FROM time_machine_snapshots WHERE chat_id = p_chat_id)
    AND is_active = true AND is_soft_deleted = false;
    
    SELECT COUNT(*) INTO v_file_count
    FROM media_vault
    WHERE chat_id = p_chat_id AND status = 'active';
    
    -- Generate checksum (simplified)
    v_checksum := encode(sha256(p_chat_id::text || v_version::text || NOW()::text), 'hex');
    
    INSERT INTO time_machine_snapshots (
        chat_id, tenant_id, version, trigger, trigger_details,
        message_count, file_count, previous_snapshot_id, checksum
    ) VALUES (
        p_chat_id, p_tenant_id, v_version, p_trigger, p_trigger_details,
        v_message_count, v_file_count, v_previous_id, v_checksum
    ) RETURNING id INTO v_snapshot_id;
    
    RETURN v_snapshot_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION current_app_id() RETURNS VARCHAR(50) AS $$
