RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION analyze_model_specialties(p_model_id VARCHAR, p_capabilities TEXT[])
RETURNS TEXT[] AS $$
DECLARE
    v_suggested_specialties TEXT[] := '{}';
    v_cap TEXT;
BEGIN
    FOREACH v_cap IN ARRAY p_capabilities LOOP
        -- Map capabilities to specialties
        CASE LOWER(v_cap)
            WHEN 'reasoning' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'deep_reasoning');
            WHEN 'math' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'math_computation');
            WHEN 'coding' THEN 
                v_suggested_specialties := array_append(v_suggested_specialties, 'code_generation');
                v_suggested_specialties := array_append(v_suggested_specialties, 'code_review');
                v_suggested_specialties := array_append(v_suggested_specialties, 'code_explanation');
            WHEN 'vision' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'image_analysis');
            WHEN 'creative' THEN 
                v_suggested_specialties := array_append(v_suggested_specialties, 'creative_writing');
                v_suggested_specialties := array_append(v_suggested_specialties, 'content_generation');
            WHEN 'multilingual' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'translation');
            WHEN 'fast' THEN 
                v_suggested_specialties := array_append(v_suggested_specialties, 'quick_answer');
                v_suggested_specialties := array_append(v_suggested_specialties, 'classification');
            WHEN 'efficient' THEN 
                v_suggested_specialties := array_append(v_suggested_specialties, 'quick_answer');
                v_suggested_specialties := array_append(v_suggested_specialties, 'summarization');
            WHEN 'long-context' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'summarization');
            WHEN 'analysis' THEN 
                v_suggested_specialties := array_append(v_suggested_specialties, 'scientific_analysis');
                v_suggested_specialties := array_append(v_suggested_specialties, 'deep_reasoning');
            WHEN 'planning' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'deep_reasoning');
            WHEN 'language' THEN v_suggested_specialties := array_append(v_suggested_specialties, 'content_generation');
            WHEN 'general' THEN 
                v_suggested_specialties := array_append(v_suggested_specialties, 'quick_answer');
                v_suggested_specialties := array_append(v_suggested_specialties, 'content_generation');
            ELSE NULL;
        END CASE;
    END LOOP;
    
    -- Return unique specialties
    RETURN ARRAY(SELECT DISTINCT unnest(v_suggested_specialties));
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION register_model_with_orchestration(
    p_model_id VARCHAR,
    p_provider VARCHAR,
    p_source VARCHAR, -- 'external' or 'self-hosted'
    p_capabilities TEXT[],
    p_is_fast BOOLEAN DEFAULT false,
    p_quality_tier INTEGER DEFAULT 2 -- 1=premium, 2=standard, 3=economy
)
RETURNS void AS $$
DECLARE
    v_specialties TEXT[];
    v_specialty TEXT;
    v_current_models TEXT[];
    v_position INTEGER;
BEGIN
    -- Analyze capabilities to determine specialties
    v_specialties := analyze_model_specialties(p_model_id, p_capabilities);
    
    -- Register model with each relevant specialty
    FOREACH v_specialty IN ARRAY v_specialties LOOP
        -- Get current models for this specialty
        SELECT preferred_models INTO v_current_models 
        FROM model_specialties WHERE name = v_specialty;
        
        IF v_current_models IS NULL THEN
            CONTINUE;
        END IF;
        
        -- Skip if already registered
        IF p_model_id = ANY(v_current_models) THEN
            CONTINUE;
        END IF;
        
        -- Determine position based on quality tier and source
        IF p_quality_tier = 1 THEN
            -- Premium models go to front
            v_position := 1;
        ELSIF p_source = 'self-hosted' THEN
            -- Self-hosted models go after top 2
            v_position := LEAST(3, array_length(v_current_models, 1) + 1);
        ELSE
            -- Standard models go to middle/end
            v_position := LEAST(array_length(v_current_models, 1) + 1, 5);
        END IF;
        
        -- Insert at position
        v_current_models := array_cat(
            v_current_models[1:v_position-1],
            ARRAY[p_model_id] || v_current_models[v_position:]
        );
        
        -- Limit to top 5 preferred models
        v_current_models := v_current_models[1:5];
        
        -- Update specialty
        UPDATE model_specialties 
        SET preferred_models = v_current_models
        WHERE name = v_specialty;
        
        -- Initialize performance tracking
        INSERT INTO model_specialty_performance (model_id, specialty_name, avg_quality_score, specialty_rank)
        VALUES (p_model_id, v_specialty, 
                CASE p_quality_tier WHEN 1 THEN 0.85 WHEN 2 THEN 0.75 ELSE 0.65 END,
                v_position)
        ON CONFLICT (model_id, specialty_name) DO NOTHING;
    END LOOP;
    
    -- If self-hosted, create/update pool entry
    IF p_source = 'self-hosted' THEN
        INSERT INTO self_hosted_model_pools (tenant_id, name, model_id, thermal_state)
        VALUES (NULL, p_model_id, p_model_id, 'COLD')
        ON CONFLICT DO NOTHING;
    END IF;
    
    -- Log the registration
    INSERT INTO model_registry_events (event_type, source_table, model_id, provider, change_details, processed, processed_at)
    VALUES ('model_registered_orchestration', 'orchestration_sync', p_model_id, p_provider, 
            jsonb_build_object('specialties', v_specialties, 'source', p_source, 'quality_tier', p_quality_tier),
            true, NOW());
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION unregister_model_from_orchestration(p_model_id VARCHAR)
RETURNS void AS $$
DECLARE
    v_specialty RECORD;
BEGIN
    -- Remove from all specialty preferred/fallback lists
    FOR v_specialty IN SELECT specialty_id, name, preferred_models, fallback_models FROM model_specialties LOOP
        IF p_model_id = ANY(v_specialty.preferred_models) THEN
            UPDATE model_specialties 
            SET preferred_models = array_remove(preferred_models, p_model_id)
            WHERE specialty_id = v_specialty.specialty_id;
        END IF;
        
        IF p_model_id = ANY(v_specialty.fallback_models) THEN
            UPDATE model_specialties 
            SET fallback_models = array_remove(fallback_models, p_model_id)
            WHERE specialty_id = v_specialty.specialty_id;
        END IF;
    END LOOP;
    
    -- Remove performance tracking
    DELETE FROM model_specialty_performance WHERE model_id = p_model_id;
    
    -- Remove self-hosted pool entry
    DELETE FROM self_hosted_model_pools WHERE model_id = p_model_id;
    
    -- Log the removal
    INSERT INTO model_registry_events (event_type, source_table, model_id, change_details, processed, processed_at)
    VALUES ('model_unregistered_orchestration', 'orchestration_sync', p_model_id, 
            jsonb_build_object('action', 'removed'), true, NOW());
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION sync_orchestration_from_registry()
RETURNS TABLE(models_synced INTEGER, models_removed INTEGER, errors TEXT[]) AS $$
DECLARE
    v_model RECORD;
    v_synced INTEGER := 0;
    v_removed INTEGER := 0;
    v_errors TEXT[] := '{}';
    v_capabilities TEXT[];
    v_quality_tier INTEGER;
BEGIN
    -- Sync enabled models from unified registry
    FOR v_model IN 
        SELECT model_id, provider, source, capabilities, 
               CASE 
                   WHEN input_price_per_1m > 10 THEN 1 -- Premium
                   WHEN input_price_per_1m > 1 THEN 2 -- Standard
                   ELSE 3 -- Economy
               END as quality_tier
        FROM unified_model_registry 
        WHERE enabled = true AND deprecated = false
    LOOP
        BEGIN
            v_capabilities := COALESCE(v_model.capabilities, '{}');
            PERFORM register_model_with_orchestration(
                v_model.model_id,
                v_model.provider,
                v_model.source,
                v_capabilities,
                'fast' = ANY(v_capabilities),
                v_model.quality_tier
            );
            v_synced := v_synced + 1;
        EXCEPTION WHEN OTHERS THEN
            v_errors := array_append(v_errors, v_model.model_id || ': ' || SQLERRM);
        END;
    END LOOP;
    
    -- Remove disabled/deprecated models from orchestration
    FOR v_model IN
        SELECT DISTINCT msp.model_id 
        FROM model_specialty_performance msp
        LEFT JOIN unified_model_registry umr ON msp.model_id = umr.model_id
        WHERE umr.model_id IS NULL 
           OR umr.enabled = false 
           OR umr.deprecated = true
    LOOP
        BEGIN
            PERFORM unregister_model_from_orchestration(v_model.model_id);
            v_removed := v_removed + 1;
        EXCEPTION WHEN OTHERS THEN
            v_errors := array_append(v_errors, 'Remove ' || v_model.model_id || ': ' || SQLERRM);
        END;
    END LOOP;
    
    RETURN QUERY SELECT v_synced, v_removed, v_errors;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION on_model_registry_change()
RETURNS TRIGGER AS $$
DECLARE
    v_capabilities TEXT[];
    v_quality_tier INTEGER;
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Log the event
        INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, provider, change_details)
        VALUES ('model_added', 'unified_model_registry', NEW.id::VARCHAR, NEW.model_id, NEW.provider,
                jsonb_build_object('source', NEW.source, 'capabilities', NEW.capabilities));
        
        -- Auto-register if enabled and not deprecated
        IF NEW.enabled AND NOT NEW.deprecated THEN
            v_capabilities := COALESCE(NEW.capabilities, '{}');
            v_quality_tier := CASE 
                WHEN NEW.input_price_per_1m > 10 THEN 1
                WHEN NEW.input_price_per_1m > 1 THEN 2
                ELSE 3
            END;
            
            PERFORM register_model_with_orchestration(
                NEW.model_id, NEW.provider, NEW.source, v_capabilities,
                'fast' = ANY(v_capabilities), v_quality_tier
            );
        END IF;
        
        RETURN NEW;
        
    ELSIF TG_OP = 'UPDATE' THEN
        -- Log the event
        INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, provider, change_details)
        VALUES ('model_updated', 'unified_model_registry', NEW.id::VARCHAR, NEW.model_id, NEW.provider,
                jsonb_build_object(
                    'enabled_changed', OLD.enabled IS DISTINCT FROM NEW.enabled,
                    'deprecated_changed', OLD.deprecated IS DISTINCT FROM NEW.deprecated,
                    'capabilities_changed', OLD.capabilities IS DISTINCT FROM NEW.capabilities
                ));
        
        -- Handle enable/disable/deprecate changes
        IF (OLD.enabled AND NOT NEW.enabled) OR (NOT OLD.deprecated AND NEW.deprecated) THEN
            -- Model disabled or deprecated - remove from orchestration
            PERFORM unregister_model_from_orchestration(NEW.model_id);
        ELSIF (NOT OLD.enabled AND NEW.enabled) OR (OLD.deprecated AND NOT NEW.deprecated) THEN
            -- Model enabled or un-deprecated - add to orchestration
            v_capabilities := COALESCE(NEW.capabilities, '{}');
            v_quality_tier := CASE 
                WHEN NEW.input_price_per_1m > 10 THEN 1
                WHEN NEW.input_price_per_1m > 1 THEN 2
                ELSE 3
            END;
            
            PERFORM register_model_with_orchestration(
                NEW.model_id, NEW.provider, NEW.source, v_capabilities,
                'fast' = ANY(v_capabilities), v_quality_tier
            );
        ELSIF OLD.capabilities IS DISTINCT FROM NEW.capabilities THEN
            -- Capabilities changed - re-register
            PERFORM unregister_model_from_orchestration(NEW.model_id);
            
            v_capabilities := COALESCE(NEW.capabilities, '{}');
            v_quality_tier := CASE 
                WHEN NEW.input_price_per_1m > 10 THEN 1
                WHEN NEW.input_price_per_1m > 1 THEN 2
                ELSE 3
            END;
            
            PERFORM register_model_with_orchestration(
                NEW.model_id, NEW.provider, NEW.source, v_capabilities,
                'fast' = ANY(v_capabilities), v_quality_tier
            );
        END IF;
        
        RETURN NEW;
        
    ELSIF TG_OP = 'DELETE' THEN
        -- Log the event
        INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, provider, change_details)
        VALUES ('model_removed', 'unified_model_registry', OLD.id::VARCHAR, OLD.model_id, OLD.provider,
                jsonb_build_object('removed', true));
        
        -- Remove from orchestration
        PERFORM unregister_model_from_orchestration(OLD.model_id);
        
        RETURN OLD;
    END IF;
    
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION on_provider_health_change()
RETURNS TRIGGER AS $$
BEGIN
    -- Log significant health changes
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO model_registry_events (event_type, source_table, source_id, provider, change_details)
        VALUES ('provider_health_changed', 'provider_health', NEW.id::VARCHAR, NEW.provider_id,
                jsonb_build_object('old_status', OLD.status, 'new_status', NEW.status));
        
        -- If provider became unhealthy, we might want to adjust routing
        -- This is handled by the orchestrator at runtime, but we log for auditing
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION on_self_hosted_model_change()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, change_details)
        VALUES ('self_hosted_added', 'self_hosted_model_pools', NEW.pool_id::VARCHAR, NEW.model_id,
                jsonb_build_object('thermal_state', NEW.thermal_state));
        RETURN NEW;
        
    ELSIF TG_OP = 'UPDATE' THEN
        -- Log thermal state changes
        IF NEW.thermal_state IS DISTINCT FROM OLD.thermal_state THEN
            INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, change_details)
            VALUES ('self_hosted_thermal_changed', 'self_hosted_model_pools', NEW.pool_id::VARCHAR, NEW.model_id,
                    jsonb_build_object('old_state', OLD.thermal_state, 'new_state', NEW.thermal_state));
        END IF;
        
        -- Log instance count changes
        IF NEW.healthy_instances IS DISTINCT FROM OLD.healthy_instances THEN
            INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, change_details)
            VALUES ('self_hosted_instances_changed', 'self_hosted_model_pools', NEW.pool_id::VARCHAR, NEW.model_id,
                    jsonb_build_object('old_instances', OLD.healthy_instances, 'new_instances', NEW.healthy_instances));
        END IF;
        
        RETURN NEW;
        
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO model_registry_events (event_type, source_table, source_id, model_id, change_details)
        VALUES ('self_hosted_removed', 'self_hosted_model_pools', OLD.pool_id::VARCHAR, OLD.model_id,
                jsonb_build_object('removed', true));
        
        RETURN OLD;
    END IF;
    
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION run_orchestration_sync(p_sync_type VARCHAR DEFAULT 'incremental')
RETURNS UUID AS $$
DECLARE
    v_sync_id UUID;
    v_start TIMESTAMPTZ := NOW();
    v_result RECORD;
BEGIN
    INSERT INTO orchestration_sync_log (sync_type, started_at)
    VALUES (p_sync_type, v_start)
    RETURNING sync_id INTO v_sync_id;
    
    -- Run sync
    SELECT * INTO v_result FROM sync_orchestration_from_registry();
    
    -- Update log
    UPDATE orchestration_sync_log SET
        models_synced = v_result.models_synced,
        models_removed = v_result.models_removed,
        errors = v_result.errors,
        duration_ms = EXTRACT(MILLISECONDS FROM NOW() - v_start)::INTEGER,
        completed_at = NOW()
    WHERE sync_id = v_sync_id;
    
    RETURN v_sync_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION notify_orchestration_change()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM pg_notify('orchestration_changes', json_build_object(
        'event_type', NEW.event_type,
        'model_id', NEW.model_id,
        'provider', NEW.provider,
        'timestamp', NEW.created_at
    )::text);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION increment_config_version(
    p_config_type VARCHAR,
    p_change_type VARCHAR,
    p_change_source VARCHAR DEFAULT NULL,
    p_changed_by VARCHAR DEFAULT NULL,
    p_affected_keys TEXT[] DEFAULT '{}',
    p_change_summary TEXT DEFAULT NULL,
    p_change_payload JSONB DEFAULT '{}'
)
RETURNS BIGINT AS $$
DECLARE
    v_new_version BIGINT;
BEGIN
    -- Increment counter
    UPDATE config_version_counters 
    SET current_version = current_version + 1, last_updated = NOW()
    WHERE config_type = p_config_type
    RETURNING current_version INTO v_new_version;
    
    IF v_new_version IS NULL THEN
        -- Config type doesn't exist, create it
        INSERT INTO config_version_counters (config_type, current_version)
        VALUES (p_config_type, 1)
        RETURNING current_version INTO v_new_version;
    END IF;
    
    -- Log the version change
    INSERT INTO config_versions (
        version_number, config_type, change_type, change_source, 
        changed_by, affected_keys, change_summary, change_payload
    ) VALUES (
        v_new_version, p_config_type, p_change_type, p_change_source,
        p_changed_by, p_affected_keys, p_change_summary, p_change_payload
    );
    
    -- Create notification
    INSERT INTO config_change_notifications (
        config_type, version_number, change_type, notification_payload
    ) VALUES (
        p_config_type, v_new_version, p_change_type,
        jsonb_build_object(
            'version', v_new_version,
            'type', p_change_type,
            'affected_keys', p_affected_keys,
            'timestamp', NOW()
        )
    );
    
    -- Send PostgreSQL notification for real-time listeners
    PERFORM pg_notify('config_changes', json_build_object(
        'config_type', p_config_type,
        'version', v_new_version,
        'change_type', p_change_type,
        'timestamp', NOW()
    )::text);
    
    -- Invalidate affected cache entries
    UPDATE live_config_cache 
    SET expires_at = NOW() 
    WHERE config_type = p_config_type;
    
    RETURN v_new_version;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_config_version(p_config_type VARCHAR)
RETURNS BIGINT AS $$
DECLARE
    v_version BIGINT;
BEGIN
    SELECT current_version INTO v_version 
    FROM config_version_counters 
    WHERE config_type = p_config_type;
    
    RETURN COALESCE(v_version, 0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_config_freshness(p_service_versions JSONB)
RETURNS TABLE(config_type VARCHAR, current_version BIGINT, service_version BIGINT, needs_update BOOLEAN) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        cvc.config_type::VARCHAR,
        cvc.current_version,
        COALESCE((p_service_versions->>cvc.config_type)::BIGINT, 0) as service_version,
        cvc.current_version > COALESCE((p_service_versions->>cvc.config_type)::BIGINT, 0) as needs_update
    FROM config_version_counters cvc;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_pending_notifications(
    p_service_id UUID,
    p_last_seen_versions JSONB
)
RETURNS TABLE(
    notification_id UUID,
    config_type VARCHAR,
    version_number BIGINT,
    change_type VARCHAR,
    priority VARCHAR,
    requires_restart BOOLEAN,
    notification_payload JSONB
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ccn.notification_id,
        ccn.config_type::VARCHAR,
        ccn.version_number,
        ccn.change_type::VARCHAR,
        ccn.priority::VARCHAR,
        ccn.requires_restart,
        ccn.notification_payload
    FROM config_change_notifications ccn
    WHERE ccn.expires_at > NOW()
      AND ccn.version_number > COALESCE((p_last_seen_versions->>ccn.config_type)::BIGINT, 0)
      AND NOT (p_service_id::TEXT = ANY(ccn.acknowledged_by))
    ORDER BY ccn.created_at ASC;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION acknowledge_notifications(
    p_service_id UUID,
    p_notification_ids UUID[]
)
RETURNS void AS $$
BEGIN
    UPDATE config_change_notifications
    SET acknowledged_by = array_append(acknowledged_by, p_service_id::TEXT)
    WHERE notification_id = ANY(p_notification_ids);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cache_config(
    p_cache_key VARCHAR,
    p_config_type VARCHAR,
    p_value JSONB,
    p_ttl_seconds INTEGER DEFAULT NULL
)
RETURNS void AS $$
DECLARE
    v_version BIGINT;
    v_expires TIMESTAMPTZ;
BEGIN
    SELECT current_version INTO v_version FROM config_version_counters WHERE config_type = p_config_type;
    
    IF p_ttl_seconds IS NOT NULL THEN
        v_expires := NOW() + (p_ttl_seconds || ' seconds')::INTERVAL;
    END IF;
    
    INSERT INTO live_config_cache (cache_key, config_type, cached_value, version_number, expires_at)
    VALUES (p_cache_key, p_config_type, p_value, COALESCE(v_version, 0), v_expires)
    ON CONFLICT (cache_key) DO UPDATE SET
        cached_value = EXCLUDED.cached_value,
        version_number = EXCLUDED.version_number,
        expires_at = EXCLUDED.expires_at,
        updated_at = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_cached_config(p_cache_key VARCHAR)
RETURNS JSONB AS $$
DECLARE
    v_cached RECORD;
    v_current_version BIGINT;
BEGIN
    SELECT * INTO v_cached FROM live_config_cache WHERE cache_key = p_cache_key;
    
    IF v_cached IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Check expiry
    IF v_cached.expires_at IS NOT NULL AND v_cached.expires_at < NOW() THEN
        DELETE FROM live_config_cache WHERE cache_key = p_cache_key;
        RETURN NULL;
    END IF;
    
    -- Check version freshness
    SELECT current_version INTO v_current_version 
    FROM config_version_counters 
    WHERE config_type = v_cached.config_type;
    
    IF v_current_version > v_cached.version_number THEN
        -- Stale cache
        DELETE FROM live_config_cache WHERE cache_key = p_cache_key;
        RETURN NULL;
    END IF;
    
    -- Update hit stats
    UPDATE live_config_cache 
    SET hit_count = hit_count + 1, last_hit = NOW()
    WHERE cache_key = p_cache_key;
    
    RETURN v_cached.cached_value;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION service_heartbeat(
    p_service_name VARCHAR,
    p_service_type VARCHAR,
    p_instance_identifier VARCHAR DEFAULT NULL,
    p_config_versions JSONB DEFAULT '{}'
)
RETURNS UUID AS $$
DECLARE
    v_instance_id UUID;
BEGIN
    -- Try to find existing instance
    SELECT instance_id INTO v_instance_id
    FROM service_instances
    WHERE service_name = p_service_name
      AND instance_identifier = p_instance_identifier
      AND status = 'active';
    
    IF v_instance_id IS NOT NULL THEN
        -- Update heartbeat
        UPDATE service_instances SET
            last_heartbeat = NOW(),
            config_versions = p_config_versions
        WHERE instance_id = v_instance_id;
    ELSE
        -- Register new instance
        INSERT INTO service_instances (
            service_name, service_type, instance_identifier, config_versions
        ) VALUES (
            p_service_name, p_service_type, p_instance_identifier, p_config_versions
        )
        RETURNING instance_id INTO v_instance_id;
    END IF;
    
    RETURN v_instance_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION version_model_registry_change()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        PERFORM increment_config_version(
            'models', 'create', TG_TABLE_NAME, NULL,
            ARRAY[NEW.model_id], 'Model added: ' || NEW.model_id,
            jsonb_build_object('model_id', NEW.model_id, 'provider', NEW.provider)
        );
    ELSIF TG_OP = 'UPDATE' THEN
        PERFORM increment_config_version(
            'models', 'update', TG_TABLE_NAME, NULL,
            ARRAY[NEW.model_id], 'Model updated: ' || NEW.model_id,
            jsonb_build_object('model_id', NEW.model_id, 'changes', 
                jsonb_build_object(
                    'enabled', NEW.enabled,
                    'deprecated', NEW.deprecated
                ))
        );
    ELSIF TG_OP = 'DELETE' THEN
        PERFORM increment_config_version(
            'models', 'delete', TG_TABLE_NAME, NULL,
            ARRAY[OLD.model_id], 'Model removed: ' || OLD.model_id,
            jsonb_build_object('model_id', OLD.model_id)
        );
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION version_specialty_change()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM increment_config_version(
        'specialties', TG_OP, TG_TABLE_NAME, NULL,
        ARRAY[COALESCE(NEW.name, OLD.name)], 
        'Specialty ' || TG_OP || ': ' || COALESCE(NEW.name, OLD.name),
        jsonb_build_object('specialty', COALESCE(NEW.name, OLD.name))
    );
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION version_orchestration_change()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM increment_config_version(
        'orchestration', 'update', TG_TABLE_NAME, NULL,
        ARRAY[NEW.tenant_id::TEXT], 
        'Orchestration settings updated',
        jsonb_build_object('tenant_id', NEW.tenant_id)
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION version_system_config_change()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM increment_config_version(
        'system', TG_OP, TG_TABLE_NAME, NULL,
        ARRAY[COALESCE(NEW.key, OLD.key)], 
        'System config ' || TG_OP || ': ' || COALESCE(NEW.key, OLD.key),
        jsonb_build_object('key', COALESCE(NEW.key, OLD.key))
    );
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_config_engine()
RETURNS void AS $$
BEGIN
    -- Mark stale service instances
    UPDATE service_instances 
    SET status = 'stale'
    WHERE status = 'active' 
      AND last_heartbeat < NOW() - INTERVAL '5 minutes';
    
    -- Delete old terminated instances
    DELETE FROM service_instances
    WHERE status IN ('stale', 'terminated')
      AND last_heartbeat < NOW() - INTERVAL '1 hour';
    
    -- Delete expired notifications
    DELETE FROM config_change_notifications
    WHERE expires_at < NOW();
    
    -- Delete expired cache entries
    DELETE FROM live_config_cache
    WHERE expires_at IS NOT NULL AND expires_at < NOW();
    
    -- Keep only last 1000 versions per config type
    DELETE FROM config_versions
    WHERE version_id IN (
        SELECT version_id FROM (
            SELECT version_id, ROW_NUMBER() OVER (
                PARTITION BY config_type ORDER BY version_number DESC
            ) as rn
            FROM config_versions
        ) sub WHERE rn > 1000
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION generate_explanation_stub(
    p_tenant_id UUID,
    p_request_id UUID,
    p_reasoning_chain JSONB,
    p_key_factors JSONB
)
RETURNS UUID AS $$
DECLARE
    v_trace_id UUID;
BEGIN
    INSERT INTO explanation_traces (
        tenant_id, request_id, reasoning_chain, key_factors
    ) VALUES (
        p_tenant_id, p_request_id, p_reasoning_chain, p_key_factors
    ) RETURNING trace_id INTO v_trace_id;
    
    RETURN v_trace_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_safety_violation(
    p_tenant_id UUID,
    p_rule_id UUID,
    p_violation_type VARCHAR,
    p_content_type VARCHAR,
    p_action_taken VARCHAR,
    p_was_blocked BOOLEAN
)
RETURNS UUID AS $$
DECLARE
    v_violation_id UUID;
BEGIN
    INSERT INTO safety_violations (
        tenant_id, rule_id, violation_type, content_type, action_taken, was_blocked
    ) VALUES (
        p_tenant_id, p_rule_id, p_violation_type, p_content_type, p_action_taken, p_was_blocked
    ) RETURNING violation_id INTO v_violation_id;
    
    -- Update rule stats
    UPDATE safety_rules SET times_triggered = times_triggered + 1 WHERE rule_id = p_rule_id;
    
    RETURN v_violation_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION process_feedback_for_learning(p_feedback_id UUID)
RETURNS BOOLEAN AS $$
DECLARE
    v_feedback RECORD;
BEGIN
    SELECT * INTO v_feedback FROM user_feedback WHERE feedback_id = p_feedback_id;
    
    IF v_feedback IS NULL OR v_feedback.processed THEN
        RETURN false;
    END IF;
    
    -- Mark as processed
    UPDATE user_feedback SET processed = true WHERE feedback_id = p_feedback_id;
    
    -- If it's a correction, potentially create a correction pattern
    IF v_feedback.feedback_type = 'correction' AND v_feedback.corrected_response IS NOT NULL THEN
        -- Could trigger more sophisticated learning here
        UPDATE user_feedback SET learning_applied = true WHERE feedback_id = p_feedback_id;
    END IF;
    
    -- If it's a preference, update learned preferences
    IF v_feedback.feedback_type = 'preference' AND v_feedback.preference_key IS NOT NULL THEN
        INSERT INTO learned_preferences (
            tenant_id, user_id, preference_type, preference_key, preference_value, learned_from
        ) VALUES (
            v_feedback.tenant_id, v_feedback.user_id, 'user_stated', 
            v_feedback.preference_key, v_feedback.preference_value, ARRAY[p_feedback_id]
        )
        ON CONFLICT (tenant_id, user_id, preference_type, preference_key) DO UPDATE SET
            preference_value = EXCLUDED.preference_value,
            sample_count = learned_preferences.sample_count + 1,
            learned_from = array_append(learned_preferences.learned_from, p_feedback_id::TEXT),
            updated_at = NOW();
        
        UPDATE user_feedback SET learning_applied = true WHERE feedback_id = p_feedback_id;
    END IF;
    
    RETURN true;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION detect_user_pattern(
    p_tenant_id UUID,
    p_user_id UUID,
    p_action TEXT,
    p_context JSONB
)
RETURNS void AS $$
DECLARE
    v_existing RECORD;
BEGIN
    -- Check for existing pattern
    SELECT * INTO v_existing
    FROM user_behavior_patterns
    WHERE tenant_id = p_tenant_id
      AND (user_id = p_user_id OR user_id IS NULL)
      AND predicted_action = p_action
    LIMIT 1;
    
    IF v_existing IS NOT NULL THEN
        -- Update existing pattern
        UPDATE user_behavior_patterns SET
            occurrence_count = occurrence_count + 1,
            last_occurrence = NOW(),
            confidence = LEAST(1.0, confidence + 0.05),
            example_instances = (
                SELECT jsonb_agg(inst) FROM (
                    SELECT inst FROM jsonb_array_elements(example_instances) inst
                    ORDER BY inst->>'timestamp' DESC
                    LIMIT 9
                ) sub
            ) || jsonb_build_object('context', p_context, 'timestamp', NOW()),
            updated_at = NOW()
        WHERE pattern_id = v_existing.pattern_id;
    ELSE
        -- Create new pattern
        INSERT INTO user_behavior_patterns (
            tenant_id, user_id, pattern_type, predicted_action, trigger_conditions, example_instances
        ) VALUES (
            p_tenant_id, p_user_id, 'contextual', p_action, p_context,
            jsonb_build_array(jsonb_build_object('context', p_context, 'timestamp', NOW()))
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION find_analogies(
    p_source_domain VARCHAR,
    p_source_concept TEXT,
    p_limit INTEGER DEFAULT 5
)
RETURNS TABLE(
    analogy_id UUID,
    target_domain VARCHAR,
    mapping JSONB,
    quality DECIMAL
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        am.mapping_id,
        am.target_domain::VARCHAR,
        am.structural_alignment,
        am.mapping_quality
    FROM analogical_mappings am
    WHERE am.source_domain = p_source_domain
      AND am.source_concept ILIKE '%' || p_source_concept || '%'
    ORDER BY am.mapping_quality DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calibrate_confidence(
    p_tenant_id UUID,
    p_domain VARCHAR,
    p_raw_confidence DECIMAL
)
RETURNS DECIMAL AS $$
DECLARE
    v_curve RECORD;
    v_adjustment DECIMAL;
BEGIN
    -- Get calibration curve for domain
    SELECT * INTO v_curve
    FROM calibration_curves
    WHERE (tenant_id = p_tenant_id OR tenant_id IS NULL)
      AND domain = p_domain
    ORDER BY sample_count DESC
    LIMIT 1;
    
    IF v_curve IS NULL THEN
        -- No calibration data, return raw confidence
        RETURN p_raw_confidence;
    END IF;
    
    -- Apply adjustment based on overconfidence rate
    IF v_curve.overconfidence_rate > 0.3 THEN
        v_adjustment := -0.1 * v_curve.overconfidence_rate;
    ELSIF v_curve.underconfidence_rate > 0.3 THEN
        v_adjustment := 0.1 * v_curve.underconfidence_rate;
    ELSE
        v_adjustment := 0;
    END IF;
    
    RETURN GREATEST(0, LEAST(1, p_raw_confidence + v_adjustment));
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION find_related_knowledge(
    p_node_id UUID,
    p_max_depth INTEGER DEFAULT 2,
    p_limit INTEGER DEFAULT 20
)
RETURNS TABLE(
    node_id UUID,
    name VARCHAR,
    node_type VARCHAR,
    relation_path TEXT[],
    depth INTEGER
) AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE related AS (
        -- Start node
        SELECT 
            kn.node_id,
            kn.name,
            kn.node_type,
            ARRAY[]::TEXT[] as relation_path,
            0 as depth
        FROM knowledge_nodes kn
        WHERE kn.node_id = p_node_id
        
        UNION ALL
        
        -- Traverse edges
        SELECT 
            kn2.node_id,
            kn2.name,
            kn2.node_type,
            r.relation_path || ke.relation_type,
            r.depth + 1
        FROM related r
        JOIN knowledge_edges ke ON (ke.source_node_id = r.node_id OR ke.target_node_id = r.node_id)
        JOIN knowledge_nodes kn2 ON (
            (ke.target_node_id = kn2.node_id AND ke.source_node_id = r.node_id) OR
            (ke.source_node_id = kn2.node_id AND ke.target_node_id = r.node_id)
        )
        WHERE r.depth < p_max_depth
          AND kn2.node_id != p_node_id
    )
    SELECT DISTINCT ON (related.node_id)
        related.node_id,
        related.name::VARCHAR,
        related.node_type::VARCHAR,
        related.relation_path,
        related.depth
    FROM related
    WHERE related.depth > 0
    ORDER BY related.node_id, related.depth
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION detect_context_change(
    p_tenant_id UUID,
    p_session_id UUID,
    p_new_content TEXT
)
RETURNS JSONB AS $$
DECLARE
    v_current RECORD;
    v_changes JSONB := '{}';
BEGIN
    -- Get current context
    SELECT * INTO v_current
    FROM active_contexts
    WHERE tenant_id = p_tenant_id AND session_id = p_session_id;
    
    -- Detect changes (simplified - would use ML in production)
    IF p_new_content ILIKE '%technical%' OR p_new_content ILIKE '%code%' THEN
        v_changes := v_changes || '{"domain": "technical"}'::jsonb;
    ELSIF p_new_content ILIKE '%creative%' OR p_new_content ILIKE '%story%' THEN
        v_changes := v_changes || '{"domain": "creative"}'::jsonb;
    END IF;
    
    IF p_new_content ILIKE '%urgent%' OR p_new_content ILIKE '%asap%' THEN
        v_changes := v_changes || '{"urgency": "high"}'::jsonb;
    END IF;
    
    RETURN v_changes;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION generate_idea_code()
RETURNS VARCHAR(50) AS $$
DECLARE
    v_max_num INTEGER;
    v_new_code VARCHAR(50);
BEGIN
    SELECT COALESCE(MAX(SUBSTRING(idea_code FROM 4)::INTEGER), 0) + 1 INTO v_max_num
    FROM self_improvement_ideas
    WHERE idea_code LIKE 'SI-%';
    
    v_new_code := 'SI-' || LPAD(v_max_num::TEXT, 4, '0');
    RETURN v_new_code;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_improvement_idea(
    p_tenant_id UUID,
    p_title VARCHAR,
    p_description TEXT,
    p_category VARCHAR,
    p_origin_type VARCHAR,
    p_problem_statement TEXT DEFAULT NULL,
    p_proposed_solution TEXT DEFAULT NULL,
    p_confidence DECIMAL DEFAULT 0.5
)
RETURNS UUID AS $$
DECLARE
    v_idea_id UUID;
    v_idea_code VARCHAR(50);
BEGIN
    v_idea_code := generate_idea_code();
    
    INSERT INTO self_improvement_ideas (
        tenant_id, idea_code, title, description, category, origin_type,
        problem_statement, proposed_solution, confidence_score, created_by
    ) VALUES (
        p_tenant_id, v_idea_code, p_title, p_description, p_category, p_origin_type,
        p_problem_statement, p_proposed_solution, p_confidence, 'agi_self_analysis'
    ) RETURNING idea_id INTO v_idea_id;
    
    -- Notify admin
    INSERT INTO improvement_notifications (
        tenant_id, notification_type, title, message, related_idea_id, priority
    ) VALUES (
        p_tenant_id, 'new_idea', 'New Self-Improvement Idea: ' || p_title,
        'The AGI has identified a new improvement opportunity in ' || p_category,
        v_idea_id, 
        CASE WHEN p_confidence > 0.8 THEN 'high' ELSE 'normal' END
    );
    
    RETURN v_idea_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION evolve_improvement_idea(
    p_idea_id UUID,
    p_change_type VARCHAR,
    p_change_summary TEXT,
    p_changes JSONB,
    p_trigger VARCHAR DEFAULT 'agi_self_evolution'
)
RETURNS INTEGER AS $$
DECLARE
    v_current_version INTEGER;
    v_new_version INTEGER;
BEGIN
    -- Get current version
    SELECT version INTO v_current_version FROM self_improvement_ideas WHERE idea_id = p_idea_id;
    v_new_version := v_current_version + 1;
    
    -- Record evolution
    INSERT INTO improvement_evolution_history (
        idea_id, version_from, version_to, change_type, change_summary, changes_made, evolution_trigger, triggered_by
    ) VALUES (
        p_idea_id, v_current_version, v_new_version, p_change_type, p_change_summary, p_changes, p_trigger, 'agi_self_evolution'
    );
    
    -- Update version
    UPDATE self_improvement_ideas SET
        version = v_new_version,
        updated_at = NOW()
    WHERE idea_id = p_idea_id;
    
    -- Notify if significant change
    IF p_change_type IN ('pivot', 'expansion', 'merge') THEN
        INSERT INTO improvement_notifications (
            tenant_id, notification_type, title, message, related_idea_id
        )
        SELECT tenant_id, 'idea_evolved', 'Idea Evolved: ' || title,
               'Self-improvement idea has been ' || p_change_type || 'd: ' || p_change_summary,
               p_idea_id
        FROM self_improvement_ideas WHERE idea_id = p_idea_id;
    END IF;
    
    RETURN v_new_version;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION deprecate_improvement_idea(
    p_idea_id UUID,
    p_reason TEXT,
    p_superseded_by UUID DEFAULT NULL
)
RETURNS void AS $$
BEGIN
    -- Mark as deprecated
    UPDATE self_improvement_ideas SET
        is_deprecated = true,
        deprecated_at = NOW(),
        deprecation_reason = p_reason,
        superseded_by_id = p_superseded_by,
        status = 'deprecated',
        updated_at = NOW()
    WHERE idea_id = p_idea_id;
    
    -- If superseded, link the new idea
    IF p_superseded_by IS NOT NULL THEN
        UPDATE self_improvement_ideas SET
            parent_idea_id = p_idea_id
        WHERE idea_id = p_superseded_by;
    END IF;
    
    -- Notify
    INSERT INTO improvement_notifications (
        tenant_id, notification_type, title, message, related_idea_id
    )
    SELECT tenant_id, 'idea_deprecated', 'Idea Deprecated: ' || title,
           'Reason: ' || p_reason,
           p_idea_id
    FROM self_improvement_ideas WHERE idea_id = p_idea_id;
    
    -- Record in evolution history
    INSERT INTO improvement_evolution_history (
        idea_id, version_from, version_to, change_type, change_summary, changes_made, evolution_trigger
    )
    SELECT idea_id, version, version, 'deprecation', p_reason, 
           jsonb_build_object('is_deprecated', jsonb_build_object('old', false, 'new', true)),
           'superseded'
    FROM self_improvement_ideas WHERE idea_id = p_idea_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_idea_composite_score(p_idea_id UUID)
RETURNS DECIMAL AS $$
DECLARE
    v_idea RECORD;
    v_score DECIMAL;
BEGIN
    SELECT * INTO v_idea FROM self_improvement_ideas WHERE idea_id = p_idea_id;
    
    -- Weighted score: confidence * 0.3 + impact * 0.3 + feasibility * 0.2 + urgency * 0.2
    v_score := COALESCE(v_idea.confidence_score, 0.5) * 0.3 +
               COALESCE(v_idea.impact_score, 0.5) * 0.3 +
               COALESCE(v_idea.feasibility_score, 0.5) * 0.2 +
               COALESCE(v_idea.urgency_score, 0.5) * 0.2;
    
    -- Update the idea
    UPDATE self_improvement_ideas SET composite_score = v_score WHERE idea_id = p_idea_id;
    
    RETURN v_score;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION auto_deprecate_stale_ideas()
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER := 0;
    v_idea RECORD;
BEGIN
    FOR v_idea IN 
        SELECT idea_id, title
        FROM self_improvement_ideas
        WHERE status = 'proposed'
          AND NOT is_deprecated
          AND created_at < NOW() - INTERVAL '90 days'
          AND (composite_score IS NULL OR composite_score < 0.3)
    LOOP
        PERFORM deprecate_improvement_idea(
            v_idea.idea_id,
            'Auto-deprecated: Stale proposal with low priority (90+ days without action)',
            NULL
        );
        v_count := v_count + 1;
    END LOOP;
    
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_self_awareness(
    p_tenant_id UUID,
    p_capability VARCHAR,
    p_self_strength DECIMAL,
    p_self_weakness DECIMAL,
    p_actual_performance DECIMAL
)
RETURNS UUID AS $$
DECLARE
    v_awareness_id UUID;
    v_existing RECORD;
    v_accuracy DECIMAL;
BEGIN
    -- Calculate assessment accuracy
    v_accuracy := 1 - ABS(p_self_strength - p_actual_performance);
    
    -- Check if exists
    SELECT * INTO v_existing
    FROM performance_self_awareness
    WHERE tenant_id = p_tenant_id AND capability_area = p_capability;
    
    IF v_existing IS NOT NULL THEN
        -- Update existing
        UPDATE performance_self_awareness SET
            self_assessed_strength = p_self_strength,
            self_assessed_weakness = p_self_weakness,
            actual_performance = p_actual_performance,
            assessment_accuracy = (assessment_accuracy * assessment_count + v_accuracy) / (assessment_count + 1),
            assessment_count = assessment_count + 1,
            last_assessed = NOW(),
            performance_trend = CASE
                WHEN p_actual_performance > actual_performance + 0.05 THEN 'improving'
                WHEN p_actual_performance < actual_performance - 0.05 THEN 'declining'
                ELSE 'stable'
            END
        WHERE awareness_id = v_existing.awareness_id
        RETURNING awareness_id INTO v_awareness_id;
    ELSE
        -- Create new
        INSERT INTO performance_self_awareness (
            tenant_id, capability_area, self_assessed_strength, self_assessed_weakness,
            actual_performance, assessment_accuracy, confidence_in_assessment
        ) VALUES (
            p_tenant_id, p_capability, p_self_strength, p_self_weakness,
            p_actual_performance, v_accuracy, 0.5
        ) RETURNING awareness_id INTO v_awareness_id;
    END IF;
    
    RETURN v_awareness_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_calculate_composite_score()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.confidence_score IS DISTINCT FROM OLD.confidence_score OR
       NEW.impact_score IS DISTINCT FROM OLD.impact_score OR
       NEW.feasibility_score IS DISTINCT FROM OLD.feasibility_score OR
       NEW.urgency_score IS DISTINCT FROM OLD.urgency_score THEN
        PERFORM calculate_idea_composite_score(NEW.idea_id);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_update_improvement_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_metadata_completeness(p_model_id VARCHAR)
RETURNS DECIMAL AS $$
DECLARE
    v_metadata RECORD;
    v_total_fields INTEGER := 20;
    v_filled_fields INTEGER := 0;
BEGIN
    SELECT * INTO v_metadata FROM model_metadata WHERE model_id = p_model_id;
    
    IF v_metadata IS NULL THEN
        RETURN 0;
    END IF;
    
    -- Count filled fields
    IF v_metadata.model_name IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.provider IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.model_family IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.context_window IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.max_output_tokens IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.capabilities != '{}' THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.supported_modalities != '{}' THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF array_length(v_metadata.specialties, 1) > 0 THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.benchmarks != '{}' THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.input_price_per_1m IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.output_price_per_1m IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF array_length(v_metadata.regions_available, 1) > 0 THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.rate_limits != '{}' THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.best_use_cases != '[]' THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.official_docs_url IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.reliability_score IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.quality_score IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.training_cutoff IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.release_date IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    IF v_metadata.architecture IS NOT NULL THEN v_filled_fields := v_filled_fields + 1; END IF;
    
    -- Update the metadata record
    UPDATE model_metadata 
    SET metadata_completeness = v_filled_fields::DECIMAL / v_total_fields
    WHERE model_id = p_model_id;
    
    RETURN v_filled_fields::DECIMAL / v_total_fields;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION validate_model_metadata(p_model_id VARCHAR)
RETURNS TABLE(
    rule_name VARCHAR,
    field_name VARCHAR,
    severity VARCHAR,
    passed BOOLEAN,
    message TEXT
) AS $$
DECLARE
    v_metadata RECORD;
    v_rule RECORD;
    v_value TEXT;
    v_passed BOOLEAN;
    v_message TEXT;
BEGIN
    SELECT * INTO v_metadata FROM model_metadata WHERE model_id = p_model_id;
    
    FOR v_rule IN SELECT * FROM metadata_validation_rules WHERE enabled = true LOOP
        v_passed := true;
        v_message := 'OK';
        
        -- Get field value dynamically
        EXECUTE format('SELECT ($1).%I::TEXT', v_rule.field_name) INTO v_value USING v_metadata;
        
        CASE v_rule.validation_type
            WHEN 'required' THEN
                IF v_value IS NULL OR v_value = '' OR v_value = '{}' OR v_value = '[]' THEN
                    v_passed := false;
                    v_message := v_rule.field_name || ' is required';
                END IF;
            WHEN 'min_value' THEN
                IF v_value IS NOT NULL AND v_value::NUMERIC < (v_rule.validation_config->>'min')::NUMERIC THEN
                    v_passed := false;
                    v_message := v_rule.field_name || ' must be at least ' || (v_rule.validation_config->>'min');
                END IF;
            WHEN 'pattern' THEN
                IF v_value IS NOT NULL AND v_value !~ (v_rule.validation_config->>'pattern') THEN
                    v_passed := false;
                    v_message := v_rule.field_name || ' does not match required pattern';
                END IF;
            ELSE
                NULL;
        END CASE;
        
        RETURN QUERY SELECT 
            v_rule.name::VARCHAR,
            v_rule.field_name::VARCHAR,
            v_rule.severity::VARCHAR,
            v_passed,
            v_message;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION can_add_model(p_model_id VARCHAR)
RETURNS JSONB AS $$
DECLARE
    v_validation RECORD;
    v_errors INTEGER := 0;
    v_warnings INTEGER := 0;
    v_messages JSONB := '[]';
BEGIN
    FOR v_validation IN SELECT * FROM validate_model_metadata(p_model_id) LOOP
        IF NOT v_validation.passed THEN
            IF v_validation.severity = 'error' THEN
                v_errors := v_errors + 1;
            ELSIF v_validation.severity = 'warning' THEN
                v_warnings := v_warnings + 1;
            END IF;
            
            v_messages := v_messages || jsonb_build_object(
                'rule', v_validation.rule_name,
                'field', v_validation.field_name,
                'severity', v_validation.severity,
                'message', v_validation.message
            );
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'can_add', v_errors = 0,
        'errors', v_errors,
        'warnings', v_warnings,
        'validation_messages', v_messages,
        'completeness', (SELECT metadata_completeness FROM model_metadata WHERE model_id = p_model_id)
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION merge_metadata(
    p_model_id VARCHAR,
    p_new_data JSONB,
    p_source VARCHAR,
    p_confidence DECIMAL DEFAULT 0.7
)
RETURNS JSONB AS $$
DECLARE
    v_existing RECORD;
    v_merged JSONB := '{}';
    v_changes JSONB := '{}';
    v_key TEXT;
    v_new_value JSONB;
    v_existing_value JSONB;
BEGIN
    SELECT * INTO v_existing FROM model_metadata WHERE model_id = p_model_id;
    
    -- For each key in new data
    FOR v_key IN SELECT jsonb_object_keys(p_new_data) LOOP
        v_new_value := p_new_data->v_key;
        
        -- Get existing value
        EXECUTE format('SELECT to_jsonb(($1).%I)', v_key) INTO v_existing_value USING v_existing;
        
        -- Decide whether to use new value
        -- Use new if: existing is null, or new has higher confidence, or is from official source
        IF v_existing_value IS NULL OR v_existing_value = 'null'::jsonb OR 
           (p_source LIKE '%official%' AND p_confidence > 0.8) THEN
            v_merged := v_merged || jsonb_build_object(v_key, v_new_value);
            v_changes := v_changes || jsonb_build_object(v_key, jsonb_build_object(
                'old', v_existing_value,
                'new', v_new_value,
                'source', p_source
            ));
        END IF;
    END LOOP;
    
    RETURN jsonb_build_object(
        'merged_data', v_merged,
        'changes', v_changes,
        'fields_updated', (SELECT array_agg(key) FROM jsonb_object_keys(v_changes) key)
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_models_needing_refresh(p_max_age_hours INTEGER DEFAULT 168)
RETURNS TABLE(model_id VARCHAR, last_verified TIMESTAMPTZ, completeness DECIMAL) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        mm.model_id::VARCHAR,
        mm.last_verified,
        mm.metadata_completeness
    FROM model_metadata mm
    WHERE mm.is_available = true
      AND (mm.last_verified IS NULL OR mm.last_verified < NOW() - (p_max_age_hours || ' hours')::INTERVAL)
    ORDER BY mm.last_verified NULLS FIRST, mm.metadata_completeness ASC
    LIMIT 50;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_calculate_completeness()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM calculate_metadata_completeness(NEW.model_id);
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_validate_before_registry_add()
RETURNS TRIGGER AS $$
DECLARE
    v_validation JSONB;
BEGIN
    -- Check if metadata exists and is sufficient
    SELECT can_add_model(NEW.model_id) INTO v_validation;
    
    IF v_validation IS NULL THEN
        RAISE EXCEPTION 'Model % has no metadata. Metadata must be added before registering a model.', NEW.model_id;
    END IF;
    
    IF NOT (v_validation->>'can_add')::BOOLEAN THEN
        RAISE EXCEPTION 'Model % cannot be added due to incomplete metadata: %', 
            NEW.model_id, v_validation->>'validation_messages';
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION initialize_moral_principles(p_tenant_id UUID DEFAULT NULL)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER := 0;
BEGIN
    INSERT INTO moral_principles (
        tenant_id, principle_number, title, principle_text, explanation,
        positive_behaviors, negative_behaviors, example_applications,
        category, priority, is_absolute, is_default
    )
    SELECT 
        p_tenant_id, principle_number, title, principle_text, explanation,
        positive_behaviors, negative_behaviors, example_applications,
        category, priority, is_absolute, true
    FROM default_moral_principles
    ON CONFLICT (tenant_id, principle_number) DO NOTHING;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    -- Initialize settings if needed
    INSERT INTO moral_compass_settings (tenant_id)
    VALUES (p_tenant_id)
    ON CONFLICT (tenant_id) DO NOTHING;
    
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION reset_moral_principles(
    p_tenant_id UUID DEFAULT NULL,
    p_modified_by VARCHAR DEFAULT 'system'
)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER := 0;
    v_principle RECORD;
BEGIN
    -- Log the reset
    INSERT INTO principle_modification_history (
        principle_id, modification_type, previous_values, modified_by, reason
    )
    SELECT 
        mp.principle_id, 'reset',
        jsonb_build_object(
            'title', mp.title,
            'principle_text', mp.principle_text,
            'priority', mp.priority
        ),
        p_modified_by, 'Reset to defaults'
    FROM moral_principles mp
    WHERE mp.tenant_id IS NOT DISTINCT FROM p_tenant_id;
    
    -- Delete existing
    DELETE FROM moral_principles WHERE tenant_id IS NOT DISTINCT FROM p_tenant_id;
    
    -- Re-initialize from defaults
    SELECT initialize_moral_principles(p_tenant_id) INTO v_count;
    
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION restore_principle_to_default(
    p_principle_id UUID,
    p_modified_by VARCHAR DEFAULT 'system'
)
RETURNS BOOLEAN AS $$
DECLARE
    v_principle RECORD;
    v_default RECORD;
BEGIN
    -- Get current principle
    SELECT * INTO v_principle FROM moral_principles WHERE principle_id = p_principle_id;
    IF v_principle IS NULL THEN
        RETURN false;
    END IF;
    
    -- Get default
    SELECT * INTO v_default FROM default_moral_principles WHERE principle_number = v_principle.principle_number;
    IF v_default IS NULL THEN
        RETURN false;
    END IF;
    
    -- Log the restore
    INSERT INTO principle_modification_history (
        principle_id, modification_type, previous_values, new_values, modified_by, reason
    ) VALUES (
        p_principle_id, 'restored',
        jsonb_build_object('title', v_principle.title, 'principle_text', v_principle.principle_text),
        jsonb_build_object('title', v_default.title, 'principle_text', v_default.principle_text),
        p_modified_by, 'Restored to default'
    );
    
    -- Update to default values
    UPDATE moral_principles SET
        title = v_default.title,
        principle_text = v_default.principle_text,
        explanation = v_default.explanation,
        positive_behaviors = v_default.positive_behaviors,
        negative_behaviors = v_default.negative_behaviors,
        example_applications = v_default.example_applications,
        category = v_default.category,
        priority = v_default.priority,
        is_absolute = v_default.is_absolute,
        modified_by = p_modified_by,
        modified_at = NOW(),
        modification_reason = 'Restored to default'
    WHERE principle_id = p_principle_id;
    
    RETURN true;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION evaluate_moral_situation(
    p_tenant_id UUID,
    p_situation TEXT
)
RETURNS TABLE(
    principle_id UUID,
    principle_number INTEGER,
    title VARCHAR,
    relevance_score DECIMAL,
    guidance TEXT
) AS $$
BEGIN
    -- Simple keyword-based relevance (would use AI in production)
    RETURN QUERY
    SELECT 
        mp.principle_id,
        mp.principle_number,
        mp.title::VARCHAR,
        CASE 
            WHEN p_situation ILIKE ANY(
                SELECT '%' || jsonb_array_elements_text(mp.positive_behaviors) || '%'
            ) THEN 0.8
            WHEN p_situation ILIKE ANY(
                SELECT '%' || jsonb_array_elements_text(mp.negative_behaviors) || '%'
            ) THEN 0.9
            ELSE 0.3
        END as relevance_score,
        mp.principle_text as guidance
    FROM moral_principles mp
    WHERE mp.tenant_id IS NOT DISTINCT FROM p_tenant_id
      AND mp.is_active = true
    ORDER BY mp.priority DESC, relevance_score DESC
    LIMIT 5;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_routing_for_training(
    p_tenant_id UUID,
    p_task_text TEXT,
    p_specialty VARCHAR,
    p_models_considered TEXT[],
    p_model_selected VARCHAR,
    p_strategy VARCHAR,
    p_quality_score DECIMAL,
    p_latency_ms INTEGER,
    p_cost_cents DECIMAL
)
RETURNS UUID AS $$
DECLARE
    v_sample_id UUID;
    v_complexity VARCHAR;
BEGIN
    -- Detect complexity based on task length and keywords
    v_complexity := CASE
        WHEN length(p_task_text) > 1000 OR p_task_text ~* 'complex|detailed|comprehensive|analyze' THEN 'complex'
        WHEN length(p_task_text) > 300 OR p_task_text ~* 'explain|describe|compare' THEN 'moderate'
        ELSE 'simple'
    END;
    
    INSERT INTO ml_routing_training_data (
        tenant_id, task_text, detected_specialty, detected_complexity,
        models_considered, model_selected, routing_strategy,
        quality_score, latency_ms, cost_cents,
        was_good_choice
    ) VALUES (
        p_tenant_id, p_task_text, p_specialty, v_complexity,
        p_models_considered, p_model_selected, p_strategy,
        p_quality_score, p_latency_ms, p_cost_cents,
        p_quality_score >= 0.7 -- Good choice if quality >= 70%
    )
    RETURNING sample_id INTO v_sample_id;
    
    RETURN v_sample_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_training_feedback(
    p_sample_id UUID,
    p_feedback VARCHAR,
    p_feedback_text TEXT DEFAULT NULL
)
RETURNS VOID AS $$
BEGIN
    UPDATE ml_routing_training_data SET
        user_feedback = p_feedback,
        user_feedback_text = p_feedback_text,
        was_good_choice = CASE
            WHEN p_feedback = 'positive' THEN true
            WHEN p_feedback = 'negative' THEN false
            ELSE was_good_choice
        END
    WHERE sample_id = p_sample_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION export_training_batch(
    p_batch_name VARCHAR,
    p_model_type VARCHAR,
    p_min_samples INTEGER DEFAULT 1000
)
RETURNS TABLE(
    batch_id UUID,
    samples_exported INTEGER
) AS $$
DECLARE
    v_batch_id UUID;
    v_count INTEGER;
BEGIN
    -- Count available samples
    SELECT COUNT(*) INTO v_count
    FROM ml_routing_training_data
    WHERE used_for_training = false
      AND quality_score IS NOT NULL;
    
    IF v_count < p_min_samples THEN
        RAISE EXCEPTION 'Not enough training samples. Have %, need %', v_count, p_min_samples;
    END IF;
    
    -- Create batch
    INSERT INTO ml_training_batches (batch_name, model_type, samples_count, status)
    VALUES (p_batch_name, p_model_type, v_count, 'exporting')
    RETURNING ml_training_batches.batch_id INTO v_batch_id;
    
    -- Mark samples as used
    UPDATE ml_routing_training_data SET
        used_for_training = true,
        training_batch_id = v_batch_id,
        exported_at = NOW()
    WHERE used_for_training = false
      AND quality_score IS NOT NULL;
    
    RETURN QUERY SELECT v_batch_id, v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ml_best_model(
    p_specialty VARCHAR,
    p_complexity VARCHAR DEFAULT 'moderate'
)
RETURNS VARCHAR AS $$
DECLARE
    v_model VARCHAR;
BEGIN
    -- Use historical performance to pick best model
    SELECT model_selected INTO v_model
    FROM ml_routing_training_data
    WHERE detected_specialty = p_specialty
      AND detected_complexity = p_complexity
      AND was_good_choice = true
    GROUP BY model_selected
    ORDER BY AVG(quality_score) DESC, COUNT(*) DESC
    LIMIT 1;
    
    -- Fallback to best overall
    IF v_model IS NULL THEN
        SELECT model_id INTO v_model
        FROM ai_model_registry
        WHERE is_available = true AND is_deprecated = false
        ORDER BY cap_reasoning DESC
        LIMIT 1;
    END IF;
    
    RETURN v_model;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_learning_interaction(
    p_tenant_id UUID,
    p_user_id UUID,
    p_session_id VARCHAR,
    p_request_type VARCHAR,
    p_request_source VARCHAR,
    p_request_text TEXT,
    p_model_selected VARCHAR,
    p_response_text TEXT,
    p_total_latency_ms INTEGER,
    p_total_cost_cents DECIMAL,
    p_metadata JSONB DEFAULT '{}'
)
RETURNS UUID AS $$
DECLARE
    v_interaction_id UUID;
BEGIN
    INSERT INTO learning_interactions (
        tenant_id, user_id, session_id, request_type, request_source,
        request_text, model_selected, response_text,
        total_latency_ms, total_cost_cents, context_metadata
    ) VALUES (
        p_tenant_id, p_user_id, p_session_id, p_request_type, p_request_source,
        p_request_text, p_model_selected, p_response_text,
        p_total_latency_ms, p_total_cost_cents, p_metadata
    )
    RETURNING interaction_id INTO v_interaction_id;
    
    -- Create empty outcome record for later computation
    INSERT INTO learning_outcomes (interaction_id)
    VALUES (v_interaction_id);
    
    RETURN v_interaction_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_learning_feedback(
    p_interaction_id UUID,
    p_rating INTEGER DEFAULT NULL,
    p_thumbs VARCHAR DEFAULT NULL,
    p_feedback_text TEXT DEFAULT NULL,
    p_response_action VARCHAR DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_feedback_id UUID;
    v_tenant_id UUID;
    v_user_id UUID;
BEGIN
    -- Get tenant and user from interaction
    SELECT tenant_id, user_id INTO v_tenant_id, v_user_id
    FROM learning_interactions WHERE interaction_id = p_interaction_id;
    
    INSERT INTO learning_feedback (
        interaction_id, tenant_id, user_id, rating, thumbs, feedback_text, response_action
    ) VALUES (
        p_interaction_id, v_tenant_id, v_user_id, p_rating, p_thumbs, p_feedback_text, p_response_action
    )
    RETURNING feedback_id INTO v_feedback_id;
    
    -- Update outcome score based on feedback
    PERFORM compute_learning_outcome(p_interaction_id);
    
    RETURN v_feedback_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_learning_outcome(p_interaction_id UUID)
RETURNS VOID AS $$
DECLARE
    v_feedback_score DECIMAL;
    v_signal_score DECIMAL;
    v_auto_score DECIMAL;
    v_final_score DECIMAL;
BEGIN
    -- Get explicit feedback score (if any)
    SELECT 
        COALESCE(
            AVG(CASE 
                WHEN thumbs = 'up' THEN 1.0
                WHEN thumbs = 'down' THEN 0.0
                WHEN rating IS NOT NULL THEN (rating - 1) / 4.0
                ELSE NULL
            END),
            -1 -- No feedback
        )
    INTO v_feedback_score
    FROM learning_feedback WHERE interaction_id = p_interaction_id;
    
    -- Get implicit signal score (if any)
    SELECT 
        CASE 
            WHEN did_regenerate THEN 0.3
            WHEN did_copy_response THEN 0.9
            WHEN did_continue_session THEN 0.7
            WHEN did_abandon_session THEN 0.2
            ELSE 0.5 -- Neutral
        END
    INTO v_signal_score
    FROM learning_implicit_signals WHERE interaction_id = p_interaction_id;
    
    -- Get auto quality score
    SELECT auto_quality_score INTO v_auto_score
    FROM learning_interactions WHERE interaction_id = p_interaction_id;
    
    -- Compute final score (weighted average)
    v_final_score := CASE
        WHEN v_feedback_score >= 0 THEN 
            v_feedback_score * 0.6 + COALESCE(v_signal_score, 0.5) * 0.2 + COALESCE(v_auto_score, 0.5) * 0.2
        ELSE
            COALESCE(v_signal_score, 0.5) * 0.4 + COALESCE(v_auto_score, 0.5) * 0.6
    END;
    
    UPDATE learning_outcomes SET
        outcome_score = v_final_score,
        routing_was_optimal = v_final_score >= 0.7,
        last_updated = NOW()
    WHERE interaction_id = p_interaction_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_model_performance(
    p_period_type VARCHAR DEFAULT 'daily'
)
RETURNS INTEGER AS $$
DECLARE
    v_period_start TIMESTAMPTZ;
    v_period_end TIMESTAMPTZ;
    v_count INTEGER := 0;
BEGIN
    -- Determine period
    IF p_period_type = 'hourly' THEN
        v_period_start := date_trunc('hour', NOW() - INTERVAL '1 hour');
        v_period_end := date_trunc('hour', NOW());
    ELSIF p_period_type = 'daily' THEN
        v_period_start := date_trunc('day', NOW() - INTERVAL '1 day');
        v_period_end := date_trunc('day', NOW());
    ELSE
        v_period_start := date_trunc('week', NOW() - INTERVAL '1 week');
        v_period_end := date_trunc('week', NOW());
    END IF;
    
    INSERT INTO learning_model_performance (
        model_id, tenant_id, specialty, period_start, period_end, period_type,
        total_requests, successful_requests, failed_requests,
        avg_quality_score, avg_latency_ms, total_cost_cents
    )
    SELECT 
        li.model_selected,
        li.tenant_id,
        li.detected_specialty,
        v_period_start,
        v_period_end,
        p_period_type,
        COUNT(*),
        COUNT(*) FILTER (WHERE NOT li.had_error),
        COUNT(*) FILTER (WHERE li.had_error),
        AVG(lo.outcome_score),
        AVG(li.total_latency_ms),
        SUM(li.total_cost_cents)
    FROM learning_interactions li
    LEFT JOIN learning_outcomes lo ON li.interaction_id = lo.interaction_id
    WHERE li.created_at >= v_period_start AND li.created_at < v_period_end
    GROUP BY li.model_selected, li.tenant_id, li.detected_specialty
    ON CONFLICT (model_id, tenant_id, specialty, period_start, period_type) DO UPDATE SET
        total_requests = EXCLUDED.total_requests,
        successful_requests = EXCLUDED.successful_requests,
        failed_requests = EXCLUDED.failed_requests,
        avg_quality_score = EXCLUDED.avg_quality_score,
        avg_latency_ms = EXCLUDED.avg_latency_ms,
        total_cost_cents = EXCLUDED.total_cost_cents;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_specialty_insights(p_specialty VARCHAR, p_tenant_id UUID DEFAULT NULL)
RETURNS VOID AS $$
BEGIN
    INSERT INTO learning_specialty_insights (specialty, tenant_id, model_rankings, samples_analyzed, last_computed)
    SELECT 
        p_specialty,
        p_tenant_id,
        jsonb_agg(jsonb_build_object(
            'model', model_id,
            'avg_quality', avg_quality_score,
            'avg_latency', avg_latency_ms,
            'total_cost', total_cost_cents,
            'samples', total_requests
        ) ORDER BY avg_quality_score DESC NULLS LAST),
        SUM(total_requests),
        NOW()
    FROM learning_model_performance
    WHERE specialty = p_specialty 
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
      AND period_type = 'daily'
      AND period_start >= NOW() - INTERVAL '30 days'
    GROUP BY specialty
    ON CONFLICT (specialty, tenant_id) DO UPDATE SET
        model_rankings = EXCLUDED.model_rankings,
        samples_analyzed = EXCLUDED.samples_analyzed,
        last_computed = NOW();
    
    -- Update best models
    UPDATE learning_specialty_insights lsi SET
        best_model_quality = (model_rankings->0->>'model'),
        best_model_balanced = (model_rankings->0->>'model')
    WHERE specialty = p_specialty 
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_compute_outcome()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM compute_learning_outcome(NEW.interaction_id);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION run_learning_aggregations()
RETURNS JSONB AS $$
DECLARE
    v_hourly INTEGER;
    v_daily INTEGER;
    v_specialties TEXT[];
    v_spec TEXT;
BEGIN
    -- Aggregate hourly
    SELECT aggregate_model_performance('hourly') INTO v_hourly;
    
    -- Aggregate daily (if it's a new day)
    IF EXTRACT(HOUR FROM NOW()) = 0 THEN
        SELECT aggregate_model_performance('daily') INTO v_daily;
        
        -- Update all specialty insights
        SELECT ARRAY_AGG(DISTINCT detected_specialty) INTO v_specialties
        FROM learning_interactions
        WHERE detected_specialty IS NOT NULL;
        
        FOREACH v_spec IN ARRAY COALESCE(v_specialties, ARRAY[]::TEXT[])
        LOOP
            PERFORM update_specialty_insights(v_spec, NULL);
        END LOOP;
    END IF;
    
    RETURN jsonb_build_object(
        'hourly_aggregated', v_hourly,
        'daily_aggregated', COALESCE(v_daily, 0),
        'timestamp', NOW()
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION submit_feedback(
    p_tenant_id UUID,
    p_user_id UUID,
    p_target_type VARCHAR,
    p_target_id VARCHAR,
    p_thumbs VARCHAR DEFAULT NULL,
    p_rating INTEGER DEFAULT NULL,
    p_comment TEXT DEFAULT NULL,
    p_interaction_id UUID DEFAULT NULL,
    p_original_prompt TEXT DEFAULT NULL,
    p_original_response TEXT DEFAULT NULL,
    p_model_used VARCHAR DEFAULT NULL,
    p_workflow_used VARCHAR DEFAULT NULL,
    p_feedback_tags TEXT[] DEFAULT NULL,
    p_user_action VARCHAR DEFAULT NULL,
    p_session_id VARCHAR DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_feedback_id UUID;
BEGIN
    INSERT INTO feedback_registry (
        tenant_id, user_id, target_type, target_id,
        thumbs, rating, comment, interaction_id,
        original_prompt, original_response, model_used, workflow_used,
        feedback_tags, user_action, session_id
    ) VALUES (
        p_tenant_id, p_user_id, p_target_type, p_target_id,
        p_thumbs, p_rating, p_comment, p_interaction_id,
        p_original_prompt, p_original_response, p_model_used, p_workflow_used,
        COALESCE(p_feedback_tags, '{}'), p_user_action, p_session_id
    )
    RETURNING feedback_id INTO v_feedback_id;
    
    -- Update learning outcome if interaction_id provided
    IF p_interaction_id IS NOT NULL THEN
        UPDATE learning_outcomes SET
            outcome_score = CASE
                WHEN p_thumbs = 'up' THEN GREATEST(COALESCE(outcome_score, 0.5) + 0.2, 1.0)
                WHEN p_thumbs = 'down' THEN LEAST(COALESCE(outcome_score, 0.5) - 0.2, 0.0)
                WHEN p_rating IS NOT NULL THEN (p_rating - 1) / 4.0
                ELSE outcome_score
            END,
            routing_was_optimal = CASE
                WHEN p_thumbs = 'up' OR (p_rating IS NOT NULL AND p_rating >= 4) THEN true
                WHEN p_thumbs = 'down' OR (p_rating IS NOT NULL AND p_rating <= 2) THEN false
                ELSE routing_was_optimal
            END,
            last_updated = NOW()
        WHERE interaction_id = p_interaction_id;
    END IF;
    
    RETURN v_feedback_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION submit_think_tank_feedback(
    p_conversation_id UUID,
    p_tenant_id UUID,
    p_user_id UUID,
    p_thumbs VARCHAR DEFAULT NULL,
    p_rating INTEGER DEFAULT NULL,
    p_comment TEXT DEFAULT NULL,
    p_message_id UUID DEFAULT NULL,
    p_best_participant VARCHAR DEFAULT NULL,
    p_worst_participant VARCHAR DEFAULT NULL,
    p_participant_ratings JSONB DEFAULT NULL,
    p_goal_achieved BOOLEAN DEFAULT NULL,
    p_improvement_suggestions TEXT DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_feedback_id UUID;
BEGIN
    INSERT INTO think_tank_feedback (
        conversation_id, tenant_id, user_id, message_id,
        thumbs, rating, comment,
        best_participant, worst_participant, participant_ratings,
        goal_achieved, improvement_suggestions
    ) VALUES (
        p_conversation_id, p_tenant_id, p_user_id, p_message_id,
        p_thumbs, p_rating, p_comment,
        p_best_participant, p_worst_participant, COALESCE(p_participant_ratings, '{}'),
        p_goal_achieved, p_improvement_suggestions
    )
    RETURNING feedback_id INTO v_feedback_id;
    
    -- Also record in main feedback registry
    INSERT INTO feedback_registry (
        tenant_id, user_id, target_type, target_id,
        thumbs, rating, comment, workflow_used,
        feedback_source
    ) VALUES (
        p_tenant_id, p_user_id, 'think_tank', p_conversation_id::VARCHAR,
        p_thumbs, p_rating, p_comment, 'think_tank',
        'think_tank'
    );
    
    RETURN v_feedback_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_feedback(p_period_type VARCHAR DEFAULT 'daily')
RETURNS INTEGER AS $$
DECLARE
    v_period_start TIMESTAMPTZ;
    v_period_end TIMESTAMPTZ;
    v_count INTEGER := 0;
BEGIN
    -- Determine period
    IF p_period_type = 'hourly' THEN
        v_period_start := date_trunc('hour', NOW() - INTERVAL '1 hour');
        v_period_end := date_trunc('hour', NOW());
    ELSIF p_period_type = 'daily' THEN
        v_period_start := date_trunc('day', NOW() - INTERVAL '1 day');
        v_period_end := date_trunc('day', NOW());
    ELSE
        v_period_start := date_trunc('week', NOW() - INTERVAL '1 week');
        v_period_end := date_trunc('week', NOW());
    END IF;
    
    -- Aggregate by model
    INSERT INTO feedback_aggregates (
        aggregate_type, aggregate_key, tenant_id, period_start, period_end, period_type,
        total_feedback, thumbs_up, thumbs_down, ratings_count, comments_count,
        avg_rating, positive_ratio
    )
    SELECT 
        'model',
        model_used,
        tenant_id,
        v_period_start,
        v_period_end,
        p_period_type,
        COUNT(*),
        COUNT(*) FILTER (WHERE thumbs = 'up'),
        COUNT(*) FILTER (WHERE thumbs = 'down'),
        COUNT(*) FILTER (WHERE rating IS NOT NULL),
        COUNT(*) FILTER (WHERE comment IS NOT NULL AND comment != ''),
        AVG(rating),
        AVG(CASE WHEN thumbs = 'up' THEN 1.0 WHEN thumbs = 'down' THEN 0.0 ELSE NULL END)
    FROM feedback_registry
    WHERE created_at >= v_period_start AND created_at < v_period_end
      AND model_used IS NOT NULL
    GROUP BY model_used, tenant_id
    ON CONFLICT (aggregate_type, aggregate_key, tenant_id, period_start, period_type) DO UPDATE SET
        total_feedback = EXCLUDED.total_feedback,
        thumbs_up = EXCLUDED.thumbs_up,
        thumbs_down = EXCLUDED.thumbs_down,
        avg_rating = EXCLUDED.avg_rating,
        positive_ratio = EXCLUDED.positive_ratio;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    -- Aggregate by workflow
    INSERT INTO feedback_aggregates (
        aggregate_type, aggregate_key, tenant_id, period_start, period_end, period_type,
        total_feedback, thumbs_up, thumbs_down, avg_rating, positive_ratio
    )
    SELECT 
        'workflow',
        workflow_used,
        tenant_id,
        v_period_start,
        v_period_end,
        p_period_type,
        COUNT(*),
        COUNT(*) FILTER (WHERE thumbs = 'up'),
        COUNT(*) FILTER (WHERE thumbs = 'down'),
        AVG(rating),
        AVG(CASE WHEN thumbs = 'up' THEN 1.0 WHEN thumbs = 'down' THEN 0.0 ELSE NULL END)
    FROM feedback_registry
    WHERE created_at >= v_period_start AND created_at < v_period_end
      AND workflow_used IS NOT NULL
    GROUP BY workflow_used, tenant_id
    ON CONFLICT (aggregate_type, aggregate_key, tenant_id, period_start, period_type) DO UPDATE SET
        total_feedback = EXCLUDED.total_feedback,
        thumbs_up = EXCLUDED.thumbs_up,
        thumbs_down = EXCLUDED.thumbs_down,
        avg_rating = EXCLUDED.avg_rating,
        positive_ratio = EXCLUDED.positive_ratio;
    
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_feedback_for_learning(p_limit INTEGER DEFAULT 1000)
RETURNS TABLE (
    feedback_id UUID,
    original_prompt TEXT,
    original_response TEXT,
    model_used VARCHAR,
    workflow_used VARCHAR,
    thumbs VARCHAR,
    rating INTEGER,
    comment TEXT,
    feedback_tags TEXT[],
    is_positive BOOLEAN
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        fr.feedback_id,
        fr.original_prompt,
        fr.original_response,
        fr.model_used,
        fr.workflow_used,
        fr.thumbs,
        fr.rating,
        fr.comment,
        fr.feedback_tags,
        (fr.thumbs = 'up' OR (fr.rating IS NOT NULL AND fr.rating >= 4)) as is_positive
    FROM feedback_registry fr
    WHERE fr.processed_for_learning = false
      AND fr.original_prompt IS NOT NULL
      AND (fr.thumbs IS NOT NULL OR fr.rating IS NOT NULL)
    ORDER BY fr.created_at DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mark_feedback_processed(p_feedback_ids UUID[], p_batch_id UUID)
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE feedback_registry SET
        processed_for_learning = true,
        learning_batch_id = p_batch_id,
        processed_at = NOW()
    WHERE feedback_id = ANY(p_feedback_ids);
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_specialty_leaderboard(
    p_specialty TEXT,
    p_limit INTEGER DEFAULT 10
) RETURNS TABLE (
    rank INTEGER,
    model_id TEXT,
    provider TEXT,
    model_name TEXT,
    score DECIMAL,
    tier TEXT,
    trend TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ROW_NUMBER() OVER (ORDER BY COALESCE(sr.admin_override, sr.proficiency_score) DESC)::INTEGER as rank,
        sr.model_id,
        sr.provider,
        mm.model_name,
        COALESCE(sr.admin_override, sr.proficiency_score) as score,
        sr.tier,
        sr.trend
    FROM specialty_rankings sr
    JOIN model_metadata mm ON sr.model_id = mm.model_id
    WHERE sr.specialty = p_specialty
      AND mm.is_available = true
    ORDER BY COALESCE(sr.admin_override, sr.proficiency_score) DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_ranking_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION schedule_agi_snapshot()
RETURNS void AS $$
DECLARE
    t_id UUID;
BEGIN
    FOR t_id IN 
        SELECT tenant_id FROM agi_persistence_config 
        WHERE auto_snapshot_enabled = true
        AND (
            NOT EXISTS (
                SELECT 1 FROM agi_learning_snapshots 
                WHERE tenant_id = agi_persistence_config.tenant_id
                AND created_at > NOW() - (snapshot_interval_hours * INTERVAL '1 hour')
            )
        )
    LOOP
        INSERT INTO agi_learning_snapshots (tenant_id, snapshot_type)
        VALUES (t_id, 'checkpoint');
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_old_agi_snapshots()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER := 0;
BEGIN
    WITH to_delete AS (
        SELECT snapshot_id
        FROM (
            SELECT snapshot_id,
                   ROW_NUMBER() OVER (PARTITION BY tenant_id ORDER BY created_at DESC) as rn,
                   c.max_snapshots_retained
            FROM agi_learning_snapshots s
            JOIN agi_persistence_config c ON s.tenant_id = c.tenant_id
        ) ranked
        WHERE rn > max_snapshots_retained
    )
    DELETE FROM agi_learning_snapshots WHERE snapshot_id IN (SELECT snapshot_id FROM to_delete);
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_agi_persistence_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION detect_text_language(input_text TEXT)
RETURNS VARCHAR(10) AS $$
DECLARE
  cjk_count INTEGER;
  total_count INTEGER;
  cjk_ratio FLOAT;
BEGIN
  IF input_text IS NULL OR LENGTH(input_text) = 0 THEN
    RETURN 'en';
  END IF;
  
  -- Count CJK characters (Chinese, Japanese, Korean Unicode ranges)
  -- CJK Unified Ideographs: U+4E00 to U+9FFF
  -- Hiragana: U+3040 to U+309F
  -- Katakana: U+30A0 to U+30FF
  -- Hangul: U+AC00 to U+D7AF
  cjk_count := LENGTH(
    REGEXP_REPLACE(
      input_text, 
      '[^\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FF\uAC00-\uD7AF]', 
      '', 
      'g'
    )
  );
  
  total_count := LENGTH(REGEXP_REPLACE(input_text, '\s', '', 'g'));
  
  IF total_count = 0 THEN
    RETURN 'en';
  END IF;
  
  cjk_ratio := cjk_count::FLOAT / total_count::FLOAT;
  
  -- If more than 10% CJK characters, consider it CJK content
  IF cjk_ratio > 0.1 THEN
    -- Presence of Hiragana/Katakana → Japanese
    IF input_text ~ '[\u3040-\u309F\u30A0-\u30FF]' THEN
      RETURN 'ja';
    -- Presence of Hangul → Korean
    ELSIF input_text ~ '[\uAC00-\uD7AF]' THEN
      RETURN 'ko';
    -- Default CJK to Chinese
    ELSE
      RETURN 'zh';
    END IF;
  END IF;
  
  -- Check for Arabic script
  IF input_text ~ '[\u0600-\u06FF]' THEN
    RETURN 'ar';
  END IF;
  
  -- Check for Cyrillic (Russian)
  IF input_text ~ '[\u0400-\u04FF]' THEN
    RETURN 'ru';
  END IF;
  
  -- Default to English for Latin script
  RETURN 'en';
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- ============================================================================
-- TRIGGER TO UPDATE LANGUAGE AND SEARCH VECTORS
-- ============================================================================

-- Function to update search vectors based on language
CREATE OR REPLACE FUNCTION update_conversation_search()
RETURNS TRIGGER AS $$
DECLARE
  combined_text TEXT;
  lang VARCHAR(10);
BEGIN
  combined_text := COALESCE(NEW.title, '') || ' ' || COALESCE(NEW.summary, '');
  lang := detect_text_language(combined_text);
  
  NEW.detected_language := lang;
  
  -- Always update simple tsvector (works for all languages as fallback)
  NEW.search_vector_simple := to_tsvector('simple', combined_text);
  
  -- Update language-specific tsvector for supported languages
  IF lang = 'en' THEN
    NEW.search_vector_english := to_tsvector('english', combined_text);
  ELSIF lang = 'es' THEN
    NEW.search_vector_english := to_tsvector('spanish', combined_text);
  ELSIF lang = 'fr' THEN
    NEW.search_vector_english := to_tsvector('french', combined_text);
  ELSIF lang = 'de' THEN
    NEW.search_vector_english := to_tsvector('german', combined_text);
  ELSIF lang = 'ru' THEN
    NEW.search_vector_english := to_tsvector('russian', combined_text);
  ELSIF lang = 'pt' THEN
    NEW.search_vector_english := to_tsvector('portuguese', combined_text);
  ELSIF lang = 'it' THEN
    NEW.search_vector_english := to_tsvector('italian', combined_text);
  ELSIF lang = 'nl' THEN
    NEW.search_vector_english := to_tsvector('dutch', combined_text);
  ELSIF lang = 'tr' THEN
    NEW.search_vector_english := to_tsvector('turkish', combined_text);
  ELSE
    -- For CJK and other languages, just use simple config
    NEW.search_vector_english := NULL;
  END IF;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION search_content(
  search_query TEXT,
  p_tenant_id UUID,
  p_user_id UUID DEFAULT NULL,
  p_limit INTEGER DEFAULT 20,
  p_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
  id UUID,
  content_type VARCHAR(50),
  title TEXT,
  summary TEXT,
  relevance FLOAT,
  detected_language VARCHAR(10),
  created_at TIMESTAMPTZ
) AS $$
DECLARE
  query_lang VARCHAR(10);
  is_cjk BOOLEAN;
BEGIN
  -- Detect query language
  query_lang := detect_text_language(search_query);
  is_cjk := query_lang IN ('zh', 'ja', 'ko');
  
  IF is_cjk THEN
    -- Use pg_bigm LIKE search for CJK
    RETURN QUERY
    SELECT 
      c.id,
      'conversation'::VARCHAR(50) as content_type,
      c.title,
      c.summary,
      -- Relevance based on bigm similarity
      bigm_similarity(search_query, COALESCE(c.title, '') || ' ' || COALESCE(c.summary, '')) as relevance,
      c.detected_language,
      c.created_at
    FROM uds_conversations c
    WHERE c.tenant_id = p_tenant_id
      AND (p_user_id IS NULL OR c.user_id = p_user_id)
      AND (
        c.title LIKE '%' || search_query || '%'
        OR c.summary LIKE '%' || search_query || '%'
      )
    ORDER BY relevance DESC, c.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
  ELSE
    -- Use tsvector search for Western languages
    RETURN QUERY
    SELECT 
      c.id,
      'conversation'::VARCHAR(50) as content_type,
      c.title,
      c.summary,
      -- Relevance based on ts_rank
      CASE 
        WHEN c.search_vector_english IS NOT NULL 
        THEN ts_rank(c.search_vector_english, plainto_tsquery('english', search_query))
        ELSE ts_rank(c.search_vector_simple, plainto_tsquery('simple', search_query))
      END as relevance,
      c.detected_language,
      c.created_at
    FROM uds_conversations c
    WHERE c.tenant_id = p_tenant_id
      AND (p_user_id IS NULL OR c.user_id = p_user_id)
      AND (
        c.search_vector_english @@ plainto_tsquery('english', search_query)
        OR c.search_vector_simple @@ plainto_tsquery('simple', search_query)
      )
    ORDER BY relevance DESC, c.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
  END IF;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Grant execute permission
GRANT EXECUTE ON FUNCTION search_content TO radiant_app;
GRANT EXECUTE ON FUNCTION detect_text_language TO radiant_app;

-- ============================================================================
-- BACKFILL EXISTING DATA
-- ============================================================================

-- Update existing conversations with language detection and search vectors
UPDATE uds_conversations 
SET 
  detected_language = detect_text_language(COALESCE(title, '') || ' ' || COALESCE(summary, '')),
  search_vector_simple = to_tsvector('simple', COALESCE(title, '') || ' ' || COALESCE(summary, ''))
WHERE detected_language = 'en' OR search_vector_simple IS NULL;

-- Update English tsvector for detected English content
UPDATE uds_conversations 
SET search_vector_english = to_tsvector('english', COALESCE(title, '') || ' ' || COALESCE(summary, ''))
WHERE detected_language = 'en';

-- ============================================================================
-- VERIFY INSTALLATION
-- ============================================================================

DO $$
BEGIN
  -- Verify pg_bigm is installed
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_bigm') THEN
    RAISE EXCEPTION 'pg_bigm extension is not installed';
  END IF;
  
  RAISE NOTICE 'Migration 071: Multi-language search setup complete';
  RAISE NOTICE 'pg_bigm extension: INSTALLED';
  RAISE NOTICE 'CJK bi-gram indexes: CREATED';
  RAISE NOTICE 'Language detection function: CREATED';
  RAISE NOTICE 'Unified search function: CREATED';
END $$;


