-- Source: 076_delight_statistics.sql
-- RADIANT v4.18.0 - Delight System Statistics
-- Persistent statistics and analytics for delight message usage

-- ============================================================================
-- Daily Statistics Aggregation Table
-- ============================================================================

CREATE TABLE IF NOT EXISTS delight_daily_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    stat_date DATE NOT NULL,
    
    -- Message statistics
    messages_shown INTEGER DEFAULT 0,
    unique_messages_shown INTEGER DEFAULT 0,
    messages_by_category JSONB DEFAULT '{}',  -- { "domain_loading": 10, "time_awareness": 5, ... }
    messages_by_injection_point JSONB DEFAULT '{}',  -- { "pre_execution": 20, "during_execution": 15, ... }
    messages_by_trigger_type JSONB DEFAULT '{}',  -- { "domain_loading": 10, "time_aware": 5, ... }
    
    -- Achievement statistics
    achievements_unlocked INTEGER DEFAULT 0,
    achievements_by_type JSONB DEFAULT '{}',  -- { "domain_explorer": 5, "streak": 3, ... }
    achievements_by_rarity JSONB DEFAULT '{}',  -- { "common": 10, "rare": 2, "legendary": 0 }
    
    -- Easter egg statistics
    easter_eggs_discovered INTEGER DEFAULT 0,
    easter_eggs_by_id JSONB DEFAULT '{}',  -- { "konami": 3, "chaos_mode": 5, ... }
    
    -- User engagement
    active_users INTEGER DEFAULT 0,
    users_by_personality_mode JSONB DEFAULT '{}',  -- { "professional": 10, "expressive": 50, ... }
    average_intensity_level DECIMAL(3,1) DEFAULT 5.0,
    
    -- Sound statistics
    sounds_played INTEGER DEFAULT 0,
    sounds_by_theme JSONB DEFAULT '{}',  -- { "default": 100, "mission_control": 20, ... }
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, stat_date)
);

-- ============================================================================
-- Message Performance Table
-- ============================================================================

CREATE TABLE IF NOT EXISTS delight_message_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    message_id INTEGER NOT NULL REFERENCES delight_messages(id) ON DELETE CASCADE,
    
    -- Lifetime statistics
    total_shown INTEGER DEFAULT 0,
    total_unique_users INTEGER DEFAULT 0,
    
    -- Time-based stats
    shown_today INTEGER DEFAULT 0,
    shown_this_week INTEGER DEFAULT 0,
    shown_this_month INTEGER DEFAULT 0,
    
    -- Performance metrics
    first_shown_at TIMESTAMP WITH TIME ZONE,
    last_shown_at TIMESTAMP WITH TIME ZONE,
    
    -- Tracking for rate limiting
    shown_by_hour JSONB DEFAULT '{}',  -- { "0": 5, "1": 3, ..., "23": 10 }
    shown_by_day_of_week JSONB DEFAULT '{}',  -- { "0": 50, "1": 100, ..., "6": 30 }
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, message_id)
);

-- ============================================================================
-- Achievement Statistics Table
-- ============================================================================

CREATE TABLE IF NOT EXISTS delight_achievement_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    achievement_id VARCHAR(50) NOT NULL REFERENCES delight_achievements(id) ON DELETE CASCADE,
    
    -- Lifetime statistics
    total_unlocked INTEGER DEFAULT 0,
    total_in_progress INTEGER DEFAULT 0,
    
    -- Time-based stats
    unlocked_today INTEGER DEFAULT 0,
    unlocked_this_week INTEGER DEFAULT 0,
    unlocked_this_month INTEGER DEFAULT 0,
    
    -- Completion rate
    average_days_to_unlock DECIMAL(6,2),
    fastest_unlock_days DECIMAL(6,2),
    
    first_unlocked_at TIMESTAMP WITH TIME ZONE,
    last_unlocked_at TIMESTAMP WITH TIME ZONE,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, achievement_id)
);

-- ============================================================================
-- Easter Egg Discovery Statistics
-- ============================================================================

CREATE TABLE IF NOT EXISTS delight_easter_egg_stats (
    id SERIAL PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,
    easter_egg_id VARCHAR(50) NOT NULL REFERENCES delight_easter_eggs(id) ON DELETE CASCADE,
    
    -- Lifetime statistics
    total_discoveries INTEGER DEFAULT 0,
    total_activations INTEGER DEFAULT 0,  -- Some eggs can be triggered multiple times
    
    -- Time-based stats
    discovered_today INTEGER DEFAULT 0,
    discovered_this_week INTEGER DEFAULT 0,
    discovered_this_month INTEGER DEFAULT 0,
    
    first_discovered_at TIMESTAMP WITH TIME ZONE,
    last_discovered_at TIMESTAMP WITH TIME ZONE,
    
    -- Most common discovery hour (for time-based eggs)
    discovery_by_hour JSONB DEFAULT '{}',
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(tenant_id, easter_egg_id)
);

-- ============================================================================
-- User Engagement Summary
-- ============================================================================

CREATE TABLE IF NOT EXISTS delight_user_engagement (
    id SERIAL PRIMARY KEY,
    user_id VARCHAR(255) NOT NULL,
    tenant_id VARCHAR(255) NOT NULL,
    
    -- Message engagement
    total_messages_seen INTEGER DEFAULT 0,
    unique_messages_seen INTEGER DEFAULT 0,
    favorite_category VARCHAR(50),
    
    -- Achievement progress
    total_achievements_unlocked INTEGER DEFAULT 0,
    total_achievement_points INTEGER DEFAULT 0,
    current_streak_days INTEGER DEFAULT 0,
    longest_streak_days INTEGER DEFAULT 0,
    
    -- Easter egg discoveries
    total_easter_eggs_found INTEGER DEFAULT 0,
    
    -- Time tracking
    first_interaction_at TIMESTAMP WITH TIME ZONE,
    last_interaction_at TIMESTAMP WITH TIME ZONE,
    total_sessions INTEGER DEFAULT 0,
    
    -- Preferences history
    personality_mode_history JSONB DEFAULT '[]',  -- Track changes over time
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(user_id, tenant_id)
);

-- ============================================================================
-- Indexes for Statistics Tables
-- ============================================================================

CREATE INDEX IF NOT EXISTS idx_delight_daily_stats_tenant ON delight_daily_stats(tenant_id);
CREATE INDEX IF NOT EXISTS idx_delight_daily_stats_date ON delight_daily_stats(stat_date);
CREATE INDEX IF NOT EXISTS idx_delight_message_stats_tenant ON delight_message_stats(tenant_id);
CREATE INDEX IF NOT EXISTS idx_delight_message_stats_message ON delight_message_stats(message_id);
CREATE INDEX IF NOT EXISTS idx_delight_achievement_stats_tenant ON delight_achievement_stats(tenant_id);
CREATE INDEX IF NOT EXISTS idx_delight_easter_egg_stats_tenant ON delight_easter_egg_stats(tenant_id);
CREATE INDEX IF NOT EXISTS idx_delight_user_engagement_user ON delight_user_engagement(user_id, tenant_id);
CREATE INDEX IF NOT EXISTS idx_delight_event_log_type ON delight_event_log(event_type);

-- ============================================================================
-- Function to Update Daily Statistics
-- ============================================================================

CREATE OR REPLACE FUNCTION update_delight_daily_stats()
RETURNS TRIGGER AS $$
BEGIN
    -- Insert or update daily stats for the tenant
    INSERT INTO delight_daily_stats (tenant_id, stat_date, messages_shown)
    VALUES (NEW.tenant_id, CURRENT_DATE, 0)
    ON CONFLICT (tenant_id, stat_date) DO NOTHING;
    
    -- Update based on event type
    IF NEW.event_type = 'message_shown' THEN
        UPDATE delight_daily_stats
        SET messages_shown = messages_shown + 1,
            updated_at = NOW()
        WHERE tenant_id = NEW.tenant_id AND stat_date = CURRENT_DATE;
        
        -- Update message stats
        IF NEW.message_id IS NOT NULL THEN
            INSERT INTO delight_message_stats (tenant_id, message_id, total_shown, shown_today, first_shown_at, last_shown_at)
            VALUES (NEW.tenant_id, NEW.message_id, 1, 1, NOW(), NOW())
            ON CONFLICT (tenant_id, message_id) DO UPDATE SET
                total_shown = delight_message_stats.total_shown + 1,
                shown_today = delight_message_stats.shown_today + 1,
                last_shown_at = NOW(),
                updated_at = NOW();
        END IF;
        
    ELSIF NEW.event_type = 'achievement_unlocked' THEN
        UPDATE delight_daily_stats
        SET achievements_unlocked = achievements_unlocked + 1,
            updated_at = NOW()
        WHERE tenant_id = NEW.tenant_id AND stat_date = CURRENT_DATE;
        
        -- Update achievement stats
        IF NEW.achievement_id IS NOT NULL THEN
            INSERT INTO delight_achievement_stats (tenant_id, achievement_id, total_unlocked, unlocked_today, first_unlocked_at, last_unlocked_at)
            VALUES (NEW.tenant_id, NEW.achievement_id, 1, 1, NOW(), NOW())
            ON CONFLICT (tenant_id, achievement_id) DO UPDATE SET
                total_unlocked = delight_achievement_stats.total_unlocked + 1,
                unlocked_today = delight_achievement_stats.unlocked_today + 1,
                last_unlocked_at = NOW(),
                updated_at = NOW();
        END IF;
        
    ELSIF NEW.event_type = 'easter_egg_found' THEN
        UPDATE delight_daily_stats
        SET easter_eggs_discovered = easter_eggs_discovered + 1,
            updated_at = NOW()
        WHERE tenant_id = NEW.tenant_id AND stat_date = CURRENT_DATE;
        
        -- Update easter egg stats
        IF NEW.easter_egg_id IS NOT NULL THEN
            INSERT INTO delight_easter_egg_stats (tenant_id, easter_egg_id, total_discoveries, discovered_today, first_discovered_at, last_discovered_at)
            VALUES (NEW.tenant_id, NEW.easter_egg_id, 1, 1, NOW(), NOW())
            ON CONFLICT (tenant_id, easter_egg_id) DO UPDATE SET
                total_discoveries = delight_easter_egg_stats.total_discoveries + 1,
                discovered_today = delight_easter_egg_stats.discovered_today + 1,
                last_discovered_at = NOW(),
                updated_at = NOW();
        END IF;
        
    ELSIF NEW.event_type = 'sound_played' THEN
        UPDATE delight_daily_stats
        SET sounds_played = sounds_played + 1,
            updated_at = NOW()
        WHERE tenant_id = NEW.tenant_id AND stat_date = CURRENT_DATE;
    END IF;
    
    -- Update user engagement
    INSERT INTO delight_user_engagement (user_id, tenant_id, total_messages_seen, first_interaction_at, last_interaction_at, total_sessions)
    VALUES (NEW.user_id, NEW.tenant_id, 
            CASE WHEN NEW.event_type = 'message_shown' THEN 1 ELSE 0 END,
            NOW(), NOW(), 1)
    ON CONFLICT (user_id, tenant_id) DO UPDATE SET
        total_messages_seen = CASE 
            WHEN NEW.event_type = 'message_shown' 
            THEN delight_user_engagement.total_messages_seen + 1 
            ELSE delight_user_engagement.total_messages_seen 
        END,
        total_achievements_unlocked = CASE 
            WHEN NEW.event_type = 'achievement_unlocked' 
            THEN delight_user_engagement.total_achievements_unlocked + 1 
            ELSE delight_user_engagement.total_achievements_unlocked 
        END,
        total_easter_eggs_found = CASE 
            WHEN NEW.event_type = 'easter_egg_found' 
            THEN delight_user_engagement.total_easter_eggs_found + 1 
            ELSE delight_user_engagement.total_easter_eggs_found 
        END,
        last_interaction_at = NOW(),
        updated_at = NOW();
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION reset_delight_daily_counters()
RETURNS void AS $$
BEGIN
    -- Reset today counters in message stats
    UPDATE delight_message_stats
    SET shown_today = 0,
        shown_this_week = CASE 
            WHEN EXTRACT(DOW FROM CURRENT_DATE) = 1 THEN 0 
            ELSE shown_this_week 
        END,
        shown_this_month = CASE 
            WHEN EXTRACT(DAY FROM CURRENT_DATE) = 1 THEN 0 
            ELSE shown_this_month 
        END;
    
    -- Reset today counters in achievement stats
    UPDATE delight_achievement_stats
    SET unlocked_today = 0,
        unlocked_this_week = CASE 
            WHEN EXTRACT(DOW FROM CURRENT_DATE) = 1 THEN 0 
            ELSE unlocked_this_week 
        END,
        unlocked_this_month = CASE 
            WHEN EXTRACT(DAY FROM CURRENT_DATE) = 1 THEN 0 
            ELSE unlocked_this_month 
        END;
    
    -- Reset today counters in easter egg stats
    UPDATE delight_easter_egg_stats
    SET discovered_today = 0,
        discovered_this_week = CASE 
            WHEN EXTRACT(DOW FROM CURRENT_DATE) = 1 THEN 0 
            ELSE discovered_this_week 
        END,
        discovered_this_month = CASE 
            WHEN EXTRACT(DAY FROM CURRENT_DATE) = 1 THEN 0 
            ELSE discovered_this_month 
        END;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_daily_revenue(target_date DATE)
RETURNS VOID AS $$
BEGIN
    -- Insert or update platform-wide totals
    INSERT INTO revenue_daily_aggregates (
        aggregate_date, tenant_id, product,
        subscription_revenue, credit_purchase_revenue, ai_markup_external_revenue,
        ai_markup_self_hosted_revenue, overage_revenue, storage_revenue, other_revenue,
        total_gross_revenue,
        aws_compute_cost, aws_storage_cost, aws_network_cost, aws_database_cost,
        external_ai_cost, infrastructure_cost, platform_fees_cost, total_cost,
        gross_profit, gross_margin
    )
    SELECT 
        target_date,
        NULL,  -- Platform total
        'combined',
        COALESCE(SUM(CASE WHEN source = 'subscription' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN source = 'credit_purchase' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN source = 'ai_markup_external' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN source = 'ai_markup_self_hosted' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN source = 'overage' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN source = 'storage' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN source = 'other' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(amount), 0),
        0, 0, 0, 0, 0, 0, 0, 0, -- Costs populated separately
        0, 0
    FROM revenue_entries
    WHERE period_start::DATE = target_date
    ON CONFLICT (aggregate_date, tenant_id, product) DO UPDATE SET
        subscription_revenue = EXCLUDED.subscription_revenue,
        credit_purchase_revenue = EXCLUDED.credit_purchase_revenue,
        ai_markup_external_revenue = EXCLUDED.ai_markup_external_revenue,
        ai_markup_self_hosted_revenue = EXCLUDED.ai_markup_self_hosted_revenue,
        overage_revenue = EXCLUDED.overage_revenue,
        storage_revenue = EXCLUDED.storage_revenue,
        other_revenue = EXCLUDED.other_revenue,
        total_gross_revenue = EXCLUDED.total_gross_revenue,
        updated_at = NOW();
    
    -- Update costs
    UPDATE revenue_daily_aggregates rda SET
        aws_compute_cost = costs.aws_compute,
        aws_storage_cost = costs.aws_storage,
        aws_network_cost = costs.aws_network,
        aws_database_cost = costs.aws_database,
        external_ai_cost = costs.external_ai,
        infrastructure_cost = costs.infrastructure,
        platform_fees_cost = costs.platform_fees,
        total_cost = costs.total_cost,
        gross_profit = rda.total_gross_revenue - costs.total_cost,
        gross_margin = CASE 
            WHEN rda.total_gross_revenue > 0 
            THEN ((rda.total_gross_revenue - costs.total_cost) / rda.total_gross_revenue * 100)
            ELSE 0 
        END,
        updated_at = NOW()
    FROM (
        SELECT
            COALESCE(SUM(CASE WHEN category = 'aws_compute' THEN amount ELSE 0 END), 0) as aws_compute,
            COALESCE(SUM(CASE WHEN category = 'aws_storage' THEN amount ELSE 0 END), 0) as aws_storage,
            COALESCE(SUM(CASE WHEN category = 'aws_network' THEN amount ELSE 0 END), 0) as aws_network,
            COALESCE(SUM(CASE WHEN category = 'aws_database' THEN amount ELSE 0 END), 0) as aws_database,
            COALESCE(SUM(CASE WHEN category = 'external_ai' THEN amount ELSE 0 END), 0) as external_ai,
            COALESCE(SUM(CASE WHEN category = 'infrastructure' THEN amount ELSE 0 END), 0) as infrastructure,
            COALESCE(SUM(CASE WHEN category = 'platform_fees' THEN amount ELSE 0 END), 0) as platform_fees,
            COALESCE(SUM(amount), 0) as total_cost
        FROM cost_entries
        WHERE period_start::DATE = target_date
    ) costs
    WHERE rda.aggregate_date = target_date AND rda.tenant_id IS NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_revenue_aggregate()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM aggregate_daily_revenue(NEW.period_start::DATE);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_preprompt_score(
    p_template_id UUID,
    p_mode VARCHAR(50),
    p_domain_id VARCHAR(100),
    p_model_id VARCHAR(100),
    p_complexity VARCHAR(20),
    p_task_type VARCHAR(50)
) RETURNS DECIMAL AS $$
DECLARE
    v_template preprompt_templates%ROWTYPE;
    v_score DECIMAL := 0;
    v_mode_attr DECIMAL;
    v_domain_attr DECIMAL;
    v_model_attr DECIMAL;
BEGIN
    SELECT * INTO v_template FROM preprompt_templates WHERE id = p_template_id;
    
    IF NOT FOUND THEN
        RETURN 0;
    END IF;
    
    -- Start with base effectiveness
    v_score := v_template.base_effectiveness_score;
    
    -- Add mode bonus if applicable
    IF p_mode = ANY(v_template.applicable_modes) THEN
        v_score := v_score + v_template.mode_weight;
        
        -- Check attribution score for this mode
        SELECT success_correlation INTO v_mode_attr
        FROM preprompt_attribution_scores
        WHERE template_id = p_template_id AND factor_type = 'mode' AND factor_value = p_mode;
        
        IF FOUND THEN
            v_score := v_score + (v_mode_attr * v_template.feedback_weight);
        END IF;
    END IF;
    
    -- Add domain bonus if applicable
    IF p_domain_id = ANY(v_template.applicable_domains) OR array_length(v_template.applicable_domains, 1) IS NULL THEN
        v_score := v_score + v_template.domain_weight;
        
        -- Check attribution score for this domain
        SELECT success_correlation INTO v_domain_attr
        FROM preprompt_attribution_scores
        WHERE template_id = p_template_id AND factor_type = 'domain' AND factor_value = p_domain_id;
        
        IF FOUND THEN
            v_score := v_score + (v_domain_attr * v_template.feedback_weight);
        END IF;
    END IF;
    
    -- Add model bonus if compatible
    IF p_model_id = ANY(v_template.compatible_models) OR p_model_id = ANY(v_template.preferred_models) THEN
        v_score := v_score + v_template.model_weight;
        IF p_model_id = ANY(v_template.preferred_models) THEN
            v_score := v_score + 0.1; -- Extra bonus for preferred
        END IF;
    ELSIF p_model_id = ANY(v_template.incompatible_models) THEN
        v_score := v_score - 0.5; -- Penalty for incompatible
    END IF;
    
    -- Add complexity bonus
    IF p_complexity = ANY(v_template.complexity_range) THEN
        v_score := v_score + v_template.complexity_weight;
    END IF;
    
    -- Add task type bonus
    IF p_task_type = ANY(v_template.applicable_task_types) OR array_length(v_template.applicable_task_types, 1) IS NULL THEN
        v_score := v_score + v_template.task_type_weight;
    END IF;
    
    -- Apply feedback adjustment from average score
    IF v_template.avg_feedback_score IS NOT NULL THEN
        v_score := v_score + ((v_template.avg_feedback_score - 3) / 10); -- -0.2 to +0.2
    END IF;
    
    RETURN GREATEST(0, LEAST(2, v_score)); -- Cap between 0 and 2
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_preprompt_attribution(
    p_instance_id UUID
) RETURNS VOID AS $$
DECLARE
    v_instance preprompt_instances%ROWTYPE;
    v_feedback preprompt_feedback%ROWTYPE;
    v_correlation DECIMAL;
BEGIN
    SELECT * INTO v_instance FROM preprompt_instances WHERE id = p_instance_id;
    SELECT * INTO v_feedback FROM preprompt_feedback WHERE instance_id = p_instance_id ORDER BY created_at DESC LIMIT 1;
    
    IF NOT FOUND OR v_instance.template_id IS NULL THEN
        RETURN;
    END IF;
    
    -- Calculate correlation based on feedback
    v_correlation := CASE 
        WHEN v_feedback.rating >= 4 THEN 0.1
        WHEN v_feedback.rating = 3 THEN 0.0
        ELSE -0.1
    END;
    
    -- Update mode attribution
    INSERT INTO preprompt_attribution_scores (template_id, factor_type, factor_value, success_correlation, sample_size, avg_feedback_score)
    VALUES (v_instance.template_id, 'mode', v_instance.orchestration_mode, v_correlation, 1, v_feedback.rating)
    ON CONFLICT (template_id, factor_type, factor_value) DO UPDATE SET
        success_correlation = (preprompt_attribution_scores.success_correlation * preprompt_attribution_scores.sample_size + v_correlation) / (preprompt_attribution_scores.sample_size + 1),
        sample_size = preprompt_attribution_scores.sample_size + 1,
        avg_feedback_score = (COALESCE(preprompt_attribution_scores.avg_feedback_score, 3) * preprompt_attribution_scores.sample_size + v_feedback.rating) / (preprompt_attribution_scores.sample_size + 1),
        confidence = LEAST(1.0, (preprompt_attribution_scores.sample_size + 1)::DECIMAL / 100),
        last_calculated = NOW();
    
    -- Update model attribution
    INSERT INTO preprompt_attribution_scores (template_id, factor_type, factor_value, success_correlation, sample_size, avg_feedback_score)
    VALUES (v_instance.template_id, 'model', v_instance.model_id, v_correlation, 1, v_feedback.rating)
    ON CONFLICT (template_id, factor_type, factor_value) DO UPDATE SET
        success_correlation = (preprompt_attribution_scores.success_correlation * preprompt_attribution_scores.sample_size + v_correlation) / (preprompt_attribution_scores.sample_size + 1),
        sample_size = preprompt_attribution_scores.sample_size + 1,
        avg_feedback_score = (COALESCE(preprompt_attribution_scores.avg_feedback_score, 3) * preprompt_attribution_scores.sample_size + v_feedback.rating) / (preprompt_attribution_scores.sample_size + 1),
        confidence = LEAST(1.0, (preprompt_attribution_scores.sample_size + 1)::DECIMAL / 100),
        last_calculated = NOW();
    
    -- Update domain attribution if detected
    IF v_instance.detected_domain_id IS NOT NULL THEN
        INSERT INTO preprompt_attribution_scores (template_id, factor_type, factor_value, success_correlation, sample_size, avg_feedback_score)
        VALUES (v_instance.template_id, 'domain', v_instance.detected_domain_id, v_correlation, 1, v_feedback.rating)
        ON CONFLICT (template_id, factor_type, factor_value) DO UPDATE SET
            success_correlation = (preprompt_attribution_scores.success_correlation * preprompt_attribution_scores.sample_size + v_correlation) / (preprompt_attribution_scores.sample_size + 1),
            sample_size = preprompt_attribution_scores.sample_size + 1,
            avg_feedback_score = (COALESCE(preprompt_attribution_scores.avg_feedback_score, 3) * preprompt_attribution_scores.sample_size + v_feedback.rating) / (preprompt_attribution_scores.sample_size + 1),
            confidence = LEAST(1.0, (preprompt_attribution_scores.sample_size + 1)::DECIMAL / 100),
            last_calculated = NOW();
    END IF;
    
    -- Update template stats
    UPDATE preprompt_templates SET
        total_uses = total_uses + 1,
        successful_uses = successful_uses + CASE WHEN v_feedback.rating >= 4 THEN 1 ELSE 0 END,
        avg_feedback_score = (COALESCE(avg_feedback_score, 3) * total_uses + v_feedback.rating) / (total_uses + 1),
        updated_at = NOW()
    WHERE id = v_instance.template_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_update_attribution()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM update_preprompt_attribution(NEW.instance_id);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_user_rules_for_preprompt(
    p_user_id UUID,
    p_domain_id TEXT DEFAULT NULL,
    p_mode TEXT DEFAULT NULL
)
RETURNS TABLE (
    rule_id UUID,
    rule_text TEXT,
    rule_type VARCHAR(50),
    priority INTEGER
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id,
        r.rule_text,
        r.rule_type,
        r.priority
    FROM user_memory_rules r
    WHERE r.user_id = p_user_id
      AND r.is_active = true
      AND r.apply_to_preprompts = true
      AND (
          array_length(r.applicable_domains, 1) IS NULL 
          OR p_domain_id = ANY(r.applicable_domains)
      )
      AND (
          array_length(r.applicable_modes, 1) IS NULL 
          OR p_mode = ANY(r.applicable_modes)
      )
    ORDER BY r.priority DESC, r.created_at ASC;
END;
$$ LANGUAGE plpgsql STABLE;

-- Format rules as a system prompt section
CREATE OR REPLACE FUNCTION format_user_rules_for_prompt(p_user_id UUID)
RETURNS TEXT AS $$
DECLARE
    rules_text TEXT := '';
    rule_record RECORD;
BEGIN
    FOR rule_record IN 
        SELECT rule_text, rule_type 
        FROM get_user_rules_for_preprompt(p_user_id)
    LOOP
        rules_text := rules_text || '- ' || rule_record.rule_text || E'\n';
    END LOOP;
    
    IF rules_text = '' THEN
        RETURN NULL;
    END IF;
    
    RETURN E'\n## User Preferences\nThe user has set the following rules for how you should respond:\n' || rules_text;
END;
$$ LANGUAGE plpgsql STABLE;

-- Update rule application stats
CREATE OR REPLACE FUNCTION update_rule_application_stats()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE user_memory_rules
    SET times_applied = times_applied + 1,
        last_applied_at = NOW()
    WHERE id = NEW.rule_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_memory_category_tree()
RETURNS TABLE (
    id UUID,
    code VARCHAR,
    name VARCHAR,
    description TEXT,
    icon VARCHAR,
    color VARCHAR,
    level INTEGER,
    path VARCHAR,
    parent_code VARCHAR,
    is_system BOOLEAN,
    child_count BIGINT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        mc.id,
        mc.code,
        mc.name,
        mc.description,
        mc.icon,
        mc.color,
        mc.level,
        mc.path,
        parent.code AS parent_code,
        mc.is_system,
        (SELECT COUNT(*) FROM memory_categories child WHERE child.parent_id = mc.id) AS child_count
    FROM memory_categories mc
    LEFT JOIN memory_categories parent ON mc.parent_id = parent.id
    ORDER BY mc.display_order, mc.name;
END;
$$ LANGUAGE plpgsql STABLE;

-- Get memories by category
CREATE OR REPLACE FUNCTION get_user_memories_by_category(
    p_user_id UUID,
    p_category_code VARCHAR DEFAULT NULL
)
RETURNS TABLE (
    memory_id UUID,
    rule_text TEXT,
    rule_summary VARCHAR,
    category_code VARCHAR,
    category_name VARCHAR,
    category_icon VARCHAR,
    category_color VARCHAR,
    is_active BOOLEAN,
    times_applied INTEGER,
    created_at TIMESTAMPTZ
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id AS memory_id,
        r.rule_text,
        r.rule_summary,
        mc.code AS category_code,
        mc.name AS category_name,
        mc.icon AS category_icon,
        mc.color AS category_color,
        r.is_active,
        r.times_applied,
        r.created_at
    FROM user_memory_rules r
    LEFT JOIN memory_categories mc ON r.memory_category_id = mc.id OR r.memory_category_code = mc.code
    WHERE r.user_id = p_user_id
      AND (p_category_code IS NULL OR mc.code = p_category_code OR mc.path LIKE p_category_code || '.%')
    ORDER BY mc.display_order, r.priority DESC, r.created_at;
END;
$$ LANGUAGE plpgsql STABLE;

-- ============================================================================
-- Update preset rules with categories
-- ============================================================================

UPDATE preset_user_rules SET 
    -- Will need to add memory_category_code column first
    -- This is a placeholder for category assignment
    updated_at = NOW()
WHERE id IS NOT NULL;

-- Add category_code to preset_user_rules
ALTER TABLE preset_user_rules
ADD COLUMN IF NOT EXISTS memory_category_code VARCHAR(50);

-- Assign categories to existing presets based on rule_type
UPDATE preset_user_rules SET memory_category_code = 
    CASE rule_type
        WHEN 'restriction' THEN 'constraint.topic'
        WHEN 'privacy' THEN 'constraint.privacy'
        WHEN 'format' THEN 'instruction.format'
        WHEN 'source' THEN 'instruction.source'
        WHEN 'tone' THEN 'instruction.tone'
        WHEN 'preference' THEN 'preference.style'
        WHEN 'accessibility' THEN 'preference.style'
        WHEN 'topic' THEN 'constraint.topic'
        ELSE 'preference'
    END
WHERE memory_category_code IS NULL;

-- ============================================================================
-- Grants
-- ============================================================================

GRANT SELECT ON memory_categories TO authenticated;
GRANT EXECUTE ON FUNCTION get_memory_category_tree TO authenticated;
GRANT EXECUTE ON FUNCTION get_user_memories_by_category TO authenticated;


-- Source: 082_ai_ethics_standards.sql
-- Migration: 082_ai_ethics_standards
-- Description: Add AI ethics standards framework with industry standard sources
-- Shows administrators the standards each ethical principle is derived from
-- Author: RADIANT System
-- Date: 2024-12-28

-- ============================================================================
-- AI Ethics Standards - Industry frameworks and their principles
-- ============================================================================

CREATE TABLE IF NOT EXISTS ai_ethics_standards (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Standard identification
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    full_name VARCHAR(500) NOT NULL,
    version VARCHAR(50),
    
    -- Organization
    organization VARCHAR(255) NOT NULL,
    organization_type VARCHAR(50) NOT NULL,  -- government, iso, industry, academic, religious
    
    -- Details
    description TEXT,
    url VARCHAR(500),
    publication_date DATE,
    
    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    is_mandatory BOOLEAN NOT NULL DEFAULT false,  -- Required for compliance
    
    -- Display
    display_order INTEGER NOT NULL DEFAULT 0,
    icon VARCHAR(50),
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ============================================================================
-- Add standard references to ethical_principles
-- ============================================================================

ALTER TABLE ethical_principles
ADD COLUMN IF NOT EXISTS standard_codes TEXT[] DEFAULT '{}';

ALTER TABLE ethical_principles
ADD COLUMN IF NOT EXISTS standard_references JSONB DEFAULT '[]';

ALTER TABLE ethical_principles
ADD COLUMN IF NOT EXISTS framework_alignment TEXT;

