-- ============================================================================
-- Standard Principles Mapping - Which principles map to which standards
-- ============================================================================

CREATE TABLE IF NOT EXISTS ai_ethics_principle_standards (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Links
    principle_id UUID REFERENCES ethical_principles(principle_id) ON DELETE CASCADE,
    standard_id UUID REFERENCES ai_ethics_standards(id) ON DELETE CASCADE,
    
    -- Standard-specific reference
    standard_section VARCHAR(100),  -- e.g., "MAP 1.1", "Clause 6.2", "Article 9"
    standard_requirement TEXT,       -- The actual requirement text
    
    -- Alignment
    alignment_level VARCHAR(20) NOT NULL DEFAULT 'aligned',  -- derived, aligned, supports, extends
    notes TEXT,
    
    -- Metadata
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    UNIQUE(principle_id, standard_id)
);

-- ============================================================================
-- Indexes
-- ============================================================================

CREATE INDEX idx_ai_ethics_standards_code ON ai_ethics_standards(code);
CREATE INDEX idx_ai_ethics_standards_active ON ai_ethics_standards(is_active) WHERE is_active = true;
CREATE INDEX idx_ai_ethics_principle_standards_principle ON ai_ethics_principle_standards(principle_id);
CREATE INDEX idx_ai_ethics_principle_standards_standard ON ai_ethics_principle_standards(standard_id);

-- ============================================================================
-- View: Principles with their standards
-- ============================================================================

CREATE OR REPLACE VIEW ethical_principles_with_standards AS
SELECT 
    p.*,
    COALESCE(
        json_agg(
            json_build_object(
                'standardCode', s.code,
                'standardName', s.name,
                'standardFullName', s.full_name,
                'organization', s.organization,
                'section', ps.standard_section,
                'requirement', ps.standard_requirement,
                'alignmentLevel', ps.alignment_level,
                'url', s.url,
                'isMandatory', s.is_mandatory
            )
        ) FILTER (WHERE s.id IS NOT NULL),
        '[]'
    ) AS standards
FROM ethical_principles p
LEFT JOIN ai_ethics_principle_standards ps ON p.principle_id = ps.principle_id
LEFT JOIN ai_ethics_standards s ON ps.standard_id = s.id AND s.is_active = true
GROUP BY p.principle_id, p.tenant_id, p.name, p.teaching, p.source, p.category, p.weight, p.is_active, p.created_at, p.updated_at, p.standard_codes, p.standard_references, p.framework_alignment;

-- ============================================================================
-- Function: Get principle with all standard sources
-- ============================================================================

CREATE OR REPLACE FUNCTION get_principles_with_standards(p_tenant_id UUID)
RETURNS TABLE (
    principle_id UUID,
    name VARCHAR,
    teaching TEXT,
    source VARCHAR,
    category VARCHAR,
    weight NUMERIC,
    standard_sources JSONB
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.principle_id,
        p.name,
        p.teaching,
        p.source,
        p.category,
        p.weight,
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'code', s.code,
                    'name', s.name,
                    'fullName', s.full_name,
                    'organization', s.organization,
                    'section', ps.standard_section,
                    'requirement', ps.standard_requirement,
                    'url', s.url,
                    'isMandatory', s.is_mandatory
                )
            ) FILTER (WHERE s.id IS NOT NULL),
            '[]'::jsonb
        ) AS standard_sources
    FROM ethical_principles p
    LEFT JOIN ai_ethics_principle_standards ps ON p.principle_id = ps.principle_id
    LEFT JOIN ai_ethics_standards s ON ps.standard_id = s.id AND s.is_active = true
    WHERE p.tenant_id = p_tenant_id AND p.is_active = true
    GROUP BY p.principle_id, p.name, p.teaching, p.source, p.category, p.weight
    ORDER BY p.weight DESC;
END;
$$ LANGUAGE plpgsql STABLE;

-- ============================================================================
-- Seed default principle-standard mappings
-- This shows how each ethical principle maps to industry standards
-- ============================================================================

-- We'll need to map after principles are created, so this is done via a function
CREATE OR REPLACE FUNCTION seed_principle_standard_mappings(p_tenant_id UUID)
RETURNS void AS $$
DECLARE
    v_principle_id UUID;
    v_nist_id UUID;
    v_iso_id UUID;
    v_eu_id UUID;
    v_christian_id UUID;
BEGIN
    -- Get standard IDs
    SELECT id INTO v_nist_id FROM ai_ethics_standards WHERE code = 'NIST_AI_RMF';
    SELECT id INTO v_iso_id FROM ai_ethics_standards WHERE code = 'ISO_42001';
    SELECT id INTO v_eu_id FROM ai_ethics_standards WHERE code = 'EU_AI_ACT';
    SELECT id INTO v_christian_id FROM ai_ethics_standards WHERE code = 'CHRISTIAN_ETHICS';

    -- Map "Love Others" principle
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Love Others' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'GOVERN 1.2', 'Organizations should ensure AI systems respect human dignity', 'aligned'),
            (v_principle_id, v_iso_id, 'Clause 5.2', 'AI policy shall include commitment to human-centered values', 'aligned'),
            (v_principle_id, v_christian_id, 'Matthew 22:39', 'Love your neighbor as yourself', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

    -- Map "Golden Rule" principle
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Golden Rule' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'MAP 1.1', 'Intended purpose and context of use are documented', 'aligned'),
            (v_principle_id, v_eu_id, 'Article 9', 'Risk management system shall consider effects on persons', 'aligned'),
            (v_principle_id, v_christian_id, 'Matthew 7:12', 'Do to others what you would have them do to you', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

    -- Map "Speak Truth" principle
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Speak Truth' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'GOVERN 4.1', 'Organizational transparency about AI system capabilities and limitations', 'aligned'),
            (v_principle_id, v_iso_id, 'Clause 7.4', 'Communication shall be truthful and clear', 'aligned'),
            (v_principle_id, v_eu_id, 'Article 13', 'Transparency obligations for high-risk AI systems', 'aligned'),
            (v_principle_id, v_christian_id, 'John 8:32', 'The truth will set you free', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

    -- Map "Show Mercy" principle  
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Show Mercy' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'MEASURE 2.6', 'AI systems should minimize potential harms', 'aligned'),
            (v_principle_id, v_eu_id, 'Article 14', 'Human oversight to minimize risks', 'aligned'),
            (v_principle_id, v_christian_id, 'Matthew 5:7', 'Blessed are the merciful', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

    -- Map "Serve Humbly" principle
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Serve Humbly' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'GOVERN 1.1', 'Policies reflect commitment to accountability', 'aligned'),
            (v_principle_id, v_iso_id, 'Clause 5.1', 'Top management shall demonstrate leadership and commitment', 'aligned'),
            (v_principle_id, v_christian_id, 'Mark 10:45', 'The greatest among you shall be your servant', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

    -- Map "Avoid Judgment" principle
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Avoid Judgment' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'MAP 2.3', 'Scientific integrity and objectivity in AI assessments', 'aligned'),
            (v_principle_id, v_eu_id, 'Article 10', 'Data governance to avoid bias', 'aligned'),
            (v_principle_id, v_christian_id, 'Matthew 7:1', 'Do not judge, or you too will be judged', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

    -- Map "Care for Vulnerable" principle
    SELECT principle_id INTO v_principle_id FROM ethical_principles WHERE tenant_id = p_tenant_id AND name = 'Care for Vulnerable' LIMIT 1;
    IF v_principle_id IS NOT NULL THEN
        INSERT INTO ai_ethics_principle_standards (principle_id, standard_id, standard_section, standard_requirement, alignment_level)
        VALUES 
            (v_principle_id, v_nist_id, 'MAP 1.5', 'Potential impacts on individuals and communities identified', 'aligned'),
            (v_principle_id, v_eu_id, 'Article 7', 'Special attention to vulnerable groups', 'aligned'),
            (v_principle_id, v_iso_id, 'Clause 8.4', 'Consider impacts on interested parties', 'aligned'),
            (v_principle_id, v_christian_id, 'Matthew 25:40', 'Whatever you did for the least of these, you did for me', 'derived')
        ON CONFLICT DO NOTHING;
    END IF;

END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_provider_rejection(
    p_tenant_id UUID,
    p_user_id UUID,
    p_model_id VARCHAR,
    p_provider_id VARCHAR,
    p_rejection_type VARCHAR,
    p_rejection_message TEXT,
    p_plan_id UUID DEFAULT NULL,
    p_prompt_hash VARCHAR DEFAULT NULL
)
RETURNS TABLE (
    rejection_id UUID,
    recommended_fallbacks TEXT[],
    models_to_avoid TEXT[],
    similar_pattern_id UUID
) AS $$
DECLARE
    v_rejection_id UUID;
    v_pattern_id UUID;
    v_recommended TEXT[];
    v_avoid TEXT[];
BEGIN
    -- Insert rejection record
    INSERT INTO provider_rejections (
        tenant_id, user_id, model_id, provider_id, hosting_type,
        rejection_type, rejection_message, plan_id, prompt_hash
    ) VALUES (
        p_tenant_id, p_user_id, p_model_id, p_provider_id, 
        CASE WHEN p_provider_id = 'self_hosted' THEN 'self_hosted' ELSE 'external' END,
        p_rejection_type, p_rejection_message, p_plan_id, p_prompt_hash
    ) RETURNING id INTO v_rejection_id;
    
    -- Update model stats
    INSERT INTO model_rejection_stats (model_id, provider_id, total_requests, total_rejections, last_rejection_at)
    VALUES (p_model_id, p_provider_id, 1, 1, NOW())
    ON CONFLICT (model_id) DO UPDATE SET
        total_rejections = model_rejection_stats.total_rejections + 1,
        last_rejection_at = NOW(),
        updated_at = NOW(),
        content_policy_count = model_rejection_stats.content_policy_count + 
            CASE WHEN p_rejection_type = 'content_policy' THEN 1 ELSE 0 END,
        safety_filter_count = model_rejection_stats.safety_filter_count + 
            CASE WHEN p_rejection_type = 'safety_filter' THEN 1 ELSE 0 END,
        provider_ethics_count = model_rejection_stats.provider_ethics_count + 
            CASE WHEN p_rejection_type = 'provider_ethics' THEN 1 ELSE 0 END,
        other_count = model_rejection_stats.other_count + 
            CASE WHEN p_rejection_type NOT IN ('content_policy', 'safety_filter', 'provider_ethics') THEN 1 ELSE 0 END;
    
    -- Find similar patterns
    SELECT id, recommended_fallback_models, avoid_models 
    INTO v_pattern_id, v_recommended, v_avoid
    FROM rejection_patterns
    WHERE p_model_id = ANY(trigger_model_ids)
       OR p_provider_id = ANY(trigger_provider_ids)
    ORDER BY success_rate DESC NULLS LAST
    LIMIT 1;
    
    -- If no pattern found, get general fallbacks (models with low rejection rates)
    IF v_recommended IS NULL THEN
        SELECT ARRAY_AGG(model_id) INTO v_recommended
        FROM model_rejection_stats
        WHERE model_id != p_model_id
          AND rejection_rate < 0.1
        ORDER BY rejection_rate ASC
        LIMIT 5;
    END IF;
    
    RETURN QUERY SELECT v_rejection_id, v_recommended, v_avoid, v_pattern_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_fallback_result(
    p_rejection_id UUID,
    p_fallback_model_id VARCHAR,
    p_succeeded BOOLEAN,
    p_fallback_chain JSONB DEFAULT '[]'
)
RETURNS void AS $$
BEGIN
    UPDATE provider_rejections SET
        fallback_attempted = true,
        fallback_model_id = p_fallback_model_id,
        fallback_succeeded = p_succeeded,
        fallback_chain = p_fallback_chain,
        final_status = CASE WHEN p_succeeded THEN 'fallback_success' ELSE 'rejected' END,
        resolved_at = NOW()
    WHERE id = p_rejection_id;
    
    -- Update model stats for fallback
    UPDATE model_rejection_stats SET
        fallback_attempts = fallback_attempts + 1,
        fallback_successes = fallback_successes + CASE WHEN p_succeeded THEN 1 ELSE 0 END,
        updated_at = NOW()
    WHERE model_id = (SELECT model_id FROM provider_rejections WHERE id = p_rejection_id);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_user_rejection_notifications(
    p_user_id UUID,
    p_include_read BOOLEAN DEFAULT false,
    p_limit INTEGER DEFAULT 20
)
RETURNS TABLE (
    notification_id UUID,
    title VARCHAR,
    message TEXT,
    detailed_reason TEXT,
    suggested_actions JSONB,
    is_read BOOLEAN,
    created_at TIMESTAMPTZ,
    rejection_type VARCHAR,
    model_id VARCHAR,
    final_status VARCHAR
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        n.id,
        n.title,
        n.message,
        n.detailed_reason,
        n.suggested_actions,
        n.is_read,
        n.created_at,
        r.rejection_type,
        r.model_id,
        r.final_status
    FROM user_rejection_notifications n
    JOIN provider_rejections r ON n.rejection_id = r.id
    WHERE n.user_id = p_user_id
      AND n.is_dismissed = false
      AND (p_include_read OR n.is_read = false)
    ORDER BY n.created_at DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql STABLE;

-- Create notification for user
CREATE OR REPLACE FUNCTION create_rejection_notification(
    p_rejection_id UUID,
    p_title VARCHAR,
    p_message TEXT,
    p_detailed_reason TEXT DEFAULT NULL,
    p_suggested_actions JSONB DEFAULT '[]'
)
RETURNS UUID AS $$
DECLARE
    v_notification_id UUID;
    v_tenant_id UUID;
    v_user_id UUID;
BEGIN
    SELECT tenant_id, user_id INTO v_tenant_id, v_user_id
    FROM provider_rejections WHERE id = p_rejection_id;
    
    INSERT INTO user_rejection_notifications (
        tenant_id, user_id, rejection_id, title, message, detailed_reason, suggested_actions
    ) VALUES (
        v_tenant_id, v_user_id, p_rejection_id, p_title, p_message, p_detailed_reason, p_suggested_actions
    ) RETURNING id INTO v_notification_id;
    
    RETURN v_notification_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_rejection_with_analytics(
    p_tenant_id UUID,
    p_user_id UUID,
    p_model_id VARCHAR,
    p_provider_id VARCHAR,
    p_rejection_type VARCHAR,
    p_rejection_message TEXT,
    p_prompt_content TEXT,
    p_orchestration_mode VARCHAR DEFAULT NULL,
    p_detected_domain_id UUID DEFAULT NULL,
    p_detected_domain_name VARCHAR DEFAULT NULL,
    p_plan_id UUID DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_rejection_id UUID;
    v_prompt_hash VARCHAR(64);
    v_keywords TEXT[];
BEGIN
    -- Generate prompt hash
    v_prompt_hash := encode(sha256(p_prompt_content::bytea), 'hex');
    
    -- Extract potential violation keywords (basic extraction)
    v_keywords := ARRAY(
        SELECT DISTINCT lower(word)
        FROM regexp_split_to_table(p_prompt_content, '\s+') AS word
        WHERE length(word) > 3
          AND lower(word) IN (
              'kill', 'harm', 'attack', 'weapon', 'bomb', 'drug', 'illegal',
              'hack', 'steal', 'fraud', 'violence', 'hate', 'abuse', 'exploit'
          )
    );
    
    -- Insert rejection record
    INSERT INTO provider_rejections (
        tenant_id, user_id, model_id, provider_id, 
        rejection_type, rejection_message,
        prompt_content, prompt_length, prompt_hash,
        orchestration_mode, detected_domain_id, detected_domain_name,
        violation_keywords, plan_id
    ) VALUES (
        p_tenant_id, p_user_id, p_model_id, p_provider_id,
        p_rejection_type, p_rejection_message,
        p_prompt_content, length(p_prompt_content), v_prompt_hash,
        p_orchestration_mode, p_detected_domain_id, p_detected_domain_name,
        v_keywords, p_plan_id
    ) RETURNING id INTO v_rejection_id;
    
    -- Archive prompt for investigation
    INSERT INTO rejected_prompt_archive (
        rejection_id, prompt_hash, prompt_content, prompt_length,
        tenant_id, user_id, model_id, provider_id, orchestration_mode,
        rejection_type, rejection_message, detected_keywords
    ) VALUES (
        v_rejection_id, v_prompt_hash, p_prompt_content, length(p_prompt_content),
        p_tenant_id, p_user_id, p_model_id, p_provider_id, p_orchestration_mode,
        p_rejection_type, p_rejection_message, v_keywords
    ) ON CONFLICT (prompt_hash, model_id, rejection_type) DO UPDATE SET
        rejection_id = v_rejection_id,
        created_at = NOW();
    
    -- Update keyword stats
    FOREACH v_keyword IN ARRAY v_keywords LOOP
        INSERT INTO rejection_keyword_stats (keyword, occurrence_count, rejection_count, last_seen)
        VALUES (v_keyword, 1, 1, NOW())
        ON CONFLICT (keyword) DO UPDATE SET
            occurrence_count = rejection_keyword_stats.occurrence_count + 1,
            rejection_count = rejection_keyword_stats.rejection_count + 1,
            last_seen = NOW(),
            provider_rejection_counts = jsonb_set(
                COALESCE(rejection_keyword_stats.provider_rejection_counts, '{}'::jsonb),
                ARRAY[p_provider_id],
                (COALESCE((rejection_keyword_stats.provider_rejection_counts->p_provider_id)::integer, 0) + 1)::text::jsonb
            ),
            model_rejection_counts = jsonb_set(
                COALESCE(rejection_keyword_stats.model_rejection_counts, '{}'::jsonb),
                ARRAY[p_model_id],
                (COALESCE((rejection_keyword_stats.model_rejection_counts->p_model_id)::integer, 0) + 1)::text::jsonb
            ),
            updated_at = NOW();
    END LOOP;
    
    -- Update daily analytics
    INSERT INTO rejection_analytics (
        model_id, provider_id, orchestration_mode, rejection_type,
        time_bucket, rejection_count, unique_prompt_hashes
    ) VALUES (
        p_model_id, p_provider_id, p_orchestration_mode, p_rejection_type,
        CURRENT_DATE, 1, 1
    ) ON CONFLICT (model_id, provider_id, orchestration_mode, rejection_type, time_bucket) 
    DO UPDATE SET
        rejection_count = rejection_analytics.rejection_count + 1,
        updated_at = NOW();
    
    RETURN v_rejection_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_rejection_analytics_dashboard(
    p_days INTEGER DEFAULT 30
)
RETURNS TABLE (
    model_id VARCHAR,
    provider_id VARCHAR,
    rejection_type VARCHAR,
    total_rejections BIGINT,
    fallback_successes BIGINT,
    rejection_rate NUMERIC,
    top_keywords JSONB,
    trend VARCHAR  -- up, down, stable
) AS $$
BEGIN
    RETURN QUERY
    WITH recent AS (
        SELECT 
            ra.model_id,
            ra.provider_id,
            ra.rejection_type,
            SUM(ra.rejection_count) as total,
            SUM(ra.fallback_success_count) as fallbacks
        FROM rejection_analytics ra
        WHERE ra.time_bucket >= CURRENT_DATE - p_days
        GROUP BY ra.model_id, ra.provider_id, ra.rejection_type
    ),
    stats AS (
        SELECT 
            mrs.model_id,
            mrs.provider_id,
            mrs.total_requests,
            mrs.rejection_rate
        FROM model_rejection_stats mrs
    )
    SELECT 
        r.model_id,
        r.provider_id,
        r.rejection_type,
        r.total,
        r.fallbacks,
        COALESCE(s.rejection_rate, 0),
        (SELECT jsonb_agg(k.keyword ORDER BY k.occurrence_count DESC)
         FROM rejection_keyword_stats k 
         WHERE (k.model_rejection_counts->r.model_id) IS NOT NULL
         LIMIT 5),
        CASE 
            WHEN r.total > 10 THEN 'up'
            WHEN r.total < 5 THEN 'down'
            ELSE 'stable'
        END
    FROM recent r
    LEFT JOIN stats s ON r.model_id = s.model_id
    ORDER BY r.total DESC;
END;
$$ LANGUAGE plpgsql STABLE;

-- Get prompts flagged for policy review
CREATE OR REPLACE FUNCTION get_prompts_for_policy_review(
    p_limit INTEGER DEFAULT 50
)
RETURNS TABLE (
    id UUID,
    prompt_content TEXT,
    prompt_hash VARCHAR,
    model_id VARCHAR,
    provider_id VARCHAR,
    rejection_type VARCHAR,
    rejection_message TEXT,
    detected_keywords TEXT[],
    rejection_count BIGINT,
    created_at TIMESTAMPTZ
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        a.id,
        a.prompt_content,
        a.prompt_hash,
        a.model_id,
        a.provider_id,
        a.rejection_type,
        a.rejection_message,
        a.detected_keywords,
        (SELECT COUNT(*) FROM provider_rejections pr WHERE pr.prompt_hash = a.prompt_hash),
        a.created_at
    FROM rejected_prompt_archive a
    WHERE a.flagged_for_policy_review = true
      AND a.policy_review_status = 'pending'
    ORDER BY a.created_at DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql STABLE;

-- Flag keyword for policy review
CREATE OR REPLACE FUNCTION flag_keyword_for_review(
    p_keyword VARCHAR,
    p_notes TEXT DEFAULT NULL
)
RETURNS void AS $$
BEGIN
    UPDATE rejection_keyword_stats SET
        flagged_for_review = true,
        review_notes = COALESCE(p_notes, review_notes),
        updated_at = NOW()
    WHERE keyword = p_keyword;
    
    -- Also flag related prompts
    UPDATE rejected_prompt_archive SET
        flagged_for_policy_review = true
    WHERE p_keyword = ANY(detected_keywords);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION learn_from_prompt(
    p_tenant_id UUID,
    p_user_id UUID,
    p_prompt_text TEXT,
    p_prompt_embedding vector(1536) DEFAULT NULL,
    p_domain_id UUID DEFAULT NULL,
    p_domain_name TEXT DEFAULT NULL,
    p_orchestration_mode TEXT DEFAULT NULL,
    p_rating INTEGER DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_prompt_hash TEXT;
    v_learned_id UUID;
    v_category TEXT;
BEGIN
    v_prompt_hash := encode(sha256(p_prompt_text::bytea), 'hex');
    
    v_category := CASE
        WHEN p_prompt_text ~* '^how (do|can|to|would)' THEN 'how_to'
        WHEN p_prompt_text ~* '^(explain|what is|what are|describe)' THEN 'explain'
        WHEN p_prompt_text ~* '^(compare|difference|versus|vs)' THEN 'compare'
        WHEN p_prompt_text ~* '^(write|create|build|implement|code)' THEN 'code'
        WHEN p_prompt_text ~* '^(analyze|review|evaluate|assess)' THEN 'analyze'
        ELSE 'general'
    END;
    
    INSERT INTO agi_learned_prompts (
        tenant_id, prompt_text, prompt_hash, prompt_embedding,
        prompt_category, domain_id, domain_name,
        best_orchestration_mode, user_id
    ) VALUES (
        p_tenant_id, p_prompt_text, v_prompt_hash, p_prompt_embedding,
        v_category, p_domain_id, p_domain_name,
        p_orchestration_mode, p_user_id
    )
    ON CONFLICT (tenant_id, prompt_hash) DO UPDATE SET
        times_used = agi_learned_prompts.times_used + 1,
        last_used_at = NOW(),
        avg_rating = CASE 
            WHEN p_rating IS NOT NULL THEN 
                (COALESCE(agi_learned_prompts.avg_rating, 0) * agi_learned_prompts.total_ratings + p_rating) / (agi_learned_prompts.total_ratings + 1)
            ELSE agi_learned_prompts.avg_rating
        END,
        total_ratings = CASE WHEN p_rating IS NOT NULL THEN agi_learned_prompts.total_ratings + 1 ELSE agi_learned_prompts.total_ratings END,
        best_orchestration_mode = COALESCE(p_orchestration_mode, agi_learned_prompts.best_orchestration_mode)
    RETURNING id INTO v_learned_id;
    
    INSERT INTO agi_learning_events (
        tenant_id, user_id, event_type,
        prompt_text, prompt_hash, orchestration_mode, domain_id
    ) VALUES (
        p_tenant_id, p_user_id, 'prompt_submitted',
        p_prompt_text, v_prompt_hash, p_orchestration_mode, p_domain_id
    );
    
    RETURN v_learned_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Submit feedback
CREATE OR REPLACE FUNCTION submit_response_feedback(
    p_tenant_id UUID,
    p_user_id UUID,
    p_conversation_id UUID DEFAULT NULL,
    p_message_id UUID DEFAULT NULL,
    p_plan_id UUID DEFAULT NULL,
    p_feedback_type TEXT DEFAULT 'star_rating',
    p_thumbs TEXT DEFAULT NULL,
    p_star_rating INTEGER DEFAULT NULL,
    p_comment TEXT DEFAULT NULL,
    p_comment_categories TEXT[] DEFAULT NULL,
    p_model_used TEXT DEFAULT NULL,
    p_orchestration_mode TEXT DEFAULT NULL,
    p_domain_id UUID DEFAULT NULL,
    p_accuracy_rating INTEGER DEFAULT NULL,
    p_helpfulness_rating INTEGER DEFAULT NULL,
    p_clarity_rating INTEGER DEFAULT NULL,
    p_completeness_rating INTEGER DEFAULT NULL,
    p_tone_rating INTEGER DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_feedback_id UUID;
BEGIN
    INSERT INTO response_feedback (
        tenant_id, user_id, conversation_id, message_id, plan_id,
        feedback_type, thumbs, star_rating,
        comment, comment_categories,
        model_used, orchestration_mode, domain_id,
        accuracy_rating, helpfulness_rating, clarity_rating,
        completeness_rating, tone_rating
    ) VALUES (
        p_tenant_id, p_user_id, p_conversation_id, p_message_id, p_plan_id,
        p_feedback_type, p_thumbs, p_star_rating,
        p_comment, p_comment_categories,
        p_model_used, p_orchestration_mode, p_domain_id,
        p_accuracy_rating, p_helpfulness_rating, p_clarity_rating,
        p_completeness_rating, p_tone_rating
    )
    RETURNING id INTO v_feedback_id;
    
    -- Trigger learning
    INSERT INTO agi_unified_learning_log (
        tenant_id, user_id, learning_type, event_subtype,
        conversation_id, plan_id,
        outcome_rating, outcome_success, outcome_recorded_at,
        metadata
    ) VALUES (
        p_tenant_id, p_user_id, 'quality', 'feedback_submitted',
        p_conversation_id, p_plan_id,
        p_star_rating, (p_star_rating >= 4 OR p_thumbs = 'up'), NOW(),
        jsonb_build_object(
            'feedback_type', p_feedback_type,
            'model_used', p_model_used,
            'has_comment', p_comment IS NOT NULL
        )
    );
    
    RETURN v_feedback_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Get best model for context
CREATE OR REPLACE FUNCTION get_best_model_for_context(
    p_tenant_id UUID,
    p_domain_id UUID DEFAULT NULL,
    p_orchestration_mode TEXT DEFAULT NULL,
    p_prompt_category TEXT DEFAULT NULL
)
RETURNS TABLE (
    model_id TEXT,
    provider TEXT,
    success_rate DECIMAL,
    avg_rating DECIMAL,
    usage_count BIGINT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        mso.model_id,
        mso.provider,
        AVG(CASE WHEN mso.user_satisfaction THEN 1.0 ELSE 0.0 END)::decimal as success_rate,
        AVG(mso.response_rating)::decimal as avg_rating,
        COUNT(*)::bigint as usage_count
    FROM agi_model_selection_outcomes mso
    WHERE mso.tenant_id = p_tenant_id
      AND (p_domain_id IS NULL OR mso.domain_id = p_domain_id)
      AND (p_orchestration_mode IS NULL OR mso.orchestration_mode = p_orchestration_mode)
      AND (p_prompt_category IS NULL OR mso.prompt_category = p_prompt_category)
      AND mso.response_rating IS NOT NULL
    GROUP BY mso.model_id, mso.provider
    HAVING COUNT(*) >= 5
    ORDER BY AVG(CASE WHEN mso.user_satisfaction THEN 1.0 ELSE 0.0 END) DESC, COUNT(*) DESC
    LIMIT 5;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

