-- Function to update affective state based on events
CREATE OR REPLACE FUNCTION update_affect_on_event(
    p_tenant_id UUID,
    p_event_type TEXT,
    p_valence_impact NUMERIC,
    p_arousal_impact NUMERIC
) RETURNS VOID AS $$
BEGIN
    INSERT INTO affective_state (tenant_id, valence, arousal)
    VALUES (p_tenant_id, GREATEST(-1, LEAST(1, p_valence_impact)), GREATEST(0, LEAST(1, 0.5 + p_arousal_impact)))
    ON CONFLICT (tenant_id) DO UPDATE SET
        valence = GREATEST(-1, LEAST(1, affective_state.valence + p_valence_impact * 0.3)),
        arousal = GREATEST(0, LEAST(1, affective_state.arousal + p_arousal_impact * 0.3)),
        updated_at = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_consciousness_profile(
    p_tenant_id UUID
) RETURNS VOID AS $$
DECLARE
    v_overall NUMERIC;
    v_passed INTEGER;
    v_total INTEGER;
    v_events INTEGER;
    v_level TEXT;
BEGIN
    -- Calculate stats from test results
    SELECT 
        COALESCE(AVG(score), 0),
        COUNT(*) FILTER (WHERE passed = true),
        COUNT(*)
    INTO v_overall, v_passed, v_total
    FROM consciousness_test_results
    WHERE tenant_id = p_tenant_id
    AND timestamp > NOW() - INTERVAL '30 days';
    
    -- Count emergence events
    SELECT COUNT(*) INTO v_events
    FROM emergence_events
    WHERE tenant_id = p_tenant_id
    AND timestamp > NOW() - INTERVAL '30 days';
    
    -- Determine emergence level
    v_level := CASE
        WHEN v_overall >= 0.8 THEN 'advanced'
        WHEN v_overall >= 0.65 THEN 'established'
        WHEN v_overall >= 0.5 THEN 'developing'
        WHEN v_overall >= 0.3 THEN 'emerging'
        ELSE 'dormant'
    END;
    
    -- Update profile
    INSERT INTO consciousness_profiles (tenant_id, overall_score, emergence_level, emergence_events, tests_passed, tests_total, last_assessment)
    VALUES (p_tenant_id, v_overall, v_level, v_events, v_passed, v_total, NOW())
    ON CONFLICT (tenant_id) DO UPDATE SET
        overall_score = v_overall,
        emergence_level = v_level,
        emergence_events = v_events,
        tests_passed = v_passed,
        tests_total = v_total,
        last_assessment = NOW(),
        updated_at = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_app_state(
    p_app_id UUID,
    p_user_id UUID,
    p_component_id TEXT,
    p_input_id TEXT,
    p_new_value JSONB
) RETURNS JSONB AS $$
DECLARE
    v_tenant_id UUID;
    v_previous_value JSONB;
    v_new_state JSONB;
BEGIN
    -- Get current state and tenant
    SELECT tenant_id, current_state -> (p_component_id || '_' || p_input_id)
    INTO v_tenant_id, v_previous_value
    FROM generated_apps
    WHERE id = p_app_id;
    
    -- Update state
    UPDATE generated_apps
    SET current_state = jsonb_set(
            current_state,
            ARRAY[p_component_id || '_' || p_input_id],
            p_new_value
        ),
        interaction_count = interaction_count + 1,
        last_interacted_at = NOW(),
        updated_at = NOW()
    WHERE id = p_app_id
    RETURNING current_state INTO v_new_state;
    
    -- Record interaction
    INSERT INTO app_interactions (
        tenant_id, app_id, user_id,
        component_id, input_id,
        previous_value, new_value
    ) VALUES (
        v_tenant_id, p_app_id, p_user_id,
        p_component_id, p_input_id,
        v_previous_value, p_new_value
    );
    
    RETURN v_new_state;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_or_create_app_preferences(
    p_tenant_id UUID,
    p_user_id UUID
) RETURNS user_app_preferences AS $$
DECLARE
    v_prefs user_app_preferences;
BEGIN
    SELECT * INTO v_prefs
    FROM user_app_preferences
    WHERE user_id = p_user_id;
    
    IF NOT FOUND THEN
        INSERT INTO user_app_preferences (tenant_id, user_id)
        VALUES (p_tenant_id, p_user_id)
        RETURNING * INTO v_prefs;
    END IF;
    
    RETURN v_prefs;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_consent(
    p_user_id UUID,
    p_consent_type VARCHAR(50)
) RETURNS BOOLEAN AS $$
DECLARE
    v_granted BOOLEAN;
BEGIN
    SELECT granted INTO v_granted
    FROM consent_records
    WHERE user_id = p_user_id AND consent_type = p_consent_type;
    
    RETURN COALESCE(v_granted, false);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_consent(
    p_tenant_id UUID,
    p_user_id UUID,
    p_consent_type VARCHAR(50),
    p_granted BOOLEAN,
    p_ip_address INET DEFAULT NULL,
    p_user_agent TEXT DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO consent_records (
        tenant_id, user_id, consent_type, granted, 
        granted_at, ip_address, user_agent
    ) VALUES (
        p_tenant_id, p_user_id, p_consent_type, p_granted,
        CASE WHEN p_granted THEN NOW() ELSE NULL END,
        p_ip_address, p_user_agent
    )
    ON CONFLICT (tenant_id, user_id, consent_type)
    DO UPDATE SET 
        granted = p_granted,
        granted_at = CASE WHEN p_granted THEN NOW() ELSE consent_records.granted_at END,
        withdrawn_at = CASE WHEN NOT p_granted THEN NOW() ELSE NULL END,
        ip_address = COALESCE(p_ip_address, consent_records.ip_address),
        user_agent = COALESCE(p_user_agent, consent_records.user_agent),
        updated_at = NOW()
    RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

