$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_app_feedback_stats(p_app_id UUID)
RETURNS TABLE (
    total_feedback BIGINT,
    positive_count BIGINT,
    negative_count BIGINT,
    avg_star_rating DECIMAL,
    most_common_type VARCHAR
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*) as total_feedback,
        COUNT(*) FILTER (WHERE rating = 'thumbs_up' OR rating LIKE 'star_%' AND rating >= 'star_4') as positive_count,
        COUNT(*) FILTER (WHERE rating = 'thumbs_down' OR rating LIKE 'star_%' AND rating <= 'star_2') as negative_count,
        AVG(CASE 
            WHEN rating = 'star_1' THEN 1
            WHEN rating = 'star_2' THEN 2
            WHEN rating = 'star_3' THEN 3
            WHEN rating = 'star_4' THEN 4
            WHEN rating = 'star_5' THEN 5
            ELSE NULL
        END) as avg_star_rating,
        (SELECT feedback_type FROM generative_ui_feedback WHERE app_id = p_app_id 
         GROUP BY feedback_type ORDER BY COUNT(*) DESC LIMIT 1) as most_common_type
    FROM generative_ui_feedback
    WHERE app_id = p_app_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_learning_trigger(
    p_tenant_id UUID,
    p_feedback_type VARCHAR(30)
) RETURNS BOOLEAN AS $$
DECLARE
    v_count INTEGER;
    v_threshold INTEGER;
BEGIN
    -- Get threshold from config
    SELECT min_feedback_for_learning INTO v_threshold
    FROM ui_feedback_config
    WHERE tenant_id = p_tenant_id;
    
    v_threshold := COALESCE(v_threshold, 10);
    
    -- Count unprocessed feedback of this type
    SELECT COUNT(*) INTO v_count
    FROM generative_ui_feedback
    WHERE tenant_id = p_tenant_id
      AND feedback_type = p_feedback_type
      AND agi_processed = FALSE;
    
    RETURN v_count >= v_threshold;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_session_activity()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE ui_improvement_sessions
    SET last_activity_at = NOW()
    WHERE id = NEW.session_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_feedback_aggregates()
RETURNS TRIGGER AS $$
DECLARE
    v_period_start DATE;
BEGIN
    v_period_start := DATE_TRUNC('day', NEW.created_at)::DATE;
    
    INSERT INTO ui_feedback_aggregates (
        tenant_id, period_type, period_start, total_feedback,
        positive_feedback, negative_feedback
    ) VALUES (
        NEW.tenant_id, 'daily', v_period_start, 1,
        CASE WHEN NEW.rating IN ('thumbs_up', 'star_4', 'star_5') THEN 1 ELSE 0 END,
        CASE WHEN NEW.rating IN ('thumbs_down', 'star_1', 'star_2') THEN 1 ELSE 0 END
    )
    ON CONFLICT (tenant_id, period_type, period_start)
    DO UPDATE SET
        total_feedback = ui_feedback_aggregates.total_feedback + 1,
        positive_feedback = ui_feedback_aggregates.positive_feedback + 
            CASE WHEN NEW.rating IN ('thumbs_up', 'star_4', 'star_5') THEN 1 ELSE 0 END,
        negative_feedback = ui_feedback_aggregates.negative_feedback + 
            CASE WHEN NEW.rating IN ('thumbs_down', 'star_1', 'star_2') THEN 1 ELSE 0 END,
        computed_at = NOW();
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_multipage_app(
    p_tenant_id UUID,
    p_user_id UUID,
    p_name VARCHAR(200),
    p_app_type VARCHAR(30),
    p_description TEXT DEFAULT NULL,
    p_theme JSONB DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
    v_app_id UUID;
BEGIN
    INSERT INTO generated_multipage_apps (
        tenant_id, user_id, name, app_type, description, theme
    ) VALUES (
        p_tenant_id, p_user_id, p_name, p_app_type, p_description,
        COALESCE(p_theme, '{"mode": "light"}'::jsonb)
    ) RETURNING id INTO v_app_id;
    
    RETURN v_app_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION add_app_page(
    p_app_id UUID,
    p_slug VARCHAR(200),
    p_title VARCHAR(200),
    p_page_type VARCHAR(30),
    p_sections JSONB DEFAULT '[]',
    p_layout JSONB DEFAULT NULL,
    p_show_in_nav BOOLEAN DEFAULT TRUE,
    p_nav_order INTEGER DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
    v_page_id UUID;
    v_nav_order INTEGER;
BEGIN
    -- Get next nav order if not specified
    IF p_nav_order IS NULL THEN
        SELECT COALESCE(MAX(nav_order), 0) + 1 INTO v_nav_order
        FROM app_pages WHERE app_id = p_app_id;
    ELSE
        v_nav_order := p_nav_order;
    END IF;
    
    INSERT INTO app_pages (
        app_id, slug, title, page_type, sections, layout, show_in_nav, nav_order
    ) VALUES (
        p_app_id, p_slug, p_title, p_page_type, p_sections,
        COALESCE(p_layout, '{"type": "centered", "showHeader": true, "showFooter": true}'::jsonb),
        p_show_in_nav, v_nav_order
    ) RETURNING id INTO v_page_id;
    
    -- Set as home page if it's the first page or slug is empty
    IF p_slug = '' OR NOT EXISTS (SELECT 1 FROM app_pages WHERE app_id = p_app_id AND id != v_page_id) THEN
        UPDATE generated_multipage_apps SET home_page_id = v_page_id WHERE id = p_app_id;
    END IF;
    
    RETURN v_page_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_multipage_app(p_app_id UUID)
RETURNS JSONB AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'app', row_to_json(a.*),
        'pages', COALESCE((
            SELECT jsonb_agg(row_to_json(p.*) ORDER BY p.nav_order)
            FROM app_pages p WHERE p.app_id = a.id
        ), '[]'::jsonb)
    ) INTO v_result
    FROM generated_multipage_apps a
    WHERE a.id = p_app_id;
    
    RETURN v_result;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION save_app_version(
    p_app_id UUID,
    p_changed_by UUID,
    p_change_summary TEXT DEFAULT NULL
) RETURNS INTEGER AS $$
DECLARE
    v_version INTEGER;
    v_snapshot JSONB;
BEGIN
    -- Get next version number
    SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
    FROM app_versions WHERE app_id = p_app_id;
    
    -- Get current snapshot
    v_snapshot := get_multipage_app(p_app_id);
    
    -- Save version
    INSERT INTO app_versions (app_id, version, snapshot, change_summary, changed_by)
    VALUES (p_app_id, v_version, v_snapshot, p_change_summary, p_changed_by);
    
    -- Update app version number
    UPDATE generated_multipage_apps SET version = v_version, updated_at = NOW()
    WHERE id = p_app_id;
    
    RETURN v_version;
END;
$$ LANGUAGE plpgsql;

