CREATE OR REPLACE FUNCTION update_ego_affect(
  p_tenant_id UUID,
  p_event_type TEXT,
  p_valence_delta DECIMAL,
  p_arousal_delta DECIMAL
)
RETURNS ego_affect AS $$
DECLARE
  v_affect ego_affect;
BEGIN
  -- Get or create affect
  SELECT * INTO v_affect FROM get_ego_affect(p_tenant_id);
  
  -- Update with deltas, clamping to valid ranges
  UPDATE ego_affect SET
    valence = GREATEST(-1, LEAST(1, valence + p_valence_delta)),
    arousal = GREATEST(0, LEAST(1, arousal + p_arousal_delta)),
    last_trigger_event = p_event_type,
    last_trigger_at = NOW(),
    updated_at = NOW()
  WHERE tenant_id = p_tenant_id
  RETURNING * INTO v_affect;
  
  -- Update dominant emotion
  UPDATE ego_affect SET
    dominant_emotion = CASE
      WHEN valence > 0.3 AND arousal > 0.6 THEN 'excited'
      WHEN valence > 0.3 AND arousal < 0.4 THEN 'content'
      WHEN valence < -0.3 AND arousal > 0.6 THEN 'frustrated'
      WHEN valence < -0.3 AND arousal < 0.4 THEN 'sad'
      WHEN curiosity > 0.7 THEN 'curious'
      WHEN confidence > 0.7 THEN 'confident'
      ELSE 'neutral'
    END
  WHERE tenant_id = p_tenant_id
  RETURNING * INTO v_affect;
  
  RETURN v_affect;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION add_ego_memory(
  p_tenant_id UUID,
  p_memory_type TEXT,
  p_content TEXT,
  p_importance DECIMAL DEFAULT 0.5,
  p_conversation_id UUID DEFAULT NULL,
  p_is_pinned BOOLEAN DEFAULT false
)
RETURNS UUID AS $$
DECLARE
  v_memory_id UUID;
BEGIN
  INSERT INTO ego_working_memory (
    tenant_id, memory_type, content, importance, 
    conversation_id, is_pinned,
    expires_at
  ) VALUES (
    p_tenant_id, p_memory_type, p_content, p_importance,
    p_conversation_id, p_is_pinned,
    CASE WHEN p_is_pinned THEN NULL ELSE NOW() + INTERVAL '24 hours' END
  )
  RETURNING memory_id INTO v_memory_id;
  
  RETURN v_memory_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ego_working_memory(
  p_tenant_id UUID,
  p_limit INTEGER DEFAULT 10
)
RETURNS TABLE (
  memory_type TEXT,
  content TEXT,
  importance DECIMAL,
  created_at TIMESTAMPTZ
) AS $$
BEGIN
  RETURN QUERY
  SELECT m.memory_type, m.content, m.importance, m.created_at
  FROM ego_working_memory m
  WHERE m.tenant_id = p_tenant_id
    AND (m.expires_at > NOW() OR m.is_pinned = true)
  ORDER BY m.is_pinned DESC, m.importance DESC, m.created_at DESC
  LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_ego_memories()
RETURNS INTEGER AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM ego_working_memory
  WHERE expires_at < NOW() AND is_pinned = false;
  
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_tenant_concurrency(p_tenant_id TEXT)
RETURNS TABLE (
    total_active INTEGER,
    user_counts JSONB
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*)::INTEGER as total_active,
        jsonb_object_agg(user_id, user_count) as user_counts
    FROM (
        SELECT user_id, COUNT(*) as user_count
        FROM library_executions
        WHERE tenant_id = p_tenant_id AND status = 'running'
        GROUP BY user_id
    ) sub;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Check if execution can start
CREATE OR REPLACE FUNCTION can_start_execution(
    p_tenant_id TEXT,
    p_user_id TEXT
)
RETURNS TABLE (
    allowed BOOLEAN,
    reason TEXT
) AS $$
DECLARE
    v_config library_execution_config%ROWTYPE;
    v_tenant_active INTEGER;
    v_user_active INTEGER;
BEGIN
    -- Get config
    SELECT * INTO v_config FROM library_execution_config WHERE tenant_id = p_tenant_id;
    
    IF v_config IS NULL THEN
        RETURN QUERY SELECT true, NULL::TEXT;
        RETURN;
    END IF;
    
    IF NOT v_config.execution_enabled THEN
        RETURN QUERY SELECT false, 'Library execution is disabled';
        RETURN;
    END IF;
    
    -- Count active executions
    SELECT COUNT(*) INTO v_tenant_active
    FROM library_executions
    WHERE tenant_id = p_tenant_id AND status = 'running';
    
    IF v_tenant_active >= v_config.max_concurrent_executions THEN
        RETURN QUERY SELECT false, format('Tenant limit reached (%s/%s)', v_tenant_active, v_config.max_concurrent_executions);
        RETURN;
    END IF;
    
    SELECT COUNT(*) INTO v_user_active
    FROM library_executions
    WHERE tenant_id = p_tenant_id AND user_id = p_user_id AND status = 'running';
    
    IF v_user_active >= v_config.max_concurrent_per_user THEN
        RETURN QUERY SELECT false, format('User limit reached (%s/%s)', v_user_active, v_config.max_concurrent_per_user);
        RETURN;
    END IF;
    
    RETURN QUERY SELECT true, NULL::TEXT;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Aggregate hourly stats
CREATE OR REPLACE FUNCTION aggregate_hourly_execution_stats()
RETURNS void AS $$
BEGIN
    INSERT INTO library_execution_aggregates (
        tenant_id, library_id, period_start, period_type,
        execution_count, successful_count, failed_count,
        total_duration_ms, total_credits, avg_duration_ms
    )
    SELECT 
        tenant_id,
        library_id,
        date_trunc('hour', started_at) as period_start,
        'hourly',
        COUNT(*),
        COUNT(*) FILTER (WHERE status = 'completed'),
        COUNT(*) FILTER (WHERE status = 'failed'),
        COALESCE(SUM(duration_ms), 0),
        COALESCE(SUM(credits_used), 0),
        AVG(duration_ms)::INTEGER
    FROM library_executions
    WHERE started_at >= NOW() - INTERVAL '2 hours'
      AND started_at < date_trunc('hour', NOW())
      AND status IN ('completed', 'failed')
    GROUP BY tenant_id, library_id, date_trunc('hour', started_at)
    ON CONFLICT (tenant_id, library_id, period_start, period_type) DO UPDATE SET
        execution_count = EXCLUDED.execution_count,
        successful_count = EXCLUDED.successful_count,
        failed_count = EXCLUDED.failed_count,
        total_duration_ms = EXCLUDED.total_duration_ms,
        total_credits = EXCLUDED.total_credits,
        avg_duration_ms = EXCLUDED.avg_duration_ms;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION get_tenant_concurrency(TEXT) IS 'Get current execution concurrency for a tenant';
COMMENT ON FUNCTION can_start_execution(TEXT, TEXT) IS 'Check if a new execution can be started';
COMMENT ON FUNCTION aggregate_hourly_execution_stats() IS 'Aggregate execution statistics hourly';

