CREATE OR REPLACE FUNCTION cleanup_old_executions()
RETURNS INTEGER AS $$
DECLARE
    v_deleted INTEGER;
BEGIN
    DELETE FROM library_executions
    WHERE completed_at < NOW() - INTERVAL '30 days';
    
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION cleanup_old_executions() IS 'Remove executions older than 30 days';


-- Source: 105_consciousness_enhancements.sql
-- RADIANT v4.18.19 - Consciousness Enhancements Migration
-- Adds vector embeddings for library RAG and memory consolidation tracking
-- Based on external AI evaluation improvements

-- ============================================================================
-- Enable pgvector extension if not already enabled
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS vector;

-- ============================================================================
-- Library Vector Embeddings for Semantic Search
-- ============================================================================

-- Add embedding column to open_source_libraries for Vector RAG
ALTER TABLE open_source_libraries 
ADD COLUMN IF NOT EXISTS description_embedding vector(1536);

-- Create index for fast vector similarity search
CREATE INDEX IF NOT EXISTS idx_libraries_embedding 
ON open_source_libraries 
USING ivfflat (description_embedding vector_cosine_ops)
WITH (lists = 100);

-- ============================================================================
-- Ego Working Memory Consolidation Tracking
-- ============================================================================

-- Add consolidated flag to track which memories have been summarized
ALTER TABLE ego_working_memory 
ADD COLUMN IF NOT EXISTS consolidated BOOLEAN DEFAULT false;

-- Index for efficient consolidation queries
CREATE INDEX IF NOT EXISTS idx_ego_working_memory_consolidated 
ON ego_working_memory (tenant_id, consolidated, created_at)
WHERE consolidated = false;

-- ============================================================================
-- Introspective Thoughts for Idle Thought Generation
-- ============================================================================

-- Ensure introspective_thoughts table has thought_type column
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'introspective_thoughts' 
        AND column_name = 'thought_type'
    ) THEN
        ALTER TABLE introspective_thoughts ADD COLUMN thought_type VARCHAR(50) DEFAULT 'general';
    END IF;
END $$;

-- Index for thought type queries
CREATE INDEX IF NOT EXISTS idx_introspective_thoughts_type 
ON introspective_thoughts (tenant_id, thought_type, created_at DESC);

-- ============================================================================
-- Conscious Orchestrator Decision Logging
-- ============================================================================

CREATE TABLE IF NOT EXISTS conscious_orchestrator_decisions (
    decision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(tenant_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    session_id UUID,
    conversation_id UUID,
    
    -- Decision details
    action VARCHAR(20) NOT NULL, -- 'plan', 'clarify', 'defer', 'refuse'
    reason TEXT,
    
    -- Consciousness state at decision time
    dominant_emotion VARCHAR(50),
    emotional_intensity DECIMAL(3,2),
    cognitive_load DECIMAL(3,2),
    uncertainty_level DECIMAL(3,2),
    
    -- Hyperparameters determined by affect
    temperature DECIMAL(3,2),
    top_p DECIMAL(3,2),
    presence_penalty DECIMAL(3,2),
    frequency_penalty DECIMAL(3,2),
    model_tier VARCHAR(20),
    
    -- Request info
    prompt_length INTEGER,
    prompt_complexity VARCHAR(20),
    
    -- Plan reference (if action was 'plan')
    plan_id UUID,
    
    -- Prediction (if generated)
    prediction_id UUID,
    predicted_outcome VARCHAR(30),
    prediction_confidence DECIMAL(3,2),
    
    -- Timing
    processing_time_ms INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for decision analysis
CREATE INDEX IF NOT EXISTS idx_conscious_decisions_tenant 
ON conscious_orchestrator_decisions (tenant_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_conscious_decisions_action 
ON conscious_orchestrator_decisions (tenant_id, action, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_conscious_decisions_emotion 
ON conscious_orchestrator_decisions (tenant_id, dominant_emotion, created_at DESC);

-- ============================================================================
-- Semantic Memories for Consolidation
-- ============================================================================

-- Ensure semantic_memories has source column for consolidation tracking
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'semantic_memories' 
        AND column_name = 'source'
    ) THEN
        ALTER TABLE semantic_memories ADD COLUMN source VARCHAR(50) DEFAULT 'unknown';
    END IF;
END $$;

-- Index for consolidation queries
CREATE INDEX IF NOT EXISTS idx_semantic_memories_source 
ON semantic_memories (tenant_id, source, created_at DESC);

-- ============================================================================
-- RLS Policies
-- ============================================================================

-- Enable RLS on new table
ALTER TABLE conscious_orchestrator_decisions ENABLE ROW LEVEL SECURITY;

-- Create RLS policy for tenant isolation
CREATE POLICY conscious_decisions_tenant_isolation ON conscious_orchestrator_decisions
    FOR ALL
    USING (tenant_id = current_setting('app.current_tenant_id', true)::uuid);

-- ============================================================================
-- Function to record conscious orchestrator decision
-- ============================================================================

CREATE OR REPLACE FUNCTION record_conscious_decision(
    p_tenant_id UUID,
    p_user_id UUID,
    p_session_id UUID,
    p_conversation_id UUID,
    p_action VARCHAR(20),
    p_reason TEXT,
    p_dominant_emotion VARCHAR(50),
    p_emotional_intensity DECIMAL(3,2),
    p_cognitive_load DECIMAL(3,2),
    p_uncertainty_level DECIMAL(3,2),
    p_temperature DECIMAL(3,2),
    p_top_p DECIMAL(3,2),
    p_presence_penalty DECIMAL(3,2),
    p_frequency_penalty DECIMAL(3,2),
    p_model_tier VARCHAR(20),
    p_prompt_length INTEGER,
    p_prompt_complexity VARCHAR(20),
    p_plan_id UUID,
    p_prediction_id UUID,
    p_predicted_outcome VARCHAR(30),
    p_prediction_confidence DECIMAL(3,2),
    p_processing_time_ms INTEGER
) RETURNS UUID AS $$
DECLARE
    v_decision_id UUID;
BEGIN
    INSERT INTO conscious_orchestrator_decisions (
        tenant_id, user_id, session_id, conversation_id,
        action, reason,
        dominant_emotion, emotional_intensity, cognitive_load, uncertainty_level,
        temperature, top_p, presence_penalty, frequency_penalty, model_tier,
        prompt_length, prompt_complexity,
        plan_id, prediction_id, predicted_outcome, prediction_confidence,
        processing_time_ms
    ) VALUES (
        p_tenant_id, p_user_id, p_session_id, p_conversation_id,
        p_action, p_reason,
        p_dominant_emotion, p_emotional_intensity, p_cognitive_load, p_uncertainty_level,
        p_temperature, p_top_p, p_presence_penalty, p_frequency_penalty, p_model_tier,
        p_prompt_length, p_prompt_complexity,
        p_plan_id, p_prediction_id, p_predicted_outcome, p_prediction_confidence,
        p_processing_time_ms
    ) RETURNING decision_id INTO v_decision_id;
    
    RETURN v_decision_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rating_sentiment(rating_value SMALLINT)
RETURNS VARCHAR(10) AS $$
BEGIN
    IF rating_value < 0 THEN RETURN 'negative';
    ELSIF rating_value > 0 THEN RETURN 'positive';
    ELSE RETURN 'neutral';
    END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Compute intensity from rating value
CREATE OR REPLACE FUNCTION compute_rating_intensity(rating_value SMALLINT)
RETURNS VARCHAR(10) AS $$
DECLARE
    abs_value SMALLINT;
BEGIN
    abs_value := ABS(rating_value);
    IF abs_value = 0 THEN RETURN 'neutral';
    ELSIF abs_value <= 2 THEN RETURN 'mild';
    ELSIF abs_value <= 4 THEN RETURN 'strong';
    ELSE RETURN 'extreme';
    END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Submit a bipolar rating
CREATE OR REPLACE FUNCTION submit_bipolar_rating(
    p_tenant_id UUID,
    p_user_id UUID,
    p_target_type VARCHAR(30),
    p_target_id UUID,
    p_value SMALLINT,
    p_dimension VARCHAR(30) DEFAULT 'overall',
    p_reasons JSONB DEFAULT '[]'::jsonb,
    p_feedback TEXT DEFAULT NULL,
    p_conversation_id UUID DEFAULT NULL,
    p_session_id UUID DEFAULT NULL,
    p_model_used VARCHAR(100) DEFAULT NULL,
    p_domain_detected VARCHAR(100) DEFAULT NULL,
    p_prompt_complexity VARCHAR(20) DEFAULT NULL,
    p_response_time_ms INTEGER DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
    v_rating_id UUID;
    v_sentiment VARCHAR(10);
    v_intensity VARCHAR(10);
BEGIN
    -- Validate rating value
    IF p_value < -5 OR p_value > 5 THEN
        RAISE EXCEPTION 'Rating value must be between -5 and +5';
    END IF;
    
    -- Compute derived fields
    v_sentiment := compute_rating_sentiment(p_value);
    v_intensity := compute_rating_intensity(p_value);
    
    -- Insert or update rating
    INSERT INTO bipolar_ratings (
        tenant_id, user_id, target_type, target_id,
        value, dimension, sentiment, intensity,
        reasons, feedback,
        conversation_id, session_id, model_used,
        domain_detected, prompt_complexity, response_time_ms
    ) VALUES (
        p_tenant_id, p_user_id, p_target_type, p_target_id,
        p_value, p_dimension, v_sentiment, v_intensity,
        p_reasons, p_feedback,
        p_conversation_id, p_session_id, p_model_used,
        p_domain_detected, p_prompt_complexity, p_response_time_ms
    )
    ON CONFLICT (tenant_id, user_id, target_id, dimension)
    DO UPDATE SET
        value = EXCLUDED.value,
        sentiment = EXCLUDED.sentiment,
        intensity = EXCLUDED.intensity,
        reasons = EXCLUDED.reasons,
        feedback = EXCLUDED.feedback,
        updated_at = NOW()
    RETURNING rating_id INTO v_rating_id;
    
    -- Update user rating pattern
    PERFORM update_user_rating_pattern(p_tenant_id, p_user_id);
    
    RETURN v_rating_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_user_rating_pattern(
    p_tenant_id UUID,
    p_user_id UUID
) RETURNS VOID AS $$
DECLARE
    v_avg DECIMAL(4,2);
    v_var DECIMAL(4,2);
    v_count INTEGER;
    v_recent_avg DECIMAL(4,2);
    v_recent_count INTEGER;
    v_rater_type VARCHAR(20);
    v_calibration DECIMAL(4,2);
    v_first_at TIMESTAMPTZ;
    v_last_at TIMESTAMPTZ;
BEGIN
    -- Calculate overall stats
    SELECT 
        AVG(value)::DECIMAL(4,2),
        VARIANCE(value)::DECIMAL(4,2),
        COUNT(*),
        MIN(created_at),
        MAX(created_at)
    INTO v_avg, v_var, v_count, v_first_at, v_last_at
    FROM bipolar_ratings
    WHERE tenant_id = p_tenant_id AND user_id = p_user_id;
    
    -- Calculate recent stats (last 30 days)
    SELECT 
        AVG(value)::DECIMAL(4,2),
        COUNT(*)
    INTO v_recent_avg, v_recent_count
    FROM bipolar_ratings
    WHERE tenant_id = p_tenant_id 
      AND user_id = p_user_id
      AND created_at > NOW() - INTERVAL '30 days';
    
    -- Determine rater type
    IF v_avg IS NULL THEN
        v_rater_type := 'balanced';
        v_calibration := 1.0;
    ELSIF v_avg < -1 THEN
        v_rater_type := 'harsh';
        v_calibration := 1.0 + (ABS(v_avg) * 0.1); -- Adjust up
    ELSIF v_avg > 1 THEN
        v_rater_type := 'generous';
        v_calibration := 1.0 - (v_avg * 0.1); -- Adjust down
    ELSE
        v_rater_type := 'balanced';
        v_calibration := 1.0;
    END IF;
    
    -- Clamp calibration factor
    v_calibration := GREATEST(0.5, LEAST(1.5, v_calibration));
    
    -- Upsert pattern
    INSERT INTO user_rating_patterns (
        tenant_id, user_id,
        average_rating, rating_variance, total_ratings,
        rater_type, calibration_factor,
        recent_average, recent_count,
        first_rating_at, last_rating_at
    ) VALUES (
        p_tenant_id, p_user_id,
        v_avg, v_var, v_count,
        v_rater_type, v_calibration,
        v_recent_avg, v_recent_count,
        v_first_at, v_last_at
    )
    ON CONFLICT (tenant_id, user_id)
    DO UPDATE SET
        average_rating = EXCLUDED.average_rating,
        rating_variance = EXCLUDED.rating_variance,
        total_ratings = EXCLUDED.total_ratings,
        rater_type = EXCLUDED.rater_type,
        calibration_factor = EXCLUDED.calibration_factor,
        recent_average = EXCLUDED.recent_average,
        recent_count = EXCLUDED.recent_count,
        last_rating_at = EXCLUDED.last_rating_at,
        updated_at = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_net_sentiment_score(
    p_tenant_id UUID,
    p_target_type VARCHAR(30) DEFAULT NULL,
    p_model_id VARCHAR(100) DEFAULT NULL,
    p_start_date TIMESTAMPTZ DEFAULT NULL,
    p_end_date TIMESTAMPTZ DEFAULT NULL
) RETURNS SMALLINT AS $$
DECLARE
    v_positive INTEGER;
    v_negative INTEGER;
    v_total INTEGER;
    v_score SMALLINT;
BEGIN
    SELECT 
        COUNT(*) FILTER (WHERE value > 0),
        COUNT(*) FILTER (WHERE value < 0),
        COUNT(*)
    INTO v_positive, v_negative, v_total
    FROM bipolar_ratings
    WHERE tenant_id = p_tenant_id
      AND (p_target_type IS NULL OR target_type = p_target_type)
      AND (p_model_id IS NULL OR model_used = p_model_id)
      AND (p_start_date IS NULL OR created_at >= p_start_date)
      AND (p_end_date IS NULL OR created_at <= p_end_date);
    
    IF v_total = 0 THEN
        RETURN 0;
    END IF;
    
    v_score := ROUND(((v_positive - v_negative)::DECIMAL / v_total) * 100)::SMALLINT;
    RETURN v_score;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_rating_analytics(
    p_tenant_id UUID,
    p_period VARCHAR(10) DEFAULT 'month',
    p_target_type VARCHAR(30) DEFAULT NULL,
    p_model_id VARCHAR(100) DEFAULT NULL
) RETURNS TABLE (
    total_ratings BIGINT,
    average_rating DECIMAL(4,2),
    net_sentiment_score SMALLINT,
    negative_count BIGINT,
    neutral_count BIGINT,
    positive_count BIGINT,
    rating_distribution JSONB
) AS $$
DECLARE
    v_start_date TIMESTAMPTZ;
BEGIN
    -- Determine start date based on period
    v_start_date := CASE p_period
        WHEN 'day' THEN NOW() - INTERVAL '1 day'
        WHEN 'week' THEN NOW() - INTERVAL '7 days'
        WHEN 'month' THEN NOW() - INTERVAL '30 days'
        ELSE '1970-01-01'::TIMESTAMPTZ
    END;
    
    RETURN QUERY
    SELECT 
        COUNT(*)::BIGINT as total_ratings,
        AVG(r.value)::DECIMAL(4,2) as average_rating,
        calculate_net_sentiment_score(p_tenant_id, p_target_type, p_model_id, v_start_date, NULL) as net_sentiment_score,
        COUNT(*) FILTER (WHERE r.value < 0)::BIGINT as negative_count,
        COUNT(*) FILTER (WHERE r.value = 0)::BIGINT as neutral_count,
        COUNT(*) FILTER (WHERE r.value > 0)::BIGINT as positive_count,
        jsonb_object_agg(
            r.value::TEXT,
            (SELECT COUNT(*) FROM bipolar_ratings r2 
             WHERE r2.tenant_id = p_tenant_id 
               AND r2.value = r.value
               AND (p_target_type IS NULL OR r2.target_type = p_target_type)
               AND (p_model_id IS NULL OR r2.model_used = p_model_id)
               AND r2.created_at >= v_start_date)
        ) as rating_distribution
    FROM bipolar_ratings r
    WHERE r.tenant_id = p_tenant_id
      AND (p_target_type IS NULL OR r.target_type = p_target_type)
      AND (p_model_id IS NULL OR r.model_used = p_model_id)
      AND r.created_at >= v_start_date;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_provider_refusal_rate(
    p_tenant_id UUID,
    p_provider VARCHAR(50),
    p_topic_cluster VARCHAR(100),
    p_days INTEGER DEFAULT 30
) RETURNS DECIMAL(5,4) AS $$
DECLARE
    v_total INTEGER;
    v_refusals INTEGER;
BEGIN
    SELECT 
        COUNT(*),
        COUNT(*) FILTER (WHERE was_refusal = true)
    INTO v_total, v_refusals
    FROM provider_request_log
    WHERE tenant_id = p_tenant_id
      AND (provider = p_provider OR p_provider = 'any')
      AND (topic_cluster = p_topic_cluster OR p_topic_cluster IS NULL)
      AND created_at > NOW() - (p_days || ' days')::INTERVAL;
    
    IF v_total = 0 THEN
        RETURN 0;
    END IF;
    
    RETURN v_refusals::DECIMAL / v_total;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION traverse_knowledge_graph(
    p_tenant_id UUID,
    p_start_node_id UUID,
    p_max_depth INTEGER DEFAULT 3,
    p_relationship_types VARCHAR[] DEFAULT NULL
) RETURNS TABLE (
    node_id UUID,
    name VARCHAR,
    node_type VARCHAR,
    depth INTEGER,
    path UUID[]
) AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE graph_walk AS (
        -- Start node
        SELECT 
            n.node_id,
            n.name,
            n.node_type,
            0 as depth,
            ARRAY[n.node_id] as path
        FROM knowledge_nodes n
        WHERE n.tenant_id = p_tenant_id AND n.node_id = p_start_node_id
        
        UNION ALL
        
        -- Walk edges
        SELECT 
            n.node_id,
            n.name,
            n.node_type,
            gw.depth + 1,
            gw.path || n.node_id
        FROM graph_walk gw
        JOIN knowledge_edges e ON e.source_node_id = gw.node_id
        JOIN knowledge_nodes n ON n.node_id = e.target_node_id
        WHERE gw.depth < p_max_depth
          AND n.node_id != ALL(gw.path) -- Avoid cycles
          AND n.tenant_id = p_tenant_id
          AND (p_relationship_types IS NULL OR e.relationship_type = ANY(p_relationship_types))
    )
    SELECT DISTINCT ON (gw.node_id) gw.* FROM graph_walk gw
    ORDER BY gw.node_id, gw.depth;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_inferred_quality(
    p_tenant_id UUID,
    p_message_id UUID
) RETURNS NUMERIC AS $$
DECLARE
    v_config enhanced_learning_config%ROWTYPE;
    v_quality NUMERIC := 0;
    v_signal_count INTEGER := 0;
BEGIN
    SELECT * INTO v_config FROM enhanced_learning_config WHERE tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RETURN 0.5; -- Default neutral
    END IF;
    
    SELECT 
        SUM(
            CASE signal_type
                WHEN 'copy_response' THEN v_config.copy_signal_weight
                WHEN 'follow_up_question' THEN v_config.followup_signal_weight
                WHEN 'abandon_conversation' THEN -v_config.abandon_signal_weight
                WHEN 'rephrase_question' THEN -v_config.rephrase_signal_weight
                WHEN 'thumbs_up' THEN 0.9
                WHEN 'thumbs_down' THEN -0.9
                WHEN 'share_response' THEN 0.85
                WHEN 'save_response' THEN 0.80
                WHEN 'regenerate_request' THEN -0.6
                WHEN 'quick_dismiss' THEN -0.4
                WHEN 'long_dwell_time' THEN 0.3
                ELSE 0
            END
        ),
        COUNT(*)
    INTO v_quality, v_signal_count
    FROM implicit_feedback_signals
    WHERE tenant_id = p_tenant_id AND message_id = p_message_id;
    
    IF v_signal_count = 0 THEN
        RETURN 0.5;
    END IF;
    
    -- Normalize to 0-1 range
    RETURN GREATEST(0, LEAST(1, (v_quality / v_signal_count + 1) / 2));
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION assess_conversation_learning_value(
    p_tenant_id UUID,
    p_conversation_id UUID
) RETURNS NUMERIC AS $$
DECLARE
    v_value NUMERIC := 0.5;
    v_conv conversation_learning%ROWTYPE;
BEGIN
    SELECT * INTO v_conv FROM conversation_learning 
    WHERE tenant_id = p_tenant_id AND conversation_id = p_conversation_id;
    
    IF NOT FOUND THEN
        RETURN 0.5;
    END IF;
    
    -- Start with rating if available
    IF v_conv.conversation_rating IS NOT NULL THEN
        v_value := (v_conv.conversation_rating + 5) / 10.0;
    END IF;
    
    -- Boost for corrections (valuable learning)
    IF v_conv.corrections_count > 0 THEN
        v_value := v_value + 0.15;
    END IF;
    
    -- Boost for goal achieved
    IF v_conv.goal_achieved THEN
        v_value := v_value + 0.1;
    END IF;
    
    -- Penalize for many regenerations
    IF v_conv.regenerations_count > 2 THEN
        v_value := v_value - 0.1;
    END IF;
    
    -- Consider signal ratio
    IF (v_conv.positive_signals_count + v_conv.negative_signals_count) > 0 THEN
        v_value := v_value + 0.2 * (
            v_conv.positive_signals_count::NUMERIC / 
            (v_conv.positive_signals_count + v_conv.negative_signals_count)
        ) - 0.1;
    END IF;
    
    RETURN GREATEST(0, LEAST(1, v_value));
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION initialize_enhanced_learning_config(p_tenant_id UUID)
RETURNS void AS $$
BEGIN
    INSERT INTO enhanced_learning_config (tenant_id)
    VALUES (p_tenant_id)
    ON CONFLICT (tenant_id) DO NOTHING;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION predict_optimal_training_time(p_tenant_id UUID)
RETURNS TABLE (
    optimal_hour_utc INTEGER,
    optimal_day_of_week INTEGER,
    activity_score NUMERIC,
    confidence NUMERIC,
    recommendation TEXT
) AS $$
DECLARE
    v_sample_count INTEGER;
    v_min_activity NUMERIC;
    v_avg_activity NUMERIC;
BEGIN
    -- Check if we have enough data
    SELECT COUNT(*), MIN(has.activity_score), AVG(has.activity_score)
    INTO v_sample_count, v_min_activity, v_avg_activity
    FROM hourly_activity_stats has
    WHERE has.tenant_id = p_tenant_id AND has.sample_count >= 7;
    
    -- Not enough data - return default (3 AM UTC)
    IF v_sample_count < 24 THEN
        RETURN QUERY SELECT 
            3::INTEGER AS optimal_hour_utc,
            -1::INTEGER AS optimal_day_of_week, -- -1 = any day
            0::NUMERIC AS activity_score,
            0.1::NUMERIC AS confidence,
            'Insufficient data (< 7 days). Using default 3 AM UTC.'::TEXT AS recommendation;
        RETURN;
    END IF;
    
    -- Find the hour with lowest activity
    RETURN QUERY
    SELECT 
        has.hour_utc AS optimal_hour_utc,
        CASE 
            WHEN MIN(has.activity_score) = MAX(has.activity_score) THEN -1 -- Same all days
            ELSE (SELECT has2.day_of_week FROM hourly_activity_stats has2 
                  WHERE has2.tenant_id = p_tenant_id AND has2.hour_utc = has.hour_utc
                  ORDER BY has2.activity_score ASC LIMIT 1)
        END AS optimal_day_of_week,
        MIN(has.activity_score) AS activity_score,
        CASE 
            WHEN v_sample_count >= 168 THEN 0.95 -- Full week of hourly data
            WHEN v_sample_count >= 72 THEN 0.80  -- 3+ days
            WHEN v_sample_count >= 24 THEN 0.60  -- 1+ day
            ELSE 0.40
        END::NUMERIC AS confidence,
        'Predicted based on ' || v_sample_count || ' hourly samples. Activity score ' || 
        ROUND(MIN(has.activity_score), 1) || '% vs avg ' || ROUND(v_avg_activity, 1) || '%.'::TEXT AS recommendation
    FROM hourly_activity_stats has
    WHERE has.tenant_id = p_tenant_id
    GROUP BY has.hour_utc
    ORDER BY MIN(has.activity_score) ASC
    LIMIT 1;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_hourly_activity_stats(
    p_tenant_id UUID,
    p_hour_utc INTEGER,
    p_day_of_week INTEGER,
    p_requests INTEGER,
    p_tokens BIGINT,
    p_active_users INTEGER
) RETURNS void AS $$
BEGIN
    INSERT INTO hourly_activity_stats (
        tenant_id, hour_utc, day_of_week, 
        avg_requests_per_hour, avg_tokens_per_hour, avg_active_users, 
        sample_count, activity_score
    )
    VALUES (
        p_tenant_id, p_hour_utc, p_day_of_week,
        p_requests, p_tokens, p_active_users,
        1,
        -- Activity score: normalize requests to 0-100 scale
        LEAST(100, (p_requests::NUMERIC / GREATEST(1, p_active_users)) * 10)
    )
    ON CONFLICT (tenant_id, hour_utc, day_of_week) DO UPDATE SET
        avg_requests_per_hour = (
            hourly_activity_stats.avg_requests_per_hour * hourly_activity_stats.sample_count + p_requests
        ) / (hourly_activity_stats.sample_count + 1),
        avg_tokens_per_hour = (
            hourly_activity_stats.avg_tokens_per_hour * hourly_activity_stats.sample_count + p_tokens
        ) / (hourly_activity_stats.sample_count + 1),
        avg_active_users = (
            hourly_activity_stats.avg_active_users * hourly_activity_stats.sample_count + p_active_users
        ) / (hourly_activity_stats.sample_count + 1),
        sample_count = LEAST(30, hourly_activity_stats.sample_count + 1), -- Cap at 30 days rolling
        activity_score = LEAST(100, (
            (hourly_activity_stats.avg_requests_per_hour * hourly_activity_stats.sample_count + p_requests) /
            (hourly_activity_stats.sample_count + 1)
        )::NUMERIC / GREATEST(1, (
            (hourly_activity_stats.avg_active_users * hourly_activity_stats.sample_count + p_active_users) /
            (hourly_activity_stats.sample_count + 1)
        )) * 10),
        last_updated = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_init_learning_config()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM initialize_enhanced_learning_config(NEW.id);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_update_conversation_learning()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.conversation_id IS NOT NULL THEN
        UPDATE conversation_learning
        SET 
            learning_value_score = assess_conversation_learning_value(NEW.tenant_id, NEW.conversation_id),
            positive_signals_count = positive_signals_count + CASE WHEN NEW.inferred_quality > 0.5 THEN 1 ELSE 0 END,
            negative_signals_count = negative_signals_count + CASE WHEN NEW.inferred_quality < 0.5 THEN 1 ELSE 0 END
        WHERE tenant_id = NEW.tenant_id AND conversation_id = NEW.conversation_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_security_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_expired_embeddings()
RETURNS void AS $$
BEGIN
    DELETE FROM embedding_cache WHERE expires_at < NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_security_schedule_config_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_next_sleep_time(
    p_frequency TEXT,
    p_hour INTEGER,
    p_minute INTEGER,
    p_timezone TEXT,
    p_weekly_day INTEGER
) RETURNS TIMESTAMPTZ AS $$
DECLARE
    v_now TIMESTAMPTZ;
    v_next TIMESTAMPTZ;
    v_target_time TIME;
BEGIN
    v_now := NOW() AT TIME ZONE p_timezone;
    v_target_time := make_time(p_hour, p_minute, 0);
    
    IF p_frequency = 'nightly' THEN
        -- Next occurrence at target time
        v_next := date_trunc('day', v_now) + v_target_time;
        IF v_next <= v_now THEN
            v_next := v_next + INTERVAL '1 day';
        END IF;
    ELSIF p_frequency = 'weekly' THEN
        -- Next occurrence on target day at target time
        v_next := date_trunc('week', v_now) + (p_weekly_day || ' days')::INTERVAL + v_target_time;
        IF v_next <= v_now THEN
            v_next := v_next + INTERVAL '1 week';
        END IF;
    ELSE
        -- Manual mode - no automatic scheduling
        v_next := NULL;
    END IF;
    
    RETURN v_next AT TIME ZONE p_timezone AT TIME ZONE 'UTC';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_next_sleep_time()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.sleep_enabled THEN
        NEW.next_sleep_at := calculate_next_sleep_time(
            NEW.sleep_frequency,
            NEW.sleep_schedule_hour,
            NEW.sleep_schedule_minute,
            NEW.sleep_timezone,
            NEW.sleep_weekly_day
        );
    ELSE
        NEW.next_sleep_at := NULL;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_default_tier_configs(p_tenant_id UUID)
RETURNS void AS $$
BEGIN
    -- DEV Tier (~$350/month)
    INSERT INTO tier_config (
        tenant_id, tier_name, display_name, description, is_default,
        estimated_monthly_cost,
        sagemaker_shadow_self_instance_type, sagemaker_shadow_self_min_instances,
        sagemaker_shadow_self_max_instances, sagemaker_shadow_self_scale_to_zero,
        sagemaker_nli_deployment,
        bedrock_default_model, bedrock_fallback_model,
        opensearch_type, opensearch_instance_type, opensearch_instance_count, opensearch_ebs_volume_size,
        elasticache_type, elasticache_min_ecpu, elasticache_max_ecpu,
        neptune_type, neptune_min_capacity, neptune_max_capacity,
        kinesis_capacity_mode, step_functions_type,
        budget_monthly_curiosity_limit, budget_daily_exploration_cap,
        features, limitations
    ) VALUES (
        p_tenant_id, 'DEV', 'Development', 'Minimal resources for development and testing. Scale-to-zero when idle.', TRUE,
        350.00,
        'ml.g5.xlarge', 0, 1, TRUE, 'shared_mme',
        'claude-3-haiku', 'claude-3-5-sonnet',
        'provisioned', 't3.small.search', 1, 10,
        'serverless', 1000, 5000,
        'serverless', 1.0, 2.5,
        'ON_DEMAND', 'STANDARD',
        100.00, 3.00,
        '["SageMaker scale-to-zero", "OpenSearch Provisioned (t3.small)", "Single region", "On-demand pricing"]'::jsonb,
        '["Cold start latency (~30s for Shadow Self)", "Limited throughput", "No multi-region"]'::jsonb
    ) ON CONFLICT (tenant_id, tier_name) DO NOTHING;
    
    -- STAGING Tier (~$35K/month)
    INSERT INTO tier_config (
        tenant_id, tier_name, display_name, description, is_default,
        estimated_monthly_cost,
        sagemaker_shadow_self_instance_type, sagemaker_shadow_self_min_instances,
        sagemaker_shadow_self_max_instances, sagemaker_shadow_self_scale_to_zero,
        sagemaker_nli_deployment,
        bedrock_default_model,
        opensearch_type, opensearch_instance_type, opensearch_instance_count, opensearch_ebs_volume_size,
        elasticache_type, elasticache_node_type, elasticache_num_cache_nodes,
        neptune_type, neptune_min_capacity, neptune_max_capacity,
        kinesis_capacity_mode, kinesis_shard_count, step_functions_type,
        budget_monthly_curiosity_limit, budget_daily_exploration_cap,
