    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_regulatory_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION run_audit_check(p_check_code VARCHAR)
RETURNS TABLE (
    check_code VARCHAR,
    check_name VARCHAR,
    passed BOOLEAN,
    details TEXT
) AS $$
DECLARE
    v_check system_audit_checks%ROWTYPE;
    v_result BOOLEAN;
BEGIN
    SELECT * INTO v_check FROM system_audit_checks WHERE system_audit_checks.check_code = p_check_code AND is_active = true;
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT p_check_code, 'Check not found'::VARCHAR, false, 'Audit check not found in registry'::TEXT;
        RETURN;
    END IF;
    
    IF v_check.check_query IS NULL THEN
        RETURN QUERY SELECT v_check.check_code, v_check.check_name, true, 'Manual check - assumed passed'::TEXT;
        RETURN;
    END IF;
    
    BEGIN
        EXECUTE v_check.check_query INTO v_result;
        RETURN QUERY SELECT v_check.check_code, v_check.check_name, COALESCE(v_result, false), 
            CASE WHEN COALESCE(v_result, false) THEN 'Check passed' ELSE v_check.remediation_steps END;
    EXCEPTION WHEN OTHERS THEN
        RETURN QUERY SELECT v_check.check_code, v_check.check_name, false, 'Error executing check: ' || SQLERRM;
    END;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION run_framework_audit(p_framework VARCHAR)
RETURNS TABLE (
    check_code VARCHAR,
    check_name VARCHAR,
    category VARCHAR,
    severity VARCHAR,
    is_required BOOLEAN,
    passed BOOLEAN,
    details TEXT
) AS $$
DECLARE
    v_check system_audit_checks%ROWTYPE;
    v_result BOOLEAN;
    v_details TEXT;
BEGIN
    FOR v_check IN 
        SELECT * FROM system_audit_checks 
        WHERE framework = p_framework AND is_active = true 
        ORDER BY severity DESC, check_code
    LOOP
        IF v_check.check_query IS NULL THEN
            v_result := true;
            v_details := 'Manual check - requires verification';
        ELSE
            BEGIN
                EXECUTE v_check.check_query INTO v_result;
                v_result := COALESCE(v_result, false);
                v_details := CASE WHEN v_result THEN 'Check passed' ELSE v_check.remediation_steps END;
            EXCEPTION WHEN OTHERS THEN
                v_result := false;
                v_details := 'Error: ' || SQLERRM;
            END;
        END IF;
        
        RETURN QUERY SELECT 
            v_check.check_code, 
            v_check.check_name, 
            v_check.category,
            v_check.severity,
            v_check.is_required,
            v_result, 
            v_details;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_audit_schedule_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_effective_checklist_version(
    p_tenant_id UUID,
    p_standard_id UUID
) RETURNS UUID AS $$
DECLARE
    v_config tenant_checklist_config%ROWTYPE;
    v_version_id UUID;
BEGIN
    -- Get tenant config
    SELECT * INTO v_config
    FROM tenant_checklist_config
    WHERE tenant_id = p_tenant_id AND standard_id = p_standard_id;
    
    -- If no config or auto mode, return latest version
    IF v_config.id IS NULL OR v_config.version_selection = 'auto' THEN
        SELECT id INTO v_version_id
        FROM compliance_checklist_versions
        WHERE standard_id = p_standard_id AND is_latest = true AND is_active = true
        LIMIT 1;
        RETURN v_version_id;
    END IF;
    
    -- Return selected version
    RETURN v_config.selected_version_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_checklist_completion(
    p_tenant_id UUID,
    p_version_id UUID
) RETURNS DECIMAL AS $$
DECLARE
    v_total INTEGER;
    v_completed INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_total
    FROM compliance_checklist_items
    WHERE version_id = p_version_id AND is_required = true;
    
    IF v_total = 0 THEN
        RETURN 100.0;
    END IF;
    
    SELECT COUNT(*) INTO v_completed
    FROM tenant_checklist_progress p
    JOIN compliance_checklist_items i ON p.item_id = i.id
    WHERE p.tenant_id = p_tenant_id 
      AND i.version_id = p_version_id 
      AND i.is_required = true
      AND p.status IN ('completed', 'not_applicable');
    
    RETURN ROUND((v_completed::DECIMAL / v_total) * 100, 2);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_latest_checklist_version(
    p_version_id UUID
) RETURNS VOID AS $$
DECLARE
    v_standard_id UUID;
BEGIN
    -- Get standard ID
    SELECT standard_id INTO v_standard_id
    FROM compliance_checklist_versions
    WHERE id = p_version_id;
    
    -- Clear previous latest
    UPDATE compliance_checklist_versions
    SET is_latest = false, updated_at = NOW()
    WHERE standard_id = v_standard_id AND is_latest = true;
    
    -- Set new latest
    UPDATE compliance_checklist_versions
    SET is_latest = true, updated_at = NOW()
    WHERE id = p_version_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_checklist_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION auth.tenant_id()
RETURNS UUID AS $$
  SELECT NULLIF(current_setting('app.current_tenant_id', true), '')::UUID;
$$ LANGUAGE SQL STABLE;

COMMENT ON FUNCTION auth.tenant_id() IS 
'Returns current tenant UUID from session context. STABLE ensures single evaluation per query.';

-- Application ID retrieval
CREATE OR REPLACE FUNCTION auth.app_id()
RETURNS VARCHAR(50) AS $$
  SELECT NULLIF(current_setting('app.current_app_id', true), '');
$$ LANGUAGE SQL STABLE;

COMMENT ON FUNCTION auth.app_id() IS 
'Returns current application ID from session context. NULL when no app context set.';

-- Permission level retrieval
CREATE OR REPLACE FUNCTION auth.permission_level()
RETURNS TEXT AS $$
  SELECT COALESCE(NULLIF(current_setting('app.permission_level', true), ''), 'user');
$$ LANGUAGE SQL STABLE;

COMMENT ON FUNCTION auth.permission_level() IS 
'Returns permission level: radiant_admin, tenant_admin, app_admin, or user.';

-- User ID retrieval
CREATE OR REPLACE FUNCTION auth.user_id()
RETURNS UUID AS $$
  SELECT NULLIF(current_setting('app.current_user_id', true), '')::UUID;
$$ LANGUAGE SQL STABLE;

COMMENT ON FUNCTION auth.user_id() IS 
'Returns current user UUID from session context.';

-- Jurisdiction retrieval (for GDPR/CCPA compliance)
CREATE OR REPLACE FUNCTION auth.jurisdiction()
RETURNS TEXT AS $$
  SELECT current_setting('app.user_jurisdiction', true);
$$ LANGUAGE SQL STABLE;

COMMENT ON FUNCTION auth.jurisdiction() IS 
'Returns user jurisdiction code (EU, US-CA, BR, etc.) for compliance routing.';

-- Data region retrieval (for data sovereignty)
CREATE OR REPLACE FUNCTION auth.data_region()
RETURNS TEXT AS $$
  SELECT COALESCE(NULLIF(current_setting('app.data_region', true), ''), 'us-east-1');
$$ LANGUAGE SQL STABLE;

COMMENT ON FUNCTION auth.data_region() IS 
'Returns data region code (us-east-1, eu-west-1, etc.) for sovereignty enforcement.';

-- Check if current user is Radiant admin (super_admin in existing schema)
CREATE OR REPLACE FUNCTION auth.is_radiant_admin()
RETURNS BOOLEAN AS $$
  SELECT auth.permission_level() = 'radiant_admin' 
    OR COALESCE(current_setting('app.is_super_admin', true), 'false')::BOOLEAN;
$$ LANGUAGE SQL STABLE;

-- Check if current user is Tenant admin or higher
CREATE OR REPLACE FUNCTION auth.is_tenant_admin()
RETURNS BOOLEAN AS $$
  SELECT auth.permission_level() IN ('radiant_admin', 'tenant_admin')
    OR auth.is_radiant_admin();
$$ LANGUAGE SQL STABLE;

-- Check if Break Glass mode is active (for emergency access)
CREATE OR REPLACE FUNCTION auth.is_break_glass()
RETURNS BOOLEAN AS $$
  SELECT COALESCE(current_setting('app.break_glass_mode', true), 'false')::BOOLEAN;
$$ LANGUAGE SQL STABLE;

-- ============================================================================
-- SECTION 2: EXTEND TENANTS TABLE FOR DATA SOVEREIGNTY
-- ============================================================================

ALTER TABLE tenants ADD COLUMN IF NOT EXISTS data_region VARCHAR(20) DEFAULT 'us-east-1';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS allowed_regions TEXT[] DEFAULT '{us-east-1}';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS tier VARCHAR(32) DEFAULT 'standard';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS compliance_frameworks TEXT[] DEFAULT '{}';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS data_processing_agreement_signed_at TIMESTAMPTZ;
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS primary_contact_email VARCHAR(255);
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS billing_email VARCHAR(255);

-- Add check constraint for tier if not exists
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'tenants_tier_check'
  ) THEN
    ALTER TABLE tenants ADD CONSTRAINT tenants_tier_check 
      CHECK (tier IN ('free', 'standard', 'professional', 'enterprise'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_tenants_data_region ON tenants(data_region);

COMMENT ON COLUMN tenants.data_region IS 
'Primary data residency region for this tenant. Used for GDPR/sovereignty compliance.';
COMMENT ON COLUMN tenants.allowed_regions IS 
'List of regions where tenant data may be processed. Cross-region transfers require explicit consent.';
COMMENT ON COLUMN tenants.compliance_frameworks IS 
'Compliance frameworks this tenant is subject to (GDPR, CCPA, HIPAA, SOC2, etc.)';

