-- Source: 126_tenant_management_system.sql
-- ============================================================================
-- MIGRATION: 126_tenant_management_system.sql
-- RADIANT v4.18.55 - Tenant Management System (TMS)
-- ============================================================================
-- Implements comprehensive multi-tenant management with:
-- - Tenant lifecycle (create, update, soft delete, restore, hard delete)
-- - No orphan users rule (database-enforced)
-- - Phantom tenant creation for individual signups
-- - Multi-tenant user support with role-based membership
-- - Configurable retention with restore capability
-- - Full audit trail
-- ============================================================================

BEGIN;

-- ============================================================================
-- SECTION 1: EXTEND TENANTS TABLE
-- ============================================================================

-- Add new columns to existing tenants table
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS type VARCHAR(20) DEFAULT 'organization' 
    CHECK (type IN ('organization', 'individual'));
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS tier INTEGER DEFAULT 1 CHECK (tier BETWEEN 1 AND 5);
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS primary_region VARCHAR(20) DEFAULT 'us-east-1';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS compliance_mode JSONB DEFAULT '[]'::jsonb;
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS retention_days INTEGER DEFAULT 30 CHECK (retention_days BETWEEN 7 AND 730);
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS deletion_scheduled_at TIMESTAMPTZ;
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS deletion_requested_by UUID;
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS stripe_customer_id VARCHAR(255);
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS kms_key_arn VARCHAR(500);
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb;

-- Update status check constraint to include new statuses
ALTER TABLE tenants DROP CONSTRAINT IF EXISTS tenants_status_check;
ALTER TABLE tenants ADD CONSTRAINT tenants_status_check 
    CHECK (status IN ('active', 'suspended', 'pending', 'pending_deletion', 'deleted'));

-- Add indexes for new columns
CREATE INDEX IF NOT EXISTS idx_tenants_type ON tenants(type);
CREATE INDEX IF NOT EXISTS idx_tenants_tier ON tenants(tier);
CREATE INDEX IF NOT EXISTS idx_tenants_deletion ON tenants(deletion_scheduled_at) 
    WHERE status = 'pending_deletion';
CREATE INDEX IF NOT EXISTS idx_tenants_stripe ON tenants(stripe_customer_id) 
    WHERE stripe_customer_id IS NOT NULL;

COMMENT ON COLUMN tenants.type IS 'organization = company, individual = phantom tenant for single users';
COMMENT ON COLUMN tenants.compliance_mode IS 'Array of compliance frameworks: hipaa, soc2, gdpr';
COMMENT ON COLUMN tenants.retention_days IS 'Days to retain data after soft delete before hard delete';

-- ============================================================================
-- SECTION 2: TENANT USER MEMBERSHIPS (Multi-Tenant Users)
-- ============================================================================

CREATE TABLE IF NOT EXISTS tenant_user_memberships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR(50) DEFAULT 'member' 
        CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
    status VARCHAR(20) DEFAULT 'active' 
        CHECK (status IN ('active', 'suspended', 'invited')),
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    invited_by UUID REFERENCES users(id),
    invitation_token VARCHAR(255),
    invitation_expires_at TIMESTAMPTZ,
    last_active_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(tenant_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_memberships_tenant ON tenant_user_memberships(tenant_id);
CREATE INDEX IF NOT EXISTS idx_memberships_user ON tenant_user_memberships(user_id);
CREATE INDEX IF NOT EXISTS idx_memberships_role ON tenant_user_memberships(tenant_id, role);
CREATE INDEX IF NOT EXISTS idx_memberships_invitation ON tenant_user_memberships(invitation_token) 
    WHERE invitation_token IS NOT NULL;

COMMENT ON TABLE tenant_user_memberships IS 'Junction table for many-to-many user-tenant relationships';

-- ============================================================================
-- SECTION 3: RISK ACCEPTANCES (Compliance)
-- ============================================================================

CREATE TABLE IF NOT EXISTS tms_risk_acceptances (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
    control_id VARCHAR(50) NOT NULL,
    control_framework VARCHAR(20) CHECK (control_framework IN ('hipaa', 'soc2', 'gdpr', 'nist')),
    risk_description TEXT NOT NULL,
    mitigating_controls TEXT,
    business_justification TEXT NOT NULL,
    risk_level VARCHAR(20) CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),
    accepted_by UUID NOT NULL REFERENCES users(id),
    approved_by UUID REFERENCES users(id),
    expires_at TIMESTAMPTZ NOT NULL,
    status VARCHAR(20) DEFAULT 'pending' 
        CHECK (status IN ('pending', 'approved', 'rejected', 'expired', 'renewed')),
    renewal_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_risks_tenant ON tms_risk_acceptances(tenant_id);
CREATE INDEX IF NOT EXISTS idx_risks_status ON tms_risk_acceptances(status);
CREATE INDEX IF NOT EXISTS idx_risks_expires ON tms_risk_acceptances(expires_at) WHERE status = 'approved';

-- ============================================================================
-- SECTION 4: TENANT AUDIT LOG
-- ============================================================================

CREATE TABLE IF NOT EXISTS tms_audit_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES tenants(id) ON DELETE SET NULL,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    admin_id UUID REFERENCES administrators(id) ON DELETE SET NULL,
    action VARCHAR(100) NOT NULL,
    resource_type VARCHAR(50),
    resource_id VARCHAR(255),
    old_value JSONB,
    new_value JSONB,
    ip_address INET,
    user_agent TEXT,
    trace_id VARCHAR(100),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tms_audit_tenant ON tms_audit_log(tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tms_audit_user ON tms_audit_log(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tms_audit_action ON tms_audit_log(action, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tms_audit_trace ON tms_audit_log(trace_id) WHERE trace_id IS NOT NULL;

COMMENT ON TABLE tms_audit_log IS 'Immutable audit log for all TMS operations';

-- ============================================================================
-- SECTION 5: GLOBAL RETENTION SETTINGS
-- ============================================================================

CREATE TABLE IF NOT EXISTS tms_retention_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    setting_key VARCHAR(100) UNIQUE NOT NULL,
    setting_value JSONB NOT NULL,
    description TEXT,
    updated_by UUID REFERENCES administrators(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Insert default settings
INSERT INTO tms_retention_settings (setting_key, setting_value, description) VALUES
    ('default_retention_days', '30', 'Default retention period for soft-deleted tenants'),
    ('min_retention_days', '7', 'Minimum allowed retention period'),
    ('max_retention_days', '730', 'Maximum allowed retention period'),
    ('hipaa_min_retention_days', '90', 'Minimum retention for HIPAA-compliant tenants'),
    ('hard_delete_batch_size', '10', 'Number of tenants to hard delete per scheduled run'),
    ('deletion_notification_days', '[7, 3, 1]', 'Days before deletion to send notifications')
ON CONFLICT (setting_key) DO NOTHING;

-- ============================================================================
-- SECTION 6: VERIFICATION CODES (2FA for sensitive operations)
-- ============================================================================

CREATE TABLE IF NOT EXISTS tms_verification_codes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    admin_id UUID REFERENCES administrators(id) ON DELETE CASCADE,
    operation VARCHAR(50) NOT NULL CHECK (operation IN ('restore_tenant', 'hard_delete', 'transfer_ownership', 'compliance_override')),
    resource_id UUID NOT NULL,
    code_hash VARCHAR(64) NOT NULL,
    attempts INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 3,
    expires_at TIMESTAMPTZ NOT NULL,
    verified_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT chk_user_or_admin CHECK (user_id IS NOT NULL OR admin_id IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS idx_verification_codes_user ON tms_verification_codes(user_id, operation) 
    WHERE verified_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_verification_codes_admin ON tms_verification_codes(admin_id, operation) 
    WHERE verified_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_verification_codes_expires ON tms_verification_codes(expires_at) 
    WHERE verified_at IS NULL;

COMMENT ON TABLE tms_verification_codes IS 'Time-limited verification codes for sensitive TMS operations';

-- ============================================================================
-- SECTION 7: DELETION NOTIFICATIONS
-- ============================================================================

CREATE TABLE IF NOT EXISTS tms_deletion_notifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    notification_type VARCHAR(20) NOT NULL CHECK (notification_type IN ('7_day', '3_day', '1_day', 'deleted')),
    sent_to JSONB NOT NULL, -- Array of email addresses
    sent_at TIMESTAMPTZ DEFAULT NOW(),
    delivery_status VARCHAR(20) DEFAULT 'pending' CHECK (delivery_status IN ('pending', 'sent', 'failed', 'bounced')),
    error_message TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_deletion_notifications_tenant ON tms_deletion_notifications(tenant_id);
CREATE INDEX IF NOT EXISTS idx_deletion_notifications_type ON tms_deletion_notifications(notification_type, sent_at);

-- ============================================================================
-- SECTION 8: ORPHAN USER PREVENTION TRIGGER
-- ============================================================================

CREATE OR REPLACE FUNCTION tms_prevent_orphan_users()
RETURNS TRIGGER AS $$
DECLARE
    remaining_memberships INTEGER;
    v_user_record RECORD;
BEGIN
    -- Get user info before we check memberships
    SELECT id, email, display_name INTO v_user_record
    FROM users WHERE id = OLD.user_id;
    
    -- Count remaining active memberships for this user (excluding the one being deleted)
    SELECT COUNT(*) INTO remaining_memberships 
    FROM tenant_user_memberships 
    WHERE user_id = OLD.user_id 
    AND id != OLD.id
    AND status != 'invited';  -- Don't count pending invitations
    
    IF remaining_memberships = 0 THEN
        -- This is the last active membership
        -- Mark user as deleted (soft delete, preserve for audit)
        UPDATE users SET 
            status = 'deleted', 
            updated_at = NOW() 
        WHERE id = OLD.user_id;
        
        -- Log the automatic deletion
        INSERT INTO tms_audit_log (tenant_id, user_id, action, resource_type, resource_id, old_value, new_value)
        VALUES (
            OLD.tenant_id, 
            OLD.user_id, 
            'user_auto_deleted_orphan', 
            'user', 
            OLD.user_id::text, 
            jsonb_build_object(
                'email', v_user_record.email,
                'display_name', v_user_record.display_name,
                'last_tenant_id', OLD.tenant_id
            ),
            jsonb_build_object('reason', 'last_membership_removed', 'previous_role', OLD.role)
        );
        
        RAISE NOTICE 'Auto-deleted orphan user: % (%)', OLD.user_id, v_user_record.email;
    END IF;
    
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION tms_process_scheduled_deletions()
RETURNS TABLE (
    deleted_tenant_id UUID,
    deleted_tenant_name VARCHAR,
    deleted_at TIMESTAMPTZ,
    users_deleted INTEGER,
    users_retained INTEGER
) AS $$
DECLARE
    tenant_record RECORD;
    v_users_deleted INTEGER;
    v_users_retained INTEGER;
    v_batch_size INTEGER;
BEGIN
    -- Get batch size from settings
    SELECT (setting_value::TEXT)::INTEGER INTO v_batch_size
    FROM tms_retention_settings 
    WHERE setting_key = 'hard_delete_batch_size';
    
    v_batch_size := COALESCE(v_batch_size, 10);
    
    FOR tenant_record IN 
        SELECT t.id, t.name, t.kms_key_arn
        FROM tenants t
        WHERE t.status = 'pending_deletion' 
        AND t.deletion_scheduled_at < NOW()
        ORDER BY t.deletion_scheduled_at ASC
        LIMIT v_batch_size
    LOOP
        -- Count users that will be deleted (only in this tenant) vs retained (in multiple tenants)
        SELECT 
            COUNT(*) FILTER (WHERE membership_count = 1),
            COUNT(*) FILTER (WHERE membership_count > 1)
        INTO v_users_deleted, v_users_retained
        FROM (
            SELECT 
                tum.user_id,
                (SELECT COUNT(*) FROM tenant_user_memberships m2 
                 WHERE m2.user_id = tum.user_id AND m2.status = 'active') as membership_count
            FROM tenant_user_memberships tum
            WHERE tum.tenant_id = tenant_record.id
        ) subq;
        
        -- Log before deletion (preserve audit trail)
        INSERT INTO tms_audit_log (tenant_id, action, resource_type, resource_id, new_value)
        VALUES (
            tenant_record.id, 
            'tenant_hard_deleted', 
            'tenant', 
            tenant_record.id::text,
            jsonb_build_object(
                'name', tenant_record.name,
                'users_deleted', v_users_deleted,
                'users_retained', v_users_retained,
                'kms_key_arn', tenant_record.kms_key_arn
            )
        );
        
        -- Delete memberships first (triggers orphan check)
        DELETE FROM tenant_user_memberships WHERE tenant_id = tenant_record.id;
        
        -- Update tenant status to deleted
        UPDATE tenants 
        SET status = 'deleted', updated_at = NOW()
        WHERE id = tenant_record.id;
        
        -- Return result row
        deleted_tenant_id := tenant_record.id;
        deleted_tenant_name := tenant_record.name;
        deleted_at := NOW();
        users_deleted := COALESCE(v_users_deleted, 0);
        users_retained := COALESCE(v_users_retained, 0);
        RETURN NEXT;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION tms_create_phantom_tenant(
    p_user_email VARCHAR(255),
    p_user_display_name VARCHAR(255),
    p_cognito_user_id VARCHAR(128)
)
RETURNS TABLE (
    tenant_id UUID,
    user_id UUID,
    tenant_name VARCHAR
) AS $$
DECLARE
    v_tenant_id UUID;
    v_user_id UUID;
    v_tenant_name VARCHAR(255);
    v_existing_user RECORD;
BEGIN
    -- Check if user already exists
    SELECT id, tenant_id INTO v_existing_user
    FROM users 
    WHERE email = p_user_email OR cognito_user_id = p_cognito_user_id
    LIMIT 1;
    
    IF v_existing_user.id IS NOT NULL THEN
        -- User exists, return their primary tenant
        RETURN QUERY 
        SELECT 
            v_existing_user.tenant_id,
            v_existing_user.id,
            t.name::VARCHAR
        FROM tenants t WHERE t.id = v_existing_user.tenant_id;
        RETURN;
    END IF;
    
    -- Generate tenant name from user's display name or email
    v_tenant_name := COALESCE(p_user_display_name, split_part(p_user_email, '@', 1)) || '''s Workspace';
    
    -- Create phantom tenant (individual type)
    INSERT INTO tenants (name, display_name, type, status, tier, retention_days)
    VALUES (
        'phantom_' || gen_random_uuid()::text, -- Unique internal name
        v_tenant_name,
        'individual', 
        'active', 
        1,
        30
    )
    RETURNING id INTO v_tenant_id;
    
    -- Create user
    INSERT INTO users (tenant_id, cognito_user_id, email, display_name, role, status)
    VALUES (v_tenant_id, p_cognito_user_id, p_user_email, p_user_display_name, 'admin', 'active')
    RETURNING id INTO v_user_id;
    
    -- Create membership with owner role
    INSERT INTO tenant_user_memberships (tenant_id, user_id, role, status, joined_at)
    VALUES (v_tenant_id, v_user_id, 'owner', 'active', NOW());
    
    -- Log creation
    INSERT INTO tms_audit_log (tenant_id, user_id, action, resource_type, resource_id, new_value)
    VALUES (
        v_tenant_id, 
        v_user_id, 
        'phantom_tenant_created', 
        'tenant', 
        v_tenant_id::text,
        jsonb_build_object('name', v_tenant_name, 'email', p_user_email, 'type', 'individual')
    );
    
    RETURN QUERY SELECT v_tenant_id, v_user_id, v_tenant_name::VARCHAR;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION tms_create_verification_code(
    p_user_id UUID,
    p_admin_id UUID,
    p_operation VARCHAR(50),
    p_resource_id UUID,
    p_expires_minutes INTEGER DEFAULT 15
)
RETURNS VARCHAR(6) AS $$
DECLARE
    v_code VARCHAR(6);
    v_code_hash VARCHAR(64);
BEGIN
    -- Generate 6-digit code
    v_code := LPAD((floor(random() * 1000000)::integer)::text, 6, '0');
    
    -- Hash the code for storage
    v_code_hash := encode(digest(v_code, 'sha256'), 'hex');
    
    -- Delete any existing unused codes for this operation
    DELETE FROM tms_verification_codes
    WHERE (user_id = p_user_id OR admin_id = p_admin_id)
    AND operation = p_operation
    AND resource_id = p_resource_id
    AND verified_at IS NULL;
    
    -- Insert new code
    INSERT INTO tms_verification_codes (
        user_id, admin_id, operation, resource_id, code_hash, expires_at
    ) VALUES (
        p_user_id, p_admin_id, p_operation, p_resource_id, v_code_hash,
        NOW() + (p_expires_minutes || ' minutes')::interval
    );
    
    RETURN v_code;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION tms_verify_code(
    p_user_id UUID,
    p_admin_id UUID,
    p_operation VARCHAR(50),
    p_resource_id UUID,
    p_code VARCHAR(6)
)
RETURNS JSONB AS $$
DECLARE
    v_record RECORD;
    v_code_hash VARCHAR(64);
BEGIN
    v_code_hash := encode(digest(p_code, 'sha256'), 'hex');
    
    -- Find matching code
    SELECT * INTO v_record
    FROM tms_verification_codes
    WHERE (user_id = p_user_id OR admin_id = p_admin_id)
    AND operation = p_operation
    AND resource_id = p_resource_id
    AND verified_at IS NULL
    AND expires_at > NOW()
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;
    
    IF v_record IS NULL THEN
        RETURN jsonb_build_object('valid', false, 'error', 'no_code_found', 'message', 'No valid verification code found');
    END IF;
    
    -- Check attempts
    IF v_record.attempts >= v_record.max_attempts THEN
        RETURN jsonb_build_object('valid', false, 'error', 'max_attempts', 'message', 'Maximum verification attempts exceeded');
    END IF;
    
    -- Increment attempts
    UPDATE tms_verification_codes SET attempts = attempts + 1 WHERE id = v_record.id;
    
    -- Check code
    IF v_record.code_hash != v_code_hash THEN
        RETURN jsonb_build_object(
            'valid', false, 
            'error', 'invalid_code', 
            'message', 'Invalid verification code',
            'attempts_remaining', v_record.max_attempts - v_record.attempts - 1
        );
    END IF;
    
    -- Mark as verified
    UPDATE tms_verification_codes SET verified_at = NOW() WHERE id = v_record.id;
    
    RETURN jsonb_build_object('valid', true, 'verified_at', NOW());
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_format_supported(
    p_provider_id VARCHAR,
    p_format VARCHAR
) RETURNS BOOLEAN AS $$
DECLARE
    v_formats JSONB;
BEGIN
    SELECT supported_formats INTO v_formats
    FROM provider_file_capabilities
    WHERE provider_id = p_provider_id;
    
    IF v_formats IS NULL THEN
        RETURN false;
    END IF;
    
    RETURN v_formats ? p_format;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION check_format_supported IS 'Check if a file format is supported by an AI provider';

-- Function to get conversion statistics for a tenant
CREATE OR REPLACE FUNCTION get_conversion_stats(
    p_tenant_id UUID,
    p_days INTEGER DEFAULT 30
) RETURNS TABLE (
    total_files BIGINT,
    converted_count BIGINT,
    native_count BIGINT,
    failed_count BIGINT,
    total_bytes_processed BIGINT,
    avg_processing_ms INTEGER,
    most_common_format VARCHAR,
    most_common_strategy VARCHAR
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*)::BIGINT AS total_files,
        SUM(CASE WHEN needs_conversion THEN 1 ELSE 0 END)::BIGINT AS converted_count,
        SUM(CASE WHEN NOT needs_conversion THEN 1 ELSE 0 END)::BIGINT AS native_count,
        SUM(CASE WHEN conversion_status = 'failed' THEN 1 ELSE 0 END)::BIGINT AS failed_count,
        COALESCE(SUM(original_size), 0)::BIGINT AS total_bytes_processed,
        COALESCE(AVG(processing_time_ms), 0)::INTEGER AS avg_processing_ms,
        (SELECT original_format FROM file_conversions fc2 
         WHERE fc2.tenant_id = p_tenant_id 
         AND fc2.created_at >= NOW() - (p_days || ' days')::INTERVAL
         GROUP BY original_format ORDER BY COUNT(*) DESC LIMIT 1) AS most_common_format,
        (SELECT strategy FROM file_conversions fc3 
         WHERE fc3.tenant_id = p_tenant_id 
         AND fc3.created_at >= NOW() - (p_days || ' days')::INTERVAL
         GROUP BY strategy ORDER BY COUNT(*) DESC LIMIT 1) AS most_common_strategy
    FROM file_conversions fc
    WHERE fc.tenant_id = p_tenant_id
    AND fc.created_at >= NOW() - (p_days || ' days')::INTERVAL;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION get_conversion_stats IS 'Get file conversion statistics for a tenant over a specified period';

-- ============================================================================
-- SECTION 6: CLEANUP FUNCTION
-- ============================================================================

-- Function to clean up old conversion records and S3 files
CREATE OR REPLACE FUNCTION cleanup_old_conversions(
    p_retention_days INTEGER DEFAULT 30
) RETURNS TABLE (
    deleted_count INTEGER,
    s3_keys_to_delete TEXT[]
) AS $$
DECLARE
    v_deleted INTEGER;
    v_s3_keys TEXT[];
BEGIN
    -- Collect S3 keys before deleting
    SELECT ARRAY_AGG(DISTINCT key) INTO v_s3_keys
    FROM (
        SELECT original_s3_key AS key FROM file_conversions 
        WHERE created_at < NOW() - (p_retention_days || ' days')::INTERVAL
        AND original_s3_key IS NOT NULL
        UNION
        SELECT converted_s3_key AS key FROM file_conversions 
        WHERE created_at < NOW() - (p_retention_days || ' days')::INTERVAL
        AND converted_s3_key IS NOT NULL
    ) AS keys;
    
    -- Delete old records
    WITH deleted AS (
        DELETE FROM file_conversions
        WHERE created_at < NOW() - (p_retention_days || ' days')::INTERVAL
        RETURNING id
    )
    SELECT COUNT(*)::INTEGER INTO v_deleted FROM deleted;
    
    RETURN QUERY SELECT v_deleted, v_s3_keys;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_format_understanding(
    p_tenant_id UUID,
    p_model_id VARCHAR(200),
    p_provider_id VARCHAR(100),
    p_file_format VARCHAR(50),
    p_outcome VARCHAR(50), -- 'success', 'partial', 'failure'
    p_weight DECIMAL(4,3) DEFAULT 0.1
)
RETURNS model_format_understanding AS $$
DECLARE
    v_record model_format_understanding;
    v_outcome_value DECIMAL(4,3);
    v_new_score DECIMAL(4,3);
    v_new_confidence DECIMAL(4,3);
BEGIN
    -- Map outcome to value
    v_outcome_value := CASE p_outcome
        WHEN 'success' THEN 1.0
        WHEN 'partial' THEN 0.6
        WHEN 'failure' THEN 0.0
        ELSE 0.5
    END;
    
    -- Insert or update the record
    INSERT INTO model_format_understanding (
        tenant_id, model_id, provider_id, file_format,
        understanding_score, confidence,
        success_count, failure_count, total_attempts,
        last_evaluated_at
    ) VALUES (
        p_tenant_id, p_model_id, p_provider_id, p_file_format,
        v_outcome_value, p_weight,
        CASE WHEN p_outcome = 'success' THEN 1 ELSE 0 END,
        CASE WHEN p_outcome = 'failure' THEN 1 ELSE 0 END,
        1,
        NOW()
    )
    ON CONFLICT (tenant_id, model_id, file_format) DO UPDATE SET
        -- Exponential moving average for score
        understanding_score = model_format_understanding.understanding_score * (1 - p_weight) + v_outcome_value * p_weight,
        -- Increase confidence with more data (asymptotic to 1.0)
        confidence = LEAST(0.95, model_format_understanding.confidence + (1 - model_format_understanding.confidence) * 0.05),
        -- Update counts
        success_count = model_format_understanding.success_count + CASE WHEN p_outcome = 'success' THEN 1 ELSE 0 END,
        failure_count = model_format_understanding.failure_count + CASE WHEN p_outcome = 'failure' THEN 1 ELSE 0 END,
        total_attempts = model_format_understanding.total_attempts + 1,
        -- Timestamps
        updated_at = NOW(),
        last_evaluated_at = NOW()
    RETURNING * INTO v_record;
    
    -- Log the event
    INSERT INTO format_understanding_events (
        tenant_id, understanding_id, event_type,
        previous_score, new_score, triggered_by, details
    ) VALUES (
        p_tenant_id, v_record.id, 'score_updated',
        v_record.understanding_score, v_record.understanding_score,
        'feedback',
        jsonb_build_object('outcome', p_outcome, 'weight', p_weight)
    );
    
    RETURN v_record;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_format_recommendation(
    p_tenant_id UUID,
    p_model_id VARCHAR(200),
    p_file_format VARCHAR(50),
    p_threshold DECIMAL(4,3) DEFAULT 0.7
)
RETURNS TABLE (
    should_convert BOOLEAN,
    understanding_score DECIMAL(4,3),
    confidence DECIMAL(4,3),
    recommendation_reason TEXT,
    total_attempts INTEGER
) AS $$
DECLARE
    v_record model_format_understanding;
    v_global global_format_learning;
BEGIN
    -- Check tenant-specific understanding
    SELECT * INTO v_record
    FROM model_format_understanding
    WHERE tenant_id = p_tenant_id
      AND model_id = p_model_id
      AND file_format = p_file_format;
    
    -- If force convert is set, return that
    IF v_record.force_convert THEN
        RETURN QUERY SELECT 
            true AS should_convert,
            v_record.understanding_score,
            v_record.confidence,
            'Admin override: ' || COALESCE(v_record.force_convert_reason, 'Manual override') AS recommendation_reason,
            v_record.total_attempts;
        RETURN;
    END IF;
    
    -- If we have tenant-specific data with good confidence
    IF v_record.id IS NOT NULL AND v_record.confidence >= 0.5 THEN
        RETURN QUERY SELECT
            v_record.understanding_score < p_threshold AS should_convert,
            v_record.understanding_score,
            v_record.confidence,
            CASE 
                WHEN v_record.understanding_score >= p_threshold THEN 
                    'Model understands this format well (score: ' || ROUND(v_record.understanding_score::numeric, 2) || ')'
                ELSE 
                    'Model struggles with this format (score: ' || ROUND(v_record.understanding_score::numeric, 2) || ')'
            END AS recommendation_reason,
            v_record.total_attempts;
        RETURN;
    END IF;
    
    -- Fall back to global learning
    SELECT * INTO v_global
    FROM global_format_learning
    WHERE model_id = p_model_id
      AND file_format = p_file_format;
    
    IF v_global.id IS NOT NULL AND v_global.global_confidence >= 0.3 THEN
        RETURN QUERY SELECT
            v_global.global_understanding_score < p_threshold AS should_convert,
            v_global.global_understanding_score,
            v_global.global_confidence,
            'Based on global learning across ' || v_global.tenant_count || ' tenants' AS recommendation_reason,
            v_global.total_attempts;
        RETURN;
    END IF;
    
    -- No data - return default (don't convert, let model try)
    RETURN QUERY SELECT
        false AS should_convert,
        0.5::DECIMAL(4,3) AS understanding_score,
        0.0::DECIMAL(4,3) AS confidence,
        'No learning data available - assuming model can handle format' AS recommendation_reason,
        0 AS total_attempts;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_global_format_learning()
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER := 0;
BEGIN
    -- Aggregate all tenant data to global
    INSERT INTO global_format_learning (
        model_id, provider_id, file_format,
        global_understanding_score, global_confidence,
        total_success_count, total_failure_count, total_attempts, tenant_count,
        updated_at
    )
    SELECT 
        model_id, 
        provider_id, 
        file_format,
        -- Weighted average of understanding scores
        SUM(understanding_score * total_attempts) / NULLIF(SUM(total_attempts), 0) AS global_understanding_score,
        -- Confidence based on data volume
        LEAST(0.95, 0.1 + (LN(SUM(total_attempts) + 1) / 10)) AS global_confidence,
        SUM(success_count) AS total_success_count,
        SUM(failure_count) AS total_failure_count,
        SUM(total_attempts) AS total_attempts,
        COUNT(DISTINCT tenant_id) AS tenant_count,
        NOW() AS updated_at
    FROM model_format_understanding
    GROUP BY model_id, provider_id, file_format
    ON CONFLICT (model_id, file_format) DO UPDATE SET
        global_understanding_score = EXCLUDED.global_understanding_score,
        global_confidence = EXCLUDED.global_confidence,
        total_success_count = EXCLUDED.total_success_count,
        total_failure_count = EXCLUDED.total_failure_count,
        total_attempts = EXCLUDED.total_attempts,
        tenant_count = EXCLUDED.tenant_count,
        updated_at = NOW();
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION refresh_tenant_daily_metrics()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_tenant_daily_metrics;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_learning_influence(
    p_tenant_id UUID,
    p_user_id UUID,
    p_decision_type VARCHAR(50),
    p_context JSONB DEFAULT '{}'
)
RETURNS TABLE (
    user_influence JSONB,
    tenant_influence JSONB,
    global_influence JSONB,
    user_weight DECIMAL(3, 2),
    tenant_weight DECIMAL(3, 2),
    global_weight DECIMAL(3, 2),
    combined_recommendation JSONB
) AS $$
DECLARE
    v_config learning_influence_config%ROWTYPE;
    v_user_data JSONB := '{}';
    v_tenant_data JSONB := '{}';
    v_global_data JSONB := '{}';
BEGIN
    -- Get config or use defaults
    SELECT * INTO v_config 
    FROM learning_influence_config 
    WHERE tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        v_config.user_weight := 0.60;
        v_config.tenant_weight := 0.30;
        v_config.global_weight := 0.10;
        v_config.enable_user_learning := true;
        v_config.enable_tenant_aggregation := true;
        v_config.enable_global_learning := true;
    END IF;
    
    -- Get user-level learning
    IF v_config.enable_user_learning THEN
        SELECT jsonb_object_agg(preference_key, jsonb_build_object(
            'value', preference_value,
            'confidence', confidence,
            'evidence_count', evidence_count
        )) INTO v_user_data
        FROM user_learned_preferences
        WHERE tenant_id = p_tenant_id AND user_id = p_user_id;
    END IF;
    
    -- Get tenant-level learning
    IF v_config.enable_tenant_aggregation THEN
        SELECT jsonb_object_agg(learning_dimension, jsonb_build_object(
            'state', state_data,
            'confidence', confidence,
            'sample_count', sample_count
        )) INTO v_tenant_data
        FROM tenant_aggregate_learning
        WHERE tenant_id = p_tenant_id;
    END IF;
    
    -- Get global learning
    IF v_config.enable_global_learning THEN
        SELECT jsonb_object_agg(learning_dimension, jsonb_build_object(
            'state', state_data,
            'confidence', confidence,
            'sample_count', sample_count
        )) INTO v_global_data
        FROM global_aggregate_learning
        WHERE contributing_tenants >= 
            (SELECT COALESCE(MIN(min_tenant_threshold), 5) FROM global_aggregate_learning);
    END IF;
    
    RETURN QUERY SELECT 
        COALESCE(v_user_data, '{}'),
        COALESCE(v_tenant_data, '{}'),
        COALESCE(v_global_data, '{}'),
        v_config.user_weight,
        v_config.tenant_weight,
        v_config.global_weight,
        jsonb_build_object(
            'user', v_user_data,
            'tenant', v_tenant_data,
            'global', v_global_data,
            'weights', jsonb_build_object(
                'user', v_config.user_weight,
                'tenant', v_config.tenant_weight,
                'global', v_config.global_weight
            )
        );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION record_learning_event(
    p_tenant_id UUID,
    p_user_id UUID,
    p_event_type VARCHAR(50),
    p_learning_dimension VARCHAR(100),
    p_event_data JSONB,
    p_impact_score DECIMAL(3, 2) DEFAULT 0.50
)
RETURNS UUID AS $$
DECLARE
    v_event_id UUID;
    v_aggregate_id UUID;
    v_current_state JSONB;
    v_new_state JSONB;
BEGIN
    -- Insert event
    INSERT INTO tenant_learning_events (
        tenant_id, event_type, source_user_hash,
        event_data, impact_score, occurred_at
    ) VALUES (
        p_tenant_id, p_event_type, encode(sha256(p_user_id::text::bytea), 'hex'),
        p_event_data, p_impact_score, NOW()
    ) RETURNING id INTO v_event_id;
    
    -- Update or create tenant aggregate
    SELECT id, state_data INTO v_aggregate_id, v_current_state
    FROM tenant_aggregate_learning
    WHERE tenant_id = p_tenant_id AND learning_dimension = p_learning_dimension;
    
    IF NOT FOUND THEN
        INSERT INTO tenant_aggregate_learning (
            tenant_id, learning_dimension, state_data, sample_count, contributing_users
        ) VALUES (
            p_tenant_id, p_learning_dimension, p_event_data, 1, 1
        ) RETURNING id INTO v_aggregate_id;
    ELSE
        -- Simple state update (in production, use more sophisticated merging)
        UPDATE tenant_aggregate_learning
        SET 
            state_data = state_data || p_event_data,
            sample_count = sample_count + 1,
            last_updated = NOW(),
            last_learning_event_at = NOW()
        WHERE id = v_aggregate_id;
    END IF;
    
    -- Link event to aggregate
    UPDATE tenant_learning_events
    SET aggregate_learning_id = v_aggregate_id, was_incorporated = true
    WHERE id = v_event_id;
    
    RETURN v_event_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_learning_snapshot(
    p_scope_type VARCHAR(20),
    p_scope_id UUID DEFAULT NULL,
    p_tenant_id UUID DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_snapshot_id UUID;
    v_version INTEGER;
    v_state JSONB;
    v_checksum VARCHAR(64);
BEGIN
    -- Get next version
    SELECT COALESCE(MAX(snapshot_version), 0) + 1 INTO v_version
    FROM learning_snapshots
    WHERE scope_type = p_scope_type AND scope_id IS NOT DISTINCT FROM p_scope_id;
    
    -- Build state based on scope
    IF p_scope_type = 'user' THEN
        SELECT jsonb_build_object(
            'preferences', (SELECT jsonb_agg(row_to_json(p)) FROM user_learned_preferences p 
                           WHERE user_id = p_scope_id AND tenant_id = p_tenant_id),
            'rules', (SELECT jsonb_agg(row_to_json(r)) FROM user_rules r 
                     WHERE user_id = p_scope_id AND tenant_id = p_tenant_id),
            'memories', (SELECT jsonb_agg(row_to_json(m)) FROM memories m 
                        JOIN memory_stores ms ON m.store_id = ms.id 
                        WHERE ms.user_id = p_scope_id AND ms.tenant_id = p_tenant_id)
        ) INTO v_state;
    ELSIF p_scope_type = 'tenant' THEN
        SELECT jsonb_build_object(
            'aggregate_learning', (SELECT jsonb_agg(row_to_json(a)) FROM tenant_aggregate_learning a 
                                  WHERE tenant_id = p_scope_id),
            'model_performance', (SELECT jsonb_agg(row_to_json(m)) FROM tenant_model_performance m 
                                 WHERE tenant_id = p_scope_id),
            'influence_config', (SELECT row_to_json(c) FROM learning_influence_config c 
                                WHERE tenant_id = p_scope_id)
        ) INTO v_state;
    ELSIF p_scope_type = 'global' THEN
        SELECT jsonb_build_object(
            'aggregate_learning', (SELECT jsonb_agg(row_to_json(g)) FROM global_aggregate_learning g),
            'model_performance', (SELECT jsonb_agg(row_to_json(m)) FROM global_model_performance m),
            'pattern_library', (SELECT jsonb_agg(row_to_json(p)) FROM global_pattern_library p)
        ) INTO v_state;
    END IF;
    
    -- Calculate checksum
    v_checksum := encode(sha256(v_state::text::bytea), 'hex');
    
    -- Mark previous as not current
    UPDATE learning_snapshots
    SET is_current = false
    WHERE scope_type = p_scope_type AND scope_id IS NOT DISTINCT FROM p_scope_id;
    
    -- Insert snapshot
    INSERT INTO learning_snapshots (
        scope_type, scope_id, tenant_id,
        snapshot_version, learning_state, state_checksum,
        is_current
    ) VALUES (
        p_scope_type, p_scope_id, p_tenant_id,
        v_version, v_state, v_checksum,
        true
    ) RETURNING id INTO v_snapshot_id;
    
    RETURN v_snapshot_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_metrics_summary(
    p_tenant_id UUID,
    p_start_date DATE,
    p_end_date DATE
)
RETURNS TABLE (
    total_cost_cents BIGINT,
    total_tokens BIGINT,
    total_api_calls BIGINT,
    success_rate DECIMAL(5, 2),
    avg_latency_ms DECIMAL(10, 2),
    failure_count BIGINT,
    violation_count BIGINT,
    active_users BIGINT,
    models_used TEXT[]
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(SUM(bm.total_cost_cents), 0)::BIGINT as total_cost_cents,
        COALESCE(SUM(bm.total_tokens), 0)::BIGINT as total_tokens,
        COALESCE(SUM(bm.api_calls), 0)::BIGINT as total_api_calls,
        CASE WHEN COALESCE(SUM(bm.api_calls), 0) > 0 
            THEN (COALESCE(SUM(bm.successful_calls), 0)::DECIMAL / SUM(bm.api_calls) * 100)
            ELSE 0 
        END as success_rate,
        COALESCE(AVG(pm.total_latency_ms), 0) as avg_latency_ms,
        (SELECT COUNT(*) FROM failure_events fe 
         WHERE fe.tenant_id = p_tenant_id 
         AND fe.occurred_at::date BETWEEN p_start_date AND p_end_date)::BIGINT as failure_count,
        (SELECT COUNT(*) FROM prompt_violations pv 
         WHERE pv.tenant_id = p_tenant_id 
         AND pv.occurred_at::date BETWEEN p_start_date AND p_end_date)::BIGINT as violation_count,
        (SELECT COUNT(DISTINCT bm2.user_id) FROM billing_metrics bm2 
         WHERE bm2.tenant_id = p_tenant_id 
         AND bm2.period_date BETWEEN p_start_date AND p_end_date)::BIGINT as active_users,
        (SELECT ARRAY_AGG(DISTINCT bm3.model_id) FROM billing_metrics bm3 
         WHERE bm3.tenant_id = p_tenant_id 
         AND bm3.period_date BETWEEN p_start_date AND p_end_date) as models_used
    FROM billing_metrics bm
    LEFT JOIN performance_metrics pm ON pm.tenant_id = bm.tenant_id 
        AND pm.recorded_at::date = bm.period_date
    WHERE bm.tenant_id = p_tenant_id
    AND bm.period_date BETWEEN p_start_date AND p_end_date
    GROUP BY bm.tenant_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION auto_version_user_rule()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- Only version if content actually changed
        IF OLD.rule_content IS DISTINCT FROM NEW.rule_content OR
           OLD.rule_priority IS DISTINCT FROM NEW.rule_priority OR
           OLD.is_active IS DISTINCT FROM NEW.is_active THEN
            
            INSERT INTO user_rules_versions (
                rule_id, version, rule_content, rule_priority, is_active,
                change_type, change_reason
            ) VALUES (
                NEW.id, NEW.current_version, NEW.rule_content, NEW.rule_priority, NEW.is_active,
                'update', 'Auto-versioned on update'
            );
            
            NEW.current_version := NEW.current_version + 1;
            NEW.updated_at := NOW();
        END IF;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO user_rules_versions (
            rule_id, version, rule_content, rule_priority, is_active,
            change_type, change_reason
        ) VALUES (
            NEW.id, 1, NEW.rule_content, NEW.rule_priority, NEW.is_active,
            'create', 'Initial creation'
        );
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_to_global()
RETURNS void AS $$
DECLARE
    v_min_tenants INTEGER := 5;
BEGIN
    -- Aggregate model performance across tenants
    INSERT INTO global_model_performance (model_id, task_type, quality_score, speed_score, 
        cost_efficiency_score, reliability_score, total_tenants_using, total_uses, 
        positive_feedback_rate, confidence, last_aggregated_at)
    SELECT 
        tmp.model_id,
        tmp.task_type,
        AVG(tmp.quality_score) as quality_score,
        AVG(tmp.speed_score) as speed_score,
        AVG(tmp.cost_efficiency_score) as cost_efficiency_score,
        AVG(tmp.reliability_score) as reliability_score,
        COUNT(DISTINCT tmp.tenant_id) as total_tenants_using,
        SUM(tmp.total_uses) as total_uses,
        AVG(CASE WHEN tmp.total_uses > 0 
            THEN tmp.positive_feedback::DECIMAL / (tmp.positive_feedback + tmp.negative_feedback)
            ELSE 0.5 END) as positive_feedback_rate,
        CASE WHEN COUNT(DISTINCT tmp.tenant_id) >= v_min_tenants THEN 0.80 ELSE 0.30 END as confidence,
        NOW()
    FROM tenant_model_performance tmp
    GROUP BY tmp.model_id, tmp.task_type
    HAVING COUNT(DISTINCT tmp.tenant_id) >= v_min_tenants
    ON CONFLICT (model_id, task_type) DO UPDATE SET
        quality_score = EXCLUDED.quality_score,
        speed_score = EXCLUDED.speed_score,
        cost_efficiency_score = EXCLUDED.cost_efficiency_score,
        reliability_score = EXCLUDED.reliability_score,
        total_tenants_using = EXCLUDED.total_tenants_using,
        total_uses = EXCLUDED.total_uses,
        positive_feedback_rate = EXCLUDED.positive_feedback_rate,
        confidence = EXCLUDED.confidence,
        last_aggregated_at = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION insert_model_capabilities(
    p_model_id VARCHAR(100),
    p_capabilities JSONB
) RETURNS VOID AS $$
DECLARE
    matrix_id UUID;
    cap JSONB;
BEGIN
    SELECT id INTO matrix_id FROM model_language_matrices WHERE model_id = p_model_id;
    IF matrix_id IS NULL THEN
        RETURN;
    END IF;
    
    FOR cap IN SELECT * FROM jsonb_array_elements(p_capabilities)
    LOOP
        INSERT INTO model_language_capabilities (matrix_id, language_code, support_level, quality_score)
        VALUES (
            matrix_id,
            cap->>'lang',
            cap->>'level',
            (cap->>'score')::INTEGER
        )
        ON CONFLICT (matrix_id, language_code) DO UPDATE SET
            support_level = EXCLUDED.support_level,
            quality_score = EXCLUDED.quality_score;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_translation_config_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_cache_hit_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.last_used_at != NEW.last_used_at THEN
        NEW.hit_count = OLD.hit_count + 1;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_expired_translation_cache()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM translation_cache WHERE expires_at < NOW();
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION enforce_translation_cache_limit()
RETURNS INTEGER AS $$
DECLARE
    tenant RECORD;
    max_size INTEGER;
    current_count INTEGER;
    to_delete INTEGER;
    deleted_total INTEGER := 0;
BEGIN
    FOR tenant IN SELECT DISTINCT tenant_id FROM translation_cache LOOP
        SELECT COALESCE(tc.max_cache_size, 10000) INTO max_size
        FROM translation_config tc WHERE tc.tenant_id = tenant.tenant_id;
        
        SELECT COUNT(*) INTO current_count
        FROM translation_cache WHERE tenant_id = tenant.tenant_id;
        
        IF current_count > max_size THEN
            to_delete := current_count - max_size;
            
            DELETE FROM translation_cache
            WHERE id IN (
                SELECT id FROM translation_cache
                WHERE tenant_id = tenant.tenant_id
                ORDER BY last_used_at ASC
                LIMIT to_delete
            );
            
            deleted_total := deleted_total + to_delete;
        END IF;
    END LOOP;
    
    RETURN deleted_total;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_ghost_vector(
    p_user_id UUID,
    p_tenant_id UUID,
    p_vector BYTEA,
    p_version VARCHAR,
    p_reason VARCHAR DEFAULT 'reanchor'
)
RETURNS UUID AS $$
DECLARE
    v_ghost_id UUID;
BEGIN
    -- Get existing ghost ID
    SELECT id INTO v_ghost_id 
    FROM ghost_vectors 
    WHERE user_id = p_user_id AND tenant_id = p_tenant_id;
    
    IF v_ghost_id IS NOT NULL THEN
        -- Save to history
        INSERT INTO ghost_vector_history (ghost_id, user_id, tenant_id, vector, version, turn_count, reason)
        SELECT id, user_id, tenant_id, vector, version, turn_count, p_reason
        FROM ghost_vectors 
        WHERE id = v_ghost_id;
        
        -- Update existing
        UPDATE ghost_vectors 
        SET vector = p_vector,
            version = p_version,
            turn_count = 0,
            last_reanchor_at = NOW(),
            updated_at = NOW()
        WHERE id = v_ghost_id;
    ELSE
        -- Insert new
        INSERT INTO ghost_vectors (user_id, tenant_id, vector, version, turn_count, last_reanchor_at)
        VALUES (p_user_id, p_tenant_id, p_vector, p_version, 0, NOW())
        RETURNING id INTO v_ghost_id;
    END IF;
    
    RETURN v_ghost_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION increment_ghost_turn(p_user_id UUID, p_tenant_id UUID)
RETURNS INTEGER AS $$
DECLARE
    v_new_count INTEGER;
BEGIN
    UPDATE ghost_vectors 
    SET turn_count = turn_count + 1,
        updated_at = NOW()
    WHERE user_id = p_user_id AND tenant_id = p_tenant_id
    RETURNING turn_count INTO v_new_count;
    
    RETURN COALESCE(v_new_count, 0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION process_oversight_timeouts()
RETURNS TABLE(expired_count INTEGER, escalated_count INTEGER) AS $$
DECLARE
    v_expired INTEGER;
    v_escalated INTEGER;
BEGIN
    -- Auto-reject expired items (7-day rule: "Silence ≠ Consent")
    UPDATE oversight_queue 
    SET status = 'expired'
    WHERE status IN ('pending', 'escalated') 
    AND expires_at < NOW();
    
    GET DIAGNOSTICS v_expired = ROW_COUNT;
    
    -- Escalate items approaching timeout (3-day threshold)
    UPDATE oversight_queue 
    SET status = 'escalated', 
        escalated_at = NOW()
    WHERE status = 'pending' 
    AND created_at < NOW() - INTERVAL '3 days'
    AND expires_at >= NOW();
    
    GET DIAGNOSTICS v_escalated = ROW_COUNT;
    
    RETURN QUERY SELECT v_expired, v_escalated;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_twilight_dream_tenants(p_twilight_hour INTEGER)
RETURNS TABLE(tenant_id UUID, timezone VARCHAR, hours_since_dream FLOAT) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.tenant_id,
        COALESCE(tds.timezone, 'UTC')::VARCHAR,
        EXTRACT(EPOCH FROM (NOW() - COALESCE(tds.last_dream_at, NOW() - INTERVAL '100 hours'))) / 3600 AS hours_since_dream
    FROM tenants t
    LEFT JOIN tenant_dream_status tds ON t.tenant_id = tds.tenant_id
    WHERE 
        -- Local time is twilight hour
        EXTRACT(HOUR FROM NOW() AT TIME ZONE COALESCE(tds.timezone, 'UTC')) = p_twilight_hour
        AND EXTRACT(MINUTE FROM NOW() AT TIME ZONE COALESCE(tds.timezone, 'UTC')) < 15
        -- At least 20 hours since last dream
        AND (tds.last_dream_at IS NULL OR tds.last_dream_at < NOW() - INTERVAL '20 hours')
        -- Not already in queue
        AND NOT EXISTS (
            SELECT 1 FROM dream_queue dq 
            WHERE dq.tenant_id = t.tenant_id 
            AND dq.status = 'pending'
        )
    ORDER BY hours_since_dream DESC
    LIMIT 500;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_starved_tenants(p_max_hours INTEGER)
RETURNS TABLE(tenant_id UUID, hours_since_dream FLOAT) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.tenant_id,
        EXTRACT(EPOCH FROM (NOW() - COALESCE(tds.last_dream_at, NOW() - INTERVAL '100 hours'))) / 3600 AS hours_since_dream
    FROM tenants t
    LEFT JOIN tenant_dream_status tds ON t.tenant_id = tds.tenant_id
    WHERE 
        tds.last_dream_at IS NULL 
        OR tds.last_dream_at < NOW() - (p_max_hours || ' hours')::INTERVAL
    ORDER BY hours_since_dream DESC
    LIMIT 100;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_config_value(
    p_config_key VARCHAR,
    p_new_value JSONB,
    p_changed_by UUID,
    p_reason TEXT DEFAULT NULL
)
RETURNS VOID AS $$
DECLARE
    v_old_value JSONB;
BEGIN
    -- Get old value
    SELECT value INTO v_old_value 
    FROM system_config 
    WHERE key = p_config_key;
    
    -- Update config
    UPDATE system_config 
    SET value = p_new_value,
        last_modified_by = p_changed_by,
        last_modified_at = NOW(),
        updated_at = NOW()
    WHERE key = p_config_key;
    
    -- Record history
    INSERT INTO config_history (config_key, old_value, new_value, changed_by, change_reason)
    VALUES (p_config_key, v_old_value, p_new_value, p_changed_by, p_reason);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_config_value(p_config_key VARCHAR)
RETURNS JSONB AS $$
DECLARE
    v_value JSONB;
BEGIN
    SELECT value INTO v_value 
    FROM system_config 
    WHERE key = p_config_key;
    
    RETURN v_value;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_config_number(p_config_key VARCHAR, p_default NUMERIC DEFAULT 0)
RETURNS NUMERIC AS $$
DECLARE
    v_value JSONB;
BEGIN
    SELECT value INTO v_value 
    FROM system_config 
    WHERE key = p_config_key;
    
    IF v_value IS NULL THEN
        RETURN p_default;
    END IF;
    
    RETURN (v_value #>> '{}')::NUMERIC;
EXCEPTION WHEN OTHERS THEN
    RETURN p_default;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_config_boolean(p_config_key VARCHAR, p_default BOOLEAN DEFAULT false)
RETURNS BOOLEAN AS $$
DECLARE
    v_value JSONB;
BEGIN
    SELECT value INTO v_value 
    FROM system_config 
    WHERE key = p_config_key;
    
    IF v_value IS NULL THEN
        RETURN p_default;
    END IF;
    
    RETURN (v_value #>> '{}')::BOOLEAN;
EXCEPTION WHEN OTHERS THEN
    RETURN p_default;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_config_string(p_config_key VARCHAR, p_default VARCHAR DEFAULT '')
RETURNS VARCHAR AS $$
DECLARE
    v_value JSONB;
BEGIN
    SELECT value INTO v_value 
    FROM system_config 
    WHERE key = p_config_key;
    
    IF v_value IS NULL THEN
        RETURN p_default;
    END IF;
    
    RETURN v_value #>> '{}';
EXCEPTION WHEN OTHERS THEN
    RETURN p_default;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION reset_config_to_default(p_config_key VARCHAR, p_changed_by UUID)
RETURNS VOID AS $$
DECLARE
    v_default JSONB;
BEGIN
    SELECT default_value INTO v_default 
    FROM system_config 
    WHERE key = p_config_key;
    
    IF v_default IS NOT NULL THEN
        PERFORM set_config_value(p_config_key, v_default, p_changed_by, 'Reset to default');
    END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_config_by_category(p_category VARCHAR)
RETURNS TABLE(
    key VARCHAR,
    value JSONB,
    name VARCHAR,
    description TEXT,
    type VARCHAR,
    constraints_json JSONB,
    dangerous BOOLEAN,
    default_value JSONB
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sc.key,
        sc.value,
        sc.name,
        sc.description,
        sc.type,
        sc.constraints_json,
        sc.dangerous,
        sc.default_value
    FROM system_config sc
    WHERE sc.category = p_category
    ORDER BY sc.key;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ecd_stats(p_tenant_id UUID, p_days INTEGER DEFAULT 7)
RETURNS TABLE (
    avg_score FLOAT,
    first_pass_rate FLOAT,
    refinements_today INTEGER,
    blocked_today INTEGER,
    total_requests INTEGER
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(AVG(ecd_score), 0)::FLOAT as avg_score,
        COALESCE(
            (COUNT(*) FILTER (WHERE refinement_attempts = 1 AND passed)::FLOAT / NULLIF(COUNT(*), 0)) * 100,
            100
        )::FLOAT as first_pass_rate,
        COALESCE(SUM(refinement_attempts - 1) FILTER (WHERE created_at::DATE = CURRENT_DATE), 0)::INTEGER as refinements_today,
        COALESCE(COUNT(*) FILTER (WHERE blocked AND created_at::DATE = CURRENT_DATE), 0)::INTEGER as blocked_today,
        COUNT(*)::INTEGER as total_requests
    FROM ecd_metrics
    WHERE tenant_id = p_tenant_id
      AND created_at > NOW() - (p_days || ' days')::INTERVAL;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to log ECD metrics
CREATE OR REPLACE FUNCTION log_ecd_metrics(
    p_user_id UUID,
    p_tenant_id UUID,
    p_request_id UUID,
    p_ecd_score FLOAT,
    p_divergent_entities JSONB,
    p_grounded_count INTEGER,
    p_refinement_attempts INTEGER,
    p_passed BOOLEAN,
    p_blocked BOOLEAN,
    p_domain VARCHAR,
    p_threshold FLOAT
)
RETURNS UUID AS $$
DECLARE
    v_metrics_id UUID;
BEGIN
    INSERT INTO ecd_metrics (
        user_id, tenant_id, request_id, ecd_score, divergent_entities,
        grounded_entities_count, refinement_attempts, passed, blocked, domain, threshold_used
    ) VALUES (
        p_user_id, p_tenant_id, p_request_id, p_ecd_score, p_divergent_entities,
        p_grounded_count, p_refinement_attempts, p_passed, p_blocked, p_domain, p_threshold
    )
    RETURNING id INTO v_metrics_id;
    
    RETURN v_metrics_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_ecd_entity_stats(
    p_tenant_id UUID,
    p_entity_type VARCHAR,
    p_grounded INTEGER,
    p_divergent INTEGER
)
RETURNS VOID AS $$
BEGIN
    INSERT INTO ecd_entity_stats (tenant_id, entity_type, total_count, grounded_count, divergent_count)
    VALUES (p_tenant_id, p_entity_type, p_grounded + p_divergent, p_grounded, p_divergent)
    ON CONFLICT (tenant_id, entity_type, date) DO UPDATE SET
        total_count = ecd_entity_stats.total_count + EXCLUDED.total_count,
        grounded_count = ecd_entity_stats.grounded_count + EXCLUDED.grounded_count,
        divergent_count = ecd_entity_stats.divergent_count + EXCLUDED.divergent_count,
        updated_at = NOW();
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ecd_entity_breakdown(p_tenant_id UUID, p_days INTEGER DEFAULT 7)
RETURNS TABLE (
    entity_type VARCHAR,
    total_count BIGINT,
    grounded_count BIGINT,
    divergent_count BIGINT,
    divergence_rate FLOAT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.entity_type,
        SUM(e.total_count)::BIGINT as total_count,
        SUM(e.grounded_count)::BIGINT as grounded_count,
        SUM(e.divergent_count)::BIGINT as divergent_count,
        CASE 
            WHEN SUM(e.total_count) > 0 
            THEN (SUM(e.divergent_count)::FLOAT / SUM(e.total_count)::FLOAT) * 100
            ELSE 0
        END as divergence_rate
    FROM ecd_entity_stats e
    WHERE e.tenant_id = p_tenant_id
      AND e.date > CURRENT_DATE - p_days
    GROUP BY e.entity_type
    ORDER BY divergence_rate DESC;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to get ECD trend data
CREATE OR REPLACE FUNCTION get_ecd_trend(p_tenant_id UUID, p_days INTEGER DEFAULT 7)
RETURNS TABLE (
    date DATE,
    avg_score FLOAT,
    pass_rate FLOAT,
    total_requests BIGINT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        DATE(m.created_at) as date,
        AVG(m.ecd_score)::FLOAT as avg_score,
        (COUNT(*) FILTER (WHERE m.passed)::FLOAT / NULLIF(COUNT(*), 0) * 100)::FLOAT as pass_rate,
        COUNT(*)::BIGINT as total_requests
    FROM ecd_metrics m
    WHERE m.tenant_id = p_tenant_id
      AND m.created_at > NOW() - (p_days || ' days')::INTERVAL
    GROUP BY DATE(m.created_at)
    ORDER BY date;
END;
$$ LANGUAGE plpgsql STABLE;

-- =============================================================================
-- Comments
-- =============================================================================

COMMENT ON TABLE ecd_metrics IS 'ECD verification metrics for hallucination detection';
COMMENT ON TABLE ecd_audit_log IS 'Detailed audit trail for ECD verification (compliance)';
COMMENT ON TABLE ecd_entity_stats IS 'Aggregated entity type statistics for ECD monitoring';
COMMENT ON FUNCTION get_ecd_stats IS 'Get ECD statistics for admin dashboard';
COMMENT ON FUNCTION log_ecd_metrics IS 'Log ECD verification result';
COMMENT ON FUNCTION get_ecd_entity_breakdown IS 'Get divergence rates by entity type';
COMMENT ON FUNCTION get_ecd_trend IS 'Get ECD score trend over time';


