-- Source: 136_thinktank_shared_conversations.sql
-- ============================================================================
-- RADIANT v4.18.0 - Think Tank Shared Conversations Migration
-- Allows users to share conversations via public links
-- ============================================================================

-- Shared conversation links
CREATE TABLE thinktank_shared_conversations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID NOT NULL REFERENCES thinktank_conversations(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    shared_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    share_token VARCHAR(64) NOT NULL UNIQUE,
    title VARCHAR(500),
    description TEXT,
    is_public BOOLEAN DEFAULT true,
    allow_copy BOOLEAN DEFAULT true,
    expires_at TIMESTAMPTZ,
    view_count INTEGER DEFAULT 0,
    max_views INTEGER,
    password_hash VARCHAR(255),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Access log for shared conversations
CREATE TABLE thinktank_share_access_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    share_id UUID NOT NULL REFERENCES thinktank_shared_conversations(id) ON DELETE CASCADE,
    accessor_ip VARCHAR(45),
    accessor_user_id UUID REFERENCES users(id),
    user_agent TEXT,
    accessed_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes
CREATE INDEX idx_shared_conv_token ON thinktank_shared_conversations(share_token);
CREATE INDEX idx_shared_conv_conversation ON thinktank_shared_conversations(conversation_id);
CREATE INDEX idx_shared_conv_tenant ON thinktank_shared_conversations(tenant_id);
CREATE INDEX idx_shared_conv_user ON thinktank_shared_conversations(shared_by);
CREATE INDEX idx_share_access_log ON thinktank_share_access_log(share_id, accessed_at DESC);

-- Row level security
ALTER TABLE thinktank_shared_conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE thinktank_share_access_log ENABLE ROW LEVEL SECURITY;

-- Policy: Users can manage their own shares
CREATE POLICY thinktank_shared_conv_owner ON thinktank_shared_conversations
    FOR ALL USING (
        tenant_id = current_setting('app.current_tenant_id')::UUID AND
        shared_by = current_setting('app.user_id')::UUID
    );

-- Policy: Anyone can view public shares (for public access endpoint)
CREATE POLICY thinktank_shared_conv_public ON thinktank_shared_conversations
    FOR SELECT USING (is_public = true);

CREATE POLICY thinktank_share_access_isolation ON thinktank_share_access_log
    FOR ALL USING (
        share_id IN (
            SELECT id FROM thinktank_shared_conversations 
            WHERE tenant_id = current_setting('app.current_tenant_id')::UUID
        )
    );

-- Function to generate secure share token
CREATE OR REPLACE FUNCTION generate_share_token()
RETURNS VARCHAR(64) AS $$
DECLARE
    token VARCHAR(64);
BEGIN
    -- Generate a URL-safe base64-like token
    token := encode(gen_random_bytes(32), 'hex');
    RETURN token;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_share_token()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.share_token IS NULL THEN
        NEW.share_token := generate_share_token();
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION increment_share_view_count()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE thinktank_shared_conversations
    SET view_count = view_count + 1
    WHERE id = NEW.share_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION generate_session_link_token()
RETURNS VARCHAR(64) AS $$
BEGIN
    RETURN encode(gen_random_bytes(32), 'hex');
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION assign_participant_color()
RETURNS TRIGGER AS $$
DECLARE
    colors TEXT[] := ARRAY['#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6', '#3b82f6', '#8b5cf6', '#ec4899'];
    participant_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO participant_count FROM session_participants WHERE session_id = NEW.session_id;
    NEW.color := colors[(participant_count % array_length(colors, 1)) + 1];
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_session_activity()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND TG_TABLE_NAME = 'session_participants' THEN
        INSERT INTO session_activity_log (session_id, participant_id, activity_type, activity_data)
        VALUES (NEW.session_id, NEW.id, 'participant_joined', jsonb_build_object('status', NEW.status));
    ELSIF TG_OP = 'INSERT' AND TG_TABLE_NAME = 'session_messages' THEN
        INSERT INTO session_activity_log (session_id, participant_id, activity_type, activity_data)
        VALUES (NEW.session_id, NEW.participant_id, 'message_sent', jsonb_build_object('message_id', NEW.id, 'role', NEW.role));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_stale_deployment_locks()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM deployment_locks
    WHERE last_heartbeat < NOW() - INTERVAL '120 seconds';
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_expired_snapshots()
RETURNS INTEGER AS $$
DECLARE
    updated_count INTEGER;
BEGIN
    UPDATE deployment_snapshots
    SET status = 'expired'
    WHERE status = 'available' AND expires_at < NOW();
    
    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_system_config_change()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.value IS DISTINCT FROM NEW.value THEN
        INSERT INTO system_config_audit (
            config_id, config_key, old_value, new_value, changed_by
        ) VALUES (
            NEW.id, 
            NEW.category || '.' || NEW.key, 
            OLD.value, 
            NEW.value,
            NEW.updated_by
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_config_change()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO config_audit_log (config_id, action, old_value, new_value, changed_by, changed_at)
    VALUES (
        COALESCE(NEW.id, OLD.id),
        TG_OP,
        CASE WHEN TG_OP = 'DELETE' OR TG_OP = 'UPDATE' THEN OLD.value ELSE NULL END,
        CASE WHEN TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN NEW.value ELSE NULL END,
        COALESCE(NEW.updated_by, OLD.updated_by),
        NOW()
    );
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_or_create_user_model(p_tenant_id UUID, p_user_id UUID)
RETURNS UUID AS $$
DECLARE
    v_model_id UUID;
BEGIN
    SELECT model_id INTO v_model_id
    FROM user_mental_models
    WHERE tenant_id = p_tenant_id AND user_id = p_user_id;
    
    IF v_model_id IS NULL THEN
        INSERT INTO user_mental_models (tenant_id, user_id)
        VALUES (p_tenant_id, p_user_id)
        RETURNING model_id INTO v_model_id;
    END IF;
    
    RETURN v_model_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_model_on_interaction(p_tenant_id UUID, p_user_id UUID)
RETURNS void AS $$
BEGIN
    UPDATE user_mental_models SET
        total_interactions = total_interactions + 1,
        last_interaction = NOW(),
        updated_at = NOW()
    WHERE tenant_id = p_tenant_id AND user_id = p_user_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_prediction_accuracy(p_tenant_id UUID, p_user_id UUID, p_days INTEGER DEFAULT 30)
RETURNS TABLE(prediction_type VARCHAR, total INTEGER, correct INTEGER, accuracy DECIMAL) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        up.prediction_type,
        COUNT(*)::INTEGER as total,
        COUNT(*) FILTER (WHERE up.outcome_matched = true)::INTEGER as correct,
        (COUNT(*) FILTER (WHERE up.outcome_matched = true)::DECIMAL / NULLIF(COUNT(*), 0))::DECIMAL(5,4) as accuracy
    FROM user_predictions up
    WHERE up.tenant_id = p_tenant_id 
      AND up.user_id = p_user_id
      AND up.outcome_observed = true
      AND up.created_at > NOW() - (p_days || ' days')::INTERVAL
    GROUP BY up.prediction_type;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_active_user_goals(p_tenant_id UUID, p_user_id UUID)
RETURNS TABLE(goal_id UUID, goal_text TEXT, priority INTEGER, progress DECIMAL, goal_type VARCHAR) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ug.goal_id,
        ug.goal_text,
        ug.priority,
        ug.progress,
        ug.goal_type
    FROM user_goals ug
    WHERE ug.tenant_id = p_tenant_id 
      AND ug.user_id = p_user_id
      AND ug.is_active = true
      AND ug.status = 'active'
    ORDER BY ug.priority DESC, ug.last_mentioned DESC;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_tom_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION expire_old_predictions()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE user_predictions
    SET outcome_observed = true, outcome_matched = false, outcome_notes = 'Expired without observation'
    WHERE expires_at < NOW() AND outcome_observed IS NULL;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_plan_progress(p_plan_id UUID)
RETURNS DECIMAL AS $$
DECLARE
    v_total INTEGER;
    v_completed INTEGER;
BEGIN
    SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'completed')
    INTO v_total, v_completed
    FROM plan_tasks
    WHERE plan_id = p_plan_id AND task_type = 'primitive';
    
    IF v_total = 0 THEN RETURN 0; END IF;
    RETURN (v_completed::DECIMAL / v_total * 100);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ready_tasks(p_plan_id UUID)
RETURNS TABLE(task_id UUID, name VARCHAR, task_type VARCHAR, path TEXT) AS $$
BEGIN
    RETURN QUERY
    SELECT pt.task_id, pt.name, pt.task_type, pt.path
    FROM plan_tasks pt
    WHERE pt.plan_id = p_plan_id
      AND pt.status = 'pending'
      AND NOT EXISTS (
          SELECT 1 FROM plan_tasks dep
          WHERE dep.task_id = ANY(pt.depends_on)
            AND dep.status NOT IN ('completed', 'skipped')
      );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_task_status(
    p_task_id UUID,
    p_status VARCHAR,
    p_output TEXT DEFAULT NULL
)
RETURNS void AS $$
DECLARE
    v_plan_id UUID;
BEGIN
    -- Get plan ID
    SELECT plan_id INTO v_plan_id FROM plan_tasks WHERE task_id = p_task_id;
    
    -- Update task
    UPDATE plan_tasks SET
        status = p_status,
        output = COALESCE(p_output, output),
        completed_at = CASE WHEN p_status IN ('completed', 'failed', 'skipped') THEN NOW() ELSE completed_at END,
        success = CASE WHEN p_status = 'completed' THEN true WHEN p_status = 'failed' THEN false ELSE success END,
        updated_at = NOW()
    WHERE task_id = p_task_id;
    
    -- Update blocked tasks if this one completed
    IF p_status = 'completed' THEN
        UPDATE plan_tasks SET
            status = 'pending',
            updated_at = NOW()
        WHERE plan_id = v_plan_id
          AND status = 'blocked'
          AND p_task_id = ANY(depends_on)
          AND NOT EXISTS (
              SELECT 1 FROM plan_tasks dep
              WHERE dep.task_id = ANY(depends_on)
                AND dep.task_id != p_task_id
                AND dep.status NOT IN ('completed', 'skipped')
          );
    END IF;
    
    -- Update plan progress
    UPDATE task_plans SET
        progress = calculate_plan_progress(v_plan_id),
        completed_tasks = (SELECT COUNT(*) FROM plan_tasks WHERE plan_id = v_plan_id AND status = 'completed'),
        updated_at = NOW()
    WHERE plan_id = v_plan_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION start_plan_session(p_plan_id UUID, p_user_id UUID)
RETURNS UUID AS $$
DECLARE
    v_session_id UUID;
    v_progress DECIMAL;
BEGIN
    SELECT progress INTO v_progress FROM task_plans WHERE plan_id = p_plan_id;
    
    INSERT INTO plan_sessions (plan_id, tenant_id, user_id, progress_at_start, session_context)
    SELECT p_plan_id, tenant_id, p_user_id, v_progress,
           jsonb_build_object('ready_tasks', (SELECT array_agg(task_id) FROM get_ready_tasks(p_plan_id)))
    FROM task_plans WHERE plan_id = p_plan_id
    RETURNING session_id INTO v_session_id;
    
    -- Update plan
    UPDATE task_plans SET
        sessions_count = sessions_count + 1,
        last_session_id = v_session_id,
        status = CASE WHEN status = 'draft' THEN 'active' ELSE status END,
        started_at = COALESCE(started_at, NOW()),
        updated_at = NOW()
    WHERE plan_id = p_plan_id;
    
    RETURN v_session_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION end_plan_session(
    p_session_id UUID,
    p_next_steps JSONB DEFAULT '[]',
    p_notes TEXT DEFAULT NULL
)
RETURNS void AS $$
DECLARE
    v_plan_id UUID;
    v_progress DECIMAL;
BEGIN
    SELECT plan_id INTO v_plan_id FROM plan_sessions WHERE session_id = p_session_id;
    SELECT progress INTO v_progress FROM task_plans WHERE plan_id = v_plan_id;
    
    UPDATE plan_sessions SET
        ended_at = NOW(),
        duration_mins = EXTRACT(EPOCH FROM (NOW() - started_at)) / 60,
        progress_at_end = v_progress,
        tasks_completed = (
            SELECT COUNT(*) FROM plan_tasks
            WHERE plan_id = v_plan_id AND status = 'completed'
              AND completed_at >= (SELECT started_at FROM plan_sessions WHERE session_id = p_session_id)
        ),
        next_steps = p_next_steps,
        session_notes = p_notes,
        next_session_context = jsonb_build_object(
            'progress', v_progress,
            'ready_tasks', (SELECT array_agg(task_id) FROM get_ready_tasks(v_plan_id)),
            'blockers', (SELECT blockers FROM task_plans WHERE plan_id = v_plan_id)
        )
    WHERE session_id = p_session_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_plan_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_task_status_change()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO plan_execution_log (plan_id, task_id, tenant_id, event_type, event_details, triggered_by)
        VALUES (
            NEW.plan_id,
            NEW.task_id,
            NEW.tenant_id,
            'task_' || NEW.status,
            jsonb_build_object('previous_status', OLD.status, 'new_status', NEW.status, 'output', NEW.output),
            'system'
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_ego_daily_metrics()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO ego_metrics_daily (
    tenant_id, metric_date,
    total_stimuli, direct_responses, external_recruitments,
    clarification_requests, deferrals
  )
  VALUES (
    NEW.tenant_id,
    DATE(NEW.created_at),
    1,
    CASE WHEN NEW.decision_type = 'respond_directly' THEN 1 ELSE 0 END,
    CASE WHEN NEW.decision_type = 'recruit_external' THEN 1 ELSE 0 END,
    CASE WHEN NEW.decision_type = 'clarify' THEN 1 ELSE 0 END,
    CASE WHEN NEW.decision_type = 'defer' THEN 1 ELSE 0 END
  )
  ON CONFLICT (tenant_id, metric_date) DO UPDATE SET
    total_stimuli = ego_metrics_daily.total_stimuli + 1,
    direct_responses = ego_metrics_daily.direct_responses + 
      CASE WHEN NEW.decision_type = 'respond_directly' THEN 1 ELSE 0 END,
    external_recruitments = ego_metrics_daily.external_recruitments + 
      CASE WHEN NEW.decision_type = 'recruit_external' THEN 1 ELSE 0 END,
    clarification_requests = ego_metrics_daily.clarification_requests + 
      CASE WHEN NEW.decision_type = 'clarify' THEN 1 ELSE 0 END,
    deferrals = ego_metrics_daily.deferrals + 
      CASE WHEN NEW.decision_type = 'defer' THEN 1 ELSE 0 END,
    total_ego_tokens = ego_metrics_daily.total_ego_tokens + 
      COALESCE(NEW.ego_input_tokens, 0) + COALESCE(NEW.ego_output_tokens, 0),
    total_recruited_tokens = ego_metrics_daily.total_recruited_tokens + 
      COALESCE(NEW.recruited_input_tokens, 0) + COALESCE(NEW.recruited_output_tokens, 0),
    total_thoughts_generated = ego_metrics_daily.total_thoughts_generated + 
      COALESCE(NEW.thoughts_generated, 0),
    updated_at = NOW();
    
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ego_decision_stats(
  p_tenant_id UUID,
  p_days INTEGER DEFAULT 30
)
RETURNS TABLE (
  decision_type TEXT,
  count BIGINT,
  avg_confidence DECIMAL,
  avg_latency_ms DECIMAL,
  satisfaction_rate DECIMAL
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    e.decision_type,
    COUNT(*)::BIGINT,
    AVG(e.decision_confidence)::DECIMAL,
    AVG(e.total_duration_ms)::DECIMAL,
    AVG(CASE WHEN e.user_satisfied THEN 1 ELSE 0 END)::DECIMAL
  FROM ego_activity_log e
  WHERE e.tenant_id = p_tenant_id
    AND e.created_at > NOW() - (p_days || ' days')::INTERVAL
  GROUP BY e.decision_type;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_library_proficiencies(p_library_id VARCHAR)
RETURNS JSONB AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'reasoning_depth', reasoning_depth,
    'mathematical_quantitative', mathematical_quantitative,
    'code_generation', code_generation,
    'creative_generative', creative_generative,
    'research_synthesis', research_synthesis,
    'factual_recall_precision', factual_recall_precision,
    'multi_step_problem_solving', multi_step_problem_solving,
    'domain_terminology_handling', domain_terminology_handling
  ) INTO result
  FROM open_source_libraries
  WHERE library_id = p_library_id;
  
  RETURN result;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to calculate proficiency match score
CREATE OR REPLACE FUNCTION calculate_proficiency_match(
  p_library_id VARCHAR,
  p_required_proficiencies JSONB,
  p_weights JSONB DEFAULT '{}'
) RETURNS DECIMAL AS $$
DECLARE
  lib_profs JSONB;
  dimension TEXT;
  required_score INTEGER;
  lib_score INTEGER;
  weight DECIMAL;
  total_weight DECIMAL := 0;
  weighted_sum DECIMAL := 0;
  dimensions TEXT[] := ARRAY[
    'reasoning_depth', 'mathematical_quantitative', 'code_generation',
    'creative_generative', 'research_synthesis', 'factual_recall_precision',
    'multi_step_problem_solving', 'domain_terminology_handling'
  ];
BEGIN
  lib_profs := get_library_proficiencies(p_library_id);
  
  FOREACH dimension IN ARRAY dimensions LOOP
    IF p_required_proficiencies ? dimension THEN
      required_score := (p_required_proficiencies ->> dimension)::INTEGER;
      lib_score := (lib_profs ->> dimension)::INTEGER;
      weight := COALESCE((p_weights ->> dimension)::DECIMAL, 1.0);
      
      -- Score: how well library meets or exceeds requirement (0-1)
      weighted_sum := weighted_sum + (
        LEAST(lib_score::DECIMAL / GREATEST(required_score, 1), 1.0) * weight
      );
      total_weight := total_weight + weight;
    END IF;
  END LOOP;
  
  IF total_weight = 0 THEN
    RETURN 1.0; -- No requirements = perfect match
  END IF;
  
  RETURN weighted_sum / total_weight;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to find matching libraries
CREATE OR REPLACE FUNCTION find_matching_libraries(
  p_tenant_id UUID,
  p_required_proficiencies JSONB,
  p_domains JSONB DEFAULT NULL,
  p_categories JSONB DEFAULT NULL,
  p_min_match DECIMAL DEFAULT 0.5,
  p_limit INTEGER DEFAULT 10
) RETURNS TABLE (
  library_id VARCHAR,
  name VARCHAR,
  category VARCHAR,
  match_score DECIMAL,
  proficiency_match DECIMAL,
  domain_match DECIMAL
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    l.library_id,
    l.name,
    l.category,
    (
      calculate_proficiency_match(l.library_id, p_required_proficiencies, 
        COALESCE((SELECT proficiency_weights FROM library_registry_config WHERE tenant_id = p_tenant_id), '{}'::JSONB)
      ) * 0.7 +
      CASE 
        WHEN p_domains IS NULL THEN 1.0
        WHEN l.domains ?| ARRAY(SELECT jsonb_array_elements_text(p_domains)) THEN 1.0
        WHEN l.domains ? 'all' THEN 0.8
        ELSE 0.3
      END * 0.3
    )::DECIMAL as match_score,
    calculate_proficiency_match(l.library_id, p_required_proficiencies, '{}')::DECIMAL as proficiency_match,
    CASE 
      WHEN p_domains IS NULL THEN 1.0
      WHEN l.domains ?| ARRAY(SELECT jsonb_array_elements_text(p_domains)) THEN 1.0
      WHEN l.domains ? 'all' THEN 0.8
      ELSE 0.3
    END::DECIMAL as domain_match
  FROM open_source_libraries l
  LEFT JOIN tenant_library_overrides o ON l.library_id = o.library_id AND o.tenant_id = p_tenant_id
  WHERE 
    COALESCE(o.enabled, true) = true
    AND (p_categories IS NULL OR l.category = ANY(ARRAY(SELECT jsonb_array_elements_text(p_categories))))
    AND l.library_id NOT IN (
      SELECT jsonb_array_elements_text(disabled_libraries)
      FROM library_registry_config
      WHERE tenant_id = p_tenant_id
    )
  HAVING (
    calculate_proficiency_match(l.library_id, p_required_proficiencies, '{}') * 0.7 +
    CASE 
      WHEN p_domains IS NULL THEN 1.0
      WHEN l.domains ?| ARRAY(SELECT jsonb_array_elements_text(p_domains)) THEN 1.0
      WHEN l.domains ? 'all' THEN 0.8
      ELSE 0.3
    END * 0.3
  ) >= p_min_match
  ORDER BY match_score DESC
  LIMIT p_limit;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to record library usage
CREATE OR REPLACE FUNCTION record_library_usage(
  p_tenant_id UUID,
  p_user_id UUID,
  p_library_id VARCHAR,
  p_invocation_type VARCHAR,
  p_success BOOLEAN,
  p_execution_time_ms INTEGER,
  p_error_message TEXT DEFAULT NULL,
  p_conversation_id UUID DEFAULT NULL,
  p_request_id UUID DEFAULT NULL,
  p_prompt_domain VARCHAR DEFAULT NULL,
  p_match_score DECIMAL DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
  v_event_id UUID;
BEGIN
  -- Insert event
  INSERT INTO library_usage_events (
    tenant_id, user_id, library_id, invocation_type, success,
    execution_time_ms, error_message, conversation_id, request_id,
    prompt_domain, match_score
  ) VALUES (
    p_tenant_id, p_user_id, p_library_id, p_invocation_type, p_success,
    p_execution_time_ms, p_error_message, p_conversation_id, p_request_id,
    p_prompt_domain, p_match_score
  ) RETURNING event_id INTO v_event_id;
  
  -- Update aggregates
  INSERT INTO library_usage_aggregates (
    tenant_id, library_id, total_invocations, successful_invocations,
    failed_invocations, total_execution_time_ms, invocations_by_type, last_used_at
  ) VALUES (
    p_tenant_id, p_library_id, 1,
    CASE WHEN p_success THEN 1 ELSE 0 END,
    CASE WHEN p_success THEN 0 ELSE 1 END,
    COALESCE(p_execution_time_ms, 0),
    jsonb_build_object(p_invocation_type, 1),
    NOW()
  )
  ON CONFLICT (tenant_id, library_id) DO UPDATE SET
    total_invocations = library_usage_aggregates.total_invocations + 1,
    successful_invocations = library_usage_aggregates.successful_invocations + 
      CASE WHEN p_success THEN 1 ELSE 0 END,
    failed_invocations = library_usage_aggregates.failed_invocations + 
      CASE WHEN p_success THEN 0 ELSE 1 END,
    total_execution_time_ms = library_usage_aggregates.total_execution_time_ms + 
      COALESCE(p_execution_time_ms, 0),
    invocations_by_type = library_usage_aggregates.invocations_by_type || 
      jsonb_build_object(
        p_invocation_type, 
        COALESCE((library_usage_aggregates.invocations_by_type ->> p_invocation_type)::INTEGER, 0) + 1
      ),
    last_used_at = NOW(),
    updated_at = NOW();
  
  RETURN v_event_id;
END;
$$ LANGUAGE plpgsql;

