$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_ethics_training_data(p_tenant_id TEXT)
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER := 0;
    retention_days INTEGER;
BEGIN
    -- Get retention policy
    SELECT feedback_retention_days INTO retention_days
    FROM ethics_free_reasoning_config
    WHERE tenant_id = p_tenant_id;
    
    IF retention_days IS NULL THEN
        retention_days := 90;
    END IF;
    
    -- Delete old feedback that has been used for training
    DELETE FROM ethics_training_feedback
    WHERE tenant_id = p_tenant_id
      AND used_for_training = true
      AND created_at < NOW() - (retention_days || ' days')::INTERVAL;
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    -- Delete old thoughts
    DELETE FROM ethics_free_thoughts
    WHERE tenant_id = p_tenant_id
      AND created_at < NOW() - (retention_days || ' days')::INTERVAL;
    
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION find_similar_audit_entries(
  p_tenant_id UUID,
  p_query_embedding vector(1536),
  p_limit INTEGER DEFAULT 10,
  p_min_similarity FLOAT DEFAULT 0.7
)
RETURNS TABLE (
  id UUID,
  entry_type VARCHAR(50),
  entry_content JSONB,
  timestamp TIMESTAMPTZ,
  similarity FLOAT
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    a.id,
    a.entry_type,
    a.entry_content,
    a.timestamp,
    (1 - (a.embedding <=> p_query_embedding))::FLOAT AS similarity
  FROM cato_audit_trail a
  WHERE a.tenant_id = p_tenant_id
    AND a.embedding IS NOT NULL
    AND (1 - (a.embedding <=> p_query_embedding)) >= p_min_similarity
  ORDER BY a.embedding <=> p_query_embedding
  LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_recovery_effectiveness(
  p_tenant_id UUID,
  p_time_window INTERVAL DEFAULT '7 days'
)
RETURNS TABLE (
  strategy_type VARCHAR(50),
  total_attempts BIGINT,
  resolved_count BIGINT,
  resolution_rate NUMERIC(5,2),
  avg_attempts_to_resolve NUMERIC(5,2)
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.strategy_type,
    COUNT(*) AS total_attempts,
    COUNT(*) FILTER (WHERE r.resolved = TRUE) AS resolved_count,
    ROUND(100.0 * COUNT(*) FILTER (WHERE r.resolved = TRUE) / NULLIF(COUNT(*), 0), 2) AS resolution_rate,
    ROUND(AVG(r.attempt) FILTER (WHERE r.resolved = TRUE), 2) AS avg_attempts_to_resolve
  FROM cato_epistemic_recovery r
  WHERE r.tenant_id = p_tenant_id
    AND r.timestamp > NOW() - p_time_window
  GROUP BY r.strategy_type
  ORDER BY total_attempts DESC;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_cato_safety_metrics(
  p_tenant_id UUID,
  p_time_window INTERVAL DEFAULT '24 hours'
)
RETURNS TABLE (
  metric_name TEXT,
  metric_value BIGINT
) AS $$
BEGIN
  RETURN QUERY
  
  -- CBF Violations
  SELECT 'cbf_violations_total'::TEXT, COUNT(*)::BIGINT
  FROM cato_cbf_violations WHERE tenant_id = p_tenant_id AND timestamp > NOW() - p_time_window
  
  UNION ALL
  
  SELECT 'cbf_violations_critical'::TEXT, COUNT(*)::BIGINT
  FROM cato_cbf_violations WHERE tenant_id = p_tenant_id AND timestamp > NOW() - p_time_window AND is_critical = TRUE
  
  UNION ALL
  
  -- Recovery Events
  SELECT 'recovery_events'::TEXT, COUNT(*)::BIGINT
  FROM cato_epistemic_recovery WHERE tenant_id = p_tenant_id AND timestamp > NOW() - p_time_window
  
  UNION ALL
  
  -- Human Escalations
  SELECT 'escalations_pending'::TEXT, COUNT(*)::BIGINT
  FROM cato_human_escalations WHERE tenant_id = p_tenant_id AND status = 'PENDING'
  
  UNION ALL
  
  -- Governor Limitations
  SELECT 'governor_limitations'::TEXT, COUNT(*)::BIGINT
  FROM cato_governor_state WHERE tenant_id = p_tenant_id AND timestamp > NOW() - p_time_window AND was_limited = TRUE
  
  UNION ALL
  
  -- Fractures Detected
  SELECT 'fractures_detected'::TEXT, COUNT(*)::BIGINT
  FROM cato_fracture_detections WHERE tenant_id = p_tenant_id AND timestamp > NOW() - p_time_window AND has_fracture = TRUE
  
  UNION ALL
  
  -- Veto Events
  SELECT 'veto_events'::TEXT, COUNT(*)::BIGINT
  FROM cato_veto_log WHERE tenant_id = p_tenant_id AND timestamp > NOW() - p_time_window;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION detect_dependency_cycle(
  p_dependent_agent_id UUID,
  p_dependency_agent_id UUID
) RETURNS BOOLEAN AS $$
DECLARE
  v_has_cycle BOOLEAN := FALSE;
  v_visited UUID[] := ARRAY[p_dependent_agent_id];
  v_current UUID := p_dependency_agent_id;
  v_next UUID;
BEGIN
  -- BFS to detect cycle
  WHILE v_current IS NOT NULL AND NOT v_has_cycle LOOP
    -- Check if we've reached the original agent
    IF v_current = p_dependent_agent_id THEN
      v_has_cycle := TRUE;
      EXIT;
    END IF;
    
    -- Check if already visited
    IF v_current = ANY(v_visited) THEN
      EXIT;
    END IF;
    
    v_visited := array_append(v_visited, v_current);
    
    -- Get next dependency
    SELECT dependency_agent_id INTO v_next
    FROM agent_dependencies
    WHERE dependent_agent_id = v_current
      AND status = 'pending'
    LIMIT 1;
    
    v_current := v_next;
  END LOOP;
  
  RETURN v_has_cycle;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION find_similar_decisions(
  p_tenant_id UUID,
  p_question_embedding vector(1536),
  p_similarity_threshold DECIMAL DEFAULT 0.85,
  p_limit INTEGER DEFAULT 5
) RETURNS TABLE (
  decision_id UUID,
  question TEXT,
  answer TEXT,
  similarity DECIMAL
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    rd.id,
    rd.question,
    rd.answer,
    (1 - (rd.question_embedding <=> p_question_embedding))::DECIMAL AS similarity
  FROM resolved_decisions rd
  WHERE rd.tenant_id = p_tenant_id
    AND rd.is_valid = TRUE
    AND (rd.expires_at IS NULL OR rd.expires_at > NOW())
    AND (1 - (rd.question_embedding <=> p_question_embedding)) >= p_similarity_threshold
  ORDER BY rd.question_embedding <=> p_question_embedding
  LIMIT p_limit;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION acquire_resource_lock(
  p_tenant_id UUID,
  p_resource_uri VARCHAR,
  p_agent_id UUID,
  p_agent_type VARCHAR,
  p_lock_type VARCHAR,
  p_timeout_seconds INTEGER DEFAULT 300
) RETURNS TABLE (
  success BOOLEAN,
  lock_id UUID,
  wait_position INTEGER,
  holder_agent_id UUID
) AS $$
DECLARE
  v_resource_hash VARCHAR(64);
  v_existing_lock RECORD;
  v_lock_id UUID;
  v_wait_position INTEGER;
BEGIN
  v_resource_hash := encode(sha256(p_resource_uri::bytea), 'hex');
  
  -- Check for existing lock
  SELECT * INTO v_existing_lock
  FROM resource_locks
  WHERE tenant_id = p_tenant_id
    AND resource_hash = v_resource_hash
    AND released_at IS NULL
    AND expires_at > NOW()
  FOR UPDATE;
  
  IF v_existing_lock IS NULL THEN
    -- No existing lock, acquire it
    INSERT INTO resource_locks (
      tenant_id, resource_type, resource_uri, resource_hash,
      holder_agent_id, holder_agent_type, lock_type, expires_at
    ) VALUES (
      p_tenant_id,
      CASE 
        WHEN p_resource_uri LIKE 'file:%' THEN 'file'
        WHEN p_resource_uri LIKE 'db:%' THEN 'database_row'
        ELSE 'other'
      END,
      p_resource_uri,
      v_resource_hash,
      p_agent_id,
      p_agent_type,
      p_lock_type,
      NOW() + (p_timeout_seconds || ' seconds')::INTERVAL
    )
    RETURNING id INTO v_lock_id;
    
    RETURN QUERY SELECT TRUE, v_lock_id, 0::INTEGER, NULL::UUID;
  ELSE
    -- Lock exists, check compatibility
    IF v_existing_lock.lock_type = 'read' AND p_lock_type = 'read' THEN
      -- Multiple readers allowed
      RETURN QUERY SELECT TRUE, v_existing_lock.id, 0::INTEGER, v_existing_lock.holder_agent_id;
    ELSE
      -- Add to wait queue
      v_wait_position := COALESCE(array_length(v_existing_lock.wait_queue, 1), 0) + 1;
      
      UPDATE resource_locks
      SET wait_queue = array_append(wait_queue, p_agent_id)
      WHERE id = v_existing_lock.id;
      
      RETURN QUERY SELECT FALSE, v_existing_lock.id, v_wait_position, v_existing_lock.holder_agent_id;
    END IF;
  END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION release_resource_lock(
  p_lock_id UUID,
  p_agent_id UUID
) RETURNS TABLE (
  success BOOLEAN,
  next_agent_id UUID
) AS $$
DECLARE
  v_lock RECORD;
  v_next_agent UUID;
BEGIN
  SELECT * INTO v_lock
  FROM resource_locks
  WHERE id = p_lock_id
    AND holder_agent_id = p_agent_id
    AND released_at IS NULL
  FOR UPDATE;
  
  IF v_lock IS NULL THEN
    RETURN QUERY SELECT FALSE, NULL::UUID;
    RETURN;
  END IF;
  
  -- Get next agent from wait queue
  IF array_length(v_lock.wait_queue, 1) > 0 THEN
    v_next_agent := v_lock.wait_queue[1];
  END IF;
  
  -- Release the lock
  UPDATE resource_locks
  SET released_at = NOW(),
      wait_queue = wait_queue[2:array_length(wait_queue, 1)]
  WHERE id = p_lock_id;
  
  RETURN QUERY SELECT TRUE, v_next_agent;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_blackboard_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_resolved_decision_event()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO blackboard_events (tenant_id, event_type, decision_id, details)
    VALUES (NEW.tenant_id, 'answer_provided', NEW.id, 
      jsonb_build_object('question', NEW.question, 'answer_source', NEW.answer_source));
  ELSIF TG_OP = 'UPDATE' AND OLD.is_valid = TRUE AND NEW.is_valid = FALSE THEN
    INSERT INTO blackboard_events (tenant_id, event_type, decision_id, details)
    VALUES (NEW.tenant_id, 'answer_invalidated', NEW.id,
      jsonb_build_object('reason', NEW.invalidation_reason, 'invalidated_by', NEW.invalidated_by));
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION is_ghost_expired(
    p_updated_at TIMESTAMPTZ,
    p_ttl_seconds INTEGER
) RETURNS BOOLEAN AS $$
BEGIN
    IF p_ttl_seconds IS NULL OR p_ttl_seconds <= 0 THEN
        RETURN FALSE; -- No TTL means never expires
    END IF;
    RETURN p_updated_at + (p_ttl_seconds || ' seconds')::interval < NOW();
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Function to calculate semantic similarity (placeholder - real impl uses pgvector)
CREATE OR REPLACE FUNCTION ghost_semantic_match(
    p_tenant_id UUID,
    p_semantic_key TEXT,
    p_threshold FLOAT DEFAULT 0.85
) RETURNS TABLE (
    ghost_id UUID,
    user_id UUID,
    semantic_key TEXT,
    similarity FLOAT,
    domain_hint VARCHAR(50),
    ttl_seconds INTEGER,
    updated_at TIMESTAMPTZ
) AS $$
BEGIN
    -- Simple exact match for now; pgvector would use cosine similarity
    RETURN QUERY
    SELECT 
        gv.id AS ghost_id,
        gv.user_id::UUID,
        gv.semantic_key,
        1.0::FLOAT AS similarity,
        gv.domain_hint,
        gv.ttl_seconds,
        gv.updated_at
    FROM ghost_vectors gv
    WHERE gv.tenant_id = p_tenant_id
      AND gv.semantic_key = p_semantic_key
      AND NOT is_ghost_expired(gv.updated_at, gv.ttl_seconds)
    LIMIT 1;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to record cognitive routing decision
CREATE OR REPLACE FUNCTION record_cognitive_routing(
    p_tenant_id UUID,
    p_session_id UUID,
    p_query_hash VARCHAR(64),
    p_query_preview TEXT,
    p_complexity_score FLOAT,
    p_original_model VARCHAR(100),
    p_selected_model VARCHAR(100),
    p_routing_reason TEXT,
    p_retrieval_confidence FLOAT,
    p_ghost_hit BOOLEAN,
    p_semantic_key_matched TEXT,
    p_route_type VARCHAR(20),
    p_estimated_cost_cents FLOAT,
    p_routing_latency_ms INTEGER
) RETURNS UUID AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO cognitive_routing_decisions (
        tenant_id, session_id, query_hash, query_preview,
        complexity_score, original_model, selected_model, routing_reason,
        retrieval_confidence, ghost_hit, semantic_key_matched,
        route_type, estimated_cost_cents, routing_latency_ms
    ) VALUES (
        p_tenant_id, p_session_id, p_query_hash, p_query_preview,
        p_complexity_score, p_original_model, p_selected_model, p_routing_reason,
        p_retrieval_confidence, p_ghost_hit, p_semantic_key_matched,
        p_route_type, p_estimated_cost_cents, p_routing_latency_ms
    ) RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_circuit_breaker(
    p_tenant_id UUID,
    p_endpoint_type VARCHAR(50),
    p_endpoint_id VARCHAR(100),
    p_success BOOLEAN,
    p_latency_ms INTEGER DEFAULT NULL
) RETURNS TABLE (
    new_state VARCHAR(20),
    should_allow BOOLEAN
) AS $$
DECLARE
    v_record cognitive_circuit_breakers%ROWTYPE;
    v_new_state VARCHAR(20);
    v_should_allow BOOLEAN := TRUE;
BEGIN
    -- Get or create circuit breaker record
    SELECT * INTO v_record
    FROM cognitive_circuit_breakers
    WHERE tenant_id = p_tenant_id 
      AND endpoint_type = p_endpoint_type 
      AND endpoint_id = p_endpoint_id
    FOR UPDATE;
    
    IF NOT FOUND THEN
        INSERT INTO cognitive_circuit_breakers (tenant_id, endpoint_type, endpoint_id)
        VALUES (p_tenant_id, p_endpoint_type, p_endpoint_id)
        RETURNING * INTO v_record;
    END IF;
    
    -- Update based on success/failure
    IF p_success THEN
        IF v_record.state = 'HALF_OPEN' THEN
            v_record.half_open_successes := v_record.half_open_successes + 1;
            IF v_record.half_open_successes >= v_record.half_open_max_requests THEN
                v_new_state := 'CLOSED';
                v_record.failure_count := 0;
            ELSE
                v_new_state := v_record.state;
            END IF;
        ELSE
            v_new_state := 'CLOSED';
            v_record.failure_count := 0;
        END IF;
        v_record.success_count := v_record.success_count + 1;
        v_record.last_success_at := NOW();
    ELSE
        v_record.failure_count := v_record.failure_count + 1;
        v_record.total_failures := v_record.total_failures + 1;
        v_record.last_failure_at := NOW();
        
        IF v_record.failure_count >= v_record.failure_threshold THEN
            v_new_state := 'OPEN';
        ELSIF v_record.state = 'HALF_OPEN' THEN
            v_new_state := 'OPEN';
        ELSE
            v_new_state := v_record.state;
        END IF;
    END IF;
    
    -- Check if OPEN circuit should transition to HALF_OPEN
    IF v_record.state = 'OPEN' AND 
       v_record.last_failure_at + (v_record.recovery_timeout_seconds || ' seconds')::interval < NOW() THEN
        v_new_state := 'HALF_OPEN';
        v_record.half_open_successes := 0;
    END IF;
    
    -- Determine if request should be allowed
    v_should_allow := v_new_state IN ('CLOSED', 'HALF_OPEN');
    
    -- Update record
    UPDATE cognitive_circuit_breakers SET
        state = COALESCE(v_new_state, state),
        failure_count = v_record.failure_count,
        success_count = v_record.success_count,
        half_open_successes = v_record.half_open_successes,
        last_failure_at = v_record.last_failure_at,
        last_success_at = v_record.last_success_at,
        total_requests = total_requests + 1,
        avg_latency_ms = CASE 
            WHEN p_latency_ms IS NOT NULL THEN 
                (COALESCE(avg_latency_ms, 0) * total_requests + p_latency_ms) / (total_requests + 1)
            ELSE avg_latency_ms
        END,
        state_changed_at = CASE WHEN COALESCE(v_new_state, state) != state THEN NOW() ELSE state_changed_at END,
        updated_at = NOW()
    WHERE id = v_record.id;
    
    RETURN QUERY SELECT COALESCE(v_new_state, v_record.state), v_should_allow;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_expired_ghosts(
    p_tenant_id UUID DEFAULT NULL,
    p_batch_size INTEGER DEFAULT 1000
) RETURNS INTEGER AS $$
DECLARE
    v_deleted INTEGER;
BEGIN
    WITH deleted AS (
        DELETE FROM ghost_vectors
        WHERE id IN (
            SELECT id FROM ghost_vectors
            WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
              AND ttl_seconds IS NOT NULL
              AND ttl_seconds > 0
              AND is_ghost_expired(updated_at, ttl_seconds)
            LIMIT p_batch_size
        )
        RETURNING id
    )
    SELECT COUNT(*) INTO v_deleted FROM deleted;
    
    RETURN v_deleted;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION emit_cognitive_metric(
    p_tenant_id UUID,
    p_metric_name VARCHAR(100),
    p_value FLOAT,
    p_unit VARCHAR(50) DEFAULT 'Count',
    p_dimensions JSONB DEFAULT '{}'::jsonb
) RETURNS UUID AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO cognitive_metrics (
        tenant_id, metric_namespace, metric_name, value, unit, dimensions
    ) VALUES (
        p_tenant_id, 'Radiant/Cognitive', p_metric_name, p_value, p_unit, p_dimensions
    ) RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_ghost_access_stats()
RETURNS TRIGGER AS $$
BEGIN
    -- This would be called when ghost is read
    UPDATE ghost_vectors 
    SET last_accessed_at = NOW(),
        access_count = access_count + 1
    WHERE id = NEW.id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_old_cognitive_metrics()
RETURNS TRIGGER AS $$
BEGIN
    DELETE FROM cognitive_metrics
    WHERE timestamp < NOW() - INTERVAL '30 days';
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_aws_monitoring_cache()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM aws_monitoring_cache WHERE expires_at < NOW();
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_free_tier_savings(p_tenant_id UUID, p_period_start DATE)
RETURNS DECIMAL AS $$
DECLARE
    total_savings DECIMAL := 0;
    lambda_savings DECIMAL;
    xray_savings DECIMAL;
BEGIN
    -- Lambda savings: $0.20 per 1M requests (first 1M free)
    SELECT LEAST(used_amount, free_tier_limit) * 0.0000002 INTO lambda_savings
    FROM aws_free_tier_usage
    WHERE tenant_id = p_tenant_id 
      AND period_start = p_period_start 
      AND service = 'Lambda' 
      AND metric = 'Invocations';
    
    -- X-Ray savings: $0.50 per 100K traces (first 100K free)
    SELECT LEAST(used_amount, free_tier_limit) * 0.000005 INTO xray_savings
    FROM aws_free_tier_usage
    WHERE tenant_id = p_tenant_id 
      AND period_start = p_period_start 
      AND service = 'X-Ray' 
      AND metric = 'Traces';
    
    total_savings := COALESCE(lambda_savings, 0) + COALESCE(xray_savings, 0);
    RETURN total_savings;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION init_free_tier_settings()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO aws_free_tier_settings (tenant_id, service, free_tier_enabled, paid_tier_enabled)
    VALUES 
        (NEW.tenant_id, 'lambda', true, false),
        (NEW.tenant_id, 'aurora', true, false),
        (NEW.tenant_id, 'xray', true, false),
        (NEW.tenant_id, 'cloudwatch', true, false),
        (NEW.tenant_id, 'cost_explorer', true, false),
        (NEW.tenant_id, 'api_gateway', true, false),
        (NEW.tenant_id, 'sqs', true, false),
        (NEW.tenant_id, 's3', true, false),
        (NEW.tenant_id, 'dynamodb', true, false),
        (NEW.tenant_id, 'sns', true, false),
        (NEW.tenant_id, 'ses', true, false)
    ON CONFLICT (tenant_id, service) DO NOTHING;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_view_analytics(
    p_tenant_id UUID,
    p_start_date TIMESTAMPTZ DEFAULT NOW() - INTERVAL '30 days',
    p_end_date TIMESTAMPTZ DEFAULT NOW()
)
RETURNS TABLE (
    view_type TEXT,
    execution_mode TEXT,
    total_count BIGINT,
    avg_cost_cents NUMERIC,
    avg_duration_ms NUMERIC,
    escalation_rate NUMERIC,
    satisfaction_rate NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        v.view_type,
        v.execution_mode,
        COUNT(*)::BIGINT AS total_count,
        AVG(v.actual_cost_cents)::NUMERIC AS avg_cost_cents,
        AVG(v.duration_ms)::NUMERIC AS avg_duration_ms,
        (COUNT(*) FILTER (WHERE v.user_escalated = TRUE)::NUMERIC / NULLIF(COUNT(*), 0)) AS escalation_rate,
        (COUNT(*) FILTER (WHERE v.user_satisfied = TRUE)::NUMERIC / NULLIF(COUNT(*) FILTER (WHERE v.user_satisfied IS NOT NULL), 0)) AS satisfaction_rate
    FROM view_state_history v
    WHERE v.tenant_id = p_tenant_id
      AND v.created_at BETWEEN p_start_date AND p_end_date
    GROUP BY v.view_type, v.execution_mode
    ORDER BY total_count DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Get escalation analytics
CREATE OR REPLACE FUNCTION get_escalation_analytics(
    p_tenant_id UUID,
    p_start_date TIMESTAMPTZ DEFAULT NOW() - INTERVAL '30 days',
    p_end_date TIMESTAMPTZ DEFAULT NOW()
)
RETURNS TABLE (
    escalation_reason TEXT,
    total_count BIGINT,
    avg_sniper_cost_cents NUMERIC,
    avg_war_room_cost_cents NUMERIC,
    success_rate NUMERIC,
    satisfaction_rate NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.escalation_reason,
        COUNT(*)::BIGINT AS total_count,
        AVG(e.sniper_cost_cents)::NUMERIC AS avg_sniper_cost_cents,
        AVG(e.war_room_cost_cents)::NUMERIC AS avg_war_room_cost_cents,
        (COUNT(*) FILTER (WHERE e.war_room_successful = TRUE)::NUMERIC / NULLIF(COUNT(*), 0)) AS success_rate,
        (COUNT(*) FILTER (WHERE e.user_satisfied = TRUE)::NUMERIC / NULLIF(COUNT(*) FILTER (WHERE e.user_satisfied IS NOT NULL), 0)) AS satisfaction_rate
    FROM execution_escalations e
    WHERE e.tenant_id = p_tenant_id
      AND e.escalated_at BETWEEN p_start_date AND p_end_date
    GROUP BY e.escalation_reason
    ORDER BY total_count DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Log a view state transition
CREATE OR REPLACE FUNCTION log_view_transition(
    p_tenant_id UUID,
    p_project_id UUID,
    p_session_id UUID,
    p_view_type TEXT,
    p_execution_mode TEXT,
    p_domain_hint TEXT DEFAULT 'general',
    p_rationale TEXT DEFAULT NULL,
    p_query_text TEXT DEFAULT NULL,
    p_estimated_cost_cents INTEGER DEFAULT 1
)
RETURNS UUID AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO view_state_history (
        tenant_id, project_id, session_id, view_type, execution_mode,
        domain_hint, rationale, query_text, query_hash, estimated_cost_cents
    ) VALUES (
        p_tenant_id, p_project_id, p_session_id, p_view_type, p_execution_mode,
        p_domain_hint, p_rationale, p_query_text, 
        CASE WHEN p_query_text IS NOT NULL THEN md5(p_query_text) ELSE NULL END,
        p_estimated_cost_cents
    )
    RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Log an escalation from Sniper to War Room
CREATE OR REPLACE FUNCTION log_escalation(
    p_tenant_id UUID,
    p_project_id UUID,
    p_session_id UUID,
    p_sniper_response_id UUID,
    p_original_query TEXT,
    p_escalation_reason TEXT,
    p_sniper_response TEXT DEFAULT NULL,
    p_sniper_cost_cents INTEGER DEFAULT NULL,
    p_additional_context TEXT DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO execution_escalations (
        tenant_id, project_id, session_id, sniper_response_id,
        original_query, escalation_reason, sniper_response,
        sniper_cost_cents, additional_context
    ) VALUES (
        p_tenant_id, p_project_id, p_session_id, p_sniper_response_id,
        p_original_query, p_escalation_reason, p_sniper_response,
        p_sniper_cost_cents, p_additional_context
    )
    RETURNING id INTO v_id;
    
    -- Update the view state history to mark as escalated
    UPDATE view_state_history 
    SET user_escalated = TRUE 
    WHERE session_id = p_session_id 
      AND created_at = (
          SELECT MAX(created_at) FROM view_state_history WHERE session_id = p_session_id
      );
    
    RETURN v_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================================
-- COMMENTS
-- ============================================================================

COMMENT ON TABLE view_state_history IS 'PROMPT-41: Tracks Polymorphic UI view morphing decisions and outcomes';
COMMENT ON TABLE execution_escalations IS 'PROMPT-41: Tracks Sniper → War Room escalations via the Gearbox';
COMMENT ON TABLE polymorphic_config IS 'PROMPT-41: Per-tenant configuration for Polymorphic UI behavior';
COMMENT ON FUNCTION get_view_analytics IS 'PROMPT-41: Returns view type analytics for a tenant';
COMMENT ON FUNCTION get_escalation_analytics IS 'PROMPT-41: Returns escalation reason analytics for a tenant';
COMMENT ON FUNCTION log_view_transition IS 'PROMPT-41: Logs a UI view transition with all metadata';
COMMENT ON FUNCTION log_escalation IS 'PROMPT-41: Logs a Sniper → War Room escalation';


-- Source: 161_liquid_interface.sql
-- RADIANT v4.18.0 - Liquid Interface Migration
-- "Don't Build the Tool. BE the Tool."
-- The chat interface morphs into the tool the user needs

-- ============================================================================
-- LIQUID SESSIONS
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_sessions (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL,
    
    -- Current state
    mode TEXT NOT NULL DEFAULT 'chat' CHECK (mode IN ('chat', 'morphed', 'transitioning', 'ejecting')),
    current_schema JSONB,
    ghost_state JSONB NOT NULL DEFAULT '{}',
    
    -- Metadata
    message_count INTEGER NOT NULL DEFAULT 0,
    morphed_at TIMESTAMP,
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_liquid_sessions_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_liquid_sessions_tenant ON liquid_sessions(tenant_id);
CREATE INDEX IF NOT EXISTS idx_liquid_sessions_user ON liquid_sessions(tenant_id, user_id);
CREATE INDEX IF NOT EXISTS idx_liquid_sessions_conversation ON liquid_sessions(conversation_id);
CREATE INDEX IF NOT EXISTS idx_liquid_sessions_mode ON liquid_sessions(mode) WHERE mode != 'chat';
CREATE INDEX IF NOT EXISTS idx_liquid_sessions_activity ON liquid_sessions(last_activity_at DESC);

-- Row Level Security
ALTER TABLE liquid_sessions ENABLE ROW LEVEL SECURITY;

CREATE POLICY liquid_sessions_tenant_isolation ON liquid_sessions
    USING (tenant_id = current_setting('app.current_tenant_id', true));

-- ============================================================================
-- GHOST STATE (Persisted UI-AI bindings)
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_ghost_state (
    session_id TEXT NOT NULL,
    context_key TEXT NOT NULL,
    value JSONB,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    PRIMARY KEY (session_id, context_key),
    CONSTRAINT fk_ghost_state_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_ghost_state_session ON liquid_ghost_state(session_id);
CREATE INDEX IF NOT EXISTS idx_ghost_state_updated ON liquid_ghost_state(updated_at DESC);

-- ============================================================================
-- GHOST EVENTS (User interactions with morphed UI)
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_ghost_events (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    
    -- Event source
    component_id TEXT NOT NULL,
    component_type TEXT NOT NULL,
    
    -- Event details
    action TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    current_state JSONB NOT NULL DEFAULT '{}',
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_ghost_events_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_ghost_events_session ON liquid_ghost_events(session_id);
CREATE INDEX IF NOT EXISTS idx_ghost_events_component ON liquid_ghost_events(component_id);
CREATE INDEX IF NOT EXISTS idx_ghost_events_action ON liquid_ghost_events(action);
CREATE INDEX IF NOT EXISTS idx_ghost_events_created ON liquid_ghost_events(created_at DESC);

-- Partition by month for performance (optional)
-- CREATE INDEX IF NOT EXISTS idx_ghost_events_created_month ON liquid_ghost_events(date_trunc('month', created_at));

-- ============================================================================
-- AI REACTIONS (AI responses to ghost events)
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_ai_reactions (
    id TEXT PRIMARY KEY,
    event_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    
    -- Reaction details
    type TEXT NOT NULL CHECK (type IN ('speak', 'update', 'morph', 'suggest')),
    message TEXT,
    state_updates JSONB,
    new_schema JSONB,
    suggestions JSONB,
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_ai_reactions_event FOREIGN KEY (event_id) REFERENCES liquid_ghost_events(id) ON DELETE CASCADE,
    CONSTRAINT fk_ai_reactions_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_ai_reactions_event ON liquid_ai_reactions(event_id);
CREATE INDEX IF NOT EXISTS idx_ai_reactions_session ON liquid_ai_reactions(session_id);
CREATE INDEX IF NOT EXISTS idx_ai_reactions_type ON liquid_ai_reactions(type);
CREATE INDEX IF NOT EXISTS idx_ai_reactions_created ON liquid_ai_reactions(created_at DESC);

-- ============================================================================
-- EJECT HISTORY (Record of app exports)
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_eject_history (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    
    -- Eject configuration
    framework TEXT NOT NULL,
    features JSONB NOT NULL DEFAULT '[]',
    file_count INTEGER NOT NULL DEFAULT 0,
    
    -- Result
    status TEXT NOT NULL DEFAULT 'success' CHECK (status IN ('success', 'partial', 'failed')),
    deploy_url TEXT,
    repo_url TEXT,
    warnings JSONB,
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_eject_history_session FOREIGN KEY (session_id) REFERENCES liquid_sessions(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_eject_history_session ON liquid_eject_history(session_id);
CREATE INDEX IF NOT EXISTS idx_eject_history_framework ON liquid_eject_history(framework);
CREATE INDEX IF NOT EXISTS idx_eject_history_created ON liquid_eject_history(created_at DESC);

-- ============================================================================
-- COMPONENT USAGE ANALYTICS
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_component_usage (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id TEXT NOT NULL,
    
    -- Component info
    component_id TEXT NOT NULL,
    component_category TEXT NOT NULL,
    
    -- Usage stats
    morph_count INTEGER NOT NULL DEFAULT 0,
    interaction_count INTEGER NOT NULL DEFAULT 0,
    eject_count INTEGER NOT NULL DEFAULT 0,
    
    -- Time tracking
    first_used_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_used_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT uk_component_usage UNIQUE (tenant_id, component_id),
    CONSTRAINT fk_component_usage_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_component_usage_tenant ON liquid_component_usage(tenant_id);
CREATE INDEX IF NOT EXISTS idx_component_usage_component ON liquid_component_usage(component_id);
CREATE INDEX IF NOT EXISTS idx_component_usage_category ON liquid_component_usage(component_category);
CREATE INDEX IF NOT EXISTS idx_component_usage_count ON liquid_component_usage(morph_count DESC);

-- Row Level Security
ALTER TABLE liquid_component_usage ENABLE ROW LEVEL SECURITY;

CREATE POLICY liquid_component_usage_tenant_isolation ON liquid_component_usage
    USING (tenant_id = current_setting('app.current_tenant_id', true));

-- ============================================================================
-- INTENT PATTERNS (Learnable intent detection)
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_intent_patterns (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id TEXT NOT NULL,
    
    -- Pattern definition
    pattern TEXT NOT NULL,
    category TEXT NOT NULL,
    confidence REAL NOT NULL DEFAULT 0.8,
    
    -- Learning metadata
    success_count INTEGER NOT NULL DEFAULT 0,
    failure_count INTEGER NOT NULL DEFAULT 0,
    last_matched_at TIMESTAMP,
    
    -- Source
    source TEXT NOT NULL DEFAULT 'system' CHECK (source IN ('system', 'learned', 'admin')),
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_intent_patterns_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_intent_patterns_tenant ON liquid_intent_patterns(tenant_id);
CREATE INDEX IF NOT EXISTS idx_intent_patterns_category ON liquid_intent_patterns(category);
CREATE INDEX IF NOT EXISTS idx_intent_patterns_confidence ON liquid_intent_patterns(confidence DESC);

-- Row Level Security
ALTER TABLE liquid_intent_patterns ENABLE ROW LEVEL SECURITY;

CREATE POLICY liquid_intent_patterns_tenant_isolation ON liquid_intent_patterns
    USING (tenant_id = current_setting('app.current_tenant_id', true));

-- ============================================================================
-- LIQUID CONFIGURATION
-- ============================================================================

CREATE TABLE IF NOT EXISTS liquid_config (
    tenant_id TEXT PRIMARY KEY,
    
    -- Feature flags
    enabled BOOLEAN NOT NULL DEFAULT true,
    auto_morph_enabled BOOLEAN NOT NULL DEFAULT true,
    eject_enabled BOOLEAN NOT NULL DEFAULT true,
    
    -- Thresholds
    morph_confidence_threshold REAL NOT NULL DEFAULT 0.85,
    auto_revert_timeout_seconds INTEGER NOT NULL DEFAULT 300,
    
    -- Limits
    max_active_sessions INTEGER NOT NULL DEFAULT 10,
    max_ghost_events_per_session INTEGER NOT NULL DEFAULT 1000,
    
    -- AI overlay defaults
    default_overlay_mode TEXT NOT NULL DEFAULT 'sidebar',
    default_overlay_position TEXT NOT NULL DEFAULT 'right',
    
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_liquid_config_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- ============================================================================
-- FUNCTIONS AND TRIGGERS
-- ============================================================================

-- Update component usage stats
CREATE OR REPLACE FUNCTION update_component_usage()
RETURNS TRIGGER AS $$
BEGIN
    -- Extract components from schema and increment usage
    IF NEW.current_schema IS NOT NULL AND NEW.mode = 'morphed' THEN
        -- This would need JSONB path queries to extract component IDs
        -- Simplified version: just increment morph count for any schema change
        INSERT INTO liquid_component_usage (tenant_id, component_id, component_category, morph_count)
        VALUES (NEW.tenant_id, 'general', 'data', 1)
        ON CONFLICT (tenant_id, component_id)
        DO UPDATE SET 
            morph_count = liquid_component_usage.morph_count + 1,
            last_used_at = CURRENT_TIMESTAMP;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_old_liquid_sessions()
RETURNS void AS $$
BEGIN
    -- Delete sessions inactive for more than 24 hours
    DELETE FROM liquid_sessions
    WHERE last_activity_at < CURRENT_TIMESTAMP - INTERVAL '24 hours'
    AND mode = 'chat';
    
    -- Archive morphed sessions older than 7 days
    UPDATE liquid_sessions
    SET mode = 'chat', current_schema = NULL
    WHERE last_activity_at < CURRENT_TIMESTAMP - INTERVAL '7 days'
    AND mode = 'morphed';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_reality_engine_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_reality_engine_expired()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER := 0;
BEGIN
    -- Delete expired predictions
    DELETE FROM precognition_predictions
    WHERE expires_at < NOW() AND status = 'ready';
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    -- Delete old auto-snapshots (keep last 100 per session)
    DELETE FROM reality_snapshots rs
    WHERE rs.is_auto_snapshot = true
      AND rs.is_bookmarked = false
      AND rs.id NOT IN (
          SELECT id FROM reality_snapshots
          WHERE session_id = rs.session_id
          ORDER BY timestamp DESC
          LIMIT 100
      );
    
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION queue_s3_cleanup()
RETURNS TRIGGER AS $$
BEGIN
    -- Queue the S3 object for deletion
    IF OLD.s3_key IS NOT NULL THEN
        INSERT INTO s3_cleanup_queue (s3_bucket, s3_key, s3_region, source_table, source_id)
        VALUES (OLD.s3_bucket, OLD.s3_key, OLD.s3_region, TG_TABLE_NAME, OLD.id);
        
        -- Also queue thumbnail if exists
        IF OLD.thumbnail_s3_key IS NOT NULL THEN
            INSERT INTO s3_cleanup_queue (s3_bucket, s3_key, s3_region, source_table, source_id)
            VALUES (OLD.s3_bucket, OLD.thumbnail_s3_key, OLD.s3_region, TG_TABLE_NAME, OLD.id);
        END IF;
    END IF;
    
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_session_tenant(p_session_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM collaborative_sessions 
        WHERE id = p_session_id 
        AND tenant_id = current_setting('app.current_tenant_id')::UUID
    );
END;
$$ LANGUAGE plpgsql STABLE;

-- Apply policies
CREATE POLICY guest_invites_isolation ON collaboration_guest_invites
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY guests_isolation ON collaboration_guests
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY facilitators_isolation ON collaboration_facilitators
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY interventions_isolation ON facilitator_interventions
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY branches_isolation ON conversation_branches
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY merge_requests_isolation ON branch_merge_requests
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY recordings_isolation ON session_recordings
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY media_notes_isolation ON session_media_notes
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY annotations_isolation ON async_annotations
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY roundtables_isolation ON ai_roundtables
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY contributions_isolation ON roundtable_contributions
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY kg_isolation ON session_knowledge_graphs
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY kg_nodes_isolation ON knowledge_graph_nodes
    FOR ALL USING (check_session_tenant(session_id));

CREATE POLICY kg_edges_isolation ON knowledge_graph_edges
    FOR ALL USING (
        graph_id IN (SELECT id FROM session_knowledge_graphs WHERE check_session_tenant(session_id))
    );

CREATE POLICY attachments_isolation ON collaboration_attachments
    FOR ALL USING (check_session_tenant(session_id));


