        "glowColor": "#A78BFA",
        "trailEffect": true,
        "fontFamily": "Inter",
        "fontSize": "md",
        "blur": true,
        "shadows": true,
        "animations": true
    }',
    
    preferences JSONB NOT NULL DEFAULT '{
        "autoFly": true,
        "smoothTransitions": true,
        "showJourneyTrail": true,
        "preCognitionEnabled": true,
        "showPredictions": true,
        "telepathyIntensity": "moderate",
