        "maxParallelRealities": 4,
        "autoCompare": true,
        "reducedMotion": false,
        "highContrast": false,
        "screenReaderMode": false
    }',
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

