    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_carpet_themes_tenant ON carpet_themes(tenant_id);
CREATE INDEX idx_carpet_themes_user ON carpet_themes(user_id);

