-- Get effective settings for a user, creating defaults if needed
CREATE OR REPLACE FUNCTION get_effective_collaboration_settings(
    p_tenant_id UUID,
    p_user_id UUID
) RETURNS TABLE (
    enable_collaborative_chat BOOLEAN,
    enable_intra_tenant_chat BOOLEAN,
    enable_guest_access BOOLEAN,
    enable_ai_facilitator BOOLEAN,
    enable_branch_merge BOOLEAN,
    enable_time_shifted_playback BOOLEAN,
    enable_ai_roundtable BOOLEAN,
    enable_knowledge_graph BOOLEAN,
    can_invite_guests BOOLEAN,
    max_guests_per_session INTEGER,
    max_participants_per_session INTEGER,
    max_branches_per_session INTEGER,
    facilitator_persona VARCHAR,
    default_guest_permission VARCHAR
) AS $$
DECLARE
    v_tenant tenant_collaboration_settings%ROWTYPE;
    v_user user_collaboration_settings%ROWTYPE;
BEGIN
    -- Get or create tenant settings
    SELECT * INTO v_tenant FROM tenant_collaboration_settings WHERE tenant_id = p_tenant_id;
    IF NOT FOUND THEN
        INSERT INTO tenant_collaboration_settings (tenant_id) VALUES (p_tenant_id)
        RETURNING * INTO v_tenant;
    END IF;
    
    -- Get or create user settings
    SELECT * INTO v_user FROM user_collaboration_settings WHERE tenant_id = p_tenant_id AND user_id = p_user_id;
    IF NOT FOUND THEN
        INSERT INTO user_collaboration_settings (tenant_id, user_id) VALUES (p_tenant_id, p_user_id)
        RETURNING * INTO v_user;
    END IF;
    
    RETURN QUERY SELECT 
        COALESCE(v_tenant.enable_collaborative_chat, true),
        COALESCE(v_tenant.enable_intra_tenant_chat, true),
        COALESCE(v_tenant.enable_guest_access, true),
        
        CASE 
            WHEN v_tenant.allow_user_override_facilitator AND v_user.enable_ai_facilitator IS NOT NULL 
            THEN v_user.enable_ai_facilitator AND COALESCE(v_tenant.enable_ai_facilitator, true)
            ELSE COALESCE(v_tenant.enable_ai_facilitator, true)
        END,
        
        CASE 
            WHEN v_tenant.allow_user_override_branch_merge AND v_user.enable_branch_merge IS NOT NULL 
            THEN v_user.enable_branch_merge AND COALESCE(v_tenant.enable_branch_merge, true)
            ELSE COALESCE(v_tenant.enable_branch_merge, true)
        END,
        
        CASE 
            WHEN v_tenant.allow_user_override_playback AND v_user.enable_time_shifted_playback IS NOT NULL 
            THEN v_user.enable_time_shifted_playback AND COALESCE(v_tenant.enable_time_shifted_playback, true)
            ELSE COALESCE(v_tenant.enable_time_shifted_playback, true)
        END,
        
        CASE 
            WHEN v_tenant.allow_user_override_roundtable AND v_user.enable_ai_roundtable IS NOT NULL 
            THEN v_user.enable_ai_roundtable AND COALESCE(v_tenant.enable_ai_roundtable, true)
            ELSE COALESCE(v_tenant.enable_ai_roundtable, true)
        END,
        
        CASE 
            WHEN v_tenant.allow_user_override_knowledge_graph AND v_user.enable_knowledge_graph IS NOT NULL 
            THEN v_user.enable_knowledge_graph AND COALESCE(v_tenant.enable_knowledge_graph, true)
            ELSE COALESCE(v_tenant.enable_knowledge_graph, true)
        END,
        
        COALESCE(v_tenant.allow_user_override_guest_invite, true),
        COALESCE(v_tenant.max_guests_per_session, 10),
        COALESCE(v_tenant.max_participants_per_session, 50),
        COALESCE(v_tenant.max_branches_per_session, 10),
        COALESCE(v_user.preferred_facilitator_persona, v_tenant.default_facilitator_persona, 'professional'),
        COALESCE(v_tenant.default_guest_permission, 'commenter');
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_collaboration_settings_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_user_violation_summary()
RETURNS TRIGGER AS $$
DECLARE
    v_summary_exists BOOLEAN;
    v_category_counts JSONB;
BEGIN
    -- Check if summary exists
    SELECT EXISTS(
        SELECT 1 FROM user_violation_summary 
        WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
        AND user_id = COALESCE(NEW.user_id, OLD.user_id)
    ) INTO v_summary_exists;
    
    -- Calculate category counts
    SELECT COALESCE(jsonb_object_agg(category, cnt), '{}')
    INTO v_category_counts
    FROM (
        SELECT category, COUNT(*) as cnt
        FROM user_violations
        WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id)
        AND user_id = COALESCE(NEW.user_id, OLD.user_id)
        GROUP BY category
    ) cats;
    
    IF v_summary_exists THEN
        UPDATE user_violation_summary SET
            total_violations = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
            ),
            active_violations = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND status NOT IN ('resolved', 'dismissed')
            ),
            resolved_violations = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND status = 'resolved'
            ),
            warning_count = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND severity = 'warning'
            ),
            minor_count = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND severity = 'minor'
            ),
            major_count = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND severity = 'major'
            ),
            critical_count = (
                SELECT COUNT(*) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND severity = 'critical'
            ),
            violations_by_category = v_category_counts,
            first_violation_at = (
                SELECT MIN(occurred_at) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
            ),
            last_violation_at = (
                SELECT MAX(occurred_at) FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
            ),
            risk_score = (
                SELECT LEAST(100.0, 
                    COALESCE(SUM(
                        CASE severity 
                            WHEN 'critical' THEN 40 
                            WHEN 'major' THEN 20 
                            WHEN 'minor' THEN 10 
                            ELSE 5 
                        END
                    ), 0)
                )
                FROM user_violations 
                WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                AND status NOT IN ('resolved', 'dismissed')
            ),
            risk_level = CASE 
                WHEN (SELECT COUNT(*) FROM user_violations 
                      WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                      AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                      AND severity = 'critical' AND status NOT IN ('resolved', 'dismissed')) > 0 THEN 'critical'
                WHEN (SELECT COUNT(*) FROM user_violations 
                      WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                      AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                      AND severity = 'major' AND status NOT IN ('resolved', 'dismissed')) >= 2 THEN 'high'
                WHEN (SELECT COUNT(*) FROM user_violations 
                      WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                      AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                      AND status NOT IN ('resolved', 'dismissed')) >= 5 THEN 'elevated'
                WHEN (SELECT COUNT(*) FROM user_violations 
                      WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
                      AND user_id = COALESCE(NEW.user_id, OLD.user_id)
                      AND status NOT IN ('resolved', 'dismissed')) >= 2 THEN 'moderate'
                ELSE 'low'
            END,
            updated_at = NOW()
        WHERE tenant_id = COALESCE(NEW.tenant_id, OLD.tenant_id) 
        AND user_id = COALESCE(NEW.user_id, OLD.user_id);
    ELSE
        INSERT INTO user_violation_summary (
            tenant_id, user_id, total_violations, active_violations, 
            violations_by_category, first_violation_at, last_violation_at,
            risk_score, risk_level
        ) VALUES (
            NEW.tenant_id, NEW.user_id, 1, 1,
            v_category_counts, NEW.occurred_at, NEW.occurred_at,
            CASE NEW.severity WHEN 'critical' THEN 40 WHEN 'major' THEN 20 WHEN 'minor' THEN 10 ELSE 5 END,
            CASE NEW.severity WHEN 'critical' THEN 'critical' WHEN 'major' THEN 'elevated' ELSE 'low' END
        );
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_thinktank_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION audit_decision_changes()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO decision_audit (decision_id, tenant_id, action, actor_type, details)
    VALUES (NEW.id, NEW.tenant_id, 'created', 'system', 
            jsonb_build_object('domain', NEW.domain, 'timeout_seconds', NEW.timeout_seconds));
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status != NEW.status THEN
      INSERT INTO decision_audit (decision_id, tenant_id, action, actor_id, actor_type, details)
      VALUES (NEW.id, NEW.tenant_id, 
              CASE NEW.status 
                WHEN 'resolved' THEN 'resolved'
                WHEN 'expired' THEN 'expired'
                WHEN 'escalated' THEN 'escalated'
                ELSE 'updated'
              END,
              NEW.resolved_by,
              CASE WHEN NEW.resolved_by IS NOT NULL THEN 'user' ELSE 'system' END,
              jsonb_build_object(
                'old_status', OLD.status, 
                'new_status', NEW.status,
                'resolution', NEW.resolution,
                'guidance', NEW.guidance
              ));
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION audit_heuristic_changes()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO audit_logs (
        tenant_id,
        action,
        resource_type,
        resource_id,
        details,
        created_at
    ) VALUES (
        COALESCE(NEW.tenant_id, OLD.tenant_id),
        TG_OP,
        'knowledge_heuristic',
        COALESCE(NEW.id, OLD.id),
        jsonb_build_object(
            'domain', COALESCE(NEW.domain, OLD.domain),
            'heuristic_preview', LEFT(COALESCE(NEW.heuristic_text, OLD.heuristic_text), 100),
            'confidence_score', COALESCE(NEW.confidence_score, OLD.confidence_score)
        ),
        NOW()
    );
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_heuristic_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_expired_idempotency_keys()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM idempotency_keys WHERE expires_at < NOW();
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION can_access_workflow(p_workflow_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
AS $$
DECLARE
    v_tenant_id UUID;
    v_is_system BOOLEAN;
BEGIN
    SELECT tenant_id, is_system_workflow
    INTO v_tenant_id, v_is_system
    FROM orchestration_workflows
    WHERE workflow_id = p_workflow_id;
    
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    
    -- System workflows are accessible to all
    IF v_is_system OR v_tenant_id IS NULL THEN
        RETURN TRUE;
    END IF;
    
    -- User workflows only accessible to their tenant
    RETURN v_tenant_id = current_setting('app.current_tenant_id', true)::uuid;
END;
$$;

-- Function to check if user can modify a workflow
CREATE OR REPLACE FUNCTION can_modify_workflow(p_workflow_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
AS $$
DECLARE
    v_tenant_id UUID;
    v_is_system BOOLEAN;
    v_created_by UUID;
BEGIN
    SELECT tenant_id, is_system_workflow, created_by
    INTO v_tenant_id, v_is_system, v_created_by
    FROM orchestration_workflows
    WHERE workflow_id = p_workflow_id;
    
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    
    -- Super admins can modify anything
    IF current_setting('app.is_super_admin', true)::boolean = true THEN
        RETURN TRUE;
    END IF;
    
    -- System workflows cannot be modified by regular users
    IF v_is_system OR v_tenant_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Tenant admins can modify any workflow in their tenant
    IF current_setting('app.is_tenant_admin', true)::boolean = true 
       AND v_tenant_id = current_setting('app.current_tenant_id', true)::uuid THEN
        RETURN TRUE;
    END IF;
    
    -- Users can only modify workflows they created
    RETURN v_tenant_id = current_setting('app.current_tenant_id', true)::uuid
           AND v_created_by = current_setting('app.current_user_id', true)::uuid;
END;
$$;

-- Function to get accessible workflows for current user
CREATE OR REPLACE FUNCTION get_accessible_workflows()
RETURNS TABLE (
    workflow_id UUID,
    workflow_code VARCHAR(100),
    common_name VARCHAR(200),
    is_system_workflow BOOLEAN,
    is_own_workflow BOOLEAN,
    can_modify BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        w.workflow_id,
        w.workflow_code,
        w.common_name,
        w.is_system_workflow,
        (w.tenant_id = current_setting('app.current_tenant_id', true)::uuid) AS is_own_workflow,
        can_modify_workflow(w.workflow_id) AS can_modify
    FROM orchestration_workflows w
    WHERE w.tenant_id IS NULL  -- System workflows
       OR w.tenant_id = current_setting('app.current_tenant_id', true)::uuid;  -- Tenant workflows
END;
$$;

-- ============================================================================
-- 9. AUDIT TRIGGER FOR WORKFLOW MODIFICATIONS
-- ============================================================================

-- Create audit table for workflow changes if it doesn't exist
CREATE TABLE IF NOT EXISTS orchestration_audit_log (
    audit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    table_name VARCHAR(100) NOT NULL,
    record_id UUID NOT NULL,
    action VARCHAR(20) NOT NULL, -- 'INSERT', 'UPDATE', 'DELETE'
    old_data JSONB,
    new_data JSONB,
    tenant_id UUID,
    user_id UUID,
    ip_address INET,
    user_agent TEXT,
    changed_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_orchestration_audit_tenant ON orchestration_audit_log(tenant_id);
CREATE INDEX IF NOT EXISTS idx_orchestration_audit_table ON orchestration_audit_log(table_name);
CREATE INDEX IF NOT EXISTS idx_orchestration_audit_record ON orchestration_audit_log(record_id);
CREATE INDEX IF NOT EXISTS idx_orchestration_audit_time ON orchestration_audit_log(changed_at);

ALTER TABLE orchestration_audit_log ENABLE ROW LEVEL SECURITY;

-- Tenants can only see audit logs for their tenant
CREATE POLICY orchestration_audit_log_tenant_isolation ON orchestration_audit_log
    FOR SELECT
    USING (
        tenant_id = current_setting('app.current_tenant_id', true)::uuid
        OR current_setting('app.is_super_admin', true)::boolean = true
    );

-- Only system can insert audit logs
CREATE POLICY orchestration_audit_log_system_insert ON orchestration_audit_log
    FOR INSERT
    WITH CHECK (true);

-- Audit function for workflow tables
CREATE OR REPLACE FUNCTION orchestration_audit_trigger()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_old_data JSONB;
    v_new_data JSONB;
    v_record_id UUID;
    v_tenant_id UUID;
BEGIN
    -- Determine record ID and tenant based on operation
    IF TG_OP = 'DELETE' THEN
        v_old_data := to_jsonb(OLD);
        v_record_id := OLD.workflow_id;
        v_tenant_id := OLD.tenant_id;
    ELSIF TG_OP = 'UPDATE' THEN
        v_old_data := to_jsonb(OLD);
        v_new_data := to_jsonb(NEW);
        v_record_id := NEW.workflow_id;
        v_tenant_id := NEW.tenant_id;
    ELSIF TG_OP = 'INSERT' THEN
        v_new_data := to_jsonb(NEW);
        v_record_id := NEW.workflow_id;
        v_tenant_id := NEW.tenant_id;
    END IF;
    
    INSERT INTO orchestration_audit_log (
        table_name,
        record_id,
        action,
        old_data,
        new_data,
        tenant_id,
        user_id,
        ip_address,
        user_agent
    ) VALUES (
        TG_TABLE_NAME,
        v_record_id,
        TG_OP,
        v_old_data,
        v_new_data,
        v_tenant_id,
        current_setting('app.current_user_id', true)::uuid,
        current_setting('app.client_ip', true)::inet,
        current_setting('app.user_agent', true)
    );
    
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        -- Don't fail the main operation if audit fails
        RAISE WARNING 'Audit logging failed: %', SQLERRM;
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        ELSE
            RETURN NEW;
        END IF;
END;
$$;

-- Apply audit trigger to workflow tables
DROP TRIGGER IF EXISTS orchestration_workflows_audit ON orchestration_workflows;
CREATE TRIGGER orchestration_workflows_audit
    AFTER INSERT OR UPDATE OR DELETE ON orchestration_workflows
    FOR EACH ROW EXECUTE FUNCTION orchestration_audit_trigger();

DROP TRIGGER IF EXISTS user_workflow_templates_audit ON user_workflow_templates;
CREATE TRIGGER user_workflow_templates_audit
    AFTER INSERT OR UPDATE OR DELETE ON user_workflow_templates
    FOR EACH ROW EXECUTE FUNCTION orchestration_audit_trigger();

DROP TRIGGER IF EXISTS workflow_customizations_audit ON workflow_customizations;
CREATE TRIGGER workflow_customizations_audit
    AFTER INSERT OR UPDATE OR DELETE ON workflow_customizations
    FOR EACH ROW EXECUTE FUNCTION orchestration_audit_trigger();

