END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION queue_s3_orphan_on_delete()
RETURNS TRIGGER AS $$
DECLARE
  v_s3_key VARCHAR;
  v_registry_id UUID;
BEGIN
  -- Check each S3 key column and queue orphans
  
  -- For thinktank_messages
  IF TG_TABLE_NAME = 'thinktank_messages' AND OLD.content_s3_key IS NOT NULL THEN
    INSERT INTO s3_orphan_queue (s3_bucket, s3_key, reason, original_registry_id)
    SELECT s.s3_bucket, s.s3_key, 'source_deleted', s.id
    FROM s3_content_registry s
    WHERE s.s3_key = OLD.content_s3_key
    ON CONFLICT (s3_bucket, s3_key) DO NOTHING;
    
    UPDATE s3_content_registry 
    SET reference_count = reference_count - 1, marked_for_deletion = true
    WHERE s3_key = OLD.content_s3_key;
  END IF;
  
  -- For memories
  IF TG_TABLE_NAME = 'memories' AND OLD.content_s3_key IS NOT NULL THEN
    INSERT INTO s3_orphan_queue (s3_bucket, s3_key, reason)
    SELECT s.s3_bucket, s.s3_key, 'source_deleted'
    FROM s3_content_registry s
    WHERE s.s3_key = OLD.content_s3_key
    ON CONFLICT (s3_bucket, s3_key) DO NOTHING;
    
    UPDATE s3_content_registry 
    SET reference_count = reference_count - 1, marked_for_deletion = true
    WHERE s3_key = OLD.content_s3_key;
  END IF;
  
  -- For learning_episodes
  IF TG_TABLE_NAME = 'learning_episodes' THEN
    IF OLD.draft_s3_key IS NOT NULL THEN
      INSERT INTO s3_orphan_queue (s3_bucket, s3_key, reason)
      SELECT s.s3_bucket, s.s3_key, 'source_deleted'
      FROM s3_content_registry s
      WHERE s.s3_key = OLD.draft_s3_key
      ON CONFLICT (s3_bucket, s3_key) DO NOTHING;
      
      UPDATE s3_content_registry 
      SET reference_count = reference_count - 1, marked_for_deletion = true
      WHERE s3_key = OLD.draft_s3_key;
    END IF;
    
    IF OLD.final_s3_key IS NOT NULL THEN
      INSERT INTO s3_orphan_queue (s3_bucket, s3_key, reason)
      SELECT s.s3_bucket, s.s3_key, 'source_deleted'
      FROM s3_content_registry s
      WHERE s.s3_key = OLD.final_s3_key
      ON CONFLICT (s3_bucket, s3_key) DO NOTHING;
      
      UPDATE s3_content_registry 
      SET reference_count = reference_count - 1, marked_for_deletion = true
      WHERE s3_key = OLD.final_s3_key;
    END IF;
  END IF;
  
  RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_orphans_for_deletion(
  p_batch_size INTEGER DEFAULT 100
)
RETURNS TABLE (
  id UUID,
  s3_bucket VARCHAR,
  s3_key VARCHAR,
  s3_version_id VARCHAR,
  reason VARCHAR
) AS $$
BEGIN
  -- Mark batch as processing
  UPDATE s3_orphan_queue
  SET deletion_status = 'processing'
  WHERE id IN (
    SELECT q.id FROM s3_orphan_queue q
    WHERE q.deletion_status = 'pending'
    AND q.delete_after <= NOW()
    ORDER BY q.queued_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  );
  
  -- Return the batch
  RETURN QUERY
  SELECT q.id, q.s3_bucket, q.s3_key, q.s3_version_id, q.reason
  FROM s3_orphan_queue q
  WHERE q.deletion_status = 'processing';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mark_orphan_deleted(
  p_id UUID,
  p_success BOOLEAN,
  p_error_message TEXT DEFAULT NULL
)
RETURNS VOID AS $$
BEGIN
  UPDATE s3_orphan_queue
  SET 
    deletion_status = CASE WHEN p_success THEN 'completed' ELSE 'failed' END,
    deleted_at = CASE WHEN p_success THEN NOW() ELSE NULL END,
    error_message = p_error_message
  WHERE id = p_id;
  
  -- If successful, also remove from registry
  IF p_success THEN
    DELETE FROM s3_content_registry
    WHERE id = (SELECT original_registry_id FROM s3_orphan_queue WHERE id = p_id);
  END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION find_existing_s3_content(
  p_tenant_id UUID,
  p_content_hash VARCHAR
)
RETURNS TABLE (
  s3_key VARCHAR,
  s3_bucket VARCHAR
) AS $$
BEGIN
  -- If content already exists, return existing key (content-addressable storage)
  RETURN QUERY
  SELECT r.s3_key, r.s3_bucket
  FROM s3_content_registry r
  WHERE r.tenant_id = p_tenant_id
  AND r.content_hash = p_content_hash
  AND r.marked_for_deletion = false
  LIMIT 1;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_persistence_integrity(p_tenant_id UUID)
RETURNS TABLE (
  table_name VARCHAR,
  total_records BIGINT,
  complete_records BIGINT,
  incomplete_records BIGINT,
  integrity_score DECIMAL(5,2)
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pr.table_name,
    COUNT(*)::BIGINT as total_records,
    COUNT(*) FILTER (WHERE pr.is_complete = true)::BIGINT as complete_records,
    COUNT(*) FILTER (WHERE pr.is_complete = false)::BIGINT as incomplete_records,
    CASE 
      WHEN COUNT(*) = 0 THEN 100.00
      ELSE ROUND((COUNT(*) FILTER (WHERE pr.is_complete = true)::DECIMAL / COUNT(*)) * 100, 2)
    END as integrity_score
  FROM persistence_records pr
  WHERE pr.tenant_id = p_tenant_id
  GROUP BY pr.table_name;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION recover_incomplete_transactions(p_tenant_id UUID)
RETURNS TABLE (
  transaction_id VARCHAR,
  status VARCHAR,
  operations_count INTEGER
) AS $$
BEGIN
  -- Find and mark incomplete transactions
  UPDATE persistence_wal
  SET status = 'recovered', completed_at = NOW()
  WHERE tenant_id = p_tenant_id AND status = 'prepare';
  
  -- Mark affected records as incomplete
  UPDATE persistence_records pr
  SET is_complete = false
  WHERE pr.tenant_id = p_tenant_id
  AND EXISTS (
    SELECT 1 FROM persistence_wal pw
    WHERE pw.tenant_id = p_tenant_id
    AND pw.status = 'recovered'
    AND pw.operations::text LIKE '%' || pr.record_id || '%'
  );
  
  RETURN QUERY
  SELECT 
    pw.transaction_id::VARCHAR,
    'recovered'::VARCHAR,
    COALESCE(jsonb_array_length(pw.operations), 0)::INTEGER
  FROM persistence_wal pw
  WHERE pw.tenant_id = p_tenant_id
  AND pw.status = 'recovered'
  AND pw.completed_at >= NOW() - INTERVAL '1 minute';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_complete_records(
  p_tenant_id UUID,
  p_table_name VARCHAR
)
RETURNS TABLE (
  record_id VARCHAR,
  data JSONB,
  checksum VARCHAR,
  updated_at TIMESTAMPTZ
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pr.record_id::VARCHAR,
    pr.data,
    pr.checksum::VARCHAR,
    pr.updated_at
  FROM persistence_records pr
  WHERE pr.tenant_id = p_tenant_id
  AND pr.table_name = p_table_name
  AND pr.is_complete = true
  ORDER BY pr.updated_at DESC;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_persistence_data(p_retention_days INTEGER DEFAULT 30)
RETURNS TABLE (
  wal_deleted INTEGER,
  logs_deleted INTEGER
) AS $$
DECLARE
  v_wal_deleted INTEGER;
  v_logs_deleted INTEGER;
BEGIN
  -- Clean up old committed/recovered WAL entries
  DELETE FROM persistence_wal 
  WHERE status IN ('commit', 'rollback', 'recovered')
  AND completed_at < NOW() - (p_retention_days || ' days')::INTERVAL;
  GET DIAGNOSTICS v_wal_deleted = ROW_COUNT;
  
  -- Clean up old info-level integrity logs
  DELETE FROM persistence_integrity_log
  WHERE severity = 'info'
  AND created_at < NOW() - (p_retention_days || ' days')::INTERVAL;
  GET DIAGNOSTICS v_logs_deleted = ROW_COUNT;
  
  RETURN QUERY SELECT v_wal_deleted, v_logs_deleted;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_persistence_record_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_next_run(
  p_schedule VARCHAR,
  p_schedule_time TIME,
  p_schedule_day_of_week INTEGER,
  p_schedule_day_of_month INTEGER,
  p_timezone VARCHAR
) RETURNS TIMESTAMPTZ AS $$
DECLARE
  v_now TIMESTAMPTZ := NOW();
  v_next TIMESTAMPTZ;
  v_today DATE := (v_now AT TIME ZONE COALESCE(p_timezone, 'UTC'))::DATE;
BEGIN
  CASE p_schedule
    WHEN 'manual' THEN
      RETURN NULL;
    WHEN 'daily' THEN
      v_next := (v_today + INTERVAL '1 day' + p_schedule_time) AT TIME ZONE COALESCE(p_timezone, 'UTC');
      IF v_next <= v_now THEN
        v_next := v_next + INTERVAL '1 day';
      END IF;
    WHEN 'weekly' THEN
      v_next := (v_today + ((7 + COALESCE(p_schedule_day_of_week, 1) - EXTRACT(DOW FROM v_today)::INTEGER) % 7) * INTERVAL '1 day' + p_schedule_time) AT TIME ZONE COALESCE(p_timezone, 'UTC');
      IF v_next <= v_now THEN
        v_next := v_next + INTERVAL '7 days';
      END IF;
    WHEN 'monthly' THEN
      v_next := (DATE_TRUNC('month', v_today) + (COALESCE(p_schedule_day_of_month, 1) - 1) * INTERVAL '1 day' + p_schedule_time) AT TIME ZONE COALESCE(p_timezone, 'UTC');
      IF v_next <= v_now THEN
        v_next := (DATE_TRUNC('month', v_today) + INTERVAL '1 month' + (COALESCE(p_schedule_day_of_month, 1) - 1) * INTERVAL '1 day' + p_schedule_time) AT TIME ZONE COALESCE(p_timezone, 'UTC');
      END IF;
    WHEN 'quarterly' THEN
      v_next := (DATE_TRUNC('quarter', v_today) + INTERVAL '3 months' + (COALESCE(p_schedule_day_of_month, 1) - 1) * INTERVAL '1 day' + p_schedule_time) AT TIME ZONE COALESCE(p_timezone, 'UTC');
    ELSE
      RETURN NULL;
  END CASE;
  
  RETURN v_next;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_due_reports()
RETURNS TABLE (
  id UUID,
  tenant_id UUID,
  name VARCHAR,
  report_type VARCHAR,
  format VARCHAR,
  parameters JSONB,
  recipients JSONB,
  template_id UUID
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.id,
    r.tenant_id,
    r.name,
    r.report_type,
    r.format,
    r.parameters,
    r.recipients,
    r.template_id
  FROM admin_reports r
  WHERE r.status = 'active'
  AND r.schedule != 'manual'
  AND r.next_run_at IS NOT NULL
  AND r.next_run_at <= NOW()
  AND (r.last_run_status IS NULL OR r.last_run_status != 'running')
  ORDER BY r.next_run_at ASC
  LIMIT 50;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_report_after_run(
  p_report_id UUID,
  p_status VARCHAR,
  p_error TEXT DEFAULT NULL
) RETURNS VOID AS $$
BEGIN
  UPDATE admin_reports
  SET 
    last_run_at = NOW(),
    last_run_status = p_status,
    last_run_error = p_error,
    run_count = run_count + 1,
    next_run_at = calculate_next_run(schedule, schedule_time, schedule_day_of_week, schedule_day_of_month, schedule_timezone),
    updated_at = NOW()
  WHERE id = p_report_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trigger_calculate_next_run()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.schedule != 'manual' AND NEW.status = 'active' THEN
    NEW.next_run_at := calculate_next_run(
      NEW.schedule, 
      NEW.schedule_time, 
      NEW.schedule_day_of_week, 
      NEW.schedule_day_of_month,
      NEW.schedule_timezone
    );
  ELSE
    NEW.next_run_at := NULL;
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

