$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION auto_compute_artifact_hash_on_freeze()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.status = 'frozen' AND OLD.status != 'frozen' THEN
        NEW.content_hash = encode(sha256(NEW.artifact_content::text::bytea), 'hex');
        NEW.signature_timestamp = NOW();
        NEW.frozen_at = NOW();
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_decision_artifact_version(
    p_artifact_id UUID,
    p_new_content JSONB,
    p_user_id UUID
) RETURNS UUID AS $$
DECLARE
    v_new_id UUID;
    v_current_version INT;
    v_conversation_id UUID;
    v_tenant_id UUID;
    v_title VARCHAR(500);
    v_miner_model VARCHAR(100);
    v_compliance_frameworks TEXT[];
    v_primary_domain VARCHAR(100);
BEGIN
    -- Get current artifact data
    SELECT version, conversation_id, tenant_id, title, miner_model, 
           compliance_frameworks, primary_domain
    INTO v_current_version, v_conversation_id, v_tenant_id, v_title, 
         v_miner_model, v_compliance_frameworks, v_primary_domain
    FROM decision_artifacts
    WHERE id = p_artifact_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Artifact not found: %', p_artifact_id;
    END IF;
    
    -- Freeze current version
    UPDATE decision_artifacts
    SET status = 'frozen',
        frozen_at = NOW(),
        frozen_by = p_user_id
    WHERE id = p_artifact_id;
    
    -- Create new version
    INSERT INTO decision_artifacts (
        conversation_id, user_id, tenant_id, title,
        artifact_content, parent_artifact_id, version,
        status, miner_model, compliance_frameworks, primary_domain,
        extraction_timestamp
    )
    VALUES (
        v_conversation_id, p_user_id, v_tenant_id, v_title,
        p_new_content, p_artifact_id, v_current_version + 1,
        'active', v_miner_model, v_compliance_frameworks, v_primary_domain, NOW()
    )
    RETURNING id INTO v_new_id;
    
    RETURN v_new_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_decision_artifact_version_history(
    p_artifact_id UUID
) RETURNS TABLE (
    artifact_id UUID,
    version INT,
    status VARCHAR(32),
    created_at TIMESTAMPTZ,
    frozen_at TIMESTAMPTZ,
    frozen_by UUID,
    content_hash VARCHAR(64)
) AS $$
DECLARE
    v_root_id UUID;
BEGIN
    -- Find root artifact (walk up parent chain)
    WITH RECURSIVE artifact_chain AS (
        SELECT id, parent_artifact_id, 0 as depth
        FROM decision_artifacts
        WHERE id = p_artifact_id
        
        UNION ALL
        
        SELECT da.id, da.parent_artifact_id, ac.depth + 1
        FROM decision_artifacts da
        JOIN artifact_chain ac ON da.id = ac.parent_artifact_id
    )
    SELECT id INTO v_root_id
    FROM artifact_chain
    WHERE parent_artifact_id IS NULL;
    
    -- Return all versions from root
    RETURN QUERY
    WITH RECURSIVE version_chain AS (
        SELECT id, version, status, created_at, frozen_at, frozen_by, content_hash
        FROM decision_artifacts
        WHERE id = v_root_id
        
        UNION ALL
        
        SELECT da.id, da.version, da.status, da.created_at, da.frozen_at, da.frozen_by, da.content_hash
        FROM decision_artifacts da
        JOIN version_chain vc ON da.parent_artifact_id = vc.id
    )
    SELECT * FROM version_chain
    ORDER BY version ASC;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_decision_artifact_staleness(
    p_artifact_id UUID
) RETURNS TABLE (
    is_stale BOOLEAN,
    stale_query_count INT,
    oldest_stale_query_age_hours DECIMAL
) AS $$
DECLARE
    v_artifact RECORD;
    v_stale_count INT := 0;
    v_oldest_age DECIMAL := 0;
    v_query RECORD;
    v_age_hours DECIMAL;
BEGIN
    SELECT artifact_content, staleness_threshold_days
    INTO v_artifact
    FROM decision_artifacts
    WHERE id = p_artifact_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Artifact not found: %', p_artifact_id;
    END IF;
    
    -- Check each volatile query
    FOR v_query IN 
        SELECT * FROM jsonb_array_elements(
            COALESCE(v_artifact.artifact_content->'volatile_queries', '[]'::jsonb)
        ) AS q
    LOOP
        v_age_hours := EXTRACT(EPOCH FROM (
            NOW() - (v_query.q->>'last_verified_at')::TIMESTAMPTZ
        )) / 3600;
        
        IF v_age_hours > COALESCE((v_query.q->>'staleness_threshold_hours')::DECIMAL, 168) THEN
            v_stale_count := v_stale_count + 1;
            IF v_age_hours > v_oldest_age THEN
                v_oldest_age := v_age_hours;
            END IF;
        END IF;
    END LOOP;
    
    RETURN QUERY SELECT 
        v_stale_count > 0,
        v_stale_count,
        v_oldest_age;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_decision_artifact_staleness_status()
RETURNS INT AS $$
DECLARE
    v_updated INT := 0;
    v_artifact RECORD;
    v_staleness RECORD;
BEGIN
    FOR v_artifact IN 
        SELECT id FROM decision_artifacts 
        WHERE status = 'active' AND validation_status != 'invalidated'
    LOOP
        SELECT * INTO v_staleness 
        FROM check_decision_artifact_staleness(v_artifact.id);
        
        IF v_staleness.is_stale AND v_staleness.stale_query_count > 0 THEN
            UPDATE decision_artifacts 
            SET validation_status = 'stale'
            WHERE id = v_artifact.id AND validation_status = 'fresh';
            
            IF FOUND THEN
                v_updated := v_updated + 1;
            END IF;
        END IF;
    END LOOP;
    
    RETURN v_updated;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_user_agent_access(
    p_tenant_id UUID,
    p_user_id UUID,
    p_agent_key VARCHAR(50)
) RETURNS BOOLEAN AS $$
DECLARE
    v_has_access BOOLEAN := false;
    v_agent_id UUID;
BEGIN
    -- Get agent ID
    SELECT id INTO v_agent_id FROM agent_registry WHERE agent_key = p_agent_key AND is_active = true;
    
    IF v_agent_id IS NULL THEN
        RETURN false;
    END IF;
    
    -- Check direct user-agent access
    SELECT EXISTS(
        SELECT 1 FROM user_agent_access 
        WHERE tenant_id = p_tenant_id 
        AND user_id = p_user_id 
        AND agent_id = v_agent_id 
        AND is_active = true
        AND (expires_at IS NULL OR expires_at > NOW())
    ) INTO v_has_access;
    
    IF v_has_access THEN
        RETURN true;
    END IF;
    
    -- Check role-based access
    SELECT EXISTS(
        SELECT 1 FROM tenant_user_roles tur
        JOIN tenant_roles tr ON tr.id = tur.role_id
        WHERE tur.tenant_id = p_tenant_id
        AND tur.user_id = p_user_id
        AND tur.is_active = true
        AND (tur.expires_at IS NULL OR tur.expires_at > NOW())
        AND tr.agent_access ? p_agent_key
    ) INTO v_has_access;
    
    RETURN v_has_access;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get user's effective permissions for an agent
CREATE OR REPLACE FUNCTION get_user_agent_permissions(
    p_tenant_id UUID,
    p_user_id UUID,
    p_agent_key VARCHAR(50)
) RETURNS JSONB AS $$
DECLARE
    v_permissions JSONB := '{}'::jsonb;
    v_agent_id UUID;
    v_default_perms JSONB;
    v_role_perms JSONB;
    v_direct_perms JSONB;
BEGIN
    -- Get agent default permissions
    SELECT id, default_permissions INTO v_agent_id, v_default_perms 
    FROM agent_registry WHERE agent_key = p_agent_key AND is_active = true;
    
    IF v_agent_id IS NULL THEN
        RETURN '{}'::jsonb;
    END IF;
    
    v_permissions := COALESCE(v_default_perms, '{}'::jsonb);
    
    -- Merge role-based permissions (union of all roles)
    SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb) INTO v_role_perms
    FROM (
        SELECT (jsonb_each(tr.permissions)).*
        FROM tenant_user_roles tur
        JOIN tenant_roles tr ON tr.id = tur.role_id
        WHERE tur.tenant_id = p_tenant_id
        AND tur.user_id = p_user_id
        AND tur.is_active = true
        AND tr.agent_access ? p_agent_key
    ) sub;
    
    v_permissions := v_permissions || COALESCE(v_role_perms, '{}'::jsonb);
    
    -- Merge direct user permissions (highest priority)
    SELECT permissions INTO v_direct_perms
    FROM user_agent_access
    WHERE tenant_id = p_tenant_id
    AND user_id = p_user_id
    AND agent_id = v_agent_id
    AND is_active = true;
    
    v_permissions := v_permissions || COALESCE(v_direct_perms, '{}'::jsonb);
    
    RETURN v_permissions;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to update domain node counts
CREATE OR REPLACE FUNCTION update_domain_node_counts() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE curator_domains 
        SET node_count = node_count + 1, updated_at = NOW()
        WHERE id = NEW.domain_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE curator_domains 
        SET node_count = node_count - 1, updated_at = NOW()
        WHERE id = OLD.domain_id;
    ELSIF TG_OP = 'UPDATE' AND OLD.domain_id IS DISTINCT FROM NEW.domain_id THEN
        UPDATE curator_domains 
        SET node_count = node_count - 1, updated_at = NOW()
        WHERE id = OLD.domain_id;
        UPDATE curator_domains 
        SET node_count = node_count + 1, updated_at = NOW()
        WHERE id = NEW.domain_id;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION set_domain_path() RETURNS TRIGGER AS $$
DECLARE
    v_parent_depth INTEGER;
    v_parent_path UUID[];
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.depth := 0;
        NEW.path_ids := ARRAY[NEW.id];
    ELSE
        SELECT depth, path_ids INTO v_parent_depth, v_parent_path
        FROM curator_domains WHERE id = NEW.parent_id;
        
        NEW.depth := COALESCE(v_parent_depth, 0) + 1;
        NEW.path_ids := COALESCE(v_parent_path, '{}') || NEW.id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

