CREATE OR REPLACE FUNCTION cortex_get_tier_health_summary(p_tenant_id UUID)
RETURNS TABLE (
    tier VARCHAR(10),
    status VARCHAR(20),
    alert_count BIGINT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        th.tier,
        th.status,
        COUNT(ta.id) FILTER (WHERE ta.resolved_at IS NULL) as alert_count
    FROM cortex_tier_health th
    LEFT JOIN cortex_tier_alerts ta ON ta.tenant_id = th.tenant_id AND ta.tier = th.tier
    WHERE th.tenant_id = p_tenant_id
    AND th.checked_at = (
        SELECT MAX(checked_at) FROM cortex_tier_health 
        WHERE tenant_id = p_tenant_id AND tier = th.tier
    )
    GROUP BY th.tier, th.status;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cortex_update_document_node_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE cortex_graph_documents 
        SET node_count = node_count + 1,
            updated_at = NOW()
        WHERE id = ANY(NEW.source_document_ids);
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE cortex_graph_documents 
        SET node_count = GREATEST(0, node_count - 1),
            updated_at = NOW()
        WHERE id = ANY(OLD.source_document_ids);
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_golden_rule_match(
    p_tenant_id UUID,
    p_query TEXT,
    p_entity_id UUID DEFAULT NULL
) RETURNS TABLE (
    rule_id UUID,
    rule_type VARCHAR(20),
    override TEXT,
    priority INTEGER,
    verified_by VARCHAR(255),
    verified_at TIMESTAMPTZ,
    signature VARCHAR(128)
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        gr.id,
        gr.rule_type,
        gr.override,
        gr.priority,
        gr.verified_by,
        gr.verified_at,
        gr.signature
    FROM cortex_golden_rules gr
    WHERE gr.tenant_id = p_tenant_id
      AND gr.is_active = true
      AND (gr.expires_at IS NULL OR gr.expires_at > NOW())
      AND (p_entity_id IS NULL OR gr.entity_id = p_entity_id OR gr.entity_id IS NULL)
      AND p_query ILIKE '%' || gr.condition || '%'
    ORDER BY gr.priority DESC, gr.verified_at DESC
    LIMIT 1;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION generate_signature(
    p_content TEXT,
    p_user VARCHAR(255)
) RETURNS VARCHAR(128) AS $$
BEGIN
    RETURN encode(sha256((p_content || p_user || NOW()::text)::bytea), 'hex');
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_stub_node_content_url(
    p_stub_node_id UUID,
    p_range_start INTEGER DEFAULT NULL,
    p_range_end INTEGER DEFAULT NULL
) RETURNS TEXT AS $$
DECLARE
    v_stub cortex_stub_nodes%ROWTYPE;
    v_mount cortex_zero_copy_mounts%ROWTYPE;
BEGIN
    SELECT * INTO v_stub FROM cortex_stub_nodes WHERE id = p_stub_node_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Stub node not found: %', p_stub_node_id;
    END IF;
    
    SELECT * INTO v_mount FROM cortex_zero_copy_mounts WHERE id = v_stub.mount_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Mount not found for stub node: %', p_stub_node_id;
    END IF;
    
    -- Return the URI (actual signed URL generation happens in application layer)
    RETURN v_stub.uri;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Grant permissions
GRANT EXECUTE ON FUNCTION check_golden_rule_match TO authenticated;
GRANT EXECUTE ON FUNCTION generate_signature TO authenticated;
GRANT EXECUTE ON FUNCTION get_stub_node_content_url TO authenticated;


-- Source: V2026_01_24_001__services_layer_api_keys.sql
-- ============================================================================
-- RADIANT v5.52.5 - Services Layer API Keys & Interface Access Control
-- Migration: V2026_01_24_001__services_layer_api_keys.sql
--
-- Implements:
-- 1. PostgreSQL api_keys table with interface_type (A2A, MCP, API)
-- 2. Interface-based access control
-- 3. Key sync mechanism between admin apps
-- 4. Audit logging for key operations
-- ============================================================================

-- ============================================================================
-- 1. API Keys Table (replaces DynamoDB for main operations)
-- ============================================================================

CREATE TABLE IF NOT EXISTS api_keys (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Key identification
  name VARCHAR(255) NOT NULL,
  description TEXT,
  key_prefix VARCHAR(20) NOT NULL,
  key_hash VARCHAR(128) NOT NULL,
  
  -- Interface type - CRITICAL for access control
  interface_type VARCHAR(20) NOT NULL CHECK (interface_type IN ('api', 'mcp', 'a2a', 'all')),
  
  -- Scopes and permissions
  scopes TEXT[] NOT NULL DEFAULT ARRAY['chat', 'models'],
  allowed_endpoints TEXT[],  -- NULL = all endpoints for interface
  denied_endpoints TEXT[],   -- Explicit denials
  
  -- Rate limiting
  rate_limit_per_minute INTEGER,
  rate_limit_per_hour INTEGER,
  rate_limit_per_day INTEGER,
  
  -- Validity
  is_active BOOLEAN NOT NULL DEFAULT true,
  expires_at TIMESTAMPTZ,
  last_used_at TIMESTAMPTZ,
  use_count INTEGER NOT NULL DEFAULT 0,
  
  -- A2A specific fields
  a2a_agent_id VARCHAR(255),
  a2a_agent_type VARCHAR(100),
  a2a_allowed_operations TEXT[],
  a2a_mtls_required BOOLEAN DEFAULT true,
  a2a_client_cert_fingerprint VARCHAR(128),
  
  -- MCP specific fields
  mcp_allowed_tools TEXT[],
  mcp_allowed_resources TEXT[],
  mcp_protocol_version VARCHAR(20) DEFAULT '2025-03-26',
  
  -- Metadata
  created_by UUID,
  created_by_app VARCHAR(50) CHECK (created_by_app IN ('radiant_admin', 'thinktank_admin', 'api', 'system')),
  metadata JSONB DEFAULT '{}',
  tags TEXT[],
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  revoked_at TIMESTAMPTZ,
  revoked_by UUID,
  revoked_reason TEXT,
  
  UNIQUE(tenant_id, key_prefix),
  UNIQUE(key_hash)
);

-- Indexes for fast lookups
CREATE INDEX idx_api_keys_tenant ON api_keys(tenant_id);
CREATE INDEX idx_api_keys_hash ON api_keys(key_hash);
CREATE INDEX idx_api_keys_prefix ON api_keys(key_prefix);
CREATE INDEX idx_api_keys_interface ON api_keys(interface_type);
CREATE INDEX idx_api_keys_active ON api_keys(is_active) WHERE is_active = true;
CREATE INDEX idx_api_keys_a2a_agent ON api_keys(a2a_agent_id) WHERE interface_type = 'a2a';

-- RLS Policy
ALTER TABLE api_keys ENABLE ROW LEVEL SECURITY;

CREATE POLICY api_keys_tenant_isolation ON api_keys
  USING (tenant_id = current_setting('app.current_tenant_id', true)::uuid);

-- ============================================================================
-- 2. API Key Audit Log
-- ============================================================================

CREATE TABLE IF NOT EXISTS api_key_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  key_id UUID REFERENCES api_keys(id) ON DELETE SET NULL,
  
  -- Action details
  action VARCHAR(50) NOT NULL CHECK (action IN (
    'created', 'updated', 'revoked', 'restored', 'used', 'rate_limited',
    'expired', 'scope_denied', 'interface_denied', 'endpoint_denied',
    'a2a_auth_success', 'a2a_auth_failure', 'mcp_auth_success', 'mcp_auth_failure'
  )),
  
  -- Context
  key_prefix VARCHAR(20),
  interface_type VARCHAR(20),
  endpoint_accessed VARCHAR(500),
  
  -- Request details
  ip_address INET,
  user_agent TEXT,
  request_id VARCHAR(100),
  
  -- A2A specific
  a2a_agent_id VARCHAR(255),
  a2a_operation VARCHAR(100),
  
  -- Result
  success BOOLEAN NOT NULL DEFAULT true,
  error_code VARCHAR(50),
  error_message TEXT,
  
  -- Actor
  actor_user_id UUID,
  actor_type VARCHAR(50) CHECK (actor_type IN ('user', 'admin', 'system', 'agent')),
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  -- Metadata
  metadata JSONB DEFAULT '{}'
);

CREATE INDEX idx_api_key_audit_tenant ON api_key_audit_log(tenant_id, created_at DESC);
CREATE INDEX idx_api_key_audit_key ON api_key_audit_log(key_id, created_at DESC);
CREATE INDEX idx_api_key_audit_action ON api_key_audit_log(action, created_at DESC);
CREATE INDEX idx_api_key_audit_a2a ON api_key_audit_log(a2a_agent_id) WHERE a2a_agent_id IS NOT NULL;

-- RLS Policy
ALTER TABLE api_key_audit_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY api_key_audit_tenant_isolation ON api_key_audit_log
  USING (tenant_id = current_setting('app.current_tenant_id', true)::uuid);

-- ============================================================================
-- 3. Interface Access Policies
-- ============================================================================

CREATE TABLE IF NOT EXISTS interface_access_policies (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Policy scope (NULL tenant_id = global policy)
  interface_type VARCHAR(20) NOT NULL CHECK (interface_type IN ('api', 'mcp', 'a2a')),
  
  -- Access rules
  require_authentication BOOLEAN NOT NULL DEFAULT true,
  require_mtls BOOLEAN DEFAULT false,
  allowed_ip_ranges CIDR[],
  blocked_ip_ranges CIDR[],
  
  -- Rate limits (per interface)
  global_rate_limit_per_minute INTEGER,
  global_rate_limit_per_hour INTEGER,
  
  -- A2A specific policies
  a2a_allowed_agent_types TEXT[],
  a2a_require_registration BOOLEAN DEFAULT true,
  a2a_max_concurrent_connections INTEGER DEFAULT 100,
  
  -- MCP specific policies
  mcp_allowed_protocol_versions TEXT[] DEFAULT ARRAY['2024-11-05', '2025-03-26'],
  mcp_require_capability_negotiation BOOLEAN DEFAULT true,
  mcp_max_tools_per_request INTEGER DEFAULT 50,
  
  -- Feature flags
  is_enabled BOOLEAN NOT NULL DEFAULT true,
  priority INTEGER DEFAULT 0,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(tenant_id, interface_type)
);

