-- ============================================================================
-- 4. A2A Agent Registry (for agent authentication)
-- ============================================================================

CREATE TABLE IF NOT EXISTS a2a_registered_agents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Agent identification
  agent_id VARCHAR(255) NOT NULL,
  agent_name VARCHAR(255) NOT NULL,
  agent_type VARCHAR(100) NOT NULL,
  agent_version VARCHAR(50),
  
  -- Authentication
  api_key_id UUID REFERENCES api_keys(id) ON DELETE SET NULL,
  mtls_cert_fingerprint VARCHAR(128),
  mtls_cert_expires_at TIMESTAMPTZ,
  
  -- Capabilities
  supported_operations TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  supported_protocols TEXT[] DEFAULT ARRAY['a2a-v1'],
  max_concurrent_requests INTEGER DEFAULT 10,
  
  -- Status
  status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'revoked', 'pending')),
  last_heartbeat_at TIMESTAMPTZ,
  last_request_at TIMESTAMPTZ,
  total_requests INTEGER NOT NULL DEFAULT 0,
  
  -- Contact
  owner_email VARCHAR(255),
  webhook_url VARCHAR(500),
  
  -- Metadata
  metadata JSONB DEFAULT '{}',
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(tenant_id, agent_id)
);

CREATE INDEX idx_a2a_agents_tenant ON a2a_registered_agents(tenant_id);
CREATE INDEX idx_a2a_agents_status ON a2a_registered_agents(status) WHERE status = 'active';
CREATE INDEX idx_a2a_agents_type ON a2a_registered_agents(agent_type);

-- RLS Policy
ALTER TABLE a2a_registered_agents ENABLE ROW LEVEL SECURITY;

CREATE POLICY a2a_agents_tenant_isolation ON a2a_registered_agents
  USING (tenant_id = current_setting('app.current_tenant_id', true)::uuid);

-- ============================================================================
-- 5. Key Sync Log (for admin app synchronization)
-- ============================================================================

CREATE TABLE IF NOT EXISTS api_key_sync_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  key_id UUID NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE,
  
  -- Sync details
  source_app VARCHAR(50) NOT NULL CHECK (source_app IN ('radiant_admin', 'thinktank_admin')),
  target_app VARCHAR(50) NOT NULL CHECK (target_app IN ('radiant_admin', 'thinktank_admin')),
  sync_type VARCHAR(20) NOT NULL CHECK (sync_type IN ('create', 'update', 'revoke', 'delete')),
  
  -- Status
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'synced', 'failed', 'skipped')),
  error_message TEXT,
  retry_count INTEGER DEFAULT 0,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  synced_at TIMESTAMPTZ,
  
  -- Metadata
  changes JSONB
);

CREATE INDEX idx_key_sync_pending ON api_key_sync_log(status, created_at) WHERE status = 'pending';

-- ============================================================================
-- 6. Functions for API Key Operations
-- ============================================================================

-- Function to validate API key and check interface access
CREATE OR REPLACE FUNCTION validate_api_key_for_interface(
  p_key_hash VARCHAR,
  p_interface_type VARCHAR,
  p_endpoint VARCHAR DEFAULT NULL
) RETURNS TABLE (
  is_valid BOOLEAN,
  key_id UUID,
  tenant_id UUID,
  scopes TEXT[],
  error_code VARCHAR,
  error_message TEXT
) AS $$
DECLARE
  v_key RECORD;
  v_policy RECORD;
BEGIN
  -- Find the key
  SELECT * INTO v_key FROM api_keys
  WHERE key_hash = p_key_hash AND is_active = true;
  
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::UUID, NULL::UUID, NULL::TEXT[], 'INVALID_KEY'::VARCHAR, 'API key not found or inactive'::TEXT;
    RETURN;
  END IF;
  
  -- Check expiration
  IF v_key.expires_at IS NOT NULL AND v_key.expires_at < NOW() THEN
    RETURN QUERY SELECT false, v_key.id, v_key.tenant_id, v_key.scopes, 'KEY_EXPIRED'::VARCHAR, 'API key has expired'::TEXT;
    RETURN;
  END IF;
  
  -- Check interface type
  IF v_key.interface_type != 'all' AND v_key.interface_type != p_interface_type THEN
    RETURN QUERY SELECT false, v_key.id, v_key.tenant_id, v_key.scopes, 'INTERFACE_DENIED'::VARCHAR, 
      format('Key not authorized for %s interface', p_interface_type)::TEXT;
    RETURN;
  END IF;
  
  -- Check endpoint restrictions
  IF p_endpoint IS NOT NULL THEN
    -- Check denied endpoints
    IF v_key.denied_endpoints IS NOT NULL AND p_endpoint = ANY(v_key.denied_endpoints) THEN
      RETURN QUERY SELECT false, v_key.id, v_key.tenant_id, v_key.scopes, 'ENDPOINT_DENIED'::VARCHAR, 
        format('Endpoint %s is explicitly denied', p_endpoint)::TEXT;
      RETURN;
    END IF;
    
    -- Check allowed endpoints (if specified)
    IF v_key.allowed_endpoints IS NOT NULL AND array_length(v_key.allowed_endpoints, 1) > 0 THEN
      IF NOT p_endpoint = ANY(v_key.allowed_endpoints) THEN
        RETURN QUERY SELECT false, v_key.id, v_key.tenant_id, v_key.scopes, 'ENDPOINT_DENIED'::VARCHAR, 
          format('Endpoint %s is not in allowed list', p_endpoint)::TEXT;
        RETURN;
      END IF;
    END IF;
  END IF;
  
  -- Update usage
  UPDATE api_keys SET
    last_used_at = NOW(),
    use_count = use_count + 1,
    updated_at = NOW()
  WHERE id = v_key.id;
  
  -- Success
  RETURN QUERY SELECT true, v_key.id, v_key.tenant_id, v_key.scopes, NULL::VARCHAR, NULL::TEXT;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_api_key(
  p_tenant_id UUID,
  p_name VARCHAR,
  p_interface_type VARCHAR,
  p_key_prefix VARCHAR,
  p_key_hash VARCHAR,
  p_scopes TEXT[] DEFAULT ARRAY['chat', 'models'],
  p_created_by UUID DEFAULT NULL,
  p_created_by_app VARCHAR DEFAULT 'api',
  p_expires_at TIMESTAMPTZ DEFAULT NULL,
  p_a2a_agent_id VARCHAR DEFAULT NULL,
  p_mcp_allowed_tools TEXT[] DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
  v_key_id UUID;
BEGIN
  INSERT INTO api_keys (
    tenant_id, name, interface_type, key_prefix, key_hash, scopes,
    created_by, created_by_app, expires_at, a2a_agent_id, mcp_allowed_tools
  ) VALUES (
    p_tenant_id, p_name, p_interface_type, p_key_prefix, p_key_hash, p_scopes,
    p_created_by, p_created_by_app, p_expires_at, p_a2a_agent_id, p_mcp_allowed_tools
  ) RETURNING id INTO v_key_id;
  
  -- Log creation
  INSERT INTO api_key_audit_log (
    tenant_id, key_id, action, key_prefix, interface_type,
    actor_user_id, actor_type, success
  ) VALUES (
    p_tenant_id, v_key_id, 'created', p_key_prefix, p_interface_type,
    p_created_by, CASE WHEN p_created_by IS NOT NULL THEN 'admin' ELSE 'system' END, true
  );
  
  -- Queue sync if created from admin app
  IF p_created_by_app IN ('radiant_admin', 'thinktank_admin') THEN
    INSERT INTO api_key_sync_log (key_id, source_app, target_app, sync_type, changes)
    VALUES (
      v_key_id,
      p_created_by_app,
      CASE WHEN p_created_by_app = 'radiant_admin' THEN 'thinktank_admin' ELSE 'radiant_admin' END,
      'create',
      jsonb_build_object('name', p_name, 'interface_type', p_interface_type, 'scopes', p_scopes)
    );
  END IF;
  
  RETURN v_key_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION revoke_api_key(
  p_key_id UUID,
  p_revoked_by UUID,
  p_reason TEXT DEFAULT NULL
) RETURNS BOOLEAN AS $$
DECLARE
  v_key RECORD;
BEGIN
  SELECT * INTO v_key FROM api_keys WHERE id = p_key_id;
  
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  
  UPDATE api_keys SET
    is_active = false,
    revoked_at = NOW(),
    revoked_by = p_revoked_by,
    revoked_reason = p_reason,
    updated_at = NOW()
  WHERE id = p_key_id;
  
  -- Log revocation
  INSERT INTO api_key_audit_log (
    tenant_id, key_id, action, key_prefix, interface_type,
    actor_user_id, actor_type, success, metadata
  ) VALUES (
    v_key.tenant_id, p_key_id, 'revoked', v_key.key_prefix, v_key.interface_type,
    p_revoked_by, 'admin', true, jsonb_build_object('reason', p_reason)
  );
  
  -- Queue sync
  INSERT INTO api_key_sync_log (key_id, source_app, target_app, sync_type, changes)
  VALUES (
    p_key_id,
    'radiant_admin',
    'thinktank_admin',
    'revoke',
    jsonb_build_object('revoked_by', p_revoked_by, 'reason', p_reason)
  );
  
  RETURN true;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_api_keys_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uds_search_index_update_tsvector()
RETURNS TRIGGER AS $$
BEGIN
    NEW.content_tsvector := to_tsvector('english', NEW.content_text);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uds_next_audit_sequence(p_tenant_id UUID)
RETURNS BIGINT AS $$
DECLARE
    v_sequence BIGINT;
BEGIN
    SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_sequence
    FROM uds_audit_log
    WHERE tenant_id = p_tenant_id;
    RETURN v_sequence;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uds_calculate_merkle_hash(
    p_event_type TEXT,
    p_action TEXT,
    p_resource_type TEXT,
    p_resource_id UUID,
    p_previous_hash TEXT,
    p_timestamp TIMESTAMPTZ
)
RETURNS TEXT AS $$
BEGIN
    RETURN encode(
        sha256(
            (COALESCE(p_event_type, '') || 
             COALESCE(p_action, '') || 
             COALESCE(p_resource_type, '') || 
             COALESCE(p_resource_id::TEXT, '') || 
             COALESCE(p_previous_hash, '') ||
             COALESCE(p_timestamp::TEXT, ''))::BYTEA
        ),
        'hex'
    );
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Auto-update conversation stats
CREATE OR REPLACE FUNCTION uds_update_conversation_stats()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE uds_conversations
        SET message_count = message_count + 1,
            total_input_tokens = total_input_tokens + COALESCE(NEW.input_tokens, 0),
            total_output_tokens = total_output_tokens + COALESCE(NEW.output_tokens, 0),
            total_cost_credits = total_cost_credits + COALESCE(NEW.cost_credits, 0),
            last_message_at = NEW.created_at,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = NEW.conversation_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE uds_conversations
        SET message_count = GREATEST(message_count - 1, 0),
            total_input_tokens = GREATEST(total_input_tokens - COALESCE(OLD.input_tokens, 0), 0),
            total_output_tokens = GREATEST(total_output_tokens - COALESCE(OLD.output_tokens, 0), 0),
            total_cost_credits = GREATEST(total_cost_credits - COALESCE(OLD.cost_credits, 0), 0),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = OLD.conversation_id;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uds_update_attachment_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.conversation_id IS NOT NULL THEN
        UPDATE uds_conversations
        SET attachment_count = attachment_count + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = NEW.conversation_id;
    ELSIF TG_OP = 'DELETE' AND OLD.conversation_id IS NOT NULL THEN
        UPDATE uds_conversations
        SET attachment_count = GREATEST(attachment_count - 1, 0),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = OLD.conversation_id;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uds_initialize_tenant(p_tenant_id UUID)
RETURNS VOID AS $$
BEGIN
    -- Create default config
    INSERT INTO uds_config (tenant_id)
    VALUES (p_tenant_id)
    ON CONFLICT (tenant_id) DO NOTHING;
    
    -- Create tenant encryption key entry (actual key in KMS)
    INSERT INTO uds_encryption_keys (tenant_id, key_id, key_type)
    VALUES (p_tenant_id, 'aws/kms/uds-tenant-' || p_tenant_id, 'tenant')
    ON CONFLICT DO NOTHING;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_cato_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cato_consolidate_memories(p_tenant_id VARCHAR(64))
RETURNS TABLE (
  expired_removed INTEGER,
  low_importance_removed INTEGER,
  total_remaining INTEGER
) AS $$
DECLARE
  v_expired INTEGER;
  v_low_importance INTEGER;
  v_remaining INTEGER;
BEGIN
  -- Remove expired memories
  DELETE FROM cato_global_memory 
  WHERE tenant_id = p_tenant_id 
    AND expires_at IS NOT NULL 
    AND expires_at < NOW();
  GET DIAGNOSTICS v_expired = ROW_COUNT;
  
  -- Remove low importance memories older than 30 days with few accesses
  DELETE FROM cato_global_memory
  WHERE tenant_id = p_tenant_id
    AND importance < 0.3
    AND access_count < 3
    AND created_at < NOW() - INTERVAL '30 days'
    AND category NOT IN ('procedural'); -- Keep procedural memories (skills)
  GET DIAGNOSTICS v_low_importance = ROW_COUNT;
  
  -- Count remaining
  SELECT COUNT(*) INTO v_remaining 
  FROM cato_global_memory 
  WHERE tenant_id = p_tenant_id;
  
  RETURN QUERY SELECT v_expired, v_low_importance, v_remaining;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cato_cortex_initialize_bridge(p_tenant_id UUID)
RETURNS void AS $$
BEGIN
    INSERT INTO cato_cortex_bridge_config (tenant_id)
    VALUES (p_tenant_id)
    ON CONFLICT (tenant_id) DO NOTHING;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cato_cortex_get_pending_sync(
    p_tenant_id UUID,
    p_category VARCHAR DEFAULT NULL,
    p_limit INTEGER DEFAULT 100
)
RETURNS TABLE (
    memory_id UUID,
    category VARCHAR,
    key TEXT,
    value JSONB,
    importance DECIMAL,
    created_at TIMESTAMPTZ
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.id::UUID as memory_id,
        m.category::VARCHAR,
        m.key::TEXT,
        m.value::JSONB,
        m.importance::DECIMAL,
        m.created_at
    FROM cato_global_memory m
    WHERE m.tenant_id = p_tenant_id
    AND (m.synced_to_cortex IS NULL OR m.synced_to_cortex = false)
    AND (p_category IS NULL OR m.category = p_category)
    ORDER BY m.importance DESC, m.created_at DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Cleanup expired enrichment cache
CREATE OR REPLACE FUNCTION cato_cortex_cleanup_enrichment_cache()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM cato_cortex_enrichment_cache
    WHERE expires_at < NOW();
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cato_memory_auto_promote_trigger()
RETURNS TRIGGER AS $$
DECLARE
    v_config cato_cortex_bridge_config%ROWTYPE;
BEGIN
    -- Get bridge config for tenant
    SELECT * INTO v_config 
    FROM cato_cortex_bridge_config 
    WHERE tenant_id = NEW.tenant_id;
    
    -- If auto-promote enabled and importance exceeds threshold
    IF v_config.auto_promote_high_importance = true 
       AND NEW.importance >= v_config.importance_promotion_threshold
       AND (NEW.synced_to_cortex IS NULL OR NEW.synced_to_cortex = false) THEN
        -- Mark for immediate sync (actual sync handled by application)
        NEW.synced_to_cortex := false;
        -- Log high-importance detection (sync happens async)
        RAISE NOTICE 'High-importance memory detected for tenant %, memory %', NEW.tenant_id, NEW.id;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_batch_write_staging()
RETURNS void AS $$
BEGIN
    DELETE FROM batch_write_staging
    WHERE status = 'completed' 
    AND processed_at < NOW() - INTERVAL '1 hour';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_rls_policy_optimized(
    p_table_name TEXT,
    p_policy_name TEXT
) RETURNS void AS $$
DECLARE
    policy_exists BOOLEAN;
BEGIN
    -- Check if policy exists
    SELECT EXISTS(
        SELECT 1 FROM pg_policies 
        WHERE tablename = p_table_name AND policyname = p_policy_name
    ) INTO policy_exists;
    
    IF policy_exists THEN
        -- Drop existing policy
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I', p_policy_name, p_table_name);
    END IF;
    
    -- Create optimized policy with SELECT wrapper
    EXECUTE format(
        'CREATE POLICY %I ON %I 
         USING (tenant_id = (SELECT current_setting(''app.current_tenant_id'', true)::uuid))
         WITH CHECK (tenant_id = (SELECT current_setting(''app.current_tenant_id'', true)::uuid))',
        p_policy_name, p_table_name
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_rate_limit_state()
RETURNS void AS $$
BEGIN
    DELETE FROM rate_limit_state
    WHERE window_start < NOW() - INTERVAL '1 hour';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_monthly_partition(
    p_table_name TEXT,
    p_partition_prefix TEXT
) RETURNS TEXT AS $$
DECLARE
    partition_date DATE;
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    -- Create partition for next month
    partition_date := DATE_TRUNC('month', NOW() + INTERVAL '1 month');
    partition_name := p_partition_prefix || '_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-DD');
    
    -- Check if partition already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_tables 
        WHERE tablename = partition_name
    ) THEN
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS %I PARTITION OF %I 
             FOR VALUES FROM (%L) TO (%L)',
            partition_name, p_table_name, start_date, end_date
        );
        RETURN 'Created partition: ' || partition_name;
    ELSE
        RETURN 'Partition already exists: ' || partition_name;
    END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION ensure_future_partitions(
    p_months_ahead INTEGER DEFAULT 3
) RETURNS TABLE(partition_name TEXT, status TEXT) AS $$
DECLARE
    i INTEGER;
    result_model TEXT;
    result_usage TEXT;
BEGIN
    FOR i IN 1..p_months_ahead LOOP
        -- Model logs partitions
        SELECT create_monthly_partition(
            'model_execution_logs_partitioned', 
            'model_logs'
        ) INTO result_model;
        
        -- Usage partitions
        SELECT create_monthly_partition(
            'usage_records_partitioned',
            'usage'
        ) INTO result_usage;
        
        partition_name := 'model_logs_' || TO_CHAR(DATE_TRUNC('month', NOW() + (i || ' months')::INTERVAL), 'YYYY_MM');
        status := result_model;
        RETURN NEXT;
        
        partition_name := 'usage_' || TO_CHAR(DATE_TRUNC('month', NOW() + (i || ' months')::INTERVAL), 'YYYY_MM');
        status := result_usage;
        RETURN NEXT;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION archive_old_partition(
    p_table_name TEXT,
    p_partition_name TEXT,
    p_archive_schema TEXT DEFAULT 'archive'
) RETURNS TEXT AS $$
BEGIN
    -- Create archive schema if not exists
    EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', p_archive_schema);
    
    -- Detach partition
    EXECUTE format(
        'ALTER TABLE %I DETACH PARTITION %I',
        p_table_name, p_partition_name
    );
    
    -- Move to archive schema
    EXECUTE format(
        'ALTER TABLE %I SET SCHEMA %I',
        p_partition_name, p_archive_schema
    );
    
    RETURN 'Archived partition: ' || p_partition_name || ' to schema: ' || p_archive_schema;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_partition_stats(p_table_name TEXT)
RETURNS TABLE(
    partition_name TEXT,
    row_count BIGINT,
    total_size TEXT,
    index_size TEXT,
    min_date TIMESTAMPTZ,
    max_date TIMESTAMPTZ
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        child.relname::TEXT as partition_name,
        pg_stat_user_tables.n_live_tup as row_count,
        pg_size_pretty(pg_table_size(child.oid)) as total_size,
        pg_size_pretty(pg_indexes_size(child.oid)) as index_size,
        NULL::TIMESTAMPTZ as min_date,
        NULL::TIMESTAMPTZ as max_date
    FROM pg_inherits
    JOIN pg_class parent ON pg_inherits.inhparent = parent.oid
    JOIN pg_class child ON pg_inherits.inhrelid = child.oid
    LEFT JOIN pg_stat_user_tables ON child.relname = pg_stat_user_tables.relname
    WHERE parent.relname = p_table_name
    ORDER BY child.relname;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION refresh_all_materialized_views()
RETURNS TABLE(view_name TEXT, refresh_status TEXT, duration_ms NUMERIC) AS $$
DECLARE
    start_time TIMESTAMPTZ;
    view_record RECORD;
BEGIN
    FOR view_record IN 
        SELECT matviewname 
        FROM pg_matviews 
        WHERE schemaname = 'public' 
        AND matviewname LIKE 'mv_%'
    LOOP
        start_time := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', view_record.matviewname);
            view_name := view_record.matviewname;
            refresh_status := 'success';
            duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - start_time)) * 1000;
        EXCEPTION WHEN OTHERS THEN
            view_name := view_record.matviewname;
            refresh_status := 'error: ' || SQLERRM;
            duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - start_time)) * 1000;
        END;
        RETURN NEXT;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION refresh_priority_materialized_views()
RETURNS TABLE(view_name TEXT, refresh_status TEXT, duration_ms NUMERIC) AS $$
DECLARE
    start_time TIMESTAMPTZ;
    view_names TEXT[] := ARRAY[
        'mv_tenant_daily_usage',
        'mv_tenant_model_performance'
    ];
    v TEXT;
BEGIN
    FOREACH v IN ARRAY view_names
    LOOP
        start_time := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', v);
            view_name := v;
            refresh_status := 'success';
            duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - start_time)) * 1000;
        EXCEPTION WHEN OTHERS THEN
            view_name := v;
            refresh_status := 'error: ' || SQLERRM;
            duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - start_time)) * 1000;
        END;
        RETURN NEXT;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_mv_refresh(
    p_view_name TEXT,
    p_status TEXT,
    p_duration_ms NUMERIC
) RETURNS void AS $$
BEGIN
    INSERT INTO mv_refresh_log (view_name, refresh_status, duration_ms)
    VALUES (p_view_name, p_status, p_duration_ms);
    
    -- Cleanup old logs (keep 7 days)
    DELETE FROM mv_refresh_log 
    WHERE refreshed_at < NOW() - INTERVAL '7 days';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_tenant_usage_summary(
    p_tenant_id UUID,
    p_start_date DATE,
    p_end_date DATE
) RETURNS TABLE(
    day DATE,
    total_requests BIGINT,
    total_tokens BIGINT,
    avg_latency_ms NUMERIC,
    success_rate_pct NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        mv.day::DATE,
        mv.total_requests,
        mv.total_tokens,
        mv.avg_latency_ms,
        mv.success_rate_pct
    FROM mv_tenant_daily_usage mv
    WHERE mv.tenant_id = p_tenant_id
    AND mv.day >= p_start_date
    AND mv.day <= p_end_date
    ORDER BY mv.day;
END;
$$ LANGUAGE plpgsql STABLE;

-- Get model performance comparison
CREATE OR REPLACE FUNCTION get_model_performance_comparison(
    p_tenant_id UUID,
    p_hours INTEGER DEFAULT 24
) RETURNS TABLE(
    model_id VARCHAR(100),
    model_provider VARCHAR(50),
    request_count BIGINT,
    avg_latency_ms NUMERIC,
    p95_latency_ms NUMERIC,
    tokens_per_second NUMERIC,
    error_rate NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        mv.model_id,
        mv.model_provider,
        SUM(mv.request_count)::BIGINT,
        AVG(mv.avg_latency_ms),
        AVG(mv.p95_latency_ms),
        AVG(mv.tokens_per_second),
        SUM(mv.error_count)::NUMERIC / NULLIF(SUM(mv.request_count), 0) * 100
    FROM mv_tenant_model_performance mv
    WHERE mv.tenant_id = p_tenant_id
    AND mv.hour > NOW() - (p_hours || ' hours')::INTERVAL
    GROUP BY mv.model_id, mv.model_provider
    ORDER BY SUM(mv.request_count) DESC;
END;
$$ LANGUAGE plpgsql STABLE;

