    updated_at = NOW();

-- Function to update network metrics after inference
CREATE OR REPLACE FUNCTION update_axiom_network_metrics(
    p_network_id VARCHAR(32),
    p_latency_ms INTEGER,
    p_used_fallback BOOLEAN
) RETURNS VOID AS $$
DECLARE
    v_current_rpm DECIMAL(10,2);
    v_current_error_rate DECIMAL(5,4);
BEGIN
    -- Get current metrics
    SELECT requests_per_minute, error_rate INTO v_current_rpm, v_current_error_rate
    FROM axiom_network_status WHERE network_id = p_network_id;
    
    -- Update with exponential moving average
    UPDATE axiom_network_status
    SET 
        last_inference_ms = p_latency_ms,
        avg_latency_ms = COALESCE(avg_latency_ms * 0.95 + p_latency_ms * 0.05, p_latency_ms),
        total_inferences = total_inferences + 1,
        last_request_at = NOW(),
        error_rate = CASE WHEN p_used_fallback THEN LEAST(1.0, error_rate * 0.95 + 0.05) ELSE GREATEST(0.0, error_rate * 0.95) END,
        -- Promote to warm if cold and getting traffic
        thermal_state = CASE 
            WHEN thermal_state = 'cold' AND total_inferences > 10 THEN 'warm'::axiom_network_thermal_state
            ELSE thermal_state
        END,
        updated_at = NOW()
    WHERE network_id = p_network_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION auto_cool_axiom_networks() RETURNS INTEGER AS $$
DECLARE
    v_cooled_count INTEGER := 0;
BEGIN
    UPDATE axiom_network_status
    SET thermal_state = 'cold'::axiom_network_thermal_state,
        updated_at = NOW()
    WHERE thermal_state IN ('warm', 'hot')
      AND last_request_at < NOW() - (auto_cool_after_minutes || ' minutes')::INTERVAL;
    
    GET DIAGNOSTICS v_cooled_count = ROW_COUNT;
    RETURN v_cooled_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_effective_cartridge_stack(
    p_tenant_id UUID,
    p_user_id UUID DEFAULT NULL
) RETURNS TABLE (
    cartridge_id UUID,
    name VARCHAR(255),
    scope cartridge_scope,
    position INTEGER,
    is_enabled BOOLEAN,
    can_disable BOOLEAN,
    allow_user_override BOOLEAN
) AS $$
BEGIN
    RETURN QUERY
    -- Tenant cartridges (always enabled, cannot disable)
    SELECT 
        c.id,
        c.name,
        c.scope,
        COALESCE(sp.position, 0)::INTEGER,
        true AS is_enabled,
        false AS can_disable,
        c.allow_user_override
    FROM cartridges c
    LEFT JOIN cartridge_stack_positions sp ON sp.cartridge_id = c.id AND sp.user_id IS NULL
    WHERE c.tenant_id = p_tenant_id
      AND c.scope = 'tenant'
      AND c.status = 'active'
      AND c.archived_at IS NULL
    
    UNION ALL
    
    -- User cartridges (if user_id provided)
    SELECT 
        c.id,
        c.name,
        c.scope,
        COALESCE(sp.position, 1000)::INTEGER,
        c.is_enabled,
        true AS can_disable,
        true AS allow_user_override
    FROM cartridges c
    LEFT JOIN cartridge_stack_positions sp ON sp.cartridge_id = c.id AND sp.user_id = p_user_id
    WHERE c.tenant_id = p_tenant_id
      AND c.scope = 'user'
      AND c.user_id = p_user_id
      AND c.status IN ('active', 'ready')
      AND c.archived_at IS NULL
      AND p_user_id IS NOT NULL
    
    ORDER BY position;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION get_effective_cartridge_stack IS 'Get the resolved cartridge stack for a tenant/user';


