-- Source: V2026_02_01_008__system_cartridge_registry.sql
-- =============================================================================
-- System Cartridge Registry Migration
-- v6.1.0: Domain experts as system cartridges with full audit trail
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------

CREATE TYPE cartridge_category AS ENUM ('general', 'domain_expert');
CREATE TYPE cartridge_thermal_state AS ENUM ('cold', 'warming', 'warm', 'hot');
CREATE TYPE system_cartridge_audit_action AS ENUM (
  'created', 'updated', 'deleted', 'enabled', 'disabled', 
  'thermal_state_changed', 'version_upgraded'
);

-- -----------------------------------------------------------------------------
-- Extend cartridges table with system cartridge fields
-- -----------------------------------------------------------------------------

ALTER TABLE cartridges 
  ADD COLUMN IF NOT EXISTS category cartridge_category DEFAULT 'general',
  ADD COLUMN IF NOT EXISTS domain_id VARCHAR(255),
  ADD COLUMN IF NOT EXISTS domain_display_name VARCHAR(500),
  ADD COLUMN IF NOT EXISTS thermal_state cartridge_thermal_state DEFAULT 'cold',
  ADD COLUMN IF NOT EXISTS thermal_state_changed_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS last_inference_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS inference_count BIGINT DEFAULT 0,
  ADD COLUMN IF NOT EXISTS registered_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS registered_by UUID,
  ADD COLUMN IF NOT EXISTS registered_via VARCHAR(50),
  ADD COLUMN IF NOT EXISTS previous_version_id UUID,
  ADD COLUMN IF NOT EXISTS version_history JSONB DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS compliance_reviewed_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS compliance_reviewed_by UUID,
  ADD COLUMN IF NOT EXISTS compliance_notes TEXT;

-- Index for system cartridges
CREATE INDEX IF NOT EXISTS idx_cartridges_system_scope 
  ON cartridges(scope) WHERE scope = 'system';

CREATE INDEX IF NOT EXISTS idx_cartridges_category 
  ON cartridges(category);

CREATE INDEX IF NOT EXISTS idx_cartridges_domain_id 
  ON cartridges(domain_id) WHERE domain_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_cartridges_thermal_state 
  ON cartridges(thermal_state);

-- -----------------------------------------------------------------------------
-- System Cartridge Audit Log (HIPAA/SOC2/GDPR compliant)
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS system_cartridge_audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
  action system_cartridge_audit_action NOT NULL,
  performed_by UUID NOT NULL,
  performed_by_email VARCHAR(255),
  performed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  previous_state JSONB,
  new_state JSONB,
  reason TEXT,
  ip_address INET,
  user_agent TEXT,
  compliance_flags TEXT[] DEFAULT '{}',
  
  -- Partition by month for efficient querying and retention
  created_month DATE GENERATED ALWAYS AS (date_trunc('month', performed_at)::date) STORED
) PARTITION BY RANGE (created_month);

-- Create partitions for current and next 12 months
DO $$
DECLARE
  partition_date DATE;
  partition_name TEXT;
  start_date DATE;
  end_date DATE;
BEGIN
  FOR i IN 0..12 LOOP
    partition_date := date_trunc('month', CURRENT_DATE + (i || ' months')::interval)::date;
    partition_name := 'system_cartridge_audit_log_' || to_char(partition_date, 'YYYY_MM');
    start_date := partition_date;
    end_date := (partition_date + interval '1 month')::date;
    
    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = partition_name) THEN
      EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF system_cartridge_audit_log 
         FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
      );
    END IF;
  END LOOP;
END $$;

-- Indexes for audit log
CREATE INDEX IF NOT EXISTS idx_system_cartridge_audit_cartridge_id 
  ON system_cartridge_audit_log(cartridge_id);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_audit_action 
  ON system_cartridge_audit_log(action);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_audit_performed_at 
  ON system_cartridge_audit_log(performed_at DESC);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_audit_performed_by 
  ON system_cartridge_audit_log(performed_by);

-- -----------------------------------------------------------------------------
-- Tenant Cartridge Visibility (toggle on/off per tenant)
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tenant_cartridge_visibility (
  tenant_id UUID NOT NULL,
  cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
  is_visible BOOLEAN NOT NULL DEFAULT true,
  disabled_at TIMESTAMPTZ,
  disabled_by UUID,
  disabled_reason TEXT,
  enabled_at TIMESTAMPTZ,
  enabled_by UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  PRIMARY KEY (tenant_id, cartridge_id)
);

-- Enable RLS
ALTER TABLE tenant_cartridge_visibility ENABLE ROW LEVEL SECURITY;

-- RLS policy for tenant isolation
CREATE POLICY tenant_cartridge_visibility_tenant_isolation 
  ON tenant_cartridge_visibility
  FOR ALL
  USING (tenant_id = current_setting('app.current_tenant_id', true)::uuid);

-- Index for visibility lookups
CREATE INDEX IF NOT EXISTS idx_tenant_cartridge_visibility_cartridge 
  ON tenant_cartridge_visibility(cartridge_id);

CREATE INDEX IF NOT EXISTS idx_tenant_cartridge_visibility_hidden 
  ON tenant_cartridge_visibility(tenant_id) WHERE is_visible = false;

-- -----------------------------------------------------------------------------
-- System Cartridge Thermal State Tracking
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS system_cartridge_thermal_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
  previous_state cartridge_thermal_state,
  new_state cartridge_thermal_state NOT NULL,
  changed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  trigger_reason VARCHAR(100), -- 'inference_spike', 'idle_timeout', 'manual', 'cold_start'
  inference_count_at_change BIGINT,
  
  -- Metrics at time of change
  avg_latency_ms DECIMAL(10, 2),
  p99_latency_ms DECIMAL(10, 2),
  error_rate DECIMAL(5, 4)
);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_thermal_history_cartridge 
  ON system_cartridge_thermal_history(cartridge_id);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_thermal_history_changed_at 
  ON system_cartridge_thermal_history(changed_at DESC);

-- -----------------------------------------------------------------------------
-- System Cartridge Inference Metrics
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS system_cartridge_inference_metrics (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cartridge_id UUID NOT NULL REFERENCES cartridges(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL,
  
  -- Metrics window (1-hour buckets)
  bucket_start TIMESTAMPTZ NOT NULL,
  bucket_end TIMESTAMPTZ NOT NULL,
  
  -- Inference stats
  inference_count INTEGER NOT NULL DEFAULT 0,
  success_count INTEGER NOT NULL DEFAULT 0,
  error_count INTEGER NOT NULL DEFAULT 0,
  
  -- Latency stats
  avg_latency_ms DECIMAL(10, 2),
  min_latency_ms DECIMAL(10, 2),
  max_latency_ms DECIMAL(10, 2),
  p50_latency_ms DECIMAL(10, 2),
  p95_latency_ms DECIMAL(10, 2),
  p99_latency_ms DECIMAL(10, 2),
  
  -- Network types breakdown (for domain_expert cartridges)
  network_usage JSONB DEFAULT '{}'::jsonb,
  
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  UNIQUE(cartridge_id, tenant_id, bucket_start)
);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_metrics_cartridge 
  ON system_cartridge_inference_metrics(cartridge_id);

CREATE INDEX IF NOT EXISTS idx_system_cartridge_metrics_bucket 
  ON system_cartridge_inference_metrics(bucket_start DESC);

-- -----------------------------------------------------------------------------
-- Functions
-- -----------------------------------------------------------------------------

-- Function to log system cartridge audit events
CREATE OR REPLACE FUNCTION log_system_cartridge_audit(
  p_cartridge_id UUID,
  p_action system_cartridge_audit_action,
  p_performed_by UUID,
  p_performed_by_email VARCHAR(255) DEFAULT NULL,
  p_previous_state JSONB DEFAULT NULL,
  p_new_state JSONB DEFAULT NULL,
  p_reason TEXT DEFAULT NULL,
  p_ip_address INET DEFAULT NULL,
  p_user_agent TEXT DEFAULT NULL,
  p_compliance_flags TEXT[] DEFAULT '{}'
) RETURNS UUID AS $$
DECLARE
  v_audit_id UUID;
BEGIN
  INSERT INTO system_cartridge_audit_log (
    cartridge_id, action, performed_by, performed_by_email,
    previous_state, new_state, reason,
    ip_address, user_agent, compliance_flags
  ) VALUES (
    p_cartridge_id, p_action, p_performed_by, p_performed_by_email,
    p_previous_state, p_new_state, p_reason,
    p_ip_address, p_user_agent, p_compliance_flags
  ) RETURNING id INTO v_audit_id;
  
  RETURN v_audit_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to update thermal state with history tracking
CREATE OR REPLACE FUNCTION update_cartridge_thermal_state(
  p_cartridge_id UUID,
  p_new_state cartridge_thermal_state,
  p_trigger_reason VARCHAR(100) DEFAULT 'manual'
) RETURNS VOID AS $$
DECLARE
  v_current_state cartridge_thermal_state;
  v_inference_count BIGINT;
BEGIN
  -- Get current state
  SELECT thermal_state, inference_count 
  INTO v_current_state, v_inference_count
  FROM cartridges 
  WHERE id = p_cartridge_id;
  
  -- Skip if no change
  IF v_current_state = p_new_state THEN
    RETURN;
  END IF;
  
  -- Update cartridge
  UPDATE cartridges 
  SET thermal_state = p_new_state,
      thermal_state_changed_at = NOW()
  WHERE id = p_cartridge_id;
  
  -- Log history
  INSERT INTO system_cartridge_thermal_history (
    cartridge_id, previous_state, new_state, 
    trigger_reason, inference_count_at_change
  ) VALUES (
    p_cartridge_id, v_current_state, p_new_state,
    p_trigger_reason, v_inference_count
  );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION is_system_cartridge_visible(
  p_cartridge_id UUID,
  p_tenant_id UUID
) RETURNS BOOLEAN AS $$
DECLARE
  v_is_visible BOOLEAN;
BEGIN
  -- Check if there's an explicit visibility entry
  SELECT is_visible INTO v_is_visible
  FROM tenant_cartridge_visibility
  WHERE cartridge_id = p_cartridge_id AND tenant_id = p_tenant_id;
  
  -- Default to visible if no explicit entry
  IF v_is_visible IS NULL THEN
    RETURN true;
  END IF;
  
  RETURN v_is_visible;
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to get visible system cartridges for a tenant
CREATE OR REPLACE FUNCTION get_visible_system_cartridges(
  p_tenant_id UUID
) RETURNS TABLE (
  cartridge_id UUID,
  name VARCHAR,
  category cartridge_category,
  domain_id VARCHAR,
  thermal_state cartridge_thermal_state
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.id,
    c.name,
    c.category,
    c.domain_id,
    c.thermal_state
  FROM cartridges c
  WHERE c.scope = 'system'
    AND c.status = 'active'
    AND c.archived_at IS NULL
    AND is_system_cartridge_visible(c.id, p_tenant_id);
END;
$$ LANGUAGE plpgsql STABLE;

-- Function to auto-cool idle cartridges (called by scheduler)
CREATE OR REPLACE FUNCTION auto_cool_idle_system_cartridges(
  p_idle_minutes INTEGER DEFAULT 30
) RETURNS INTEGER AS $$
DECLARE
  v_count INTEGER := 0;
BEGIN
  -- Move hot → warm if idle for p_idle_minutes
  UPDATE cartridges
  SET thermal_state = 'warm',
      thermal_state_changed_at = NOW()
  WHERE scope = 'system'
    AND thermal_state = 'hot'
    AND last_inference_at < NOW() - (p_idle_minutes || ' minutes')::interval;
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  
  -- Move warm → cold if idle for 2x idle time
  UPDATE cartridges
  SET thermal_state = 'cold',
      thermal_state_changed_at = NOW()
  WHERE scope = 'system'
    AND thermal_state = 'warm'
    AND last_inference_at < NOW() - ((p_idle_minutes * 2) || ' minutes')::interval;
  
  GET DIAGNOSTICS v_count = v_count + ROW_COUNT;
  
  RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION log_pki_operation(
  p_action pki_audit_action,
  p_target_type VARCHAR(32),
  p_target_id UUID,
  p_tenant_id UUID,
  p_performed_by UUID,
  p_performed_by_email VARCHAR(256),
  p_success BOOLEAN,
  p_error_message TEXT DEFAULT NULL,
  p_details JSONB DEFAULT NULL,
  p_ip_address INET DEFAULT NULL,
  p_user_agent TEXT DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
  v_id UUID;
BEGIN
  INSERT INTO pki_audit_log (
    action, target_type, target_id, tenant_id,
    performed_by, performed_by_email, success,
    error_message, details, ip_address, user_agent
  ) VALUES (
    p_action, p_target_type, p_target_id, p_tenant_id,
    p_performed_by, p_performed_by_email, p_success,
    p_error_message, p_details, p_ip_address, p_user_agent
  ) RETURNING id INTO v_id;
  
  RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION increment_signing_key_usage(
  p_key_id UUID
) RETURNS VOID AS $$
BEGIN
  UPDATE cartridge_signing_keys
  SET 
    usage_count = usage_count + 1,
    last_used_at = NOW(),
    updated_at = NOW()
  WHERE id = p_key_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_active_signing_key(
  p_tenant_id UUID,
  p_purpose signature_type
) RETURNS cartridge_signing_keys AS $$
DECLARE
  v_key cartridge_signing_keys;
BEGIN
  SELECT * INTO v_key
  FROM cartridge_signing_keys
  WHERE tenant_id = p_tenant_id
    AND purpose = p_purpose
    AND status = 'active'
    AND valid_from <= NOW()
    AND valid_until > NOW()
  ORDER BY created_at DESC
  LIMIT 1;
  
  RETURN v_key;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION is_cartridge_signature_valid(
  p_cartridge_id UUID
) RETURNS BOOLEAN AS $$
DECLARE
  v_cache signature_verification_cache;
BEGIN
  SELECT * INTO v_cache
  FROM signature_verification_cache
  WHERE cartridge_id = p_cartridge_id
    AND expires_at > NOW()
    AND is_valid = true
  LIMIT 1;
  
  RETURN v_cache.id IS NOT NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION cleanup_expired_verification_cache()
RETURNS INTEGER AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM signature_verification_cache
  WHERE expires_at < NOW();
  
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_vault_secrets_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_vault_requirements(p_cartridge_id UUID, p_tenant_id UUID)
RETURNS TABLE (
  secret_key VARCHAR,
  is_required BOOLEAN,
  is_satisfied BOOLEAN,
  expires_soon BOOLEAN
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.secret_key,
    r.is_required,
    CASE WHEN s.id IS NOT NULL AND s.is_active THEN true ELSE false END as is_satisfied,
    CASE WHEN s.expires_at IS NOT NULL AND s.expires_at < NOW() + INTERVAL '30 days' THEN true ELSE false END as expires_soon
  FROM cartridge_vault_requirements r
  LEFT JOIN vault_secrets s ON s.tenant_id = r.tenant_id AND s.key = r.secret_key AND s.is_active = true
  WHERE r.cartridge_id = p_cartridge_id AND r.tenant_id = p_tenant_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ----------------------------------------------------------------------------
-- Comments
-- ----------------------------------------------------------------------------

COMMENT ON TABLE vault_secrets IS 'Genesis Vault - encrypted secrets storage for Keyhole Pattern';
COMMENT ON TABLE vault_access_log IS 'Audit log for all vault secret access';
COMMENT ON TABLE cartridge_vault_requirements IS 'Secrets required by each cartridge (vault.req)';
COMMENT ON TABLE vault_secret_history IS 'History of secret rotations for audit and rollback';


-- Source: V2026_02_01_011__cartridge_rnir.sql
-- ============================================================================
-- RNIR (Radiant Neural Intermediate Representation) Schema
-- Model-agnostic cognitive source code for cartridges
-- 
-- Version: 1.0.0
-- Date: 2026-02-01
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Enums
-- ----------------------------------------------------------------------------

CREATE TYPE rnir_compilation_target AS ENUM (
  'lora',
  'system_prompt',
  'few_shot',
  'rag_chunks',
  'all'
);

CREATE TYPE rnir_model_family AS ENUM (
  'llama',
  'qwen',
  'mistral',
  'claude',
  'gpt',
  'gemini',
  'universal'
);

CREATE TYPE rnir_compilation_status AS ENUM (
  'pending',
  'queued',
  'compiling',
  'completed',
  'failed',
  'cancelled'
);

CREATE TYPE rnir_example_source AS ENUM (
  'curator',
  'manual',
  'synthetic',
  'imported'
);

-- ----------------------------------------------------------------------------
-- RNIR Documents Table
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rnir_documents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cartridge_id UUID NOT NULL,
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  
  -- Document metadata
  version VARCHAR(20) NOT NULL DEFAULT '1.0',
  domain VARCHAR(100) NOT NULL,
  
  -- Statistics
  example_count INTEGER NOT NULL DEFAULT 0,
  total_tokens INTEGER NOT NULL DEFAULT 0,
  avg_quality DECIMAL(3,2),
  
  -- Storage
  s3_path TEXT,
  size_bytes BIGINT,
  checksum VARCHAR(64),
  
  -- Generation info
  generated_by VARCHAR(100),
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  modified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  CONSTRAINT rnir_doc_cartridge_domain_unique UNIQUE (cartridge_id, domain)
);

-- Enable RLS
ALTER TABLE rnir_documents ENABLE ROW LEVEL SECURITY;

CREATE POLICY rnir_documents_tenant_isolation ON rnir_documents
  USING (tenant_id = current_setting('app.current_tenant_id', true)::UUID);

-- Indexes
CREATE INDEX idx_rnir_documents_cartridge ON rnir_documents(cartridge_id);
CREATE INDEX idx_rnir_documents_tenant ON rnir_documents(tenant_id);
CREATE INDEX idx_rnir_documents_domain ON rnir_documents(tenant_id, domain);

-- ----------------------------------------------------------------------------
-- RNIR Examples Table (for searchable examples)
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rnir_examples (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id UUID NOT NULL REFERENCES rnir_documents(id) ON DELETE CASCADE,
  tenant_id UUID NOT NULL,
  
  -- Example content
  user_input TEXT NOT NULL,
  assistant_response TEXT NOT NULL,
  system_context TEXT,
  
  -- Metadata
  domain VARCHAR(100),
  tags JSONB DEFAULT '[]'::jsonb,
  quality DECIMAL(3,2),
  source rnir_example_source NOT NULL DEFAULT 'curator',
  
  -- Token counts
  user_tokens INTEGER,
  assistant_tokens INTEGER,
  
  -- Embedding for semantic search
  embedding vector(1536),
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE rnir_examples ENABLE ROW LEVEL SECURITY;

CREATE POLICY rnir_examples_tenant_isolation ON rnir_examples
  USING (tenant_id = current_setting('app.current_tenant_id', true)::UUID);

-- Indexes
CREATE INDEX idx_rnir_examples_document ON rnir_examples(document_id);
CREATE INDEX idx_rnir_examples_tenant ON rnir_examples(tenant_id);
CREATE INDEX idx_rnir_examples_domain ON rnir_examples(tenant_id, domain);
CREATE INDEX idx_rnir_examples_quality ON rnir_examples(quality DESC) WHERE quality IS NOT NULL;
CREATE INDEX idx_rnir_examples_embedding ON rnir_examples USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- ----------------------------------------------------------------------------
-- RNIR Compilation Jobs
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rnir_compilation_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  cartridge_id UUID NOT NULL,
  
  -- Compilation settings
  target rnir_compilation_target NOT NULL,
  model_family rnir_model_family NOT NULL,
  model_id VARCHAR(100),
  
  -- LoRA settings (if target is lora)
  lora_settings JSONB,
  
  -- System prompt settings (if target is system_prompt)
  prompt_settings JSONB,
  
  -- Status
  status rnir_compilation_status NOT NULL DEFAULT 'pending',
  progress INTEGER NOT NULL DEFAULT 0,
  current_step TEXT,
  
  -- Priority
  priority INTEGER NOT NULL DEFAULT 5,
  
  -- Timing
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  -- Error info
  error TEXT,
  error_details JSONB,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE rnir_compilation_jobs ENABLE ROW LEVEL SECURITY;

CREATE POLICY rnir_compilation_jobs_tenant_isolation ON rnir_compilation_jobs
  USING (tenant_id = current_setting('app.current_tenant_id', true)::UUID);

-- Indexes
CREATE INDEX idx_rnir_compilation_jobs_tenant ON rnir_compilation_jobs(tenant_id);
CREATE INDEX idx_rnir_compilation_jobs_cartridge ON rnir_compilation_jobs(cartridge_id);
CREATE INDEX idx_rnir_compilation_jobs_status ON rnir_compilation_jobs(status, priority DESC) WHERE status IN ('pending', 'queued');
CREATE INDEX idx_rnir_compilation_jobs_active ON rnir_compilation_jobs(tenant_id, status) WHERE status IN ('pending', 'queued', 'compiling');

-- ----------------------------------------------------------------------------
-- RNIR Compiled Artifacts
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rnir_compiled_artifacts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id UUID NOT NULL REFERENCES rnir_compilation_jobs(id) ON DELETE CASCADE,
  cartridge_id UUID NOT NULL,
  tenant_id UUID NOT NULL,
  
  -- Artifact info
  target rnir_compilation_target NOT NULL,
  model_family rnir_model_family NOT NULL,
  model_id VARCHAR(100),
  
  -- Storage
  artifact_path TEXT NOT NULL,
  size_bytes BIGINT NOT NULL,
  checksum VARCHAR(64) NOT NULL,
  
  -- Status
  status rnir_compilation_status NOT NULL DEFAULT 'completed',
  
  -- Metrics
  training_loss DECIMAL(10,6),
  validation_loss DECIMAL(10,6),
  examples_processed INTEGER,
  compilation_time_seconds INTEGER,
  
  -- Timing
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  
  -- Error
  error_message TEXT,
  
  -- Timestamps
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

