-- Function to update model weights after interrogation
CREATE OR REPLACE FUNCTION update_livs_model_weights()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO livs_model_weights (tenant_id, model_id, total_interrogations, lies_detected, lie_rate, sample_size, last_updated)
    VALUES (
        NEW.tenant_id,
        NEW.original_model_id,
        1,
        CASE WHEN NEW.lie_detected THEN 1 ELSE 0 END,
        CASE WHEN NEW.lie_detected THEN 1.0 ELSE 0.0 END,
        1,
        NOW()
    )
    ON CONFLICT (tenant_id, model_id) DO UPDATE SET
        total_interrogations = livs_model_weights.total_interrogations + 1,
        lies_detected = livs_model_weights.lies_detected + CASE WHEN NEW.lie_detected THEN 1 ELSE 0 END,
        lie_rate = (livs_model_weights.lies_detected + CASE WHEN NEW.lie_detected THEN 1 ELSE 0 END)::decimal / 
                   (livs_model_weights.total_interrogations + 1),
        sample_size = livs_model_weights.sample_size + 1,
        last_updated = NOW();
    
    -- Update domain-specific rates if domain provided
    IF NEW.domain IS NOT NULL THEN
        UPDATE livs_model_weights
        SET domain_lie_rates = jsonb_set(
            COALESCE(domain_lie_rates, '{}'::jsonb),
            ARRAY[NEW.domain],
            to_jsonb(
                COALESCE((domain_lie_rates->>NEW.domain)::decimal, 0) * 0.9 + 
                CASE WHEN NEW.lie_detected THEN 0.1 ELSE 0.0 END
            )
        )
        WHERE tenant_id = NEW.tenant_id AND model_id = NEW.original_model_id;
    END IF;
    
    -- Update question type rates if provided
    IF NEW.query_type IS NOT NULL THEN
        UPDATE livs_model_weights
        SET question_type_lie_rates = jsonb_set(
            COALESCE(question_type_lie_rates, '{}'::jsonb),
            ARRAY[NEW.query_type],
            to_jsonb(
                COALESCE((question_type_lie_rates->>NEW.query_type)::decimal, 0) * 0.9 + 
                CASE WHEN NEW.lie_detected THEN 0.1 ELSE 0.0 END
            )
        )
        WHERE tenant_id = NEW.tenant_id AND model_id = NEW.original_model_id;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION aggregate_livs_global_weights()
RETURNS void AS $$
BEGIN
    INSERT INTO livs_global_model_weights (model_id, total_interrogations, lies_detected, lie_rate, contributing_tenants, last_updated)
    SELECT 
        model_id,
        SUM(total_interrogations),
        SUM(lies_detected),
        CASE WHEN SUM(total_interrogations) > 0 
             THEN SUM(lies_detected)::decimal / SUM(total_interrogations)
             ELSE 0 END,
        COUNT(DISTINCT tenant_id),
        NOW()
    FROM livs_model_weights
    GROUP BY model_id
    ON CONFLICT (model_id) DO UPDATE SET
        total_interrogations = EXCLUDED.total_interrogations,
        lies_detected = EXCLUDED.lies_detected,
        lie_rate = EXCLUDED.lie_rate,
        contributing_tenants = EXCLUDED.contributing_tenants,
        last_updated = EXCLUDED.last_updated;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_crucible_session_questions()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE crucible_sessions
    SET 
        total_questions_asked = total_questions_asked + 1,
        questions_remaining = questions_remaining - 1,
        updated_at = NOW()
    WHERE id = NEW.session_id;
    
    -- Update participant questions asked
    UPDATE crucible_participants
    SET 
        questions_asked = questions_asked + 1,
        updated_at = NOW()
    WHERE session_id = NEW.session_id AND participant_id = NEW.asker_id;
    
    -- Update participant questions received
    UPDATE crucible_participants
    SET 
        questions_received = questions_received + 1,
        updated_at = NOW()
    WHERE session_id = NEW.session_id AND participant_id = NEW.target_id;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_circular_citation()
RETURNS TRIGGER AS $$
DECLARE
    asker_participant_id VARCHAR(64);
    is_circular BOOLEAN := FALSE;
BEGIN
    -- Get the asker's participant ID for this answer's question
    SELECT q.asker_id INTO asker_participant_id
    FROM crucible_questions q
    WHERE q.id = NEW.question_id;
    
    -- Check if citing someone who previously cited the asker
    IF NEW.source_type = 'other_participant' AND NEW.source_participant_id IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 
            FROM crucible_citations c
            JOIN crucible_answers a ON c.answer_id = a.id
            JOIN crucible_questions q ON a.question_id = q.id
            WHERE c.source_participant_id = asker_participant_id
            AND q.asker_id = NEW.source_participant_id
            AND q.session_id = (
                SELECT session_id FROM crucible_questions WHERE id = NEW.question_id
            )
        ) INTO is_circular;
        
        IF is_circular THEN
            NEW.is_circular := TRUE;
            
            -- Update participant circular citation count
            UPDATE crucible_participants
            SET 
                circular_citations = circular_citations + 1,
                updated_at = NOW()
            WHERE session_id = (SELECT session_id FROM crucible_questions WHERE id = NEW.question_id)
            AND participant_id = (SELECT target_id FROM crucible_questions WHERE id = NEW.question_id);
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION update_crucible_model_performance()
RETURNS TRIGGER AS $$
DECLARE
    winner_id VARCHAR(64);
    winner_model_id VARCHAR(255);
    participant RECORD;
BEGIN
    IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
        -- Find the winner (highest score)
        SELECT fr.participant_id, p.model_id INTO winner_id, winner_model_id
        FROM crucible_final_reports fr
        JOIN crucible_participants p ON fr.session_id = p.session_id AND fr.participant_id = p.participant_id
        WHERE fr.session_id = NEW.id
        ORDER BY fr.final_score DESC NULLS LAST
        LIMIT 1;
        
        -- Update performance for each LLM participant
        FOR participant IN
            SELECT p.*, fr.final_score
            FROM crucible_participants p
            LEFT JOIN crucible_final_reports fr ON p.session_id = fr.session_id AND p.participant_id = fr.participant_id
            WHERE p.session_id = NEW.id AND p.can_deliberate = TRUE
        LOOP
            INSERT INTO crucible_model_performance (
                tenant_id, model_id, model_name, sessions_participated, wins,
                total_score, total_questions_asked, high_quality_questions,
                circular_citations, last_session_at
            ) VALUES (
                NEW.tenant_id, participant.model_id, participant.model_name, 1,
                CASE WHEN participant.participant_id = winner_id THEN 1 ELSE 0 END,
                COALESCE(participant.final_score, 0),
                participant.questions_asked,
                (SELECT COUNT(*) FROM crucible_questions WHERE session_id = NEW.id AND asker_id = participant.participant_id AND quality_score IN ('high', 'exceptional')),
                participant.circular_citations,
                NOW()
            )
            ON CONFLICT (tenant_id, model_id) DO UPDATE SET
                sessions_participated = crucible_model_performance.sessions_participated + 1,
                wins = crucible_model_performance.wins + EXCLUDED.wins,
                total_score = crucible_model_performance.total_score + EXCLUDED.total_score,
                total_questions_asked = crucible_model_performance.total_questions_asked + EXCLUDED.total_questions_asked,
                high_quality_questions = crucible_model_performance.high_quality_questions + EXCLUDED.high_quality_questions,
                circular_citations = crucible_model_performance.circular_citations + EXCLUDED.circular_citations,
                last_session_at = NOW(),
                updated_at = NOW();
        END LOOP;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_crucible_resolved_config(
    p_tenant_id UUID,
    p_user_id UUID DEFAULT NULL,
    p_method_id VARCHAR DEFAULT NULL,
    p_workflow_id UUID DEFAULT NULL
) RETURNS JSONB AS $$
DECLARE
    v_system RECORD;
    v_tenant RECORD;
    v_user_global RECORD;
    v_user_method RECORD;
    v_user_workflow RECORD;
    v_user_method_workflow RECORD;
    v_result JSONB;
BEGIN
    -- Get system config
    SELECT * INTO v_system FROM crucible_system_config LIMIT 1;
    
    -- Get tenant config
    SELECT * INTO v_tenant FROM crucible_tenant_config WHERE tenant_id = p_tenant_id;
    
    -- Start with system defaults
    v_result := jsonb_build_object(
        'max_questions', v_system.default_max_questions,
        'question_timeout_seconds', v_system.question_timeout_seconds,
        'session_timeout_seconds', v_system.session_timeout_seconds,
        'min_llms_for_crucible', v_system.min_llms_for_crucible,
        'cost_mode', v_system.default_cost_mode,
        'cost_mode_question_limits', v_system.cost_mode_question_limits,
        'circular_citation_penalty', v_system.circular_citation_penalty,
        'source', 'system'
    );
    
    -- Apply tenant overrides
    IF v_tenant IS NOT NULL THEN
        IF v_tenant.max_questions_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('max_questions', v_tenant.max_questions_override, 'source', 'tenant');
        END IF;
        IF v_tenant.question_timeout_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('question_timeout_seconds', v_tenant.question_timeout_override);
        END IF;
        IF v_tenant.session_timeout_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('session_timeout_seconds', v_tenant.session_timeout_override);
        END IF;
        IF v_tenant.min_llms_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('min_llms_for_crucible', v_tenant.min_llms_override);
        END IF;
        IF v_tenant.cost_mode_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('cost_mode', v_tenant.cost_mode_override);
        END IF;
        IF v_tenant.cost_mode_limits_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('cost_mode_question_limits', v_tenant.cost_mode_limits_override);
        END IF;
        IF v_tenant.circular_penalty_override IS NOT NULL THEN
            v_result := v_result || jsonb_build_object('circular_citation_penalty', v_tenant.circular_penalty_override);
        END IF;
        
        v_result := v_result || jsonb_build_object(
            'show_deliberation_to_users', v_tenant.show_deliberation_to_users,
            'auto_enable_for_multi_llm', v_tenant.auto_enable_for_multi_llm
        );
    END IF;
    
    -- Apply user preferences if allowed and provided
    IF p_user_id IS NOT NULL AND (v_tenant IS NULL OR v_tenant.allow_user_override) AND v_system.allow_user_override THEN
        -- Check method+workflow specific first (highest priority)
        IF p_method_id IS NOT NULL AND p_workflow_id IS NOT NULL THEN
            SELECT * INTO v_user_method_workflow 
            FROM crucible_user_preferences 
            WHERE tenant_id = p_tenant_id 
              AND user_id = p_user_id 
              AND scope = 'method_in_workflow'
              AND method_id = p_method_id
              AND workflow_id = p_workflow_id;
            
            IF v_user_method_workflow IS NOT NULL AND v_user_method_workflow.explicitly_set THEN
                IF v_user_method_workflow.max_questions IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('max_questions', v_user_method_workflow.max_questions, 'source', 'user_method_workflow');
                END IF;
                IF v_user_method_workflow.cost_mode IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('cost_mode', v_user_method_workflow.cost_mode);
                END IF;
                IF v_user_method_workflow.enabled IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('enabled', v_user_method_workflow.enabled);
                END IF;
                RETURN v_result;
            END IF;
        END IF;
        
        -- Check workflow-specific
        IF p_workflow_id IS NOT NULL THEN
            SELECT * INTO v_user_workflow 
            FROM crucible_user_preferences 
            WHERE tenant_id = p_tenant_id 
              AND user_id = p_user_id 
              AND scope = 'workflow'
              AND workflow_id = p_workflow_id;
            
            IF v_user_workflow IS NOT NULL AND v_user_workflow.explicitly_set THEN
                IF v_user_workflow.max_questions IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('max_questions', v_user_workflow.max_questions, 'source', 'user_workflow');
                END IF;
                IF v_user_workflow.cost_mode IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('cost_mode', v_user_workflow.cost_mode);
                END IF;
                IF v_user_workflow.enabled IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('enabled', v_user_workflow.enabled);
                END IF;
                RETURN v_result;
            END IF;
        END IF;
        
        -- Check method-specific
        IF p_method_id IS NOT NULL THEN
            SELECT * INTO v_user_method 
            FROM crucible_user_preferences 
            WHERE tenant_id = p_tenant_id 
              AND user_id = p_user_id 
              AND scope = 'method'
              AND method_id = p_method_id;
            
            IF v_user_method IS NOT NULL AND v_user_method.explicitly_set THEN
                IF v_user_method.max_questions IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('max_questions', v_user_method.max_questions, 'source', 'user_method');
                END IF;
                IF v_user_method.cost_mode IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('cost_mode', v_user_method.cost_mode);
                END IF;
                IF v_user_method.enabled IS NOT NULL THEN
                    v_result := v_result || jsonb_build_object('enabled', v_user_method.enabled);
                END IF;
                RETURN v_result;
            END IF;
        END IF;
        
        -- Check user global
        SELECT * INTO v_user_global 
        FROM crucible_user_preferences 
        WHERE tenant_id = p_tenant_id 
          AND user_id = p_user_id 
          AND scope = 'global';
        
        IF v_user_global IS NOT NULL AND v_user_global.explicitly_set THEN
            IF v_user_global.max_questions IS NOT NULL THEN
                v_result := v_result || jsonb_build_object('max_questions', v_user_global.max_questions, 'source', 'user_global');
            END IF;
            IF v_user_global.cost_mode IS NOT NULL THEN
                v_result := v_result || jsonb_build_object('cost_mode', v_user_global.cost_mode);
            END IF;
            IF v_user_global.enabled IS NOT NULL THEN
                v_result := v_result || jsonb_build_object('enabled', v_user_global.enabled);
            END IF;
        END IF;
    END IF;
    
    RETURN v_result;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uep_streams_update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uep_get_stream_progress(p_stream_id UUID)
RETURNS TABLE (
  stream_id UUID,
  status uep_stream_status,
  chunks_received INTEGER,
  total_chunks INTEGER,
  bytes_transferred BIGINT,
  total_bytes BIGINT,
  percent_complete DECIMAL(5, 2),
  estimated_remaining_ms INTEGER,
  last_chunk_at TIMESTAMPTZ
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    s.stream_id,
    s.status,
    s.last_chunk_sequence AS chunks_received,
    s.total_chunks,
    s.last_chunk_offset AS bytes_transferred,
    s.total_size_bytes AS total_bytes,
    CASE 
      WHEN s.total_size_bytes > 0 THEN 
        ROUND((s.last_chunk_offset::DECIMAL / s.total_size_bytes) * 100, 2)
      WHEN s.total_chunks > 0 THEN 
        ROUND((s.last_chunk_sequence::DECIMAL / s.total_chunks) * 100, 2)
      ELSE 0
    END AS percent_complete,
    CASE 
      WHEN s.last_chunk_at IS NOT NULL AND s.last_chunk_sequence > 0 THEN
        ROUND(
          EXTRACT(EPOCH FROM (s.last_chunk_at - s.started_at)) * 1000 / s.last_chunk_sequence * 
          (COALESCE(s.total_chunks, 0) - s.last_chunk_sequence)
        )::INTEGER
      ELSE NULL
    END AS estimated_remaining_ms,
    s.last_chunk_at
  FROM uep_streams s
  WHERE s.stream_id = p_stream_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uep_generate_resume_token(p_stream_id UUID)
RETURNS TEXT AS $$
DECLARE
  v_token TEXT;
BEGIN
  v_token := encode(
    digest(
      p_stream_id::TEXT || NOW()::TEXT || random()::TEXT,
      'sha256'
    ),
    'base64'
  );
  
  UPDATE uep_streams
  SET resume_token = v_token,
      resume_expiry = NOW() + INTERVAL '24 hours'
  WHERE stream_id = p_stream_id;
  
  RETURN v_token;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uep_validate_resume_token(p_stream_id UUID, p_token TEXT)
RETURNS BOOLEAN AS $$
DECLARE
  v_valid BOOLEAN;
BEGIN
  SELECT (resume_token = p_token AND resume_expiry > NOW())
  INTO v_valid
  FROM uep_streams
  WHERE stream_id = p_stream_id;
  
  RETURN COALESCE(v_valid, FALSE);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION uep_record_metric(
  p_tenant_id UUID,
  p_source_type uep_source_type,
  p_envelope_type uep_envelope_type,
  p_content_type VARCHAR(255),
  p_bytes BIGINT DEFAULT 0,
  p_latency_ms INTEGER DEFAULT NULL,
  p_cost_cents DECIMAL(12, 4) DEFAULT 0,
  p_is_error BOOLEAN DEFAULT FALSE
)
RETURNS VOID AS $$
DECLARE
  v_bucket_time TIMESTAMPTZ;
BEGIN
  -- Round to nearest minute
  v_bucket_time := date_trunc('minute', NOW());
  
  INSERT INTO uep_metrics (
    tenant_id, bucket_time, source_type, envelope_type, content_type,
    envelope_count, total_bytes_transferred, total_cost_cents, error_count
  )
  VALUES (
    p_tenant_id, v_bucket_time, p_source_type, p_envelope_type, p_content_type,
    1, p_bytes, p_cost_cents, CASE WHEN p_is_error THEN 1 ELSE 0 END
  )
  ON CONFLICT (tenant_id, bucket_time, source_type, envelope_type, content_type)
  DO UPDATE SET
    envelope_count = uep_metrics.envelope_count + 1,
    total_bytes_transferred = uep_metrics.total_bytes_transferred + EXCLUDED.total_bytes_transferred,
    total_cost_cents = uep_metrics.total_cost_cents + EXCLUDED.total_cost_cents,
    error_count = uep_metrics.error_count + EXCLUDED.error_count;
END;
$$ LANGUAGE plpgsql;


