    FOR SELECT
    USING (
        -- Own templates
        (tenant_id = current_setting('app.current_tenant_id', true)::uuid 
         AND user_id = current_setting('app.current_user_id', true)::uuid)
        -- Shared within tenant
        OR (tenant_id = current_setting('app.current_tenant_id', true)::uuid 
